private static bool IsAnonymousClient(string? clientId)
    => string.IsNullOrWhiteSpace(clientId) || clientId == EmptyObjectId;

// ── P3-S03 ── Top Class Times ────────────────────────────────────────────

/// <inheritdoc />
public async Task<List<TopClassTimeDto>> GetTopClassTimesAsync(AnalyticsRangeQuery range, string? format = null)
{
    // 1. Pull sessions that started in window and weren't cancelled or blocked.
    // These define the universe of "classes held" — the denominator for
    // OccupancyPct and the bucket source for hour-of-day.
    var sessionFilters = new List<FilterDefinition<CalendarSession>>
    {
        Builders<CalendarSession>.Filter.Gte(s => s.StartTime, range.StartDate),
        Builders<CalendarSession>.Filter.Lt(s => s.StartTime, range.EndDate),
        Builders<CalendarSession>.Filter.In(s => s.Status, new[] { "SCHEDULED", "COMPLETED" }),
    };
    if (!string.IsNullOrWhiteSpace(format))
    {
        // Allow caller to filter to GROUP / MAT / PRIVATE / DUO. Unknown values
        // pass through to Mongo and just yield no rows — acceptable since
        // the controller layer is the gatekeeper.
        sessionFilters.Add(Builders<CalendarSession>.Filter.Eq(s => s.Format, format));
    }

    var sessions = await _sessions
        .Find(Builders<CalendarSession>.Filter.And(sessionFilters))
        .ToListAsync();
    if (sessions.Count == 0) return new List<TopClassTimeDto>();

    var sessionIds = sessions.Select(s => s.Id).ToList();

    // 2. Pull attendances that link to those sessions and counted as a
    // booking (BOOKED) or a check-in (CHECKED_IN). Cancellations and
    // no-shows are excluded from BookingCount per the spec.
    var attendances = await _attendances
        .Find(Builders<Attendance>.Filter.And(
            Builders<Attendance>.Filter.In(a => a.CalendarSessionId, sessionIds),
            Builders<Attendance>.Filter.In(a => a.Status, new[] { "BOOKED", "CHECKED_IN" })))
        .ToListAsync();

    // 3. Build the bucket map. Key = (HourOfDay UTC, Format).
    // We carry the session's Format on the bucket key so a 9am hour with
    // both GROUP and PRIVATE sessions surfaces as two rows, which is what
    // the bar chart wants. When `format` was already filtered server-side,
    // every bucket has the same Format anyway.
    var sessionLookup = sessions.ToDictionary(s => s.Id!, s => s);  // _id always populated on read.
    var buckets = new Dictionary<(int hour, string fmt), BucketAccumulator>();

    foreach (var session in sessions)
    {
        var key = (session.StartTime.Hour, session.Format);
        if (!buckets.TryGetValue(key, out var acc))
        {
            acc = new BucketAccumulator();
            buckets[key] = acc;
        }
        acc.SessionsHeld += 1;
        acc.CapacitySum += session.Capacity;
    }

    foreach (var attendance in attendances)
    {
        // Defensive: the attendance's session may have been filtered out
        // by the format filter — skip it if so rather than orphan-counting.
        if (attendance.CalendarSessionId is null) continue;
        if (!sessionLookup.TryGetValue(attendance.CalendarSessionId, out var session)) continue;

        var key = (session.StartTime.Hour, session.Format);
        if (!buckets.TryGetValue(key, out var acc)) continue;

        acc.BookingCount += 1;
        if (attendance.Status == "CHECKED_IN") acc.AttendedCount += 1;
    }

    // 4. Materialise to DTOs sorted by BookingCount desc, then hour asc
    // (so two equally-popular hours render in chronological order).
    return buckets
        .Select(kvp => new TopClassTimeDto
        {
            HourOfDay = kvp.Key.hour,
            Format = kvp.Key.fmt,
            BookingCount = kvp.Value.BookingCount,
            AttendedCount = kvp.Value.AttendedCount,
            SessionsHeld = kvp.Value.SessionsHeld,
            OccupancyPct = ComputeOccupancyPct(kvp.Value),
        })
        .OrderByDescending(b => b.BookingCount)
        .ThenBy(b => b.HourOfDay)
        .ToList();
}

/// <summary>
/// Per-bucket running totals. Internal helper class — not exposed.
/// </summary>
private sealed class BucketAccumulator
{
    public int BookingCount;
    public int AttendedCount;
    public int SessionsHeld;
    public int CapacitySum;
}

/// <summary>
/// AttendedCount / (SessionsHeld * AvgCapacity) * 100, rounded to 1dp.
/// Returns 0 when no sessions held (empty bucket can't yield a percentage).
/// We use AvgCapacity rather than max-or-first so a bucket where one slot
/// was a 12-cap reformer and another was a 10-cap mat doesn't get
/// arithmetically punished.
/// </summary>
private static decimal ComputeOccupancyPct(BucketAccumulator acc)
{
    if (acc.SessionsHeld == 0 || acc.CapacitySum == 0) return 0m;

    // CapacitySum is the sum across SessionsHeld sessions, so dividing
    // AttendedCount by CapacitySum yields the same answer as dividing by
    // (SessionsHeld * AvgCapacity) — with one fewer rounding step.
    var pct = (decimal)acc.AttendedCount / acc.CapacitySum * 100m;
    return Math.Round(pct, 1, MidpointRounding.AwayFromZero);
}

