// SPM-75 — KPI descriptor table. Drives both the value rendering and the
// optional month-over-month comparison. Each descriptor maps a DOM id to:
//   field   — the month-summary DTO field carrying the raw numeric value
//   value() — how to render the value for display
//   raw()   — the comparable numeric magnitude used for delta math
//   delta() — how to render the ABSOLUTE change between the two months
// `raw`/`delta` are split out because occupancy is stored as a 0..1
// fraction but shown as a whole percentage, so its delta reads as points.
const fmtInt = (n) => (n == null ? "—" : Number(n).toLocaleString("en-US"));
const MONTH_KPIS = [
  {
    id: "totalRevenue",
    field: "totalRevenueVnd",
    value: fmtVnd,
    raw: (n) => Number(n) || 0,
    delta: (n) => `${n >= 0 ? "+" : "−"}${fmtVnd(Math.abs(n))}`,
  },
  {
    id: "singleClassRevenue",
    field: "singleClassRevenueVnd",
    value: fmtVnd,
    raw: (n) => Number(n) || 0,
    delta: (n) => `${n >= 0 ? "+" : "−"}${fmtVnd(Math.abs(n))}`,
  },
  {
    id: "packageRevenue",
    field: "packageRevenueVnd",
    value: fmtVnd,
    raw: (n) => Number(n) || 0,
    delta: (n) => `${n >= 0 ? "+" : "−"}${fmtVnd(Math.abs(n))}`,
  },
  {
    id: "merchRevenue",
    field: "merchandiseRevenueVnd",
    value: fmtVnd,
    raw: (n) => Number(n) || 0,
    delta: (n) => `${n >= 0 ? "+" : "−"}${fmtVnd(Math.abs(n))}`,
  },
  {
    id: "packagesSold",
    field: "packagesSold",
    value: fmtInt,
    raw: (n) => Number(n) || 0,
    delta: (n) => `${n >= 0 ? "+" : "−"}${fmtInt(Math.abs(n))}`,
  },
  {
    id: "newClients",
    field: "newClients",
    value: fmtInt,
    raw: (n) => Number(n) || 0,
    delta: (n) => `${n >= 0 ? "+" : "−"}${fmtInt(Math.abs(n))}`,
  },
  {
    id: "dailyAvgRev",
    field: "dailyAverageRevenueVnd",
    value: fmtVnd,
    raw: (n) => Number(n) || 0,
    delta: (n) => `${n >= 0 ? "+" : "−"}${fmtVnd(Math.abs(n))}`,
  },
  {
    id: "dailyAvgClasses",
    field: "dailyAverageClasses",
    value: (n) => (Number(n) || 0).toFixed(1),
    raw: (n) => Number(n) || 0,
    delta: (n) => `${n >= 0 ? "+" : "−"}${Math.abs(n).toFixed(1)}`,
  },
  {
    id: "avgOccupancy",
    field: "avgGroupClassOccupancy",
    value: (n) => ((Number(n) || 0) * 100).toFixed(0) + "%",
    // Compare on whole-percentage points so the delta reads "+3 pts".
    raw: (n) => (Number(n) || 0) * 100,
    delta: (n) => `${n >= 0 ? "+" : "−"}${Math.abs(n).toFixed(0)} pts`,
  },
