value: (n) => Math.min(100, Math.round(Number(n) || 0)) + "%",
// Compare on whole-percentage points so the delta reads "+3 pts".
raw: (n) => Number(n) || 0,
delta: (n) => `${n >= 0 ? "+" : "−"}${Math.abs(n).toFixed(0)} pts`,

