// ── P6: Booking Source + Payment Method Distribution ───────────────
let bookingSourceChart = null;
let paymentMethodChart = null;

async function loadDistributions() {
  const { start, end } = rangeFromState();
  const sub = document.getElementById("distSubtitle");
  sub.textContent = periodLabel();
  const pal = readPalette();
  const colors = [
    pal.accent,
    "#4EA5D9",
    "#45B68D",
    "#E67E22",
    "#9B59B6",
    "#E74C3C",
  ];

  // Booking source
  try {
    const res = await fetch(
      `${API}/api/analytics/booking-source-distribution?startDate=${start}&endDate=${end}`,
      { headers: { Authorization: `Bearer ${token}` } },
    );
    if (res.ok) {
      const rows = await res.json();
      if (bookingSourceChart) bookingSourceChart.destroy();
      bookingSourceChart = new Chart(
        document.getElementById("bookingSourceChart").getContext("2d"),
        {
          type: "doughnut",
          data: {
            labels: rows.map((r) => r.source || r.label || "Unknown"),
            datasets: [
              {
                data: rows.map((r) => r.count),
                backgroundColor: colors.slice(0, rows.length),
                borderWidth: 0,
              },
            ],
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            cutout: "65%",
            plugins: {
              legend: {
                position: "bottom",
                labels: {
                  font: { family: "Inter", size: 11 },
                  boxWidth: 10,
                },
              },
            },
          },
        },
      );
    }
  } catch (e) {
    console.warn("[analytics] booking-source failed:", e);
  }

  // Payment method
  try {
    const res = await fetch(
      `${API}/api/analytics/payment-method-distribution?startDate=${start}&endDate=${end}`,
      { headers: { Authorization: `Bearer ${token}` } },
    );
    if (res.ok) {
      const rows = await res.json();
      if (paymentMethodChart) paymentMethodChart.destroy();
      paymentMethodChart = new Chart(
        document.getElementById("paymentMethodChart").getContext("2d"),
        {
          type: "doughnut",
          data: {
            labels: rows.map((r) => r.method || r.label || "Unknown"),
            datasets: [
              {
                data: rows.map((r) => r.count),
                backgroundColor: colors.slice(0, rows.length),
                borderWidth: 0,
              },
            ],
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            cutout: "65%",
            plugins: {
              legend: {
                position: "bottom",
                labels: {
                  font: { family: "Inter", size: 11 },
                  boxWidth: 10,
                },
              },
            },
          },
        },
      );
    }
  } catch (e) {
    console.warn("[analytics] payment-method failed:", e);
  }
}

