// which returns either { isValid: true, discountVnd, label, promotionId }
// or { isValid: false, reason } (always the same generic reason on failure
// to defeat code enumeration).
async function applyPromoCode() {
  const input = document.getElementById("promoCodeInput");
  const hintEl = document.getElementById("promoHint");
  const code = (input.value || "").trim().toUpperCase();
  if (!code) return;

  const subtotal = cart.reduce(
    (s, c) => s + (c.unitPrice ?? c.basePrice ?? 0) * c.qty,
    0,
  );
  const productTypes = Array.from(
    new Set(cart.map((c) => c.type).filter(Boolean)),
  );

  try {
    const r = await fetch(`${API}/api/promotions/preview`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        code,
        subtotalVnd: subtotal,
        productTypes,
        clientId: selectedClient?.id || null,
      }),
    });
    const data = await r.json();
    if (data.isValid) {
      appliedPromo = {
        promotionId: data.promotionId,
        code,
        discount: data.discountVnd || 0,
        label: data.label || "",
      };
      input.disabled = true;
      document.getElementById("applyPromoBtn").style.display = "none";
      document.getElementById("clearPromoBtn").style.display = "inline-flex";
      delete hintEl.dataset.kind;
    } else {
      appliedPromo = null;
      hintEl.style.display = "block";
      hintEl.style.color = "var(--color-danger)";
      hintEl.dataset.kind = "error";
      hintEl.textContent =
        data.reason || "This code can't be used on this cart.";
    }
  } catch {
    hintEl.style.display = "block";
    hintEl.style.color = "var(--color-danger)";
    hintEl.dataset.kind = "error";
    hintEl.textContent = "Network error — please try again.";
  }
  recalc();
}

function clearPromoCode() {
  appliedPromo = null;
  const input = document.getElementById("promoCodeInput");
  input.disabled = false;
  input.value = "";
  document.getElementById("applyPromoBtn").style.display = "inline-flex";
  document.getElementById("clearPromoBtn").style.display = "none";
  const hintEl = document.getElementById("promoHint");
  hintEl.style.display = "none";
  delete hintEl.dataset.kind;
