public async Task<PromoRedemption> RedeemAsync(
    string promotionId,
    string invoiceId,
    string clientId,
    decimal discountApplied,
    string codeSnapshot)
{
    if (string.IsNullOrEmpty(promotionId))
        throw new ArgumentException("promotionId required.", nameof(promotionId));
    if (string.IsNullOrEmpty(invoiceId))
        throw new ArgumentException("invoiceId required.", nameof(invoiceId));
    if (discountApplied < 0)
        throw new ArgumentException("discountApplied must be non-negative.", nameof(discountApplied));

    var promo = await _promotions.Find(p => p.Id == promotionId).FirstOrDefaultAsync()
        ?? throw new InvalidOperationException($"Promotion {promotionId} not found.");

    if (!promo.IsActive)
        throw new InvalidOperationException("This promotion is no longer active.");

    // Atomic $inc, guarded by MaxRedemptions (when set).
    var incFilter = Builders<Promotion>.Filter.And(
        Builders<Promotion>.Filter.Eq(p => p.Id, promotionId),
        Builders<Promotion>.Filter.Eq(p => p.IsActive, true),
        promo.MaxRedemptions is null
            ? Builders<Promotion>.Filter.Empty
            : Builders<Promotion>.Filter.Where(p =>
                p.MaxRedemptions == null || p.RedeemedCount < p.MaxRedemptions.Value));

