// Lets the receptionist create a client without leaving POS. The form
// markup + validation live in the shared <ClientFormFields/> component;
// here we only handle modal open/close + post-save auto-selection.
function openQuickAddClient() {
  if (!window.clientForm) {
    // Should not happen — the component initialises on DOMContentLoaded.
    console.error("[pos] clientForm component not initialised");
    return;
  }
  window.clientForm.reset();
  // Carry whatever's in the search field over as a starting Name. Tiny
  // touch, big DX win — staff almost always type the name first.
  const search = document.getElementById("clientSearch");
  if (search && search.value.trim()) {
    window.clientForm.setName(search.value.trim());
  }
  const overlay = document.getElementById("quickAddClientModal");
  if (overlay) overlay.classList.add("open");
  // Focus the first field for keyboard users.
  setTimeout(() => document.getElementById("cName")?.focus(), 50);
}

