function matchesFilter(product) {
  if (!filterType) return true;
  if (filterType === "STUDIO_RENTAL") {
    return product.type === "FREELANCE_PACKAGE" || product.type === "FREELANCE_SINGLE";
  }
  return product.type === filterType;
}

function defaultProductIcon(type) {
  switch (type) {
    case "MERCHANDISE":
      return "shopping-bag";
    case "FREELANCE_PACKAGE":
    case "FREELANCE_SINGLE":
      return "home";
    case "PACKAGE":
    default:
      return "package";
  }
}

