function syncSaleModeUI(mode) {
  const isRental = mode === "STUDIO_RENTAL";
  document.getElementById("saleModeClientBtn").className = mode === "CLIENT" ? "btn btn-secondary btn-sm" : "btn btn-ghost btn-sm";
  document.getElementById("saleModeRentalBtn").className = isRental ? "btn btn-secondary btn-sm" : "btn btn-ghost btn-sm";
  document.getElementById("clientSearch").placeholder = isRental
    ? "Search freelance instructors..."
    : "Search by name, email, or phone…";
  document.getElementById("openQuickAddClientBtn").style.display = isRental ? "none" : "inline-flex";
  document.getElementById("voucherRow").style.display = isRental ? "none" : "";
  document.getElementById("promoRow").style.display = isRental ? "none" : "";
  document.getElementById("refereeRow").style.display = isRental ? "none" : "";
  if (isRental) {
    document.getElementById("voucherSelect").value = "";
    document.getElementById("refereeSelect").value = "";
    clearPromoCode();
  }
}

function setSaleMode(mode) {
  if (saleMode === mode) return;
  if (cart.length) {
    window.showToast && window.showToast("Finish or clear the current cart before switching sale type.", "warning");
    return;
  }
  saleMode = mode;
  clearClient();
  syncSaleModeUI(mode);
  filterPOS(mode === "STUDIO_RENTAL" ? "STUDIO_RENTAL" : "");
}

