/* ═══ Event Card ═══ */
.ev {
  position: absolute; top: 2px; bottom: 2px;
  left: 3px; right: 20px; /* 20px right gutter for quick-action click */
  border-radius: 6px; padding: 4px 7px;
  font-size: 11px; cursor: pointer;
  overflow: hidden; z-index: 1;
  border-left: 4px solid var(--ev-accent, var(--color-brand-accent));
  background: var(--ev-bg, rgba(200,164,93,0.15));
  color: var(--ev-text, #e0c070);
  transition: all 0.12s;
  display: flex; flex-direction: column;
}
.ev:hover {
  filter: brightness(1.1);
  transform: scale(1.01);
  z-index: 5;
  box-shadow: 0 4px 16px rgba(0,0,0,0.3);
}
.ev.selected {
  box-shadow: 0 0 0 2px var(--color-brand-accent), 0 4px 16px rgba(0,0,0,0.3);
  z-index: 6;
}
.ev .ev-time {
  font-size: 9px; opacity: 0.65; line-height: 1;
  margin-bottom: 1px; white-space: nowrap;
  overflow: hidden; text-overflow: ellipsis;
}
.ev .ev-name {
  font-size: 11px; font-weight: 700; line-height: 1.2;
  margin-bottom: 2px; overflow: hidden;
  text-overflow: ellipsis; white-space: nowrap;
}
.ev .ev-instructor {
  display: flex; align-items: center; gap: 4px;
  margin-bottom: 1px;
}
.ev .ev-inst-avatar {
  width: 14px; height: 14px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 7px; font-weight: 700; color: #fff;
  flex-shrink: 0; background: var(--ev-accent, var(--color-brand-accent));
}
.ev .ev-inst-name {
  font-size: 9.5px; font-weight: 600; opacity: 0.85;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.ev .ev-capacity {
  font-size: 9px; opacity: 0.7;
  display: flex; align-items: center; gap: 3px;
}
.ev .ev-clients {
  font-size: 8.5px; opacity: 0.8; line-height: 1.25;
  flex: 1; overflow: hidden;
}
.ev .ev-client-line {
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.ev .ev-more { opacity: 0.5; font-style: italic; }
.ev .ev-waitlist-badge {
  position: absolute; top: 3px; right: 4px;
  font-size: 8px; font-weight: 700;
  background: var(--color-danger); color: white;
  padding: 1px 4px; border-radius: 3px;
}
/* SPM-91 — Private (hidden from public booking page) indicator. */
.ev .ev-private-badge {
  position: absolute; top: 3px; left: 4px;
  font-size: 9px; line-height: 1;
  opacity: 0.85; pointer-events: none;
}

/* Origin indicators (border LINE STYLE = where the session came from) */
.ev.origin-override { border-left-style: dashed; }
.ev.origin-freelance { border-left-style: dotted; border-left-width: 5px; }

/* Status indicators (COLOR = session lifecycle outcome; border stays SOLID) */
.ev.status-completed {
  --ev-accent: #34A853;
  background: rgba(52,168,83,0.16);
  border-left-color: #34A853;
}
.ev.status-noshow {
  --ev-accent: #C0392B;
  background: rgba(192,57,43,0.16);
  border-left-color: #C0392B;
}

/* ═══ Blocked Slot ═══ */
.ev.blocked {
  background: repeating-linear-gradient(135deg,
    rgba(180,50,50,0.06), rgba(180,50,50,0.06) 4px,
    rgba(180,50,50,0.14) 4px, rgba(180,50,50,0.14) 8px
  ) !important;
  border-color: var(--color-danger) !important;
  color: var(--color-text-muted);
  cursor: default;
  display: flex; flex-direction: column;
  align-items: center; justify-content: center;
  text-align: center;
}
.ev.blocked .ev-block-icon { font-size: 20px; opacity: 0.6; margin-bottom: 2px; }
.ev.blocked .ev-block-label { font-size: 10px; font-weight: 700; }
.ev.blocked .ev-block-reason { font-size: 9px; opacity: 0.6; margin-top: 1px; }
.ev.blocked .ev-block-scope {
  font-size: 8px; font-weight: 600; padding: 1px 5px;
  border-radius: 3px; margin-top: 3px; display: inline-block;
}

