else if (s.origin === 'FREELANCE' || s.isFreelance) originCls = ' origin-freelance';

// Status-based colour (solid): distinguish completed vs no-show sessions.
let statusCls = '';
if (s.status === 'COMPLETED') statusCls = ' status-completed';
else if (s.status === 'NO_SHOW') statusCls = ' status-noshow';

ev.className = `ev${isSelected ? ' selected' : ''}${originCls}${statusCls}`;
// Let the status CSS class own --ev-bg/--ev-accent so the status colour wins;
// only the format colour applies for SCHEDULED (no status class) sessions.
if (!statusCls) {
  ev.style.setProperty('--ev-bg', color.bg);
  ev.style.setProperty('--ev-accent', color.accent);
}
ev.style.setProperty('--ev-text', color.text);

const timeStr = `${fmtTime(st)} – ${fmtTime(et)}`;
const waitlistCount = s.waitlistCount || 0;

ev.innerHTML = `
  <div class="ev-time">${esc(timeStr)}</div>
  <div class="ev-name">${esc(s.className || 'Class')}</div>
  <div class="ev-instructor">
    <span class="ev-inst-avatar" style="background:${color.accent};">${esc(initials)}</span>
    <span class="ev-inst-name">${esc(s.instructorName || '—')}</span>
  </div>
  <div class="ev-capacity">👥 ${s.currentBookings ?? 0} / ${s.capacity ?? '?'}</div>
  <div class="ev-clients" data-sid="${s.id}"></div>
  ${waitlistCount > 0 ? `<span class="ev-waitlist-badge">!${waitlistCount}</span>` : ''}
  ${s.isPublic === false ? `<span class="ev-private-badge" title="Hidden from the public booking page">🔒</span>` : ''}

