file.content:
.sp-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--sp-space-sm);
  font-size: 14px;
  font-weight: 600;
  font-family: 'Inter', sans-serif;
  padding: 12px 20px;
  border-radius: var(--sp-radius-md);
  border: 1px solid transparent;
  cursor: pointer;
  transition: all var(--sp-transition-fast);
  text-decoration: none;
  white-space: nowrap;
  -webkit-tap-highlight-color: transparent;
}

.sp-btn svg {
  width: 16px;
  height: 16px;
}

.sp-btn-primary {
  background: var(--sp-dark);
  color: var(--sp-white);
  border-color: var(--sp-dark);
}

.sp-btn-primary:hover {
  background: var(--sp-dark-hover);
  transform: translateY(-0.5px);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}

.sp-btn-primary:active {
  transform: translateY(0);
  box-shadow: none;
}

.sp-btn-primary:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

.sp-btn-brand {
  background: var(--sp-brand);
  color: var(--sp-white);
  border-color: var(--sp-brand);
}

.sp-btn-brand:hover {
  background: var(--sp-brand-dark);
  transform: translateY(-0.5px);
  box-shadow: 0 2px 8px rgba(201, 123, 75, 0.3);
}

.sp-btn-outline {
  background: var(--sp-white);
  color: var(--sp-text-primary);
  border-color: var(--sp-border);
}

.sp-btn-outline:hover {
  border-color: var(--sp-border-strong);
  background: var(--sp-surface-raised);
}

.sp-btn-outline-brand {

