/* Secondary action — pairs with .sp-btn-primary as a lower-emphasis button.
   Previously undefined, which left anchors using it rendering as a bare blue
   link (e.g. "Create Free Account" on the booking login gate). */
.sp-btn-secondary {
  background: var(--sp-white);
  color: var(--sp-text-primary);
  border-color: var(--sp-border-strong);
}

.sp-btn-secondary:hover {
  background: var(--sp-surface-raised);
  border-color: var(--sp-dark);
  color: var(--sp-dark);
  transform: translateY(-0.5px);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}

.sp-btn-secondary:active {
  transform: translateY(0);
  box-shadow: none;
}

.sp-btn-secondary:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

.sp-btn-brand {
  background: var(--sp-brand);

