(function initEmailTemplatesTab() {
  let templatesCache = []; // list returned by the API
  let currentId = null;    // id of the template open in the editor
  let currentTpl = null;   // full template object open in the editor (incl. defaults)

  async function loadTemplates() {
    const list = document.getElementById('emailTplList');
    list.innerHTML = '<div style="color:var(--color-text-muted);font-size:13px;">Loading…</div>';
    try {
      const res = await fetch(`${API}/api/settings/email-templates`, {
        headers: { Authorization: 'Bearer ' + token },
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      templatesCache = await res.json();
      renderTemplateList();
    } catch (e) {
      list.innerHTML = '<div style="color:var(--color-danger);font-size:13px;">Failed to load email templates.</div>';
    }
  }

  async function toggleTemplateEnabled(id, isEnabled) {
    try {
      const res = await fetch(`${API}/api/settings/email-templates/${encodeURIComponent(id)}/enabled`, {
        method: 'PATCH',
        headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' },
        body: JSON.stringify({ isEnabled }),
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const updated = await res.json();
      const idx = templatesCache.findIndex(t => t.id === id);
      if (idx !== -1) templatesCache[idx] = { ...templatesCache[idx], isEnabled: updated.isEnabled };
    } catch (e) {
      console.error('Failed to toggle template enabled:', e);
    }
  }

  function renderTemplateList() {
    const list = document.getElementById('emailTplList');
    if (!templatesCache.length) {
      list.innerHTML = '<div style="color:var(--color-text-muted);font-size:13px;">No templates found.</div>';
      return;
    }
    list.innerHTML = templatesCache.map((t) => {
      const customised = !!t.isCustomised;
      const isEnabled = t.isEnabled !== false;
      const badge = customised
        ? '<span style="margin-left:8px;font-size:10px;padding:2px 8px;background:var(--color-brand-subtle,#eef0ff);border:1px solid var(--color-border-subtle);border-radius:999px;color:var(--color-brand,#635bff);">Customised</span>'
        : '<span style="margin-left:8px;font-size:10px;padding:2px 8px;background:var(--color-surface);border:1px solid var(--color-border-subtle);border-radius:999px;color:var(--color-text-muted);">Using default</span>';
      const securityNote = (t.id === 'password-reset' || t.id === 'email-verification')
        ? '<span style="font-size:10px;color:var(--color-text-muted);">(security — always sent)</span>' : '';
      const toggleDisabled = (t.id === 'password-reset' || t.id === 'email-verification') ? 'disabled' : '';
      return `
        <div style="display:flex;align-items:center;gap:12px;padding:12px;border:1px solid var(--color-border-subtle);border-radius:var(--radius-sm);background:var(--color-surface-raised);${!isEnabled ? 'opacity:0.6;' : ''}">
          <label class="toggle-switch" title="${isEnabled ? 'Auto-send ON' : 'Auto-send OFF'}" style="flex-shrink:0;">
            <input type="checkbox" class="tpl-enabled-toggle" data-tpl-id="${escapeHtml(t.id)}" ${isEnabled ? 'checked' : ''} ${toggleDisabled} />
            <span class="toggle-switch-slider"></span>
          </label>
          <div style="flex:1;min-width:0;">
            <div style="font-size:13px;font-weight:600;">${escapeHtml(t.name || t.id)}${badge} ${securityNote}</div>
            <div style="font-size:11px;color:var(--color-text-muted);font-family:monospace;">${escapeHtml(t.id)}</div>
          </div>
          <button class="btn btn-secondary btn-sm" data-tpl-edit="${escapeHtml(t.id)}" type="button">Edit</button>
        </div>`;
    }).join('');

    list.querySelectorAll('[data-tpl-edit]').forEach((btn) => {
      btn.addEventListener('click', () => openEditor(btn.getAttribute('data-tpl-edit')));
    });
    list.querySelectorAll('.tpl-enabled-toggle').forEach((chk) => {
      chk.addEventListener('change', async (e) => {
        const id = chk.getAttribute('data-tpl-id');
        await toggleTemplateEnabled(id, e.target.checked);
        renderTemplateList(); // re-render to update opacity
      });
    });
  }

  function openEditor(id) {
    const t = templatesCache.find((x) => x.id === id);
    if (!t) return;
    currentId = id;
    currentTpl = t;
    document.getElementById('emailTplEditId').value = id;
    document.getElementById('emailTplEditorTitle').textContent = `Edit: ${t.name || t.id}`;
    document.getElementById('emailTplEditorSubtitle').textContent =
      'Showing the built-in default — edit and Save to customise, or Reset to default to restore it. Highlighted chips are variables present in your text.';
    // Show the RESOLVED content (defaults filled in) so the editor is never blank.
    document.getElementById('emailTplSubject').value = t.subject || '';
    document.getElementById('emailTplBody').value = t.bodyHtml || '';
    document.getElementById('emailTplError').style.display = 'none';
    document.getElementById('emailTplSuccess').style.display = 'none';

    // Variable chips — colour is set dynamically by updateVarChips() based on whether
    // each {Token} currently appears in the subject/body.
    const varsWrap = document.getElementById('emailTplVars');
    const avail = Array.isArray(t.availableVariables) ? t.availableVariables : [];
    const required = Array.isArray(t.requiredVariables) ? t.requiredVariables : [];
    varsWrap.innerHTML = avail.map((v) => {
      const isReq = required.indexOf(v) !== -1;
      return `<button type="button" class="email-tpl-var-chip" data-var="${escapeHtml(v)}" data-required="${isReq ? '1' : '0'}"
        style="font-family:monospace;font-size:11px;padding:3px 9px;border-radius:999px;cursor:pointer;transition:background .12s,border-color .12s,color .12s,opacity .12s;">{${escapeHtml(v)}}${isReq ? ' *' : ''}</button>`;
    }).join('');
    varsWrap.querySelectorAll('.email-tpl-var-chip').forEach((chip) => {
      chip.addEventListener('click', () => { insertVariable(chip.getAttribute('data-var')); updateVarChips(); });
    });

    document.getElementById('emailTplRequiredNote').textContent = required.length
      ? `Required variables (marked *): ${required.map((v) => '{' + v + '}').join(', ')}`
      : 'This template has no required variables.';

    updateVarChips();
    document.getElementById('emailTplEditorCard').style.display = '';
    document.getElementById('emailTplEditorCard').scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  // Insert a {variable} token at the cursor in whichever field was last focused
  // (defaults to the body textarea).
  let lastFocusedField = 'emailTplBody';
  ['emailTplSubject', 'emailTplBody'].forEach((fid) => {
    const el = document.getElementById(fid);
    el.addEventListener('focus', () => { lastFocusedField = fid; });
    el.addEventListener('input', updateVarChips);
  });

  // Highlight each variable chip when its {Token} is present in the current subject/body;
  // mute it when absent; flag a required token that's still missing (save will reject it).
  function updateVarChips() {
    const text = (document.getElementById('emailTplSubject').value || '') + '\n' +
                 (document.getElementById('emailTplBody').value || '');
    document.querySelectorAll('#emailTplVars .email-tpl-var-chip').forEach((chip) => {

