    public async Task<EmailTemplate> SetEmailTemplateEnabledAsync(string id, bool isEnabled, CancellationToken ct = default)
    {
        var def = EmailTemplateDefaults.ById(id);
        if (def == null)
            throw new InvalidOperationException($"Unknown email template id '{id}'.");

        var settings = await GetAsync(ct);
        var list = settings.EmailTemplates ?? new List<EmailTemplate>();
        var entry = list.FirstOrDefault(t => t.Id == id);
        if (entry == null)
        {
            entry = new EmailTemplate { Id = id, Name = def.Name };
            list.Add(entry);
        }
        entry.IsEnabled = isEnabled;
        settings.EmailTemplates = list.Where(t => EmailTemplateDefaults.ById(t.Id) != null).ToList();
        settings.UpdatedAt = DateTime.UtcNow;
        await _settings.ReplaceOneAsync(s => s.Id == settings.Id, settings, cancellationToken: ct);
        return (await GetResolvedEmailTemplateAsync(id, ct))!;
    }

    /// <summary>
    /// Decrypt a stored value, returning empty string on any failure
    /// (empty input, corrupted data, key rotation). This prevents a
    /// single corrupted field from crashing the entire settings load.
    /// </summary>
    private string SafeDecrypt(string? encrypted)
    {
        if (string.IsNullOrEmpty(encrypted)) return "";
        try
        {
            return SettingsEncryptionHelper.Decrypt(encrypted, _encryptionKey);
        }
        catch
        {
            return "";
        }
    }
}

