public async Task<EmailTemplate?> GetResolvedEmailTemplateAsync(string id, CancellationToken ct = default)
{
    var def = EmailTemplateDefaults.ById(id);
    if (def == null) return null; // unknown id — caller must use its hardcoded fallback

    var settings = await GetAsync(ct);
    var stored = (settings.EmailTemplates ?? new List<EmailTemplate>())
        .FirstOrDefault(t => t.Id == id);

    // Resolve each field independently: a blank stored field falls back to the
    // built-in default so a partially-customised template never sends a blank
    // subject or body.
    var subject = stored != null && !string.IsNullOrWhiteSpace(stored.Subject)
        ? stored.Subject
        : def.Subject;
    var body = stored != null && !string.IsNullOrWhiteSpace(stored.BodyHtml)
        ? stored.BodyHtml
        : def.BodyHtml;

    return new EmailTemplate
    {
        Id = def.Id,
        Name = def.Name,
        Subject = subject,
        BodyHtml = body,
        RequiredVariables = new List<string>(def.RequiredVariables),
        AvailableVariables = new List<string>(def.AvailableVariables),
    };
}

public async Task<EmailTemplate> UpdateEmailTemplateAsync(string id, string subject, string bodyHtml, CancellationToken ct = default)
{
    var def = EmailTemplateDefaults.ById(id);
    if (def == null)
        throw new InvalidOperationException($"Unknown email template id '{id}'.");

    subject ??= "";
    bodyHtml ??= "";

    // Required-variable validation. A blank field means "use the built-in
    // default" for that field, so it can't be missing a variable — only
    // validate the non-blank fields. We check the COMBINED non-blank text so a
    // variable that legitimately lives only in the subject (or only the body)
    // still counts as present.
    var subjectProvided = !string.IsNullOrWhiteSpace(subject);
    var bodyProvided = !string.IsNullOrWhiteSpace(bodyHtml);

    // Validate the EFFECTIVE content that will actually be sent: a blank field
    // resolves to the built-in default (which always contains its variables). So
    // customising ONLY the subject (leaving the body on default) still passes when a
    // required variable lives in the body, and vice-versa.
    if (subjectProvided || bodyProvided)
    {
        var effSubject = subjectProvided ? subject : def.Subject;
        var effBody = bodyProvided ? bodyHtml : def.BodyHtml;
        var combined = effSubject + "\n" + effBody;
        foreach (var v in def.RequiredVariables)
        {
            if (!combined.Contains("{" + v + "}", StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    $"Email template '{def.Name}' is missing the required variable {{{v}}}. " +
                    $"It must appear in the subject or body.");
