private string CustomerPortalUrl => $"{_publicBaseUrl}/account";

public EmailService(IConfiguration configuration, ILogger<EmailService> logger, ISettingsService? settingsService = null)
{
    _logger = logger;
    var section = configuration.GetSection("SmtpSettings");
    _smtpHost = section["Host"] ?? "smtp.gmail.com";
    _smtpPort = int.Parse(section["Port"] ?? "587");
    _smtpUser = section["Username"] ?? "";
    _smtpPass = section["Password"] ?? "";
    _fromEmail = section["FromEmail"] ?? "noreply@soulpilates.com.vn";
    _fromName = section["FromName"] ?? "Soul Pilates Da Nang";
    _enabled = bool.Parse(section["Enabled"] ?? "false");
    _settingsService = settingsService;

    // PublicSite:BaseUrl drives every absolute link emitted by this
    // service. We trim trailing slashes so callers can compose paths as
    // $"{_publicBaseUrl}/verify-email?..." without worrying about "//"
    // in the final URL.
    var rawBase = configuration["PublicSite:BaseUrl"];
    _publicBaseUrl = string.IsNullOrWhiteSpace(rawBase)
        ? "http://localhost:4321"
        : rawBase.TrimEnd('/');
}

public async Task SendBookingConfirmationAsync(string toEmail, string clientName, string bookingReference,
    string className, string instructorName, DateTime classTime, string format,
    DateTime? endTime = null)
{
    if (!_enabled || string.IsNullOrWhiteSpace(toEmail)) return;
