content.content:
250	        // ── Aggregate session-level earnings ───────────────────────────
251	        // Private fractional revenue is summed *raw* here, then the commission
252	        // rate is applied below once we know the class count for tier resolution.
253	        //
254	        // For PERCENTAGE_TIERED group classes, we also accumulate raw group revenue
255	        // so the tiered commission can be applied at the end.
256	        decimal privateRawRevenue = 0;
257	        decimal groupRawRevenue = 0;
258	        int totalClassesWithAttendees = 0;
259	        foreach (var session in sessions)
260	        {
261	            // Load attendances that actually showed up (CHECKED_IN or ARRIVED)
262	            // — the frontend sets "ARRIVED" via the status dropdown, but some
263	            // legacy code paths set "CHECKED_IN" directly. Accept both.
264	            var rawArrivedAttendances = await _attendances
265	                .Find(a => a.CalendarSessionId == session.Id
266	                        && (a.Status == "CHECKED_IN" || a.Status == "ARRIVED")
267	                        && a.Status != "CANCELLED")
268	                .ToListAsync();
269	
270	            // SPM-113 — money: an arrival only counts toward the instructor's
271	            // commission if the attendee both arrived AND paid. The owner
272	            // decision is to apply the paid rule EVERYWHERE — earnings total,
273	            // head-count payout, and tier thresholds — so we filter the arrived
274	            // set here, BEFORE it feeds any of those calculations. Genuinely
275	            // unpaid monetary arrivals count nowhere; PACKAGE_CREDIT and free
276	            // classes remain satisfied (see IsAttendancePaidAsync). The filter
277	            // is a pure read, so re-runs stay idempotent.
278	            var arrivedAttendances = new List<Attendance>();
279	            foreach (var a in rawArrivedAttendances)
280	            {
281	                if (await IsAttendancePaidAsync(a)) arrivedAttendances.Add(a);
282	            }
283	
284	            // Only count towards tiers if at least one paid attendee arrived.
285	            // Empty classes (or classes with only unpaid arrivals) must not
286	            // inflate the tier counter or generate any payout.
287	            if (arrivedAttendances.Count == 0) continue;
288	
289	            var isPrivate = session.Capacity == 1 || session.Format == "PRIVATE";
290	            if (!isPrivate)
291	            {
292	                result.TotalGroupClasses++;
293	                totalClassesWithAttendees++;
294	
295	                if (result.CommissionModelSnapshot == "FIXED_HEADCOUNT")
296	                {
297	                    // SPM-90 — the headcount ladder is per SEAT, not per attendance
298	                    // ROW. A group booking of N seats (att.Quantity == N) counts as
299	                    // N students, exactly like PERCENTAGE_TIERED sums per-attendee
300	                    // revenue with quantity. Empty-arrival attendees
301	                    // (CountsTowardsCommission == false) are excluded from the count.
302	                    var seatHeadcount = arrivedAttendances
303	                        .Where(a => a.CountsTowardsCommission)
304	                        .Sum(a => Math.Max(1, a.Quantity));
305	
306	                    result.GroupClassEarnings += ResolveHeadcountPayoutFromSnapshot(result, seatHeadcount);
307	                }
308	                else if (result.CommissionModelSnapshot == "PERCENTAGE_TIERED")
309	                {
310	                    // ── PERCENTAGE_TIERED for group classes ──────────────────
311	                    // The instructor earns a % of the revenue generated by the
312	                    // attendees who arrived. Revenue per attendee is determined
313	                    // from their linked invoice paid balance, falling back to
314	                    // the session's drop-in price.
315	                    foreach (var att in arrivedAttendances)
316	                    {
317	                        if (!att.CountsTowardsCommission) continue;
318	
319	                        var revenueBase = await ResolveAttendeeRevenueAsync(att, session);
320	
321	                        // Apply referral discount.
322	                        var discountPct = att.ReferralDiscountPct.HasValue
323	                            ? Math.Clamp(att.ReferralDiscountPct.Value, 0m, 1m)
324	                            : 0m;
325	                        groupRawRevenue += revenueBase * (1m - discountPct);
326	                    }
327	
328	                    // Also add flat rate + per-head if configured (hybrid model).
