    private static decimal ResolveHeadcountPayoutFromSnapshot(InstructorPayrollResult r, int students, bool isPrivate = false)
    {
        if (students <= 0) return 0m;

        var tiers = isPrivate && r.PrivateHeadcountTiersSnapshot is { Count: > 0 }
            ? r.PrivateHeadcountTiersSnapshot
            : r.HeadcountTiersSnapshot;

        var fallbackRate = isPrivate && r.PrivateRatePerHeadSnapshot > 0m
            ? r.PrivateRatePerHeadSnapshot
            : r.RatePerHeadSnapshot;

        return ResolveHeadcountPayoutCore(tiers, fallbackRate, r.UseMarginalHeadcountTiersSnapshot, students);
    }

    private static decimal ResolveHeadcountPayoutCore(
        IReadOnlyList<HeadcountPayoutTier>? tiers,
        decimal fallbackRate,
        bool useMarginal,
        int students)
    {
        if (tiers is null || tiers.Count == 0)
        {
            return fallbackRate * students;
        }

        var ordered = tiers.OrderBy(t => t.MinStudents).ToList();

        if (useMarginal)
        {
            decimal total = 0m;
            for (int n = 1; n <= students; n++)
            {
                var rung = ordered.FirstOrDefault(t =>
                    n >= t.MinStudents && (!t.MaxStudents.HasValue || n <= t.MaxStudents.Value));
                rung ??= ordered.First();
                total += rung.RatePerStudent;
            }
            return total;
        }

        var flatRung = ordered.FirstOrDefault(t =>
            students >= t.MinStudents && (!t.MaxStudents.HasValue || students <= t.MaxStudents.Value));
        flatRung ??= students > ordered.Last().MinStudents ? ordered.Last() : ordered.First();
        return flatRung.RatePerStudent * students;
    }
}

