        // Resolve the in-force rate revision for the period END. Using End
        // (not Start) matches what a payroll clerk expects — "pay people
        // under whatever rate was in effect when the month closed". The
        // revision service lazily bootstraps a baseline if there is no
        // revision yet (legacy staff rows), so the result is never null
        // for an existing staff member.
        var revision = await _revisions.ResolveAsOfAsync(staff.Id!, end);

        // Monthly commission override takes precedence over the revision.
        revision = await ApplyCommissionOverrideAsync(staff.Id!, end, revision);

        var result = await AggregateInstructorAsync(staff, revision, group.ToList());
        run.Results.Add(result);
    }

    run.TotalPayroll = run.Results.Sum(r => r.TotalPay);

    if (existing is null)
    {
        await _payrollRuns.InsertOneAsync(run);
    }
    else
    {
        await _payrollRuns.ReplaceOneAsync(p => p.Id == existing.Id, run);
    }

    return run;
}

/// <summary>
/// P3-S10 — live per-instructor recalc for the instructor self-service portal.
/// Reuses the same <see cref="AggregateInstructorAsync"/> helper as the admin
/// payroll path so the two surfaces never drift. **Deliberately does NOT
/// persist a <see cref="PayrollRun"/> row** — the instructor portal would
/// otherwise pollute the audit history on every dashboard refresh.
///
/// <para>
/// Reads rates from the in-force revision as-of <paramref name="end"/> so
/// the portal's tier-progress meter matches what the admin payroll path
/// would compute for the same window — including for historical months.
/// </para>
/// </summary>
public async Task<InstructorPayrollResult?> CalculateForInstructorAsync(
    string staffId, DateTime start, DateTime end)
{
    if (string.IsNullOrWhiteSpace(staffId)) return null;

    var staff = await _staff.Find(s => s.Id == staffId).FirstOrDefaultAsync();
    if (staff is null) return null;

    var revision = await _revisions.ResolveAsOfAsync(staff.Id!, end);

    // Monthly commission override takes precedence over the revision.
    revision = await ApplyCommissionOverrideAsync(staff.Id!, end, revision);

    // Pull only this instructor's COMPLETED sessions — must mirror
    // the admin payroll path exactly (Status == "COMPLETED") so the
    // instructor portal never shows a different number from the
    // admin washout. SCHEDULED/NO_SHOW sessions must be excluded;
    // they haven't happened yet (or were empty) and should not
    // contribute to the earnings total.
    var sessions = await _sessions
        .Find(s => s.InstructorId == staffId
                && s.StartTime >= start
                && s.StartTime <= end
                && s.Status == "COMPLETED"
                && s.Origin != "BLOCK")
        .ToListAsync();

