function monthRange() {
  const now = new Date();
  const start = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;
  const nx = new Date(now.getFullYear(), now.getMonth()+1, 1);
  const end = `${nx.getFullYear()}-${String(nx.getMonth()+1).padStart(2,'0')}-01`;
  return { start, end };
}

// ── shared fetches (cached so multiple widgets reuse one request) ──
let _kpis, _summary;
const getKpis = () => (_kpis ||= fetch(`${API}/api/analytics/dashboard-kpis`, { headers: authH }).then(r => r.ok ? r.json() : null).catch(() => null));
const getSummary = () => {
  const { start, end } = monthRange();
  return (_summary ||= fetch(`${API}/api/analytics/month-summary?startDate=${start}&endDate=${end}`, { headers: authH }).then(r => r.ok ? r.json() : null).catch(() => null));
};

// ── widget registry: id → { render(el), load(el) } ──
const WIDGETS = {
  'revenue-kpi': {
    render: () => `<div class="wg-eyebrow">Finance</div><div class="wg-title">Monthly Revenue</div><div class="wg-big" data-f="v">--</div><div class="wg-delta flat" data-f="d">Loading…</div>`,
    load: async (el) => { const d = await getKpis(); if (!d) return; el.querySelector('[data-f=v]').textContent = fmtVnd(d.monthlyRevenueVnd ?? 0);
      const de = el.querySelector('[data-f=d]'); const p = d.monthlyRevenueDeltaPct;
      if (p == null || Math.abs(p) > 999) { de.textContent = 'New month baseline'; de.className = 'wg-delta flat'; }
      else if (p >= 0) { de.textContent = `▲ ${p.toFixed(1)}% vs last month`; de.className = 'wg-delta up'; }
      else { de.textContent = `▼ ${Math.abs(p).toFixed(1)}% vs last month`; de.className = 'wg-delta down'; } },
  },
  'payroll-estimate': {
    render: () => `<div class="wg-eyebrow">Finance</div><div class="wg-title">Payroll Estimate</div><div class="wg-big" data-f="v">--</div><div class="wg-sub" data-f="s">&nbsp;</div>`,
    load: async (el) => { const d = await getKpis(); if (!d) return; el.querySelector('[data-f=v]').textContent = fmtVnd(d.payrollEstimateVnd ?? 0); if (d.payrollEstimatePeriodLabel) el.querySelector('[data-f=s]').textContent = d.payrollEstimatePeriodLabel; },
  },
  'active-clients': {
    render: () => `<div class="wg-eyebrow">Clients</div><div class="wg-title">Active Clients (30d)</div><div class="wg-big" data-f="v">--</div><div class="wg-sub">Distinct clients active in the last 30 days</div>`,
    load: async (el) => { const d = await getKpis(); if (d) el.querySelector('[data-f=v]').textContent = fmtInt(d.activeClients30d ?? 0); },
  },
  'classes-week': {
    render: () => `<div class="wg-eyebrow">Schedule</div><div class="wg-title">Classes This Week</div><div class="wg-big" data-f="v">--</div><div class="wg-sub">Scheduled classes this week</div>`,
    load: async (el) => { const d = await getKpis(); if (d) el.querySelector('[data-f=v]').textContent = fmtInt(d.classesThisWeek ?? 0); },
  },
  'occupancy': {
    render: () => `<div class="wg-eyebrow">Operations</div><div class="wg-title">Class Occupancy</div><div class="wg-big" data-f="v">--</div><div class="wg-sub">Average fill rate this month</div>`,
    load: async (el) => { const d = await getSummary(); if (d) el.querySelector('[data-f=v]').textContent = fmtPctRaw(d.avgGroupClassOccupancy ?? 0); },
  },
  'live-visitors': {
    render: () => `<div class="wg-eyebrow">Web</div><div class="wg-title"><span class="wg-live-dot"></span>Live Visitors</div><div class="wg-big" data-f="v">--</div><div class="wg-sub">Active on the site in the last 5 min</div>`,
    load: async (el) => {
      const hit = async () => { try { const r = await fetch(`${API}/api/track/visitors/live`, { headers: authH }); if (r.ok) { const d = await r.json(); el.querySelector('[data-f=v]').textContent = fmtInt(d.live ?? 0); } } catch {} };
      hit(); const t = setInterval(() => { if (document.visibilityState === 'visible') hit(); }, 20000); el._timer = t;
    },
  },
  'studio-pulse': {
    render: () => `<div class="wg-eyebrow">Operating notes</div><div class="wg-title">Studio Pulse</div><div class="wg-body"><div class="wg-pulse-grid">
      ${['Month Revenue|r','Packages Sold|p','New Clients|n','Projection|j','Classes Held|c','Merch Revenue|m'].map(x=>{const[l,k]=x.split('|');return `<div class="wg-pulse-cell"><div class="l">${l}</div><div class="v" data-k="${k}">--</div></div>`}).join('')}
    </div></div>`,
    load: async (el) => { const d = await getSummary(); if (!d) return; const s=(k,v)=>{const e=el.querySelector(`[data-k=${k}]`); if(e)e.textContent=v;};
      s('r',fmtVnd(d.totalRevenueVnd??0)); s('p',fmtInt(d.packagesSold??0)); s('n',fmtInt(d.newClients??0)); s('j',fmtVnd(d.monthlyProjectionVnd??0)); s('c',fmtInt(d.totalClasses??0)); s('m',fmtVnd(d.merchandiseRevenueVnd??0)); },
  },
  'recent-invoices': {
    render: () => `<div class="wg-eyebrow">Live activity</div><div class="wg-title">Recent Invoices</div><div class="wg-body"><table class="wg-table"><thead><tr><th>Client</th><th>Date</th><th class="num">Amount</th></tr></thead><tbody data-f="b"><tr><td colspan="3" class="wg-muted">Loading…</td></tr></tbody></table></div>`,
    load: async (el) => { try { const r = await fetch(`${API}/api/invoice/recent?limit=6`, { headers: authH }); const inv = r.ok ? await r.json() : []; const b = el.querySelector('[data-f=b]');
      if (!inv?.length) { b.innerHTML = `<tr><td colspan="3" class="wg-muted">No invoices yet.</td></tr>`; return; }
      b.innerHTML = inv.map(i => `<tr><td>${esc(i.clientName)}</td><td>${new Date(i.issueDate).toLocaleDateString('en-US',{month:'short',day:'numeric'})}</td><td class="num">${fmtVnd(i.totalNet)}</td></tr>`).join(''); } catch {} },
  },
  'top-clients': {
    render: () => `<div class="wg-eyebrow">Operations</div><div class="wg-title">Top Clients</div><div class="wg-body"><table class="wg-table"><thead><tr><th>Client</th><th class="num">Revenue</th></tr></thead><tbody data-f="b"><tr><td colspan="2" class="wg-muted">Loading…</td></tr></tbody></table></div>`,
    load: async (el) => { const { start, end } = monthRange(); try { const r = await fetch(`${API}/api/analytics/top-clients?startDate=${start}&endDate=${end}&top=6`, { headers: authH }); const rows = r.ok ? await r.json() : []; const b = el.querySelector('[data-f=b]');
      if (!rows?.length) { b.innerHTML = `<tr><td colspan="2" class="wg-muted">No data this month.</td></tr>`; return; }
      b.innerHTML = rows.map(c => `<tr><td>${esc(c.fullName)}</td><td class="num">${fmtVnd(c.revenueVnd)}</td></tr>`).join(''); } catch {} },
  },
  'signup-source': {
    render: () => `<div class="wg-eyebrow">Acquisition</div><div class="wg-title">Sign-up Source</div><div class="wg-body"><table class="wg-table"><thead><tr><th>Source</th><th class="num">Customers</th><th class="num">Share</th></tr></thead><tbody data-f="b"><tr><td colspan="3" class="wg-muted">Loading…</td></tr></tbody></table></div>`,
    load: async (el) => { const { start, end } = monthRange(); try { const r = await fetch(`${API}/api/track/visitors/signup-sources?start=${start}&end=${end}`, { headers: authH }); const rows = r.ok ? await r.json() : []; const b = el.querySelector('[data-f=b]');
      if (!rows?.length) { b.innerHTML = `<tr><td colspan="3" class="wg-muted">No sign-ups this month.</td></tr>`; return; }
      b.innerHTML = rows.map(x => { const l = String(x.label||''); return `<tr><td>${esc(l.charAt(0).toUpperCase()+l.slice(1))}</td><td class="num">${fmtInt(x.visitors)}</td><td class="num">${x.percentage}%</td></tr>`; }).join(''); } catch {} },
  },
  'booking-funnel': {
    render: () => `<div class="wg-eyebrow">Conversion</div><div class="wg-title">Booking Funnel</div><div class="wg-body" data-f="b"><div class="wg-muted">Loading…</div></div>`,
    load: async (el) => { const { start, end } = monthRange(); try { const r = await fetch(`${API}/api/track/visitors/funnel?start=${start}&end=${end}`, { headers: authH }); const rows = r.ok ? await r.json() : []; const b = el.querySelector('[data-f=b]');
      if (!rows?.length || rows[0]?.sessions === 0) { b.innerHTML = `<div class="wg-muted">No funnel activity this month.</div>`; return; }
      b.innerHTML = rows.map(s => `<div class="wg-funnel-row"><div class="wg-funnel-bar-wrap"><div class="wg-funnel-bar" style="width:${Math.max(s.conversionFromStart,3)}%">${fmtInt(s.sessions)}</div></div><div class="wg-funnel-label">${esc(s.step)} · ${s.conversionFromStart}%</div></div>`).join(''); } catch {} },
  },
  'revenue-vs-expenses': {
    render: () => `<div class="wg-eyebrow">Finance trend</div><div class="wg-title">Revenue vs Expenses</div><div class="wg-body"><div class="wg-canvas-wrap"><canvas data-f="c"></canvas></div></div>`,
    load: async (el) => { try { const year = new Date().getFullYear(); const r = await fetch(`${API}/api/analytics/yearly-revenue-expense?year=${year}`, { headers: authH }); const rows = r.ok ? await r.json() : []; const ctx = el.querySelector('[data-f=c]').getContext('2d');
      if (el._chart) el._chart.destroy();
      el._chart = new Chart(ctx, { type: 'line', data: { labels: rows.map(x => x.monthLabel || x.month || ''), datasets: [
        { label: 'Revenue', data: rows.map(x => x.revenueVnd ?? 0), borderColor: css('--color-brand-accent') || '#db7d3c', backgroundColor: 'rgba(219,125,60,0.15)', fill: true, tension: 0.35 },
        { label: 'Expenses', data: rows.map(x => x.expensesVnd ?? 0), borderColor: '#4ea5d9', backgroundColor: 'rgba(78,165,217,0.12)', fill: true, tension: 0.35 } ] },
        options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { labels: { boxWidth: 12, font: { size: 10 } } } }, scales: { y: { ticks: { callback: v => (v/1e6).toFixed(0)+'M', font: { size: 9 } } }, x: { ticks: { font: { size: 9 } } } } } }); } catch {} },
  },
  'revenue-breakdown': {
    render: () => `<div class="wg-eyebrow">Sales mix</div><div class="wg-title">What's Driving Revenue</div><div class="wg-body"><div class="wg-canvas-wrap"><canvas data-f="c"></canvas></div></div>`,
    load: async (el) => { const { start, end } = monthRange(); try { const r = await fetch(`${API}/api/analytics/revenue-breakdown?startDate=${start}&endDate=${end}`, { headers: authH }); const d = r.ok ? await r.json() : null; if (!d) return; const ctx = el.querySelector('[data-f=c]').getContext('2d');
      if (el._chart) el._chart.destroy();
      el._chart = new Chart(ctx, { type: 'doughnut', data: { labels: ['Classes','Packages','Merch','Rentals'], datasets: [{ data: [d.singleClassRevenueVnd??0, d.packageRevenueVnd??0, d.merchandiseRevenueVnd??0, d.rentalRevenueVnd??0], backgroundColor: ['#db7d3c','#4ea5d9','#44be82','#9b59b6'] }] }, options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { position: 'bottom', labels: { boxWidth: 10, font: { size: 10 } } } } } }); } catch {} },
  },
};

// ── state ──
let grid = null;
let catalog = [];       // [{id,title,category,description,defaultW,defaultH,minW,minH}]
let placements = [];    // [{widgetId,x,y,w,h}]
const gridEl = document.getElementById('dashGrid');

function widgetInner(id) {
  const w = WIDGETS[id];
  return `<button class="wg-remove" data-remove="${id}" title="Remove">✕</button>${w ? w.render() : `<div class="wg-muted">${esc(id)}</div>`}`;
}

function addWidgetToGrid(p) {
  const meta = catalog.find(c => c.id === p.widgetId) || {};
  const el = grid.addWidget({
    x: p.x, y: p.y, w: p.w || meta.defaultW || 4, h: p.h || meta.defaultH || 2,
    minW: meta.minW || 2, minH: meta.minH || 2,
    content: widgetInner(p.widgetId),
  });
  el.setAttribute('gs-widget-id', p.widgetId);
  const contentEl = el.querySelector('.grid-stack-item-content');
  const w = WIDGETS[p.widgetId];
  if (w && w.load) { try { w.load(contentEl); } catch (e) { console.warn('widget load failed', p.widgetId, e); } }
  return el;

