using System;
using System.Collections.Generic;
using System.Linq;

namespace SoulPilates.Core.Dashboard;

/// <summary>
/// Server-authoritative catalog of dashboard widgets. Each widget declares the
/// roles allowed to see it, so revenue/financial widgets never reach a
/// receptionist or instructor even if a tampered layout requests them. The
/// frontend renders only what this catalog (filtered by role) returns.
/// </summary>
public static class DashboardWidgetCatalog
{
    public sealed record Widget(
        string Id,
        string Title,
        string Category,
        string Description,
        int DefaultW,
        int DefaultH,
        int MinW,
        int MinH,
        string[] AllowedRoles);

    // Role groups. Financial data is limited to the money-trusted roles.
    private static readonly string[] Financial = { "Admin", "Owner", "Accountant", "SuperAdmin" };
    private static readonly string[] Operational = { "Admin", "Owner", "Accountant", "Manager", "Receptionist", "SuperAdmin" };
    private static readonly string[] Everyone = { "Admin", "Owner", "Accountant", "Manager", "Receptionist", "Instructor", "Freelance", "SuperAdmin" };

    /// <summary>The full catalog. Order here is the default placement order.</summary>
    public static readonly IReadOnlyList<Widget> All = new List<Widget>
    {
        // ── Financial (Admin / Owner / Accountant) ──
        new("revenue-kpi",        "Monthly Revenue",      "Financial",   "Revenue this month with month-over-month delta.", 4, 2, 3, 2, Financial),
        new("payroll-estimate",   "Payroll Estimate",     "Financial",   "Estimated payroll for the current period.",       4, 2, 3, 2, Financial),
        new("revenue-vs-expenses","Revenue vs Expenses",  "Financial",   "Yearly revenue against expenses.",                8, 4, 4, 3, Financial),
        new("revenue-breakdown",  "What's Driving Revenue","Financial",  "Revenue split by source (classes / packages / merch).", 4, 4, 3, 3, Financial),
        new("recent-invoices",    "Recent Invoices",      "Financial",   "The latest invoices raised.",                     6, 4, 4, 3, Financial),
        new("signup-source",      "Sign-up Source",       "Financial",   "How new customers heard about the studio.",       6, 3, 4, 2, Financial),

        // ── Operational (Admin / Owner / Accountant / Manager / Receptionist) ──
        new("active-clients",     "Active Clients (30d)", "Operational", "Distinct clients with activity in the last 30 days.", 4, 2, 3, 2, Operational),
        new("classes-week",       "Classes This Week",    "Operational", "Scheduled classes for the current week.",         4, 2, 3, 2, Everyone),
        new("occupancy",          "Class Occupancy",      "Operational", "Average class fill rate for the period.",          4, 2, 3, 2, Operational),
        new("studio-pulse",       "Studio Pulse",         "Operational", "Today's at-a-glance activity snapshot.",           6, 4, 4, 3, Operational),
        new("top-clients",        "Top Clients",          "Operational", "Highest-value clients for the period.",            6, 4, 4, 3, Operational),

        // ── Web analytics (Admin / Owner / Accountant / Manager / Receptionist) ──
        new("live-visitors",      "Live Visitors",        "Web",         "Visitors active on the site right now.",           3, 2, 3, 2, Operational),
        new("booking-funnel",     "Booking Funnel",       "Web",         "Where visitors drop off on the way to a booking.", 8, 4, 4, 3, Operational),
    };

    /// <summary>Widgets a given role is allowed to see.</summary>
    public static IEnumerable<Widget> ForRole(string? role)
    {
        var r = (role ?? "").Trim();
        return All.Where(w => w.AllowedRoles.Contains(r, StringComparer.OrdinalIgnoreCase));
    }

    public static bool IsAllowed(string widgetId, string? role)
    {
        var r = (role ?? "").Trim();
        return All.Any(w => w.Id == widgetId && w.AllowedRoles.Contains(r, StringComparer.OrdinalIgnoreCase));
    }

    /// <summary>Default layout for a role: allowed widgets flowed onto a 12-col grid.</summary>
    public static List<(string WidgetId, int X, int Y, int W, int H)> DefaultLayoutFor(string? role)
    {
        var result = new List<(string, int, int, int, int)>();
        int x = 0, y = 0, rowH = 0;
        foreach (var w in ForRole(role))
        {
            if (x + w.DefaultW > 12) { x = 0; y += rowH; rowH = 0; }
            result.Add((w.Id, x, y, w.DefaultW, w.DefaultH));
            x += w.DefaultW;
            rowH = Math.Max(rowH, w.DefaultH);
        }
        return result;
    }
}

