:root {
  /* Brand */
  --brand: #F0642B;
  --brand-2: #FF8A3D;
  --brand-3: #FFB067;
  --brand-ink: #C24A17;
  --brand-glow: rgba(240, 100, 43, 0.35);

  /* Neutrals — light */
  --bg: #FFFFFF;
