  --ink-2: #423B33;
  --ink-3: #6B6259;
  --line: rgba(22, 19, 15, 0.09);
  --line-2: rgba(22, 19, 15, 0.06);
  --card: #FFFFFF;

  /* Charcoal (dark sections) */
  --char: #14110E;
  --char-2: #1C1813;
  --char-3: #251F19;
  --char-line: rgba(255, 255, 255, 0.10);
  --char-ink: #F5F1EC;
  --char-ink-2: rgba(245, 241, 236, 0.66);

  /* Accents for charts */
