/* Nexis marketing site — interactions & data-driven grids */
(function () {
  'use strict';

  var icon = function (p) {
    return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' + p + '</svg>';
  };

  /* ---------- Nav: scrolled state + mobile toggle ---------- */
  var nav = document.getElementById('nav');
  var onScroll = function () { nav.classList.toggle('scrolled', window.scrollY > 12); };
  window.addEventListener('scroll', onScroll, { passive: true }); onScroll();

  var toggle = document.getElementById('navToggle');
  var links = document.getElementById('navLinks');
  if (toggle) toggle.addEventListener('click', function () { links.classList.toggle('open'); });
  links.querySelectorAll('a').forEach(function (a) { a.addEventListener('click', function () { links.classList.remove('open'); }); });

  /* ---------- Scroll reveal ---------- */
  var io = new IntersectionObserver(function (entries) {
    entries.forEach(function (e) { if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); } });
  }, { threshold: 0.12, rootMargin: '0px 0px -8% 0px' });
  var observeReveals = function () { document.querySelectorAll('.reveal:not(.in)').forEach(function (el) { io.observe(el); }); };

  /* ---------- Count-up stats ---------- */
  var countUp = function (el) {
    var target = parseFloat(el.getAttribute('data-count'));
    var dec = parseInt(el.getAttribute('data-dec') || '0', 10);
    var suffix = el.getAttribute('data-suffix') || '';
    var span = el.querySelector('span') || el;
    var start = null, dur = 1600;
    var step = function (ts) {
      if (!start) start = ts;
      var p = Math.min((ts - start) / dur, 1);
      var eased = 1 - Math.pow(1 - p, 3);
      var val = target * eased;
      span.textContent = (dec ? val.toFixed(dec) : Math.floor(val).toLocaleString('en-US')) + suffix;
      if (p < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  };
  var statIO = new IntersectionObserver(function (entries) {
    entries.forEach(function (e) { if (e.isIntersecting) { countUp(e.target); statIO.unobserve(e.target); } });
  }, { threshold: 0.6 });
  document.querySelectorAll('.num[data-count]').forEach(function (el) { statIO.observe(el); });

  /* ---------- Feature grid ---------- */
  var features = [
    ['Online Booking', 'M8 2v4M16 2v4M3 10h18M5 4h14a2 2 0 012 2v13a2 2 0 01-2 2H5a2 2 0 01-2-2V6a2 2 0 012-2z'],
    ['Recurring Memberships', 'M3 12a9 9 0 019-9 9 9 0 016.7 3M21 12a9 9 0 01-9 9 9 9 0 01-6.7-3M21 3v6h-6M3 21v-6h6'],
    ['Class Packages', 'M3 8.5L12 4l9 4.5M3 8.5v7L12 20l9-4.5v-7M3 8.5L12 13l9-4.5'],
    ['Payment Gateway', 'M2 6h20v12H2zM2 10h20'],
    ['Point of Sale', 'M6 2l-3 4v14a2 2 0 002 2h14a2 2 0 002-2V6l-3-4zM3 6h18M16 10a4 4 0 01-8 0'],
    ['CRM', 'M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2M9 7a4 4 0 100 8 4 4 0 000-8zM23 21v-2a4 4 0 00-3-3.87'],
    ['Client Notes', 'M4 4h16v14l-4-3H4zM8 9h8M8 12h5'],
    ['Attendance Tracking', 'M9 11l3 3L22 4M21 12v7a2 2 0 01-2 2H5a2 2 0 01-2-2V5a2 2 0 012-2h11'],
    ['Digital Waivers', 'M4 3h11l5 5v13H4zM15 3v5h5M8 13h8M8 17h5'],
    ['Mobile Friendly', 'M7 2h10a2 2 0 012 2v16a2 2 0 01-2 2H7a2 2 0 01-2-2V4a2 2 0 012-2zM11 18h2'],
    ['Email Automation', 'M4 4h16v16H4zM4 6l8 6 8-6'],
    ['SMS Automation', 'M21 15a2 2 0 01-2 2H7l-4 4V5a2 2 0 012-2h14a2 2 0 012 2z'],
    ['Push Notifications', 'M18 8A6 6 0 006 8c0 7-3 9-3 9h18s-3-2-3-9M13.7 21a2 2 0 01-3.4 0'],
    ['Gift Cards', 'M20 12v9H4v-9M2 7h20v5H2zM12 7v14M12 7a3 3 0 10-3-3M12 7a3 3 0 013-3'],
    ['Discount Codes', 'M9 9h.01M15 15h.01M7 7l10 10M20.5 12a8.5 8.5 0 11-17 0 8.5 8.5 0 0117 0z'],
    ['Waitlists', 'M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2M9 7a4 4 0 100 8 4 4 0 000-8zM19 8v6M22 11h-6'],
    ['Reporting', 'M4 4h16v16H4zM8 16v-4M12 16V8M16 16v-6'],
    ['Analytics', 'M3 3v18h18M7 14l3-3 4 4 6-6'],
    ['Accounting', 'M12 1v22M17 5H9.5a3.5 3.5 0 000 7h5a3.5 3.5 0 010 7H6'],
    ['Payroll', 'M16 4h2a2 2 0 012 2v14a2 2 0 01-2 2H6a2 2 0 01-2-2V6a2 2 0 012-2h2M9 2h6v4H9zM9 12h6M9 16h4'],
    ['Staff Permissions', 'M12 2l8 4v6c0 5-3.5 8-8 10-4.5-2-8-5-8-10V6zM9 12l2 2 4-4'],
    ['Multiple Locations', 'M12 22s-8-5.5-8-12a8 8 0 1116 0c0 6.5-8 12-8 12zM12 10a2 2 0 100-4 2 2 0 000 4z'],
    ['Inventory', 'M3 8.5L12 4l9 4.5M3 8.5v7L12 20l9-4.5v-7M3 8.5L12 13l9-4.5M12 13v7'],
    ['Retail Sales', 'M6 2l-3 4v14a2 2 0 002 2h14a2 2 0 002-2V6l-3-4zM3 6h18M16 10a4 4 0 01-8 0'],
    ['Studio Rentals', 'M3 21h18M5 21V7l7-4 7 4v14M9 21v-6h6v6'],
    ['Instructor Payroll', 'M12 2a5 5 0 100 10 5 5 0 000-10zM4 22a8 8 0 0116 0'],
    ['Commission Tracking', 'M3 17l6-6 4 4 8-8M21 7v6h-6'],
    ['Google Calendar Sync', 'M8 2v4M16 2v4M3 10h18M5 4h14a2 2 0 012 2v13a2 2 0 01-2 2H5a2 2 0 01-2-2V6a2 2 0 012-2z'],
    ['Stripe Payments', 'M2 6h20v12H2zM2 10h20'],
    ['Square Payments', 'M4 4h16v16H4zM9 9h6v6H9z'],
    ['Xero Integration', 'M12 3a9 9 0 100 18 9 9 0 000-18zM8 12h8'],
    ['QuickBooks Integration', 'M12 3a9 9 0 100 18 9 9 0 000-18zM12 7v10M9 9.5a3 3 0 013-1.5'],
    ['API Access', 'M8 3H5a2 2 0 00-2 2v3M16 3h3a2 2 0 012 2v3M8 21H5a2 2 0 01-2-2v-3M16 21h3a2 2 0 002-2v-3M9 9l-2 3 2 3M15 9l2 3-2 3'],
    ['Automated Workflows', 'M4 4h6v6H4zM14 14h6v6h-6zM10 7h4a2 2 0 012 2v5']
  ];
  var fg = document.getElementById('featGrid');
  if (fg) fg.innerHTML = features.map(function (f) {
    return '<div class="feat-cell reveal"><span class="fi">' + icon('<path d="' + f[1] + '"/>') + '</span><span>' + f[0] + '</span></div>';
  }).join('');

  /* ---------- Automation ---------- */
  var autos = [
    ['Automatic reminders', 'Class & appointment reminders by email, SMS and push'],
    ['Automatic payments', 'Recurring memberships charged on schedule, hands-free'],
    ['Automatic package deductions', 'Credits drawn down the moment a client checks in'],
    ['Automatic waitlists', 'Open spots promoted to the next member instantly'],
    ['Automatic invoices & receipts', 'Generated and delivered the second a sale completes'],
    ['Automatic payroll calculations', 'Commissions & tiers computed from completed classes'],
    ['Automatic attendance', 'Check-ins recorded and rolled into every report'],
    ['Automatic reports', 'Daily, weekly and monthly summaries in your inbox'],
    ['Automatic reconciliation', 'Payouts matched to payments with zero manual work'],
    ['Automatic onboarding', 'New clients guided from signup to first class']
  ];
  var ag = document.getElementById('autoGrid');
  var boltIcon = icon('<path d="M13 2L3 14h7l-1 8 10-12h-7z"/>');
  if (ag) ag.innerHTML = autos.map(function (a) {
    return '<div class="auto-item reveal"><span class="ai">' + boltIcon + '</span><div><div class="at">' + a[0] + '</div><div class="as">' + a[1] + '</div></div></div>';
  }).join('');

  /* ---------- Integrations ---------- */
  var ints = [
    ['Stripe', '#635BFF', 'S'], ['Square', '#000000', '□'], ['QuickBooks', '#2CA01C', 'qb'],
    ['Xero', '#13B5EA', 'X'], ['Google Calendar', '#4285F4', 'G'], ['Zoom', '#2D8CFF', 'Z'],
    ['Mailchimp', '#FFE01B', '@'], ['Twilio', '#F22F46', 'T'], ['WhatsApp', '#25D366', 'W'],
    ['Zapier', '#FF4A00', 'Z'], ['Meta Pixel', '#0866FF', 'M'], ['Google Analytics', '#E8710A', 'GA']
  ];
  var ig = document.getElementById('intGrid');
  if (ig) ig.innerHTML = ints.map(function (i) {
    var dark = i[1] === '#FFE01B';
    return '<div class="int-cell reveal"><span class="il" style="background:' + i[1] + (dark ? ';color:#16130F' : '') + '">' + i[2] + '</span><span>' + i[0] + '</span></div>';
  }).join('');

  /* ---------- Comparison table ---------- */
  var yes = '<span class="yes">' + icon('<path d="M20 6L9 17l-5-5"/>') + '</span>';
  var no = '<span class="no">' + icon('<path d="M18 6L6 18M6 6l12 12"/>') + '</span>';
  var cmp = [
    ['Unlimited Bookings', 1, 1, 1], ['Unlimited Clients', 1, 1, 1], ['CRM', 1, 1, 1],
    ['Payment Processing', 1, 1, 1], ['Accounting', 0, 1, 1], ['Analytics', 0, 1, 1],
    ['Marketing Automation', 0, 1, 1], ['API Access', 0, 1, 1], ['Priority Support', 0, 1, 1],
    ['White Label', 0, 0, 1], ['Custom Integrations', 0, 0, 1], ['Enterprise Support', 0, 0, 1]
  ];
  var cb = document.getElementById('cmpBody');
  var cell = function (v) { return v ? yes : no; };
  if (cb) cb.innerHTML = cmp.map(function (r) {
    return '<tr><td>' + r[0] + '</td><td class="ctr">' + cell(r[1]) + '</td><td class="ctr colpop">' + cell(r[2]) + '</td><td class="ctr">' + cell(r[3]) + '</td></tr>';
  }).join('');

  /* ---------- FAQ ---------- */
  var faqs = [
    ['Can I migrate from another booking system?', 'Yes. Our team handles full migration of your clients, memberships, packages and historical data from Mindbody, Momence, WellnessLiving and most other systems — usually within a few days and at no extra cost on annual plans.'],
    ['How does the free trial work?', 'You get full access to every feature for 14 days. No credit card required to start. If you love it, pick a plan; if not, your account simply pauses — nothing is charged automatically.'],
    ['Can I cancel anytime?', 'Absolutely. Nexis is month-to-month with no lock-in contracts. Cancel from your dashboard whenever you like and keep access until the end of your billing period.'],
    ['Which payment gateways are supported?', 'Stripe and Square are built in for card payments, and we support cash and bank transfers at the point of sale. Payouts reconcile automatically into your accounting.'],
    ['Can I manage multiple studios?', 'Yes. The Enterprise plan gives you one dashboard for unlimited locations, with cross-location memberships, shared instructors and central reporting.'],
    ['Do clients need to download an app?', 'No. Your clients book, buy and check in from any mobile browser — no app store, no downloads. It feels like a native app but works instantly from a link.']
  ];
  var fl = document.getElementById('faqList');
  if (fl) {
    fl.innerHTML = faqs.map(function (f) {
      return '<div class="faq-item reveal"><button class="faq-q">' + f[0] + '<span class="pm">+</span></button><div class="faq-a"><p>' + f[1] + '</p></div></div>';
    }).join('');
    fl.querySelectorAll('.faq-q').forEach(function (q) {
      q.addEventListener('click', function () {
        var item = q.parentElement;
        var a = item.querySelector('.faq-a');
        var open = item.classList.toggle('open');
        a.style.maxHeight = open ? a.scrollHeight + 'px' : '0';
      });
    });
  }

  /* Observe reveals now that dynamic content exists */
  observeReveals();

  /* Subtle parallax on hero floats */
  var floats = document.querySelectorAll('.hero-stage .float');
  if (window.matchMedia('(min-width: 981px)').matches) {
    window.addEventListener('scroll', function () {
      var y = window.scrollY;
      floats.forEach(function (f, i) { f.style.transform = 'translateY(' + (y * (0.02 + i * 0.012)) + 'px)'; });
    }, { passive: true });
  }
})();

