#!/usr/bin/env python3
"""Synthesize historical CalendarSessions + linked Attendances from classes.csv.
Group/Mat: grouped by (date, instructor, class name) -> one session, real occupancy.
Private: 1-seat sessions. Duo: 2-seat sessions. Times are synthetic (hourly slots
per instructor/day). Dry-run prints counts; --commit writes NDJSON only (import done by caller)."""
import csv, os, re, json, hashlib, datetime as dt
from collections import defaultdict

INC = "/opt/soulpilates/_incoming"
OUT = "/tmp/claude-0/-root/f1b1af7e-43da-44b8-92b2-51e4d240617b/scratchpad/ndjson2"
os.makedirs(OUT, exist_ok=True)

def oid(kind, key): return hashlib.md5(f"{kind}:{key}".encode()).hexdigest()[:24]
_c=[0]
def new_oid():
    _c[0]+=1
    return (f"{int(dt.datetime.now().timestamp()):08x}"+f"{_c[0]:016x}")[:24]
def OID(s): return {"$oid": s}
def DATE(d): return {"$date": d.strftime("%Y-%m-%dT%H:%M:%SZ")} if d else None
def D(v): return {"$numberDecimal": str(v)}
def money(s):
    s=re.sub(r"[₫$,()\s]","",str(s or ""));
    try: return int(float(s)) if s else 0
    except: return 0
def parse_mdy(s):
    s=(s or "").strip()
    for f in ("%m-%d-%Y","%m/%d/%Y"):
        try: return dt.datetime.strptime(s,f)
        except: pass
    return None
def rows(fn):
    with open(os.path.join(INC,fn),newline="",encoding="utf-8-sig") as f:
        for r in csv.DictReader(f): yield r

# deterministic maps matching import_data.py
def staff_lookup(name):
    n=(name or "").strip().lower()
    if n.startswith("nhi"): n="nhi"
    if n in ("nhi","linna","santino","tuan","phong","linh"): return oid("staff",n), name.strip()
    return None, name
client_id={}
for r in rows("clients.csv"):
    cid=(r.get("Client ID") or "").strip()
    if cid: client_id[cid]=oid("client",cid)
# rebuild package ids from packages.csv (regular packages referenced by classes)
pkg_id={}
for r in rows("packages.csv"):
    pid=(r.get("Package ID") or "").strip(); cid=(r.get("Client ID") or "").strip()
    if pid and cid: pkg_id[pid]=oid("pkg",pid+"_"+cid+"_"+(r.get("Receipt ID") or ""))

DROPIN={"GROUP":250000,"MAT":250000,"PRIVATE":850000,"DUO":425000}
CAP={"GROUP":10,"MAT":12,"PRIVATE":1,"DUO":2}

# collect class rows grouped for session synthesis
group_rows=defaultdict(list)   # (date,instr,classname,fmt) -> [rows]  for GROUP/MAT/DUO
private_rows=[]                 # each -> own session
all_rows=0
for r in rows("classes.csv"):
    cid=(r.get("Client ID") or "").strip(); prod=(r.get("Product") or "").strip()
    if not cid or cid not in client_id or not prod: continue
    date=parse_mdy(r.get("Date"))
    if not date: continue
    fmt_raw=(r.get("Class Format") or "GROUP").strip().upper()
    fmt = "PRIVATE" if "PRIV" in fmt_raw else ("DUO" if "DUO" in fmt_raw else ("MAT" if "MAT" in fmt_raw else "GROUP"))
    instr=(r.get("Instructor") or "").strip()
    cname=(r.get("Class Name") or r.get("Product") or "Class").strip() or "Class"
    all_rows+=1
    rec=dict(r); rec["_fmt"]=fmt; rec["_date"]=date; rec["_instr"]=instr; rec["_cname"]=cname
    if fmt=="PRIVATE": private_rows.append(rec)
    else: group_rows[(date.date(),instr,cname,fmt)].append(rec)

sessions=[]; attendances=[]
slot_counter=defaultdict(int)  # (date,instr) -> next hour slot index
def next_time(date,instr):
    idx=slot_counter[(date.date(),instr)]; slot_counter[(date.date(),instr)]+=1
    return date.replace(hour=min(8+idx,20),minute=0,second=0,microsecond=0)

def make_session(date,instr,cname,fmt,attn_rows):
    sid_staff,iname=staff_lookup(instr)
    st=next_time(date,instr); et=st+dt.timedelta(minutes=55)
    sess_oid=oid("sess", f"{date.date()}|{instr}|{cname}|{fmt}|{st.hour}")
    cap=CAP.get(fmt,10)
    n=len(attn_rows)
    if fmt in ("PRIVATE","DUO") and n>cap: cap=n
    sessions.append({
        "_id":OID(sess_oid),"InstructorId":OID(sid_staff) if sid_staff else None,
        "InstructorName":iname,"StartTime":DATE(st),"EndTime":DATE(et),
        "Capacity":cap,"CurrentBookings":n,"Status":"COMPLETED","Format":fmt,
        "ClassName":cname,"Origin":"IMPORTED","IsFreelance":False,
