namespace SoulPilates.Core.Entities;

/// <summary>
/// One rung of a tiered commission ladder. A staff member's <see cref="Staff.Tiers"/>
/// list is searched by class-count to pick the rung whose <c>[MinClasses, MaxClasses]</c>
/// range covers the count for the period; the rung's <c>CommissionPercentage</c>
/// is then applied to that period's revenue.
///
/// <para>
/// Extracted from the legacy <c>InstructorContract</c> entity in P2-S09 so it has
/// its own home; both the entity and a few service contracts reference it.
/// </para>
/// </summary>
public class CommissionTier
{
    /// <summary>Inclusive lower bound on class count for this rung to apply.</summary>
    public int MinClasses { get; set; }

    /// <summary>Inclusive upper bound; <c>null</c> means "no upper bound" (top rung).</summary>
    public int? MaxClasses { get; set; }

    /// <summary>Commission rate (e.g. <c>0.20m</c> for 20%) for class counts in this rung.</summary>
    public decimal CommissionPercentage { get; set; }
}

