using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;
using SoulPilates.Core.Entities;
using System;
using System.Collections.Generic;

namespace SoulPilates.Core.Entities;

/// <summary>
/// Persistent, per-(period) record of a payroll calculation. Inserted by
/// <see cref="SoulPilates.Services.PayrollService.CalculatePayrollAsync"/> at the
/// end of every monthly run; the financial pipeline downstream
/// (<c>AccountingService.ComputeMonthlyWashoutAsync</c>) reads from this
/// collection so washouts are computed against a frozen labour total rather
/// than re-derived live.
///
/// <para>
/// Each call to <c>CalculatePayrollAsync</c> for a given <c>(PeriodStart, PeriodEnd)</c>
/// upserts a single row — there can never be two rows for the same period.
/// Older versions of this service inserted unconditionally; that allowed two
/// payroll runs in the same month to double-count labour cost downstream.
/// The unique index <c>ux_period</c> in the service constructor enforces this
/// at the database level.
/// </para>
/// </summary>
public class PayrollRun : BaseEntity
{
    public DateTime PeriodStart { get; set; }
    public DateTime PeriodEnd { get; set; }

    public decimal TotalPayroll { get; set; }
    public DateTime RunDate { get; set; } = DateTime.UtcNow;

    public List<InstructorPayrollResult> Results { get; set; } = new();
}

/// <summary>
/// Per-instructor slice of a <see cref="PayrollRun"/>. Stores both the
/// computed totals and a <b>complete snapshot of the rate sheet that produced
/// them</b> via <see cref="RateRevisionId"/> and the inline snapshot fields.
///
/// <para>
/// Why snapshot redundantly? Three reasons:
/// </para>
/// <list type="number">
///   <item><b>Idempotency.</b> A re-run of January after a rate edit in April
///   resolves the in-force April-as-of-Jan revision via
///   <c>StaffRateRevisionService.ResolveAsOfAsync</c>; the snapshot block lets
///   that resolution be audited without re-querying.</item>
///   <item><b>Defence in depth.</b> If <see cref="StaffRateRevision"/> data is
///   ever corrupted or migrated incorrectly, the inline snapshot on
///   <c>PayrollRun</c> still answers "what was Nhi paid under, in January?".</item>
///   <item><b>Display.</b> The admin payroll detail screen renders the rate
///   ladder in-place; reading it from one document is faster than joining.</item>
/// </list>
/// </summary>
public class InstructorPayrollResult
{
    [BsonRepresentation(BsonType.ObjectId)]
    public string InstructorId { get; set; } = null!;

    /// <summary>
    /// Denormalised at write time so a renamed staff member doesn't shift the
    /// historical payroll listing. Same pattern as <c>Attendance.ClientName</c>.
    /// </summary>
    public string InstructorNameSnapshot { get; set; } = string.Empty;

    /// <summary>
    /// Foreign key into <see cref="StaffRateRevision"/> — the rate sheet that
    /// was in force at <c>PayrollRun.PeriodEnd</c>. Nullable for the rare case
    /// where no revision was resolvable at all (the instructor has been deleted
    /// since the last run AND no historical revision was minted); the inline
    /// snapshot below still records the values used.
    /// </summary>
    [BsonRepresentation(BsonType.ObjectId)]
    public string? RateRevisionId { get; set; }

    // ── Inline snapshot of every rate-affecting field at the moment of calc ──

    public string CommissionModelSnapshot { get; set; } = "";
    public decimal BaseSalarySnapshot { get; set; }
    public decimal GroupFlatRatePerClassSnapshot { get; set; }
    public decimal GroupRatePerHeadSnapshot { get; set; }
    public decimal RatePerHeadSnapshot { get; set; }
    public decimal PrivateRatePerHeadSnapshot { get; set; }
    public bool HasTieredPrivateCommissionSnapshot { get; set; }
    public decimal FlatPrivateCommissionPctSnapshot { get; set; }
    public bool UseMarginalHeadcountTiersSnapshot { get; set; }

    public List<CommissionTier> TiersSnapshot { get; set; } = new();
    public List<HeadcountPayoutTier> HeadcountTiersSnapshot { get; set; } = new();
    public List<HeadcountPayoutTier> PrivateHeadcountTiersSnapshot { get; set; } = new();

    // ── Computed totals ─────────────────────────────────────────────────────

    public decimal BaseSalaryAmount { get; set; }

    public int TotalGroupClasses { get; set; }
    public decimal GroupClassEarnings { get; set; }

    public int TotalPrivateClasses { get; set; }
    public decimal PrivateClassEarnings { get; set; }

    public decimal TotalPay { get; set; }
}

