    // Group by instructor up-front so we make at most one Staff lookup per person.
    foreach (var group in sessions.GroupBy(s => s.InstructorId))
    {
        var instructorId = group.Key;
        if (string.IsNullOrEmpty(instructorId)) continue;

        var staff = await _staff.Find(s => s.Id == instructorId).FirstOrDefaultAsync();
        if (staff is null) continue;

        // Resolve the in-force rate revision for the period END. Using End
        // (not Start) matches what a payroll clerk expects — "pay people
        // under whatever rate was in effect when the month closed". The
        // revision service lazily bootstraps a baseline if there is no
        // revision yet (legacy staff rows), so the result is never null
        // for an existing staff member.
        var revision = await _revisions.ResolveAsOfAsync(staff.Id!, end);

        // Monthly commission override takes precedence over the revision.
        revision = await ApplyCommissionOverrideAsync(staff.Id!, end, revision);

        var result = await AggregateInstructorAsync(staff, revision, group.ToList());
        run.Results.Add(result);
    }

    run.TotalPayroll = run.Results.Sum(r => r.TotalPay);

    if (existing is null)
    {
        await _payrollRuns.InsertOneAsync(run);
    }
    else
    {
        await _payrollRuns.ReplaceOneAsync(p => p.Id == existing.Id, run);
    }

    return run;
}

