/// <summary>Full class detail including attendee roster and instructor commission snapshot.</summary>
[HttpGet("class/{sessionId}")]
[Authorize(Roles = "Admin,Receptionist,Accountant")]
public async Task<IActionResult> GetClassDetail(string sessionId)
{
    var detail = await _schedulingService.GetClassDetailAsync(sessionId);
    if (detail is null) return NotFound(new { message = "Class session not found." });
    return Ok(detail);
}

/// <summary>CSV export of bookings matching the same filters.</summary>
[HttpGet("bookings/export/csv")]
[Authorize(Roles = "Admin,Receptionist,Accountant")]
public async Task<IActionResult> ExportBookingsCsv([FromQuery] BookingListQuery query)
{
    query.Limit = 10000;
    query.Page = 1;
    var result = await _schedulingService.ListBookingsAsync(query);
    var sb = new System.Text.StringBuilder();
    sb.AppendLine("BookingRef,Client,Class,Instructor,BookedAt,SessionDate,Status,PaymentMethod,PaymentStatus,AmountPaid,AmountDue,Source");
    foreach (var b in result.Items)
    {
        sb.AppendLine($"\"{b.BookingReference}\",\"{b.ClientName}\",\"{b.ClassName}\",\"{b.InstructorName}\",{b.BookedAt:yyyy-MM-dd},{b.SessionStartTime:yyyy-MM-dd HH:mm},{b.Status},{b.PaymentMethod ?? ""},{b.PaymentStatus},{b.AmountPaid},{b.AmountDueAtStudio},{b.BookingSource}");
    }
    return File(System.Text.Encoding.UTF8.GetBytes(sb.ToString()), "text/csv", $"bookings-{DateTime.UtcNow:yyyyMMdd}.csv");
}

[HttpGet]
[AllowAnonymous]
public async Task<IActionResult> Get([FromQuery] DateTime start, [FromQuery] DateTime end)
{
    var sessions = await _schedulingService.GetSessionsAsync(start, end);

    // SPM-91 — unauthenticated callers must not see private sessions. Mirror
    // GetPublicScheduleAsync's keep-legacy/missing-true semantics: exclude only
    // sessions explicitly marked IsPublic == false. Authenticated staff (admin
    // calendar) still receive private sessions.
    if (User.Identity?.IsAuthenticated != true)
    {
        sessions = sessions.Where(s => s.IsPublic);
    }

    return Ok(sessions);
}

[HttpPost("session")]
[Authorize(Roles = "Admin,Receptionist")]
public async Task<IActionResult> CreateSession([FromBody] CalendarSession session)
{
    var created = await _schedulingService.CreateSessionAsync(session);
    return Ok(created);
}

[HttpPost("book")]
[Authorize]
public async Task<IActionResult> Book([FromQuery] string sessionId, [FromQuery] string clientId)
{
    bool authSuccess = await _walletService.DeductCreditAsync(clientId, "GROUP", "temp_booking");
    if (!authSuccess) return BadRequest(new { message = "Insufficient active credits for this format." });

    try {
        var attendance = await _schedulingService.BookClientAsync(sessionId, clientId, null);
        return Ok(attendance);
    } catch (Exception ex) {
        return BadRequest(new { message = ex.Message });
    }
}

[HttpPut("check-in/{attendanceId}")]
[Authorize(Roles = "Admin,Receptionist,Instructor")]
public async Task<IActionResult> CheckIn(string attendanceId)
{
    var success = await _schedulingService.CheckInClientAsync(attendanceId);
    if (!success) return NotFound();
    return Ok(new { message = "Checked in inside the studio successfully!" });
}

[HttpGet("session/{sessionId}/bookings")]
[Authorize(Roles = "Admin,Receptionist,Instructor")]
public async Task<IActionResult> GetSessionBookings(string sessionId)
{
    var bookings = await _schedulingService.GetBookingsForSessionAsync(sessionId);
    return Ok(bookings);
}

