// Commission snapshot — load the instructor's current rate sheet
ClassCommissionSnapshotDto? commissionSnapshot = null;
if (!string.IsNullOrWhiteSpace(session.InstructorId))
{
    var instructor = await _staff.Find(s => s.Id == session.InstructorId).FirstOrDefaultAsync();
    if (instructor is not null)
    {
        var isPrivate = session.Capacity == 1 || session.Format == "PRIVATE";
        var countingAttendees = attendances.Count(a =>
            a.CountsTowardsCommission &&
            (a.Status == "CHECKED_IN" || a.Status == "BOOKED" || a.Status == "ARRIVED"));

        decimal flatRate = 0m, perHeadBonus = 0m, total = 0m;
        decimal classRevenue = 0m, commissionRate = 0m, commissionEarned = 0m;
        int monthClassCount = 0;

        if (instructor.CommissionModel == "FIXED_HEADCOUNT")
        {
            // SPM-115 — head-count payout. Resolve the same way payroll does
            // (PayrollService.AggregateInstructorAsync → ResolveHeadcountPayout):
            // the ladder is per SEAT, so a group booking of N seats
            // (att.Quantity == N) counts as N students. Only attendees that
            // arrived AND count towards commission feed the ladder. We reuse
            // the public live-Staff resolver so the ladder math is not
            // duplicated here.
            var seatHeadcount = attendances
                .Where(a => a.CountsTowardsCommission &&
                            (a.Status == "CHECKED_IN" || a.Status == "ARRIVED") &&
                            paidAttendanceIds.Contains(a.Id!)) // SPM-113: paid arrivals only
                .Sum(a => Math.Max(1, a.Quantity));

            // flatRate / perHeadBonus stay 0 for this model — the entire
            // payout comes from the head-count ladder.
            total = PayrollService.ResolveHeadcountPayout(instructor, seatHeadcount, isPrivate);
        }
        else if (instructor.CommissionModel == "PERCENTAGE_TIERED")
        {
            // Count how many classes this instructor has with ≥1 arrived attendee
            // in the same month, up to and including this class.
            var monthStart = new DateTime(session.StartTime.Year, session.StartTime.Month, 1, 0, 0, 0, DateTimeKind.Utc);
            var monthEnd = monthStart.AddMonths(1).AddTicks(-1);

            var monthSessions = await _sessions.Find(s =>
                s.InstructorId == session.InstructorId
                && s.StartTime >= monthStart
                && s.StartTime <= session.StartTime // up to and including this class
                && s.Status != "CANCELLED"
                && s.Status != "BLOCKED"
                && s.Origin != "BLOCK"
            ).ToListAsync();

            // SPM-113 — a month-session only advances the tier count if it has
            // >=1 PAID attendee (matches PayrollService's paid rule). Cheap
            // in-memory paid check on attendance fields only — no per-session
            // invoice query, so the class-detail load stays light.
            static bool CountsAsPaid(Attendance a) =>
                a.PaymentMethod == "PACKAGE_CREDIT"
                || a.IsFreeClass
                || (a.AmountPaid ?? 0m) > 0m
                || (a.AmountDueAtStudio ?? 0m) <= 0m;

            foreach (var ms in monthSessions)
            {
                var msAttendances = await _attendances
                    .Find(a => a.CalendarSessionId == ms.Id
                            && (a.Status == "CHECKED_IN" || a.Status == "ARRIVED" || a.Status == "BOOKED"))
                    .ToListAsync();
                if (msAttendances.Any(CountsAsPaid)) monthClassCount++;
            }

            // Resolve the tier for this class count
            commissionRate = PayrollService.ResolvePrivateCommissionRate(instructor, monthClassCount);

            // Compute revenue for this specific class from arrived/checked-in attendees
            var arrivedForRevenue = attendances.Where(a =>
                a.CountsTowardsCommission &&
                (a.Status == "CHECKED_IN" || a.Status == "ARRIVED")).ToList();

            foreach (var att in arrivedForRevenue)
            {
                var qty = Math.Max(1, att.Quantity);

                // Package-credit bookings: the invoice shows ₫0 because the client
                // pre-paid via their package. For commission, use the session's
                // drop-in price × quantity as the revenue base.
                decimal revBase = (session.DropInPrice ?? 0m) * qty;

                if (att.PaymentMethod != "PACKAGE_CREDIT")
                {
                    // Look up invoice for monetary-payment attendees
                    var linkedInv = await _invoices.Find(
                        Builders<Invoice>.Filter.ElemMatch(
                            i => i.Lines,
                            Builders<InvoiceLine>.Filter.Eq(l => l.AttendanceId, att.Id)
                        )
                    ).FirstOrDefaultAsync();

                    if (linkedInv is not null && linkedInv.Status == "PAID")
                    {
                        var line = linkedInv.Lines.FirstOrDefault(l => l.AttendanceId == att.Id);
                        if (line is not null)
                        {
                            var lineTotal = line.UnitPrice * line.Quantity - line.LineDiscount;
                            if (lineTotal > 0m) revBase = lineTotal;
                        }
                        else if (linkedInv.TotalNet > 0m)
                        {
                            revBase = linkedInv.TotalNet;
                        }
                    }
                    else if ((att.AmountPaid ?? 0m) > 0m)
                    {
                        revBase = att.AmountPaid ?? 0m;
                    }
                }

                // Apply referral discount
                var discountPct = att.ReferralDiscountPct.HasValue
                    ? Math.Clamp(att.ReferralDiscountPct.Value, 0m, 1m)
                    : 0m;
                classRevenue += revBase * (1m - discountPct);
            }

            commissionEarned = classRevenue * commissionRate;
            total = commissionEarned;
        }
        else if (!isPrivate)
        {
            // Non-tiered group class: flat rate + per-head
            flatRate = instructor.GroupFlatRatePerClass;
            perHeadBonus = instructor.GroupRatePerHead * countingAttendees;
            total = flatRate + perHeadBonus;
        }
        // Note: private commission for non-tiered requires knowing cumulative monthly revenue
        // which is payroll-run territory — we only show group/tiered commission inline here.

        commissionSnapshot = new ClassCommissionSnapshotDto
        {
            InstructorId = instructor.Id!,
            InstructorName = instructor.Name,
            CommissionModel = instructor.CommissionModel,
            FlatRateEarned = flatRate,
            PerHeadEarned = perHeadBonus,
            TotalEstimated = total,
            AttendeeCount = countingAttendees,
            IsEstimate = session.Status != "COMPLETED",
            ClassRevenue = classRevenue,
            CommissionRate = commissionRate,
            MonthClassCount = monthClassCount,
            CommissionEarned = commissionEarned,

