        class_rev=round(base_total/ncls) if ncls else base_total
        attendances.append({
            "_id":OID(new_oid()),"CalendarSessionId":OID(sess_oid),"ClientId":OID(client_id[cid]),
            "ClientName":(r.get("Client Name") or "").strip() or None,
            "PackageInstanceId":OID(pk) if pk else None,
            "Status":"CHECKED_IN","IsFreeClass":free,"CountsTowardsCommission":counts,
            "PaymentMethod":"PACKAGE_CREDIT" if pk else None,"Quantity":int(money(r.get("Quantity") or 1)) or 1,
            # Verbatim commission from the studio spreadsheet — payroll uses this
            # exact amount for imported classes instead of recomputing.
            "ImportedCommissionAmount":D(comm),
            "BookedAt":DATE(r["_date"]),"BookingSource":"ADMIN",
            "BookingReference":"IMP-"+(r.get("Class ID") or new_oid()[:8]),"CreatedAt":DATE(r["_date"]),
        })

for (d,instr,cname,fmt),rs in group_rows.items():
