    var revision = await _revisions.ResolveAsOfAsync(staff.Id!, end);

    // Monthly commission override takes precedence over the revision.
    revision = await ApplyCommissionOverrideAsync(staff.Id!, end, revision);

    var result = await AggregateInstructorAsync(staff, revision, group.ToList());
    run.Results.Add(result);
}

// ── Revenue-split commission pass ───────────────────────────────
// Some staff (e.g. an owner-operator) earn a % of the studio's TOTAL
// monthly revenue rather than per-class commission. The rate can be
// tiered on that revenue (e.g. 4% under 100M, 5% at/over). These people
// may not teach at all, so they won't appear in the session loop above —
// process them here from the month's paid revenue.
var revenueSplitStaff = await _staff
    .Find(s => s.CommissionModel == "REVENUE_SPLIT")
    .ToListAsync();
if (revenueSplitStaff.Count > 0)
{
    var monthlyRevenue = (await _invoices
        .Find(i => i.IssueDate >= start && i.IssueDate <= end && i.Status == "PAID")
        .ToListAsync()).Sum(i => i.TotalNet);

    foreach (var staff in revenueSplitStaff)
    {
        decimal pct;
        if (staff.RevenueCommissionTiers is { Count: > 0 } rtiers)
        {
            var rung = rtiers
                .Where(t => monthlyRevenue >= t.MinRevenue
                         && (t.MaxRevenue == null || monthlyRevenue < t.MaxRevenue.Value))
                .OrderByDescending(t => t.MinRevenue)
                .FirstOrDefault()
                ?? rtiers.OrderByDescending(t => t.MinRevenue).First();
            pct = NormalizeCommissionPct(rung.Percentage);
        }
        else
        {
            pct = NormalizeCommissionPct(staff.BaseRate);
        }

        var commission = monthlyRevenue * pct;
        if (commission <= 0m) continue;

        var existingResult = run.Results.FirstOrDefault(r => r.InstructorId == staff.Id);
        if (existingResult != null)
        {
            existingResult.RevenueCommissionEarnings += commission;
            existingResult.TotalPay += commission;
        }
        else
        {
            var rev = await _revisions.ResolveAsOfAsync(staff.Id!, end);
            rev = await ApplyCommissionOverrideAsync(staff.Id!, end, rev);
            var r = await AggregateInstructorAsync(staff, rev, new List<CalendarSession>());
            r.RevenueCommissionEarnings = commission;
            r.TotalPay += commission;
            run.Results.Add(r);
        }
    }
}

run.TotalPayroll = run.Results.Sum(r => r.TotalPay);

if (existing is null)
{
    await _payrollRuns.InsertOneAsync(run);
}
else
{
    await _payrollRuns.ReplaceOneAsync(p => p.Id == existing.Id, run);
}

return run;

