public class Expense : BaseEntity
{
    public string Category { get; set; } = null!; // Free-form string per P1-S04 (admin-editable list).
    public string Description { get; set; } = null!;
    public decimal Amount { get; set; }
    public DateTime DateIncurred { get; set; } = DateTime.UtcNow;

    public string Type { get; set; } = "OPEX"; // "OPEX", "CAPEX", "COGS"
    public string PaidBy { get; set; } = "COMPANY"; // "COMPANY", "STAFF"
    public string? StaffName { get; set; } // Only when PaidBy == "STAFF" (needs reimbursement)

    public string? ReceiptUrl { get; set; }
    public string EnteredByUserId { get; set; } = null!;

    // ---------------------------------------------------------------------
    // P1-S05 — Recurring & outstanding fields (SOW §12.2)
    // ---------------------------------------------------------------------

    /// <summary>
    /// How often this expense recurs. Acts as a hint for future automation and
    /// for the receptionist when she's reviewing the log; the platform doesn't
    /// auto-create monthly rows yet (filed for a future slice).
    /// One of <c>"MONTHLY"</c>, <c>"YEARLY"</c>, <c>"ONE_TIME"</c>.
    /// </summary>
    public string Frequency { get; set; } = "ONE_TIME";

    /// <summary>
    /// Has the expense actually been paid yet? Distinct from <see cref="Type"/>;
    /// an OpEx can be `NOT_PAID` (e.g. an invoice the studio owes but hasn't settled).
    /// One of <c>"PAID"</c>, <c>"NOT_PAID"</c>.
    /// </summary>
    public string PaidStatus { get; set; } = "PAID";

    /// <summary>
    /// Amount still owed when <see cref="PaidStatus"/> is <c>NOT_PAID</c> (or
    /// for partial payments). Default 0 means "fully paid". The expense list
    /// footer sums this column over the filtered rows.
    /// </summary>
    public decimal OutstandingAmount { get; set; } = 0;

    /// <summary>How the expense was/will-be settled.
    /// One of <c>"CASH"</c>, <c>"CARD"</c>, <c>"BANK_TRANSFER"</c>, <c>"OTHER"</c>.</summary>
    public string PaymentMethod { get; set; } = "CASH";

    /// <summary>Optional vendor / supplier name, free-form.</summary>
    public string? VendorName { get; set; }

    // ---------------------------------------------------------------------
    // Fund Pool source tracking
    // ---------------------------------------------------------------------

    /// <summary>
    /// Which financial pool this expense draws from.
    /// <c>"OPERATIONS"</c> (default) = standard operating expense, counted in
    /// the month's <c>TotalFixedExpenses</c> for washout. <c>"MARKETING"</c> /
    /// <c>"SAVINGS"</c> = drawn from the named reserve pool and NOT counted in
    /// the month's FixedExpenses (the cost comes out of the cumulative pool
    /// balance instead). Legacy rows with null/empty values are treated as
    /// <c>"OPERATIONS"</c> for backward compatibility.
    /// </summary>
    public string FundSource { get; set; } = "OPERATIONS";

    // ---------------------------------------------------------------------
    // P2-S05 — Reimbursement settlement (SOW §13.5)
    // ---------------------------------------------------------------------

    /// <summary>
    /// True when this <c>PaidBy="STAFF"</c> expense has been folded into a
    /// monthly distribution (owner) or staff payable (non-owner). Always false
    /// for <c>PaidBy="COMPANY"</c> expenses — there's nothing to reimburse.
    /// </summary>
    public bool ReimbursementSettled { get; set; } = false;

    /// <summary>The wall-clock time the admin clicked "Settle".</summary>
    public DateTime? SettledOn { get; set; }

    /// <summary>The <c>(Year, Month)</c> washout into which this expense was
    /// folded. Drives the third pass in <c>AccountingService.ComputeMonthlyWashoutAsync</c>.</summary>
    public int? SettledForYear { get; set; }
    public int? SettledForMonth { get; set; }

    /// <summary>The <c>_id</c> of the <c>ReimbursementSettleBatch</c> row that
    /// recorded this settlement — audit-trail link, never user-facing.</summary>
    public string? SettledInBatchId { get; set; }

    /// <summary>
    /// Snapshot of the recipient's payout-channel at settle time (P5 financial-
    /// integrity). Either <c>"OWNER"</c> (folded into <see cref="OwnerDistribution.ReimbursementAmount"/>)
    /// or <c>"STAFF"</c> (folded into <see cref="StaffPayable.ReimbursementAmount"/>).
    ///
    /// <para>
    /// Locked at settle-time so that flipping a staff member's owner status
    /// later (or rotating an owner off the active roster) cannot retroactively
    /// reshuffle a historical reimbursement between the two pools. Null on
    /// expenses settled before this field existed; the washout reader falls
    /// back to the live owner roster in that case.
    /// </para>
    /// </summary>
    public string? SettledAsRecipientType { get; set; }

    /// <summary>
    /// When <see cref="SettledAsRecipientType"/> is <c>OWNER</c>, the
    /// <c>OwnerProfile.StaffId</c> that received the reimbursement. Used so the
    /// washout reader can target the correct distribution row without having
    /// to fuzzy-match by staff name (and without risking that a rename
    /// reshuffles the routing).
    /// </summary>
    public string? SettledAsOwnerStaffId { get; set; }
}

