[HttpPost("expense")]
public async Task<IActionResult> LogExpense([FromBody] Expense expense)
{
    try
    {
        var result = await _accountingService.LogExpenseAsync(expense);
        return Ok(result);
    }
    catch (LockedWashoutException ex)
    {
        // P5 financial-integrity: the month the expense lives in is locked.
        return Conflict(new { message = ex.Message, year = ex.Year, month = ex.Month });
    }
}

