/// <summary>
/// Every active staff member with their salary for the given month, read from
/// the salary-tagged expense (SalaryForStaffId). Drives the Monthly Salaries
/// editor. Staff with no salary set for the month come back with Amount 0.
/// </summary>
public async Task<IReadOnlyList<MonthlySalaryRow>> GetMonthlySalariesAsync(int year, int month)
{
    var start = new DateTime(year, month, 1, 0, 0, 0, DateTimeKind.Utc);
    var end = start.AddMonths(1).AddTicks(-1);

    var staff = await _staffCollection.Find(s => s.IsActive).ToListAsync();
    var salaryExpenses = await _expenses
        .Find(e => e.SalaryForStaffId != null
                && e.DateIncurred >= start && e.DateIncurred <= end)
        .ToListAsync();
    var byStaff = salaryExpenses
        .GroupBy(e => e.SalaryForStaffId!)
        .ToDictionary(g => g.Key, g => g.Sum(e => e.Amount));

    return staff
        .OrderBy(s => s.Name)
        .Select(s => new MonthlySalaryRow
        {
            StaffId = s.Id!,
            StaffName = s.Name,
            Role = s.Role,
            Amount = byStaff.TryGetValue(s.Id!, out var amt) ? amt : 0m,
        })
        .ToList();
}

/// <summary>
/// Set a staff member's salary for a month. Replaces any prior salary line
/// for that staff+month; a zero amount clears it. Stored as a salary-tagged
/// OPEX expense so it flows into the washout like any other cost.
/// </summary>
public async Task SetMonthlySalaryAsync(string staffId, int year, int month, decimal amount)
{
    var start = new DateTime(year, month, 1, 0, 0, 0, DateTimeKind.Utc);
    var end = start.AddMonths(1).AddTicks(-1);

    await _expenses.DeleteManyAsync(e => e.SalaryForStaffId == staffId
        && e.DateIncurred >= start && e.DateIncurred <= end);

    if (amount <= 0m) return;

    var staff = await _staffCollection.Find(s => s.Id == staffId).FirstOrDefaultAsync();
    var name = staff?.Name ?? "Staff";
    var category = staff?.Role == "OWNER" ? "Management Salary" : "Staff Salaries";

    await _expenses.InsertOneAsync(new Expense
    {
        Category = category,
        Description = $"Salary — {name} — {year}-{month:D2}",
        Amount = amount,
        DateIncurred = new DateTime(year, month, 15, 0, 0, 0, DateTimeKind.Utc),
        Type = "OPEX",
        PaidBy = "COMPANY",
        EnteredByUserId = "salary-editor",
        Frequency = "MONTHLY",
        PaidStatus = "PAID",
        PaymentMethod = "BANK_TRANSFER",
        FundSource = "OPERATIONS",
        StaffName = name,
        SalaryForStaffId = staffId,
        CreatedAt = DateTime.UtcNow,
    });
}

