/// <summary>
/// Removes the base-salary portion of a payroll result when the staff
/// member's salary hadn't started yet for this period (period end is before
/// <see cref="Staff.SalaryEffectiveFrom"/>). Commission earned before the
/// salary start still stands — only the salary is gated.
/// </summary>
private static void ApplySalaryStartGate(InstructorPayrollResult result, Staff staff, DateTime periodEnd)
{
    if (staff.SalaryEffectiveFrom.HasValue
        && periodEnd < staff.SalaryEffectiveFrom.Value
        && result.BaseSalaryAmount != 0m)
    {
        result.TotalPay -= result.BaseSalaryAmount;
        result.BaseSalaryAmount = 0m;
        result.BaseSalarySnapshot = 0m;
    }
}

