const API = import.meta.env.PUBLIC_API_URL;
const token = localStorage.getItem("token");
if (!token) window.location.href = '/login';

// ══════════════════════════════════════════════════════════════════
//  GLOBAL STATE
// ══════════════════════════════════════════════════════════════════
const now = new Date();
let selectedYear = now.getFullYear();
let selectedMonth = now.getMonth() + 1;
let expenseType = "OPEX", payBy = "COMPANY", fundSource = "OPERATIONS";
let poolBalances = null;
let allExpenses = [];
let gridCache = null;
let currentMonths = 12;
let activeTab = 'expenses';

// ── Global month picker ────────────────────────────────────────
const globalPicker = document.getElementById('globalMonthPicker');
globalPicker.value = `${selectedYear}-${String(selectedMonth).padStart(2, '0')}`;
globalPicker.addEventListener('change', () => {
  const [y, m] = globalPicker.value.split('-').map(Number);
  selectedYear = y;
  selectedMonth = m;
  onMonthChange();
});

function onMonthChange() {
  const label = new Date(selectedYear, selectedMonth - 1).toLocaleDateString("en-US", { month: "long", year: "numeric" });
  document.getElementById("expenseMonthLabel").textContent = label;
  document.getElementById("bonusMonthLabel").textContent = label;
  // Reload active tab's data
  loadExpenses();
  loadBonuses();
  loadReimbursementsSummary();
  // Reset washout result display
  document.getElementById("washoutResult").style.display = "none";
  document.getElementById("washoutEmpty").style.display = "";
  // Invalidate P&L grid cache and reload if on that tab
  gridCache = null;
  if (activeTab === 'pnl') loadPnlGrid();
}

// ── Sub-tab switching ──────────────────────────────────────────
document.querySelectorAll('.ep-tab').forEach(btn => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('.ep-tab').forEach(b => b.classList.remove('active'));
    document.querySelectorAll('.ep-tab-panel').forEach(p => p.classList.remove('active'));
    btn.classList.add('active');
    activeTab = btn.dataset.epTab;
    const panel = document.getElementById('epPanel' + activeTab.charAt(0).toUpperCase() + activeTab.slice(1));
    if (panel) panel.classList.add('active');

    // Lazy-load data on tab activation
    if (activeTab === 'pnl' && !gridCache) loadPnlGrid();
  });
});

// ══════════════════════════════════════════════════════════════════
//  HELPERS
// ══════════════════════════════════════════════════════════════════
function escapeHtml(s) {
  return String(s ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]));
}
function fmt(n) {
  const v = Number(n) || 0;
  if (v === 0) return '—';
  return Math.round(v).toLocaleString('en-US');
}
function classForValue(v) {
  if (Number(v) === 0) return 'num-zero';
  if (Number(v) < 0) return 'num-negative';
  return '';
}

// ══════════════════════════════════════════════════════════════════
