// ══════════════════════════════════════════════════════════════════
//  SALARIES (per employee, per month)
// ══════════════════════════════════════════════════════════════════
const salaryMonthEl = document.getElementById('salaryMonth');
salaryMonthEl.value = `${selectedYear}-${String(selectedMonth).padStart(2, '0')}`;
salaryMonthEl.addEventListener('change', loadSalaries);

function salaryYm() {
  const [y, m] = salaryMonthEl.value.split('-').map(Number);
  return { y, m };
}
function recalcSalaryTotal() {
  let total = 0;
  document.querySelectorAll('.salary-input').forEach(i => { total += Number(i.value) || 0; });
  document.getElementById('salaryTotalPill').textContent = 'Total: ' + Math.round(total).toLocaleString('en-US') + ' ₫';
}
async function loadSalaries() {
