using SoulPilates.Core.Entities;
using System;

namespace SoulPilates.Core.Entities;

/// <summary>
/// Studio-wide month-end financial summary. Computed (and re-computed) by
/// <c>AccountingService.ComputeMonthlyWashoutAsync</c>; one row per (Year, Month)
/// keyed via the unique index on those two fields.
///
/// <para>
/// P2-S03 extends the model with the allocation breakdown (Marketing/Savings/Owners)
/// plus the revenue split by Category/Method that the upcoming Washout view (P2-S07)
/// and P&amp;L grid (P2-S11) consume directly.
/// </para>
/// </summary>
public class MonthlyWashout : BaseEntity
{
    public int Month { get; set; }
    public int Year { get; set; }

    public decimal TotalSalesRevenue { get; set; }
    public decimal TotalEarnedRevenue { get; set; }
    public decimal TotalPayroll { get; set; }
    public decimal TotalFixedExpenses { get; set; }
    public decimal TotalCapitalDepreciation { get; set; }

    /// <summary>
    /// Net income BEFORE the marketing/savings/owners allocation split. Equals
    /// <c>TotalSalesRevenue - TotalPayroll - TotalFixedExpenses - TotalCapitalDepreciation</c>.
    /// Distinct from <see cref="NetIncome"/> for backward compatibility — older
    /// callers reading <c>NetIncome</c> still get the legacy value.
    /// </summary>
    public decimal TotalNetBeforeAllocations { get; set; }

    /// <summary>Marketing fund's share of <see cref="TotalNetBeforeAllocations"/> for this month.</summary>
    public decimal MarketingAllocation { get; set; }

    /// <summary>Savings reserve's share.</summary>
    public decimal SavingsAllocation { get; set; }

    /// <summary>Owners' pool — what gets split per <c>OwnerProfile.EquitySharePercentage</c>.</summary>
    public decimal OwnersPool { get; set; }

    /// <summary>
    /// Allocation percentages effective for this month at compute-time. Snapshotted
    /// here so a later edit to global / override settings doesn't silently re-shape
    /// historical washouts (audit trail).
    /// </summary>
    public decimal MarketingPercentageApplied { get; set; }
    public decimal SavingsPercentageApplied { get; set; }
    public decimal OwnersPercentageApplied { get; set; }

    /// <summary>
    /// Revenue grouped by source category (e.g. <c>"PACKAGE"</c>, <c>"MERCHANDISE"</c>,
    /// <c>"MERCHANDISE"</c>). Read by the multi-month P&amp;L grid (P2-S11).
    /// Empty dictionary for legacy washouts; never null.
    /// </summary>
    public Dictionary<string, decimal> RevenueByCategory { get; set; } = new();

    /// <summary>
    /// Revenue grouped by payment method (e.g. <c>"STRIPE"</c>, <c>"CASH"</c>).
    /// Drives the Washout view's "where the money came in" panel and the
    /// Stripe-fee deduction logic in P2-S08.
    /// </summary>
    public Dictionary<string, decimal> RevenueByMethod { get; set; } = new();

    public decimal NetIncome { get; set; }

    /// <summary>
    /// Sum of <see cref="PartnerPayable.CommissionAmount"/> across every
    /// partner with a payout in this month (P2-S10). Calc-once-read-many: the
    /// P&amp;L grid (P2-S11) and the Washout view both read this rather than
    /// re-aggregating <c>RefereePayout</c> on every render.
    /// </summary>
    public decimal TotalReferralCommissions { get; set; }

    /// <summary>
    /// True when the admin clicks "Lock month" on the Washout view (P2-S07).
    /// Locked months refuse to recompute — protects the audit trail when the
    /// owners have already paid distributions out.
    /// </summary>
    public bool Locked { get; set; }

    public DateTime CalculatedAt { get; set; } = DateTime.UtcNow;
}

