/// into individual payable rows so they appear on the washout "Total Payable
/// per Payee" table and the dashboard payroll-estimate KPI.
/// <list type="bullet">
///   <item><b>Owner-instructors</b> → sets <c>SalaryAmount</c> + <c>CommissionAmount</c>
///     on the existing <see cref="OwnerDistribution"/> row and adjusts <c>TotalPayable</c>.</item>
///   <item><b>Non-owner instructors</b> → upserts a <see cref="StaffPayable"/> row with
///     salary + commission breakdown.</item>
/// </list>
/// Idempotent: fully re-derived from <c>PayrollRun.Results</c> on every recompute.
/// Runs after <see cref="EmitOwnerDistributionsAsync"/> (needs existing distribution
/// rows) and before reimbursement/bonus passes (which compose onto the rows we create).
/// </summary>
private async Task ApplyPayrollToPayablesAsync(MonthlyWashout washout, List<PayrollRun> monthPayrolls)
{
    // ── 1. Flatten instructor results from all payroll runs in the month ──
    // In practice there's exactly one PayrollRun per month (enforced by a
    // unique index), but the code handles N-runs defensively.
    var allResults = monthPayrolls.SelectMany(p => p.Results).ToList();
    if (allResults.Count == 0) return;

    // ── 2. Resolve the active owner roster to route owner-instructors ─────
    var roster = await _owners.ListAsync();
    var ownerByStaffId = roster
        .Where(o => o.IsActiveOwner)
        .ToDictionary(o => o.StaffId, o => o);

    // ── 3. Split results into owner vs non-owner buckets ──────────────────
    var ownerResults = new List<InstructorPayrollResult>();
    var staffResults = new List<InstructorPayrollResult>();
    foreach (var r in allResults)
    {
        if (ownerByStaffId.ContainsKey(r.InstructorId))
            ownerResults.Add(r);
        else
            staffResults.Add(r);
    }

    // ── 4. Apply owner-instructor pay to OwnerDistribution rows ───────────
    foreach (var r in ownerResults)
    {
        var dist = await _distributions
            .Find(d => d.Year == washout.Year
                     && d.Month == washout.Month
                     && d.OwnerStaffId == r.InstructorId)
            .FirstOrDefaultAsync();
        if (dist is null) continue;

        var salary = r.BaseSalaryAmount;
        var commission = r.TotalPay - r.BaseSalaryAmount; // group + private earnings

        // Remove any prior salary/commission contribution from TotalPayable
        // before applying the fresh values (idempotent recompute safety).
        dist.TotalPayable -= dist.SalaryAmount + dist.CommissionAmount;
        dist.SalaryAmount = salary;
        dist.CommissionAmount = commission;
        dist.TotalPayable += salary + commission;
        dist.UpdatedAt = DateTime.UtcNow;
        await _distributions.ReplaceOneAsync(d => d.Id == dist.Id, dist);
    }

    // ── 5. Upsert StaffPayable rows for non-owner instructors ─────────────
    var existing = await _staffPayables
        .Find(s => s.Year == washout.Year && s.Month == washout.Month)
        .ToListAsync();
    var existingByName = existing
        .ToDictionary(s => s.StaffName.Trim(), s => s, StringComparer.OrdinalIgnoreCase);

    // Group by instructor name (handles the theoretical edge case of an
    // instructor appearing in multiple PayrollRuns in the same month).
    var staffByName = staffResults
        .GroupBy(r => r.InstructorNameSnapshot.Trim(), StringComparer.OrdinalIgnoreCase)
        .ToDictionary(
            g => g.Key,
            g => (salary: g.Sum(r => r.BaseSalaryAmount),
                  commission: g.Sum(r => r.TotalPay - r.BaseSalaryAmount)),
            StringComparer.OrdinalIgnoreCase);

    foreach (var (name, pay) in staffByName)
    {
