/// <summary>
/// Applies the per-month Salaries (from the Salaries editor) to the "Total
/// Payable per Payee" rows: sets each payee's salary column and folds it into
/// their TotalPayable. Owners → their OwnerDistribution row; other staff →
/// their StaffPayable row (created if they don't otherwise appear this month,
/// e.g. a salaried instructor who taught no classes). Does not affect washout
/// totals — those already deduct salaries via TotalSalaries. Idempotent.
/// </summary>
private async Task ApplyMonthlySalariesToPayablesAsync(MonthlyWashout washout)
{
    var salaries = (await GetMonthlySalariesAsync(washout.Year, washout.Month))
        .Where(s => s.Amount > 0m && s.Role != "RECEPTIONIST")
        .ToList();

    var roster = await _owners.ListAsync();
    var ownerStaffIds = roster.Where(o => o.IsActiveOwner).Select(o => o.StaffId).ToHashSet();

    foreach (var s in salaries)
    {
        if (ownerStaffIds.Contains(s.StaffId))
        {
            var dist = await _distributions
                .Find(d => d.Year == washout.Year && d.Month == washout.Month && d.OwnerStaffId == s.StaffId)
                .FirstOrDefaultAsync();
            if (dist is null) continue;
            dist.TotalPayable -= dist.SalaryAmount;
            dist.SalaryAmount = s.Amount;
            dist.TotalPayable += s.Amount;
            dist.UpdatedAt = DateTime.UtcNow;
            await _distributions.ReplaceOneAsync(d => d.Id == dist.Id, dist);
        }
        else
        {
            var prior = await _staffPayables
                .Find(p => p.Year == washout.Year && p.Month == washout.Month
                        && p.StaffName == s.StaffName)
                .FirstOrDefaultAsync();
            if (prior is not null)
            {
                prior.TotalPayable -= prior.SalaryAmount;
                prior.SalaryAmount = s.Amount;
                prior.TotalPayable += s.Amount;
                prior.UpdatedAt = DateTime.UtcNow;
                await _staffPayables.ReplaceOneAsync(p => p.Id == prior.Id, prior);
            }
            else
            {
                await _staffPayables.InsertOneAsync(new StaffPayable
                {
                    StaffName = s.StaffName,
                    Year = washout.Year,
                    Month = washout.Month,
                    SalaryAmount = s.Amount,
                    CommissionAmount = 0,
                    BonusAmount = 0,
                    ReimbursementAmount = 0,
                    TotalPayable = s.Amount,
                    PaidStatus = "PENDING",
                    CreatedAt = DateTime.UtcNow,
                    UpdatedAt = DateTime.UtcNow,
                });
            }
        }
    }
}

