private async Task ApplyMonthlySalariesToPayablesAsync(MonthlyWashout washout)
{
    // ── Prune payables for staff hired AFTER this month ──
    // The participant/commission gates stop new pay being computed, but any
    // stale payable row from before the start date was set must be removed so
    // it stops showing on the per-payee table.
    var monthEnd = new DateTime(washout.Year, washout.Month, 1, 0, 0, 0, DateTimeKind.Utc)
        .AddMonths(1).AddTicks(-1);
    var notYetEmployed = (await _staffCollection.Find(_ => true).ToListAsync())
        .Where(s => s.EmploymentStartDate.HasValue && s.EmploymentStartDate.Value > monthEnd)
        .Select(s => s.Name.Trim())
        .ToHashSet(StringComparer.OrdinalIgnoreCase);
    if (notYetEmployed.Count > 0)
    {
        var monthPayables = await _staffPayables
            .Find(p => p.Year == washout.Year && p.Month == washout.Month)
            .ToListAsync();
        foreach (var p in monthPayables.Where(p => notYetEmployed.Contains(p.StaffName.Trim())))
            await _staffPayables.DeleteOneAsync(x => x.Id == p.Id);
    }

