/// <summary>
/// Deletes payable rows for staff hired AFTER this month so a not-yet-employed
/// person (e.g. a receptionist who started mid-year) stops carrying stale
/// commission/bonus. Called before the receptionist payroll cost is summed so
/// their stale pay doesn't leak into the month's totals.
/// </summary>
private async Task PruneNotYetEmployedPayablesAsync(int year, int month)
{
    var monthEnd = new DateTime(year, month, 1, 0, 0, 0, DateTimeKind.Utc).AddMonths(1).AddTicks(-1);
    var notYetEmployed = (await _staffCollection.Find(_ => true).ToListAsync())
        .Where(s => s.EmploymentStartDate.HasValue && s.EmploymentStartDate.Value > monthEnd)
        .Select(s => s.Name.Trim())
        .ToHashSet(StringComparer.OrdinalIgnoreCase);
    if (notYetEmployed.Count == 0) return;

    var monthPayables = await _staffPayables
        .Find(p => p.Year == year && p.Month == month)
        .ToListAsync();
    foreach (var p in monthPayables.Where(p => notYetEmployed.Contains(p.StaffName.Trim())))
        await _staffPayables.DeleteOneAsync(x => x.Id == p.Id);
}

