var L1 = ["08:00","10:00","16:00"];   // Level 1 times
var L2 = ["11:00","15:00","17:00"];   // Level 2 times
// className -> { day (Sun=0..Sat=6), times }
var sched = {
  "Happy Neck & Shoulder":      {day:1, times:L1},  // Monday L1
  "Sculpt Waist":               {day:1, times:L2},  // Monday L2
  "Upper Back Love":            {day:2, times:L1},  // Tuesday L1
  "Sculpt Back":                {day:2, times:L2},  // Tuesday L2
  "Lower Back Love":            {day:3, times:L1},  // Wednesday L1
  "Sculpt Arms & Shoulders":    {day:3, times:L2},  // Wednesday L2
  "Core Restore":               {day:4, times:L1},  // Thursday L1
  "Sculpt Hips & Legs":         {day:4, times:L2},  // Thursday L2
  "Reboot Arms":                {day:5, times:L1},  // Friday L1
  "Core Balance":               {day:5, times:L2},  // Friday L2
  "Hip & Knee Harmony":         {day:6, times:L1},  // Saturday L1
  "Flow & Energy":              {day:6, times:L2}   // Saturday L2
};
var updated = 0;
for (var name in sched) {
  var s = sched[name];
  var slots = s.times.map(function(t){ return { DayOfWeek: s.day, TimeOfDay: t, CapacityOverride: null, InstructorOverride: null, InstructorOverrideName: null }; });
  var r = db.ClassBlueprints.updateOne({ClassName:name, Tags:"SP_INFOGRAPHIC"}, {$set:{WeeklySlots:slots}});
  if (r.modifiedCount) updated++;
}
print("updated "+updated+" blueprints with weekly slots");
print("=== schedule by day ===");
var dayName=["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];
[1,2,3,4,5,6].forEach(function(d){
  var rows=[];
  db.ClassBlueprints.find({Tags:"SP_INFOGRAPHIC","WeeklySlots.DayOfWeek":d}).forEach(function(b){
    b.WeeklySlots.filter(function(w){return w.DayOfWeek==d;}).forEach(function(w){ rows.push({t:w.TimeOfDay, n:b.ClassName, lvl:b.DifficultyLevel=="BEGINNER"?"L1":"L2"}); });
  });
  rows.sort(function(a,b){return a.t.localeCompare(b.t);});
  print("  "+dayName[d]+": "+rows.map(function(r){return r.t+" "+r.n+"("+r.lvl+")";}).join(" | "));
});
print("total slots: "+db.ClassBlueprints.aggregate([{$match:{Tags:"SP_INFOGRAPHIC"}},{$project:{c:{$size:"$WeeklySlots"}}},{$group:{_id:null,t:{$sum:"$c"}}}]).toArray()[0].t);
EOF
cd /opt/soulpilates; MU=$(grep '^MONGO_USER=' prod.env|cut -d= -f2); MP=$(grep '^MONGO_PASSWORD=' prod.env|cut -d= -f2); docker exec -i soulpilates-prod-mongo mongosh -u "$MU" -p "$MP" --authenticationDatabase admin soulpilates --quiet < /tmp/claude-0/-root/f1b1af7e-43da-44b8-92b2-51e4d240617b/scratchpad/slots.js

