private async Task<int> MaterialiseBlueprintInternal(
    ClassBlueprint bp,
    CompanyScheduleConfig config,
    int horizonDays,
    DateTime nowUtc)
{
    var created = 0;
    var holidayDates = new HashSet<string>(
        config.Holidays?.Select(h => h.Date) ?? Enumerable.Empty<string>());
    var exceptionDates = new HashSet<string>(
        bp.ExceptionDates ?? Enumerable.Empty<string>());

    // Parse validity window
    DateOnly? validFrom = null, validTo = null;
    if (!string.IsNullOrWhiteSpace(bp.ValidFrom) &&
        DateOnly.TryParseExact(bp.ValidFrom, "yyyy-MM-dd", null, System.Globalization.DateTimeStyles.None, out var vf))
        validFrom = vf;
    if (!string.IsNullOrWhiteSpace(bp.ValidTo) &&
        DateOnly.TryParseExact(bp.ValidTo, "yyyy-MM-dd", null, System.Globalization.DateTimeStyles.None, out var vt))
        validTo = vt;

    // Resolve default instructor name + photo once
    var defaultInstructorName = bp.DefaultInstructorName ?? "";
    string? defaultInstructorPhoto = null;
    if (!string.IsNullOrWhiteSpace(bp.DefaultInstructorId))
    {
        var staff = await _staff.Find(s => s.Id == bp.DefaultInstructorId).FirstOrDefaultAsync();
        if (string.IsNullOrWhiteSpace(defaultInstructorName))
            defaultInstructorName = staff?.Name ?? "";
        defaultInstructorPhoto = staff?.PhotoUrl;
    }

    // SPM-71 — resolve the equipment NAME list once (treats old singular as [singular]).
    var equipmentTypes = ResolveEquipmentTypes(bp);

    var startDate = DateOnly.FromDateTime(TimeZoneInfo.ConvertTimeFromUtc(nowUtc, StudioTz));
    var endDate = startDate.AddDays(horizonDays);

    foreach (var slot in bp.WeeklySlots)
    {
        // Parse slot time
        if (!TimeSpan.TryParseExact(slot.TimeOfDay, @"hh\:mm", null, out var slotTime))
            continue;

        // Walk every occurrence of this day-of-week in the window
        var current = startDate;
        while (current <= endDate)
        {
            if (current.DayOfWeek == slot.DayOfWeek)
            {
                var dateStr = current.ToString("yyyy-MM-dd");

                // ── Skip checks ──
                if (holidayDates.Contains(dateStr)) { current = current.AddDays(1); continue; }
                if (exceptionDates.Contains(dateStr)) { current = current.AddDays(1); continue; }
                if (validFrom.HasValue && current < validFrom.Value) { current = current.AddDays(1); continue; }
                if (validTo.HasValue && current > validTo.Value) { current = current.AddDays(1); continue; }

                // ── Company operating hours ──
                var companyHours = ResolveHoursForDate(
                    config.WeeklyHours, config.DateOverrides, current);

                // If WeeklyHours is configured and this day is missing → studio closed
                if (config.WeeklyHours?.Count > 0 && companyHours == null)
                { current = current.AddDays(1); continue; }

                // If company hours exist, check the slot fits within them
                if (companyHours != null &&
                    !IsWithinOperatingHours(companyHours, slotTime, bp.DurationMinutes))
                { current = current.AddDays(1); continue; }

                // ── All checks passed → create session ──

                // Calculate UTC start/end times
                var localDateTime = current.ToDateTime(new TimeOnly(slotTime.Hours, slotTime.Minutes));

