public async Task<(int BlueprintsProcessed, int SessionsCreated)> MaterialiseAllBlueprintsAsync(int horizonDays, DateTime nowUtc)
{
    var blueprints = await _blueprints
        .Find(b => b.IsActive)
        .ToListAsync();

    var config = await _settingsService.GetScheduleConfigAsync();
    var totalCreated = 0;

    foreach (var bp in blueprints)
    {
        if (bp.WeeklySlots == null || bp.WeeklySlots.Count == 0) continue;
        totalCreated += await MaterialiseBlueprintInternal(bp, config, horizonDays, nowUtc);
    }

    return (blueprints.Count, totalCreated);
}

/// <summary>
/// Core materialisation logic for a single blueprint. Iterates each WeeklySlot,
/// walks every occurrence in the [now, now+horizon] window, checks holidays/
/// exceptions/validity, and inserts CalendarSession rows idempotently.
/// </summary>
// ── Operating Hours Helper ─────────────────────────────────────────────

/// <summary>
/// Returns true if the given studio-local slot time + duration fits entirely
/// within the allowed operating windows. Supports both single-window
/// (Open/Close) and multi-window (Windows list) modes.
/// </summary>
private static bool IsWithinOperatingHours(DayHours hours, TimeSpan slotTime, int durationMinutes)
{
    var slotEnd = slotTime.Add(TimeSpan.FromMinutes(durationMinutes));

    // Multi-window mode: slot must fit entirely within at least one window
    if (hours.Windows is { Count: > 0 })
    {
        return hours.Windows.Any(w =>
        {
            if (!TimeSpan.TryParseExact(w.Open, @"hh\:mm", null, out var wOpen) ||
                !TimeSpan.TryParseExact(w.Close, @"hh\:mm", null, out var wClose))
                return false;
            return slotTime >= wOpen && slotEnd <= wClose;
        });
    }

    // Single-window fallback (V2 backward-compat)
    if (!TimeSpan.TryParseExact(hours.Open, @"hh\:mm", null, out var open) ||
        !TimeSpan.TryParseExact(hours.Close, @"hh\:mm", null, out var close))
        return true; // malformed config → allow (fail-open)

    return slotTime >= open && slotEnd <= close;
}

