function syncHiddenField() {
  const el = document.getElementById("bMuscles") as HTMLInputElement;
  if (el) el.value = [...selectedMuscles].join(",");
}

// ── Render muscle chips row ──
function renderChips() {
  const wrap = document.getElementById("muscleChips")!;
  wrap.innerHTML = "";

  if (selectedMuscles.size === 0) {
    wrap.innerHTML =
      '<span style="font-size:12px;color:var(--color-text-muted);font-style:italic;">None selected — click muscles on the body above</span>';
    return;
  }

  selectedMuscles.forEach((muscle) => {
    const color = MUSCLE_COLORS[muscle] ?? "#FF6B35";
    const label = getMuscleName(muscle as any);
    const chip = document.createElement("span");
    chip.className = "muscle-chip";
    chip.style.background = color;
    chip.title = `Click to remove ${label}`;
    chip.innerHTML = `${label}<span class="chip-x" aria-label="remove">×</span>`;
    chip.addEventListener("click", () => toggleMuscle(muscle));
    wrap.appendChild(chip);
  });
}

// ── Utilities ──

