{
    // Parse slot time
    if (!TimeSpan.TryParseExact(slot.TimeOfDay, @"hh\:mm", null, out var slotTime))
        continue;

    // Walk every occurrence of this day-of-week in the window
    var current = startDate;
    while (current <= endDate)
    {
        if (current.DayOfWeek == slot.DayOfWeek)
        {
            var dateStr = current.ToString("yyyy-MM-dd");

            // ── Skip checks ──
            if (holidayDates.Contains(dateStr)) { current = current.AddDays(1); continue; }
            if (exceptionDates.Contains(dateStr)) { current = current.AddDays(1); continue; }
            if (validFrom.HasValue && current < validFrom.Value) { current = current.AddDays(1); continue; }
            if (validTo.HasValue && current > validTo.Value) { current = current.AddDays(1); continue; }

