private static List<string> ResolveEquipmentTypes(ClassBlueprint blueprint)
{
    var names = (blueprint.EquipmentTypes ?? new List<string>())
        .Where(n => !string.IsNullOrWhiteSpace(n))
        .ToList();

    if (names.Count == 0 && !string.IsNullOrWhiteSpace(blueprint.EquipmentType))
        names.Add(blueprint.EquipmentType!);

    return names;
}

public async Task<int> MaterialiseFromBlueprintAsync(string blueprintId, int horizonDays, DateTime nowUtc)
{
    var bp = await _blueprints.Find(b => b.Id == blueprintId).FirstOrDefaultAsync();
    if (bp == null || !bp.IsActive || bp.WeeklySlots == null || bp.WeeklySlots.Count == 0)
        return 0;

    var config = await _settingsService.GetScheduleConfigAsync();
    return await MaterialiseBlueprintInternal(bp, config, horizonDays, nowUtc);
}

