private static DayHours? ResolveHoursForDate(
    Dictionary<int, DayHours>? weeklyHours,
    List<DateOverride>? dateOverrides,
    DateOnly date)
{
    // Check date overrides first (they take precedence)
    var overr = dateOverrides?.FirstOrDefault(o => o.Date == date.ToString("yyyy-MM-dd"));
    if (overr != null)
    {
        return new DayHours
        {
            Open = overr.Open,
            Close = overr.Close,
            Windows = overr.Windows
        };
    }

    // Fall back to weekly hours
    if (weeklyHours == null || weeklyHours.Count == 0)
        return null; // no hours configured → don't restrict

    var dayKey = (int)date.DayOfWeek;
    return weeklyHours.TryGetValue(dayKey, out var hours) ? hours : null;
}

