using SoulPilates.Core.DTOs;

namespace SoulPilates.Core.Interfaces;

/// <summary>
/// P3-S09/S10 — backing service for the instructor self-service portal.
/// </summary>
public interface IInstructorService
{
    /// <summary>
    /// Resolve a <see cref="InstructorProfileDto"/> for the given
    /// staff id. Returns <c>null</c> when the staff id is missing or
    /// the referenced <see cref="SoulPilates.Core.Entities.Staff"/>
    /// row no longer exists. The controller maps both null cases to
    /// HTTP 404, which the Astro frontend renders as a
    /// "Profile setup pending" banner.
    /// </summary>
    Task<InstructorProfileDto?> GetProfileAsync(string? staffId);

    /// <summary>
    /// P3-S10 — upcoming-class schedule for the next 30 days (Q3-S10-2 default A).
    /// Returns the instructor's <c>SCHEDULED</c> or <c>COMPLETED</c> calendar
    /// sessions in that window, each with a redacted client roster
    /// (no phone/email; see <see cref="InstructorScheduleEntryDto"/>).
    /// Returns an empty list when the staff id is missing or has no
    /// sessions — never null.
    /// </summary>
    Task<List<InstructorScheduleEntryDto>> GetUpcomingScheduleAsync(string? staffId);

    /// <summary>
    /// P3-S10 — current-month earnings projection for the instructor
    /// portal. Always returns a result for a valid staff id (even when
    /// zero sessions have been taught — base salary still applies).
    /// Returns null only when the staff id is missing or the underlying
    /// Staff row no longer exists.
    /// </summary>
    Task<InstructorEarningsDto?> GetCurrentMonthEarningsAsync(string? staffId);
}

