/* ══ MONTH VIEW ══ */
function renderMonthGrid() {
  const headers = document.getElementById('calHeaders');
  const grid = document.getElementById('calGrid');
  const gtc = 'repeat(7, 1fr)';
  headers.style.gridTemplateColumns = gtc;
  grid.style.gridTemplateColumns = gtc;

  const dayNames = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  headers.innerHTML = dayNames.map(d => `<div class="cal-col-head">${d}</div>`).join('');

  // Build the 6-week grid starting on the Monday on/before the 1st.
  const first = new Date(selectedDayDate.getFullYear(), selectedDayDate.getMonth(), 1);
  const gridStart = getMonday(first);
  const thisMonth = selectedDayDate.getMonth();
  const todayStr = new Date().toDateString();

  const sessions = getVisibleSessions();
  // Bucket sessions by local day string.
  const byDay = new Map();
  sessions.forEach(s => {
    const key = new Date(s.startTime).toDateString();
    if (!byDay.has(key)) byDay.set(key, []);
    byDay.get(key).push(s);
  });

  grid.innerHTML = '';
  for (let i = 0; i < 42; i++) {
    const cellDate = new Date(gridStart);
    cellDate.setDate(gridStart.getDate() + i);
    const inMonth = cellDate.getMonth() === thisMonth;
    const isToday = cellDate.toDateString() === todayStr;
    const isHoliday = holidayDates.has(cellDate.toISOString().slice(0, 10));

    const cell = document.createElement('div');
    cell.className = 'cal-month-cell' + (inMonth ? '' : ' cal-month-cell-muted') + (isToday ? ' cal-month-cell-today' : '');
    cell.dataset.date = cellDate.toISOString();

    const dateHead = document.createElement('div');
    dateHead.className = 'cal-month-datenum';
    dateHead.textContent = cellDate.getDate();
    if (isHoliday) dateHead.style.color = 'var(--color-danger, #dc2626)';
    cell.appendChild(dateHead);

    const daySessions = (byDay.get(cellDate.toDateString()) || [])
      .sort((a, b) => new Date(a.startTime) - new Date(b.startTime));

    const MAX = 4;
    daySessions.slice(0, MAX).forEach(s => {
      const chip = document.createElement('div');
      const st = new Date(s.startTime);
      const time = st.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
      chip.className = 'cal-month-chip' + (s.status === 'BLOCKED' ? ' cal-month-chip-blocked' : '');
      const cap = s.capacity || 0;
      const booked = s.currentBookings || 0;
      chip.innerHTML = `<span class="cal-month-chip-time">${time}</span> ${s.className || 'Class'}` +
        (s.status === 'BLOCKED' ? '' : ` <span class="cal-month-chip-count">${booked}/${cap}</span>`);
      chip.title = `${time} · ${s.className || 'Class'}${s.instructorName ? ' · ' + s.instructorName : ''}${s.status === 'BLOCKED' ? '' : ` · ${booked}/${cap} booked`}`;
      chip.addEventListener('click', () => { if (s.id) ClassDetailPanel.open(s.id); });
      cell.appendChild(chip);
    });
    if (daySessions.length > MAX) {
      const more = document.createElement('div');
      more.className = 'cal-month-more';
      more.textContent = `+${daySessions.length - MAX} more`;
      more.addEventListener('click', () => { currentView = 'day'; selectedDayDate = new Date(cellDate); document.querySelectorAll('.cal-seg-btn').forEach(b => b.classList.toggle('active', b.dataset.view === 'day')); renderCalendar(); });
      cell.appendChild(more);
    }

    // Click empty cell → jump into that day.
