/* ── Month view ── */
.cal-col-head {
  font-size: 11px; font-weight: 600; text-transform: uppercase;
  letter-spacing: .4px; color: var(--color-text-muted);
  text-align: center; padding: 8px 0;
  border-bottom: 1px solid var(--color-border-subtle);
}
.cal-month-cell {
  min-height: 116px; padding: 4px;
  border-right: 1px solid var(--color-border-subtle);
  border-bottom: 1px solid var(--color-border-subtle);
  display: flex; flex-direction: column; gap: 2px; overflow: hidden;
}
.cal-month-cell-muted { background: var(--color-surface-raised, rgba(0,0,0,0.02)); opacity: .55; }
.cal-month-cell-today { box-shadow: inset 0 0 0 2px var(--color-brand-accent); }
.cal-month-datenum { font-size: 12px; font-weight: 600; color: var(--color-text); padding: 1px 3px; }
.cal-month-chip {
  font-size: 11px; line-height: 1.25; padding: 2px 5px; border-radius: 5px;
  background: var(--color-brand-accent-soft, rgba(99,179,237,0.16));
  color: var(--color-text); cursor: pointer;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  border-left: 3px solid var(--color-brand-accent);
}
.cal-month-chip:hover { filter: brightness(1.06); }
.cal-month-chip-blocked { background: rgba(148,148,148,0.18); border-left-color: #9ca3af; opacity: .8; }
.cal-month-chip-time { font-weight: 600; }
.cal-month-chip-count { color: var(--color-text-muted); font-size: 10px; }
.cal-month-more { font-size: 10px; color: var(--color-brand-accent); cursor: pointer; padding: 1px 4px; font-weight: 600; }

