  /* ── Featured pricing packages from API ── */
  (function (API) {
    var allPackages = []; // all featured packages from API
    var activeTab = "group";

    function fmt(n) {
      return Math.round(n || 0).toLocaleString("en-US");
    }

    /* Filter packages for the current tab.
       GROUP tab  → formatRestriction === 'GROUP'  or null/undefined
       PRIVATE tab → formatRestriction === 'PRIVATE' or null/undefined */
    function filterForTab(list, tab) {
      var targeted = list.filter(function (p) {
        var r = (p.formatRestriction || "").toUpperCase();
        return tab === "group"
          ? r === "GROUP" || r === ""
          : r === "PRIVATE" || r === "";
      });
      // fall back to all if nothing matched
      return targeted.length ? targeted : list;
    }

    function renderPackages(list) {
      var grid = document.getElementById("hpPkgGrid");
      if (!grid) return;

      var subset = filterForTab(list, activeTab).slice(0, 4);
      if (!subset.length) {
        grid.innerHTML =
          '<p style="color:rgba(255,255,255,0.4);grid-column:1/-1;padding:40px 0;">No packages available for this class type.</p>';
        return;
      }

      grid.innerHTML = subset
        .map(function (p) {
          return [
            '<div class="hp-pkg-card">',
            '<div class="hp-pkg-badge">' +
              (p.credits || 0) +
              " CLASSES</div>",
            '<div class="hp-pkg-price">' +
              fmt(p.pricePerClass) +
              ' <span class="hp-pkg-cur">VND</span></div>',
            '<div class="hp-pkg-per">PER CLASS</div>',
            '<div class="hp-pkg-total">' +
              fmt(p.basePrice) +
              ' <span class="hp-pkg-cur">VND</span></div>',
            '<div class="hp-pkg-total-label">TOTAL</div>',
            "</div>",
          ].join("");
        })
        .join("");
    }

    function updateHeading() {
      var h = document.getElementById("hpPricingHeading");
      if (h)
        h.textContent =
          activeTab === "group" ? "GROUP CLASSES" : "PRIVATE CLASSES";
    }

    function showError() {
      var grid = document.getElementById("hpPkgGrid");
      var err = document.getElementById("hpPkgError");
      if (grid) grid.style.display = "none";
      if (err) err.style.display = "block";
    }

    /* Tab click handlers */
    document.querySelectorAll(".hp-pricing-tab").forEach(function (btn) {
      btn.addEventListener("click", function () {
        document.querySelectorAll(".hp-pricing-tab").forEach(function (t) {
          t.classList.remove("active");
        });
        btn.classList.add("active");
        activeTab = btn.getAttribute("data-tab") || "group";
        updateHeading();
        if (allPackages.length) renderPackages(allPackages);
      });
    });

    async function load() {
      var base = API || window.location.origin;
      try {
        var res = await fetch(base + "/api/package-purchase/featured", {
          signal: AbortSignal.timeout(6000),
        });
        if (!res.ok) throw new Error("non-ok");
        var data = await res.json();
        if (!Array.isArray(data) || data.length === 0) {
          showError();
          return;
        }
        allPackages = data;
        renderPackages(allPackages);
      } catch (e) {
        showError();
      }
    }

    load();
  })(__API_BASE__);
</script>

