function renderPackages(list) {
  var grid = document.getElementById("hpPkgGrid");
  if (!grid) return;

  var subset = filterForTab(list, activeTab)
    .slice()
    .sort(function (a, b) {
      return (a.credits || 0) - (b.credits || 0);
    })
    .slice(0, 4);

  // Drop-in banner for the active tab.
  var dropinWrap = document.getElementById("hpDropin");
  var dropin = subset.length ? subset[0].dropInPrice || 0 : 0;
  if (dropinWrap) {
    if (dropin > 0) {
      document.getElementById("hpDropinPrice").innerHTML =
        fmt(dropin) + ' <span class="hp-dropin-cur">VND</span>';
      dropinWrap.style.display = "";
    } else {
      dropinWrap.style.display = "none";
    }
  }

  if (!subset.length) {
    grid.innerHTML =
      '<p style="color:rgba(255,255,255,0.4);grid-column:1/-1;padding:40px 0;">No packages available for this class type.</p>';
    return;
  }

  // Best deal = highest saving (usually the largest pack).
  var bestSave = 0;
  subset.forEach(function (p) {
    if ((p.savePercent || 0) > bestSave) bestSave = p.savePercent || 0;
  });

  grid.innerHTML = subset
    .map(function (p) {
      var isBest = (p.savePercent || 0) === bestSave && bestSave > 0;
      return [
        '<div class="hp-pkg-card' + (isBest ? " hp-pkg-card--best" : "") + '">',
        isBest ? '<div class="hp-pkg-bestflag">BEST DEAL</div>' : "",
        (p.savePercent || 0) > 0
          ? '<div class="hp-pkg-save">SAVE ' + p.savePercent + "%</div>"
          : "",
        '<div class="hp-pkg-badge">' + (p.credits || 0) + " CLASSES</div>",
        '<div class="hp-pkg-price">' +
          fmt(p.pricePerClass) +
          ' <span class="hp-pkg-cur">VND</span></div>',
        '<div class="hp-pkg-per">PER CLASS</div>',
        '<div class="hp-pkg-total">' +
          fmt(p.basePrice) +
          ' <span class="hp-pkg-cur">VND</span></div>',
        '<div class="hp-pkg-total-label">TOTAL</div>',
        inclusionsHtml(p),
        "</div>",
      ].join("");
    })
    .join("");
}

