/* Save ribbon — top-right corner of the card */
.hp-pkg-save {
  position: absolute;
  top: 12px;
  right: -6px;
  background: linear-gradient(135deg, #f0763a, #e2562a);
  color: var(--hp-white);
  font-family: "Inter", sans-serif;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  padding: 5px 12px;
  border-radius: 6px 0 0 6px;
  box-shadow: 0 6px 14px rgba(226, 86, 42, 0.4);
  z-index: 2;
}
.hp-pkg-save::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: -6px;
  border: 3px solid #a83c18;
  border-right-color: transparent;
  border-bottom-color: transparent;
}

/* Best-deal highlighted card */
.hp-pkg-card--best {
  box-shadow: 0 0 0 2px var(--hp-copper), 0 18px 44px rgba(0, 0, 0, 0.3);
  transform: translateY(-4px);
}
.hp-pkg-bestflag {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: linear-gradient(135deg, #f4b23c, #e2562a);
  color: #fff;
  font-family: "Inter", sans-serif;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
  text-transform: uppercase;
  padding: 4px 14px;
  border-radius: 999px;
  white-space: nowrap;
  z-index: 3;
  box-shadow: 0 6px 16px rgba(226, 86, 42, 0.45);
}

/* Drop-in banner */
.hp-dropin {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  max-width: 420px;
  margin: 0 auto 26px;
  padding: 14px 24px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 12px;
  backdrop-filter: blur(4px);
}
