using MongoDB.Driver;
using Microsoft.Extensions.Configuration;
using Microsoft.IdentityModel.Tokens;
using SoulPilates.Core.DTOs;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Infrastructure.Data;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;

namespace SoulPilates.Services;

public class AuthService : IAuthService
{
    private readonly IMongoCollection<User> _users;
    private readonly IMongoCollection<Staff> _staff;
    private readonly string _jwtSecret;

    public AuthService(MongoDbContext dbContext, IConfiguration config)
    {
        _users = dbContext.GetCollection<User>("Users");
        _staff = dbContext.GetCollection<Staff>("Staff");
        _jwtSecret = config["JwtSettings:Secret"] ?? throw new Exception("Jwt secret not found");
    }

    public async Task<LoginResponse?> AuthenticateAsync(LoginRequest request)
    {
        // Case-insensitive email lookup. Emails are stored lowercased by the
        // seeder, but sign-in input (especially iOS autofill) may arrive with
        // different casing. Anchor + escape so the value is matched literally,
        // not as a user-supplied regex.
        var emailPattern = "^" + System.Text.RegularExpressions.Regex.Escape(request.Email?.Trim() ?? "") + "$";
        var emailFilter = Builders<User>.Filter.Regex(
            u => u.Email,
            new MongoDB.Bson.BsonRegularExpression(emailPattern, "i"));
        var user = await _users.Find(emailFilter).FirstOrDefaultAsync();
        if (user == null || !PasswordHasher.Verify(request.Password, user.PasswordHash)) return null;

        var linkedStaff = await ResolveLinkedStaffAsync(user);
        var effectiveRole = ResolveEffectiveRole(user, linkedStaff);

        var tokenHandler = new JwtSecurityTokenHandler();
        var key = Encoding.ASCII.GetBytes(_jwtSecret);

        // Base claims — every authenticated user carries these.
        // P3-S09: instructor users additionally carry a `staff_id`
        // claim so the InstructorController can resolve the linked
        // Staff row without re-querying the Users collection on
        // every request. Conditional emission keeps the token small
        // for Admin/Owner accounts that have no Staff link.
        var claims = new List<Claim>
        {
            new(ClaimTypes.NameIdentifier, user.Id ?? ""),
            new(ClaimTypes.Role, effectiveRole),
            new(ClaimTypes.Email, user.Email),
        };
        if (!string.IsNullOrWhiteSpace(user.StaffId))
            claims.Add(new Claim("staff_id", user.StaffId));

        // Per-user admin-module grants → `module` claims. These let a specific
        // user (typically an instructor) reach individual admin pages that their
        // role alone wouldn't unlock. The Module:{key} authorization policy and
        // the AdminLayout nav both honour these on top of the role defaults.
        foreach (var moduleKey in (user.AllowedAdminModules ?? new List<string>())
                     .Where(m => !string.IsNullOrWhiteSpace(m))
                     .Select(m => m.Trim().ToLowerInvariant())
                     .Distinct())
        {
            claims.Add(new Claim("module", moduleKey));
        }

        var tokenDescriptor = new SecurityTokenDescriptor
        {
            Subject = new ClaimsIdentity(claims),
            Expires = DateTime.UtcNow.AddDays(7),
            SigningCredentials = new SigningCredentials(new SymmetricSecurityKey(key), SecurityAlgorithms.HmacSha256Signature)
        };

        var token = tokenHandler.CreateToken(tokenDescriptor);

        return new LoginResponse
        {
            Token = tokenHandler.WriteToken(token),
            UserRole = effectiveRole,
            StaffId = user.StaffId,
            MustChangePassword = user.MustChangePassword,
        };
    }

    public async Task<bool> ChangePasswordAsync(string userId, string newPassword)
    {
        var update = Builders<User>.Update
            .Set(u => u.PasswordHash, PasswordHasher.Hash(newPassword))
            .Set(u => u.MustChangePassword, false);
        var result = await _users.UpdateOneAsync(u => u.Id == userId, update);
        return result.MatchedCount > 0;
    }

    private string ResolveEffectiveRole(User user, Staff? staff)
    {
        var mapped = MapStaffRoleToUserRole(staff?.Role);
        if (!string.IsNullOrWhiteSpace(mapped)) return mapped;

        return string.IsNullOrWhiteSpace(user.Role) ? "Instructor" : user.Role;
    }

    private async Task<Staff?> ResolveLinkedStaffAsync(User user)
    {
        Staff? staff = null;

        if (!string.IsNullOrWhiteSpace(user.StaffId))
        {
            staff = await _staff.Find(s => s.Id == user.StaffId).FirstOrDefaultAsync();
        }

        if (staff != null) return staff;

        var filters = new List<FilterDefinition<Staff>>();
        if (!string.IsNullOrWhiteSpace(user.Id))
            filters.Add(Builders<Staff>.Filter.Eq(s => s.UserId, user.Id));
        if (!string.IsNullOrWhiteSpace(user.Email))
            filters.Add(Builders<Staff>.Filter.Eq(s => s.Email, user.Email));
        if (filters.Count == 0) return null;

        staff = await _staff.Find(Builders<Staff>.Filter.Or(filters)).FirstOrDefaultAsync();
        if (staff == null || string.IsNullOrWhiteSpace(staff.Id)) return null;

        var mappedRole = MapStaffRoleToUserRole(staff.Role) ?? user.Role ?? "Instructor";
        await _users.UpdateOneAsync(
            u => u.Id == user.Id,
            Builders<User>.Update
                .Set(u => u.StaffId, staff.Id)
                .Set(u => u.Role, mappedRole));

        if (string.IsNullOrWhiteSpace(staff.UserId) && !string.IsNullOrWhiteSpace(user.Id))
        {
            await _staff.UpdateOneAsync(
                s => s.Id == staff.Id,
                Builders<Staff>.Update.Set(s => s.UserId, user.Id));
            staff.UserId = user.Id;
        }

        user.StaffId = staff.Id;
        user.Role = mappedRole;
        return staff;
    }

    private static string? MapStaffRoleToUserRole(string? staffRole)
    {
        return (staffRole ?? string.Empty).Trim().ToUpperInvariant() switch
        {
            "RECEPTIONIST" => "Receptionist",
            "INSTRUCTOR" => "Instructor",
            "MANAGER" => "Manager",
            "OWNER" => "Owner",
            "ACCOUNTANT" => "Accountant",
            "SUPERADMIN" => "SuperAdmin",
            "FREELANCE" => "Freelance",
            _ => null,
        };
    }
}

