using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using MongoDB.Driver;
using SoulPilates.Core.Entities;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.API.Controllers;

/// <summary>
/// Backs the admin "Users &amp; Access" page. Lets an admin see every login
/// account and grant/revoke individual admin page modules per user
/// (<see cref="User.AllowedAdminModules"/>) — e.g. give one instructor the
/// Clients page without changing their role. Admin-only.
/// </summary>
[ApiController]
[Route("api/user-access")]
[Authorize(Roles = "Admin,SuperAdmin,Owner")]
public class UserAccessController : ControllerBase
{
    private readonly IMongoCollection<User> _users;
    private readonly IMongoCollection<RoleModuleDefinition> _modules;

    public UserAccessController(MongoDbContext db)
    {
        _users = db.GetCollection<User>("Users");
        _modules = db.GetCollection<RoleModuleDefinition>("RoleModuleDefinitions");
    }

    /// <summary>The full catalog of grantable admin page modules.</summary>
    [HttpGet("modules")]
    public async Task<IActionResult> GetModules()
    {
        var mods = await _modules.Find(FilterDefinition<RoleModuleDefinition>.Empty).ToListAsync();
        return Ok(mods.Select(m => new { key = m.Key, label = m.Label, path = m.Path }));
    }

    /// <summary>All login accounts with their role and per-user page grants.</summary>
    [HttpGet]
    public async Task<IActionResult> GetUsers()
    {
        var users = await _users.Find(FilterDefinition<User>.Empty).ToListAsync();
        return Ok(users
            .OrderBy(u => u.Role)
            .ThenBy(u => u.Name)
            .Select(u => new
            {
                id = u.Id,
                name = u.Name,
                email = u.Email,
                role = u.Role,
                staffId = u.StaffId,
                allowedAdminModules = u.AllowedAdminModules ?? new List<string>(),
            }));
    }

    public class SetModulesRequest
    {
        public List<string> AllowedAdminModules { get; set; } = new();
    }

    /// <summary>Replace a user's per-user admin-module grants.</summary>
    [HttpPut("{id}/modules")]
    public async Task<IActionResult> SetModules(string id, [FromBody] SetModulesRequest body)
    {
        // Validate against the real catalog so we never persist junk keys.
        var validKeys = (await _modules.Find(FilterDefinition<RoleModuleDefinition>.Empty).ToListAsync())
            .Select(m => m.Key.Trim().ToLowerInvariant())
            .ToHashSet();

        var cleaned = (body.AllowedAdminModules ?? new List<string>())
            .Select(m => (m ?? string.Empty).Trim().ToLowerInvariant())
            .Where(m => validKeys.Contains(m))
            .Distinct()
            .ToList();

        var result = await _users.UpdateOneAsync(
            u => u.Id == id,
            Builders<User>.Update.Set(u => u.AllowedAdminModules, cleaned));

        if (result.MatchedCount == 0) return NotFound();
        // Note: the user must sign in again for new grants to take effect (grants
        // are baked into the JWT `module` claims at login).
        return Ok(new { id, allowedAdminModules = cleaned });
    }
}

