    /// <summary>
    /// Set a user's exact admin-page access (custom-access mode). The provided
    /// list becomes the authoritative set — pages can be granted AND revoked.
    /// </summary>
    [HttpPut("{id}/modules")]
    public async Task<IActionResult> SetModules(string id, [FromBody] SetModulesRequest body)
    {
        // Self-lockout guard: you can't restrict your own account (you'd risk
        // losing the ability to fix access). Limit other accounts instead.
        var callerId = User.FindFirstValue(System.Security.Claims.ClaimTypes.NameIdentifier);
        if (id == callerId)
            return BadRequest(new { message = "You can't change your own access. Ask another admin." });

        // Validate against the real catalog so we never persist junk keys.
        var validKeys = (await _modules.Find(FilterDefinition<RoleModuleDefinition>.Empty).ToListAsync())
            .Select(m => m.Key.Trim().ToLowerInvariant())
            .ToHashSet();

        var cleaned = (body.AllowedAdminModules ?? new List<string>())
            .Select(m => (m ?? string.Empty).Trim().ToLowerInvariant())
            .Where(m => validKeys.Contains(m))
            .Distinct()
            .ToList();

        var result = await _users.UpdateOneAsync(
            u => u.Id == id,
            Builders<User>.Update
                .Set(u => u.AllowedAdminModules, cleaned)
                .Set(u => u.UseCustomModuleAccess, true));

        if (result.MatchedCount == 0) return NotFound();
        // Note: the user must sign in again for changes to take effect (access is
        // baked into the JWT claims at login).
        return Ok(new { id, allowedAdminModules = cleaned, useCustomModuleAccess = true });
    }

    /// <summary>Revert a user to their role's default access (drops custom mode).</summary>
    [HttpPut("{id}/reset")]
    public async Task<IActionResult> ResetToRole(string id)
    {
        var result = await _users.UpdateOneAsync(
            u => u.Id == id,
            Builders<User>.Update
                .Set(u => u.UseCustomModuleAccess, false)
                .Set(u => u.AllowedAdminModules, new List<string>()));
        if (result.MatchedCount == 0) return NotFound();
        return Ok(new { id, useCustomModuleAccess = false });
    }
}

