---
import AdminLayout from '../../layouts/AdminLayout.astro';
---
<AdminLayout title="Users & Access" activePage="user-access">

  <div class="page-header">
    <div>
      <div class="page-title">Users &amp; Access</div>
      <div class="page-subtitle">Grant individual login accounts access to specific admin pages — for example, let one instructor open Clients while others cannot.</div>
    </div>
  </div>

  <div class="card" style="margin-bottom:16px;">
    <div class="card-body" style="font-size:13px;color:var(--color-text-muted);line-height:1.5;">
      Tick or untick any page to control exactly what each account can access. Saving switches that account to <strong>custom access</strong> — the ticked pages become the complete list (role defaults no longer apply). Use <strong>Reset to role defaults</strong> to hand control back to the account's role. Changes take effect the next time the user signs in.
    </div>
  </div>

  <div id="accessList"><div class="card"><div class="card-body text-muted">Loading accounts…</div></div></div>

</AdminLayout>

<script is:inline>
  (function () {
    var API = document.querySelector('.app-shell');
    API = (API && API.dataset && API.dataset.apiBase) || '';
    var token = localStorage.getItem('token') || '';
    var MODULES = [];
    var ROLE_DEFAULTS = {}; // roleKey -> Set of module keys (locked)

    function esc(s) {
      return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
        return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
      });
    }

    function headers() {
      return { 'Content-Type': 'application/json', Authorization: 'Bearer ' + token };
    }

    // Best-effort: pull role → default modules so we can show (locked) role grants.
    async function loadRoleDefaults() {
      try {
        var res = await fetch(API + '/api/settings', { headers: headers() });
        if (!res.ok) return;
        var s = await res.json();
        var list = s.roleAccessSettings || s.RoleAccessSettings || [];
        list.forEach(function (r) {
          var key = (r.roleKey || r.RoleKey || '').toLowerCase();
          var mods = (r.enabledModuleKeys || r.EnabledModuleKeys || []).map(function (m) { return String(m).toLowerCase(); });
          ROLE_DEFAULTS[key] = new Set(mods);
        });
      } catch (e) { /* non-fatal — role columns just won't pre-lock */ }
    }

    function renderUser(u) {
      var roleKey = (u.role || '').toLowerCase();
      var roleSet = ROLE_DEFAULTS[roleKey] || new Set();
      var grants = new Set((u.allowedAdminModules || []).map(function (m) { return String(m).toLowerCase(); }));

      var checks = MODULES.map(function (m) {
        var isRoleDefault = roleSet.has(m.key);
        var isGranted = grants.has(m.key);
        var checked = isRoleDefault || isGranted;
        var disabled = isRoleDefault; // role-provided access can't be revoked here
        return (
          '<label class="access-mod" style="display:flex;align-items:center;gap:8px;padding:7px 10px;border:1px solid var(--color-border-subtle);border-radius:8px;font-size:13px;' +
          (disabled ? 'opacity:.6;' : 'cursor:pointer;') + '">' +
          '<input type="checkbox" data-mod="' + esc(m.key) + '" ' + (checked ? 'checked' : '') + ' ' + (disabled ? 'disabled' : '') + ' style="width:15px;height:15px;" />' +
          '<span>' + esc(m.label) + (isRoleDefault ? ' <span style="font-size:10px;color:var(--color-text-muted);">(role)</span>' : '') + '</span>' +
          '</label>'
        );
      }).join('');

      return (
        '<div class="card user-access-card" data-user="' + esc(u.id) + '" style="margin-bottom:14px;">' +
        '<div class="card-body">' +
        '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap;margin-bottom:12px;">' +
        '<div><div style="font-weight:700;font-size:15px;">' + esc(u.name || '(no name)') + '</div>' +
        '<div style="font-size:12px;color:var(--color-text-muted);">' + esc(u.email || '') + ' · <span style="text-transform:capitalize;">' + esc(u.role || '') + '</span></div></div>' +
        '<button class="btn btn-primary btn-sm access-save" data-user="' + esc(u.id) + '">Save</button>' +
        '</div>' +
        '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:8px;">' + checks + '</div>' +
        '<div class="access-status" style="font-size:12px;margin-top:8px;height:16px;"></div>' +
        '</div></div>'
      );
    }

    async function save(card) {
      var userId = card.getAttribute('data-user');
      var mods = [];
      card.querySelectorAll('input[type=checkbox][data-mod]').forEach(function (cb) {
        // Only send explicit (non-role, non-disabled) grants; role defaults stay implicit.
        if (cb.checked && !cb.disabled) mods.push(cb.getAttribute('data-mod'));
      });
      var status = card.querySelector('.access-status');
      status.textContent = 'Saving…';
      status.style.color = 'var(--color-text-muted)';
      try {
        var res = await fetch(API + '/api/user-access/' + userId + '/modules', {
          method: 'PUT', headers: headers(),
          body: JSON.stringify({ allowedAdminModules: mods })
        });
        if (!res.ok) throw new Error('save failed');
        status.textContent = 'Saved — user must sign in again for changes to apply.';
        status.style.color = 'var(--color-success, #16a34a)';
      } catch (e) {
        status.textContent = 'Could not save. Try again.';
        status.style.color = 'var(--color-danger, #dc2626)';
