cd /opt/soulpilates; MU=$(grep '^MONGO_USER=' prod.env|cut -d= -f2); MP=$(grep '^MONGO_PASSWORD=' prod.env|cut -d= -f2)
B=$(cat /tmp/claude-0/-root/f1b1af7e-43da-44b8-92b2-51e4d240617b/scratchpad/bookings.json)
docker exec soulpilates-prod-mongo mongosh -u "$MU" -p "$MP" --authenticationDatabase admin soulpilates --quiet --eval '
var bookings = '"$B"';
print("=== CLIENT MATCH (by email) ===");
var seen={};
bookings.forEach(function(b){
  if(seen[b.email]) return; seen[b.email]=1;
  var c=db.Clients.findOne({Email:{$regex:"^"+b.email.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")+"$",$options:"i"}});
  print((c?"EXISTING":"NEW     ")+"  "+b.email+"  ("+b.name+")"+(c?" -> "+c.FullName:""));
});
print("=== SESSION MATCH ===");
var nomatch=0;
bookings.forEach(function(b){
  var s=db.CalendarSessions.findOne({StartTime:new Date(b.utc), Format:b.format});
  if(!s){ nomatch++; print("NO MATCH  "+b.localdate+" "+b.localstart+" "+b.format+" ("+b.name+")"); }
});
print("unmatched sessions: "+nomatch+" / "+bookings.length);
'

cd /opt/soulpilates; MU=$(grep '^MONGO_USER=' prod.env|cut -d= -f2); MP=$(grep '^MONGO_PASSWORD=' prod.env|cut -d= -f2)
B=$(cat /tmp/claude-0/-root/f1b1af7e-43da-44b8-92b2-51e4d240617b/scratchpad/bookings.json)
docker exec soulpilates-prod-mongo mongosh -u "$MU" -p "$MP" --authenticationDatabase admin soulpilates --quiet --eval '
var bookings = '"$B"';
var now=new Date();
function esc(s){return s.replace(/[.*+?^${}()|[\]\\]/g,"\\$&");}
// 1) Resolve/create clients keyed by email
var clientId={}, created=0, reused=0;
bookings.forEach(function(b){
  if(clientId[b.email]) return;
  var c=db.Clients.findOne({Email:{$regex:"^"+esc(b.email)+"$",$options:"i"}});
  if(c){ clientId[b.email]=c._id; reused++; }
  else{
    var doc={FullName:b.name||b.email, Email:b.email, PhoneNumber:b.phone||null,
      CountryOfOrigin:b.country||"Vietnam", ContactPlatform:"EMAIL",
      InternalNotes:"Imported from SimplyBook (upcoming bookings) 2026-07-03",
      Tags:["Imported","SimplyBook"], LifetimeValue:NumberDecimal("0"),
      IsStudioRentalProfile:false, CreatedAt:now};
    var r=db.Clients.insertOne(doc); clientId[b.email]=r.insertedId; created++;
  }
});
print("clients: created="+created+" reused="+reused);
// 2) Insert attendances (idempotent by BookingReference), collect affected sessions
var ins=0, skip=0, nomatch=0; var affected={};
bookings.forEach(function(b){
  var ref="SBK-"+b.code;
  if(db.Attendances.findOne({BookingReference:ref})){ skip++; return; }
  var s=db.CalendarSessions.findOne({StartTime:new Date(b.utc), Format:b.format});
  if(!s){ nomatch++; print("NO MATCH "+b.localdate+" "+b.localstart+" "+b.format); return; }
  db.Attendances.insertOne({
    CalendarSessionId:s._id, ClientId:clientId[b.email], ClientName:b.name,
    ClientEmail:b.email, ClientPhone:b.phone||null, Status:"BOOKED",
    IsFreeClass:false, CountsTowardsCommission:true, Quantity:1,
    BookedAt:now, BookingReference:ref, BookingSource:"ADMIN", CreatedAt:now
  });
  ins++; affected[s._id.toString()]=s._id;
});
print("attendances: inserted="+ins+" skipped(existing)="+skip+" nomatch="+nomatch);
// 3) Resync CurrentBookings on affected sessions
var over=0;
Object.keys(affected).forEach(function(k){
  var sid=affected[k];
  var cnt=db.Attendances.countDocuments({CalendarSessionId:sid, Status:{$nin:["CANCELLED","LATE_CANCEL","NO_SHOW"]}});
  db.CalendarSessions.updateOne({_id:sid},{$set:{CurrentBookings:cnt}});
  var s=db.CalendarSessions.findOne({_id:sid},{Capacity:1});
  if(cnt>s.Capacity){ over++; print("OVER  "+sid+" bookings="+cnt+" cap="+s.Capacity); }
});
print("sessions updated: "+Object.keys(affected).length+" overbooked="+over);
'

cd /opt/soulpilates; MU=$(grep '^MONGO_USER=' prod.env|cut -d= -f2); MP=$(grep '^MONGO_PASSWORD=' prod.env|cut -d= -f2); docker exec soulpilates-prod-mongo mongosh -u "$MU" -p "$MP" --authenticationDatabase admin soulpilates --quiet --eval '
print("imported attendances: "+db.Attendances.countDocuments({BookingReference:/^SBK-/}));
print("clients total now: "+db.Clients.countDocuments({}));
print("=== sample booked sessions ===");
db.CalendarSessions.find({CurrentBookings:{$gt:0}, StartTime:{$gte:new Date()}}).sort({StartTime:1}).limit(6).forEach(function(s){
  var names=db.Attendances.find({CalendarSessionId:s._id,BookingReference:/^SBK-/}).toArray().map(function(a){return a.ClientName;});
  print("  "+s.StartTime.toISOString().slice(0,16)+" "+s.ClassName+" ("+s.Format+") "+s.CurrentBookings+"/"+s.Capacity+" -> "+names.join(", "));
});
'

cd /opt/soulpilates; MU=$(grep '^MONGO_USER=' prod.env|cut -d= -f2); MP=$(grep '^MONGO_PASSWORD=' prod.env|cut -d= -f2); docker exec soulpilates-prod-mongo mongosh -u "$MU" -p "$MP" --authenticationDatabase admin soulpilates --quiet --eval '
// Find duplicate (session, client) among imported bookings, keep earliest _id, delete rest
var dupes=db.Attendances.aggregate([
  {$match:{BookingReference:/^SBK-/}},
  {$group:{_id:{s:"$CalendarSessionId",c:"$ClientId"}, ids:{$push:"$_id"}, refs:{$push:"$BookingReference"}, n:{$sum:1}}},
  {$match:{n:{$gt:1}}}
]).toArray();
var removed=0, affected={};
dupes.forEach(function(d){
  print("dup: client="+d._id.c+" session="+d._id.s+" refs="+d.refs.join(",")+" -> keeping 1");
  d.ids.slice(1).forEach(function(id){ db.Attendances.deleteOne({_id:id}); removed++; });
  affected[d._id.s.toString()]=d._id.s;
});
print("duplicate attendances removed: "+removed);
// Resync affected session counts
Object.keys(affected).forEach(function(k){
  var sid=affected[k];
  var cnt=db.Attendances.countDocuments({CalendarSessionId:sid, Status:{$nin:["CANCELLED","LATE_CANCEL","NO_SHOW"]}});
  db.CalendarSessions.updateOne({_id:sid},{$set:{CurrentBookings:cnt}});
});
print("imported attendances now: "+db.Attendances.countDocuments({BookingReference:/^SBK-/}));
'

