  var imp=db.Attendances.countDocuments({CalendarSessionId:s._id,BookingReference:/^SBK-/});
  print(s.StartTime.toISOString().slice(0,16)+" "+s.ClassName+" "+s.CurrentBookings+"/"+s.Capacity+" (imported SBK here: "+imp+", origin "+s.Origin+")");
