'

cd /opt/soulpilates; MU=$(grep '^MONGO_USER=' prod.env|cut -d= -f2); MP=$(grep '^MONGO_PASSWORD=' prod.env|cut -d= -f2)
B=$(cat /tmp/claude-0/-root/f1b1af7e-43da-44b8-92b2-51e4d240617b/scratchpad/bookings.json)
docker exec soulpilates-prod-mongo mongosh -u "$MU" -p "$MP" --authenticationDatabase admin soulpilates --quiet --eval '
var bookings = '"$B"';
var now=new Date();
function esc(s){return s.replace(/[.*+?^${}()|[\]\\]/g,"\\$&");}
var clientId={};
bookings.forEach(function(b){ if(clientId[b.email])return; var c=db.Clients.findOne({Email:{$regex:"^"+esc(b.email)+"$",$options:"i"}}); if(c)clientId[b.email]=c._id; });
var ins=0,skip=0,affected={};
bookings.forEach(function(b){
  var ref="SBK-"+b.code;
  if(db.Attendances.findOne({BookingReference:ref})){skip++;return;}
  var s=db.CalendarSessions.findOne({StartTime:new Date(b.utc),Format:b.format});
  db.Attendances.insertOne({CalendarSessionId:s._id,ClientId:clientId[b.email],ClientName:b.name,ClientEmail:b.email,ClientPhone:b.phone||null,Status:"BOOKED",IsFreeClass:false,CountsTowardsCommission:true,Quantity:1,BookedAt:now,BookingReference:ref,BookingSource:"ADMIN",CreatedAt:now});
  ins++; affected[s._id.toString()]=s._id;
});
Object.keys(affected).forEach(function(k){var sid=affected[k];var cnt=db.Attendances.countDocuments({CalendarSessionId:sid,Status:{$nin:["CANCELLED","LATE_CANCEL","NO_SHOW"]}});db.CalendarSessions.updateOne({_id:sid},{$set:{CurrentBookings:cnt}});});
print("re-inserted="+ins+" skipped="+skip+" total imported now="+db.Attendances.countDocuments({BookingReference:/^SBK-/}));
'

