var n=db.Staff.findOne({Name:/Nhi/i});
print("=== Nhi staff commission fields ===");
printjson({id:n._id,Name:n.Name,CommissionModel:n.CommissionModel,FlatPrivateCommissionPct:n.FlatPrivateCommissionPct,HasTieredPrivateCommission:n.HasTieredPrivateCommission,Tiers:n.Tiers,BaseRate:n.BaseRate,GroupFlatRatePerClass:n.GroupFlatRatePerClass});
print("=== StaffRateRevisions for Nhi ===");
db.StaffRateRevisions.find({StaffId:n._id.toString()}).forEach(function(r){printjson(r);});
print("(also try ObjectId match)");
db.StaffRateRevisions.find({StaffId:n._id}).forEach(function(r){printjson(r);});
'

