function bindTierInputs() {
  const list = document.getElementById("tierList");
  list.querySelectorAll(".tier-rate").forEach((el) =>
    el.addEventListener("change", (e) => {
      tiers[e.target.dataset.idx].rate = parseFloat(e.target.value) || 0;
    }),
  );
  list.querySelectorAll(".tier-cap").forEach((el) =>
    el.addEventListener("change", (e) => {
      tiers[e.target.dataset.idx].cap = parseInt(e.target.value) || 0;
    }),
  );
}

document.getElementById("tierList").addEventListener("change", bindTierInputs);
renderTiers();

