input.new_string:
// Sync the tier inputs' current DOM values into the `tiers` state array.
// Runs on every edit (delegated 'input'/'change') AND is called right before
// save, so the value the user typed is never lost. (Previously this only
// *attached* listeners on change, so the first edit to a rate was dropped —
// e.g. changing 20% → 25% silently saved the old 20%.)
function bindTierInputs() {
  const list = document.getElementById("tierList");
  list.querySelectorAll(".tier-rate").forEach((el) => {
    tiers[el.dataset.idx].rate = parseFloat(el.value) || 0;
  });
  list.querySelectorAll(".tier-cap").forEach((el) => {
    tiers[el.dataset.idx].cap = parseInt(el.value) || 0;
  });
}

document.getElementById("tierList").addEventListener("input", bindTierInputs);
document.getElementById("tierList").addEventListener("change", bindTierInputs);

