var items = attendances.Select(att =>
{
    CalendarSession? sess = null;
    if (!string.IsNullOrWhiteSpace(att.CalendarSessionId))
        sessionMap.TryGetValue(att.CalendarSessionId, out sess);

    var paid = att.AmountPaid ?? 0m;
    var due = att.AmountDueAtStudio ?? 0m;

    // When a linked invoice exists, use its status as the source of truth.
    // The Attendance fields may be stale if the remaining balance was
    // settled via POS invoice-payment flow (which updates the Invoice but
    // may not have synced back to Attendance for legacy records).
    if (invoiceStatusMap.TryGetValue(att.Id!, out var invStatus))
    {
        if (invStatus.status == "PAID")
        {
            paid = invStatus.totalNet;
            due = 0m;
        }
    }

    string payStatus;
    if (att.IsFreeClass) payStatus = "free";
    else if (att.PaymentMethod == "PACKAGE_CREDIT") payStatus = "paid";
    else if (due <= 0) payStatus = "paid";
    else if (paid > 0 && due > 0) payStatus = "partial";
    else payStatus = "unpaid";

    invoiceLinkMap.TryGetValue(att.Id!, out var invLink);

