cd /opt/soulpilates; MU=$(grep '^MONGO_USER=' prod.env|cut -d= -f2); MP=$(grep '^MONGO_PASSWORD=' prod.env|cut -d= -f2); docker exec soulpilates-prod-mongo mongosh -u "$MU" -p "$MP" --authenticationDatabase admin soulpilates --quiet --eval '
var upd=0;
db.Attendances.find({BookingReference:/^SBK-/}).forEach(function(a){
  var s=db.CalendarSessions.findOne({_id:a.CalendarSessionId},{Format:1});
  var due = (s && s.Format=="PRIVATE") ? NumberDecimal("850000") : NumberDecimal("500000");
  db.Attendances.updateOne({_id:a._id},{$set:{
    PaymentMethod:"PAY_AT_STUDIO",
    AmountPaid:NumberDecimal("0"),
    AmountDueAtStudio:due
  }});
  upd++;
});
print("attendances marked pay-at-studio / unpaid: "+upd);
print("=== verify status breakdown ===");
var paid=0,unpaid=0;
db.Attendances.find({BookingReference:/^SBK-/}).forEach(function(a){
  var due=a.AmountDueAtStudio||0, p=a.AmountPaid||0;
  var st = a.IsFreeClass?"free":(a.PaymentMethod=="PACKAGE_CREDIT"?"paid":(due<=0?"paid":(p>0?"partial":"unpaid")));
  if(st=="unpaid")unpaid++;else paid++;
});
print("unpaid="+unpaid+" other="+paid);
'

