    var (refunded, hasLedgerTrail) = await _walletService.RefundCreditByAttendanceWithTrailAsync(booking.Id!);
    if (!refunded && !hasLedgerTrail && !string.IsNullOrEmpty(booking.PackageInstanceId))
    {
