        // a carried reschedule), so the deduction nets to zero and can't be
        // re-refunded later (SPM-108).
        await _walletService.RefundCreditAsync(
            booking.PackageInstanceId, booking.RescheduledFromAttendanceId ?? booking.Id!);
    }
}

