/// <summary>Cheap canonical-key → display-label converter, e.g. <c>"BANK_TRANSFER" → "Bank Transfer"</c>.</summary>
private static string Humanise(string raw)
{
    if (string.IsNullOrEmpty(raw)) return raw;
    var lower = raw.Replace('_', ' ').ToLowerInvariant();
    return System.Globalization.CultureInfo.InvariantCulture.TextInfo.ToTitleCase(lower);
}

