public async Task<PaybackSummaryDto> GetPaybackSummaryAsync()
{
    // Two parallel reads — capital list is tiny (≤ a few dozen rows even
    // years from now); washout list is at most one-row-per-month-since-launch.
    // Sequential awaits keep the ordering deterministic for tests without a
    // measurable cost.
    var capital = await _capital.Find(_ => true).ToListAsync();
    var washouts = await _washouts.Find(_ => true).ToListAsync();

    var initial = capital.Where(c => c.IsPreOpening).Sum(c => c.PurchaseAmount);

