// -- Session popup interaction ---------------------------------------
function _showPosSessionPopup(e, session) {
  if (!selectedClient) {
    window.showToast && window.showToast('Select a client first to interact with classes', 'warning');
    return;
  }
  const pop = document.getElementById('posSessionPopup');
  const content = document.getElementById('posSessionPopupContent');
  const st = new Date(session.startTime), et = new Date(session.endTime);
  const dayStr = st.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
  const timeStr = `${_posFmtTime(st)} - ${_posFmtTime(et)}`;
  const spotsLeft = Math.max(0, (session.capacity || 0) - (session.currentBookings || 0));

  // Find ALL of the client's bookings for this session (may be >1 when additional walk-in seats were added)
  const clientBookings = _posCalClientBookings.filter(b =>
    b.calendarSessionId === session.id &&
    b.status !== 'CANCELLED' && b.status !== 'NO_SHOW' && b.status !== 'LATE_CANCEL'
  );
  // Keep backward-compat alias for the walk-in button guard
  const clientBooking = clientBookings.length > 0 ? clientBookings[0] : null;

  let bookingHtml = '';
  if (clientBookings.length > 0) {
    bookingHtml = clientBookings.map(cb => {
      const amountDue = cb.amountDueAtStudio || 0;
      // Paid = free class, package-credit, no outstanding balance, or actual money paid
      const isPaid = cb.isFreeClass ||
        cb.paymentMethod === 'PACKAGE_CREDIT' ||
        amountDue <= 0 ||
        (cb.amountPaid && cb.amountPaid > 0);
      const qtyLabel = (cb.quantity ?? 1) > 1 ? ` ×${cb.quantity}` : '';
      return `
        <div class="pos-popup-session-card" style="margin-top:8px;">
          <div style="font-size:11px;font-weight:600;color:var(--color-text-primary);margin-bottom:4px;">📋 ${_posEsc(selectedClient.name)}'s Booking${qtyLabel}</div>
          <div style="display:flex;justify-content:space-between;align-items:center;">
            <div style="font-size:10px;color:var(--color-text-muted);">Ref: ${_posEsc(cb.bookingReference || cb.attendanceId?.substring(0,8))}</div>
            <span style="font-size:10px;font-weight:600;color:${isPaid ? 'var(--color-success)' : 'var(--color-warning)'}">${isPaid ? '✅ Paid' : '⚠️ Unpaid'}</span>
          </div>
          ${!isPaid ? `<button class="pos-popup-action-btn primary" style="margin-top:8px;" onclick="addCollectPaymentToCart('${cb.attendanceId}', '${session.id}', ${amountDue}, '${_posEsc(session.className)}', '${dayStr} ${_posFmtTime(st)}', '${_posEsc(session.instructorName || '')}', '${(cb.format || session.format || 'GROUP').toUpperCase()}')">
            💰 Add to Cart — Collect ${amountDue > 0 ? amountDue.toLocaleString() + ' ₫' : 'Payment'}
          </button>` : '<div style="font-size:10px;color:var(--color-success);margin-top:6px;">Payment already collected ✓</div>'}
        </div>
      `;

