// ── Class-first checkout roster ──────────────────────────────────────
// Clicking a class on the POS Classes tab opens its full roster so the whole
// class can be checked in + collected inline, with no per-client POS round-trip.
let _posRoster = { session: null };

async function openClassRoster(session) {
  _posRoster.session = session;
  const st = new Date(session.startTime), et = new Date(session.endTime);
  document.getElementById('posRosterTitle').textContent = session.className || 'Class';
  document.getElementById('posRosterSub').textContent =
    `${st.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'})} · ${_posFmtTime(st)}–${_posFmtTime(et)} · ${_posEsc(session.instructorName||'—')}`;
  document.getElementById('posRosterBody').innerHTML =
    '<div style="text-align:center;color:var(--color-text-muted);padding:30px;">Loading…</div>';
  document.getElementById('posRosterModal').classList.add('open');
  await _refreshRoster();
}
window.openClassRoster = openClassRoster;

function closePosRoster(){ document.getElementById('posRosterModal').classList.remove('open'); }
window.closePosRoster = closePosRoster;

async function _refreshRoster() {
  const sid = _posRoster.session?.id;
  if (!sid) return;
  try {
    const detail = await fetch(`${API}/api/scheduling/class/${sid}`,
      { headers: { Authorization: 'Bearer ' + token } }).then(r => r.json());
    _renderRoster(detail);
  } catch (e) {
    document.getElementById('posRosterBody').innerHTML =
      '<div style="text-align:center;color:var(--color-danger);padding:30px;">Could not load roster.</div>';
  }
}

const _ROSTER_METHODS = ['CASH:Cash','BANK_TRANSFER:Bank Transfer','MOMO:MoMo','ZALO_PAY:ZaloPay','CREDIT_CARD:Credit Card','WISE:Wise','STRIPE:Stripe'];
function _rosterMethodOptions(){ return _ROSTER_METHODS.map(m=>{const [v,l]=m.split(':');return `<option value="${v}">${l}</option>`;}).join(''); }

function _renderRoster(detail) {
  const drop = detail.dropInPrice || _posRoster.session?.dropInPrice || 0;
  const atts = (detail.attendees || []).filter(a => a.status !== 'CANCELLED' && a.status !== 'LATE_CANCEL');
  let settledCount = 0, unpaidCount = 0, dueTotal = 0;
  const rows = atts.map(a => {
    const ps = a.paymentStatus || 'unpaid';
    const settled = ps === 'paid' || ps === 'free';
    const arrived = ['ARRIVED','CHECKED_IN','COMPLETED'].includes(a.status);
    const due = a.amountDueAtStudio || 0;
    if (settled) settledCount++; else { unpaidCount++; dueTotal += (due || drop); }
    const badge = settled
      ? `<span style="color:var(--color-success);font-size:11px;font-weight:700;">${ps==='free'?'Free':'✅ Paid'}</span>`
      : `<span style="color:var(--color-warning);font-size:11px;font-weight:700;">⚠️ ${ps==='partial'?'Partial':'Unpaid'}</span>`;
    const checkBtn = `<button class="btn btn-ghost btn-sm" style="font-size:10px;padding:3px 8px;${arrived?'color:var(--color-success);border-color:var(--color-success);':''}" onclick="posCheckIn('${a.attendanceId}')">${arrived?'✓ Checked in':'Check in'}</button>`;
    const controls = settled ? '' : `
      <div style="display:flex;gap:6px;align-items:center;margin-top:8px;flex-wrap:wrap;">
        <select class="form-control roster-method" style="width:auto;font-size:11px;padding:4px 8px;">${_rosterMethodOptions()}</select>
        <input type="number" class="form-control roster-amount" value="${due||drop}" style="width:110px;font-size:11px;padding:4px 8px;" />
        <button class="btn btn-primary btn-sm" style="font-size:11px;padding:4px 12px;" onclick="posCollectOne('${a.attendanceId}',this)">Collect</button>
        <button class="btn btn-secondary btn-sm" style="font-size:11px;padding:4px 10px;" title="Settle with a package credit" onclick="posUseCredit('${a.attendanceId}',this)">Use credit</button>
      </div>`;
    return `<div class="roster-row" data-att="${a.attendanceId}" data-due="${due||drop}" data-settled="${settled?1:0}"
        style="border:1px solid var(--color-border-subtle);border-radius:10px;padding:10px 12px;margin-bottom:8px;">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;">
        <div>
          <div style="font-weight:600;font-size:13px;">${_posEsc(a.clientName||'Unknown')}${(a.quantity??1)>1?` <span style="font-size:10px;color:var(--color-brand-accent);font-weight:700;">×${a.quantity}</span>`:''}</div>
          <div style="font-size:11px;color:var(--color-text-muted);">${!settled&&(due||drop)>0?(due||drop).toLocaleString()+' ₫ due':''}</div>
        </div>
        <div style="display:flex;flex-direction:column;align-items:flex-end;gap:5px;">${badge}${checkBtn}</div>
      </div>${controls}
    </div>`;
  }).join('');
  document.getElementById('posRosterBody').innerHTML = rows ||
    '<div style="text-align:center;color:var(--color-text-muted);padding:24px;">No attendees booked in this class.</div>';
  document.getElementById('posRosterTotals').textContent =
    `${settledCount} settled · ${unpaidCount} to collect${dueTotal>0?` · ${dueTotal.toLocaleString()} ₫ due`:''}`;
  const allBtn = document.getElementById('posRosterCollectAll');
  if (allBtn) allBtn.style.display = unpaidCount > 0 ? '' : 'none';
}

async function _rosterCollect(attendanceId, amount, method, notes) {
  try {
    const r = await fetch(`${API}/api/scheduling/booking/${attendanceId}/collect-payment`, {
      method: 'POST', headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' },
      body: JSON.stringify({ amount, paymentMethod: method, notes: notes || null }),
    });
    if (!r.ok) {
      let msg = 'HTTP ' + r.status;
      try { const b = await r.clone().json(); msg = b.detail || b.message || msg; } catch {}
      window.showToast && window.showToast(msg, 'error');
      return false;
    }
    return true;
  } catch (e) { window.showToast && window.showToast('Could not collect payment', 'error'); return false; }
}

async function posCheckIn(attendanceId, silent) {
  try {
    await fetch(`${API}/api/scheduling/booking/${attendanceId}/status`, {
      method: 'PATCH', headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' },
      body: JSON.stringify({ status: 'ARRIVED' }),
    });
  } catch (e) {}
