async _mposLoadCredits(clientId) {
  const el = document.getElementById('mposCredits');
  try {
    const pkgs = await fetch(`${_CDP_API}/api/wallet/client/${clientId}`,
      { headers: { Authorization: 'Bearer ' + this._getToken() } }).then(r => r.json());
    const active = (pkgs || []).filter(p => (p.status === 'ACTIVE' || p.status === 'LOW_BALANCE') && (p.creditsRemaining ?? 0) > 0);
    const sum = f => active.filter(p => (p.format || '').toUpperCase() === f).reduce((s, p) => s + (p.creditsRemaining ?? 0), 0);
    const g = sum('GROUP'), m = sum('MAT'), pv = sum('PRIVATE');
    if (this._mpos) this._mpos._credits = { group: g, mat: m, private: pv };
    const chip = (label, n, color) => n > 0
      ? `<span style="font-size:11px;font-weight:600;padding:3px 9px;border-radius:999px;background:${color}22;color:${color};border:1px solid ${color}55;">${label}: ${n}</span>` : '';
    const chips = [chip('Group', g, '#2BB7A3'), chip('Mat', m, '#63b3ed'), chip('Private', pv, '#F4923C')].filter(Boolean).join('');
    if (chips) {
      el.innerHTML = `<span style="font-size:10px;color:var(--color-text-muted);align-self:center;">Credits</span>${chips}`;
      el.style.display = 'flex';
    } else {
      el.innerHTML = '<span style="font-size:11px;color:var(--color-text-muted);">No package credits on file</span>';
      el.style.display = 'flex';
    }
  } catch { el.style.display = 'none'; }
},

