/* ── SPM-112: Mobile sidebar drawer ──────────────────────────────
   The global stylesheet hides .sidebar at ≤768px and reveals the
   .hamburger-btn. Instructor pages have no bottom-nav fallback, so
   the hamburger slides the full sidebar in as a fixed overlay drawer.
   Scoped to this layout via is:global so AdminLayout is unaffected. */
.sidebar-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.45);
  backdrop-filter: blur(2px);
  z-index: 150;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease;
}
.sidebar-backdrop.open {
  opacity: 1;
  pointer-events: auto;
}
@media (max-width: 768px) {
  /* Override the global `display:none` only while the drawer is open. */
  .sidebar.mobile-open {
    display: flex;
    position: fixed;
    top: 0;
    left: 0;
    bottom: 0;
    width: var(--sidebar-width);
    min-width: var(--sidebar-width);
    max-width: 85vw;
    height: 100vh;
    height: 100dvh;
    z-index: 250;
    box-shadow: 4px 0 24px rgba(0, 0, 0, 0.35);
    overflow-y: auto;
    animation: instructorDrawerIn 0.28s cubic-bezier(0.16, 1, 0.3, 1);
  }
  /* Drawer shows full-width labels even though the ≤1024px rules
     collapse them; restore the expanded look inside the open drawer. */
  .sidebar.mobile-open .sidebar-logo-text,
  .sidebar.mobile-open .sidebar-logo-sub,
  .sidebar.mobile-open .nav-section-label,
  .sidebar.mobile-open .nav-item-label,
  .sidebar.mobile-open .theme-toggle .nav-item-label {
    opacity: 1;
    width: auto;
    overflow: visible;
  }
  .sidebar.mobile-open .sidebar-logo {
    justify-content: flex-start;
  }
  .sidebar.mobile-open .sidebar-logo > div:last-child {
    display: block;
  }
  .sidebar.mobile-open .nav-item,
  .sidebar.mobile-open .theme-toggle {
    justify-content: flex-start;

