  var token = localStorage.getItem('token');
  if (!token) { window.location.href = '/admin/login'; return; }
  try {
    var payload = JSON.parse(atob(token.split('.')[1]));
    var role = (payload['http://schemas.microsoft.com/ws/2008/06/identity/claims/role'] || payload.role || '').toLowerCase();
    if (role === 'customer') { window.location.href = '/'; return; }
    // Instructors are only allowed into /admin if they hold explicit per-user
    // page grants. We can't know that synchronously (grants live server-side),
    // so flag them and let the management-access fetch below decide: with no
    // granted modules they're bounced to /instructor; otherwise the nav is
    // filtered down to just their granted pages.
    window.__isInstructor = (role === 'instructor');
    // Store role for sidebar filtering
    window.__userRole = role;
  } catch (e) {

