  // (User.AllowedAdminModules). Uses the same management-access endpoint the
  // admin shell uses, plus the module catalog for labels + paths.
  (async function () {
    try {
      var api = (document.querySelector('meta[name="api-url"]') || {}).content || '';
      var token = localStorage.getItem('token') || '';
      if (!token) return;
      var h = { Authorization: 'Bearer ' + token };
      var accessRes = await fetch(api + '/api/management-access', { headers: h });
      if (!accessRes.ok) return;
      var access = await accessRes.json();
      var granted = (access.enabledModuleKeys || []).map(function (m) { return String(m).toLowerCase(); });
      if (!granted.length) return;
      var modRes = await fetch(api + '/api/user-access/modules', { headers: h });
      var catalog = modRes.ok ? await modRes.json() : [];
      var byKey = {};
      catalog.forEach(function (m) { byKey[String(m.key).toLowerCase()] = m; });
      var wrap = document.getElementById('studioPagesNav');
      var html = '';
      granted.forEach(function (k) {
        var m = byKey[k];
        if (!m || !m.path) return;
        html += '<a href="' + m.path + '" class="nav-item">' +
          '<svg class="nav-icon" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M9 18l6-6-6-6"/></svg>' +
          '<span class="nav-item-label">' + (m.label || k) + '</span></a>';
      });
      if (html) {
        wrap.innerHTML = html;
        document.getElementById('studioPagesLabel').style.display = '';
      }
    } catch (e) { /* non-fatal */ }
  })();
</script>

