/// client-profile wallet card.
/// </summary>
[HttpGet("client/{clientId}")]
public async Task<IActionResult> GetForClient(string clientId)
{
    if (string.IsNullOrWhiteSpace(clientId))
        return BadRequest(new { message = "clientId is required." });

    var packages = await _walletService.GetAllPackagesForClientAsync(clientId);

    // Derive frozen state from the entity status + expiry; the legacy
    // wallet card UI consumes `isFrozen` + `frozenUntil` as scalar fields.
    // We treat status == "FROZEN" as authoritative and surface the
    // current ExpiryDate as `frozenUntil` (since FreezePackageAsync
    // extends the expiry by the freeze duration when a freeze is applied).
    return Ok(packages.Select(p => new
    {
        id = p.Id,
        clientId = p.ClientId,
        format = p.Format,
        totalCredits = p.TotalCredits,
        creditsUsed = p.CreditsUsed,
        creditsRemaining = p.CreditsRemaining,
        activationDate = p.ActivationDate,
        expiryDate = p.ExpiryDate,
        status = p.Status,
        isFrozen = string.Equals(p.Status, "FROZEN", StringComparison.OrdinalIgnoreCase),
        frozenUntil = string.Equals(p.Status, "FROZEN", StringComparison.OrdinalIgnoreCase)
            ? (DateTime?)p.ExpiryDate
            : null,
        // Display label — the package entity doesn't carry one today, so
        // we synthesise a sensible default from the format + credits.
        // Future P4-Sxx work can resolve the real product name via the
        // InvoiceLine → Product chain.
        productName = $"{p.Format} package · {p.TotalCredits} credits",
    }));
}

