/// <summary>
/// All ACTIVE packages across every client — powers the Clients page
/// "Packages" tab. Includes the client name so the UI can link back.
/// </summary>
[HttpGet("active-packages")]
public async Task<IActionResult> GetAllActivePackages()
{
    var packages = (await _walletService.GetAllActivePackagesAsync()).ToList();
    var names = (await _clientService.GetAllClientsAsync())
        .Where(c => c.Id != null)
        .ToDictionary(c => c.Id!, c => c.FullName);

    return Ok(packages.Select(p => new
    {
        id = p.Id,
        clientId = p.ClientId,
        clientName = (p.ClientId != null && names.TryGetValue(p.ClientId, out var n)) ? n : "Unknown",
        format = p.Format,
        totalCredits = p.TotalCredits,
        creditsRemaining = p.CreditsRemaining,
        activationDate = p.ActivationDate,
        expiryDate = p.ExpiryDate,
        status = p.Status,
        productName = $"{p.Format} package · {p.TotalCredits} credits",
    }));
}

