  function loadClients(q = '') {
    fetch(`${API}/api/client?search=${encodeURIComponent(q)}`, { headers: { 'Authorization': 'Bearer ' + token } })
      .then(r => r.json()).then(data => { allClients = data; renderPage(1); }).catch(() => {});
  }

  function renderPage(page) {
    const totalPages = Math.ceil(allClients.length / PAGE_SIZE);
    if (page < 1) page = 1;
    if (page > totalPages) page = totalPages || 1;
    currentPage = page;
    const start = (page - 1) * PAGE_SIZE;
    const slice = allClients.slice(start, start + PAGE_SIZE);
    document.getElementById('clientCount').textContent = `${allClients.length} clients`;
    document.getElementById('paginationInfo').textContent = allClients.length
      ? `Showing ${start + 1}–${Math.min(start + PAGE_SIZE, allClients.length)} of ${allClients.length}`
