function loadClients(q = '') {
  fetch(`${API}/api/client?search=${encodeURIComponent(q)}`, { headers: { 'Authorization': 'Bearer ' + token } })
    .then(r => r.json()).then(data => { allClients = data; renderPage(1); }).catch(() => {});
}

function _clEsc(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]));
}

// ── Packages tab ──────────────────────────────────────────────
let _packagesLoaded = false;
function clSwitchTab(tab) {
  document.querySelectorAll('.cl-tab').forEach(b => {
    const on = b.dataset.tab === tab;
    b.classList.toggle('active', on);
    b.style.color = on ? 'var(--color-text-primary)' : 'var(--color-text-muted)';
    b.style.borderBottomColor = on ? 'var(--color-brand-accent)' : 'transparent';
  });
  document.getElementById('clientsView').style.display = tab === 'clients' ? '' : 'none';
  document.getElementById('packagesView').style.display = tab === 'packages' ? '' : 'none';
  if (tab === 'packages' && !_packagesLoaded) { _packagesLoaded = true; loadPackages(); }
}
window.clSwitchTab = clSwitchTab;

function loadPackages() {
  fetch(`${API}/api/wallet/active-packages`, { headers: { Authorization: 'Bearer ' + token } })
    .then(r => (r.ok ? r.json() : Promise.reject(r.status)))
    .then(pkgs => {
      const now = Date.now(), dayMs = 86400000;
      const info = pkgs.map(p => {
        const days = p.expiryDate ? Math.round((new Date(p.expiryDate).getTime() - now) / dayMs) : Infinity;
        const low = (p.creditsRemaining || 0) <= 2;
        const expSoon = days !== Infinity && days <= 14;
        // Lower score = more urgent: whichever runs out first (days, or credits × ~7d of runway).
        const score = Math.min(days === Infinity ? 9999 : days, (p.creditsRemaining || 0) * 7);
        return { ...p, days, low, expSoon, urgent: low || expSoon, score };
      }).sort((a, b) => a.score - b.score);

      const tbody = document.getElementById('packagesTable');
      if (!info.length) {
        tbody.innerHTML = '<tr><td colspan="6" class="text-muted text-sm" style="text-align:center;padding:40px;">No active packages.</td></tr>';
        return;
      }
      tbody.innerHTML = info.map(p => {
        const expTxt = p.days === Infinity
          ? '<span style="color:var(--color-success);">No expiry</span>'
          : new Date(p.expiryDate).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
        const flags = [];
        if (p.expSoon) flags.push(`<span class="badge badge-warning" style="font-size:10px;">⏳ ${p.days <= 0 ? 'Expired' : p.days + 'd left'}</span>`);
        if (p.low) flags.push('<span class="badge badge-danger" style="font-size:10px;">⚠️ Low</span>');
        return `<tr${p.urgent ? ' style="background:rgba(244,146,60,0.07);"' : ''}>
          <td><a href="/admin/client-profile?id=${p.clientId}" style="color:var(--color-brand-accent);font-weight:600;">${_clEsc(p.clientName)}</a></td>
          <td>${_clEsc(p.productName || p.format)}</td>
          <td><strong>${p.creditsRemaining}</strong> / ${p.totalCredits} ${flags.join(' ')}</td>
          <td class="hidden-mobile">${expTxt}</td>
          <td>${_clEsc(p.status || '')}</td>
          <td><button class="btn btn-ghost btn-sm btn-icon" title="View client" onclick="window.location.href='/admin/client-profile?id=${p.clientId}'">→</button></td>
        </tr>`;
      }).join('');
    })
    .catch(() => {
      document.getElementById('packagesTable').innerHTML = '<tr><td colspan="6" class="text-muted text-sm" style="text-align:center;padding:40px;">Could not load packages.</td></tr>';
    });
}

