file.content:
@media (display-mode: standalone) {
  .mobile-bottom-nav {
    height: calc(var(--bottom-nav-height) + env(safe-area-inset-bottom, 0px));
  }

  /* Reserve the full nav height (incl. safe area) below scrollable content. */
  .content-area {
    padding-bottom: calc(var(--bottom-nav-height) + env(safe-area-inset-bottom, 0px) + var(--space-lg)) !important;
  }

  /* Full-bleed calendar page zeroes .content-area padding and scrolls inside
     its own list container — pad that container instead. */
  .content-area:has(.cal-page) {
    padding-bottom: 0 !important;
  }
  #pwaListView {
    padding-bottom: calc(var(--bottom-nav-height) + env(safe-area-inset-bottom, 0px) + 24px) !important;
  }
  /* Lift the calendar FAB above the bottom nav. */
  #pwaFabBtn {
    bottom: calc(var(--bottom-nav-height) + env(safe-area-inset-bottom, 0px) + 16px) !important;
  }
  #pwaFabMenu {
    bottom: calc(var(--bottom-nav-height) + env(safe-area-inset-bottom, 0px) + 80px) !important;
  }
  /* The FAB must never sit on top of an open modal (it covered the
     Create button). Hide it whenever any modal/overlay is open. */
  body:has(.modal-overlay.open) #pwaFab,
  body:has(.cdp-panel.open) #pwaFab,
  body:has(.cdp-drawer.open) #pwaFab {
    display: none !important;
  }

  /* ── Modals / bottom-sheets ──
     On mobile these are bottom-anchored sheets (align-items:flex-end,
     padding:0), so their footer buttons (Cancel / Create / Complete) sat
     behind the fixed nav. Lift the sheet to rest ABOVE the nav and cap its
     height so the footer is always reachable. Applies to every modal in the
     app since they share these classes. */
  .modal-overlay {

