cd /opt/soulpilates; cat >> SoulPilates.Astro/src/styles/global.css <<'CSS'

/* ── Bottom-nav clearance (authoritative, last-wins) ──────────────────
   On any mobile width where the fixed bottom nav is shown, the scrollable
   .content-area must reserve the nav height + iOS home-indicator safe area,
   otherwise the last of the page hides behind the nav. Placed at the very end
   with !important so it beats the earlier prefers-reduced-motion override
   (which reset padding to a flat 24px) and any other breakpoint rule. The
   full-bleed calendar page opts out (it scrolls inside its own container). */
@media (max-width: 768px) {
  .content-area {
    padding-bottom: calc(var(--bottom-nav-height) + env(safe-area-inset-bottom, 0px) + var(--space-lg)) !important;
  }
  .content-area:has(.cal-page) {
    padding-bottom: 0 !important;
  }
}
CSS
