function wireQuantityStepper() {
  const minusBtn = document.getElementById("qtyMinus");
  const plusBtn = document.getElementById("qtyPlus");
  const valueEl = document.getElementById("qtyValue");
  const capEl = document.getElementById("qtyCap");

  const refresh = () => {
    valueEl.textContent = String(quantity);
    const max = spotsRemaining();
    minusBtn.disabled = quantity <= 1;
    plusBtn.disabled = quantity >= max || max <= 1;
    // Surface a typed hint when capacity is the constraint.
    if (max > 0 && max <= 3) {
      capEl.style.display = "block";
      capEl.textContent = t("checkout.quantitySpotsLeft", { n: max });
    } else {
      capEl.style.display = "none";
    }
  };

  minusBtn.addEventListener("click", async () => {
    if (quantity <= 1) return;
    quantity--;
    refresh();
    await loadPaymentOptions();
  });
  plusBtn.addEventListener("click", async () => {
    const max = spotsRemaining();
    if (quantity >= max) return;
    quantity++;
    refresh();
    await loadPaymentOptions();
  });
  refresh();
}

