private async Task SendEmailAsync(string to, string subject, string htmlBody)
    => await SendEmailAsync(to, subject, htmlBody, attachment: null);

private async Task SendEmailAsync(string to, string subject, string htmlBody, Attachment? attachment)
{
    try
    {
        using var client = new SmtpClient(_smtpHost, _smtpPort)
        {
            Credentials = new NetworkCredential(_smtpUser, _smtpPass),
            EnableSsl = true
        };

        using var msg = new MailMessage
        {
            From = new MailAddress(_fromEmail, _fromName),
            Subject = subject,
            Body = htmlBody,
            IsBodyHtml = true
        };
        msg.To.Add(to);

        if (attachment is not null)
            msg.Attachments.Add(attachment);

        await client.SendMailAsync(msg);
    }
    catch (Exception ex)
    {
        // SPM-94 / SPM-127: log but don't throw — an email failure must never break
        // booking or POS checkout, but a swallowed SMTP error must still leave a
        // diagnosable trace. Now routed through the structured logger so failures
        // surface in Serilog/GlitchTip. Swallow semantics unchanged: no rethrow.
        _logger.LogError(ex, "[EmailService] Failed to send to {To} (subject: {Subject})", to, subject);
    }

