using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.DTOs;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.API.Controllers;

// TEMPORARY diagnostic endpoint — fires every transactional email template with
// sample data so all templates can be reviewed in one pass. Gated by a shared
// secret (no JWT needed). REMOVE after testing.
[ApiController]
[Route("api/dev")]
[AllowAnonymous]
public class EmailTestController : ControllerBase
{
    private const string Secret = "SPMAILTEST-9f3a2b7c";
    private readonly IEmailService _email;
    public EmailTestController(IEmailService email) => _email = email;

    [HttpPost("email-test")]
    public async Task<IActionResult> FireAll([FromQuery] string secret, [FromQuery] string to = "jane.customer@example.com")
    {
        if (secret != Secret) return Unauthorized();

        var start = DateTime.UtcNow.Date.AddDays(1).AddHours(1); // tomorrow ~08:00 local
        var end = start.AddMinutes(55);
        var fired = new List<string>();

        await _email.SendBookingConfirmationAsync(to, "Jane Customer", "SP-260703-8001", "Happy Neck & Shoulder", "Nhi", start, "GROUP", end);
        fired.Add("BookingConfirmation");

        await _email.SendWaitlistPromotedAsync(to, "Jane Customer", "SP-260703-8002", "Sculpt Waist", "Nhi", start, "GROUP", end);
        fired.Add("WaitlistPromoted");

        await _email.SendClassReminderAsync(to, "Jane Customer", "SP-260703-8001", "Happy Neck & Shoulder", "Nhi", start, "GROUP", end, "24h");
        fired.Add("ClassReminder-24h");

        await _email.SendClassReminderAsync(to, "Jane Customer", "SP-260703-8001", "Happy Neck & Shoulder", "Nhi", start, "GROUP", end, "1h");
        fired.Add("ClassReminder-1h");

        await _email.SendClassCancelledAsync(to, "Jane Customer", "Flow & Energy", start);
        fired.Add("ClassCancelled");

        await _email.SendVerificationEmailAsync(to, "Jane Customer", "sample-verify-token-123456");
        fired.Add("VerificationEmail");

        await _email.SendPasswordResetEmailAsync(to, "Jane Customer", "sample-reset-token-123456");
        fired.Add("PasswordReset");

        var receipt = new InvoiceReceiptModel
        {
            InvoiceNumber = "SP-INV-260703-0099",
            IssueDate = DateTime.UtcNow,
            Status = "PAID",
            ClientName = "Jane Customer",
            ClientEmail = to,
            Lines = new() { new InvoiceReceiptLine { Description = "10 Group Class Pack", Quantity = 1, UnitPrice = 4250000m, LineTotal = 4250000m } },
            Payments = new() { new InvoiceReceiptPayment { PaymentDate = DateTime.UtcNow, AmountPaid = 4250000m, PaymentMethod = "CASH" } },
            TotalGross = 4250000m,
            TotalNet = 4250000m,
            AmountReceived = 4250000m,
        };
        await _email.SendReceiptAsync(to, "Jane Customer", receipt, System.Text.Encoding.ASCII.GetBytes("%PDF-1.4\n% placeholder receipt for template test\n"));
        fired.Add("Receipt (placeholder PDF)");

        await _email.SendGenericAsync(to, "A quick note from Soul Pilates", "You have an update",
            "This is the generic notification email used as a fallback when push notifications aren't available.",
            "https://new.soulpilates.com.vn/account", "Open my account");
        fired.Add("GenericNotification");

        return Ok(new { sentTo = to, note = "All routed to the test inbox via SMTP test mode.", templatesFired = fired });
    }
}

