using System.Threading.Tasks;
using SoulPilates.Core.DTOs;

namespace SoulPilates.Core.Interfaces;

public interface IEmailService
{
    Task SendBookingConfirmationAsync(string toEmail, string clientName, string bookingReference,
        string className, string instructorName, DateTime classTime, string format,
        DateTime? endTime = null);
    Task SendClassCancelledAsync(string toEmail, string clientName, string className, DateTime classTime);

    /// <summary>
    /// Send a class-reminder email for an upcoming booking. P3-S08 —
    /// dispatched by the hourly <c>BookingReminderBackgroundService</c>.
    /// The implementation attaches an <c>.ics</c> invite reusing the
    /// original booking's UID so calendar clients reconcile rather
    /// than duplicate the event.
    /// </summary>
    /// <param name="reminderWindow">
    /// Window identifier — either <c>"24h"</c> or <c>"1h"</c>. Drives
    /// the subject-line copy (<c>"Tomorrow at the studio"</c> vs
    /// <c>"Class starts in 1 hour"</c>) and the body emphasis.
    /// </param>
    Task SendClassReminderAsync(string toEmail, string clientName, string bookingReference,
        string className, string instructorName, DateTime classTime, string format,
        DateTime? endTime, string reminderWindow);

    Task SendVerificationEmailAsync(string toEmail, string fullName, string token);

    /// <summary>
    /// Send the password-reset deep-link to a customer who triggered the
    /// <c>/forgot-password</c> flow. Same SMTP-disabled silent-noop contract
    /// as the rest of the methods. The reset token is opaque to this method —
    /// callers must persist the matching hash + 24h expiry before invoking.
    /// </summary>
    Task SendPasswordResetEmailAsync(string toEmail, string fullName, string token);

    /// <summary>
    /// Send the studio receipt to the customer with the rendered PDF attached.
    /// Implementations are fire-and-forget safe: when SMTP is disabled, the bytes
    /// are silently dropped so callers can pass <c>_ = SendReceiptAsync(...)</c>
    /// without worrying about throwing in the production-disabled path.
    /// </summary>
    Task SendReceiptAsync(string toEmail, string clientName, InvoiceReceiptModel receipt, byte[] pdfBytes);

    /// <summary>
    /// P4-S02 — Notify the customer that their waitlist entry was promoted
    /// to a reserved seat. Same <c>RESERVED</c>-state semantics as
    /// <see cref="SendBookingConfirmationAsync"/>, with an extra opening
    /// paragraph explaining the promotion. Fires an <c>.ics</c> invite
    /// reusing the (newly-issued) booking reference so the client's
    /// calendar app gets a fresh event entry.
    /// </summary>
    Task SendWaitlistPromotedAsync(string toEmail, string clientName, string bookingReference,
        string className, string instructorName, DateTime classTime, string format,
        DateTime? endTime);

    /// <summary>
    /// P5-PWA — generic styled email used by
    /// <see cref="Services.NotificationPublisher"/> as the fallback
    /// delivery channel when push fails or no devices are registered for
    /// the target user. Same SMTP-disabled silent-noop contract as the
    /// rest of the methods.
    /// </summary>
    /// <param name="toEmail">Recipient address; blank → no-op.</param>
    /// <param name="subject">Bare subject line (no chrome added).</param>
    /// <param name="heading">Big H2 inside the email card. Often matches the push title.</param>
    /// <param name="bodyText">One-line body (already plaintext — will be HTML-encoded).</param>
    /// <param name="ctaUrl">Optional deep-link target — renders a button when supplied.</param>
    /// <param name="ctaLabel">Button label; defaults to "Open in Soul Pilates" when omitted.</param>
    Task SendGenericAsync(string toEmail, string subject, string heading, string bodyText,
        string? ctaUrl = null, string? ctaLabel = null);
}

