/// guaranteeing single use.
/// </summary>
public async Task<bool> ResetPasswordAsync(string token, string newPassword)
{
    if (string.IsNullOrWhiteSpace(token)) return false;
    if (string.IsNullOrWhiteSpace(newPassword) || newPassword.Length < 8) return false;

    var account = await _accounts.Find(a =>
        a.PasswordResetToken == token &&
        a.PasswordResetExpiry > DateTime.UtcNow
    ).FirstOrDefaultAsync();

    if (account == null) return false;

    var update = Builders<CustomerAccount>.Update
        .Set(a => a.PasswordHash, PasswordHasher.Hash(newPassword))
        .Set(a => a.PasswordResetToken, (string?)null)
        .Set(a => a.PasswordResetExpiry, (DateTime?)null)
        .Set(a => a.UpdatedAt, DateTime.UtcNow);

    var result = await _accounts.UpdateOneAsync(a => a.Id == account.Id, update);
    return result.ModifiedCount > 0;
}

