using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.API.Controllers;

/// <summary>
/// Admin-only migration tooling. Sends "activate your account" invites to
/// existing clients so they can set a password on the new system.
/// </summary>
[ApiController]
[Route("api/customer-migration")]
[Authorize(Roles = "Admin,SuperAdmin,Owner")]
public class CustomerMigrationController : ControllerBase
{
    private readonly ICustomerAuthService _customerAuth;

    public CustomerMigrationController(ICustomerAuthService customerAuth)
    {
        _customerAuth = customerAuth;
    }

    public class SendInvitesRequest
    {
        /// <summary>Target a single client by id (testing). Null = all eligible clients.</summary>
        public string? ClientId { get; set; }

        /// <summary>Target a single client by email (testing). Null = all eligible clients.</summary>
        public string? Email { get; set; }

        /// <summary>Re-issue a token + re-send to accounts that exist but haven't activated yet.</summary>
        public bool Resend { get; set; }
    }

    /// <summary>
    /// Send activation invites. With no ClientId/Email this sweeps every client
    /// that has an email and no account yet. In email test mode all mail is
    /// redirected to the test address, so accounts are still created for real —
    /// pass a ClientId/Email to limit a test run to a single record.
    /// </summary>
    [HttpPost("send-invites")]
    public async Task<IActionResult> SendInvites([FromBody] SendInvitesRequest req)
    {
        var result = await _customerAuth.SendActivationInvitesAsync(req?.ClientId, req?.Email, req?.Resend ?? false);
        return Ok(new
        {
            created = result.Created,
            resent = result.Resent,
            skipped = result.Skipped,
            noEmail = result.NoEmail,
        });
    }
}

