381	      // simple — server enforces the actual 8-char minimum.
382	      pwdInput.addEventListener("input", () => {
383	        const v = pwdInput.value;
384	        let score = 0;
385	        if (v.length >= 8) score++;
386	        if (/[A-Z]/.test(v) && /[a-z]/.test(v)) score++;
387	        if (/\d/.test(v) || /[^A-Za-z0-9]/.test(v)) score++;
388	        strengthFill.classList.remove("weak", "medium", "strong");
389	        if (!v) {
390	          strengthLabel.textContent = "Strength: —";
391	          strengthFill.style.width = "0%";
392	          return;
393	        }
394	        if (score <= 1) {
395	          strengthFill.classList.add("weak");
396	          strengthLabel.textContent = "Strength: weak";
397	        } else if (score === 2) {
398	          strengthFill.classList.add("medium");
399	          strengthLabel.textContent = "Strength: good";
400	        } else {
401	          strengthFill.classList.add("strong");
402	          strengthLabel.textContent = "Strength: strong";
403	        }
404	      });
