---
import '../styles/customer.css';
// Reset Password page — paired with /forgot-password and the backend's
// POST /api/customer/reset-password endpoint. The token comes in via the
// query string (?token=...); we don't trust it client-side, only forward
// it to the API for validation.
---

<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Reset Password — Soul Pilates Da Nang</title>
    <meta name="description" content="Set a new password for your Soul Pilates account." />
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link
      href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap"
      rel="stylesheet"
    />
    <link rel="icon" type="image/svg+xml" href="/favicon.svg" />
  </head>
  <body class="sp-customer">
    <div class="sp-auth-page">
      <aside class="sp-auth-aside">
        <div class="sp-auth-aside-content">
          <img
            src="/logo.png"
            alt="Soul Pilates"
            style="height:48px;width:auto;display:block;margin-bottom:var(--sp-space-lg);"
          />
          <h2 class="sp-auth-tagline">
            A fresh start<br />in a few keystrokes.
          </h2>
          <p class="sp-auth-aside-text">
            Pick something memorable but unique — your practice deserves a secure home.
          </p>
        </div>
      </aside>

      <main class="sp-auth-main">
        <div class="sp-auth-card">
          <a href="/login" class="sp-auth-back" aria-label="Back to login">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"
              ><polyline points="15 18 9 12 15 6"></polyline></svg
            >
            <span>Back to login</span>
          </a>

          <!-- Form state -->
          <div id="formState">
            <div class="sp-auth-header">
              <h1 class="sp-heading-page sp-mb-0">Set a new password</h1>
              <p class="sp-text-body sp-text-muted sp-mt-sm">
                Choose a strong password (at least 8 characters). You'll log in with this from now on.
              </p>
            </div>

            <div class="sp-error-msg" id="errorMsg"></div>

            <!-- Missing-token banner — shown immediately if URL has no ?token= -->
            <div class="sp-error-msg" id="missingTokenMsg" style="display:none;">
              This reset link is missing its token. Please
              <a href="/forgot-password" class="sp-link" style="margin-left:2px;">request a new one</a>.
            </div>

            <form id="resetForm" class="sp-auth-form" novalidate>
              <div class="sp-form-group">
                <label class="sp-form-label" for="password">New password</label>
                <div class="sp-password-input">
                  <input
                    type="password"
                    class="sp-form-input"
                    id="password"
                    autocomplete="new-password"
                    placeholder="At least 8 characters"
                    minlength="8"
                    required
                  />
                  <button
                    type="button"
                    class="sp-password-toggle"
                    id="togglePwd"
                    aria-label="Show password"
                  >
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                      <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"></path>
                      <circle cx="12" cy="12" r="3"></circle>
                    </svg>
                  </button>
                </div>
                <!-- Live strength indicator -->
                <div class="sp-strength" id="strength" aria-live="polite">
                  <div class="sp-strength-bar"><div class="sp-strength-fill" id="strengthFill"></div></div>
                  <span class="sp-strength-label" id="strengthLabel">Strength: —</span>
                </div>
              </div>

              <div class="sp-form-group">
                <label class="sp-form-label" for="confirm">Confirm new password</label>
                <input
                  type="password"
                  class="sp-form-input"
                  id="confirm"
                  autocomplete="new-password"
                  placeholder="Re-enter your new password"
                  minlength="8"
                  required
                />
              </div>

              <button
                type="submit"
                class="sp-btn sp-btn-primary sp-btn-lg sp-btn-full"
                id="btnSubmit"
              >
                <span>Update password</span>
              </button>
            </form>
          </div>

          <!-- Success state -->
          <div id="successState" style="display:none;">
            <div class="sp-auth-success-icon" aria-hidden="true">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                <polyline points="20 6 9 17 4 12"></polyline>
              </svg>
            </div>
            <h1 class="sp-heading-page sp-text-center">Password updated</h1>
            <p class="sp-text-body sp-text-muted sp-text-center sp-mt-md">
              You can now log in with your new password. We're glad to have you back.
            </p>
            <a
              href="/login"
              class="sp-btn sp-btn-primary sp-btn-full sp-mt-xl"
              >Go to Log In</a
            >
          </div>
        </div>

        <div class="sp-auth-lang">
          <button class="sp-lang-pill" data-lang="en">English</button>
          <button class="sp-lang-pill" data-lang="vi">Tiếng Việt</button>
        </div>
      </main>
    </div>

    <style is:global>
      body.sp-customer {
        min-height: 100vh;
        background: var(--sp-bg);
      }
      .sp-auth-page {
        min-height: 100vh;
        display: grid;
        grid-template-columns: 1fr 1fr;
      }
      .sp-auth-aside {
        background: linear-gradient(135deg, var(--sp-dark) 0%, #2a1f17 100%);
        color: var(--sp-white);
        display: flex;
        align-items: center;
        justify-content: center;
        padding: var(--sp-space-3xl);
        position: relative;
        overflow: hidden;
      }
      .sp-auth-aside::before {
        content: "";
        position: absolute;
        inset: 0;
        background: radial-gradient(circle at 80% 20%, rgba(212, 165, 116, 0.15) 0%, transparent 50%);
        pointer-events: none;
      }
      .sp-auth-aside-content { position: relative; max-width: 360px; }
      .sp-auth-tagline {
        font-family: 'Inter', -apple-system, sans-serif;
        font-size: 56px;
        font-weight: 500;
        line-height: 1.05;
        margin-top: 32px;
        letter-spacing: -1px;
        color: var(--sp-white);
      }
      .sp-auth-aside-text {
        font-size: 15px;
        color: rgba(255, 255, 255, 0.7);
        margin-top: 24px;
        line-height: 1.6;
      }
      .sp-auth-main {
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        padding: var(--sp-space-2xl);
        background: var(--sp-bg);
      }
      .sp-auth-card {
        background: var(--sp-white);
        border-radius: var(--sp-radius-xl);
        box-shadow: var(--sp-shadow-lg);
        padding: 48px 40px;
        width: 100%;
        max-width: 440px;
        position: relative;
        border: 1px solid var(--sp-border);
      }
      .sp-auth-back {
        position: absolute;
        top: 20px;
        left: 20px;
        display: inline-flex;
        align-items: center;
        gap: 6px;
        color: var(--sp-text-muted);
        text-decoration: none;
        font-size: 13px;
        padding: 6px 8px;
        border-radius: var(--sp-radius-sm);
        transition: color var(--sp-transition-fast);
      }
      .sp-auth-back:hover { color: var(--sp-text-primary); }
      .sp-auth-back svg { width: 14px; height: 14px; }
      .sp-auth-header { text-align: left; margin: 16px 0 32px; }
      .sp-auth-form { display: flex; flex-direction: column; gap: 18px; }
      .sp-link { color: var(--sp-brand); font-weight: 600; text-decoration: none; }
      .sp-link:hover { text-decoration: underline; }
      .sp-auth-lang {
        margin-top: 24px;
        display: flex;
        gap: 4px;
        background: var(--sp-white);
        border: 1px solid var(--sp-border);
        border-radius: var(--sp-radius-full);
        padding: 4px;
      }
      .sp-lang-pill {
        border: none;
        background: none;
        padding: 6px 14px;
        font-size: 12px;
        font-weight: 600;
        color: var(--sp-text-muted);
        cursor: pointer;
        border-radius: var(--sp-radius-full);
        font-family: "Inter", sans-serif;
        transition: all var(--sp-transition-fast);
      }
      .sp-lang-pill.active {
        background: var(--sp-dark);
        color: var(--sp-white);
      }

      /* Password input with eye-toggle */
      .sp-password-input {
        position: relative;
      }
      .sp-password-toggle {
        position: absolute;
        right: 12px;
        top: 50%;
        transform: translateY(-50%);
        background: none;
        border: none;
        cursor: pointer;
        color: var(--sp-text-muted);
        padding: 6px;
        border-radius: var(--sp-radius-sm);
        display: inline-flex;
        align-items: center;
        justify-content: center;
        transition: color var(--sp-transition-fast);
      }
      .sp-password-toggle:hover { color: var(--sp-text-primary); }
      .sp-password-toggle svg { width: 16px; height: 16px; }
      .sp-password-input .sp-form-input { padding-right: 44px; }

      /* Strength meter — 3 bars, transitions on width + color */
      .sp-strength {
        margin-top: 8px;
        display: flex;
        align-items: center;
        gap: 10px;
      }
      .sp-strength-bar {
        flex: 1;
        height: 4px;
        background: var(--sp-border);
        border-radius: 2px;
        overflow: hidden;
      }
      .sp-strength-fill {
        height: 100%;
        width: 0%;
        background: var(--sp-danger);
        border-radius: 2px;
        transition: width 0.3s ease, background 0.3s ease;
      }
      .sp-strength-fill.weak   { width: 33%; background: var(--sp-danger); }
      .sp-strength-fill.medium { width: 66%; background: var(--sp-warning); }
      .sp-strength-fill.strong { width: 100%; background: var(--sp-success); }
      .sp-strength-label {
        font-size: 11px;
        font-weight: 500;
        color: var(--sp-text-muted);
        min-width: 95px;
        text-align: right;
      }

      .sp-auth-success-icon {
        width: 72px;
        height: 72px;
        border-radius: 50%;
        background: var(--sp-success-soft, rgba(61, 140, 92, 0.12));
        color: var(--sp-success);
        display: flex;
        align-items: center;
        justify-content: center;
        margin: 8px auto 24px;
      }
      .sp-auth-success-icon svg { width: 36px; height: 36px; stroke-width: 2.5; }
      .sp-text-center { text-align: center; }
      .sp-mt-md { margin-top: var(--sp-space-md); }
      .sp-mt-xl { margin-top: var(--sp-space-xl); }
      .sp-mt-sm { margin-top: var(--sp-space-sm); }
      .sp-mb-0  { margin-bottom: 0; }

      @media (max-width: 900px) {
        .sp-auth-page { grid-template-columns: 1fr; }
        .sp-auth-aside { display: none; }
        .sp-auth-card {
          padding: 36px 24px;
          box-shadow: none;
          border: none;
          background: transparent;
        }
        .sp-auth-main { padding: var(--sp-space-lg); }
      }
    </style>

    <script>
      import { translatePage, getLocale, setLocale } from "../i18n/index.js";
      const API = import.meta.env.PUBLIC_API_URL;

      translatePage();

      document.querySelectorAll(".sp-lang-pill").forEach((b) => {
        if (b.dataset.lang === getLocale()) b.classList.add("active");
        b.addEventListener("click", () => {
          setLocale(b.dataset.lang);
          window.location.reload();
        });
      });

      // Grab token from ?token= and store in closure. We never trust this
      // client-side — only forward to the API.
      const token = new URLSearchParams(window.location.search).get("token") || "";
      if (!token) {
        document.getElementById("missingTokenMsg").style.display = "flex";
        document.getElementById("btnSubmit").disabled = true;
      }

      const pwdInput = document.getElementById("password");
      const togglePwd = document.getElementById("togglePwd");
      const strengthFill = document.getElementById("strengthFill");
      const strengthLabel = document.getElementById("strengthLabel");
      const form = document.getElementById("resetForm");
      const btn = document.getElementById("btnSubmit");
      const errEl = document.getElementById("errorMsg");

      // Eye toggle — flips both inputs together so the user can compare visually.
      togglePwd.addEventListener("click", () => {
        const t = pwdInput.type === "password" ? "text" : "password";
        pwdInput.type = t;
        document.getElementById("confirm").type = t;
      });

      // Live strength scoring (length + character classes). Intentionally
      // simple — server enforces the actual 8-char minimum.
      pwdInput.addEventListener("input", () => {
        const v = pwdInput.value;
        let score = 0;
        if (v.length >= 8) score++;
        if (/[A-Z]/.test(v) && /[a-z]/.test(v)) score++;
        if (/\d/.test(v) || /[^A-Za-z0-9]/.test(v)) score++;
        strengthFill.classList.remove("weak", "medium", "strong");
        if (!v) {
          strengthLabel.textContent = "Strength: —";
          strengthFill.style.width = "0%";
          return;
        }
        if (score <= 1) {
          strengthFill.classList.add("weak");
          strengthLabel.textContent = "Strength: weak";
        } else if (score === 2) {
          strengthFill.classList.add("medium");
          strengthLabel.textContent = "Strength: good";
        } else {
          strengthFill.classList.add("strong");
          strengthLabel.textContent = "Strength: strong";
        }
      });

      form.addEventListener("submit", async (e) => {
        e.preventDefault();
        const pwd = pwdInput.value;
        const confirm = document.getElementById("confirm").value;

        if (!token) {
          showError("Missing reset token — request a new link from the forgot-password page.");
          return;
        }
        if (pwd.length < 8) {
          showError("Password must be at least 8 characters.");
          return;
        }
        if (pwd !== confirm) {
          showError("The two passwords don't match.");
          return;
        }

        btn.disabled = true;
        const orig = btn.innerHTML;
        btn.innerHTML = "<span>Updating…</span>";

        try {
          const res = await fetch(API + "/api/customer/reset-password", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ token, newPassword: pwd }),
          });
          const data = await res.json().catch(() => ({}));
          if (!res.ok) {
            showError(data.message || "Could not reset password. Please try again.");
            return;
          }
          document.getElementById("formState").style.display = "none";
          document.getElementById("successState").style.display = "block";
        } catch (err) {
          showError("Network error. Please try again.");
        } finally {
          btn.disabled = false;
          btn.innerHTML = orig;
        }
      });

      function showError(msg) {
        errEl.textContent = msg;
        errEl.classList.add("visible");
        setTimeout(() => errEl.classList.remove("visible"), 5000);
      }
    </script>
  </body>
</html>

