using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.Services;

/// <summary>
/// Issue #5 — hosted timer that drives <see cref="IRetentionReminderService.SendDueRemindersAsync"/>.
/// Tick cadence comes from <see cref="Core.Entities.GlobalSettings.RetentionReminderTickHours"/>,
/// re-read on every iteration so an admin edit takes effect on the next loop without restarting
/// the process.
/// </summary>
public class RetentionReminderBackgroundService : BackgroundService
{
    private readonly IServiceProvider _services;
    private readonly ILogger<RetentionReminderBackgroundService> _logger;

    public RetentionReminderBackgroundService(
        IServiceProvider services,
        ILogger<RetentionReminderBackgroundService> logger)
    {
        _services = services;
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            var delayHours = 12; // defensive fallback if settings can't be read on this tick
            try
            {
                using var scope = _services.CreateScope();
                var retention = scope.ServiceProvider.GetRequiredService<IRetentionReminderService>();
                var settings = scope.ServiceProvider.GetRequiredService<ISettingsService>();

                await retention.SendDueRemindersAsync(DateTime.UtcNow, stoppingToken);

                // Read AFTER the dispatch so a freshly-saved cadence change takes
                // effect on the immediate next sleep window.
                var cfg = await settings.GetAsync(stoppingToken);
                if (cfg.RetentionReminderTickHours > 0)
                    delayHours = cfg.RetentionReminderTickHours;
            }
            catch (OperationCanceledException) { throw; }
            catch (Exception ex)
            {
                // Top-level guard — never let a single tick failure tear down the
                // hosted service. Log and continue with the fallback cadence.
                _logger.LogError(ex, "RetentionReminderBackgroundService tick threw");
            }

            await Task.Delay(TimeSpan.FromHours(Math.Clamp(delayHours, 1, 168)), stoppingToken);
        }
    }
}

