    {
        _services = services;
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                using var scope = _services.CreateScope();
                var reminderService = scope.ServiceProvider.GetRequiredService<IReminderService>();
                await reminderService.SendDueRemindersAsync(DateTime.UtcNow, stoppingToken);
            }
            catch (Exception ex)
            {
                // Top-level guard — a fault here would tear down the
                // hosted service for the rest of the process. Log and
                // wait for the next tick.
                _logger.LogError(ex, "BookingReminderBackgroundService tick threw");
            }

            // Hourly cadence. Matches P3-S08 Q3-S08-2 = A (hourly).
            // PackageExpiryBackgroundService uses 12h; this job
            // exercises a tighter window so it runs more often.
            await Task.Delay(TimeSpan.FromMinutes(60), stoppingToken);
        }
    }
}

