using Microsoft.Extensions.Logging;
using MongoDB.Driver;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.Services;

/// <summary>
/// P3-S08 — class-reminder background job.
///
/// <para>
/// Two passes per invocation, one for each reminder window. For each
/// pass: query upcoming sessions in the window, fan out to the
/// attendances on those sessions, send the email, then mark the
/// attendance with the window tag via an atomic <c>$push</c>.
/// </para>
///
/// <para>
/// Send-then-tag ordering: if email dispatch throws, no tag is
/// appended, so the next hourly tick retries the same attendance.
/// Idempotency is durable because the tag lives in MongoDB — process
/// restarts cannot trigger double-sends.
/// </para>
/// </summary>
public class ReminderService : IReminderService
{
    private readonly IMongoCollection<CalendarSession> _sessions;
    private readonly IMongoCollection<Attendance> _attendances;
    private readonly IEmailService _emailService;
    private readonly ILogger<ReminderService> _logger;

    /// <summary>
    /// Canonical window tags. Stored as raw strings on
    /// <see cref="Attendance.RemindersSent"/> rather than as an enum
    /// because adding a third window in the future is a pure data
    /// change — no schema migration, no enum churn.
    /// </summary>
    private const string Tag24h = "24h";
    private const string Tag1h = "1h";

    public ReminderService(
        MongoDbContext dbContext,
        IEmailService emailService,
        ILogger<ReminderService> logger)
    {
        _sessions = dbContext.GetCollection<CalendarSession>("CalendarSessions");
        _attendances = dbContext.GetCollection<Attendance>("Attendances");
        _emailService = emailService;
        _logger = logger;
    }

    public async Task<int> SendDueRemindersAsync(DateTime nowUtc, CancellationToken cancellationToken)
    {
        // 24h window: session start ∈ [now+23h, now+24h).
        // 1h window:  session start ∈ [now+30min, now+1h).
        var sent24 = await DispatchWindowAsync(
            windowTag: Tag24h,
            windowStart: nowUtc.AddHours(23),
            windowEnd: nowUtc.AddHours(24),
            cancellationToken);

        var sent1 = await DispatchWindowAsync(
            windowTag: Tag1h,
            windowStart: nowUtc.AddMinutes(30),
            windowEnd: nowUtc.AddHours(1),
            cancellationToken);

        var total = sent24 + sent1;
        if (total > 0)
            _logger.LogInformation("ReminderService sent {Count} emails ({SentTwentyFour} × 24h, {SentOne} × 1h) at {Now:o}",
                total, sent24, sent1, nowUtc);
        return total;
    }

    private async Task<int> DispatchWindowAsync(
        string windowTag,
        DateTime windowStart,
        DateTime windowEnd,
        CancellationToken ct)
    {
        // Step 1 — sessions starting inside the window. Status filter
        // keeps the query small (a SCHEDULED session is the only one
        // a customer can attend).
        var sessionFilter = Builders<CalendarSession>.Filter.And(
            Builders<CalendarSession>.Filter.Eq(s => s.Status, "SCHEDULED"),
            Builders<CalendarSession>.Filter.Gte(s => s.StartTime, windowStart),
            Builders<CalendarSession>.Filter.Lt(s => s.StartTime, windowEnd));

        var sessions = await _sessions.Find(sessionFilter).ToListAsync(ct);
        if (sessions.Count == 0) return 0;

        var sessionsById = sessions.ToDictionary(s => s.Id);
        var sessionIds = sessionsById.Keys.ToList();

        // Step 2 — qualifying attendances for those sessions.
        // RemindersSent !contains tag covers idempotency; the status
        // filter excludes CANCELLED/LATE_CANCEL/NO_SHOW/RESERVED.
        var attendanceFilter = Builders<Attendance>.Filter.And(
            Builders<Attendance>.Filter.In(a => a.CalendarSessionId, sessionIds),
            Builders<Attendance>.Filter.In(a => a.Status, new[] { "BOOKED", "CHECKED_IN" }),
            Builders<Attendance>.Filter.Ne(a => a.ClientEmail, null),
            Builders<Attendance>.Filter.Not(Builders<Attendance>.Filter.AnyEq(a => a.RemindersSent, windowTag)));

        var attendances = await _attendances.Find(attendanceFilter).ToListAsync(ct);
        if (attendances.Count == 0) return 0;

        var sentCount = 0;
        foreach (var attendance in attendances)
        {
            if (ct.IsCancellationRequested) break;
            if (string.IsNullOrWhiteSpace(attendance.ClientEmail)) continue;
            if (string.IsNullOrWhiteSpace(attendance.CalendarSessionId)) continue;
            if (!sessionsById.TryGetValue(attendance.CalendarSessionId, out var session)) continue;

            try
            {
                await _emailService.SendClassReminderAsync(
                    toEmail: attendance.ClientEmail,
                    clientName: attendance.ClientName ?? "there",
                    bookingReference: attendance.BookingReference,
                    className: session.ClassName,
                    instructorName: session.InstructorName,
                    classTime: session.StartTime,
                    format: session.Format,
                    endTime: session.EndTime,
                    reminderWindow: windowTag);

                // Atomic $push — if multiple workers ever processed
                // the same attendance concurrently, the worst case
                // is the tag landing twice (idempotent in practice
                // because !contains gates the next pass), but Mongo's
                // $push doesn't dedupe by default. Single-replica
                // today, revisit on scale-out.
                var update = Builders<Attendance>.Update.Push(a => a.RemindersSent, windowTag);
                await _attendances.UpdateOneAsync(
                    Builders<Attendance>.Filter.Eq(a => a.Id, attendance.Id),
                    update,
                    cancellationToken: ct);

                sentCount++;
            }
            catch (Exception ex)
            {
                // Log and continue — one bad recipient shouldn't poison
                // the rest of the batch. The unflipped tag ensures the
                // next hourly tick retries this attendance.
                _logger.LogWarning(ex,
                    "ReminderService failed to send {Window} reminder for attendance {AttendanceId} ({Email})",
                    windowTag, attendance.Id, attendance.ClientEmail);
            }
        }

        return sentCount;
    }
}

