public async Task SendClassCancelledAsync(string toEmail, string clientName, string className, DateTime classTime)
{
    if (!_enabled || string.IsNullOrWhiteSpace(toEmail)) return;
    if (!await IsTemplateEnabledAsync(EmailTemplateIds.ClassCancelled)) return;

    var dateStr = classTime.ToString("dddd, dd MMM yyyy");
    var timeStr = classTime.ToString("hh:mm tt");

    var safeClient = EmailTemplateHelper.EncodeText(clientName);
    var safeClass = EmailTemplateHelper.EncodeText(className);

    // SPM-76 — substitution. {BookingUrl} is a code-controlled absolute link.
    var bodyValues = new Dictionary<string, string>
    {
        ["ClientName"] = safeClient,
        ["ClassName"] = safeClass,
        ["Date"] = dateStr,
        ["Time"] = timeStr,
        ["BookingUrl"] = $"{_publicBaseUrl}/booking",
    };
    var subjectValues = new Dictionary<string, string> { ["ClassName"] = className };

    var (subject, inner) = await ResolveTemplateAsync(
        EmailTemplateIds.ClassCancelled,
        defaultSubject: "Class Cancelled — {ClassName} | Lớp học đã bị hủy — Soul Pilates",
        defaultBody: EmailTemplateDefaults.ClassCancelledBody,
        subjectValues: subjectValues,
        bodyValues: bodyValues);

    var body = EmailTemplateHelper.Layout(
        heading: "<span style='color: #df1b41;'>Class Cancelled</span>",
        subtitleVi: "Lớp học đã bị hủy",
        innerHtml: inner);

    // Q3-S07-3 = A: attach a METHOD:CANCEL .ics with the same UID
    // shape as the original invite so the client's calendar app
    // self-cleans. We don't have the booking reference here — the
    // class cancellation is studio-side, affecting every attendee
    // — so we synthesize a UID from the session-identifying bits.
    // This is best-effort: if it doesn't match the original UID
    // exactly (e.g. because the attendee booked via a different
    // path that uses a different format) the calendar entry won't
    // auto-remove, but the email itself is still useful.
    var startUtc = DateTime.SpecifyKind(classTime, DateTimeKind.Utc);
    var icsBytes = IcsCalendarBuilder.BuildEventCancellation(
        uid: $"{startUtc:yyyyMMddTHHmmss}-{className.GetHashCode():X}@soulpilates.com.vn",
        startUtc: startUtc,
        endUtc: startUtc.AddHours(1),
        summary: className);

    var icsAttachment = new Attachment(
        new MemoryStream(icsBytes),
        "soul-pilates-cancellation.ics",
        "text/calendar");

    await SendEmailAsync(toEmail, subject, body, icsAttachment);
}

public async Task SendClassReminderAsync(string toEmail, string clientName, string bookingReference,
    string className, string instructorName, DateTime classTime, string format,
    DateTime? endTime, string reminderWindow)
{
    if (!_enabled || string.IsNullOrWhiteSpace(toEmail)) return;
    if (!await IsTemplateEnabledAsync(EmailTemplateIds.ClassReminder)) return;

// Window-specific subject + heading copy. The two windows
// share a body shape; the only divergence is the lead phrase
// and the "arrival" copy.
var is1h = reminderWindow == "1h";
var reminderSubject = is1h
    ? $"Class starts in 1 hour — {className} | Lớp bắt đầu sau 1 giờ — Soul Pilates"
    : $"Tomorrow at the studio — {className} | Lớp ngày mai — Soul Pilates";
var heading = is1h ? "Class starts in 1 hour ⏰" : "See you tomorrow ✨";
var subtitleVi = is1h ? "Lớp bắt đầu sau 1 giờ" : "Hẹn gặp lại ngày mai";
var arrivalCopy = is1h
    ? "Heading to the studio? Please arrive 10 minutes early so we can settle you in."
    : "Tomorrow's class is locked in. Please arrive 10 minutes early.";
var arrivalCopyVi = is1h
    ? "Đang trên đường đến studio? Vui lòng đến trước 10 phút."
    : "Lớp ngày mai đã được xác nhận. Vui lòng đến trước 10 phút.";

var startUtc = DateTime.SpecifyKind(classTime, DateTimeKind.Utc);
var endUtc = endTime.HasValue
    ? DateTime.SpecifyKind(endTime.Value, DateTimeKind.Utc)
    : startUtc.AddHours(1);

var dateStr = classTime.ToString("dddd, dd MMM yyyy");
var timeStr = classTime.ToString("hh:mm tt");

var safeClient = EmailTemplateHelper.EncodeText(clientName);
var safeRef = EmailTemplateHelper.EncodeText(bookingReference);
var safeClass = EmailTemplateHelper.EncodeText(className);
var safeFormat = EmailTemplateHelper.EncodeText(format);
var safeInstructor = EmailTemplateHelper.EncodeText(instructorName);

// SPM-76 — substitution. ArrivalCopy / ReminderSubject carry the
// window-specific (1h vs 24h) copy; the heading/subtitle stay code-side.
var bodyValues = new Dictionary<string, string>
{
    ["ClientName"] = safeClient,
    ["BookingReference"] = safeRef,
    ["ClassName"] = safeClass,
    ["Format"] = safeFormat,
    ["Date"] = dateStr,
    ["Time"] = timeStr,
    ["Instructor"] = safeInstructor,
    ["ArrivalCopy"] = arrivalCopy,
    ["ArrivalCopyVi"] = arrivalCopyVi,
};
var subjectValues = new Dictionary<string, string> { ["ReminderSubject"] = reminderSubject };

var (subject, inner) = await ResolveTemplateAsync(
    EmailTemplateIds.ClassReminder,
    defaultSubject: "{ReminderSubject}",
    defaultBody: EmailTemplateDefaults.ClassReminderBody,
    subjectValues: subjectValues,
    bodyValues: bodyValues);

var body = EmailTemplateHelper.Layout(
    heading: heading,
    subtitleVi: subtitleVi,
    innerHtml: inner);

// Reuse the original booking UID so a client's calendar app
// sees this as a refresh of the existing event, not a new one.
// SEQUENCE remains 0 — matches the original invite, no bump.
var icsBytes = IcsCalendarBuilder.BuildEventInvite(
    uid: $"{bookingReference}@soulpilates.com.vn",
    startUtc: startUtc,
    endUtc: endUtc,
    summary: $"{className} — {instructorName}",
    description: $"Soul Pilates Da Nang · {format} · Reference {bookingReference}",
    location: EmailTemplateHelper.StudioLocation);

var icsAttachment = new Attachment(
    new MemoryStream(icsBytes),
    $"soul-pilates-{bookingReference}.ics",
    "text/calendar");

    await SendEmailAsync(toEmail, subject, body, icsAttachment);
}

public async Task SendVerificationEmailAsync(string toEmail, string fullName, string token)
{
    if (!_enabled || string.IsNullOrWhiteSpace(toEmail)) return;

    var verifyUrl = $"{_publicBaseUrl}/verify-email?token={token}";

    var safeName = EmailTemplateHelper.EncodeText(fullName);

    // SPM-76 — {VerifyUrl} is the code-built deep-link (required variable).
    var bodyValues = new Dictionary<string, string>
