private async Task<bool> IsTemplateEnabledAsync(string templateId)
{
    if (_settingsService == null) return true;
    try
    {
        var resolved = await _settingsService.GetResolvedEmailTemplateAsync(templateId);
        return resolved == null || resolved.IsEnabled;
    }
    catch { return true; }
}

private async Task<(string subject, string innerHtml)> ResolveTemplateAsync(
    string templateId,
    string defaultSubject,
    string defaultBody,
    IReadOnlyDictionary<string, string> subjectValues,
    IReadOnlyDictionary<string, string> bodyValues)
{
    var rawSubject = defaultSubject;
    var rawBody = defaultBody;

    if (_settingsService != null)
    {
        try
        {
            var resolved = await _settingsService.GetResolvedEmailTemplateAsync(templateId);
            if (resolved != null)
            {
                if (!string.IsNullOrWhiteSpace(resolved.Subject)) rawSubject = resolved.Subject;
                if (!string.IsNullOrWhiteSpace(resolved.BodyHtml)) rawBody = resolved.BodyHtml;
            }
        }
        catch
        {
            // Email is fire-and-forget — never let a settings hiccup break a
            // send. Fall through to the hardcoded defaults.
        }
    }

    return (
        EmailTemplateHelper.Render(rawSubject, subjectValues),
        EmailTemplateHelper.Render(rawBody, bodyValues));
}

private async Task SendEmailAsync(string to, string subject, string htmlBody)
    => await SendEmailAsync(to, subject, htmlBody, attachment: null);

private async Task SendEmailAsync(string to, string subject, string htmlBody, Attachment? attachment)
{
    // ── Test-mode guard ──
    // With SmtpSettings:TestMode=true, real customers never get test mail.
    // The recipient is either exempted (TestAllowlist), redirected to a single
    // test inbox (TestRedirectTo) with the intended recipient shown in the
    // subject, or dropped entirely if no redirect target is configured.
    if (_testMode && !_testAllowlist.Contains((to ?? string.Empty).Trim().ToLowerInvariant()))
    {
        if (string.IsNullOrWhiteSpace(_testRedirectTo))
        {
            _logger.LogInformation("[EmailService] TEST MODE — suppressed email to {To} (subject: {Subject})", to, subject);
            return;
        }
        _logger.LogInformation("[EmailService] TEST MODE — redirecting email for {To} → {Redirect}", to, _testRedirectTo);
        subject = $"[TEST → {to}] {subject}";
        to = _testRedirectTo;
    }

    try
    {
        using var client = new SmtpClient(_smtpHost, _smtpPort)
        {
            Credentials = new NetworkCredential(_smtpUser, _smtpPass),
            EnableSsl = true
        };

        using var msg = new MailMessage
        {
            From = new MailAddress(_fromEmail, _fromName),
            Subject = subject,
            Body = htmlBody,
            IsBodyHtml = true

