{
    if (!_enabled || string.IsNullOrWhiteSpace(toEmail)) return;
    if (!await IsTemplateEnabledAsync(EmailTemplateIds.ReviewRequest)) return;

    var safeName = EmailTemplateHelper.EncodeText(clientName);

