using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.Services;

/// <summary>
/// Hosted job that drives <see cref="IReviewRequestService.SendDueRequestsAsync"/>
/// hourly — the same lifetime + DI pattern as
/// <see cref="BookingReminderBackgroundService"/>. Sends the Google review request
/// ~2h after a client's first class.
/// </summary>
public class ReviewRequestBackgroundService : BackgroundService
{
    private readonly IServiceProvider _services;
    private readonly ILogger<ReviewRequestBackgroundService> _logger;

    public ReviewRequestBackgroundService(
        IServiceProvider services,
        ILogger<ReviewRequestBackgroundService> logger)
    {
        _services = services;
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                using var scope = _services.CreateScope();
                var reviewService = scope.ServiceProvider.GetRequiredService<IReviewRequestService>();
                await reviewService.SendDueRequestsAsync(DateTime.UtcNow, stoppingToken);
            }
            catch (Exception ex)
            {
                // Top-level guard — a fault here must not tear down the hosted
                // service for the rest of the process.
                _logger.LogError(ex, "ReviewRequestBackgroundService tick threw");
            }

            await Task.Delay(TimeSpan.FromMinutes(60), stoppingToken);
        }
    }
}

