using System.Net;

namespace SoulPilates.Services.Email;

/// <summary>
/// Owns the shared HTML chrome that every Soul Pilates transactional
/// email wears (header band, content card, address footer). Extracted
/// in P3-S07 so the four existing templates plus the upcoming P3-S08
/// reminder template share one source of truth — a brand-colour or
/// footer change becomes a single-spot edit instead of five.
/// </summary>
public static class EmailTemplateHelper
{
    /// <summary>
    /// Hardcoded studio location used in the address footer and
    /// (in the .ics LOCATION field) the calendar invite. Q3-S07-1 = A
    /// approves a hardcoded constant for this slice; promote to a
    /// <c>StudioAddressSettings</c> config block when the owner
    /// confirms the precise street address.
    /// </summary>
    public const string StudioLocation = "Soul Pilates Da Nang, Vietnam";

    /// <summary>
    /// Wrap a per-template <paramref name="innerHtml"/> body in the
    /// shared chrome. Output is a complete <c>&lt;!DOCTYPE html&gt;</c>
    /// document ready for <c>MailMessage.Body</c>.
    /// </summary>
    /// <param name="heading">Big header inside the content card (English).</param>
    /// <param name="subtitleVi">
    /// Smaller Vietnamese subtitle directly below the heading. Bilingual
    /// presentation matches the existing four templates (Eng/Vie pairs
    /// throughout the body); the studio's clientele is bilingual.
    /// </param>
    /// <param name="innerHtml">
    /// The per-template body content. Caller is responsible for HTML-
    /// encoding any user-supplied data inside this fragment — use
    /// <see cref="EncodeText"/> for that.
    /// </param>
    /// <param name="footerNote">
    /// Optional extra line above the address footer (e.g. "Keep this
    /// email for your records"). Rendered at 12px muted-grey.
    /// </param>
    public static string Layout(
        string heading,
        string subtitleVi,
        string innerHtml,
        string? footerNote = null)
    {
        var footerNoteHtml = string.IsNullOrWhiteSpace(footerNote)
            ? string.Empty
            : $@"
      <p style='font-size: 13px; color: #4f566b; line-height: 1.6;'>{footerNote}</p>";

        return $@"
<!DOCTYPE html>
<html>
<head><meta charset='UTF-8'></head>
<body style='font-family: Inter, Arial, sans-serif; background: #f6f8fa; padding: 32px 0;'>
  <div style='max-width: 520px; margin: 0 auto; background: white; border-radius: 12px; overflow: hidden; box-shadow: 0 1px 4px rgba(0,0,0,0.06);'>
    <div style='background: #0a0e1a; padding: 24px 32px; text-align: center;'>
      <h1 style='color: #635bff; font-size: 20px; margin: 0;'>Soul Pilates</h1>
      <p style='color: #8892a4; font-size: 12px; margin: 4px 0 0;'>DA NANG STUDIO</p>
    </div>
    <div style='padding: 32px;'>
      <h2 style='font-size: 18px; margin: 0 0 4px;'>{heading}</h2>
      <p style='color: #8792a2; font-size: 13px; margin: 0 0 24px;'>{subtitleVi}</p>
{innerHtml}{footerNoteHtml}
      <div style='border-top: 1px solid #e3e8ee; margin: 24px 0; padding-top: 16px;'>
        <p style='font-size: 12px; color: #8792a2; margin: 0;'>📍 {StudioLocation}<br/>soulpilates.com.vn</p>
      </div>
    </div>
  </div>
</body>
</html>";
    }

    /// <summary>
    /// SPM-76 substitution. Replaces every <c>{Token}</c> in
    /// <paramref name="template"/> with its value from <paramref name="values"/>.
    /// Plain ordinal <see cref="string.Replace(string,string)"/> per key — the
    /// same trivial convention the editable templates document, with no regex so
    /// an unrecognised <c>{...}</c> that isn't a known key is simply left untouched
    /// (it never matches a dictionary entry). Values are substituted verbatim, so
    /// callers MUST pre-encode any user-supplied field with <see cref="EncodeText"/>
    /// before adding it to the dictionary — exactly as the legacy interpolated
    /// templates did.
    /// </summary>
    public static string Render(string template, IReadOnlyDictionary<string, string> values)
    {
        if (string.IsNullOrEmpty(template)) return template ?? string.Empty;
        var result = template;
        foreach (var kv in values)
        {
            result = result.Replace("{" + kv.Key + "}", kv.Value ?? string.Empty);
        }
        return result;
    }

    /// <summary>
    /// HTML-encode a string before interpolating it into a template
    /// body. Wraps <see cref="WebUtility.HtmlEncode"/> with a null-safe
    /// guard so callers don't have to.
    ///
    /// <para>
    /// The receipt template already does this for client-supplied
    /// fields; the booking-confirmation template currently doesn't,
    /// which would break (or worse) on a name like <c>"O'Connor &amp; Co"</c>.
    /// Use this everywhere user data crosses the template boundary.
    /// </para>
    /// </summary>
    public static string EncodeText(string? raw)
        => string.IsNullOrEmpty(raw) ? string.Empty : WebUtility.HtmlEncode(raw);
}

