    function showConfirmation(reference) {
      // Mark as completed BEFORE any DOM work so the pagehide beacon
      // doesn't fire during the confirmation transition.
      bookingCompleted = true;

      document.getElementById("viewMethod").style.display = "none";
      document.getElementById("viewCard").style.display = "none";
      document.getElementById("viewConfirmation").style.display = "block";

      const refStr = reference || "—";
      document.getElementById("confirmRef").textContent = refStr;

      const type =
        session?.format === "PRIVATE"
          ? t("common.privateClass")
          : t("common.groupClass");
      document.getElementById("confirmMessage").textContent = t(
        "confirmation.bookingSuccess",
        { type },
      );

      // Populate the confirmation booking-summary card by mirroring the
      // already-rendered method-selection summary (single source of truth for
      // what the customer saw). Equipment / Duo rows are only shown when their
      // source row was visible.
      const mirrorConf = (srcId, dstId) => {
        const src = document.getElementById(srcId);
        const dst = document.getElementById(dstId);
        if (src && dst) dst.innerHTML = src.innerHTML;
      };
      mirrorConf("sumClass", "confSumClass");
      mirrorConf("sumInstructor", "confSumInstructor");
      mirrorConf("sumDateTime", "confSumDateTime");

      const equipRow = document.getElementById("sumEquipmentRow");
      if (equipRow && equipRow.style.display !== "none") {
        mirrorConf("sumEquipment", "confSumEquipment");
        document.getElementById("confSumEquipmentRow").style.display = "flex";
      }
      const duoRow = document.getElementById("sumDuoRow");
      if (duoRow && duoRow.style.display !== "none") {
        document.getElementById("confSumDuoRow").style.display = "flex";
      }

      // Clean up state
      sessionStorage.removeItem("sp_booking_intent");
      sessionStorage.removeItem("sp_attendance_id");

      // First-party funnel: booking confirmed (end of funnel).
      if (window.spTrackFunnel) window.spTrackFunnel('PurchaseCompleted');
      // GA4 funnel: purchase completed (end of funnel)
      if (typeof window.spTrackEvent === "function") {
        const quoteForMethod = window._spQuotes?.[selectedMethod];
        window.spTrackEvent("purchase", {
          transaction_id: refStr,
          value: quoteForMethod?.amountDueNow || 0,
          currency: quoteForMethod?.currency || "VND",
          items: [
            {
              item_id: sessionId,
              item_name: session?.className || "",
              item_category: session?.format || "",
              quantity: quantity,
            },
          ],
        });
      }
    }
  </script>
</CustomerLayout>

