using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.Services;

/// <summary>
/// Meta Conversions API sender. Config lives in the "MetaTracking" section
/// (env: <c>MetaTracking__PixelId</c>, <c>MetaTracking__AccessToken</c>,
/// <c>MetaTracking__TestEventCode</c>, <c>MetaTracking__Enabled</c>) — the same
/// env-secret pattern as SMTP/Stripe, so the access token never touches the DB
/// or any API response.
/// </summary>
public class MetaConversionsService : IMetaConversionsService
{
    private const string GraphApiVersion = "v21.0";

    private readonly HttpClient _http;
    private readonly ILogger<MetaConversionsService> _logger;
    private readonly bool _enabled;
    private readonly string _pixelId;
    private readonly string _accessToken;
    private readonly string _testEventCode;

    public MetaConversionsService(HttpClient http, IConfiguration config, ILogger<MetaConversionsService> logger)
    {
        _http = http;
        _logger = logger;
        var section = config.GetSection("MetaTracking");
        _pixelId = section["PixelId"] ?? "";
        _accessToken = section["AccessToken"] ?? "";
        _testEventCode = section["TestEventCode"] ?? "";
        _enabled = bool.TryParse(section["Enabled"], out var e) ? e : true;
    }

    public bool IsEnabled =>
        _enabled && !string.IsNullOrWhiteSpace(_pixelId) && !string.IsNullOrWhiteSpace(_accessToken);

    public string PixelId => _pixelId;

    public async Task SendEventAsync(MetaConversionEvent evt, CancellationToken ct = default)
    {
        if (!IsEnabled) return;

        try
        {
            var userData = new Dictionary<string, object?>();
            var hashedEmail = HashNormalized(evt.Email);
            if (hashedEmail != null) userData["em"] = new[] { hashedEmail };
            var hashedPhone = HashPhone(evt.Phone);
            if (hashedPhone != null) userData["ph"] = new[] { hashedPhone };
            if (!string.IsNullOrWhiteSpace(evt.Fbp)) userData["fbp"] = evt.Fbp;
            if (!string.IsNullOrWhiteSpace(evt.Fbc)) userData["fbc"] = evt.Fbc;
            if (!string.IsNullOrWhiteSpace(evt.ClientIpAddress)) userData["client_ip_address"] = evt.ClientIpAddress;
            if (!string.IsNullOrWhiteSpace(evt.ClientUserAgent)) userData["client_user_agent"] = evt.ClientUserAgent;

            var customData = new Dictionary<string, object?>();
            if (evt.Value.HasValue) customData["value"] = evt.Value.Value;
            if (!string.IsNullOrWhiteSpace(evt.Currency)) customData["currency"] = evt.Currency;
            if (!string.IsNullOrWhiteSpace(evt.ContentName)) customData["content_name"] = evt.ContentName;
            if (!string.IsNullOrWhiteSpace(evt.ContentCategory)) customData["content_category"] = evt.ContentCategory;
            if (evt.ContentIds is { Count: > 0 }) customData["content_ids"] = evt.ContentIds;

            var data = new Dictionary<string, object?>
            {
                ["event_name"] = evt.EventName,
                ["event_time"] = DateTimeOffset.UtcNow.ToUnixTimeSeconds(),
                ["event_id"] = evt.EventId,
                ["action_source"] = "website",
                ["user_data"] = userData,
            };
            if (!string.IsNullOrWhiteSpace(evt.EventSourceUrl)) data["event_source_url"] = evt.EventSourceUrl;
            if (customData.Count > 0) data["custom_data"] = customData;

            var payload = new Dictionary<string, object?> { ["data"] = new[] { data } };
            if (!string.IsNullOrWhiteSpace(_testEventCode)) payload["test_event_code"] = _testEventCode;

            var url = $"https://graph.facebook.com/{GraphApiVersion}/{_pixelId}/events?access_token={Uri.EscapeDataString(_accessToken)}";
            var json = JsonSerializer.Serialize(payload);
            using var content = new StringContent(json, Encoding.UTF8, "application/json");

            var resp = await _http.PostAsync(url, content, ct);
            if (!resp.IsSuccessStatusCode)
            {
                var body = await resp.Content.ReadAsStringAsync(ct);
                _logger.LogWarning("Meta CAPI event {Event} failed: {Status} {Body}", evt.EventName, (int)resp.StatusCode, body);
            }
        }
        catch (Exception ex)
        {
            // Tracking must never break the funnel — log and move on.
            _logger.LogWarning(ex, "Meta CAPI send threw for event {Event}", evt.EventName);
        }
    }

    /// <summary>SHA-256 of a trimmed, lower-cased string. Null/blank → null.</summary>
    private static string? HashNormalized(string? raw)
    {
        if (string.IsNullOrWhiteSpace(raw)) return null;
        return Sha256Hex(raw.Trim().ToLowerInvariant());
    }

    /// <summary>Phone normalised to digits only (keeps country code) before hashing.</summary>
    private static string? HashPhone(string? raw)
    {
        if (string.IsNullOrWhiteSpace(raw)) return null;
        var digits = new string(raw.Where(char.IsDigit).ToArray());
        return string.IsNullOrEmpty(digits) ? null : Sha256Hex(digits);
    }

    private static string Sha256Hex(string input)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(input));
        var sb = new StringBuilder(bytes.Length * 2);
        foreach (var b in bytes) sb.Append(b.ToString("x2"));
        return sb.ToString();
    }
}

