using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.API.Controllers;

/// <summary>
/// Public, first-party tracking gateway for the customer-facing Meta Pixel.
/// The browser fires the Pixel AND posts the same event here (same eventId); we
/// forward it to Meta's Conversions API server-side with the request IP + UA and
/// hashed customer data. Because this endpoint is on our own domain it isn't
/// blocked by the ad-blockers / iOS restrictions that drop <c>facebook.com/tr</c>,
/// so conversions the Pixel loses are still counted — de-duplicated by eventId.
/// </summary>
[ApiController]
[Route("api/tracking")]
[AllowAnonymous]
public class TrackingController : ControllerBase
{
    private readonly IMetaConversionsService _meta;

    public TrackingController(IMetaConversionsService meta) => _meta = meta;

    /// <summary>Public Pixel config for the browser loader. Never exposes the CAPI token.</summary>
    [HttpGet("meta-config")]
    public IActionResult MetaConfig() =>
        Ok(new { pixelId = _meta.PixelId, enabled = _meta.IsEnabled });

    public class MetaEventRequest
    {
        public string EventName { get; set; } = "";
        public string EventId { get; set; } = "";
        public string? EventSourceUrl { get; set; }
        public string? Email { get; set; }
        public string? Phone { get; set; }
        public string? Fbp { get; set; }
        public string? Fbc { get; set; }
        public decimal? Value { get; set; }
        public string? Currency { get; set; }
        public string? ContentName { get; set; }
        public string? ContentCategory { get; set; }
        public List<string>? ContentIds { get; set; }
    }

    [HttpPost("meta")]
    public async Task<IActionResult> Meta([FromBody] MetaEventRequest req, CancellationToken ct)
    {
        if (req == null || string.IsNullOrWhiteSpace(req.EventName) || string.IsNullOrWhiteSpace(req.EventId))
            return Ok(new { ok = false }); // silently ignore malformed pings

        await _meta.SendEventAsync(new MetaConversionEvent
        {
            EventName = req.EventName,
            EventId = req.EventId,
            EventSourceUrl = req.EventSourceUrl,
            Email = req.Email,
            Phone = req.Phone,
            Fbp = req.Fbp,
            Fbc = req.Fbc,
            Value = req.Value,
            Currency = req.Currency,
            ContentName = req.ContentName,
            ContentCategory = req.ContentCategory,
            ContentIds = req.ContentIds,
            ClientIpAddress = ResolveClientIp(),
            ClientUserAgent = Request.Headers.UserAgent.ToString(),
        }, ct);

        return Ok(new { ok = true });
    }

    /// <summary>Prefer the left-most X-Forwarded-For hop (real client) behind the reverse proxy.</summary>
    private string? ResolveClientIp()
    {
        var fwd = Request.Headers["X-Forwarded-For"].ToString();
        if (!string.IsNullOrWhiteSpace(fwd))
            return fwd.Split(',')[0].Trim();
        return HttpContext.Connection.RemoteIpAddress?.ToString();
    }
}

