using System.Threading.Tasks;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.DTOs;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.API.Controllers;

/// <summary>
/// First-party web-analytics surface.
///   • POST /api/track            — anonymous beacon from the public site.
///   • GET  /api/track/visitors/* — Admin-gated dashboard aggregations.
/// The write path is deliberately permissive and fire-and-forget; the read
/// paths are locked down like the rest of the analytics dashboard.
/// </summary>
[ApiController]
[Route("api/track")]
public class TrackingController : ControllerBase
{
    private readonly IVisitorAnalyticsService _visitors;

    public TrackingController(IVisitorAnalyticsService visitors)
    {
        _visitors = visitors;
    }

    /// <summary>Ingest one pageview / funnel-step beacon. Always 204 — never blocks the client.</summary>
    [HttpPost]
    [AllowAnonymous]
    public async Task<IActionResult> Track([FromBody] TrackEventRequest req, CancellationToken ct)
    {
        if (req == null) return NoContent();
        try
        {
            await _visitors.TrackAsync(req, ResolveClientIp(), Request.Headers.UserAgent.ToString(), ct);
        }
        catch
        {
            // Analytics must never surface an error to the public site.
        }
        return NoContent();
    }

    [HttpGet("visitors/live")]
    [Authorize(Roles = "Admin,Accountant")]
    public async Task<IActionResult> Live(CancellationToken ct)
        => Ok(new { live = await _visitors.GetLiveVisitorCountAsync(5, ct) });

    [HttpGet("visitors/summary")]
    [Authorize(Roles = "Admin,Accountant")]
    public async Task<IActionResult> Summary([FromQuery] DateTime start, [FromQuery] DateTime end, CancellationToken ct)
        => Ok(await _visitors.GetVisitorSummaryAsync(start.ToUniversalTime(), end.ToUniversalTime(), ct));

    [HttpGet("visitors/funnel")]
    [Authorize(Roles = "Admin,Accountant")]
    public async Task<IActionResult> Funnel([FromQuery] DateTime start, [FromQuery] DateTime end, CancellationToken ct)
        => Ok(await _visitors.GetBookingFunnelAsync(start.ToUniversalTime(), end.ToUniversalTime(), ct));

    [HttpGet("visitors/signup-sources")]
    [Authorize(Roles = "Admin,Accountant")]
    public async Task<IActionResult> SignupSources([FromQuery] DateTime start, [FromQuery] DateTime end, CancellationToken ct)
        => Ok(await _visitors.GetSignupSourcesAsync(start.ToUniversalTime(), end.ToUniversalTime(), ct));

    /// <summary>
    /// The API runs behind nginx, so the real client IP is the first hop of
    /// X-Forwarded-For; fall back to the socket address for direct hits.
    /// </summary>
    private string? ResolveClientIp()
    {
        var xff = Request.Headers["X-Forwarded-For"].ToString();
        if (!string.IsNullOrWhiteSpace(xff))
            return xff.Split(',')[0].Trim();
        return HttpContext.Connection.RemoteIpAddress?.ToString();
    }
}

