<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Verify Email | Soul Pilates Da Nang</title>
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link
      href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Outfit:wght@600;700&display=swap"
      rel="stylesheet"
    />
    <style is:global>
      *,
      *::before,
      *::after {
        box-sizing: border-box;
        margin: 0;
        padding: 0;
      }
      :root {
        --brand: #635bff;
        --surface: #fff;
        --surface-raised: #f6f8fa;
        --border: #e3e8ee;
        --text-primary: #1a1f36;
        --text-muted: #8792a2;
        --success: #10b981;
        --danger: #df1b41;
        --radius: 12px;
        --shadow-lg: 0 10px 40px rgba(0, 0, 0, 0.08);
      }
      body {
        font-family:
          "Inter",
          -apple-system,
          sans-serif;
        background: var(--surface-raised);
        color: var(--text-primary);
        min-height: 100vh;
        display: flex;
        align-items: center;
        justify-content: center;
      }
      .verify-card {
        background: var(--surface);
        border-radius: var(--radius);
        border: 1px solid var(--border);
        padding: 48px 32px;
        box-shadow: var(--shadow-lg);
        text-align: center;
        max-width: 420px;
        width: 100%;
        margin: 16px;
      }
      .verify-icon {
        width: 64px;
        height: 64px;
        border-radius: 50%;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        margin-bottom: 20px;
      }
      .verify-icon.success {
        background: rgba(16, 185, 129, 0.1);
      }
      .verify-icon.error {
        background: rgba(223, 27, 65, 0.1);
      }
      .verify-icon.loading {
        background: var(--surface-raised);
      }
      .verify-icon svg {
        width: 32px;
        height: 32px;
      }
      h2 {
        font-family: "Outfit", sans-serif;
        font-size: 20px;
        margin-bottom: 8px;
      }
      p {
        font-size: 13px;
        color: var(--text-muted);
        line-height: 1.6;
      }
      .btn-login {
        display: inline-block;
        margin-top: 20px;
        padding: 10px 24px;
        background: var(--brand);
        color: white;
        border-radius: 8px;
        text-decoration: none;
        font-weight: 600;
        font-size: 14px;
      }
      .spinner {
        width: 32px;
        height: 32px;
        border: 3px solid var(--border);
        border-top-color: var(--brand);
        border-radius: 50%;
        animation: spin 0.6s linear infinite;
      }
      @keyframes spin {
        to {
          transform: rotate(360deg);
        }
      }
    </style>
  </head>
  <body>
    <div class="verify-card" id="card">
      <div class="verify-icon loading"><div class="spinner"></div></div>
      <h2>Verifying your email...</h2>
      <p>Đang xác minh email của bạn...</p>
    </div>

    <script>
      const API = import.meta.env.PUBLIC_API_URL;

      async function verify() {
        const token = new URLSearchParams(window.location.search).get("token");
        const card = document.getElementById("card");

        if (!token) {
          card.innerHTML = `
        <div class="verify-icon error"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="#df1b41" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg></div>
        <h2>Invalid Link</h2>
        <p>No verification token found. Please check your email for the correct link.</p>`;
          return;
        }

        try {
          const res = await fetch(
            API +
              "/api/customer/verify-email?token=" +
              encodeURIComponent(token),
          );
          const data = await res.json();
          if (res.ok) {
            card.innerHTML = `
          <div class="verify-icon success"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="#10b981" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg></div>
          <h2>Email Verified! ✓</h2>
          <p>Xác minh thành công! You can now log in to your account.</p>
          <a href="/login" class="btn-login">Log In / Đăng Nhập</a>`;
          } else {
            card.innerHTML = `
          <div class="verify-icon error"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="#df1b41" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg></div>
          <h2>Verification Failed</h2>
          <p>${data.message || "Invalid or expired token. Please try registering again."}</p>`;
          }
        } catch (e) {
          card.innerHTML = `
        <div class="verify-icon error"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="#df1b41" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg></div>
        <h2>Connection Error</h2>
        <p>Could not connect to the server. Please try again later.</p>`;
        }
      }

      verify();
    </script>
  </body>
</html>

