async function openDetails(sessionId) {
  currentSessionId = sessionId;
  // Funnel: user opened a specific class to consider booking it.
  if (window.spTrackFunnel) window.spTrackFunnel('SessionSelected');
  const overlay = document.getElementById("detailsOverlay");
  overlay.classList.add("open");
  document.body.style.overflow = "hidden";

  const body = document.getElementById("detailsBody");
  body.innerHTML = `
    <div class="sp-skeleton" style="height:24px;width:60%;margin-bottom:12px;"></div>
    <div class="sp-skeleton" style="height:18px;width:40%;margin-bottom:24px;"></div>
    <div class="sp-skeleton" style="height:14px;width:100%;margin-bottom:8px;"></div>
    <div class="sp-skeleton" style="height:14px;width:90%;margin-bottom:8px;"></div>
  `;

  try {
    const res = await fetch(`${API}/api/booking/class/${sessionId}`);
    if (!res.ok) throw new Error("Not found");
    const data = await res.json();
    renderDetails(data);
    // GA4 funnel: user selected a specific class for details
    if (typeof window.spTrackEvent === 'function') {
      window.spTrackEvent('select_item', {
        item_list_id: 'class_schedule',
        items: [{
          item_id: sessionId,
          item_name: data.session?.className || '',
          item_category: data.session?.format || '',
        }],
      });
    }
  } catch (e) {
    body.innerHTML = `<div class="sp-error-msg visible">${t("common.error")}</div>`;
  }
}

function renderDetails(data) {
  const { session, blueprint, instructor } = data;

  // ── SVG icons (must be defined before any template strings that use them) ──
  const equipSvg = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="9" width="20" height="6" rx="2"/><line x1="7" y1="9" x2="7" y2="15"/></svg>`;
  const personSvg = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="7" r="4"/><path d="M5.5 21a6.5 6.5 0 0 1 13 0"/></svg>`;
  const clockSvg = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>`;
  const calSvg = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>`;

