using SoulPilates.Core.Interfaces;

namespace SoulPilates.Tests.TestHelpers;

/// <summary>
/// Silent stub for <see cref="IWalletService"/> so the webhook-focused
/// <see cref="SoulPilates.Services.PaymentService"/> tests don't need to
/// stand up the full wallet-collection schema. Webhook handlers only call
/// the wallet when a PACKAGE_CREDIT booking succeeds, which is exercised
/// through dedicated integration tests, not these dedup tests.
/// </summary>
public sealed class NoOpWalletService : IWalletService
{
    public Task<IEnumerable<ClientPackage>> GetActivePackagesForClientAsync(string clientId, string format)
        => Task.FromResult(Enumerable.Empty<ClientPackage>());

    public Task<IEnumerable<ClientPackage>> GetAllPackagesForClientAsync(string clientId)
        => Task.FromResult(Enumerable.Empty<ClientPackage>());

    public Task<bool> DeductCreditAsync(string clientId, string format, string referenceAttendanceId, int quantity = 1)
        => Task.FromResult(true);

    public Task<bool> RefundCreditAsync(string packageInstanceId, string referenceAttendanceId, int quantity = 1)
        => Task.FromResult(true);

    public Task<bool> RefundCreditByAttendanceAsync(string attendanceId)
        => Task.FromResult(true);

    public Task<(bool refunded, bool hasLedgerTrail)> RefundCreditByAttendanceWithTrailAsync(string attendanceId)
        => Task.FromResult((true, true));

    public Task<(int refundedCount, bool hasLedgerTrail)> RefundPartialCreditByAttendanceWithTrailAsync(string attendanceId, int seatsToRefund)
        => Task.FromResult((seatsToRefund, true));

    public Task<int> ForfeitCreditByAttendanceAsync(string attendanceId, int seatsForfeited)
        => Task.FromResult(seatsForfeited);

    public Task ExpireOldPackagesAsync() => Task.CompletedTask;

    public Task FreezePackageAsync(string packageInstanceId, DateTime freezeStart, int daysToFreeze, string? reason)
        => Task.CompletedTask;

    public Task<bool> AdjustCreditAsync(string packageInstanceId, int delta, string reason)
        => Task.FromResult(false);
}

