/// reminder template share one source of truth — a brand-colour or
/// footer change becomes a single-spot edit instead of five.
/// </summary>
public static class EmailTemplateHelper
{
    /// <summary>
    /// Hardcoded studio location used in the address footer and
    /// (in the .ics LOCATION field) the calendar invite. Q3-S07-1 = A
    /// approves a hardcoded constant for this slice; promote to a
