[HttpGet("class/{sessionId}")]
public async Task<IActionResult> GetClassDetails(string sessionId)
{
    var session = await _schedulingService.GetSessionByIdAsync(sessionId);
    // SPM-91: hide private (non-public) sessions from the public booking detail endpoint.
    // Booking is already blocked in ReserveSpotAsync; this closes the read-only detail disclosure.
    // Admin/instructor/payment paths call GetSessionByIdAsync directly and still see private sessions.
    if (session == null || !session.IsPublic) return NotFound(new { message = "Session not found." });

    // Pull rich blueprint data (description, benefits, muscle areas, etc.)
    var blueprint = await _schedulingService.GetBlueprintByIdAsync(session.ClassBlueprintId);
    var instructor = await _schedulingService.GetInstructorByIdAsync(session.InstructorId);

    return Ok(new
    {
        session = new
        {
            session.Id,
            session.ClassName,
            session.FocusArea,
            session.DifficultyLevel,
            session.Format,
            session.StartTime,
            session.EndTime,
            session.Capacity,
            session.CurrentBookings,
            // SPM-71 — singular kept for back-compat; list lets the detail
            // view render every piece of equipment used by the class.
            session.EquipmentType,
            EquipmentTypes = ResolveEquipmentTypes(session),

    var ok = await _waitlistService.LeaveAsync(clientId, entryId);
    if (!ok) return NotFound(new { message = "Waitlist entry not found or already left." });
    return Ok(new { success = true, message = "Removed from the waitlist." });
}

/// <summary>
/// P4-S02 — Admin-visible FIFO queue for a session. Read-only:
/// admin uses the existing AdminAddStudentAsync to override
/// capacity manually if needed (Q4-S02-6A).
/// </summary>
[HttpGet("session/{sessionId}/waitlist")]
[Authorize(Roles = "Admin")]
public async Task<IActionResult> GetSessionWaitlist(string sessionId)
{
    var entries = await _waitlistService.GetActiveForSessionAsync(sessionId);
    return Ok(entries.Select((e, i) => new
    {
        entryId = e.Id,
        position = i + 1,
        clientId = e.ClientId,
        clientName = e.ClientName,
        clientPhone = e.ClientPhone,
        clientEmail = e.ClientEmail,
        joinedAt = e.JoinedAt,
    }));
}

/// <summary>
/// SPM-71 — Resolves the equipment NAME list for a session in the public
/// schedule response. New sessions carry the denormalised
/// <see cref="CalendarSession.EquipmentTypes"/>; old documents only have the
/// singular <see cref="CalendarSession.EquipmentType"/>, which we surface as a
/// single-element list for backward compatibility. Blank entries are dropped.
/// </summary>
private static List<string> ResolveEquipmentTypes(CalendarSession s)
{
    var names = (s.EquipmentTypes ?? new List<string>())
        .Where(n => !string.IsNullOrWhiteSpace(n))
        .ToList();

