///   <item><b>Owner-instructors</b> → sets <c>SalaryAmount</c> + <c>CommissionAmount</c>
///     on the existing <see cref="OwnerDistribution"/> row and adjusts <c>TotalPayable</c>.</item>
///   <item><b>Non-owner instructors</b> → upserts a <see cref="StaffPayable"/> row with
///     salary + commission breakdown.</item>
/// </list>
/// Idempotent: fully re-derived from <c>PayrollRun.Results</c> on every recompute.
/// Runs after <see cref="EmitOwnerDistributionsAsync"/> (needs existing distribution
/// rows) and before reimbursement/bonus passes (which compose onto the rows we create).
/// </summary>
private async Task ApplyPayrollToPayablesAsync(MonthlyWashout washout, List<PayrollRun> monthPayrolls)
{
    // ── 1. Flatten instructor results from all payroll runs in the month ──
    // In practice there's exactly one PayrollRun per month (enforced by a
    // unique index), but the code handles N-runs defensively.
    var allResults = monthPayrolls.SelectMany(p => p.Results).ToList();
    if (allResults.Count == 0) return;

    // ── 2. Resolve the active owner roster to route owner-instructors ─────
    var roster = await _owners.ListAsync();
    var ownerByStaffId = roster
        .Where(o => o.IsActiveOwner)
        .ToDictionary(o => o.StaffId, o => o);

    // ── 3. Split results into owner vs non-owner buckets ──────────────────
    var ownerResults = new List<InstructorPayrollResult>();
    var staffResults = new List<InstructorPayrollResult>();
    foreach (var r in allResults)
    {
        if (ownerByStaffId.ContainsKey(r.InstructorId))
            ownerResults.Add(r);
        else
            staffResults.Add(r);
    }

