        BookingSource = "ADMIN"
    };
    await _attendances.InsertOneAsync(attendance);

    var update = Builders<CalendarSession>.Update.Inc(s => s.CurrentBookings, 1);
    await _sessions.UpdateOneAsync(s => s.Id == sessionId, update);

