public async Task<bool> CheckInClientAsync(string attendanceId)
{
    var update = Builders<Attendance>.Update.Set(a => a.Status, "CHECKED_IN");
    var result = await _attendances.UpdateOneAsync(a => a.Id == attendanceId, update);
    return result.ModifiedCount > 0;
}

