/// <summary>
/// Atomically claims <paramref name="seats"/> seat(s) on a SCHEDULED session,
/// guarding capacity inside a single <c>FindOneAndUpdate</c> so concurrent
/// bookings of the last seat(s) can never overbook. Returns true when the
/// seats were claimed; false when the session is missing / not SCHEDULED /
/// would exceed capacity. On a successful claim, callers MUST release via
/// <see cref="ReleaseSessionCapacityAsync"/> if a later step (e.g. the
/// attendance insert) fails, so the counter never drifts.
/// </summary>
private async Task<bool> TryClaimSessionCapacityAsync(string sessionId, int seats)
{
    if (seats <= 0) seats = 1;
    // $expr compares two fields in the same atomic op: CurrentBookings + seats <= Capacity.
    var capacityGuard = new BsonDocument("$expr", new BsonDocument("$lte", new BsonArray
    {
        new BsonDocument("$add", new BsonArray { "$CurrentBookings", seats }),
        "$Capacity"
    }));
    var filter = Builders<CalendarSession>.Filter.And(
        Builders<CalendarSession>.Filter.Eq(s => s.Id, sessionId),
        Builders<CalendarSession>.Filter.Eq(s => s.Status, "SCHEDULED"),
        new BsonDocumentFilterDefinition<CalendarSession>(capacityGuard));
    var updated = await _sessions.FindOneAndUpdateAsync(
        filter,
        Builders<CalendarSession>.Update.Inc(s => s.CurrentBookings, seats),
        new FindOneAndUpdateOptions<CalendarSession> { ReturnDocument = ReturnDocument.After });
    return updated != null;
}

/// <summary>Compensating release for a previously-claimed seat count (used on rollback).</summary>
private Task ReleaseSessionCapacityAsync(string sessionId, int seats) =>
    _sessions.UpdateOneAsync(s => s.Id == sessionId,
        Builders<CalendarSession>.Update.Inc(s => s.CurrentBookings, -Math.Max(1, seats)));

