namespace SoulPilates.Core.Interfaces;

/// <summary>
/// Server-side Meta (Facebook/Instagram) Conversions API sender. Mirrors the
/// browser Pixel: the client fires <c>fbq('track', ...)</c> with an
/// <c>eventID</c>, and this service posts the SAME event (same <c>eventID</c>)
/// straight to Meta's Graph API so the two are de-duplicated. Because the call
/// leaves our own server it survives ad-blockers / iOS / cookie loss that would
/// drop the browser Pixel — the key to good ad optimisation.
/// </summary>
public interface IMetaConversionsService
{
    /// <summary>True when a Pixel ID + access token are configured and tracking is on.</summary>
    bool IsEnabled { get; }

    /// <summary>The public Pixel/dataset ID (safe to expose to the browser). Empty when unset.</summary>
    string PixelId { get; }

    /// <summary>
    /// Send one conversion event to Meta. Raw email/phone are hashed (SHA-256)
    /// before leaving the process; never pass already-hashed values. Fire-and-
    /// forget safe — swallows/loggs failures so a tracking hiccup never breaks a
    /// booking.
    /// </summary>
    Task SendEventAsync(MetaConversionEvent evt, CancellationToken ct = default);
}

/// <summary>Input for a single Conversions API event.</summary>
public class MetaConversionEvent
{
    public string EventName { get; set; } = "";
    public string EventId { get; set; } = "";
    public string? EventSourceUrl { get; set; }

    // Raw (un-hashed) customer identifiers — improve match quality. Optional.
    public string? Email { get; set; }
    public string? Phone { get; set; }

    // Meta browser cookies, forwarded from the client for attribution.
    public string? Fbp { get; set; }
    public string? Fbc { get; set; }

    // Request context, captured server-side.
    public string? ClientIpAddress { get; set; }
    public string? ClientUserAgent { get; set; }

    // Custom data.
    public decimal? Value { get; set; }
    public string? Currency { get; set; }
    public string? ContentName { get; set; }
    public string? ContentCategory { get; set; }
    public List<string>? ContentIds { get; set; }
}

