const API = import.meta.env.PUBLIC_API_URL;

// ── State ──
let selectedDate = startOfDay(new Date()); // currently selected date chip
let rangeStart = selectedDate;             // derived — for loadSchedule compat
let rangeEnd   = selectedDate;             // derived — single-day selection
let dateChipCount = 90;                    // 3 months of chips by default
const DATE_CHIP_MAX = 365;                 // max ~12 months
let activeLevel = "all"; // 'all' | 'BEGINNER' | 'INTERMEDIATE' | 'ADVANCED'
let activeEquipment = null; // null | 'REFORMER' | 'WUNDA_CHAIR' | 'LADDER_BARREL'
let activeInstructor = "all"; // 'all' | instructor name
let allSessions = [];
let currentSessionId = null;
// Lookup: normalized equipment NAME -> equipment ImageUrl.
// Built from the already-loaded /api/equipment/public data so class cards
// can show the matching equipment image instead of the blueprint hero image.
let equipmentImageByName = {};
// SPM-77: setInterval handles for the auto-playing equipment galleries on
// class cards. Cleared on every renderClasses() so re-rendering the schedule
// never leaks timers.
let _cardGalleryTimers = [];
// ── Schedule transition state ──
let _scheduleAbortCtrl = null;   // AbortController for in-flight fetch
let _scheduleTransTimer = null;  // pending fade-in timer handle

// ── Format state (GROUP / PRIVATE) ──
// Read initial format from URL ?format=PRIVATE (used by instructor profile links)
let activeFormat = (() => {
  const params = new URLSearchParams(window.location.search);
  const fmt = (params.get('format') || '').toUpperCase();
  return fmt === 'PRIVATE' ? 'PRIVATE' : 'GROUP';
})();

// ── Init ──
translatePage();
initFormatToggle();
loadCredits();
initDateScroller();
setupFilters();
loadEquipmentFilters();
// loadSchedule is called by initDateScroller → selectDateChip
document
