// ── Format Toggle ──
function initFormatToggle() {
  // Highlight the correct button on load
  document.querySelectorAll('.sp-format-btn').forEach((btn) => {
    btn.classList.toggle('active', btn.dataset.format === activeFormat);
    btn.addEventListener('click', () => {
      if (btn.dataset.format === activeFormat) return;
      document.querySelectorAll('.sp-format-btn').forEach((b) => b.classList.remove('active'));
      btn.classList.add('active');
      activeFormat = btn.dataset.format;
      // Update URL without reload for bookmarkability
      const url = new URL(window.location);
      if (activeFormat === 'GROUP') {
        url.searchParams.delete('format');
      } else {
        url.searchParams.set('format', activeFormat);
      }
      window.history.replaceState({}, '', url);
      // Reset sub-filters
      activeInstructor = 'all';
      // Reload data
      loadCredits();
      loadSchedule();
    });
  });
}

