async function loadSchedule() {
  // Funnel: schedule is being shown (first render = entered the funnel).
  if (window.spTrackFunnel) window.spTrackFunnel('ScheduleViewed');

  // Cancel any in-flight request and pending transition
  if (_scheduleAbortCtrl) _scheduleAbortCtrl.abort();
  if (_scheduleTransTimer) clearTimeout(_scheduleTransTimer);

  // Immediately fade out the current view
  fadeOutSchedule();

  // Short delay before showing skeleton + firing request (80ms feels snappy but not janky)
  _scheduleAbortCtrl = new AbortController();
  const signal = _scheduleAbortCtrl.signal;

  await new Promise(res => { _scheduleTransTimer = setTimeout(res, 80); });
  if (signal.aborted) return;

  document.getElementById("classSkeleton").style.display = "block";
  document.getElementById("emptyState").style.display = "none";
  document.getElementById("errorState").style.display = "none";
  document.getElementById("classList").innerHTML = "";
  fadeInSchedule();

  // Include the full end day → end+1 midnight exclusive
  const endExclusive = addDays(rangeEnd, 1);

  try {
    const res = await fetch(
      `${API}/api/booking/schedule?start=${rangeStart.toISOString()}&end=${endExclusive.toISOString()}&format=${activeFormat}`,
      { signal },
    );
    if (signal.aborted) return;
    if (!res.ok) throw new Error("Bad response: " + res.status);
    allSessions = await res.json();
    buildInstructorFilter(allSessions);
    renderClasses();
    // GA4 funnel: user is browsing the class schedule
    if (typeof window.spTrackEvent === 'function') {
      window.spTrackEvent('view_item_list', {
        item_list_id: 'class_schedule',
        item_list_name: 'Class Schedule',
        items: allSessions.slice(0, 10).map(s => ({
          item_id: s.id,
          item_name: s.className,
          item_category: s.format,
        })),
      });
    }
  } catch (e) {
    if (e.name === 'AbortError') return; // cancelled — silently ignore
    console.error("Failed to load schedule", e);
    allSessions = [];
    document.getElementById("classSkeleton").style.display = "none";
    document.getElementById("classList").innerHTML = "";
    document.getElementById("emptyState").style.display = "none";
    document.getElementById("errorState").style.display = "flex";
  }
}

async function loadCredits() {
  const token = localStorage.getItem("customer_token");
  const badge = document.getElementById("creditsBadge");
  if (!token) { badge.style.display = "none"; return; }
  try {
    const res = await fetch(`${API}/api/customer/my-packages`, {
      headers: { Authorization: "Bearer " + token },
    });
    if (!res.ok) { badge.style.display = "none"; return; }
    const packages = await res.json();
    const active = (packages || []).filter((p) => p.creditsRemaining > 0);

    const groupTotal = active.filter(p => p.format === 'GROUP' || p.format === 'MIXED')
      .reduce((s, p) => s + p.creditsRemaining, 0);
    const matTotal = active.filter(p => p.format === 'MAT')
      .reduce((s, p) => s + p.creditsRemaining, 0);
    const privateTotal = active.filter(p => p.format === 'PRIVATE')
      .reduce((s, p) => s + p.creditsRemaining, 0);

    const showGroup = activeFormat === 'GROUP' && groupTotal > 0;
    const showMat   = activeFormat === 'GROUP' && matTotal > 0;
    const showPriv  = activeFormat === 'PRIVATE' && privateTotal > 0;

    const groupEl   = document.getElementById("creditsGroupBlock");
    const matEl     = document.getElementById("creditsMatBlock");
    const privateEl = document.getElementById("creditsPrivateBlock");

    groupEl.style.display = showGroup ? "flex" : "none";
    document.getElementById("creditsGroupCount").textContent = groupTotal;
    document.getElementById("creditsGroupLabel").textContent = groupTotal === 1 ? "Group Class" : "Group Classes";

    matEl.style.display = showMat ? "flex" : "none";
    document.getElementById("creditsMatCount").textContent = matTotal;
    document.getElementById("creditsMatLabel").textContent = matTotal === 1 ? "Mat Class" : "Mat Classes";

    privateEl.style.display = showPriv ? "flex" : "none";
    document.getElementById("creditsPrivateCount").textContent = privateTotal;
    document.getElementById("creditsPrivateLabel").textContent = privateTotal === 1 ? "Private" : "Private";

    // Fix divider borders: only the 2nd+ visible item gets a left border
    const visibleItems = [groupEl, matEl, privateEl].filter(el => el.style.display !== "none");
    visibleItems.forEach((el, i) => {
      el.style.borderLeft = i === 0 ? "none" : "1px solid var(--sp-border)";
      el.style.paddingLeft = i === 0 ? "0" : "16px";
    });

    badge.style.display = (showGroup || showMat || showPriv) ? "block" : "none";
  } catch (e) {
    /* silent */
  }
}

// ── Render ──
function renderClasses() {
  const list = document.getElementById("classList");
  document.getElementById("classSkeleton").style.display = "none";

  // SPM-77: stop any auto-play timers from the previous render before the
  // old card DOM is replaced, so setInterval handles never leak.
  _cardGalleryTimers.forEach((id) => clearInterval(id));

