1	using Microsoft.AspNetCore.Authorization;
2	using Microsoft.AspNetCore.Mvc;
3	using SoulPilates.Core.Interfaces;
4	using System.IO;
5	using System.Threading.Tasks;
6	
7	namespace SoulPilates.API.Controllers;
8	
9	[ApiController]
10	[Route("api/[controller]")]
11	public class PaymentController : ControllerBase
12	{
13	    private readonly IPaymentService _paymentService;
14	    private readonly ISchedulingService _schedulingService;
15	    private readonly ISettingsService _settingsService;
16	
17	    public PaymentController(IPaymentService paymentService, ISchedulingService schedulingService, ISettingsService settingsService)
18	    {
19	        _paymentService = paymentService;
20	        _schedulingService = schedulingService;
21	        _settingsService = settingsService;
22	    }
23	
24	    /// <summary>
25	    /// Get a price quote for a given session and payment method.
26	    /// Returns the base session fee, amount due now (including any online fee), and fee breakdown.
27	    /// <para>
28	    /// <c>quantity</c> defaults to 1; group classes use this to multiply the
29	    /// session fee for multi-seat bookings. <c>clientId</c> is sourced from the
30	    /// authenticated principal when present, but can also be passed explicitly
31	    /// (anonymous-quote path used by the booking page before the customer
32	    /// finalises auth). Upsell suggestions are admin-configurable; an empty
33	    /// <c>upsells</c> list means none are eligible or the feature is off.
34	    /// </para>
35	    /// </summary>
36	    [HttpGet("quote")]
37	    public async Task<IActionResult> Quote(
38	        [FromQuery] string sessionId,
39	        [FromQuery] string paymentMethod,
40	        [FromQuery] int quantity = 1,
41	        [FromQuery] string? clientId = null)
42	    {
43	        var session = await _schedulingService.GetSessionByIdAsync(sessionId);
44	        if (session == null) return NotFound(new { message = "Session not found." });
45	
46	        // Prefer the authenticated principal — keeps clients from masquerading.
47	        // Fall back to the query param for the anonymous browse path.
48	        var resolvedClientId = User?.FindFirst("clientId")?.Value
49	            ?? User?.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value
50	            ?? clientId;
51	
52	        try
53	        {
54	            // Resolve the drop-in price: prefer the session's snapshotted price, but
55	            // fall back to the blueprint's current price for sessions materialized before
56	            // the price was set (avoids PAYMENT.MISSING_SESSION_FEE for those sessions).
57	            var sessionFee = session.DropInPrice;
