using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.Interfaces;
using System.IO;
using System.Threading.Tasks;

namespace SoulPilates.API.Controllers;

[ApiController]
[Route("api/[controller]")]
public class PaymentController : ControllerBase
{
    private readonly IPaymentService _paymentService;
    private readonly ISchedulingService _schedulingService;
    private readonly ISettingsService _settingsService;

    public PaymentController(IPaymentService paymentService, ISchedulingService schedulingService, ISettingsService settingsService)
    {
        _paymentService = paymentService;
        _schedulingService = schedulingService;
        _settingsService = settingsService;
    }

    /// <summary>
    /// Get a price quote for a given session and payment method.
    /// Returns the base session fee, amount due now (including any online fee), and fee breakdown.
    /// <para>
    /// <c>quantity</c> defaults to 1; group classes use this to multiply the
    /// session fee for multi-seat bookings. <c>clientId</c> is sourced from the
    /// authenticated principal when present, but can also be passed explicitly
    /// (anonymous-quote path used by the booking page before the customer
    /// finalises auth). Upsell suggestions are admin-configurable; an empty
    /// <c>upsells</c> list means none are eligible or the feature is off.
    /// </para>
    /// </summary>
    [HttpGet("quote")]
    public async Task<IActionResult> Quote(
        [FromQuery] string sessionId,
        [FromQuery] string paymentMethod,
        [FromQuery] int quantity = 1,
        [FromQuery] string? clientId = null)
    {
        var session = await _schedulingService.GetSessionByIdAsync(sessionId);
        if (session == null) return NotFound(new { message = "Session not found." });

        // Prefer the authenticated principal — keeps clients from masquerading.
        // Fall back to the query param for the anonymous browse path.
        var resolvedClientId = User?.FindFirst("clientId")?.Value
            ?? User?.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value
            ?? clientId;

        try
        {
            // Resolve the drop-in price: prefer the session's snapshotted price, but
            // fall back to the blueprint's current price for sessions materialized before
            // the price was set (avoids PAYMENT.MISSING_SESSION_FEE for those sessions).
            var sessionFee = session.DropInPrice;
            if (sessionFee is null && !string.IsNullOrWhiteSpace(session.ClassBlueprintId))
            {
                var bp = await _schedulingService.GetBlueprintByIdAsync(session.ClassBlueprintId);
                if (bp != null) sessionFee = bp.DropInPrice;
            }

            var q = await _paymentService.QuotePriceAsync(
                session.Format,
                paymentMethod,
                customSessionFee: sessionFee,
                quantity: quantity,
                clientId: resolvedClientId);
            return Ok(new
            {
                sessionFee = q.SessionFee,
                amountDueNow = q.AmountDueNow,
                amountDueAtStudio = q.AmountDueAtStudio,
                depositPercentage = q.DepositPercentage,
                feeAmount = q.FeeAmount,
                feePercentage = q.FeePercentage,
                currency = q.Currency,
                quantity = q.Quantity,
                upsells = q.Upsells.Select(u => new
                {
                    productId = u.ProductId,
                    name = u.Name,
                    description = u.Description,
                    formatRestriction = u.FormatRestriction,
                    basePrice = u.BasePrice,
                    credits = u.Credits,
                    validityDays = u.ValidityDays,
                    pricePerClass = u.PricePerClass,
                    savingsPercentage = u.SavingsPercentage,
                }),
            });
        }
        catch (System.ArgumentException ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    /// <summary>
    /// Public (no auth) checkout configuration endpoint.
    /// Returns admin-configured flags controlling which payment options appear at checkout
    /// and the partial payment label the customer sees.
    /// </summary>
    [HttpGet("checkout-settings")]
    [AllowAnonymous]
    public async Task<IActionResult> GetCheckoutSettings(CancellationToken ct)
    {
        var s = await _settingsService.GetAsync(ct);
        return Ok(new
        {
            allowOnlinePayment = s.AllowOnlinePayment,
            allowPartialPayment = s.AllowPartialPayment,
            allowPayAtStudio = s.AllowPayAtStudio,
            depositPercentage = s.DepositPercentage,
            onlinePaymentFeePercentage = s.OnlinePaymentFeePercentage,
            partialPaymentLabelEn = s.PartialPaymentLabelEn,
            partialPaymentLabelVi = s.PartialPaymentLabelVi,
            enableCheckoutPackageUpsell = s.EnableCheckoutPackageUpsell,
            upsellHideForActivePackageHolders = s.UpsellHideForActivePackageHolders,
            upsellHeadlineEn = s.UpsellHeadlineEn,
            upsellHeadlineVi = s.UpsellHeadlineVi,
            upsellPackageIdGroup = s.UpsellPackageIdGroup,
            upsellPackageIdPrivate = s.UpsellPackageIdPrivate,
            upsellPackageIdMixed = s.UpsellPackageIdMixed,
            // P5-S01: Reservation system
            enableReservationSystem = s.EnableReservationSystem,
            reservationExpiryMinutes = s.ReservationExpiryMinutes,
            // Guest checkout toggle — false by default; admin must opt in
            allowGuestCheckout = s.AllowGuestCheckout,
        });
    }

    /// <summary>
    /// Create a Stripe PaymentIntent for an attendance booking.
    /// Returns the client_secret needed by Stripe Elements.
    /// </summary>
    [HttpPost("create-intent")]
    public async Task<IActionResult> CreateIntent([FromBody] CreateIntentRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.AttendanceId))
            return BadRequest(new { message = "attendanceId is required." });
        if (string.IsNullOrWhiteSpace(request.PaymentMethod))
            return BadRequest(new { message = "paymentMethod is required." });

        try
        {
            var result = await _paymentService.CreateIntentAsync(request.AttendanceId, request.PaymentMethod);
            return Ok(new
            {
                paymentIntentId = result.PaymentIntentId,
                clientSecret = result.ClientSecret,
                amount = result.Amount,
                currency = result.Currency,
                publishableKey = result.PublishableKey,
                sessionFee = result.SessionFee,
                feeAmount = result.FeeAmount,
                feePercentage = result.FeePercentage,
                amountDueAtStudio = result.AmountDueAtStudio
            });
        }
        catch (System.Exception ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    /// <summary>
    /// Client-side confirmation hook — frontend calls this after Stripe.confirmCardPayment succeeds.
    /// Marks payment as SUCCEEDED. Webhook will idempotently confirm again later.
    /// </summary>
    [HttpPost("confirm")]
    public async Task<IActionResult> Confirm([FromBody] ConfirmRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.PaymentIntentId))
            return BadRequest(new { message = "paymentIntentId is required." });
        var ok = await _paymentService.MarkSucceededAsync(request.PaymentIntentId);
        return Ok(new { success = ok });
    }

    /// <summary>
    /// Stripe webhook receiver. Verifies signature, deduplicates by Stripe event id, and applies side effects exactly once.
    /// Returns:
    ///   200 — processed, replayed (already-seen event), or unsupported event type acknowledged.
    ///   400 — invalid Stripe signature.
    ///   503 — Stripe payments are disabled on this server.
    /// </summary>
    [HttpPost("webhook")]
    public async Task<IActionResult> Webhook()
    {
        using var reader = new StreamReader(Request.Body);
        var payload = await reader.ReadToEndAsync();
        var signature = Request.Headers["Stripe-Signature"].ToString();

        var outcome = await _paymentService.HandleWebhookAsync(payload, signature);
        return outcome switch
        {
            WebhookOutcome.Disabled =>
                StatusCode(503, new { message = "Stripe payments are not enabled on this server." }),
            WebhookOutcome.BadSignature =>
                BadRequest(new { message = "Invalid Stripe signature." }),
            WebhookOutcome.Replayed
                or WebhookOutcome.Processed
                or WebhookOutcome.UnsupportedEvent => Ok(new { outcome = outcome.ToString() }),
            _ => StatusCode(500, new { message = "Unexpected webhook outcome." })
        };
    }
}

public class CreateIntentRequest
{
    public string AttendanceId { get; set; } = null!;
    public string PaymentMethod { get; set; } = null!;
}

public class ConfirmRequest
{
