        // Promote RESERVED → BOOKED
        await _attendances.UpdateOneAsync(a => a.Id == attendanceId,
            Builders<Attendance>.Update.Set(a => a.Status, "BOOKED"));

        // P4-S04 — non-Stripe payment path (PACKAGE_CREDIT / PAY_AT_STUDIO).
        await _audit.LogAsync(
            action: "PAYMENT_CREATED",
            entityType: "PaymentRecord",
            entityId: record.Id!,
            after: new { record.AttendanceId, record.PaymentMethod, record.PaymentType, record.Amount, record.Status });

        // ── Create invoice for PACKAGE_CREDIT bookings ──────────────────
        // PAY_AT_STUDIO does NOT get an invoice yet — only when marked CHECKED_IN.
        if (paymentMethod == "PACKAGE_CREDIT")
        {
            await CreateBookingInvoiceAsync(
                attendance, session, quote.SessionFee, quote.SessionFee, "CREDIT");
        }

        // P5-PWA — ping admins/managers (zero-amount payments are still a meaningful event
        // because they represent a credit redemption or studio-balance booking finalisation).
        FireAndForgetPaymentPush(record, attendance, paymentMethod);

        // P5-PWA — the attendance just transitioned RESERVED → BOOKED, so this
        // is the correct moment for the "New booking" push to the instructor +
        // admins. (Previously this fired from BookingController.ReserveSpot,
        // which produced false positives for customers who abandoned checkout.)
        FireAndForgetBookingPush(attendance, session);

        // P5-S01 — Booking confirmation email. Only fire now that the
        // status is definitively BOOKED (not RESERVED).
        FireAndForgetBookingEmail(attendance, session);

        return new PaymentIntentResult
        {
            PaymentIntentId = $"local_{record.Id}",
            ClientSecret = "",
            Amount = 0,
            Currency = Currency,
            PublishableKey = "", // No publishable key needed for zero-amount local payments
            SessionFee = quote.SessionFee,
            FeeAmount = quote.FeeAmount,
            FeePercentage = quote.FeePercentage,
            AmountDueAtStudio = quote.AmountDueAtStudio,
        };
    }

    // Stripe path — fetch live config from database
    var stripe = await GetStripeAsync();

    if (!stripe.Enabled || string.IsNullOrWhiteSpace(stripe.SecretKey))
    {
        // Development / preview mode — return a mock secret so the UI flow can be tested.
        var mock = new PaymentRecord
        {
            AttendanceId = attendanceId,
            ClientId = attendance.ClientId,
            PaymentType = paymentMethod == "STRIPE_DEPOSIT" ? "DEPOSIT" : "FULL",
            PaymentMethod = "STRIPE",
            Amount = quote.AmountDueNow,
            Currency = Currency,
            Status = "PENDING",
            StripePaymentIntentId = $"pi_mock_{Guid.NewGuid():N}"
        };
        await _payments.InsertOneAsync(mock);

        return new PaymentIntentResult
        {
            PaymentIntentId = mock.StripePaymentIntentId!,
            ClientSecret = $"{mock.StripePaymentIntentId}_secret_mock",
            Amount = quote.AmountDueNow,
            Currency = Currency,
            PublishableKey = stripe.PublishableKey,
            SessionFee = quote.SessionFee,
            FeeAmount = quote.FeeAmount,
            FeePercentage = quote.FeePercentage,
            AmountDueAtStudio = quote.AmountDueAtStudio,
        };
    }

    // Real Stripe call: amount is in the smallest unit. For VND (zero-decimal) it's whole; for USD it's cents.
    EnsureStripeApiKey(stripe);
    var amountForStripe = IsZeroDecimalCurrency(Currency)
        ? (long)quote.AmountDueNow
        : (long)(quote.AmountDueNow * 100);

    var intentService = new PaymentIntentService();
    var intent = await intentService.CreateAsync(new PaymentIntentCreateOptions
    {
        Amount = amountForStripe,
        Currency = Currency.ToLowerInvariant(),
        AutomaticPaymentMethods = new PaymentIntentAutomaticPaymentMethodsOptions { Enabled = true },
        Metadata = new System.Collections.Generic.Dictionary<string, string>
        {
            { "kind", "attendance_booking" },
            { "attendanceId", attendanceId },
            { "paymentMethod", paymentMethod },
            { "bookingReference", attendance.BookingReference }
        }
    });

    var dbRecord = new PaymentRecord
    {
        AttendanceId = attendanceId,
        ClientId = attendance.ClientId,
        PaymentType = paymentMethod == "STRIPE_DEPOSIT" ? "DEPOSIT" : "FULL",
        PaymentMethod = "STRIPE",
        Amount = quote.AmountDueNow,
        Currency = Currency,
        Status = "PENDING",
        StripePaymentIntentId = intent.Id
    };
    await _payments.InsertOneAsync(dbRecord);

    // Stamp intent ID on the attendance for cross-reference
    await _attendances.UpdateOneAsync(a => a.Id == attendanceId,
        Builders<Attendance>.Update.Set(a => a.StripePaymentIntentId, intent.Id));

    return new PaymentIntentResult
    {
        PaymentIntentId = intent.Id,
        ClientSecret = intent.ClientSecret,
        Amount = quote.AmountDueNow,
        Currency = Currency,
        PublishableKey = stripe.PublishableKey,
        SessionFee = quote.SessionFee,
        FeeAmount = quote.FeeAmount,
        FeePercentage = quote.FeePercentage,
        AmountDueAtStudio = quote.AmountDueAtStudio,
    };
}

