          r.attendanceId || r.id || "",
        );
      }

      // 2. Create payment intent
      const ir = await fetch(`${API}/api/payment/create-intent`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          attendanceId:
            attendance.id || sessionStorage.getItem("sp_attendance_id"),
          paymentMethod: selectedMethod,
        }),
      });
      const intentRes = await ir.json();
      if (!ir.ok) throw new Error(intentRes.message || "Payment setup failed. Please try again.");

      // 3. If no charge needed → straight to confirmation
      if (intentRes.amount === 0 || !intentRes.clientSecret) {
        showConfirmation(attendance.bookingReference);
        return;
      }

      // 4. Otherwise, mount Stripe Elements
      await showCardView(intentRes);
    } catch (e) {
      alert(e.message || "Something went wrong.");
      btn.disabled = false;
      btn.querySelector("span").textContent = getContinueBtnLabel();
    }
  });

/**
 * Reveal the inline guest-contact form and scroll it into view so the
 * user can't miss it. Idempotent — safe to call multiple times. Also
 * wires the inline "Log in instead" link to preserve the in-progress
 * booking via the existing ?redirect= flow.
 */
function revealGuestContactForm() {
  // If guest checkout is disabled AND the visitor is not logged in,
  // redirect to login. Only redirect for unauthenticated visitors —
  // logged-in customers with missing contact details should be shown
  // the inline form instead of being bounced into an infinite loop.
  if (
    checkoutSettings.allowGuestCheckout === false &&
    !localStorage.getItem("customer_token")
  ) {
    const here = window.location.pathname + window.location.search;
    window.location.href = "/login?redirect=" + encodeURIComponent(here);
    return;
  }

  const section = document.getElementById("guestContactSection");
  if (section.style.display === "block") return;
  section.style.display = "block";
  // Friendly scroll — the section is now the most relevant unresolved
  // field on the page.
  setTimeout(() => {
    section.scrollIntoView({ behavior: "smooth", block: "center" });
    document.getElementById("guestName").focus();
  }, 50);

  const link = document.getElementById("linkToLogin");
  if (link && !link.dataset.bound) {
    link.dataset.bound = "true";
    link.addEventListener("click", (ev) => {
      ev.preventDefault();
      window.location.href =
        "/login?redirect=/checkout?session=" +
        encodeURIComponent(sessionId);
    });
  }
}

function showGuestError(msg) {
  const el = document.getElementById("guestError");
  el.textContent = msg;
  el.classList.add("visible");
  setTimeout(() => el.classList.remove("visible"), 5000);
}

// ── Stripe card view ──
async function showCardView(intentRes) {
  document.getElementById("viewMethod").style.display = "none";
  document.getElementById("viewCard").style.display = "block";
  document.getElementById("cardAmount").textContent = fmt(
    intentRes.amount,
    intentRes.currency,
  );

  // Mirror the booking essentials so the customer keeps context. We
  // copy from the already-populated viewMethod summary instead of
  // refetching — single source of truth for what's been shown.
  const mirror = (srcId, dstId) => {
    const src = document.getElementById(srcId);
    const dst = document.getElementById(dstId);
    if (src && dst) dst.innerHTML = src.innerHTML;
  };
  mirror("sumClass", "cardSumClass");
  mirror("sumInstructor", "cardSumInstructor");
  mirror("sumDateTime", "cardSumDateTime");

  // Price breakdown. Falls back gracefully if the API somehow omits
  // the new fields (e.g. running against an older backend mid-deploy).
  const sessionFee = intentRes.sessionFee ?? intentRes.amount;
  const feeAmount = intentRes.feeAmount ?? 0;
  const feePct = intentRes.feePercentage ?? 0;
  const dueAtStudio = intentRes.amountDueAtStudio ?? 0;
  document.getElementById("cardSumSessionFee").textContent = fmt(
    sessionFee,
    intentRes.currency,
  );

