using SoulPilates.Core.Entities;
using System.Threading.Tasks;

namespace SoulPilates.Core.Interfaces;

public interface IPaymentService
{
    /// <summary>
    /// Calculate the price summary for a session — accounts for default pricing,
    /// the chosen payment method (deposit/full/studio), and admin-configured
    /// online payment surcharge and deposit percentage from GlobalSettings.
    /// <para>
    /// <paramref name="quantity"/> multiplies the session fee for group multi-seat
    /// bookings (capped to 1 for PRIVATE format by the service). When
    /// <paramref name="clientId"/> is supplied and upsells are enabled in
    /// <see cref="GlobalSettings"/>, the returned quote includes a list of
    /// matching <see cref="UpsellSuggestion"/>s for the checkout card.
    /// </para>
    /// </summary>
    Task<PriceQuote> QuotePriceAsync(
        string sessionFormat,
        string paymentMethod,
        decimal? customSessionFee = null,
        int quantity = 1,
        string? clientId = null);

    /// <summary>
    /// Create a Stripe PaymentIntent for an attendance booking.
    /// Returns the client_secret for Stripe Elements to confirm.
    /// </summary>
    Task<PaymentIntentResult> CreateIntentAsync(string attendanceId, string paymentMethod);

    /// <summary>
    /// Mark a payment as succeeded after Stripe confirmation (called by webhook OR by client confirmation).
    /// </summary>
    Task<bool> MarkSucceededAsync(string paymentIntentId);

    /// <summary>
    /// Verify and process a Stripe webhook event.
    /// Returns a <see cref="WebhookOutcome"/> describing the outcome — the controller maps this to HTTP status codes.
    /// </summary>
    Task<WebhookOutcome> HandleWebhookAsync(string payload, string signatureHeader);

    /// <summary>
    /// Get a payment record by attendance ID.
    /// </summary>
    Task<PaymentRecord?> GetByAttendanceIdAsync(string attendanceId);

    /// <summary>
    /// Create a Stripe PaymentIntent that settles a draft package-purchase
    /// <see cref="Invoice"/>. The intent metadata carries
    /// <c>kind="package_purchase"</c> so the webhook dispatcher can route
    /// success to <see cref="MarkInvoicePaidAsync"/> rather than the
    /// attendance-anchored path.
    /// </summary>
    Task<PaymentIntentResult> CreatePackagePurchaseIntentAsync(string invoiceId);

    /// <summary>
    /// Marks the invoice associated with a successful package-purchase
    /// PaymentIntent as paid by registering a <see cref="Payment"/> against it.
    /// <see cref="IInvoiceService.AddPaymentAsync"/> then provisions the
    /// <see cref="ClientPackage"/> wallet and emails the receipt.
    /// Idempotent — repeat calls for the same intent are no-ops.
    /// </summary>
    Task<bool> MarkInvoicePaidAsync(string paymentIntentId);

    /// <summary>
    /// Same idempotent finalisation logic as <see cref="MarkInvoicePaidAsync"/>
    /// but takes the invoiceId directly. Used by the dev-mode customer confirm
    /// path where the mock PaymentIntent has no recoverable metadata. The
    /// caller is responsible for authorising the customer against the invoice
    /// before invoking this method.
    /// </summary>
    Task<bool> MarkInvoicePaidByIdAsync(string invoiceId, string paymentIntentId);
}

/// <summary>
/// A single upsell card surfaced by <see cref="IPaymentService.QuotePriceAsync"/>
/// when the customer would save money by buying a package instead of paying
/// drop-in. Admin-configurable via <see cref="GlobalSettings"/> Issue #2 fields.
/// </summary>
public class UpsellSuggestion
{
    public string ProductId { get; set; } = "";
    public string Name { get; set; } = "";
    public string? Description { get; set; }
    public string FormatRestriction { get; set; } = "NONE";
    public decimal BasePrice { get; set; }
    public int Credits { get; set; }
    public int ValidityDays { get; set; }
    public decimal PricePerClass { get; set; }
    /// <summary>Per-class % saving vs. the drop-in price the customer is currently being quoted.</summary>
    public int SavingsPercentage { get; set; }
}

public class PriceQuote
{
    public decimal SessionFee { get; set; }
    public decimal AmountDueNow { get; set; }       // What customer pays online (including any fee)
    public decimal AmountDueAtStudio { get; set; }  // What they pay at front desk
    public int DepositPercentage { get; set; }
    /// <summary>Online payment surcharge amount (0 if fee is disabled or method is not online).</summary>
    public decimal FeeAmount { get; set; }
    /// <summary>Configured fee percentage that produced FeeAmount (0 if disabled).</summary>
    public decimal FeePercentage { get; set; }
    public string Currency { get; set; } = "VND";

    /// <summary>Number of seats this quote covers — multiplies the session fee for STRIPE_FULL / STRIPE_DEPOSIT / PAY_AT_STUDIO. Default 1.</summary>
    public int Quantity { get; set; } = 1;

    /// <summary>
    /// Upsell suggestions surfaced by the checkout card when the customer would
    /// save money by buying a matching package. Empty when the admin master
    /// switch is off, when no eligible product exists, or when the customer
    /// already owns an active package and the admin set
    /// <see cref="GlobalSettings.UpsellHideForActivePackageHolders"/>=true.
    /// </summary>
    public List<UpsellSuggestion> Upsells { get; set; } = new();
}

public class PaymentIntentResult
{
    public string PaymentIntentId { get; set; } = "";
    public string ClientSecret { get; set; } = "";
    public decimal Amount { get; set; }
    public string Currency { get; set; } = "VND";
    public string PublishableKey { get; set; } = "";

    // ── Itemised breakdown for the checkout summary card ──
    // These mirror the matching <see cref="PriceQuote"/> fields so the UI
    // can render "Session Fee + Online Fee = Pay Now" without re-fetching
    // the quote endpoint. Zero on non-online flows (PACKAGE_CREDIT, PAY_AT_STUDIO).
    public decimal SessionFee { get; set; }
    public decimal FeeAmount { get; set; }
    public decimal FeePercentage { get; set; }
    public decimal AmountDueAtStudio { get; set; }
}

