// ── Embedded Stripe Checkout (cleaner, Stripe-designed form) ──
async function mountEmbeddedCheckout(intentRes) {
  stripe = window.Stripe(intentRes.publishableKey);

  // Stripe renders its own pay button inside the embedded checkout, so hide
  // our "Confirm & Pay" button — the user pays within Stripe's form.
  const payBtn = document.getElementById("payBtn");
  if (payBtn) payBtn.style.display = "none";

  // Clean up any prior instance (e.g. user went back and re-entered checkout).
  if (embeddedCheckout) {
    try { embeddedCheckout.destroy(); } catch (e) {}
    embeddedCheckout = null;
  }

  embeddedCheckout = await stripe.initEmbeddedCheckout({
    clientSecret: intentRes.clientSecret,
    onComplete: async () => {
      // Finalise via the existing confirm hook; the webhook double-confirms
      // idempotently so this is safe even if the request is lost.
      try {
        await fetch(`${API}/api/payment/confirm`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ paymentIntentId: intentRes.paymentIntentId }),
        });
      } catch (e) {
        /* webhook remains the authoritative finaliser */
      }
      try { embeddedCheckout.destroy(); } catch (e) {}
      embeddedCheckout = null;
      showConfirmation(
        attendance.bookingReference ||
          sessionStorage.getItem("sp_attendance_id"),
      );
    },
  });
  embeddedCheckout.mount("#paymentElement");
}

