    public async Task UpdateStripeKeysAsync(
        bool enabled,
        string? publishableKey,
        string? secretKey,
        string? webhookSecret,
        CancellationToken ct = default)
    {
        var current = await GetAsync(ct);

        var updateDef = Builders<GlobalSettings>.Update
            .Set(s => s.StripeEnabled, enabled)
            .Set(s => s.UpdatedAt, DateTime.UtcNow);

        // Only update a key field if a non-null value was supplied.
        // Null means "leave the current value unchanged".
        if (publishableKey is not null)
            updateDef = updateDef.Set(s => s.StripePublishableKeyEncrypted,
                SettingsEncryptionHelper.Encrypt(publishableKey, _encryptionKey));

        if (secretKey is not null)
            updateDef = updateDef.Set(s => s.StripeSecretKeyEncrypted,
                SettingsEncryptionHelper.Encrypt(secretKey, _encryptionKey));

        if (webhookSecret is not null)
            updateDef = updateDef.Set(s => s.StripeWebhookSecretEncrypted,
                SettingsEncryptionHelper.Encrypt(webhookSecret, _encryptionKey));

        await _settings.UpdateOneAsync(s => s.Id == current.Id, updateDef, cancellationToken: ct);
    }
