/// <summary>
/// AES-256-CBC encryption helper for storing sensitive configuration values
/// (Stripe keys, webhook secrets, etc.) at rest in MongoDB.
///
/// Key derivation: PBKDF2 with SHA-256, 100 000 iterations, from the
/// application's JWT secret — the same secret that is already treated as a
/// deployment credential. This avoids introducing a second secret-management
/// channel while still ensuring data-at-rest protection.
///
/// Wire format: <c>Base64(IV ‖ ciphertext)</c>.
/// </summary>
public static class SettingsEncryptionHelper
{
    private const int KeySizeBytes = 32;   // AES-256
    private const int IvSizeBytes  = 16;   // AES block size
    private const int Iterations   = 100_000;
    private static readonly byte[] Salt = Encoding.UTF8.GetBytes("SoulPilates.Settings.Encryption.v1");

    /// <summary>Encrypt a plaintext string and return the Base64 wire format.</summary>
    public static string Encrypt(string plaintext, string masterKey)
    {
        if (string.IsNullOrEmpty(plaintext)) return "";

        using var deriveBytes = new Rfc2898DeriveBytes(masterKey, Salt, Iterations, HashAlgorithmName.SHA256);
        var key = deriveBytes.GetBytes(KeySizeBytes);

        using var aes = Aes.Create();
        aes.Key     = key;
        aes.Mode    = CipherMode.CBC;
        aes.Padding = PaddingMode.PKCS7;
