      const r = await fetch(`${API}/api/package-purchase/checkout`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + token,
        },
        body: JSON.stringify({ productId }),
      });
      if (r.status === 401) {
        window.location.href = "/login?redirect=" +
          encodeURIComponent(window.location.pathname + window.location.search);
        return;
      }
      if (!r.ok) {
        const err = await r.json().catch(() => ({}));
        throw new Error(err.message || "Could not start checkout.");
      }
      intent = await r.json();
      // GA4: package checkout started
      if (typeof window.spTrackEvent === 'function') {
        window.spTrackEvent('begin_checkout', {
          items: [{
            item_id: productId,
            item_name: product?.name || '',
            item_category: 'package',
            price: product?.basePrice || 0,
          }],
          value: intent.amount || product?.basePrice || 0,
          currency: intent.currency || 'VND',
        });
      }
      await showCardView();
    } catch (e) {
      btn.disabled = false;
      label.textContent = t("store.continueToPay");
      alert(e.message || "Something went wrong.");
    }
  });

async function showCardView() {
  document.getElementById("viewReview").style.display = "none";
  document.getElementById("viewCard").style.display = "block";

  const cardSummary = document.getElementById("cardSummary");
  // SPM-121: append the validity suffix only when there's a real expiry
  // window; null/0 validity is omitted rather than shown as "0 days".
  const summaryValidity =
    (intent.validityDays || 0) > 0
      ? ` · ${intent.validityDays} ${t("store.days")}`
      : "";
  cardSummary.innerHTML = `
    <div class="sp-pkg-review-line">
      <span class="label">${esc(product.name)}</span>
      <span class="value">${intent.credits} ${t("store.classes")}${esc(summaryValidity)}</span>
    </div>
    <div class="sp-pkg-review-total">
      <span class="label">${t("store.payNow")}</span>
      <span class="value">${fmtVnd(intent.amount)} <span style="font-size:14px;font-weight:500;color:var(--sp-text-muted);">${intent.currency || "VND"}</span></span>
    </div>
  `;

  if (!intent.publishableKey) {
    // Dev-mode mock path: Stripe keys aren't configured. We still
    // exercise the rest of the flow (confirm endpoint + wallet
    // provisioning) so the dev can see the full UX.
    document.getElementById("paymentElement").innerHTML = `
      <div style="padding:16px;background:#fff8e1;border-radius:8px;color:#7a5300;font-size:13px;">
        <strong>Development mode:</strong> Stripe keys not configured.<br>
        Click "Pay Now" to simulate a successful payment.
      </div>`;
    document.getElementById("payBtn").dataset.mock = "true";
    return;
  }

  stripe = window.Stripe(intent.publishableKey);
  elements = stripe.elements({
    clientSecret: intent.clientSecret,
    appearance: {
      theme: "flat",
      variables: {
        colorPrimary: "#9b6a4f",
        colorBackground: "#ffffff",
        fontFamily: "Inter, sans-serif",
        spacingUnit: "4px",
        borderRadius: "8px",
      },
    },
  });
  paymentElement = elements.create("payment");
  paymentElement.mount("#paymentElement");
}

document.getElementById("payBtn").addEventListener("click", async () => {
  const btn = document.getElementById("payBtn");
  const label = document.getElementById("payBtnLabel");
  btn.disabled = true;
  label.textContent = t("common.loading");

  try {
    if (btn.dataset.mock === "true") {
      // Mock path — POST straight to /confirm with the mock intent id.
      await fetch(`${API}/api/package-purchase/confirm`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + token,
        },
        body: JSON.stringify({
          invoiceId: intent.invoiceId,
          paymentIntentId: intent.paymentIntentId,
        }),
      });
      showSuccess();
      return;
    }

    const { error, paymentIntent } = await stripe.confirmPayment({
      elements,
      redirect: "if_required",
    });
    if (error) {
      showError(error.message);
      btn.disabled = false;
      label.textContent = t("store.payNow");
      return;
    }
    if (paymentIntent && paymentIntent.status === "succeeded") {
      // The Stripe webhook will fire `payment_intent.succeeded` and
      // mark the invoice paid + provision the wallet idempotently.
      // We *also* hit /confirm here so the customer doesn't have
      // to wait for the webhook round-trip — the second call is a
      // no-op once the invoice is paid.
      await fetch(`${API}/api/package-purchase/confirm`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + token,
        },
        body: JSON.stringify({
          invoiceId: intent.invoiceId,
          paymentIntentId: paymentIntent.id,
        }),
      });
      showSuccess();
    }
  } catch (e) {
    showError(e.message || "Payment failed.");
    btn.disabled = false;
    label.textContent = t("store.payNow");
  }

