async function mountEmbeddedCheckout() {
  stripe = window.Stripe(intent.publishableKey);

  // Stripe renders its own pay button inside the embedded checkout.
  const payBtn = document.getElementById("payBtn");
  if (payBtn) payBtn.style.display = "none";

  if (embeddedCheckout) {
    try { embeddedCheckout.destroy(); } catch (e) {}
    embeddedCheckout = null;
  }

  embeddedCheckout = await stripe.initEmbeddedCheckout({
    clientSecret: intent.clientSecret,
    onComplete: async () => {
      // Finalise via the existing confirm hook; the webhook double-confirms
      // idempotently so this is safe even if the request is lost.
      try {
        await fetch(`${API}/api/package-purchase/confirm`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: "Bearer " + token,
          },
          body: JSON.stringify({
            invoiceId: intent.invoiceId,
            paymentIntentId: intent.paymentIntentId,
          }),
        });
      } catch (e) {
        /* webhook remains the authoritative finaliser */
      }
      try { embeddedCheckout.destroy(); } catch (e) {}
      embeddedCheckout = null;
      showSuccess();
    },
  });
  embeddedCheckout.mount("#paymentElement");
}

