    public async Task<bool> MarkInvoicePaidAsync(string paymentIntentId)
    {
        // Pull the intent (real or mock) to recover the invoiceId from metadata.
        string? invoiceId = null;

        var stripeForInvoice = await GetStripeAsync();
        if (stripeForInvoice.Enabled && !string.IsNullOrWhiteSpace(stripeForInvoice.SecretKey)
            && !paymentIntentId.StartsWith("pi_pkg_mock_", StringComparison.Ordinal))
        {
            try
            {
                EnsureStripeApiKey(stripeForInvoice);
                var intentService = new PaymentIntentService();
                var intent = await intentService.GetAsync(paymentIntentId);
                if (intent.Metadata != null && intent.Metadata.TryGetValue("invoiceId", out var resolved))
                {
                    invoiceId = resolved;
                }
            }
            catch (Exception ex)
            {
                _logger.LogWarning(ex, "Could not resolve PaymentIntent {PaymentIntentId} while marking invoice paid.", paymentIntentId);
                return false;
            }
        }

        if (string.IsNullOrWhiteSpace(invoiceId))
        {
            // Dev-mode mock intents don't go through Stripe so we can't recover the
            // invoice from intent.Metadata. Caller (the controller's confirm
            // endpoint) is responsible for invoking the parallel
            // MarkInvoicePaidForDevAsync helper with the invoiceId in hand.
            _logger.LogInformation("MarkInvoicePaidAsync skipped — no invoiceId resolved from {PaymentIntentId}.", paymentIntentId);
            return false;
        }

        return await MarkInvoicePaidByIdAsync(invoiceId, paymentIntentId);
    }
