public async Task<bool> FinalizeCheckoutSessionAsync(string checkoutSessionId)
{
    if (string.IsNullOrWhiteSpace(checkoutSessionId)) return false;

    var stripe = await GetStripeAsync();
    if (!stripe.Enabled || string.IsNullOrWhiteSpace(stripe.SecretKey)) return false;
    EnsureStripeApiKey(stripe);

    Stripe.Checkout.Session session;
    try
    {
        session = await new Stripe.Checkout.SessionService().GetAsync(checkoutSessionId);
    }
    catch (Exception ex)
    {
        _logger.LogWarning(ex, "Could not retrieve Checkout Session {SessionId} for finalisation.", checkoutSessionId);
        return false;
    }

    // Never trust the caller — only finalise a session Stripe reports as paid.
    if (!string.Equals(session.PaymentStatus, "paid", StringComparison.OrdinalIgnoreCase))
    {
        _logger.LogInformation("Checkout Session {SessionId} not paid (payment_status={Status}); skipping finalise.",
            checkoutSessionId, session.PaymentStatus);
        return false;
    }

    var realPi = session.PaymentIntentId;
    if (string.IsNullOrWhiteSpace(realPi))
    {
        _logger.LogWarning("Checkout Session {SessionId} paid but has no PaymentIntent id.", checkoutSessionId);
        return false;
    }

    var kind = session.Metadata != null && session.Metadata.TryGetValue("kind", out var k) ? k : "";

    // Package purchase: the PaymentIntent carries invoiceId in its metadata.
    if (string.Equals(kind, "package_purchase", StringComparison.Ordinal))
        return await MarkInvoicePaidAsync(realPi);

    // Attendance booking: backfill the now-known PaymentIntent id onto the
    // pending PaymentRecord (keyed by session id) + the attendance, so
    // MarkSucceededAsync — which looks records up by PaymentIntent id — finalises.
    var pending = await _payments
        .Find(p => p.StripeCheckoutSessionId == checkoutSessionId)
        .FirstOrDefaultAsync();
    if (pending != null)
        await _payments.UpdateOneAsync(p => p.Id == pending.Id,
            Builders<PaymentRecord>.Update.Set(p => p.StripePaymentIntentId, realPi));

    var attendanceId = session.Metadata != null && session.Metadata.TryGetValue("attendanceId", out var aId) ? aId : pending?.AttendanceId;
    if (!string.IsNullOrWhiteSpace(attendanceId))
        await _attendances.UpdateOneAsync(a => a.Id == attendanceId,
            Builders<Attendance>.Update.Set(a => a.StripePaymentIntentId, realPi));

    return await MarkSucceededAsync(realPi);
}

