cd /opt/soulpilates
JWT=$(grep '^JWT_SECRET=' prod.env | cut -d= -f2-)
PW="$(grep '^MONGO_PASSWORD=' prod.env|cut -d= -f2)"
WHENC=$(MASTER="$JWT" WH="whsec_I6U7wkfE5ZtuSVpiJ7ZGUrBd1M5e3y4A" python3 - <<'PY'
import os, base64
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from cryptography.hazmat.primitives import hashes, padding
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
salt=b"SoulPilates.Settings.Encryption.v1"
def enc(pt, master):
    key=PBKDF2HMAC(algorithm=hashes.SHA256(), length=32, salt=salt, iterations=100000).derive(master.encode())
    iv=os.urandom(16)
    p=padding.PKCS7(128).padder(); data=p.update(pt.encode())+p.finalize()
    c=Cipher(algorithms.AES(key), modes.CBC(iv)).encryptor(); ct=c.update(data)+c.finalize()
    return base64.b64encode(iv+ct).decode()
print(enc(os.environ['WH'], os.environ['MASTER']))
PY
)
