db=db.getSiblingDB('soulpilates');
const r=db.Settings.updateOne({}, { \$set: { StripeWebhookSecretEncrypted: '$WHENC' } });
print('Settings webhook secret set: matched='+r.matchedCount+' modified='+r.modifiedCount);
const s=db.Settings.findOne({});
print('whEnc.len='+((s.StripeWebhookSecretEncrypted||'').length));
"

