using Microsoft.Extensions.Logging;
using MongoDB.Driver;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.Services;

/// <summary>
/// Post-first-class review request.
///
/// <para>
/// Once per tick: find sessions that ended ~2h ago (a bounded window so a missed
/// tick can still catch up), fan out to the attendances on those sessions, and —
/// for any attendance that is the client's FIRST attended class — send the Google
/// review email. Each processed attendance is tagged via an atomic <c>$push</c> so
/// it is never reconsidered, exactly like <see cref="ReminderService"/>.
/// </para>
///
/// <para>
/// "First class" is decided by loading the client's attended attendances and
/// checking none of them belongs to a session that started strictly before this
/// one. Because only a client's earliest-ever class can satisfy that check, and
/// old classes fall outside the candidate window, long-standing clients are never
/// emailed — only genuine first-timers going forward.
/// </para>
/// </summary>
public class ReviewRequestService : IReviewRequestService
{
    private readonly IMongoCollection<CalendarSession> _sessions;
    private readonly IMongoCollection<Attendance> _attendances;
    private readonly IEmailService _emailService;
    private readonly ILogger<ReviewRequestService> _logger;

    /// <summary>Tag stored on <see cref="Attendance.RemindersSent"/> once handled.</summary>
    private const string ReviewTag = "review-request";

    /// <summary>Statuses that count as "the client attended this class".</summary>
    private static readonly string[] AttendedStatuses = { "BOOKED", "CHECKED_IN" };

    public ReviewRequestService(
        MongoDbContext dbContext,
        IEmailService emailService,
        ILogger<ReviewRequestService> logger)
    {
        _sessions = dbContext.GetCollection<CalendarSession>("CalendarSessions");
        _attendances = dbContext.GetCollection<Attendance>("Attendances");
        _emailService = emailService;
        _logger = logger;
    }

    public async Task<int> SendDueRequestsAsync(DateTime nowUtc, CancellationToken cancellationToken)
    {
        // Candidate window: class ended between 2h and 24h ago. The 2h floor is
        // the requested delay; the 24h ceiling bounds the scan and keeps a missed
        // tick recoverable without ever emailing about ancient history.
        var windowEnd = nowUtc.AddHours(-2);
        var windowStart = nowUtc.AddHours(-24);

        var sessionFilter = Builders<CalendarSession>.Filter.And(
            Builders<CalendarSession>.Filter.Ne(s => s.Status, "CANCELLED"),
            Builders<CalendarSession>.Filter.Gte(s => s.EndTime, windowStart),
            Builders<CalendarSession>.Filter.Lt(s => s.EndTime, windowEnd));

        var sessions = await _sessions.Find(sessionFilter).ToListAsync(cancellationToken);
        if (sessions.Count == 0) return 0;

        var sessionsById = sessions.ToDictionary(s => s.Id);
        var sessionIds = sessionsById.Keys.ToList();

        // Attendances on those sessions that attended, have an email, and haven't
        // been processed for a review request yet.
        var attendanceFilter = Builders<Attendance>.Filter.And(
            Builders<Attendance>.Filter.In(a => a.CalendarSessionId, sessionIds),
            Builders<Attendance>.Filter.In(a => a.Status, AttendedStatuses),
            Builders<Attendance>.Filter.Ne(a => a.ClientEmail, null),
            Builders<Attendance>.Filter.Not(Builders<Attendance>.Filter.AnyEq(a => a.RemindersSent, ReviewTag)));

        var candidates = await _attendances.Find(attendanceFilter).ToListAsync(cancellationToken);
        if (candidates.Count == 0) return 0;

        var sentCount = 0;
        foreach (var attendance in candidates)
        {
            if (cancellationToken.IsCancellationRequested) break;
            if (string.IsNullOrWhiteSpace(attendance.ClientEmail)) continue;
            if (string.IsNullOrWhiteSpace(attendance.CalendarSessionId)) continue;
            if (!sessionsById.TryGetValue(attendance.CalendarSessionId, out var session)) continue;

            try
            {
                if (await IsFirstAttendedClassAsync(attendance.ClientId, session.StartTime, cancellationToken))
                {
                    await _emailService.SendReviewRequestAsync(
                        attendance.ClientEmail,
                        attendance.ClientName ?? "there");
                    sentCount++;
                }

                // Tag whether or not we emailed (a repeat client is suppressed but
                // must still be marked so we don't re-evaluate them every tick).
                await _attendances.UpdateOneAsync(
                    Builders<Attendance>.Filter.Eq(a => a.Id, attendance.Id),
                    Builders<Attendance>.Update.Push(a => a.RemindersSent, ReviewTag),
                    cancellationToken: cancellationToken);
            }
            catch (Exception ex)
            {
                // One bad recipient shouldn't poison the batch. The un-flipped tag
                // means the next tick retries this attendance.
                _logger.LogWarning(ex,
                    "ReviewRequestService failed for attendance {AttendanceId} ({Email})",
                    attendance.Id, attendance.ClientEmail);
            }
        }

        if (sentCount > 0)
            _logger.LogInformation("ReviewRequestService sent {Count} review requests at {Now:o}", sentCount, nowUtc);
        return sentCount;
    }

    /// <summary>
    /// True when no attended attendance of this client belongs to a session that
    /// started strictly before <paramref name="thisSessionStart"/> — i.e. this is
    /// their first class. The client's own candidate attendance shares the same
    /// start time, so it never disqualifies itself.
    /// </summary>
    private async Task<bool> IsFirstAttendedClassAsync(string clientId, DateTime thisSessionStart, CancellationToken ct)
    {
        var clientAttendances = await _attendances.Find(Builders<Attendance>.Filter.And(
            Builders<Attendance>.Filter.Eq(a => a.ClientId, clientId),
            Builders<Attendance>.Filter.In(a => a.Status, AttendedStatuses))).ToListAsync(ct);

        var otherSessionIds = clientAttendances
            .Where(a => !string.IsNullOrWhiteSpace(a.CalendarSessionId))
            .Select(a => a.CalendarSessionId!)
            .Distinct()
            .ToList();

        if (otherSessionIds.Count == 0) return true;

        var attendedSessions = await _sessions
            .Find(Builders<CalendarSession>.Filter.In(s => s.Id, otherSessionIds))
            .ToListAsync(ct);

        return !attendedSessions.Any(s => s.StartTime < thisSessionStart);
    }
}

