if (!string.IsNullOrWhiteSpace(query.Search))
{
    var s = query.Search.Trim();
    var regex = new MongoDB.Bson.BsonRegularExpression(s, "i");
    filter &= fb.Or(
        fb.Regex(a => a.ClientName, regex),
        fb.Regex(a => a.BookingReference, regex)
    );
}

// Date range filters on BookedAt as a proxy
if (query.DateFrom.HasValue && string.IsNullOrWhiteSpace(query.SessionId))
    filter &= fb.Gte(a => a.BookedAt, query.DateFrom.Value);
if (query.DateTo.HasValue && string.IsNullOrWhiteSpace(query.SessionId))
    filter &= fb.Lte(a => a.BookedAt, query.DateTo.Value.Date.AddDays(1));

// ── Push Format & Instructor filters upstream via session pre-query ──
if (!string.IsNullOrWhiteSpace(query.Format) || !string.IsNullOrWhiteSpace(query.InstructorId))
{
    var sf = Builders<CalendarSession>.Filter.Empty;
    if (!string.IsNullOrWhiteSpace(query.Format))
        sf &= Builders<CalendarSession>.Filter.Eq(s => s.Format, query.Format.ToUpperInvariant());

