if (!string.IsNullOrWhiteSpace(query.Search))
{
    var s = query.Search.Trim();
    var regex = new MongoDB.Bson.BsonRegularExpression(s, "i");
    var searchOr = new List<FilterDefinition<Attendance>>
    {
        fb.Regex(a => a.ClientName, regex),
        fb.Regex(a => a.BookingReference, regex),
    };
    // The invoices page deep-links here with the raw attendance id (a 24-char
    // ObjectId). Match it exactly when the search term parses as one, so those
    // "View booking" links resolve instead of showing "no bookings found".
    if (MongoDB.Bson.ObjectId.TryParse(s, out _))
        searchOr.Add(fb.Eq(a => a.Id, s));
    filter &= fb.Or(searchOr);
}

