    public List<string> tags { get; set; } = new();
    public string? partnerCode { get; set; }

    /// <summary>
    /// Optional date-of-birth. Used by birthday/age-segment analytics and
    /// surfaced on the admin client form. Storing it on the CRM Client is
    /// independent of <c>CustomerAccount.DateOfBirth</c> — admin entry
    /// captures DOB for walk-ins who never self-registered online.
    /// </summary>
    public DateTime? dateOfBirth { get; set; }

    public DateTime? createdAt { get; set; }

    // ── Read-only lifecycle metrics ──────────────────────────────────
