const gaEventToggle = document.getElementById('gaEventTrackingToggle');

// Populate from the settings that were already fetched during init
// (the main settings load fires on the financial tab — we piggyback)
async function loadIntegrationsSettings() {
  try {
    const res = await fetch(`${API}/api/settings`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!res.ok) return;
    const s = await res.json();
    if (gaIdInput) gaIdInput.value = s.googleAnalyticsMeasurementId || '';
    if (gaEventToggle) gaEventToggle.checked = s.enableGoogleAnalyticsEventTracking !== false;
  } catch { /* silent */ }
}
loadIntegrationsSettings();

