cd /opt/soulpilates && PW="$(grep '^MONGO_PASSWORD=' prod.env|cut -d= -f2)"; docker exec soulpilates-prod-mongo mongosh -u admin -p "$PW" --quiet --eval '
db=db.getSiblingDB("soulpilates");
// checked-in counts per client
const counts={};
db.Attendances.aggregate([{$match:{Status:"CHECKED_IN"}},{$group:{_id:"$ClientId",n:{$sum:1}}}]).forEach(r=>{counts[String(r._id)]=r.n;});
let vip=0, superVip=0;
db.Clients.find({LifetimeValue:{$gte:10000000}}).forEach(c=>{
  const cls=counts[String(c._id)]||0;
  if(c.LifetimeValue>=20000000 && cls>=20) superVip++; else vip++;
});
print("VIP (>=10M): "+vip);
print("SUPER VIP (>=20M spend AND >=20 classes): "+superVip);
' 2>&1 | tail -3

