private readonly IMongoCollection<Client> _clients;
private readonly IMongoCollection<Attendance> _attendances;
private readonly IMongoCollection<ClientPackage> _packages;
private readonly IAuditLogger _audit;
private readonly INotificationPublisher _notifications;

public ClientService(MongoDbContext dbContext, IAuditLogger audit, INotificationPublisher notifications)
{
    _clients = dbContext.GetCollection<Client>("Clients");
    _attendances = dbContext.GetCollection<Attendance>("Attendances");
    _packages = dbContext.GetCollection<ClientPackage>("ClientPackages");
    _audit = audit;
    _notifications = notifications;
}

/// <summary>
/// Active remaining credits per client, split into (group, mat, private).
/// MIXED packages count as group (they're usable for group/mat classes).
/// </summary>
public async Task<Dictionary<string, (int group, int mat, int priv)>> GetActiveCreditsByClientAsync()
{
    var packages = await _packages.Find(p => p.CreditsRemaining > 0).ToListAsync();
    var result = new Dictionary<string, (int group, int mat, int priv)>();
    foreach (var grp in packages.GroupBy(p => p.ClientId))
    {
        if (string.IsNullOrEmpty(grp.Key)) continue;
        int g = 0, m = 0, pr = 0;
        foreach (var p in grp)
        {
            switch ((p.Format ?? "").ToUpperInvariant())
            {
                case "MAT": m += p.CreditsRemaining; break;
                case "PRIVATE": pr += p.CreditsRemaining; break;
                default: g += p.CreditsRemaining; break; // GROUP, MIXED, other
            }
        }
        result[grp.Key] = (g, m, pr);
    }
    return result;
}

