.cal-nav-cluster { display: flex; align-items: center; gap: 4px; }
.cal-nav-btn {
  width: 32px; height: 32px; border: 1px solid var(--color-border);
  background: var(--color-surface); border-radius: var(--radius-sm);
  color: var(--color-text-muted); cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  transition: all 0.12s;
}
.cal-nav-btn:hover { background: var(--color-surface-raised); color: var(--color-text-primary); }
.cal-nav-btn svg { width: 14px; height: 14px; }

.cal-date-label {
  font-size: 14px; font-weight: 600;
  color: var(--color-text-primary);
  padding: 5px 12px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: var(--color-surface);
  cursor: default; white-space: nowrap;
}

/* Instructor filter dropdown */
.cal-filter-select {
  padding: 6px 10px; border: 1px solid var(--color-border);
  border-radius: var(--radius-sm); background: var(--color-surface);
  color: var(--color-text-primary); font-size: 12.5px;
  font-family: 'Inter', sans-serif; cursor: pointer;
}

/* ── Secondary Toolbar ── */
.cal-toolbar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 24px; border-bottom: 1px solid var(--color-border);
  flex-shrink: 0; gap: 12px; flex-wrap: wrap;
}
.cal-toolbar-left { display: flex; align-items: center; gap: 12px; }
.cal-toolbar-right { display: flex; align-items: center; gap: 12px; }

/* Segmented control */
.cal-seg {
  display: inline-flex; border: 1px solid var(--color-border);
  border-radius: var(--radius-sm); overflow: hidden;
}
.cal-seg-btn {
  padding: 6px 16px; border: none; background: none;
  font-size: 12px; font-weight: 600; cursor: pointer;
  color: var(--color-text-muted); font-family: 'Inter', sans-serif;
  transition: all 0.12s;
}
.cal-seg-btn:not(:last-child) { border-right: 1px solid var(--color-border); }
.cal-seg-btn.active {
  background: var(--color-brand-accent); color: white;
}
.cal-seg-btn:hover:not(.active) { background: var(--color-surface-raised); color: var(--color-text-primary); }

/* ═══ Main Body — Calendar Grid + Detail Panel ═══ */
.cal-body-wrap {
  display: flex; flex: 1; min-height: 0; overflow: hidden;
}
.cal-grid-area {
  flex: 1; min-width: 0; display: flex; flex-direction: column; overflow: hidden;
}

/* ── Day column headers ── */
.cal-col-headers {
  display: grid; flex-shrink: 0;
  border-bottom: 1px solid var(--color-border);
}
.cal-col-header {
  padding: 10px 4px; text-align: center;
}
.cal-col-header .ch-wday {
  font-size: 10px; font-weight: 600;
  text-transform: uppercase; letter-spacing: 0.5px;
  color: var(--color-text-muted);
}
.cal-col-header .ch-num {
  font-size: 20px; font-weight: 700;
  font-family: "Inter", sans-serif;
  letter-spacing: -0.4px; line-height: 1;
  color: var(--color-text-primary);
  margin-top: 2px;
}
.cal-col-header .ch-num.today {
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--color-brand-accent); color: white;
  width: 34px; height: 34px; border-radius: 50%;
  box-shadow: 0 2px 8px rgba(201,123,75,0.35);
}
.cal-col-gutter { /* time label column header — empty */ }

/* ── Time Grid ── */
.cal-scroll { flex: 1; overflow-y: auto; overflow-x: hidden; }
.cal-grid {
  display: grid; position: relative;
}

/* ── Month view ── */
.cal-col-head {
  font-size: 11px; font-weight: 600; text-transform: uppercase;
  letter-spacing: .4px; color: var(--color-text-muted);
  text-align: center; padding: 8px 0;
  border-bottom: 1px solid var(--color-border-subtle);
}
.cal-month-cell {
  min-height: 116px; padding: 4px;
  border-right: 1px solid var(--color-border-subtle);
  border-bottom: 1px solid var(--color-border-subtle);
  display: flex; flex-direction: column; gap: 2px; overflow: hidden;
}
.cal-month-cell-muted { background: var(--color-surface-raised, rgba(0,0,0,0.02)); opacity: .55; }
.cal-month-cell-today { box-shadow: inset 0 0 0 2px var(--color-brand-accent); }
.cal-month-datenum { font-size: 12px; font-weight: 600; color: var(--color-text); padding: 1px 3px; }
