}

/* Origin indicators (border LINE STYLE = where the session came from) */
.ev.origin-override { border-left-style: dashed; }
.ev.origin-freelance { border-left-style: dotted; border-left-width: 5px; }

/* Status indicators (COLOR = session lifecycle outcome; border stays SOLID) */
.ev.status-completed {
  --ev-accent: #34A853;
  background: rgba(52,168,83,0.16);
  border-left-color: #34A853;
}
.ev.status-noshow {
  --ev-accent: #C0392B;
  background: rgba(192,57,43,0.16);
  border-left-color: #C0392B;
}

/* Light mode readability — the per-format --ev-text values are pale pastels
   tuned for a dark canvas, so on the light theme they wash out against the
   tinted card. Force dark, high-contrast text (format is still conveyed by
   the coloured left border and background tint) and firm up the tint a touch
   so cards separate cleanly from the white grid. */
:root:not([data-theme="dark"]) .ev {
  color: var(--color-text-primary);
}
/* Only firm up the tint for plain scheduled cards — leave status colours
   (completed / no-show) and blocked slots to own their own background. */
:root:not([data-theme="dark"]) .ev:not(.status-completed):not(.status-noshow):not(.blocked) {
  background: var(--ev-bg-strong, var(--ev-bg, rgba(200,164,93,0.22)));
}
:root:not([data-theme="dark"]) .ev .ev-time,
:root:not([data-theme="dark"]) .ev .ev-name,
:root:not([data-theme="dark"]) .ev .ev-inst-name,
:root:not([data-theme="dark"]) .ev .ev-capacity,
:root:not([data-theme="dark"]) .ev .ev-clients,
:root:not([data-theme="dark"]) .ev .ev-more {
  color: var(--color-text-primary);
}
/* Keep the muted sub-lines legible but still secondary. */

