(function() {
  var token = localStorage.getItem('token');
  if (!token) { window.location.href = '/admin/login'; return; }
  try {
    var payload = JSON.parse(atob(token.split('.')[1]));
    var role = (payload['http://schemas.microsoft.com/ws/2008/06/identity/claims/role'] || payload.role || '').toLowerCase();
    if (role === 'customer') { window.location.href = '/'; return; }
    // Instructors are only allowed into /admin if they hold explicit per-user
    // page grants. We can't know that synchronously (grants live server-side),
    // so flag them and let the management-access fetch below decide: with no
    // granted modules they're bounced to /instructor; otherwise the nav is
    // filtered down to just their granted pages.
    window.__isInstructor = (role === 'instructor');
    // Store role for sidebar filtering
    window.__userRole = role;
    // Give instructors a way back to their own portal (Schedule/Earnings) from
    // any granted admin page.
    if (window.__isInstructor) {
      document.querySelectorAll('.instructor-portal-link').forEach(function (el) { el.style.display = ''; });
    }
  } catch (e) {
    // Malformed token — stay and let API 401 handle it
    window.__userRole = 'admin';
  }
})();

// ─── Role-based sidebar filtering ─────────────────────────────
// Each nav-item has a data-roles attribute listing which roles can see it.
// Items without data-roles are visible to all authenticated management users.
function applySidebarSectionVisibility() {
  document.querySelectorAll('.sidebar-nav .nav-section-label').forEach(function(label) {
    var next = label.nextElementSibling;
    var anyVisible = false;
    while (next && !next.classList.contains('nav-section-label')) {
      if (next.style.display !== 'none' && next.classList.contains('nav-item')) anyVisible = true;
      next = next.nextElementSibling;
    }
    label.style.display = anyVisible ? '' : 'none';
  });
}

function applyFallbackRoleAccess(role) {
  document.querySelectorAll('.sidebar-nav [data-roles], .mobile-bottom-nav [data-roles], .mobile-more-content [data-roles]').forEach(function(el) {
    var allowed = (el.getAttribute('data-roles') || '').toLowerCase().split(',');
    el.style.display = allowed.indexOf(role) === -1 ? 'none' : '';
  });
  applySidebarSectionVisibility();
}

function showManagementAccessDenied() {
  var content = document.querySelector('.content-area');
  if (!content) return;
  content.innerHTML = '<div class="card"><div class="card-body"><div style="font-size:22px;font-weight:700;margin-bottom:8px;">Access limited</div><div class="text-muted">This page is turned off for your role.</div></div></div>';
}

function findFirstVisibleManagementLink() {
  var links = document.querySelectorAll('.sidebar-nav a[data-module], .mobile-bottom-nav a[data-module], .mobile-more-content a[data-module]');
  for (var i = 0; i < links.length; i++) {
    if (links[i].style.display === 'none') continue;
    var href = links[i].getAttribute('href');
