public async Task SendBirthdayEmailAsync(string toEmail, string clientName)
{
    if (!_enabled || string.IsNullOrWhiteSpace(toEmail)) return;
    if (!await IsTemplateEnabledAsync(EmailTemplateIds.Birthday)) return;

    var safeName = EmailTemplateHelper.EncodeText(string.IsNullOrWhiteSpace(clientName) ? "there" : clientName);

    var bodyValues = new Dictionary<string, string>
    {
        ["ClientName"] = safeName,
        ["BookingUrl"] = $"{_publicBaseUrl}/booking",
    };

    var (subject, inner) = await ResolveTemplateAsync(
        EmailTemplateIds.Birthday,
        defaultSubject: "Happy Birthday from Soul Pilates! 🎉 | Chúc mừng sinh nhật",
        defaultBody: EmailTemplateDefaults.BirthdayBody,
        subjectValues: new Dictionary<string, string>(),
        bodyValues: bodyValues);

    var body = EmailTemplateHelper.Layout(
        heading: "Happy Birthday! 🎉",
        subtitleVi: "Chúc mừng sinh nhật",
        innerHtml: inner);

    await SendEmailAsync(toEmail, subject, body);
}

