using Microsoft.Extensions.Logging;
using MongoDB.Driver;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.Services;

/// <summary>
/// Birthday-greeting sender. Once per day: find clients whose date-of-birth
/// month+day matches today (studio-local, ICT) and who haven't been emailed yet
/// this calendar year, send the greeting, and stamp the year so it never repeats.
/// </summary>
public class BirthdayEmailService : IBirthdayEmailService
{
    // Studio is in Da Nang (UTC+7); birthdays fire on the correct local calendar day.
    private const int StudioUtcOffsetHours = 7;

    private readonly IMongoCollection<Client> _clients;
    private readonly IEmailService _emailService;
    private readonly ILogger<BirthdayEmailService> _logger;

    public BirthdayEmailService(MongoDbContext dbContext, IEmailService emailService, ILogger<BirthdayEmailService> logger)
    {
        _clients = dbContext.GetCollection<Client>("Clients");
        _emailService = emailService;
        _logger = logger;
    }

    public async Task<int> SendDueBirthdayEmailsAsync(DateTime nowUtc, CancellationToken cancellationToken)
    {
        var localNow = nowUtc.AddHours(StudioUtcOffsetHours);
        int month = localNow.Month, day = localNow.Day, year = localNow.Year;

        // Candidates: has a birthday + an email, and not already greeted this year.
        // Month/day is filtered in memory (small set) to avoid $expr date extraction.
        var candidates = await _clients.Find(Builders<Client>.Filter.And(
            Builders<Client>.Filter.Ne(c => c.DateOfBirth, null),
            Builders<Client>.Filter.Ne(c => c.Email, null),
            Builders<Client>.Filter.Or(
                Builders<Client>.Filter.Eq(c => c.LastBirthdayEmailSentYear, null),
                Builders<Client>.Filter.Ne(c => c.LastBirthdayEmailSentYear, year)),
            Builders<Client>.Filter.Eq(c => c.IsStudioRentalProfile, false)
        )).ToListAsync(cancellationToken);

        var sent = 0;
        foreach (var c in candidates)
        {
            if (cancellationToken.IsCancellationRequested) break;
            if (c.DateOfBirth is not { } dob) continue;
            if (dob.Month != month || dob.Day != day) continue;
            if (string.IsNullOrWhiteSpace(c.Email)) continue;

            try
            {
                await _emailService.SendBirthdayEmailAsync(c.Email, c.FullName);
                // Stamp the year AFTER a successful send so a failure retries next tick.
                await _clients.UpdateOneAsync(
                    Builders<Client>.Filter.Eq(x => x.Id, c.Id),
                    Builders<Client>.Update.Set(x => x.LastBirthdayEmailSentYear, year),
                    cancellationToken: cancellationToken);
                sent++;
            }
            catch (Exception ex)
            {
                _logger.LogWarning(ex, "BirthdayEmailService failed for client {ClientId} ({Email})", c.Id, c.Email);
            }
        }

        if (sent > 0)
            _logger.LogInformation("BirthdayEmailService sent {Count} birthday emails for {Date}", sent, localNow.ToString("MMM d"));
        return sent;
    }
}

