using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.Services;

/// <summary>
/// Hosted job that drives <see cref="IBirthdayEmailService.SendDueBirthdayEmailsAsync"/>.
/// Ticks a few times a day so the greeting goes out on the birthday regardless of
/// deploy time; the per-year dedup in the service keeps it to one email per client.
/// </summary>
public class BirthdayEmailBackgroundService : BackgroundService
{
    private readonly IServiceProvider _services;
    private readonly ILogger<BirthdayEmailBackgroundService> _logger;

    public BirthdayEmailBackgroundService(IServiceProvider services, ILogger<BirthdayEmailBackgroundService> logger)
    {
        _services = services;
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                using var scope = _services.CreateScope();
                var birthday = scope.ServiceProvider.GetRequiredService<IBirthdayEmailService>();
                await birthday.SendDueBirthdayEmailsAsync(DateTime.UtcNow, stoppingToken);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "BirthdayEmailBackgroundService tick threw");
            }

            // Every 6 hours — dedup makes extra ticks harmless.
            await Task.Delay(TimeSpan.FromHours(6), stoppingToken);
        }
    }
}

