using SoulPilates.Core.DTOs;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.Tests.TestHelpers;

/// <summary>
/// No-op <see cref="IEmailService"/> for unit/integration tests that don't
/// need to verify email delivery. All methods return completed tasks.
/// </summary>
public sealed class NoOpEmailService : IEmailService
