# Apex + www for Soul Pilates CRM. Mirrors the new.soulpilates.com.vn origin.
# Enable (symlink into sites-enabled) only AFTER the apex cert exists.

# HTTP: ACME + redirect to canonical https apex
server {
    listen 80;
    listen [::]:80;
    server_name soulpilates.com.vn www.soulpilates.com.vn;

    location /.well-known/acme-challenge/ {
        root /var/www/html;
        allow all;
    }

    location / {
        return 301 https://soulpilates.com.vn$request_uri;
    }
}

# HTTPS: www -> apex canonical redirect
server {
    listen 443 ssl;
    listen [::]:443 ssl;
    server_name www.soulpilates.com.vn;

    ssl_certificate     /etc/letsencrypt/live/soulpilates.com.vn/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/soulpilates.com.vn/privkey.pem;
    ssl_protocols       TLSv1.2 TLSv1.3;
    ssl_ciphers         HIGH:!aNULL:!MD5;

    return 301 https://soulpilates.com.vn$request_uri;
}

# HTTPS: apex — serves the CRM (identical routing to the new. origin)
server {
    listen 443 ssl;
    listen [::]:443 ssl;
    server_name soulpilates.com.vn;

    ssl_certificate     /etc/letsencrypt/live/soulpilates.com.vn/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/soulpilates.com.vn/privkey.pem;
    ssl_protocols       TLSv1.2 TLSv1.3;
    ssl_ciphers         HIGH:!aNULL:!MD5;

    client_max_body_size 15M;

    location /api/ {
        proxy_pass http://127.0.0.1:8391;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 120s;
        proxy_send_timeout 120s;
    }

    location /hubs/ {
        proxy_pass http://127.0.0.1:8391;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 3600s;
        proxy_send_timeout 3600s;
    }

    location /soulpilates-public/ {
        proxy_pass http://127.0.0.1:6324;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        expires 7d;
        add_header Cache-Control "public, immutable";
    }

    location / {
        proxy_pass http://127.0.0.1:3719;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_redirect http://soulpilates.com.vn https://soulpilates.com.vn;
        proxy_redirect http://72.62.240.50 https://soulpilates.com.vn;
    }

    add_header X-Content-Type-Options nosniff always;
    add_header X-Frame-Options SAMEORIGIN always;
    add_header Referrer-Policy strict-origin-when-cross-origin always;
}

