// One-time: rewrite persisted absolute media URLs new. -> apex.
// Run AFTER the apex serves the CRM (otherwise images 404 during transition).
db = db.getSiblingDB("soulpilates");
const from = "https://new.soulpilates.com.vn/soulpilates-public";
const to = "https://soulpilates.com.vn/soulpilates-public";
const targets = ["CalendarSessions", "ClassBlueprints", "Equipment"];
let total = 0;
targets.forEach(function (cn) {
  const c = db.getCollection(cn);
  const docs = c.find({ ImageUrl: /^https:\/\/new\.soulpilates\.com\.vn\/soulpilates-public/ },
                      { ImageUrl: 1 }).toArray();
  let n = 0;
  docs.forEach(function (d) {
    const nu = d.ImageUrl.replace(from, to);
    c.updateOne({ _id: d._id }, { $set: { ImageUrl: nu } });
    n++;
  });
  print(cn + ": rewrote " + n);
  total += n;
});
print("TOTAL rewritten: " + total);

