    // ── Create invoice for PACKAGE_CREDIT bookings ──────────────────
    // PAY_AT_STUDIO does NOT get an invoice yet — only when marked CHECKED_IN.
    if (paymentMethod == "PACKAGE_CREDIT")
    {
        await CreateBookingInvoiceAsync(
            attendance, session, quote.SessionFee, quote.SessionFee, "CREDIT");
    }

    // P5-PWA — ping admins/managers (zero-amount payments are still a meaningful event
    // because they represent a credit redemption or studio-balance booking finalisation).
    FireAndForgetPaymentPush(record, attendance, paymentMethod);

    // P5-PWA — the attendance just transitioned RESERVED → BOOKED, so this
    // is the correct moment for the "New booking" push to the instructor +
    // admins. (Previously this fired from BookingController.ReserveSpot,
    // which produced false positives for customers who abandoned checkout.)
    FireAndForgetBookingPush(attendance, session);

    // P5-S01 — Booking confirmation email. Only fire now that the
    // status is definitively BOOKED (not RESERVED).
    FireAndForgetBookingEmail(attendance, session);

    return new PaymentIntentResult
    {
        PaymentIntentId = $"local_{record.Id}",
        ClientSecret = "",
        Amount = 0,
        Currency = Currency,
        PublishableKey = "", // No publishable key needed for zero-amount local payments
        SessionFee = quote.SessionFee,
        FeeAmount = quote.FeeAmount,
        FeePercentage = quote.FeePercentage,
        AmountDueAtStudio = quote.AmountDueAtStudio,
    };
}

