/// <summary>
/// Stripe keys are managed via a dedicated endpoint (<c>POST /api/settings/stripe-keys</c>).
/// The main settings save (both Financial and Payments tabs) does not include them,
/// so we always carry forward the existing encrypted values to prevent accidental wipe.
/// </summary>
private static void PreserveStripeKeysIfAbsent(GlobalSettings update, GlobalSettings current)
{
    // The main save endpoint never sends Stripe key data — the incoming
    // update will always have empty strings for these encrypted fields.
    // Always copy them from the current DB state.
    if (string.IsNullOrEmpty(update.StripePublishableKeyEncrypted))
        update.StripePublishableKeyEncrypted = current.StripePublishableKeyEncrypted;
    if (string.IsNullOrEmpty(update.StripeSecretKeyEncrypted))
        update.StripeSecretKeyEncrypted = current.StripeSecretKeyEncrypted;
    if (string.IsNullOrEmpty(update.StripeWebhookSecretEncrypted))
        update.StripeWebhookSecretEncrypted = current.StripeWebhookSecretEncrypted;

    // Always preserve StripeEnabled from the DB state — this field is only
    // modified via the dedicated stripe-keys endpoint. The main settings
    // save always sends the C# default (false) which would silently
    // disable payments on every General-tab save without this guard.
    update.StripeEnabled = current.StripeEnabled;
}

