public async Task<PaymentIntentResult> CreatePackagePurchaseIntentAsync(string invoiceId)
{
    var invoice = await _invoices.Find(i => i.Id == invoiceId).FirstOrDefaultAsync()
        ?? throw new InvalidOperationException("Invoice not found.");

    if (invoice.Status == "PAID")
        throw new InvalidOperationException("Invoice is already paid.");

    // For package purchases we deliberately bill the **full net** every time
    // — partial deposit isn't supported on the customer-facing buy flow
    // (per product spec: it's a digital item, full pay only).
    var amountDueNow = invoice.TotalNet;
    if (amountDueNow <= 0)
        throw new InvalidOperationException("Invoice has no outstanding amount.");

    var clientSecret = "";
    string paymentIntentId;
    var useEmbedded = false;
    var checkoutSessionId = "";

    var stripe = await GetStripeAsync();

    if (!stripe.Enabled || string.IsNullOrWhiteSpace(stripe.SecretKey))
    {
        // Dev / preview mode — mock secret so the front-end Stripe Elements
        // bootstrap completes and we can drive the confirm() callback for
        // local testing without a real Stripe account.
        paymentIntentId = $"pi_pkg_mock_{Guid.NewGuid():N}";
        clientSecret = $"{paymentIntentId}_secret_mock";

        _logger.LogInformation(
            "Stripe is disabled. Returning mock package-purchase intent {PaymentIntentId} for invoice {InvoiceNumber}.",
            paymentIntentId, invoice.InvoiceNumber);
    }
    else
    {
        EnsureStripeApiKey(stripe);
        var amountForStripe = IsZeroDecimalCurrency(Currency)
            ? (long)amountDueNow
            : (long)(amountDueNow * 100);

        var itemName = invoice.Notes?.Replace("Online package purchase — ", "").Trim();
        if (string.IsNullOrWhiteSpace(itemName)) itemName = "Soul Pilates package";

        var metadata = new System.Collections.Generic.Dictionary<string, string>
        {
            // `kind` is the discriminator the webhook switch reads.
            { "kind", "package_purchase" },
            { "invoiceId", invoice.Id! },
            { "invoiceNumber", invoice.InvoiceNumber },
            { "clientId", invoice.ClientId },
        };

        // Embedded Stripe Checkout — cleaner form; metadata rides the PaymentIntent
        // so the existing package_purchase webhook path finalises unchanged.
        var sessionService = new Stripe.Checkout.SessionService();
        var checkoutSession = await sessionService.CreateAsync(new Stripe.Checkout.SessionCreateOptions
        {
            UiMode = "embedded",
            Mode = "payment",
            RedirectOnCompletion = "never",
            LineItems = new System.Collections.Generic.List<Stripe.Checkout.SessionLineItemOptions>
            {
                new()
                {
                    Quantity = 1,
                    PriceData = new Stripe.Checkout.SessionLineItemPriceDataOptions
                    {
                        Currency = Currency.ToLowerInvariant(),
                        UnitAmount = amountForStripe,
                        ProductData = new Stripe.Checkout.SessionLineItemPriceDataProductDataOptions { Name = itemName },
                    },
                },
            },
            PaymentIntentData = new Stripe.Checkout.SessionPaymentIntentDataOptions { Metadata = metadata },
            Metadata = metadata,
        });

        paymentIntentId = checkoutSession.PaymentIntentId;
        clientSecret = checkoutSession.ClientSecret;
        checkoutSessionId = checkoutSession.Id;
        useEmbedded = true;
    }

    // Audit trail — keeps PaymentService as the single source of truth.
    await _audit.LogAsync(
        action: "PACKAGE_PURCHASE_INTENT_CREATED",
        entityType: "Invoice",
        entityId: invoice.Id!,
        entityLabel: invoice.InvoiceNumber,
        metadata: new { paymentIntentId, amountDueNow, invoice.ClientId });

    return new PaymentIntentResult
    {
        PaymentIntentId = paymentIntentId,
        ClientSecret = clientSecret,
        UseEmbeddedCheckout = useEmbedded,
        CheckoutSessionId = checkoutSessionId,
        Amount = amountDueNow,
        Currency = Currency,
        PublishableKey = stripe.PublishableKey,
        SessionFee = amountDueNow, // not a session, but the UI reads SessionFee for the headline price
        FeeAmount = 0,
        FeePercentage = 0,
        AmountDueAtStudio = 0,
    };
}

