/// <summary>
/// Groups payment amounts by method for the period. Uses the <c>Payments</c>
/// collection (the source of truth for "how money came in") rather than
/// re-deriving from <c>Invoice.Status</c>, since one invoice can be paid via
/// multiple methods (deposit on Stripe, balance in cash).
/// </summary>
private async Task<Dictionary<string, decimal>> ComputeRevenueByMethodAsync(
    IEnumerable<Invoice> invoices,
    DateTime start,
    DateTime end)
{
    var invoiceIds = invoices.Select(i => i.Id!).ToList();
    if (invoiceIds.Count == 0) return new();

    // Match by both invoice scope AND payment date — protects against late
    // payments on an invoice issued in a previous month leaking into this one.
    var monthPayments = await _payments
        .Find(p => invoiceIds.Contains(p.InvoiceId) && p.PaymentDate >= start && p.PaymentDate <= end)
        .ToListAsync();

    return monthPayments
        .GroupBy(p => string.IsNullOrEmpty(p.PaymentMethod) ? "UNKNOWN" : p.PaymentMethod)
        .ToDictionary(g => g.Key, g => g.Sum(p => p.AmountPaid));
}

