684	    {
685	        var allLines = invoices.SelectMany(i => i.Lines).ToList();
686	        if (allLines.Count == 0) return new();
687	
688	        // Lines created after the P5 snapshot rollout carry their own
689	        // ProductTypeSnapshot. We only need to round-trip to Products for
690	        // the legacy tail — pre-snapshot lines whose ProductTypeSnapshot is
691	        // still null. This keeps historical washouts stable even after a
692	        // product is reclassified (the whole point of the snapshot), while
693	        // still attributing legacy lines to *something* sensible.
694	        var legacyProductIds = allLines
695	            .Where(l => string.IsNullOrWhiteSpace(l.ProductTypeSnapshot)
696	                     && !string.IsNullOrWhiteSpace(l.ProductId))
697	            .Select(l => l.ProductId)
