/// orphan payments (an invoice was deleted/voided but its payment record was
/// left behind) inflating revenue — real money kept, not money invoiced.
/// </summary>
private async Task<decimal> SumCollectedRevenueAsync(DateTime start, DateTime end)
{
    var payments = await _payments
        .Find(Builders<Payment>.Filter.And(
            Builders<Payment>.Filter.Gte(p => p.PaymentDate, start),
            Builders<Payment>.Filter.Lt(p => p.PaymentDate, end)))
        .Project(p => new PaymentRevenueRow { InvoiceId = p.InvoiceId, AmountPaid = p.AmountPaid })
        .ToListAsync();
    if (payments.Count == 0) return 0m;

    var invoiceIds = payments
        .Where(p => !string.IsNullOrEmpty(p.InvoiceId))
        .Select(p => p.InvoiceId!)
        .Distinct()
        .ToList();

    var validInvoiceIds = (await _invoices
            .Find(Builders<Invoice>.Filter.And(
                Builders<Invoice>.Filter.In(i => i.Id, invoiceIds),
                Builders<Invoice>.Filter.Ne(i => i.Status, "VOIDED")))
            .Project(i => i.Id)
            .ToListAsync())
        .ToHashSet();

    return payments
        .Where(p => !string.IsNullOrEmpty(p.InvoiceId) && validInvoiceIds.Contains(p.InvoiceId))
        .Sum(p => p.AmountPaid);
}

