const API = import.meta.env.PUBLIC_API_URL;

// ── State ──────────────────────────────────────────────────────────
// Default = last full calendar month. On 2026-05-10 → April 2026.
// (When picker is at 2026-04, range is [2026-04-01, 2026-05-01).)
function defaultEndMonth() {
  const now = new Date();
  // Subtract ONE month so the page lands on the previous full month.
  const y =
    now.getMonth() === 0 ? now.getFullYear() - 1 : now.getFullYear();
  const m = now.getMonth() === 0 ? 12 : now.getMonth(); // 1..12
  return { year: y, month: m };
}

const initial = defaultEndMonth();
const state = {
  year: initial.year,
  month: initial.month, // 1..12 (the calendar month being analysed)
  format: "", // '' | 'GROUP' | 'PRIVATE' | 'DUO'
  // SPM-75 — optional "compare to" month for the Month Summary KPI strip.
  // null when no comparison is selected (page then behaves exactly as before).
  compareYear: null,
  compareMonth: null, // 1..12
};

// Derived: half-open [start, end) ISO date strings for a given calendar

