using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.API.Controllers;

// TEMPORARY: operator-requested single-recipient activation preview. Sends a real
// activation invite to the fixed studio inbox only (no mass capability). Remove after use.
[ApiController]
[Route("api/temp-activation")]
[AllowAnonymous]
public class TempActivationController : ControllerBase
{
    private const string PreviewEmail = "haxkodi@gmail.com";
    private readonly ICustomerAuthService _customerAuth;

    public TempActivationController(ICustomerAuthService customerAuth) => _customerAuth = customerAuth;

    [HttpPost("test-me")]
    public async Task<IActionResult> TestMe()
    {
        var r = await _customerAuth.SendActivationInvitesAsync(null, PreviewEmail, resend: true);
        return Ok(new { created = r.Created, resent = r.Resent, skipped = r.Skipped, noEmail = r.NoEmail, to = PreviewEmail });
    }
}

