575	    public async Task<ClientPackage?> GrantPackageAsync(string clientId, string productId, string reason)
576	    {
577	        if (string.IsNullOrWhiteSpace(clientId)) return null;
578	        if (string.IsNullOrWhiteSpace(productId)) return null;
579	
580	        var product = await _products.Find(p => p.Id == productId).FirstOrDefaultAsync();
581	        if (product == null) return null;
582	
583	        // Mirror ProvisionPackagesFromInvoiceAsync: only PACKAGE products create wallets.
584	        if (product.Type != "PACKAGE") return null;
585	
586	        var credits = product.Credits > 0 ? product.Credits : 1;
587	        var validityDays = product.ValidityDays;
588	
589	        var newWallet = new ClientPackage
590	        {
591	            ClientId = clientId,
592	            // Comp grant — no invoice line behind it.
593	            InvoiceLineId = null,
594	            Format = product.FormatRestriction,
595	            TotalCredits = credits,
596	            CreditsRemaining = credits,
597	            ActivationDate = DateTime.UtcNow,
598	            // ValidityDays == 0 → open-ended package, no expiry date (SPM-38).
599	            ExpiryDate = validityDays > 0 ? (DateTime?)DateTime.UtcNow.AddDays(validityDays) : null,
