        lineId: (l.Id || l._id) ? (l.Id || l._id).toString() : null,
        issue: inv.IssueDate ? inv.IssueDate.getTime() : 0,
        clientId: inv.ClientId,
        claimed: false,
      });
    }
  });
});

// 3. Match each package (oldest first) to an unclaimed unit: same client + key,
//    nearest issue date to activation. Fall back to any same-key unit if the
//    client id doesn't line up (seed data can mismatch client refs).
var matched = 0, unmatched = 0, unmatchedList = [];
db.ClientPackages.find({}).sort({ ActivationDate: 1 }).forEach(function (pk) {
  if ((pk.Format || "").toUpperCase() === "FREELANCE") return; // rentals handled separately
  var key = (pk.Format || "").toUpperCase() + "|" + pk.TotalCredits;
  var units = pool[key] || [];
  var act = pk.ActivationDate ? pk.ActivationDate.getTime() : 0;
  var best = null, bestScore = Infinity;
  units.forEach(function (u) {
    if (u.claimed) return;
    // SAME CLIENT ONLY — never borrow another client's price.
    if (!(u.clientId && pk.ClientId && u.clientId.toString() === pk.ClientId.toString())) return;
    var score = Math.abs(u.issue - act); // nearest purchase date
    if (score < bestScore) { bestScore = score; best = u; }
  });
  if (best) {
    best.claimed = true;
    db.ClientPackages.updateOne({ _id: pk._id },
      { $set: { FractionalValuePerClass: best.perClass, InvoiceLineId: best.lineId } });
    matched++;
  } else {
    // No purchase line for this client/product — undo any list-price guess so it
    // falls back to drop-in (honest "unknown") rather than an assumed rate.
    db.ClientPackages.updateOne({ _id: pk._id }, { $set: { FractionalValuePerClass: 0 } });
    unmatched++;
    if (unmatchedList.length < 15) unmatchedList.push((pk.Format || "?") + "/" + pk.TotalCredits + "cr");
  }
});

print("matched to actual invoice line = " + matched);
print("unmatched (no purchase line found) = " + unmatched);
print("unmatched combos: " + unmatchedList.join(", "));

