public async Task<InstructorEarningsDto?> GetCurrentMonthEarningsAsync(
    string? staffId, int? year = null, int? month = null)
{
    if (string.IsNullOrWhiteSpace(staffId)) return null;

    // Confirm the staff row still exists before delegating — keeps
    // the not-found mapping uniform across all three /api/instructor
    // endpoints (profile, schedule's empty-list, earnings's null).
    var staff = await _staff.Find(s => s.Id == staffId).FirstOrDefaultAsync();
    if (staff is null) return null;

    // First-of-month → last-millisecond-of-month. Using UTC to
    // match how CalendarSession.StartTime is stored. Defaults to the
    // current month; an explicit year+month lets instructors review any
    // prior month's earnings.
    var now = DateTime.UtcNow;
    var y = (year is >= 2000 and <= 3000) ? year.Value : now.Year;
    var m = (month is >= 1 and <= 12) ? month.Value : now.Month;
    var periodStart = new DateTime(y, m, 1, 0, 0, 0, DateTimeKind.Utc);
    var periodEnd = periodStart.AddMonths(1).AddTicks(-1);

    var result = await _payroll.CalculateForInstructorAsync(staffId, periodStart, periodEnd);
    if (result is null) return null; // Defensive — service already validated staff.

    // For PERCENTAGE_TIERED the tier is resolved using the TOTAL
    // class count (group + private), matching AggregateInstructorAsync.
    // For other models, only private classes drive the tier ladder.
    var classesForTier = (result.CommissionModelSnapshot == "PERCENTAGE_TIERED")
        ? result.TotalGroupClasses + result.TotalPrivateClasses
        : result.TotalPrivateClasses;

    // Base salary now lives on the Expenses "Salaries" tab (salary-tagged
    // expense per staff+month), not on Staff.BaseSalary. Pull this month's
    // salary so it surfaces on the instructor's earnings page and total.
    var monthlySalary = (await _expenses
            .Find(e => e.SalaryForStaffId == staffId
                    && e.DateIncurred >= periodStart && e.DateIncurred <= periodEnd)
            .ToListAsync())
        .Sum(e => e.Amount);

    return new InstructorEarningsDto
    {
        PeriodStart = periodStart,
        PeriodEnd = periodEnd,
        BaseSalaryAmount = monthlySalary,
        GroupClassEarnings = result.GroupClassEarnings,
        PrivateClassEarnings = result.PrivateClassEarnings,
        TotalPay = result.TotalPay - result.BaseSalaryAmount + monthlySalary,
        TotalGroupClasses = result.TotalGroupClasses,
        TotalPrivateClasses = result.TotalPrivateClasses,

