function populate(c) {
  if (!c) return;
  const set = (id, v) => {
    const el = document.getElementById(id);
    if (el) el.value = v ?? "";
  };
  set("cName", c.name);
  set("cPhoneCC", c.phoneCountryCode || "+84");
  set("cPhone", c.phone);
  set("cEmail", c.email);
  set("cNotes", c.notes);
  set("cCountry", c.country);
  set("cContactPlatform", c.preferredContactPlatform || "ZALO");
  set("cMedical", c.medicalHistory);
  set("cPartner", c.partnerCode);
  // DOB hydration — trim ISO timestamp to yyyy-MM-dd for <input type="date">.
  if (c.dateOfBirth) {
    set("cDob", String(c.dateOfBirth).slice(0, 10));
  } else {
    set("cDob", "");
  }
  tags = Array.isArray(c.tags) ? [...c.tags] : [];
  renderTags();
  renderPartnerSelectedChip();
}

