function populateCountrySelects() {
  const countrySel = document.getElementById("cCountry");

  // Sort alphabetically by name, excluding Vietnam (pinned at top).
  const sorted = COUNTRIES.filter((c) => c.code !== "VN").sort((a, b) =>
    a.name.localeCompare(b.name),
  );

  if (countrySel) {
    countrySel.innerHTML = [
      `<option value="">— Select country —</option>`,
      `<option value="VN">Vietnam (Local) 🇻🇳</option>`,
      ...sorted.map(
        (c) => `<option value="${c.code}">${c.name} ${flagEmoji(c.code)}</option>`,
      ),
      `<option value="OTHER">Other 🌍</option>`,
    ].join("");
  }

  // Country-code phone field is a searchable combobox (see initCountryCodeCombo).
  ccOrdered = [
    COUNTRIES.find((c) => c.code === "VN") || { code: "VN", name: "Vietnam", dial: "+84" },
    ...sorted,
  ];
  initCountryCodeCombo();
  // Default display if nothing set yet.
  const hidden = document.getElementById("cPhoneCC");
  setPhoneCC(hidden && hidden.value ? hidden.value : "+84");
}

// ─── Country-code searchable combobox ──────────────────────────────
let ccOrdered = [];
let ccActiveIdx = -1;

function ccLabel(c) {
  return `${flagEmoji(c.code)} ${c.name} (${c.dial})`;
}

/** Set the hidden dial-code value and sync the visible input display. */
function setPhoneCC(dial) {
  const hidden = document.getElementById("cPhoneCC");
  const input = document.getElementById("cPhoneCCInput");
  if (hidden) hidden.value = dial || "+84";
  if (input) {
    const match = ccOrdered.find((c) => c.dial === (dial || "+84"));
    input.value = match ? ccLabel(match) : (dial || "+84");
    input.dataset.committed = input.value;
  }
}

function ccCloseMenu() {
  const menu = document.getElementById("cPhoneCCMenu");
  if (menu) menu.hidden = true;
  ccActiveIdx = -1;
}

function ccRenderMenu(query) {
  const menu = document.getElementById("cPhoneCCMenu");
  if (!menu) return;
  const q = (query || "").trim().toLowerCase();
  const matches = ccOrdered.filter((c) => {
    if (!q) return true;
    return (
      c.name.toLowerCase().includes(q) ||
      c.dial.toLowerCase().includes(q) ||
      c.dial.replace("+", "").includes(q.replace("+", "")) ||
      c.code.toLowerCase() === q
    );
  });
  if (matches.length === 0) {
    menu.innerHTML = `<div class="cc-combo-empty">No match</div>`;
  } else {
    menu.innerHTML = matches
      .map(
        (c, i) =>
          `<div class="cc-combo-option${i === ccActiveIdx ? " is-active" : ""}" role="option" data-dial="${c.dial}">` +
          `<span>${flagEmoji(c.code)} ${escapeHtml(c.name)}</span><span class="cc-dial">${c.dial}</span></div>`,
      )
      .join("");
  }
  menu.hidden = false;
}

function initCountryCodeCombo() {
  const input = document.getElementById("cPhoneCCInput");
  const menu = document.getElementById("cPhoneCCMenu");
  if (!input || !menu || input.dataset.ccInit === "1") return;
  input.dataset.ccInit = "1";

  input.addEventListener("focus", () => {
    input.value = ""; // let them type to search; restore on blur if nothing picked
    ccActiveIdx = -1;
    ccRenderMenu("");
  });
  input.addEventListener("input", () => {
    ccActiveIdx = -1;
    ccRenderMenu(input.value);
  });
  input.addEventListener("blur", () => {
    // Delay so a menu click (mousedown) can commit first.
    setTimeout(() => {
      ccCloseMenu();
      if (input.dataset.committed) input.value = input.dataset.committed;
    }, 150);
  });
  input.addEventListener("keydown", (e) => {
    const opts = Array.from(menu.querySelectorAll(".cc-combo-option"));
    if (e.key === "ArrowDown") {
      e.preventDefault();
      ccActiveIdx = Math.min(ccActiveIdx + 1, opts.length - 1);
      ccRenderMenu(input.value);
      menu.querySelector(".cc-combo-option.is-active")?.scrollIntoView({ block: "nearest" });
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      ccActiveIdx = Math.max(ccActiveIdx - 1, 0);
      ccRenderMenu(input.value);
      menu.querySelector(".cc-combo-option.is-active")?.scrollIntoView({ block: "nearest" });
    } else if (e.key === "Enter") {
      e.preventDefault();
      const pick = opts[ccActiveIdx] || opts[0];
      if (pick) { setPhoneCC(pick.getAttribute("data-dial")); ccCloseMenu(); input.blur(); }
    } else if (e.key === "Escape") {
      ccCloseMenu();
      if (input.dataset.committed) input.value = input.dataset.committed;
      input.blur();
    }
  });
  // mousedown (not click) so it fires before the input's blur.
  menu.addEventListener("mousedown", (e) => {
    const opt = e.target.closest(".cc-combo-option");
    if (!opt) return;
    e.preventDefault();
    setPhoneCC(opt.getAttribute("data-dial"));
    ccCloseMenu();
  });
}

