using MongoDB.Driver;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Core.Notifications;
using SoulPilates.Infrastructure.Data;
using System.Collections.Generic;
using System.Threading.Tasks;

namespace SoulPilates.Services;

public class ClientService : IClientService
{
    private readonly IMongoCollection<Client> _clients;
    private readonly IMongoCollection<Attendance> _attendances;
    private readonly IMongoCollection<ClientPackage> _packages;
    private readonly IAuditLogger _audit;
    private readonly INotificationPublisher _notifications;

    public ClientService(MongoDbContext dbContext, IAuditLogger audit, INotificationPublisher notifications)
    {
        _clients = dbContext.GetCollection<Client>("Clients");
        _attendances = dbContext.GetCollection<Attendance>("Attendances");
        _packages = dbContext.GetCollection<ClientPackage>("ClientPackages");
        _audit = audit;
        _notifications = notifications;
    }

    /// <summary>
    /// Active remaining credits per client, split into (group, mat, private).
    /// MIXED packages count as group (they're usable for group/mat classes).
    /// </summary>
    public async Task<Dictionary<string, (int group, int mat, int priv)>> GetActiveCreditsByClientAsync()
    {
        var packages = await _packages.Find(p => p.CreditsRemaining > 0).ToListAsync();
        var result = new Dictionary<string, (int group, int mat, int priv)>();
        foreach (var grp in packages.GroupBy(p => p.ClientId))
        {
            if (string.IsNullOrEmpty(grp.Key)) continue;
            int g = 0, m = 0, pr = 0;
            foreach (var p in grp)
            {
                switch ((p.Format ?? "").ToUpperInvariant())
                {
                    case "MAT": m += p.CreditsRemaining; break;
                    case "PRIVATE": pr += p.CreditsRemaining; break;
                    default: g += p.CreditsRemaining; break; // GROUP, MIXED, other
                }
            }
            result[grp.Key] = (g, m, pr);
        }
        return result;
    }

    /// <summary>Checked-in class count for one client (drives the Super VIP tier).</summary>
    public async Task<int> GetCheckedInCountAsync(string clientId) =>
        (int)await _attendances.CountDocumentsAsync(a => a.ClientId == clientId && a.Status == "CHECKED_IN");

    /// <summary>Checked-in class counts for every client in one aggregation (clientId → count).</summary>
    public async Task<Dictionary<string, int>> GetCheckedInCountsAsync()
    {
        var grouped = await _attendances.Aggregate()
            .Match(Builders<Attendance>.Filter.Eq(a => a.Status, "CHECKED_IN"))
            .Group(a => a.ClientId, g => new { ClientId = g.Key, Count = g.Count() })
            .ToListAsync();
        return grouped
            .Where(x => !string.IsNullOrEmpty(x.ClientId))
            .ToDictionary(x => x.ClientId!, x => x.Count);
    }

    public async Task<IEnumerable<Client>> GetAllClientsAsync()
    {
        return await _clients.Find(c => !c.IsStudioRentalProfile).ToListAsync();
    }

    public async Task<Client?> GetClientByIdAsync(string id)
    {
        return await _clients.Find(c => c.Id == id).FirstOrDefaultAsync();
    }

    public async Task<IEnumerable<Client>> SearchClientsAsync(string query)
    {
        if (string.IsNullOrWhiteSpace(query)) return await GetAllClientsAsync();

        var digitsOnly = new string(query.Where(char.IsDigit).ToArray());

        var filterBuilder = Builders<Client>.Filter;
        var filter = filterBuilder.Or(
            filterBuilder.Regex(c => c.FullName, new MongoDB.Bson.BsonRegularExpression(query, "i")),
            filterBuilder.Regex(c => c.Email, new MongoDB.Bson.BsonRegularExpression(query, "i")),
            filterBuilder.Regex(c => c.PhoneNumber, new MongoDB.Bson.BsonRegularExpression(query, "i")),
            string.IsNullOrEmpty(digitsOnly)
                ? filterBuilder.Where(_ => false)
                : filterBuilder.Regex(c => c.PhoneNumber, new MongoDB.Bson.BsonRegularExpression(digitsOnly, "i"))
        );

        filter &= filterBuilder.Eq(c => c.IsStudioRentalProfile, false);
        return await _clients.Find(filter).ToListAsync();
    }

    public async Task<Client> CreateClientAsync(Client client)
    {
        await _clients.InsertOneAsync(client);

        if (!client.IsStudioRentalProfile)
        {
            _ = Task.Run(async () =>
            {
                try
                {
                    var payload = new PushPayload
                    {
                        Title = "New client added",
                        Body  = $"{client.FullName} - {client.PhoneCountryCode}{client.PhoneNumber}",
                        Icon  = "/icons/icon-192.png",
                        Badge = "/icons/icon-192.png",
                        Url   = $"/admin/clients/{client.Id}",
                        Tag   = $"newclient-{client.Id}",
                    };
                    await _notifications.PublishToRolesAsync(
                        new[] { "Admin", "Manager", "Owner" },
                        NotificationCategory.NewClient,
                        payload);
                }
                catch { }
            });
        }

        return client;
    }

    public async Task UpdateClientAsync(string id, Client client)
    {
        var existing = await _clients.Find(c => c.Id == id).FirstOrDefaultAsync();

        client.Id = id;
        await _clients.ReplaceOneAsync(c => c.Id == id, client);

        if (existing is not null)
        {
            var changedBefore = new Dictionary<string, object?>();
            var changedAfter = new Dictionary<string, object?>();

            if (existing.FullName != client.FullName)
            {
                changedBefore["FullName"] = existing.FullName;
                changedAfter["FullName"] = client.FullName;
            }
            if (existing.Email != client.Email)
            {
                changedBefore["Email"] = existing.Email;
                changedAfter["Email"] = client.Email;
            }
            if (existing.PhoneNumber != client.PhoneNumber || existing.PhoneCountryCode != client.PhoneCountryCode)
            {
                changedBefore["Phone"] = $"{existing.PhoneCountryCode}{existing.PhoneNumber}";
                changedAfter["Phone"] = $"{client.PhoneCountryCode}{client.PhoneNumber}";
            }
            if (existing.DateOfBirth != client.DateOfBirth)
            {
                changedBefore["DateOfBirth"] = existing.DateOfBirth;
                changedAfter["DateOfBirth"] = client.DateOfBirth;
            }

            if (changedBefore.Count > 0)
            {
                await _audit.LogAsync(
                    action: "PII_UPDATE",
                    entityType: "Client",
                    entityId: id,
                    entityLabel: client.FullName,
                    before: changedBefore,
                    after: changedAfter);
            }
        }
    }

    public async Task<Client?> FindByPhoneOrEmailAsync(string phone, string? email)
    {
        if (!string.IsNullOrWhiteSpace(phone))
        {
            var byPhone = await _clients.Find(c => c.PhoneNumber == phone && !c.IsStudioRentalProfile).FirstOrDefaultAsync();
            if (byPhone != null) return byPhone;

            if (phone.StartsWith('+'))
            {
                var (cc, national) = PhoneSplitter.Split(phone);
                if (cc != null && !string.IsNullOrEmpty(national))
                {
                    byPhone = await _clients
                        .Find(c => c.PhoneCountryCode == cc && c.PhoneNumber == national && !c.IsStudioRentalProfile)
                        .FirstOrDefaultAsync();
                    if (byPhone != null) return byPhone;
                }
            }
        }

        if (!string.IsNullOrWhiteSpace(email))
        {
            return await _clients.Find(c => c.Email == email && !c.IsStudioRentalProfile).FirstOrDefaultAsync();
        }

        return null;
    }
}

