using MongoDB.Driver;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Core.Notifications;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.Services;

/// <summary>
/// Per-variant inventory CRUD plus atomic stock mutations. Activates the
/// dormant <see cref="MerchandiseSku"/> entity in P3-S14.
///
/// <para>
/// <see cref="TryDeductAsync"/> uses a filter-guarded <c>$inc</c> exactly mirroring
/// <c>VoucherService.RedeemAsync</c> and <c>PromotionService.RedeemAsync</c> so two
/// concurrent POS sales of the last unit can't both succeed. The deduction is the
/// payment-time effect; the wider invoice flow surrounds it with a rollback loop
/// (see <c>InvoiceService.DeductStockForMerchandiseLinesAsync</c>).
/// </para>
/// </summary>
public class MerchandiseSkuService : IMerchandiseSkuService
{
    private readonly IMongoCollection<MerchandiseSku> _skus;
    private readonly IMongoCollection<Invoice> _invoices;
    private readonly IMongoCollection<LowStockAlert> _lowStockAlerts;
    private readonly INotificationPublisher _notifications;

    public MerchandiseSkuService(MongoDbContext context, INotificationPublisher notifications)
    {
        _skus            = context.GetCollection<MerchandiseSku>("MerchandiseSkus");
        _invoices        = context.GetCollection<Invoice>("Invoices");
        _lowStockAlerts  = context.GetCollection<LowStockAlert>("LowStockAlerts");
        _notifications   = notifications;

        // TTL index: auto-expire alert rows after 48 hours so the same SKU
        // can re-trigger if it stays below threshold for multiple POS cycles.
        try
        {
            _lowStockAlerts.Indexes.CreateOne(new CreateIndexModel<LowStockAlert>(
                Builders<LowStockAlert>.IndexKeys.Ascending(a => a.FiredAt),
                new CreateIndexOptions { ExpireAfter = TimeSpan.FromHours(48), Name = "ttl_fired_48h" }));
        }
        catch { /* tolerate hot-reload / already-exists */ }
    }

    public async Task<List<MerchandiseSku>> GetAllAsync() =>
        await _skus.Find(Builders<MerchandiseSku>.Filter.Empty)
            .SortBy(s => s.ProductId)
            .ThenBy(s => s.VariantColor)
            .ThenBy(s => s.VariantSize)
            .ToListAsync();

    public async Task<List<MerchandiseSku>> GetByProductIdAsync(string productId) =>
        await _skus.Find(s => s.ProductId == productId)
            .SortBy(s => s.VariantColor)
            .ThenBy(s => s.VariantSize)
            .ToListAsync();

    public async Task<MerchandiseSku?> GetByIdAsync(string id) =>
        await _skus.Find(s => s.Id == id).FirstOrDefaultAsync();

    public async Task<MerchandiseSku> CreateAsync(MerchandiseSku sku)
    {
        if (sku is null) throw new ArgumentNullException(nameof(sku));
        if (string.IsNullOrWhiteSpace(sku.ProductId))
            throw new ArgumentException("ProductId is required.", nameof(sku));
        if (sku.StockQuantity < 0)
            throw new ArgumentException("StockQuantity cannot be negative.", nameof(sku));
        if (sku.ReorderThreshold < 0)
            throw new ArgumentException("ReorderThreshold cannot be negative.", nameof(sku));

        sku.CreatedAt = DateTime.UtcNow;
        sku.UpdatedAt = DateTime.UtcNow;
        await _skus.InsertOneAsync(sku);
        return sku;
    }

    public async Task UpdateAsync(string id, MerchandiseSku sku)
    {
        if (sku is null) throw new ArgumentNullException(nameof(sku));
        if (sku.StockQuantity < 0)
            throw new ArgumentException("StockQuantity cannot be negative.", nameof(sku));
        if (sku.ReorderThreshold < 0)
            throw new ArgumentException("ReorderThreshold cannot be negative.", nameof(sku));

        // Whitelisted update. ProductId is immutable post-create.
        var u = Builders<MerchandiseSku>.Update
            .Set(s => s.VariantColor, sku.VariantColor)
            .Set(s => s.VariantSize, sku.VariantSize)
            .Set(s => s.Sku, sku.Sku)
            .Set(s => s.StockQuantity, sku.StockQuantity)
            .Set(s => s.ReorderThreshold, sku.ReorderThreshold)
            .Set(s => s.UpdatedAt, DateTime.UtcNow);

        await _skus.UpdateOneAsync(s => s.Id == id, u);
    }

    public async Task DeleteAsync(string id)
    {
        // Referential-integrity guard: refuse to delete an SKU that any
        // past invoice points at via InvoiceLine.VariantId. The admin can
        // zero the stock instead and let the SKU sit dormant.
        var inUse = await _invoices
            .Find(i => i.Lines.Any(l => l.VariantId == id))
            .AnyAsync();
        if (inUse)
            throw new InvalidOperationException(
                "Cannot delete a SKU referenced by historical invoices. Zero its stock instead.");

        await _skus.DeleteOneAsync(s => s.Id == id);
    }

    public async Task<bool> TryDeductAsync(string skuId, int quantity)
    {
        if (quantity <= 0) throw new ArgumentOutOfRangeException(nameof(quantity), "Must be > 0.");

        // Filter-guarded $inc: only matches when StockQuantity >= quantity, so
        // a concurrent deduction past the last unit returns null and the caller
        // can roll back / 409. We use FindOneAndUpdate (instead of the old
        // UpdateOneAsync) to get the post-deduction document for the low-stock check.
        var filter = Builders<MerchandiseSku>.Filter.And(
            Builders<MerchandiseSku>.Filter.Eq(s => s.Id, skuId),
            Builders<MerchandiseSku>.Filter.Gte(s => s.StockQuantity, quantity));

        var update = Builders<MerchandiseSku>.Update
            .Inc(s => s.StockQuantity, -quantity)
            .Set(s => s.UpdatedAt, DateTime.UtcNow);

        var updated = await _skus.FindOneAndUpdateAsync(filter, update,
            new FindOneAndUpdateOptions<MerchandiseSku> { ReturnDocument = ReturnDocument.After });

        if (updated is null) return false;

        // P5-PWA — Low-stock check. Only fire if (a) we actually crossed below
        // the threshold on this deduction and (b) no alert exists for this SKU
        // within the 48h collapse window (TTL-managed LowStockAlerts collection).
        if (updated.ReorderThreshold > 0 && updated.StockQuantity <= updated.ReorderThreshold)
        {
            _ = Task.Run(async () =>
            {
                try
                {
                    // Collapse guard: if we already fired for this SKU in the last 48h, skip.
                    var recent = await _lowStockAlerts
                        .Find(a => a.SkuId == skuId)
                        .AnyAsync();
                    if (recent) return;

                    // Insert collapse row. If two concurrent sales both pass the
                    // AnyAsync check, both try to insert; both succeed (no unique
                    // index on SkuId — intentional, 2 alerts in quick succession is
                    // tolerable vs. adding a race-prone unique constraint). The TTL
                    // index cleans up.
                    await _lowStockAlerts.InsertOneAsync(new LowStockAlert
                    {
                        SkuId   = skuId,
                        FiredAt = DateTime.UtcNow,
                    });

                    var payload = new PushPayload
                    {
                        Title = "⚠️ Low stock",
                        Body  = $"{updated.Sku ?? skuId} — {updated.StockQuantity} left (threshold: {updated.ReorderThreshold})",
                        Icon  = "/icons/icon-192.png",
                        Badge = "/icons/icon-192.png",
                        Url   = "/admin/merchandise",
                        Tag   = $"lowstock-{skuId}",
                    };
                    await _notifications.PublishToRolesAsync(
                        new[] { "Admin", "Manager", "Owner" },
                        NotificationCategory.LowStock,
                        payload);
                }
                catch { /* publisher logs internally */ }
            });
        }

        return true;
    }

    public async Task<int> IncrementAsync(string skuId, int quantity)
    {
        if (quantity <= 0) throw new ArgumentOutOfRangeException(nameof(quantity), "Must be > 0.");

        var update = Builders<MerchandiseSku>.Update
            .Inc(s => s.StockQuantity, quantity)
            .Set(s => s.UpdatedAt, DateTime.UtcNow);

        var updated = await _skus.FindOneAndUpdateAsync(
            s => s.Id == skuId,
            update,
            new FindOneAndUpdateOptions<MerchandiseSku> { ReturnDocument = ReturnDocument.After });

        if (updated is null)
            throw new InvalidOperationException($"SKU {skuId} not found.");

        return updated.StockQuantity;
    }
}

