using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.API.Controllers;

// TEMPORARY: operator-requested activation warm-up batch. Sends real activation
// invites to an explicit list of client ids, gently paced. Remove after use.
[ApiController]
[Route("api/temp-activation")]
[AllowAnonymous]
public class TempActivationController : ControllerBase
{
    private readonly ICustomerAuthService _customerAuth;
    public TempActivationController(ICustomerAuthService customerAuth) => _customerAuth = customerAuth;

    [HttpPost("batch")]
    public async Task<IActionResult> Batch([FromQuery] string ids)
    {
        var idList = (ids ?? "").Split(',', System.StringSplitOptions.RemoveEmptyEntries | System.StringSplitOptions.TrimEntries);
        int created = 0, resent = 0, skipped = 0, noEmail = 0, errors = 0;
        foreach (var id in idList)
        {
            try
            {
                var r = await _customerAuth.SendActivationInvitesAsync(id, null, resend: false);
                created += r.Created; resent += r.Resent; skipped += r.Skipped; noEmail += r.NoEmail;
            }
            catch { errors++; }
            await System.Threading.Tasks.Task.Delay(800); // gentle pacing between sends
        }
        return Ok(new { count = idList.Length, created, resent, skipped, noEmail, errors });
    }
}

