public async Task<bool> UpdateBlueprintImageAsync(string id, string field, string? url)
{
    UpdateDefinition<ClassBlueprint> update = field switch
    {
        "image" => Builders<ClassBlueprint>.Update.Set(b => b.ImageUrl, url),
        _ => throw new ArgumentException($"Unknown image field '{field}'", nameof(field)),
    };
    update = update.Set(b => b.UpdatedAt, DateTime.UtcNow);

    var result = await _blueprints.UpdateOneAsync(b => b.Id == id, update);

    // SPM-73: the hero-image path used to write only the blueprint's ImageUrl,
    // leaving already-materialised future sessions with the stale image.
    // Propagate the new ImageUrl (or null on delete) to the blueprint's future
    // sessions using the SAME gating SyncBlueprintSessionsAsync applies
    // (future, non-cancelled, skip MANUAL/FREELANCE/BLOCK/OVERRIDE origins).
    // This is a TARGETED update of ImageUrl ONLY — DropInPrice and every other
    // denormalised field are deliberately left untouched so historical pricing
    // on existing sessions is preserved (owner decision).
    if (field == "image")
    {
        var fromUtc = DateTime.UtcNow;
        var sb = Builders<CalendarSession>.Filter;
        var sessionFilter = sb.And(
            sb.Eq(s => s.ClassBlueprintId, id),
            sb.Gte(s => s.StartTime, fromUtc),
            sb.Ne(s => s.Status, "CANCELLED"),
            sb.Ne(s => s.Origin, "MANUAL"),
            sb.Ne(s => s.Origin, "FREELANCE"),
            sb.Ne(s => s.Origin, "BLOCK"),
            sb.Ne(s => s.Origin, "OVERRIDE")
        );

        var sessionUpdate = Builders<CalendarSession>.Update
            .Set(s => s.ImageUrl, url)
            .Set(s => s.UpdatedAt, DateTime.UtcNow);

        await _sessions.UpdateManyAsync(sessionFilter, sessionUpdate);
    }

    return result.ModifiedCount > 0;
}

