public async Task<bool> UpdateBlueprintAsync(string id, ClassBlueprint blueprint)
{
    // Hydrate server-managed fields from the existing document so a
    // PUT from the admin form (which never carries the hero image URL or
    // the original CreatedAt) cannot wipe them.
    //
    // This mirrors the defensive pattern in ClientController.Update
    // and shields us from the classic save-after-upload race:
    //
    //   1. user uploads class-image → MediaController writes ImageUrl
    //   2. user clicks Save         → blueprint form PUTs the entity
    //                                without the image field
    //   3. without this hydration  → ReplaceOne sets ImageUrl = null,
    //                                silently clobbering step 1
    var existing = await _blueprints.Find(b => b.Id == id).FirstOrDefaultAsync();
    if (existing is null) return false;

    // SPM-71 — keep the multi-equipment lists + legacy singular consistent.
    NormalizeBlueprintEquipment(blueprint);

    blueprint.Id        = id;
    blueprint.CreatedAt = existing.CreatedAt;
    blueprint.UpdatedAt = DateTime.UtcNow;

    // Only carry forward the hero image URL when the inbound payload did
    // not explicitly set one. To clear it, call MediaController.DeleteClassImage
    // which calls UpdateBlueprintImageAsync directly.
    blueprint.ImageUrl = string.IsNullOrWhiteSpace(blueprint.ImageUrl) ? existing.ImageUrl : blueprint.ImageUrl;

    // Preserve the admin-set "featured" flag — the form doesn't carry it,
    // so the JSON-deserialised default (false) would clobber a true value.
    // The dedicated PATCH /featured endpoint mutates this atomically.
    blueprint.IsFeatured = existing.IsFeatured;

    var result = await _blueprints.ReplaceOneAsync(b => b.Id == id, blueprint);
    return result.ModifiedCount > 0;
}

