var equipmentTypes = ResolveEquipmentTypes(blueprint);
var equipmentTypeSingular = equipmentTypes.Count > 0 ? equipmentTypes[0] : blueprint.EquipmentType;

// Build a lookup: DayOfWeek → list of new WeeklySlots for that day
// This is what we match against per-session to find the "new" slot definition.
var slotsByDay = (blueprint.WeeklySlots ?? new())
    .GroupBy(s => s.DayOfWeek)
    .ToDictionary(g => g.Key, g => g.ToList());

foreach (var session in sessions)
{
    // Convert session UTC start to studio-local to extract day-of-week + time
    var localStart = TimeZoneInfo.ConvertTimeFromUtc(session.StartTime, StudioTz);
    var sessionDay = localStart.DayOfWeek;
    var sessionTimeStr = localStart.ToString("HH:mm");

    // Try to find a matching new slot
    slotsByDay.TryGetValue(sessionDay, out var daySlots);
    daySlots ??= new();

    // Determine new start/end times
    DateTime newUtcStart = session.StartTime;
    DateTime newUtcEnd = session.EndTime;

    if (daySlots.Count == 1)
    {
        // Only one slot on that day — use its time (may have changed)
        var slot = daySlots[0];
        if (TimeSpan.TryParseExact(slot.TimeOfDay, @"hh\:mm", null, out var newTime))
        {
            var newLocalDateTime = localStart.Date.Add(newTime);
            newUtcStart = TimeZoneInfo.ConvertTimeToUtc(newLocalDateTime, StudioTz);
            newUtcEnd = newUtcStart.AddMinutes(blueprint.DurationMinutes);
        }
    }
    else if (daySlots.Count > 1)
    {
        // Multiple slots on the same day — try exact time match first
        var exactMatch = daySlots.FirstOrDefault(s => s.TimeOfDay == sessionTimeStr);
        var slot = exactMatch ?? daySlots[0]; // fall back to first if ambiguous

