// On load, default to the next day that still has upcoming classes. If today
// still has classes left, we stay on today. The "Today" chip is always kept.
async function selectFirstAvailableDay() {
  const today = startOfDay(new Date());
  let target = today;
  try {
    const found = await findFirstAvailableDay(today, 14);
    if (found) target = found;
  } catch { /* fall back to today */ }
  _autoSkipNote = !isSameDay(target, today);
  selectDateChip(target);
}

// Fetch [startDay, startDay+maxDays) and return the earliest day (startOfDay)
// that still has a class which hasn't ended yet — or null if none.
async function findFirstAvailableDay(startDay, maxDays) {
  const endExclusive = addDays(startDay, maxDays);
  const res = await fetch(
    `${API}/api/booking/schedule?start=${startDay.toISOString()}&end=${endExclusive.toISOString()}&format=${activeFormat}`,
  );
  if (!res.ok) return null;
  const sessions = await res.json();
  const now = new Date();
  let earliest = null;
  for (const s of sessions) {
    const start = new Date(s.startTime);
    const end = s.endTime ? new Date(s.endTime) : new Date(start.getTime() + 90 * 60 * 1000);
    if (end < now) continue; // already finished
    const day = startOfDay(start);
    if (!earliest || day < earliest) earliest = day;
  }
  return earliest;

