/// <summary>
/// Propagates a client's new email to its linked login account(s) so the
/// customer can still sign in. Skips (leaves login email unchanged) if the
/// new email is blank or already belongs to a DIFFERENT account, to avoid
/// creating a duplicate-login conflict.
/// </summary>
private async Task SyncAccountEmailAsync(string clientId, string? newEmail)
{
    if (string.IsNullOrWhiteSpace(newEmail)) return;
    var email = newEmail.Trim().ToLowerInvariant();

    var conflict = await _accounts.CountDocumentsAsync(
        a => a.Email == email && a.ClientId != clientId);
    if (conflict > 0) return;

    await _accounts.UpdateManyAsync(
        a => a.ClientId == clientId,
        Builders<CustomerAccount>.Update
            .Set(a => a.Email, email)
            .Set(a => a.UpdatedAt, DateTime.UtcNow));
}

