using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.Services;

/// <summary>
/// Hosted job that drives <see cref="IVipEmailService.SendDueVipEmailsAsync"/>.
/// Ticks a few times a day so VIP / Super VIP congratulations go out shortly
/// after a client crosses the threshold; the per-tier dedup keeps it to one
/// email per upgrade.
/// </summary>
public class VipEmailBackgroundService : BackgroundService
{
    private readonly IServiceProvider _services;
    private readonly ILogger<VipEmailBackgroundService> _logger;

    public VipEmailBackgroundService(IServiceProvider services, ILogger<VipEmailBackgroundService> logger)
    {
        _services = services;
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                using var scope = _services.CreateScope();
                var vip = scope.ServiceProvider.GetRequiredService<IVipEmailService>();
                await vip.SendDueVipEmailsAsync(stoppingToken);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "VipEmailBackgroundService tick threw");
            }

            // Every 6 hours — dedup makes extra ticks harmless.
            await Task.Delay(TimeSpan.FromHours(6), stoppingToken);
        }
    }
}

using MongoDB.Bson;
using Microsoft.Extensions.Logging;
using MongoDB.Driver;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.Services;

/// <summary>
/// Sends a one-time congratulatory email when a client first reaches VIP or
/// Super VIP. Tier is computed the SAME way as the clients list
/// (spend + checked-in class count vs the admin VIP thresholds). Each client's
/// highest-notified tier is stamped on <see cref="Client.VipTierNotified"/> so
/// the email is sent exactly once per upgrade.
/// </summary>
public class VipEmailService : IVipEmailService
{
    private readonly IMongoCollection<Client> _clients;
    private readonly IMongoCollection<Attendance> _attendances;
    private readonly ISettingsService _settings;
    private readonly IEmailService _email;
    private readonly ILogger<VipEmailService> _logger;

    public VipEmailService(MongoDbContext dbContext, ISettingsService settings, IEmailService email, ILogger<VipEmailService> logger)
    {
        _clients = dbContext.GetCollection<Client>("Clients");
        _attendances = dbContext.GetCollection<Attendance>("Attendances");
        _settings = settings;
        _email = email;
        _logger = logger;
    }

    private static int Rank(string? tier) => tier switch { "SUPER_VIP" => 2, "VIP" => 1, _ => 0 };

    private static string Tier(GlobalSettings s, decimal lifetime, int attended)
    {
        if (!s.EnableVipProgram) return "";
        if (lifetime >= s.SuperVipMinimumSpend && attended >= s.SuperVipMinimumClasses) return "SUPER_VIP";
        if (lifetime >= s.VipMinimumSpend) return "VIP";
        return "";
    }

    public async Task<int> SendDueVipEmailsAsync(CancellationToken ct)
    {
        var settings = await _settings.GetAsync(ct);
        if (!settings.EnableVipProgram) return 0;

        // Checked-in class count per client (drives the Super VIP min-classes gate).
        var counts = new Dictionary<string, int>();
        var grouped = await _attendances.Aggregate()
            .Match(Builders<Attendance>.Filter.Eq(a => a.Status, "CHECKED_IN"))
            .Group(new BsonDocument { { "_id", "$ClientId" }, { "n", new BsonDocument("$sum", 1) } })
            .ToListAsync(ct);
        foreach (var g in grouped)
        {
            var id = g["_id"];
            var key = id.IsObjectId ? id.AsObjectId.ToString() : (id.IsString ? id.AsString : null);
            if (key != null) counts[key] = g["n"].ToInt32();
        }

        var clients = await _clients.Find(Builders<Client>.Filter.And(
            Builders<Client>.Filter.Ne(c => c.Email, null),
            Builders<Client>.Filter.Eq(c => c.IsStudioRentalProfile, false)
        )).ToListAsync(ct);

        var sent = 0;
        foreach (var c in clients)
        {
            if (ct.IsCancellationRequested) break;
            if (string.IsNullOrWhiteSpace(c.Email) || string.IsNullOrEmpty(c.Id)) continue;

            var attended = counts.GetValueOrDefault(c.Id, 0);
            var tier = Tier(settings, c.LifetimeValue, attended);
            if (Rank(tier) <= Rank(c.VipTierNotified)) continue; // no new achievement

            try
            {
                if (tier == "SUPER_VIP")
                    await _email.SendSuperVipEmailAsync(c.Email, c.FullName);
                else
                    await _email.SendVipEmailAsync(c.Email, c.FullName);

                // Stamp AFTER a successful send so a failure retries next tick.
                await _clients.UpdateOneAsync(
                    Builders<Client>.Filter.Eq(x => x.Id, c.Id),
                    Builders<Client>.Update.Set(x => x.VipTierNotified, tier),
                    cancellationToken: ct);
                sent++;
            }
            catch (Exception ex)
            {
                _logger.LogWarning(ex, "VipEmailService failed for client {ClientId} ({Email})", c.Id, c.Email);
            }
        }

        if (sent > 0)
            _logger.LogInformation("VipEmailService sent {Count} VIP achievement emails", sent);
        return sent;
    }
}

}

/// <summary>
/// Override a materialised session: reschedule, swap instructor, change capacity.
/// The original session is mutated in-place with IsOverride = true.
/// </summary>
[HttpPatch("session/{id}/override")]
[Authorize(Roles = "Admin,Manager,Instructor")]
public async Task<IActionResult> OverrideSession(string id, [FromBody] OverrideSessionRequest request)
{
    // SPM-91 — resolve the public-visibility intent. When the request omits
    // IsPublic (legacy clients), preserve the session's current value rather
    // than defaulting it on or off.
    var current = await _schedulingService.GetSessionByIdAsync(id);
    if (current is null) return NotFound(new { message = "Session not found." });

    var updated = new CalendarSession
    {
        InstructorId = request.InstructorId,
        InstructorName = request.InstructorName,
        ClassName = request.ClassName,
        FocusArea = request.FocusArea,
        DifficultyLevel = request.DifficultyLevel,
        Capacity = request.Capacity,
        StartTime = request.StartTime,
        EndTime = request.EndTime,
        Status = request.Status,
        IsPublic = request.IsPublic ?? current.IsPublic,
    };
    var success = await _schedulingService.OverrideSessionAsync(id, updated, request.Note);
    if (!success) return NotFound(new { message = "Session not found." });
    return Ok(new { message = "Session overridden." });
}

