/// <summary>
/// Remove a blocked time slot. Hard-deletes the document rather than
/// setting Status = CANCELLED, because blocked slots have no attendances
/// or credits to refund — they are purely visual calendar markers.
/// </summary>
[HttpDelete("session/{id}/unblock")]
[Authorize(Roles = "Admin,Manager")]
public async Task<IActionResult> UnblockTimeSlot(string id)
{
    var success = await _schedulingService.UnblockTimeSlotAsync(id);
    if (!success) return NotFound(new { message = "Blocked slot not found." });
    return Ok(new { message = "Block removed successfully." });
}

/// <summary>
/// SPM-70 — "Block this class": flip a REAL session's Status to BLOCKED (so it
/// leaves the public booking page and refuses reservations) and back again,
/// without deleting the document. SPM-117: allowed even when the session has
/// non-cancelled bookings; those bookings are left untouched.
/// </summary>
[HttpPatch("session/{id}/block-status")]
[Authorize(Roles = "Admin,Manager")]
public async Task<IActionResult> SetSessionBlockStatus(string id, [FromBody] SessionBlockStatusRequest request)
{
    var success = await _schedulingService.SetSessionBlockedAsync(id, request.Blocked);
    if (!success) return NotFound(new { message = "Session not found or already in the requested state." });
    return Ok(new { message = request.Blocked ? "Class blocked." : "Class unblocked." });
}

