open(sessionId) {
  this._sessionId = sessionId;
  const panel = document.getElementById('cdpPanel');
  const overlay = document.getElementById('cdpOverlay');
  if (panel) panel.classList.add('open');
  if (overlay) overlay.classList.add('open');
  if (this._mode === 'drawer') document.body.style.overflow = 'hidden';
  this._loadContent(sessionId);
},

/* ── close ───────────────────────────────────────────────── */
close() {
  const panel = document.getElementById('cdpPanel');
  const overlay = document.getElementById('cdpOverlay');
  if (panel) panel.classList.remove('open');
  if (overlay) overlay.classList.remove('open');
  if (this._mode === 'drawer') document.body.style.overflow = '';
  this._sessionId = null;
  this._sessionDetail = null;
  if (this._onClose) this._onClose();
},

/* ── refresh ─────────────────────────────────────────────── */
refresh() {
  if (this._sessionId) this._loadContent(this._sessionId);
},

/* ── viewAttendanceHistory ───────────────────────────────────
 * "View attendance history" control. When the panel is already the
 * drawer on the Classes page (drawer mode), the session detail — which
 * IS the attendance history — is already open, so just keep it open and
 * refresh in place instead of reloading the page (which used to close the
 * drawer). From the calendar (panel mode) we deep-link to the Classes
 * page so the full history view opens there.
 */
viewAttendanceHistory() {
  if (!this._sessionId) return;
  if (this._mode === 'drawer') {
    this.refresh();
  } else {
    window.location.href = `/admin/classes?sessionId=${encodeURIComponent(this._sessionId)}`;
  }
},

/* ── _loadContent ────────────────────────────────────────── */
async _loadContent(sessionId) {
  const el = document.getElementById('cdpContent');
  if (!el) return;
  el.innerHTML = '<div style="padding:48px 20px;text-align:center;color:var(--color-text-muted);">Loading…</div>';
  try {
    const r = await fetch(`${_CDP_API}/api/scheduling/class/${sessionId}`, {
      headers: { Authorization: 'Bearer ' + this._getToken() },
    });
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    const c = await r.json();
    this._sessionDetail = c;
    this._render(c);
  } catch (err) {
    if (el) el.innerHTML = '<div style="padding:48px 20px;text-align:center;color:var(--color-text-muted);">Failed to load class details.</div>';
  }
},

/* ── helpers ─────────────────────────────────────────────── */
_esc(s) {
  return String(s ?? '').replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
},
_fmtMoney(n) { return `₫${Math.round(Number(n) || 0).toLocaleString()}`; },
_fmtTime(d) { return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }); },
_isoLocal(d) { return new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 16); },

/* ── _render ─────────────────────────────────────────────── */
_render(c) {
  const el = document.getElementById('cdpContent');
  if (!el) return;
  const esc = this._esc.bind(this);
  const st = new Date(c.startTime), et = new Date(c.endTime);
  const dateStr = st.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' });
  const timeStr = `${this._fmtTime(st)} – ${this._fmtTime(et)}`;
  const duration = Math.round((et - st) / 60000);
  const spotsLeft = Math.max(0, (c.capacity || 0) - (c.currentBookings || 0));

