const HOURS = Array.from({ length: 16 }, (_, i) => i + 6); // 6am–9pm

/* ══════════════════════════════════════════════════════════════
   COLOR-BY ENGINE
   Colors are driven by REAL structured session fields (not the
   class name). The active dimension is selected via the toolbar
   "Color by" dropdown. Fixed palettes are used for the closed sets
   (Format, Difficulty); open-ended sets (Equipment, Instructor)
   derive a STABLE color per distinct value via hue hashing so the
   same value always maps to the same swatch within the view.
   ══════════════════════════════════════════════════════════════ */

// Fixed palettes for the closed-set dimensions.
const FORMAT_COLORS = {
  GROUP:   { bg: 'rgba(43,183,163,0.15)', accent: '#2BB7A3', text: '#5dd8c4' },
  PRIVATE: { bg: 'rgba(244,146,60,0.15)', accent: '#F4923C', text: '#f6a962' },
  DUO:     { bg: 'rgba(139,92,246,0.15)', accent: '#8B5CF6', text: '#a78bfa' },
};
const DIFFICULTY_COLORS = {
  ALL_LEVELS:   { bg: 'rgba(110,168,254,0.15)', accent: '#6EA8FE', text: '#8fbdff' },
  BEGINNER:     { bg: 'rgba(52,168,83,0.15)',   accent: '#34A853', text: '#5fc77c' },
  INTERMEDIATE: { bg: 'rgba(244,146,60,0.15)',  accent: '#F4923C', text: '#f6a962' },
  ADVANCED:     { bg: 'rgba(192,57,43,0.15)',   accent: '#C0392B', text: '#e07469' },
};

// Default / fallback dimension. Persisted (optional) in localStorage.
let colorBy = localStorage.getItem('calColorBy') || 'format';

// Build a color object (bg / accent / text) from an HSL hue.
function hslColorFromHue(hue) {
  return {
    bg: `hsla(${hue}, 62%, 55%, 0.15)`,
    accent: `hsl(${hue}, 62%, 55%)`,
    text: `hsl(${hue}, 70%, 68%)`,
  };
}

