 * shortcut's call to PATCH /block-status.
 */
_canBlock(c) {
  // SPM-117 — intentionally NOT gated on attendee count: an admin may block a
  // class even when it has bookings (those bookings are left as-is). The
  // confirm dialog in toggleBlockStatus warns about any booked attendees.
  const role = (this._getRole() || '').toUpperCase();
  const isAdmin = role === 'ADMIN' || role === 'MANAGER' || role === 'OWNER';
  return isAdmin && c && c.origin !== 'BLOCK';
},

// Pull a human-readable message out of an RFC-7807 problem+json body
// (the API's BusinessRuleException → { detail, code }), falling back to text.
async _readApiError(res) {
  try {
    const body = await res.clone().json();
    return body.detail || body.message || body.title || `HTTP ${res.status}`;
  } catch {
    try { return (await res.text()) || `HTTP ${res.status}`; }
    catch { return `HTTP ${res.status}`; }
  }
},

