  else if (s.blockScope === 'DIFFICULTY' && s.blockScopeValue)
    scopeHtml = `<span class="ev-block-scope" style="background:var(--color-warning);color:#000;">${s.blockScopeValue}</span>`;
  const headline = isStandaloneBlock ? (s.blockedReason || 'Blocked') : (s.className || 'Class');
  const hint = isStandaloneBlock ? 'Click to remove' : 'Blocked · click to unblock';
  ev.innerHTML = `<div class="ev-block-icon">🔒</div>
    <div class="ev-block-label">${isStandaloneBlock ? 'Studio Blocked' : 'Class Blocked'}</div>
    <div class="ev-block-reason">${esc(headline)}</div>${scopeHtml}
    <div class="ev-block-unblock" style="font-size:9px;margin-top:4px;opacity:0.7;">${hint}</div>`;
  if (myRole === 'ADMIN' || myRole === 'MANAGER' || myRole === 'OWNER') {
    ev.style.cursor = 'pointer';
    if (isStandaloneBlock)
      ev.addEventListener('click', e => { e.stopPropagation(); showUnblockPopover(e, s); });
    else
      // A blocked REAL class must NOT be deleted — offer revert instead.
      ev.addEventListener('click', e => { e.stopPropagation(); showClassBlockPopover(e, s, false); });
  }
  return ev;
}

const color = getEventColor(s);
const initials = (s.instructorName||'?').split(' ').map(w => w[0]).join('').substring(0,2).toUpperCase();
const isSelected = s.id === selectedSessionId;

let originCls = '';
if (s.origin === 'OVERRIDE') originCls = ' origin-override';
else if (s.origin === 'FREELANCE' || s.isFreelance) originCls = ' origin-freelance';

// Status-based colour (solid): distinguish completed vs no-show sessions.
let statusCls = '';
if (s.status === 'COMPLETED') statusCls = ' status-completed';
else if (s.status === 'NO_SHOW') statusCls = ' status-noshow';

ev.className = `ev${isSelected ? ' selected' : ''}${originCls}${statusCls}`;
// Let the status CSS class own --ev-bg/--ev-accent so the status colour wins;
// only the format colour applies for SCHEDULED (no status class) sessions.
if (!statusCls) {
  ev.style.setProperty('--ev-bg', color.bg);
  ev.style.setProperty('--ev-accent', color.accent);
}
ev.style.setProperty('--ev-text', color.text);
// Stronger tint for the light theme (see CSS): bump the rgba alpha of the
// base bg so cards separate from the white grid. Falls back to the base bg.
const bgSource = statusCls ? '' : color.bg;
if (bgSource && /rgba?\(/i.test(bgSource)) {
  ev.style.setProperty('--ev-bg-strong', bgSource.replace(/([\d.]+)\)\s*$/, '0.30)'));
}

const timeStr = `${fmtTime(st)} – ${fmtTime(et)}`;
const waitlistCount = s.waitlistCount || 0;

ev.innerHTML = `
  <div class="ev-time">${esc(timeStr)}</div>
  <div class="ev-name">${esc(s.className || 'Class')}</div>
  <div class="ev-instructor">
    <span class="ev-inst-avatar" style="background:${color.accent};">${esc(initials)}</span>
    <span class="ev-inst-name">${esc(s.instructorName || '—')}</span>
  </div>
  <div class="ev-capacity">👥 ${s.currentBookings ?? 0} / ${s.capacity ?? '?'}</div>
  <div class="ev-clients" data-sid="${s.id}"></div>
  ${waitlistCount > 0 ? `<span class="ev-waitlist-badge">!${waitlistCount}</span>` : ''}
  ${s.isPublic === false ? `<span class="ev-private-badge" title="Hidden from the public booking page">🔒</span>` : ''}
`;

ev.addEventListener('click', e => { e.stopPropagation(); openDetailPanel(s); });
// SPM-70 — right-click a real class to "Block this class" (admins only).
if (myRole === 'ADMIN' || myRole === 'MANAGER' || myRole === 'OWNER') {
  ev.addEventListener('contextmenu', e => {
    e.preventDefault(); e.stopPropagation();
    showClassBlockPopover(e, s, true);
  });

