  this._searchTimeout = window.setTimeout(() => this._searchStudent(q), 300);
},

async _searchStudent(q) {
  const el = document.getElementById('cdpAddResults');
  if (!el) return;
  if (!q || q.length < 2) { el.innerHTML = ''; return; }
  try {
    const clients = await fetch(`${_CDP_API}/api/client?search=${encodeURIComponent(q)}`,
      { headers: { Authorization: 'Bearer ' + this._getToken() } }).then(r => r.json());
    this._renderStudentResults(clients.slice(0, 5));
  } catch { el.innerHTML = ''; }
},

_renderStudentResults(clients) {
  const el = document.getElementById('cdpAddResults');
  if (!el) return;
  const esc = this._esc.bind(this);
  el.innerHTML = (clients || []).map(c =>
    `<div class="asr-item" onclick="ClassDetailPanel._addStudent('${c.id}','${(c.name || '').replace(/'/g, "\\'")}')">
      <span>${esc(c.name)} <span style="color:var(--color-text-muted);font-size:11px;">${esc(c.phone || '')}</span></span>
      <span style="color:var(--color-brand-accent);font-size:11px;">+ Add</span>
    </div>`
  ).join('');
},

openQuickAddClient() {
  if (this._sessionDetail?.isFreelance) return;
  if (!window.clientForm) {
    console.error('[cdp] clientForm component not initialised');
    return;
  }
  window.clientForm.reset();
  const search = document.getElementById('cdpAddSearch');
  if (search && search.value.trim()) {
    window.clientForm.setName(search.value.trim());
  }
  const overlay = document.getElementById('cdpQuickAddClientModal');
  if (overlay) overlay.classList.add('open');
  setTimeout(() => document.getElementById('cName')?.focus(), 50);
},

closeQuickAddClient() {
  const overlay = document.getElementById('cdpQuickAddClientModal');
  if (overlay) overlay.classList.remove('open');
  window.clientForm?.clearError();
},

async saveQuickAddClient() {
  const btn = document.getElementById('cdpQuickAddSaveBtn');
  const payload = window.clientForm?.getPayload?.();
  if (!payload?.ok) {
    window.clientForm?.showError(payload?.error || 'Please complete the required fields.');
    return;
  }

  window.clientForm.clearError();
