/* ── Split a multi-seat booking into separate people ───────── */
mposStartSplit() {
  const m = this._mpos; if (!m) return;
  this._splitFromAttendanceId = m.attendanceId;
  this.closeCollectModal();
  const hint = document.getElementById('cdpSplitHint');
  if (hint) hint.style.display = '';
  const box = document.getElementById('cdpAddSearch');
  if (box) { box.value = ''; try { box.scrollIntoView({ behavior: 'smooth', block: 'center' }); } catch {} box.focus(); }
  const res = document.getElementById('cdpAddResults'); if (res) res.innerHTML = '';
  window.showToast?.("Choose who the seat you're splitting off belongs to.", 'info');
},

_cancelSplitMode(ev) {
  if (ev?.preventDefault) ev.preventDefault();
  this._splitFromAttendanceId = null;
  const hint = document.getElementById('cdpSplitHint');
  if (hint) hint.style.display = 'none';
  const box = document.getElementById('cdpAddSearch'); if (box) box.value = '';
  const res = document.getElementById('cdpAddResults'); if (res) res.innerHTML = '';
},

async _doSplit(clientId, clientName) {
  const attId = this._splitFromAttendanceId;
  if (!attId) return;
  try {
    const r = await fetch(`${_CDP_API}/api/scheduling/booking/${attId}/split`, {
      method: 'POST',
      headers: { Authorization: 'Bearer ' + this._getToken(), 'Content-Type': 'application/json' },
      body: JSON.stringify({ people: [{ clientId, clientName: (clientName || '').trim(), clientPhone: null }] }),
    });
    if (!r.ok) throw new Error(await this._readApiError(r));
    window.showToast?.(`Split off ${(clientName || 'person').trim()} into their own booking`, 'success');
    this._cancelSplitMode();
    if (this._afterAttendanceUpdate && this._sessionId) await this._afterAttendanceUpdate(this._sessionId);
    this.refresh();
  } catch (err) {
    window.showToast?.(err.message || 'Failed to split booking', 'error');
  }
},

