file.content:
.ins-drawer-overlay {
  position: fixed; inset: 0;
  background: rgba(0,0,0,.45);
  z-index: 999;
  opacity: 0; pointer-events: none;
  transition: opacity 0.25s ease;
}
.ins-drawer-overlay.open { opacity: 1; pointer-events: auto; }
.ins-drawer {
  position: fixed;
  top: 0; right: 0; bottom: 0;
  width: 520px; max-width: 100vw;
  background: var(--color-surface, #1a1410);
  border-left: 1px solid var(--color-border-subtle, rgba(255,255,255,.08));
  box-shadow: -8px 0 32px rgba(0,0,0,.25);
  z-index: 1000;
  transform: translateX(100%);
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  overflow-y: auto;
}
.ins-drawer.open { transform: translateX(0); }
.ins-drawer-inner { min-height: 100%; }

/* Drawer header */
.ins-dp-header {
  display: flex; justify-content: space-between; align-items: flex-start;
  padding: 20px 20px 14px;
  border-bottom: 1px solid var(--color-border-subtle, rgba(255,255,255,.08));
  position: sticky; top: 0;
  background: var(--color-surface, #1a1410); z-index: 2;
}
.ins-dp-close {
  width: 30px; height: 30px; border: none;
  background: var(--color-surface-raised, rgba(255,255,255,.06));
  border-radius: 6px; cursor: pointer;
  color: var(--color-text-muted); flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  font-size: 14px; transition: all 0.12s;
}
.ins-dp-close:hover { background: var(--color-border-subtle); color: var(--color-text-primary); }

/* Drawer meta list */
.ins-dp-meta {
  padding: 14px 20px;
  border-bottom: 1px solid var(--color-border-subtle, rgba(255,255,255,.08));

