  const canReschedule = !_isAllInstructors && _ownsRoster
    && sess?.status === 'SCHEDULED' && sess?.startTime && new Date(sess.startTime) > new Date();

  roster.innerHTML = attendees.map((a, idx) => {
    const initials = (a.clientName || 'U').split(' ').map(w => w[0]).join('').substring(0, 2).toUpperCase();
    const ac = avatarColors[idx % avatarColors.length];
    const statusNorm = (a.status === 'CHECKED_IN') ? 'ARRIVED' : (a.status || 'BOOKED');

    // Payment badge (read-only, no POS link)
    const payBadge = a.isFreeClass
      ? '<span style="font-size:10px;color:var(--color-success,#4ade80);font-weight:600;">FREE</span>'
      : a.paymentStatus === 'package'
        ? '<span style="font-size:10px;color:var(--color-brand-accent,#c8a45d);font-weight:600;">📦 PKG</span>'
        : a.paymentStatus === 'paid'
          ? '<span style="font-size:10px;color:var(--color-success,#4ade80);font-weight:600;">✅ Paid</span>'
          : a.paymentStatus === 'partial'
            ? '<span style="font-size:10px;color:var(--color-warning,#facc15);font-weight:600;">⚠️ Partial</span>'
            : '<span style="font-size:10px;color:var(--color-warning,#facc15);font-weight:600;">Unpaid</span>';

    const statusSelect = `<select class="ins-status-select" data-status="${statusNorm}"
      onchange="insOnStatusChange(this,'${a.attendanceId}')">
      <option value="ARRIVED"      ${statusNorm === 'ARRIVED'      ? 'selected' : ''}>✅ Arrived</option>
      <option value="NO_SHOW"      ${statusNorm === 'NO_SHOW'      ? 'selected' : ''}>❌ No Show</option>
      <option value="LATE_CANCEL"  ${statusNorm === 'LATE_CANCEL'  ? 'selected' : ''}>⚠️ Late Cancel</option>
      <option value="BOOKED"       ${statusNorm === 'BOOKED' || statusNorm === 'RESERVED' ? 'selected' : ''}>📅 Booked</option>
    </select>`;

    const commNote = !a.countsTowardsCommission
      ? '<span title="Excluded from commission" style="font-size:10px;color:var(--color-text-muted);">⛔ No comm.</span>'
      : '';

    // SPM-79 — only BOOKED/RESERVED attendees on an owned, upcoming session can
    // be moved (no payment requirement — unpaid bookings reschedule too).
    const reschedBtn = (canReschedule && (statusNorm === 'BOOKED' || statusNorm === 'RESERVED'))
      ? `<button class="btn btn-secondary btn-sm" style="font-size:11px;padding:3px 8px;"
          onclick="insOpenResched('${a.attendanceId}')">🔁 Reschedule</button>`
      : '';

    return `<div class="ins-att-row">
      <div class="ins-att-avatar" style="background:${ac};">${esc(initials)}</div>
      <div class="ins-att-info">
        <div class="ins-att-name">
