async function insSearchStudent(q) {
  const el = document.getElementById('insAddResults');
  if (!el) return;
  if (!q || q.length < 2) { el.innerHTML = ''; return; }
  try {
    const clients = await fetch(`${API}/api/instructor/clients?search=${encodeURIComponent(q)}`, {
      headers: { Authorization: 'Bearer ' + token },
    }).then(r => r.json());
    el.innerHTML = (clients || []).slice(0, 5).map(c =>
      `<div class="ins-asr-item" onclick="insAddStudent('${c.id}','${(c.name || '').replace(/'/g, "\\'")}','${(c.phone || '').replace(/'/g, "\\'")}')">
        <span>${esc(c.name)} <span style="color:var(--color-text-muted);font-size:11px;">${esc(c.phone || '')}</span></span>
        <span style="color:var(--color-brand-accent,#c8a45d);font-size:11px;">+ Add</span>
      </div>`
    ).join('');
  } catch { el.innerHTML = ''; }
}

async function insAddStudent(clientId, clientName, clientPhone) {
  const sessionId = _currentDrawerSession?.id;
  if (!sessionId) return;
  try {
    const r = await fetch(vaUrl(`${API}/api/instructor/session/${sessionId}/add-student`), {
      method: 'POST',
      headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' },
      body: JSON.stringify({ clientId, clientName: (clientName || '').trim(), clientPhone: clientPhone || null }),
    });
    const data = await r.json().catch(() => ({}));
    if (!r.ok) throw new Error(data.message || `HTTP ${r.status}`);
    window.showToast?.('Client added (unpaid)', 'success');

