[HttpPost("session/{id}/add-student")]
public async Task<IActionResult> AddStudentToMySession(string id, [FromBody] InstructorAddStudentRequest request)
{
    var staffId = ResolveStaffId();
    if (string.IsNullOrWhiteSpace(staffId))
        return NotFound(new { profileLinked = false });

    // Ownership check (admins impersonating bypass this)
    var session = await _schedulingService.GetSessionByIdAsync(id);
    if (session == null)
        return NotFound(new { message = "Session not found." });
    if (!IsAdminRole() && session.InstructorId != staffId)
        return StatusCode(403, new { message = "You can only add clients to your own sessions." });

    try
    {
        var attendance = await _schedulingService.AdminAddStudentAsync(
            id, request.ClientId, request.ClientName, request.ClientPhone, request.Quantity);
        return Ok(attendance);
    }
    catch (Exception ex)
    {
        return BadRequest(new { message = ex.Message });
    }
}

/// <summary>
/// SPM-79 — Instructor reschedules a BOOKED attendee off one of their OWN
/// sessions onto a different (future) session. Reuses the same service
/// mechanics as the admin reschedule (<see cref="ISchedulingService.AdminRescheduleBookingAsync"/>,
/// which carries over the original payment/credit, adjusts both sessions'
/// CurrentBookings, promotes the old session's waitlist and emails the
/// customer) WITHOUT any payment requirement — an UNPAID booking can be moved.
///
/// <para>
/// Ownership: the attendance's CURRENT session (<paramref name="request"/>.CurrentSessionId)
/// must be taught by the caller (admins / owners impersonating skip the check),
/// and the supplied <c>attendanceId</c> must genuinely be on that session's
/// roster — this prevents an instructor moving an arbitrary booking by naming a
/// session they happen to own. All remaining business rules (booking is BOOKED,
/// not already rescheduled, target session exists / has capacity / is in the
/// future / shares the same format) are enforced inside the service.
/// </para>
/// </summary>
