// ── Attendee contact / limited-profile modal ──────────────────
let _insAttCurrent = null; // { attendanceId, clientId, name }

function insOpenAttendee(attendanceId) {
  const a = (window._insRosterAtt || []).find(x => x.attendanceId === attendanceId);
  if (!a) return;
  _insAttCurrent = { attendanceId, clientId: a.clientId, name: a.clientName || 'Attendee' };
  document.getElementById('insAttModalName').textContent = a.clientName || 'Attendee';

  const phone = a.clientPhone || '';
  const email = a.clientEmail || '';
  const rows = [];
  if (phone) rows.push(`<a href="tel:${esc(phone.replace(/\s+/g, ''))}" style="display:flex;align-items:center;gap:8px;color:var(--color-text-primary,#eee);text-decoration:none;font-size:14px;"><span>📞</span><span>${esc(phone)}</span></a>`);
  if (email) rows.push(`<a href="mailto:${esc(email)}" style="display:flex;align-items:center;gap:8px;color:var(--color-text-primary,#eee);text-decoration:none;font-size:14px;word-break:break-all;"><span>✉️</span><span>${esc(email)}</span></a>`);
  if (!phone && !email) rows.push(`<div style="color:var(--color-text-muted);font-size:13px;">No contact details on file.</div>`);
  document.getElementById('insAttContact').innerHTML = rows.join('');

  const prof = document.getElementById('insAttProfile');
  prof.style.display = 'none'; prof.innerHTML = '';
  document.getElementById('insViewProfileBtn').style.display = '';
  document.getElementById('insRemoveAttBtn').style.display = window._insCanManageRoster ? '' : 'none';
  document.getElementById('insAttendeeModal').classList.add('open');
}
