  const btn = document.getElementById('insViewProfileBtn');
  btn.disabled = true; btn.textContent = 'Loading…';
  try {
    const p = await fetch(vaUrl(`${API}/api/instructor/attendee/${_insAttCurrent.clientId}/profile`), {
      headers: { Authorization: 'Bearer ' + token },
    }).then(r => { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); });
    const fmtDate = d => d ? new Date(d).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' }) : '—';
    const line = (label, val) => `<div style="display:flex;justify-content:space-between;gap:12px;font-size:13px;padding:3px 0;"><span style="color:var(--color-text-muted);">${label}</span><span style="text-align:right;">${val}</span></div>`;
