cd /opt/soulpilates && docker exec soulpilates-prod-mongo mongosh -u admin -p "$(grep '^MONGO_PASSWORD=' prod.env|cut -d= -f2)" --quiet --eval '
const db = db.getSiblingDB("soulpilates");
// The 13 activated accounts
const activated = db.CustomerAccounts.find({EmailVerified:true},{ClientId:1,FullName:1}).toArray();
let withPkg = 0, withActivePkg = 0;
const names = [];
for (const a of activated) {
  if (!a.ClientId) continue;
  const anyPkg = db.ClientPackages.countDocuments({ClientId:a.ClientId});
  const activePkg = db.ClientPackages.countDocuments({ClientId:a.ClientId, Status:{$in:["ACTIVE","LOW_BALANCE"]}});
  if (anyPkg > 0) withPkg++;
  if (activePkg > 0) { withActivePkg++; names.push(a.FullName); }
}
print("Activated accounts        : " + activated.length);
print("…that hold ANY package    : " + withPkg);
print("…with an ACTIVE package   : " + withActivePkg);
print("Active-package holders: " + names.join(", "));
' 2>&1

