/// <summary>
/// P5-PWA — fire-and-forget "New booking" push to the instructor of
/// the session + studio Admin/Manager roles. Called the moment an
/// attendance is promoted from RESERVED → BOOKED, which is the
/// definitive "the booking is real" signal (previously this fired
/// from <c>BookingController.ReserveSpot</c>, but reservations can be
/// abandoned mid-checkout, leading to false-positive notifications).
/// </summary>
private void FireAndForgetBookingPush(Attendance attendance, CalendarSession session)
{
    _ = Task.Run(async () =>
    {
        try
        {
            var startLocal = session.StartTime.ToString("ddd HH:mm");
            var who = string.IsNullOrWhiteSpace(attendance.ClientName)
                ? "A client"
                : attendance.ClientName;
            var payload = new PushPayload
            {
                Title = "✨ New booking",
                Body  = $"{who} — {session.ClassName} · {startLocal}",
                Icon  = "/icons/icon-192.png",
                Badge = "/icons/icon-192.png",
                Url   = $"/admin/calendar?session={session.Id}",
                // Per-attendance tag, not per-session, so two confirmed
                // bookings in the same class don't collapse into one.
                Tag   = $"booking-{attendance.Id}",
            };

            // 1. The instructor for this session (if the Staff row links
            //    back to a login User — UserStaffLinker resolves this on boot).
            if (!string.IsNullOrWhiteSpace(session.InstructorId))
            {
                var instructor = await _staff.Find(s => s.Id == session.InstructorId).FirstOrDefaultAsync();
                if (instructor is not null && !string.IsNullOrWhiteSpace(instructor.UserId))
                {
                    await _notifications.PublishAsync(
                        instructor.UserId, NotificationCategory.NewBooking, payload);
                }
            }

            // 2. Studio admins + managers always get notified.
            await _notifications.PublishToRolesAsync(
                new[] { "Admin", "Manager", "Owner" }, NotificationCategory.NewBooking, payload);
        }
        catch { /* publisher already logs */ }
    });
}

