/* ═══ Batch Attendee Fetch ═══ */
async function batchFetchAttendees() {
  const ids = getVisibleSessions().filter(s => s.status !== 'BLOCKED').map(s => s.id);
  const batchSize = 8;
  for (let i = 0; i < ids.length; i += batchSize) {
    await Promise.all(ids.slice(i, i+batchSize).map(async sid => {
      try {
        const bookings = await fetch(`${API}/api/scheduling/session/${sid}/bookings`,
          { headers: { Authorization: 'Bearer ' + token } }).then(r => r.json());
        attendeeCache.set(sid, bookings);
        patchClientNames(sid, bookings);
      } catch {}
    }));
  }
}

function patchClientNames(sid, bookings) {
  const el = document.querySelector(`.ev-clients[data-sid="${sid}"]`);
  if (!el || !bookings.length) return;

