async function renderCalendar() {
  // In PWA mode the grid is hidden — refresh the list view instead of
  // doing the expensive grid render + attendee batch fetch.
  if (IS_PWA) { window.__pwaRefresh?.(); return; }
  const end = new Date(weekStart);
  end.setDate(end.getDate() + 7);

  // Update label
  if (currentView === 'week') {
    const s = weekStart.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
    const e = new Date(end.getTime()-1).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
    document.getElementById('weekLabel').textContent = `${s} – ${e}`;
  } else if (currentView === 'month') {
    document.getElementById('weekLabel').textContent = selectedDayDate.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });

