// ── Push-driven live refresh ────────────────────────────────────────────
// The service worker broadcasts "sp-data-changed" whenever a booking push is
// delivered (new booking / cancel / reschedule from ANY source). We refresh
// the calendar in place only then — no idle polling. Bursts are coalesced,
// and refreshes are deferred while the tab is hidden so we never run the
// expensive grid + attendee fetch for a screen nobody is looking at.
let _spRefreshTimer = null;
let _spRefreshPending = false;
function _spScheduleLiveRefresh() {
  if (document.hidden) { _spRefreshPending = true; return; }
  if (_spRefreshTimer) return;            // already scheduled — coalesce bursts
  _spRefreshTimer = setTimeout(() => {
    _spRefreshTimer = null;
    _spRefreshPending = false;
    try { renderCalendar(); } catch {}
  }, 1500);                                // brief delay lets the DB settle / merges bursts
}
if ('serviceWorker' in navigator) {
  navigator.serviceWorker.addEventListener('message', (e) => {
    if (e.data && e.data.type === 'sp-data-changed') _spScheduleLiveRefresh();
  });
}
document.addEventListener('visibilitychange', () => {
  if (!document.hidden && _spRefreshPending) _spScheduleLiveRefresh();
});

