file.content:
    // Commission base (studio rule, mirrors PayrollService.ResolveAttendeeRevenueAsync):
    //  • package redemption → the package's per-class rate (price ÷ credits), NOT drop-in
    //  • actually paid → what they paid (a genuine full-price drop-in stays drop-in)
    //  • unpaid but the client holds an active package for this format → package rate
    //  • otherwise → drop-in
    decimal revBase = (session.DropInPrice ?? 0m) * qty;

    if (att.PaymentMethod == "PACKAGE_CREDIT")
    {
        if (!string.IsNullOrEmpty(att.PackageInstanceId))
        {
            var pkg = await _clientPackages
                .Find(p => p.Id == att.PackageInstanceId)
                .FirstOrDefaultAsync();
            if (pkg is not null && pkg.FractionalValuePerClass > 0m)
                revBase = pkg.FractionalValuePerClass * qty;
        }
    }
    else
    {
        // Look up invoice for monetary-payment attendees
        var linkedInv = await _invoices.Find(
            Builders<Invoice>.Filter.ElemMatch(
                i => i.Lines,
                Builders<InvoiceLine>.Filter.Eq(l => l.AttendanceId, att.Id)
            )
        ).FirstOrDefaultAsync();

        var paidResolved = false;
        if (linkedInv is not null && linkedInv.Status == "PAID")
        {
            var line = linkedInv.Lines.FirstOrDefault(l => l.AttendanceId == att.Id);
            if (line is not null)
            {
                var lineTotal = line.UnitPrice * line.Quantity - line.LineDiscount;
                if (lineTotal > 0m) { revBase = lineTotal; paidResolved = true; }
            }
            else if (linkedInv.TotalNet > 0m)
            {
                revBase = linkedInv.TotalNet; paidResolved = true;
            }
        }
        else if ((att.AmountPaid ?? 0m) > 0m)
        {
            revBase = att.AmountPaid ?? 0m; paidResolved = true;
        }

        // Not paid a monetary amount, but the client is a package
        // member for this format → the class draws from the package.
        if (!paidResolved && !string.IsNullOrEmpty(session.Format))
        {
            var memberPkg = await _clientPackages
                .Find(p => p.ClientId == att.ClientId
                           && p.Format == session.Format
                           && p.FractionalValuePerClass > 0m
                           && (p.Status == "ACTIVE" || p.Status == "LOW_BALANCE"))
                .FirstOrDefaultAsync();
            if (memberPkg is not null)
                revBase = memberPkg.FractionalValuePerClass * qty;
        }
    }

    // Apply referral discount
    var discountPct = att.ReferralDiscountPct.HasValue
        ? Math.Clamp(att.ReferralDiscountPct.Value, 0m, 1m)
        : 0m;
    classRevenue += revBase * (1m - discountPct);
}

commissionEarned = classRevenue * commissionRate;

