/// Sums <c>Invoice.TotalNet</c> for paid invoices in the current month and
/// the previous month, then computes the delta-vs-previous as a percentage.
/// Returns <c>null</c> for the delta when the previous month had zero
/// revenue &mdash; an &infin;% jump is meaningless on a fresh DB and would
/// be more misleading than a dash on the dashboard.
/// </summary>
private async Task<(decimal current, decimal previous, decimal? deltaPct)> ComputeRevenueAsync(
    DateTime monthStart, DateTime nextMonthStart, DateTime prevMonthStart)
{
    var current = await SumCollectedRevenueAsync(monthStart, nextMonthStart);
    var previous = await SumCollectedRevenueAsync(prevMonthStart, monthStart);

    // Divide-by-zero guard. Previous == 0 means the dashboard's first-ever
    // month — we can't express "infinite growth" honestly, so return null
    // and let the frontend render a muted "— vs last month" pill.
    decimal? deltaPct = previous == 0
        ? (decimal?)null
        : Math.Round((current - previous) / previous * 100m, 1, MidpointRounding.AwayFromZero);

    return (current, previous, deltaPct);
}

/// <summary>
/// Cash actually collected in <c>[start, end)</c>: sums payments whose linked
/// invoice still EXISTS and is not VOIDED. This guards the dashboard against
/// orphan payments (an invoice was deleted/voided but its payment record was
/// left behind) inflating revenue — real money kept, not money invoiced.
/// </summary>
private async Task<decimal> SumCollectedRevenueAsync(DateTime start, DateTime end)
{
    var payments = await _payments
        .Find(Builders<Payment>.Filter.And(
            Builders<Payment>.Filter.Gte(p => p.PaymentDate, start),
            Builders<Payment>.Filter.Lt(p => p.PaymentDate, end)))
        .Project(p => new PaymentRevenueRow { InvoiceId = p.InvoiceId, AmountPaid = p.AmountPaid })
        .ToListAsync();
    if (payments.Count == 0) return 0m;

    var invoiceIds = payments
        .Where(p => !string.IsNullOrEmpty(p.InvoiceId))
        .Select(p => p.InvoiceId!)
        .Distinct()
        .ToList();

    var validInvoiceIds = (await _invoices
            .Find(Builders<Invoice>.Filter.And(
                Builders<Invoice>.Filter.In(i => i.Id, invoiceIds),
                Builders<Invoice>.Filter.Ne(i => i.Status, "VOIDED")))
            .Project(i => i.Id)
            .ToListAsync())
        .ToHashSet();

    return payments
        .Where(p => !string.IsNullOrEmpty(p.InvoiceId) && validInvoiceIds.Contains(p.InvoiceId))
        .Sum(p => p.AmountPaid);
}

private sealed class PaymentRevenueRow
{
    public string? InvoiceId { get; set; }

