namespace SoulPilates.Core.DTOs;

/// <summary>
/// Wire DTO for the dashboard's four top-level KPI cards (P3-S02 / SOW §15.1).
///
/// <para>
/// All amounts in VND. The shape mirrors what `admin/index.astro` renders on
/// the four cards directly above the CapEx-payback widget:
/// </para>
/// <list type="bullet">
///   <item><strong>Monthly Revenue</strong> &mdash; sum of paid invoices in the current calendar month, with a delta vs. the previous month.</item>
///   <item><strong>Active Clients (30d)</strong> &mdash; distinct clients with at least one BOOKED or CHECKED_IN attendance in the trailing 30 days.</item>
///   <item><strong>Classes This Week</strong> &mdash; calendar sessions in the current ISO Monday&ndash;Sunday window with status SCHEDULED or COMPLETED.</item>
///   <item><strong>Payroll Estimate</strong> &mdash; sum of <c>StaffPayable.TotalPayable + OwnerDistribution.TotalAmount</c> for the current month, falling back to the most recent month with rows when the current month hasn't been washed out yet.</item>
/// </list>
///
/// <para>
/// All four values are computed against <c>DateTime.UtcNow</c> on the server.
/// Time-zone shifts to <c>Asia/Ho_Chi_Minh</c> are <strong>not</strong> applied
/// in this slice &mdash; boundary cases are off by hours, not material to a
/// daily-glance KPI. Filed as a Phase-3 follow-up.
/// </para>
/// </summary>
public class DashboardKpisDto
{
    // ── Monthly Revenue ───────────────────────────────────────────────────

    /// <summary>
    /// Sum of <c>Invoice.TotalNet</c> for invoices with <c>Status="PAID"</c> whose
    /// <c>IssueDate</c> falls in <c>[startOfThisMonth, startOfNextMonth)</c>. VND.
    /// </summary>
    public decimal MonthlyRevenueVnd { get; set; }

    /// <summary>
    /// Percentage change vs. previous month, e.g. <c>20.8m</c> for "+20.8%" or
    /// <c>-5.4m</c> for "&minus;5.4%". <c>null</c> when the previous month had
    /// zero revenue (avoids divide-by-zero and meaningless &infin;% deltas on a
    /// fresh DB).
    /// </summary>
    public decimal? MonthlyRevenueDeltaPct { get; set; }

    // ── Active Clients (rolling 30 days) ──────────────────────────────────

    /// <summary>
    /// Distinct count of <c>Attendance.ClientId</c> where <c>BookedAt &ge; asOfUtc - 30d</c>
    /// and <c>Status</c> is <c>"BOOKED"</c> or <c>"CHECKED_IN"</c>. Cancellations,
    /// late-cancels and no-shows are excluded.
    /// </summary>
    public int ActiveClients30d { get; set; }

    // ── Classes This Week (Mon–Sun ISO) ───────────────────────────────────

    /// <summary>
    /// Count of <c>CalendarSession</c> rows whose <c>StartTime</c> falls in the
    /// current Monday&ndash;Sunday window of <c>asOfUtc</c> (ISO 8601, matches
    /// Vietnam convention) and whose <c>Status</c> is <c>"SCHEDULED"</c> or
    /// <c>"COMPLETED"</c>. CANCELLED and BLOCKED rows are excluded.
    /// </summary>
    public int ClassesThisWeek { get; set; }

    // ── Payroll Estimate ──────────────────────────────────────────────────

    /// <summary>
    /// Sum of <c>StaffPayable.TotalPayable + OwnerDistribution.TotalAmount</c>
    /// for the period identified by <see cref="PayrollEstimatePeriodLabel"/>.
    /// VND.
    /// </summary>
    public decimal PayrollEstimateVnd { get; set; }

    /// <summary>
    /// Human-readable period label for the payroll figure, e.g. <c>"May 2026"</c>
    /// when the current month has been washed out, or <c>"Apr 2026"</c> when we
    /// fell back to the latest computed month (and <see cref="PayrollEstimateIsLatestComputed"/> is <c>true</c>).
    /// Empty when no month has any payroll rows.
    /// </summary>
    public string PayrollEstimatePeriodLabel { get; set; } = string.Empty;

    /// <summary>
    /// <c>true</c> when the current month has no <c>StaffPayable</c> or
    /// <c>OwnerDistribution</c> rows yet and the figure was sourced from the
    /// most-recent month that does have rows. The dashboard surfaces this with
    /// a *"From {label} (current month not yet computed)"* subtitle so owners
    /// aren't misled by a stale number.
    /// </summary>
    public bool PayrollEstimateIsLatestComputed { get; set; }

    // ── Meta ──────────────────────────────────────────────────────────────

    /// <summary>Wall-clock at compute time (server <c>UtcNow</c>). Useful for "as of …" tooltips and cache busting.</summary>
    public DateTime ComputedAt { get; set; }
}

