    // Online (VAT) fees are a pass-through, excluded from the revenue above.
    const fee = d.onlineFeesReceivedVnd ?? 0;
    const fe = el.querySelector('[data-f=f]');
    if (fe) fe.textContent = fee > 0 ? `+ ${fmtVnd(fee)} online fees collected (excl. from revenue)` : 'Revenue is net of online (VAT) fees'; },
