namespace SoulPilates.Core.Entities;

/// <summary>
/// Control-plane record for one licensed studio (SaaS tenant). Lives in the
/// control database, NOT in any tenant database. Each tenant's actual studio
/// data (clients, bookings, invoices…) lives in its own database named
/// <see cref="DatabaseName"/>, giving hard database-per-tenant isolation.
/// </summary>
public class Tenant : BaseEntity
{
    /// <summary>URL-safe subdomain label, e.g. "studio-a" → studio-a.studionexis.soulpilates.com.vn.</summary>
    public string Slug { get; set; } = null!;

    /// <summary>Human-facing studio name.</summary>
    public string DisplayName { get; set; } = null!;

    /// <summary>The Mongo database this tenant's data lives in, e.g. "tenant_studio-a".</summary>
    public string DatabaseName { get; set; } = null!;

    /// <summary>ACTIVE | SUSPENDED. Suspended tenants are refused at resolution time.</summary>
    public string Status { get; set; } = "ACTIVE";

    /// <summary>Licensing plan tier, e.g. TRIAL | STARTER | PRO.</summary>
    public string Plan { get; set; } = "TRIAL";

    /// <summary>Optional custom domain mapped to this tenant (future).</summary>
