using System.Collections.Concurrent;
using MongoDB.Driver;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Multitenancy;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.Infrastructure.Multitenancy;

/// <summary>
/// Singleton tenant resolver over the control-plane DB, with a short in-memory
/// cache so we don't hit Mongo on every request. Cache is invalidated on
/// create/suspend/update via <see cref="Invalidate"/>.
/// </summary>
public class TenantRegistry : ITenantRegistry
{
    private readonly ControlPlaneContext _control;
    private readonly ConcurrentDictionary<string, (Tenant? tenant, DateTime cachedAt)> _cache = new();
    private static readonly TimeSpan CacheTtl = TimeSpan.FromMinutes(5);

    public TenantRegistry(ControlPlaneContext control) => _control = control;

    public async Task<Tenant?> ResolveBySlugAsync(string slug, CancellationToken ct = default)
    {
        if (string.IsNullOrWhiteSpace(slug)) return null;
        slug = slug.ToLowerInvariant();

        if (_cache.TryGetValue(slug, out var hit) && DateTime.UtcNow - hit.cachedAt < CacheTtl)
            return hit.tenant;

        var tenant = await _control.Tenants
            .Find(t => t.Slug == slug && t.Status == "ACTIVE")
            .FirstOrDefaultAsync(ct);

        _cache[slug] = (tenant, DateTime.UtcNow);
        return tenant;
    }

    public void Invalidate(string slug)
    {
        if (!string.IsNullOrWhiteSpace(slug))
            _cache.TryRemove(slug.ToLowerInvariant(), out _);
    }
}

