        catch (Exception ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    [HttpGet("tenants")]
    public async Task<IActionResult> ListTenants()
    {
        if (GuardControlPlane() is { } deny) return deny;
        var tenants = await _provisioning.ListTenantsAsync();
        return Ok(tenants.Select(t => new { t.Id, t.Slug, t.DisplayName, t.Status, t.Plan, t.CreatedAt, t.SuspendedAt }));
    }

    [HttpPatch("tenants/{slug}/status")]
    public async Task<IActionResult> SetStatus(string slug, [FromBody] SetTenantStatusRequest req)
    {
        if (GuardControlPlane() is { } deny) return deny;
        try
        {
            var ok = await _provisioning.SetStatusAsync(slug, req.Status);
            return ok ? Ok(new { message = $"Studio '{slug}' → {req.Status}." })
                      : NotFound(new { message = "Studio not found." });
        }
        catch (Exception ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }
}

