// Studio Nexis — SaaS marketing landing page (control-plane / apex host).
// The actual studio app is served on tenant subdomains (<studio>.studionexis…).
const siteName = "Studio Nexis";
const tagline = "The all-in-one platform to run your pilates & yoga studio.";
const features = [
  { icon: "📅", title: "Booking & Scheduling", body: "Online class booking, waitlists, private &amp; duo sessions, capacity control, and a live calendar your front desk actually enjoys." },
  { icon: "👥", title: "Client CRM", body: "Every client's profile, history, packages, medical notes, and lifetime value — one searchable place, no spreadsheets." },
  { icon: "🎟️", title: "Packages &amp; Memberships", body: "Sell class packs and memberships, auto-track credits in real time, and handle freezes, expiries, and renewals automatically." },
  { icon: "💳", title: "Payments &amp; POS", body: "Take payments at the desk or online, split bills, apply promos, and issue clean invoices &amp; receipts." },
  { icon: "📊", title: "Finance &amp; Reporting", body: "Cash-basis revenue, P&amp;L, per-class economics, and dashboards that tell you what's working — at a glance." },
  { icon: "🧾", title: "Payroll &amp; Commission", body: "Instructor commission (flat, per-head, tiered, revenue-split), bonuses, and one-click monthly payroll runs." },
  { icon: "🔔", title: "Notifications", body: "Automatic reminders, reviews, birthdays, and VIP milestones by email + push — so you retain more clients on autopilot." },
  { icon: "📈", title: "Analytics", body: "Occupancy, retention, funnel, and instructor performance — the numbers that grow a studio, not vanity metrics." },
];
