<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover" />
    <title>Studio Nexis — All-in-one studio management for pilates & yoga</title>
    <meta name="description" content="Studio Nexis is the all-in-one management platform for pilates and yoga studios: booking, CRM, packages, payments, finance, payroll, and analytics in one system." />
    <link rel="icon" href="/favicon.svg" type="image/svg+xml" />
    <meta property="og:type" content="website" />
    <meta property="og:title" content="Studio Nexis — All-in-one studio management" />
    <meta property="og:description" content="Booking, CRM, finance, payroll & analytics for pilates and yoga studios — in one platform." />
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&family=Sora:wght@600;700;800&display=swap" rel="stylesheet" />
    <style>
      :root{
        --bg:#0b1020; --bg2:#0f1630; --card:#141c38; --line:rgba(255,255,255,.08);
        --text:#eef1ف9; --text:#eef1f9; --muted:#9aa6c7; --brand:#6d5efc; --brand2:#22d3ee; --accent:#a78bfa;
      }
      *{box-sizing:border-box;margin:0;padding:0}
      body{font-family:'Inter',system-ui,sans-serif;background:var(--bg);color:var(--text);line-height:1.6;-webkit-font-smoothing:antialiased}
      a{color:inherit;text-decoration:none}
      .wrap{max-width:1120px;margin:0 auto;padding:0 24px}
      h1,h2,h3{font-family:'Sora','Inter',sans-serif;line-height:1.15;letter-spacing:-.02em}
      .btn{display:inline-flex;align-items:center;gap:8px;font-weight:700;font-size:15px;padding:13px 22px;border-radius:12px;border:1px solid transparent;cursor:pointer;transition:.15s}
      .btn-primary{background:linear-gradient(135deg,var(--brand),var(--accent));color:#fff;box-shadow:0 8px 30px rgba(109,94,252,.35)}
      .btn-primary:hover{transform:translateY(-1px);box-shadow:0 12px 36px rgba(109,94,252,.45)}
      .btn-ghost{border-color:var(--line);color:var(--text)}
      .btn-ghost:hover{background:rgba(255,255,255,.05)}

      /* Nav */
      nav{position:sticky;top:0;z-index:50;backdrop-filter:blur(12px);background:rgba(11,16,32,.7);border-bottom:1px solid var(--line)}
      .nav{display:flex;align-items:center;justify-content:space-between;height:66px}
      .logo{display:flex;align-items:center;gap:10px;font-family:'Sora';font-weight:800;font-size:19px}
      .logo-mark{width:30px;height:30px;border-radius:9px;background:linear-gradient(135deg,var(--brand),var(--brand2));display:grid;place-items:center;color:#fff;font-weight:900}
      .nav-links{display:flex;align-items:center;gap:28px}
      .nav-links a{color:var(--muted);font-weight:600;font-size:14px}
      .nav-links a:hover{color:var(--text)}
      @media(max-width:760px){.nav-links .hide-sm{display:none}}

      /* Hero */
      .hero{position:relative;padding:96px 0 72px;text-align:center;overflow:hidden}
      .hero::before{content:"";position:absolute;top:-30%;left:50%;transform:translateX(-50%);width:900px;height:700px;background:radial-gradient(closest-side,rgba(109,94,252,.28),transparent);filter:blur(20px);z-index:0}
      .hero>*{position:relative;z-index:1}
      .pill{display:inline-block;font-size:13px;font-weight:600;color:var(--brand2);border:1px solid var(--line);background:rgba(34,211,238,.08);padding:6px 14px;border-radius:999px;margin-bottom:22px}
      .hero h1{font-size:clamp(34px,6vw,60px);font-weight:800;max-width:900px;margin:0 auto 20px}
      .hero h1 em{font-style:normal;background:linear-gradient(135deg,var(--brand2),var(--accent));-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent}
      .hero p{font-size:clamp(16px,2.2vw,20px);color:var(--muted);max-width:640px;margin:0 auto 34px}
      .hero-cta{display:flex;gap:14px;justify-content:center;flex-wrap:wrap}
      .hero-sub{margin-top:18px;font-size:13px;color:var(--muted)}

      /* Features */
      .section{padding:72px 0}
      .section-head{text-align:center;max-width:660px;margin:0 auto 48px}
      .section-head h2{font-size:clamp(26px,4vw,38px);font-weight:800;margin-bottom:14px}
      .section-head p{color:var(--muted);font-size:17px}
      .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:18px}
      .card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:26px;transition:.15s}
      .card:hover{border-color:rgba(109,94,252,.5);transform:translateY(-3px)}
      .card .ic{font-size:26px;margin-bottom:14px;display:block}
      .card h3{font-size:17px;font-weight:700;margin-bottom:8px}
      .card p{color:var(--muted);font-size:14.5px}

      /* Split highlight */
      .split{display:grid;grid-template-columns:1.1fr 1fr;gap:44px;align-items:center}
      @media(max-width:820px){.split{grid-template-columns:1fr}}
      .split h2{font-size:clamp(24px,4vw,34px);font-weight:800;margin-bottom:16px}
      .split ul{list-style:none;margin-top:18px;display:flex;flex-direction:column;gap:12px}
      .split li{display:flex;gap:10px;color:var(--muted);font-size:15px}
      .split li b{color:var(--text)}
      .check{color:var(--brand2);font-weight:900;flex-shrink:0}
      .panel{background:linear-gradient(160deg,var(--bg2),var(--card));border:1px solid var(--line);border-radius:20px;padding:28px;min-height:280px;display:grid;place-items:center;color:var(--muted);text-align:center}
      .stat-row{display:flex;gap:26px;justify-content:center;flex-wrap:wrap;margin-top:8px}
      .stat b{font-family:'Sora';font-size:30px;font-weight:800;color:var(--text);display:block}
      .stat span{font-size:13px;color:var(--muted)}

      /* CTA */
      .cta{margin:40px 0 80px}
      .cta-box{background:linear-gradient(135deg,rgba(109,94,252,.18),rgba(34,211,238,.12));border:1px solid var(--line);border-radius:24px;padding:56px 32px;text-align:center}
      .cta-box h2{font-size:clamp(26px,4vw,36px);font-weight:800;margin-bottom:14px}
      .cta-box p{color:var(--muted);margin-bottom:28px;font-size:17px}

      footer{border-top:1px solid var(--line);padding:34px 0;color:var(--muted);font-size:13px}
      .foot{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px}
    </style>
  </head>
  <body>
    <nav>
      <div class="wrap nav">
        <div class="logo"><span class="logo-mark">N</span> Studio&nbsp;Nexis</div>
        <div class="nav-links">
          <a href="#features" class="hide-sm">Features</a>
          <a href="#platform" class="hide-sm">Platform</a>
          <a href="#pricing" class="hide-sm">Pricing</a>
          <a href="/login">Log in</a>
          <a href="#pricing" class="btn btn-primary" style="padding:9px 16px;font-size:14px;">Start free trial</a>
        </div>
      </div>
    </nav>

    <header class="hero">
      <div class="wrap">
        <span class="pill">✦ All-in-one studio management</span>
        <h1>Run your entire <em>pilates &amp; yoga</em> studio from one platform.</h1>
        <p>{tagline} Booking, CRM, packages, payments, finance, payroll, and analytics — finally in one place, built for the way studios actually work.</p>
        <div class="hero-cta">
          <a href="#pricing" class="btn btn-primary">Start your free trial →</a>
          <a href="#features" class="btn btn-ghost">See what's inside</a>
        </div>
        <div class="hero-sub">No credit card required · Your studio live in minutes</div>
      </div>
    </header>

    <section class="section" id="features">
      <div class="wrap">
        <div class="section-head">
          <h2>Everything your studio needs, nothing it doesn't</h2>
          <p>One login for your whole operation — from the front desk to the books.</p>
        </div>
        <div class="grid">
          {features.map((f) => (
            <div class="card">
              <span class="ic">{f.icon}</span>
              <h3 set:html={f.title}></h3>
              <p set:html={f.body}></p>
            </div>
          ))}
        </div>
      </div>
    </section>

    <section class="section" id="platform" style="background:var(--bg2);border-block:1px solid var(--line);">
      <div class="wrap split">
        <div>
          <h2>One system instead of five subscriptions</h2>
          <p style="color:var(--muted);font-size:16px;">Stop stitching together a booking app, a spreadsheet, a POS, and a payroll tool. Studio Nexis replaces the lot — so your data is connected and your team stops double-entering everything.</p>
          <ul>
            <li><span class="check">✓</span><span><b>Real-time credits</b> — a class booked is a credit deducted, instantly.</span></li>
            <li><span class="check">✓</span><span><b>Commission that's correct</b> — flat, per-head, tiered or revenue-split, computed automatically.</span></li>
            <li><span class="check">✓</span><span><b>Revenue you can trust</b> — cash-basis, fees excluded, per-class economics.</span></li>
            <li><span class="check">✓</span><span><b>Your studio, your brand</b> — your own subdomain and booking site.</span></li>
          </ul>
        </div>
        <div class="panel">
          <div>
            <div class="stat-row">
              <div class="stat"><b>1</b><span>login for everything</span></div>
              <div class="stat"><b>8+</b><span>tools replaced</span></div>
              <div class="stat"><b>∞</b><span>spreadsheets retired</span></div>
            </div>
            <p style="margin-top:22px;font-size:14px;">Booking · CRM · Packages · POS · Finance · Payroll · Notifications · Analytics</p>
          </div>
        </div>
      </div>
    </section>

    <section class="section cta" id="pricing">
      <div class="wrap">
        <div class="cta-box">
          <h2>Ready to run your studio the easy way?</h2>
          <p>Start a free trial and have your studio live on Studio Nexis today.</p>
          <div class="hero-cta">
            <a href="#" class="btn btn-primary">Start free trial →</a>
            <a href="#" class="btn btn-ghost">Book a demo</a>
          </div>
        </div>
      </div>
    </section>

    <footer>
      <div class="wrap foot">
        <div class="logo" style="font-size:16px;"><span class="logo-mark" style="width:24px;height:24px;font-size:13px;">N</span> Studio Nexis</div>
        <div>© {new Date().getFullYear()} Studio Nexis · All-in-one studio management</div>
      </div>
    </footer>
  </body>
</html>

