  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover" />
    <title>Studio Nexis — Run your pilates & yoga studio, all in one place</title>
    <meta name="description" content="Studio Nexis is the all-in-one platform for pilates & yoga studios: booking, CRM, packages, payments, finance, payroll and analytics — one login for your whole operation." />
    <link rel="icon" href="/favicon.svg" type="image/svg+xml" />
    <meta property="og:type" content="website" />
    <meta property="og:title" content="Studio Nexis — All-in-one studio management" />
    <meta property="og:description" content="Booking, CRM, finance, payroll & analytics for pilates and yoga studios — in one platform." />
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Manrope:wght@600;700;800&display=swap" rel="stylesheet" />
    <style>
      :root{
        --ink:#0d1220; --ink2:#232a3d; --muted:#616a80; --line:#e8eaf2; --line2:#eef0f6;
        --bg:#ffffff; --bg2:#f7f8fc; --brand:#5b45e0; --brand2:#8b5cf6; --brandink:#4a37c9;
        --mint:#0fb6a6; --shadow:0 1px 2px rgba(16,24,40,.04),0 12px 32px rgba(16,24,40,.06);
      }
      *{box-sizing:border-box;margin:0;padding:0}
      html{scroll-behavior:smooth}
      body{font-family:'Inter',system-ui,sans-serif;color:var(--ink);background:var(--bg);line-height:1.6;-webkit-font-smoothing:antialiased}
      a{color:inherit;text-decoration:none}
      .wrap{max-width:1160px;margin:0 auto;padding:0 24px}
      h1,h2,h3,.disp{font-family:'Manrope','Inter',sans-serif;letter-spacing:-.025em;line-height:1.1}
      .eyebrow{font-size:13px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--brand)}
      .btn{display:inline-flex;align-items:center;gap:8px;font-weight:600;font-size:15px;padding:12px 20px;border-radius:11px;border:1px solid transparent;cursor:pointer;transition:.15s;white-space:nowrap}
      .btn-primary{background:linear-gradient(135deg,var(--brand),var(--brand2));color:#fff;box-shadow:0 6px 18px rgba(91,69,224,.28)}
      .btn-primary:hover{transform:translateY(-1px);box-shadow:0 10px 26px rgba(91,69,224,.38)}
      .btn-ghost{border-color:var(--line);color:var(--ink);background:#fff}
      .btn-ghost:hover{border-color:#cfd3e6;background:var(--bg2)}
      .ic{width:22px;height:22px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}

      nav{position:sticky;top:0;z-index:50;background:rgba(255,255,255,.82);backdrop-filter:blur(12px);border-bottom:1px solid var(--line2)}
      .nav{display:flex;align-items:center;justify-content:space-between;height:68px}
      .logo{display:flex;align-items:center;gap:10px;font-family:'Manrope';font-weight:800;font-size:19px;letter-spacing:-.02em}
      .logo-mark{width:32px;height:32px;border-radius:9px;background:linear-gradient(135deg,var(--brand),var(--brand2));display:grid;place-items:center;color:#fff;font-weight:800;font-family:'Manrope'}
      .nav-links{display:flex;align-items:center;gap:26px}
      .nav-links a{color:var(--muted);font-weight:600;font-size:14.5px}
