---
// Studio Nexis — self-serve signup. Provisions a trial studio via
// POST /api/saas/signup (same-origin, control-plane host).
---
<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover" />
    <title>Start your free trial — Studio Nexis</title>
    <meta name="robots" content="noindex" />
    <link rel="icon" href="/favicon.svg" type="image/svg+xml" />
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Manrope:wght@700;800&display=swap" rel="stylesheet" />
    <style>
      :root{--ink:#0d1220;--muted:#616a80;--line:#e2e5f0;--bg2:#f7f8fc;--brand:#5b45e0;--brand2:#8b5cf6;--mint:#0fb6a6;--danger:#e5484d}
      *{box-sizing:border-box;margin:0;padding:0}
      body{font-family:'Inter',system-ui,sans-serif;color:var(--ink);background:linear-gradient(180deg,#fff,#f4f5fb);min-height:100vh;-webkit-font-smoothing:antialiased}
      a{color:var(--brand);text-decoration:none}
      h1,.disp{font-family:'Manrope',sans-serif;letter-spacing:-.025em}
      .logo{display:flex;align-items:center;gap:10px;font-family:'Manrope';font-weight:800;font-size:19px}
      .logo-mark{width:31px;height:31px;border-radius:9px;background:linear-gradient(135deg,var(--brand),var(--brand2));display:grid;place-items:center;color:#fff;font-weight:800}
      .top{max-width:1000px;margin:0 auto;padding:22px 24px}
      .shell{max-width:460px;margin:14px auto 60px;padding:0 24px}
      .card{background:#fff;border:1px solid var(--line);border-radius:20px;padding:34px;box-shadow:0 12px 40px rgba(16,24,40,.08)}
      h1{font-size:27px;font-weight:800;margin-bottom:6px}
      .sub{color:var(--muted);font-size:15px;margin-bottom:24px}
      label{display:block;font-size:13px;font-weight:600;margin:14px 0 6px}
      input{width:100%;padding:12px 13px;border:1px solid var(--line);border-radius:11px;font-size:15px;font-family:inherit;transition:.12s}
      input:focus{outline:none;border-color:var(--brand);box-shadow:0 0 0 3px rgba(91,69,224,.14)}
      .sub-domain{display:flex;align-items:stretch;border:1px solid var(--line);border-radius:11px;overflow:hidden}
      .sub-domain:focus-within{border-color:var(--brand);box-shadow:0 0 0 3px rgba(91,69,224,.14)}
      .sub-domain input{border:none;border-radius:0;box-shadow:none}
      .sub-domain input:focus{box-shadow:none}
      .sub-domain .suffix{display:flex;align-items:center;padding:0 12px;background:var(--bg2);color:var(--muted);font-size:13px;border-left:1px solid var(--line);white-space:nowrap}
      .btn{width:100%;margin-top:22px;padding:13px;border:none;border-radius:11px;background:linear-gradient(135deg,var(--brand),var(--brand2));color:#fff;font-weight:700;font-size:15px;cursor:pointer;transition:.15s}
      .btn:hover{transform:translateY(-1px);box-shadow:0 8px 22px rgba(91,69,224,.32)}
      .btn:disabled{opacity:.6;cursor:not-allowed;transform:none}
      .msg{margin-top:16px;padding:12px 14px;border-radius:11px;font-size:14px;display:none}
      .msg.err{display:block;background:#fdeceb;color:var(--danger);border:1px solid #f6c9c7}
      .foot-note{text-align:center;font-size:13px;color:var(--muted);margin-top:18px}
      /* success */
      .done{display:none;text-align:center}
      .done.show{display:block}
      .done .tick{width:58px;height:58px;border-radius:50%;background:#e6f7f4;color:var(--mint);display:grid;place-items:center;margin:0 auto 18px}
      .done h1{margin-bottom:8px}
      .url-box{margin:20px 0 8px;padding:14px;border:1px dashed var(--line);border-radius:12px;background:var(--bg2);font-weight:600;word-break:break-all}
    </style>
  </head>
  <body>
    <div class="top"><a href="/" class="logo"><span class="logo-mark">N</span>Studio&nbsp;Nexis</a></div>
    <div class="shell">
      <div class="card">
        <!-- Form -->
        <form id="signupForm">
          <h1>Start your free trial</h1>
          <p class="sub">Your studio, live on Studio Nexis in about a minute.</p>

          <label for="studioName">Studio name</label>
          <input id="studioName" type="text" placeholder="e.g. Lotus Pilates" required autocomplete="organization" />

          <label for="slug">Your address</label>
          <div class="sub-domain">
            <input id="slug" type="text" placeholder="lotus-pilates" pattern="[a-z0-9-]+" required autocomplete="off" />
            <span class="suffix">.studionexis.soulpilates.com.vn</span>
          </div>

          <label for="email">Admin email</label>
          <input id="email" type="email" placeholder="you@studio.com" required autocomplete="email" />

          <label for="password">Password</label>
          <input id="password" type="password" placeholder="At least 8 characters" minlength="8" required autocomplete="new-password" />

          <button class="btn" type="submit" id="submitBtn">Create my studio →</button>
          <div class="msg err" id="err"></div>
          <p class="foot-note">Already have a studio? <a href="/login">Log in</a></p>
        </form>

        <!-- Success -->
        <div class="done" id="done">
          <div class="tick"><svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg></div>
          <h1>Your studio is ready! 🎉</h1>
          <p class="sub">Log in with the email and password you just chose.</p>
          <div class="url-box" id="doneUrl"></div>
          <a class="btn" id="goBtn" style="display:inline-block;text-align:center;text-decoration:none;box-sizing:border-box" href="#">Go to my studio →</a>
        </div>
      </div>
    </div>

    <script is:inline>
      (function () {
        const form = document.getElementById('signupForm');
        const nameEl = document.getElementById('studioName');
        const slugEl = document.getElementById('slug');
        const err = document.getElementById('err');
        const btn = document.getElementById('submitBtn');
        let slugEdited = false;

        const slugify = (s) => s.toLowerCase().trim()
          .replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').slice(0, 40);

        nameEl.addEventListener('input', () => { if (!slugEdited) slugEl.value = slugify(nameEl.value); });
        slugEl.addEventListener('input', () => { slugEdited = true; slugEl.value = slugEl.value.toLowerCase().replace(/[^a-z0-9-]/g, ''); });

        form.addEventListener('submit', async (e) => {
          e.preventDefault();
          err.style.display = 'none';
          btn.disabled = true; btn.textContent = 'Creating your studio…';
          try {
            const res = await fetch('/api/saas/signup', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                slug: slugEl.value.trim(),
                displayName: nameEl.value.trim(),
                adminEmail: document.getElementById('email').value.trim(),
                adminPassword: document.getElementById('password').value,
              }),
            });
            const data = await res.json().catch(() => ({}));
            if (!res.ok) throw new Error(data.message || 'Could not create your studio. Try a different address.');
            document.getElementById('signupForm').style.display = 'none';
            const done = document.getElementById('done');
            document.getElementById('doneUrl').textContent = data.url;
            document.getElementById('goBtn').href = data.url + '/login';
            done.classList.add('show');
          } catch (ex) {
            err.textContent = ex.message; err.style.display = 'block';
            btn.disabled = false; btn.textContent = 'Create my studio →';
          }
        });
      })();
    </script>
  </body>
</html>

