    /// <summary>ACTIVE | SUSPENDED. Suspended tenants are refused at resolution time.</summary>
    public string Status { get; set; } = "ACTIVE";

    /// <summary>Licensing plan tier, e.g. TRIAL | STARTER | PRO.</summary>
    public string Plan { get; set; } = "TRIAL";

    /// <summary>Optional custom domain mapped to this tenant (future).</summary>
