  try {
    var payload = JSON.parse(atob(token.split(".")[1]));
    var role = (
      payload[
        "http://schemas.microsoft.com/ws/2008/06/identity/claims/role"
      ] ||
      payload.role ||
      ""
    ).toLowerCase();
    window.location.href =
      role === "instructor" ? "/instructor" : "/admin";
