})();

async function doLogin(ev) {
  if (ev) ev.preventDefault();
  // Lowercase as well as trim: iOS Safari autofill can populate the
  // email with different casing, and the account lookup is by lowercased
  // email — without this, a capitalised autofill fails as "invalid password".
  const email = document.getElementById("email").value.trim().toLowerCase();
  const password = document.getElementById("password").value;
  const errEl = document.getElementById("errorMsg");
  const btn = document.getElementById("loginBtn");
  const lbl = document.getElementById("btnLabel");
  errEl.style.display = "none";
  lbl.textContent = "Signing in…";
  btn.disabled = true;

  function fail(msg) {
    errEl.textContent = msg;
    errEl.style.display = "block";
    lbl.textContent = "Sign in";
    btn.disabled = false;
  }

  let data;
  try {
    const res = await fetch(
      import.meta.env.PUBLIC_API_URL + "/api/auth/login",
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      },
    );
    // Only a real auth rejection means bad credentials. Other statuses
    // are server/network problems and must not read as "wrong password".
    if (res.status === 401 || res.status === 400) {
      fail("Invalid email or password. Please try again.");
      return;
    }
    if (!res.ok) {
      fail("Sign-in is temporarily unavailable. Please try again in a moment.");
      return;
    }
    data = await res.json();
  } catch {
    fail("Couldn't reach the server. Check your connection and try again.");
    return;
  }

  // Storage can throw on iOS Safari Private Browsing / strict tracking
  // prevention. The login itself SUCCEEDED here — never show a password
  // error for a storage failure.
  try {
    localStorage.setItem("token", data.token);
    if (data.staffId) localStorage.setItem("staffId", data.staffId);
  } catch {
    fail("Signed in, but this browser is blocking storage. If you're using Private Browsing, turn it off for this site and try again.");
    return;
  }

  // Force password change before reaching the dashboard.
  if (data.mustChangePassword) {
    window.location.href = "/admin/change-password";
    return;
  }
  // P3-S09: role-aware post-login redirect.
  // Instructor → instructor portal; Admin, Receptionist, Accountant → admin dashboard
  const role = (data.userRole || "").toLowerCase();
  window.location.href =
    role === "instructor" ? "/instructor" : "/admin";
}

// Wire submit handler — required because Astro bundles this <script> as
// an ES module, so `doLogin` is module-scoped and not accessible from an
// inline `onsubmit=` attribute on the form.

