using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Services;

namespace SoulPilates.API.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize(Roles = "Admin")]
public class SettingsController : ControllerBase
{
    private readonly ISettingsService _settingsService;

    // Refactored in P1-S04: was directly injecting MongoDbContext, which violated
    // the controller-uses-service layer rule. The seed/backfill semantics now live
    // in SettingsService where domain rules belong.
    public SettingsController(ISettingsService settingsService)
    {
        _settingsService = settingsService;
    }

    [HttpGet]
    public async Task<IActionResult> GetSettings(CancellationToken ct)
    {
        var settings = await _settingsService.GetAsync(ct);

        // Sanitise — encrypted Stripe key fields must NEVER reach the frontend.
        // Null them out so they aren't serialised, then inject masked placeholders
        // as separate ad-hoc properties.
        var stripeConfig = await _settingsService.GetDecryptedStripeConfigAsync(ct);

        // Wipe encrypted blobs from the outbound entity — these are binary noise
        // to the frontend and must never leave the server.
        settings.StripePublishableKeyEncrypted = null;
        settings.StripeSecretKeyEncrypted = null;
        settings.StripeWebhookSecretEncrypted = null;

        // Return the full settings entity + masked display helpers.

