/// <summary>
/// SaaS onboarding: mark the first-run setup wizard complete so the admin
/// portal stops redirecting to it. Reads current settings and flips the flag
/// (defaults are valid, so this passes the full-settings validation).
/// </summary>
[HttpPost("complete-setup")]
public async Task<IActionResult> CompleteSetup(CancellationToken ct)
{
    var s = await _settingsService.GetAsync(ct);
    s.SetupCompleted = true;
    var saved = await _settingsService.UpdateAsync(s, ct);
    return Ok(new { setupCompleted = saved.SetupCompleted });
}

