// Studio Nexis — first-run setup wizard. Shown to a studio owner on their first
// admin login (AdminLayout redirects here until SetupCompleted). Standalone page.
const API = import.meta.env.PUBLIC_API_URL;
---
<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover" />
    <title>Set up your studio — Studio Nexis</title>
    <meta name="robots" content="noindex" />
    <link rel="icon" href="/favicon.svg" type="image/svg+xml" />
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Manrope:wght@700;800&display=swap" rel="stylesheet" />
    <style>
      :root{--ink:#0d1220;--muted:#616a80;--line:#e2e5f0;--bg2:#f7f8fc;--brand:#5b45e0;--brand2:#8b5cf6;--mint:#0fb6a6}
      *{box-sizing:border-box;margin:0;padding:0}
      body{font-family:'Inter',system-ui,sans-serif;color:var(--ink);background:linear-gradient(180deg,#fff,#f4f5fb);min-height:100vh;-webkit-font-smoothing:antialiased}
      a{color:var(--brand);text-decoration:none}
      h1,h2,.disp{font-family:'Manrope',sans-serif;letter-spacing:-.02em}
      .top{max-width:1000px;margin:0 auto;padding:22px 24px;display:flex;align-items:center;justify-content:space-between}
      .logo{display:flex;align-items:center;gap:10px;font-family:'Manrope';font-weight:800;font-size:19px}
      .logo-mark{width:31px;height:31px;border-radius:9px;background:linear-gradient(135deg,var(--brand),var(--brand2));display:grid;place-items:center;color:#fff;font-weight:800}
      .skip{font-size:13.5px;color:var(--muted);font-weight:600}
      .shell{max-width:600px;margin:10px auto 60px;padding:0 24px}
      .card{background:#fff;border:1px solid var(--line);border-radius:22px;padding:38px;box-shadow:0 14px 44px rgba(16,24,40,.08)}
      .steps-dots{display:flex;gap:8px;margin-bottom:26px}
      .dot{height:5px;flex:1;border-radius:3px;background:var(--line);transition:.2s}
