mposSetAttending(val) {
  const m = this._mpos; if (!m) return;
  let n = parseInt(val, 10);
  if (!Number.isFinite(n)) n = m.bookedSeats;
  n = Math.max(1, Math.min(m.bookedSeats, n));
  m.attendingSeats = n;
  m.dropInPrice = m.perSeat * n;   // drop-in charge = per-seat × attending
  const ai = document.getElementById('mposAttending');
  if (ai && String(ai.value) !== String(n)) ai.value = String(n);
  this._mposRenderCart();          // re-renders credit/drop-in lines + recalcs totals
},
mposRemoveLine(i) { this._mpos.lines.splice(i, 1); this._mposRenderCart(); },

