<script is:inline>
  (function () {
    const input = document.getElementById('clientSearchInput');
    const box = document.getElementById('clientSearchResults');
    const wrap = document.getElementById('clientQuickSearch');
    if (!input || !box) return;
    const apiEl = document.querySelector('[data-api-base]');
    const API = apiEl && apiEl.dataset ? (apiEl.dataset.apiBase || '') : '';
    const tok = () => localStorage.getItem('token') || '';
    const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
    const colors = ['#c8a45d','#4a90d9','#5cb85c','#d9534f','#8e5bd9','#d98c3f'];
    let timer = null, lastQ = '';

    function close() { box.classList.remove('open'); box.innerHTML = ''; }
    function creds(c) {
      const p = [];
      if (c.groupCredits > 0) p.push(c.groupCredits + ' Grp');
      if (c.matCredits > 0) p.push(c.matCredits + ' Mat');
      if (c.privateCredits > 0) p.push(c.privateCredits + ' Pvt');
      return p.join(' · ');
    }
    function render(list, q) {
      if (!list.length) { box.innerHTML = '<div class="cqs-empty">No clients found</div>'; box.classList.add('open'); return; }
      let html = list.slice(0, 4).map((c, i) => {
        const initials = (c.name || '?').split(' ').map(w => w[0]).join('').substring(0, 2).toUpperCase();
        const phone = [c.phoneCountryCode, c.phone].filter(Boolean).join(' ');
        const sub = [phone, c.email].filter(Boolean).join(' · ');
        const cr = creds(c);
        return '<a class="cqs-item" href="/admin/client-profile?id=' + encodeURIComponent(c.id) + '">'
          + '<span class="cqs-av" style="background:' + colors[i % colors.length] + '">' + esc(initials) + '</span>'
          + '<span class="cqs-info"><span class="cqs-name">' + esc(c.name) + '</span><span class="cqs-sub">' + (esc(sub) || '—') + '</span></span>'
          + (cr ? '<span class="cqs-cred">🎟 ' + esc(cr) + '</span>' : '')
          + '</a>';
      }).join('');
      if (list.length > 4) html += '<a class="cqs-more" href="/admin/clients?search=' + encodeURIComponent(q) + '">View all ' + list.length + ' results →</a>';
      box.innerHTML = html;
      box.classList.add('open');
    }
    async function run(q) {
      try {
        const res = await fetch(API + '/api/client?search=' + encodeURIComponent(q), { headers: { Authorization: 'Bearer ' + tok() } });
        if (!res.ok) { close(); return; }
        const list = await res.json();
        if (q !== lastQ) return;
        render(Array.isArray(list) ? list : [], q);
      } catch (e) { close(); }
    }
    input.addEventListener('input', function () {
      const q = input.value.trim();
      lastQ = q;
      if (timer) clearTimeout(timer);
      if (q.length < 2) { close(); return; }
      timer = setTimeout(function () { run(q); }, 250);
    });
    input.addEventListener('focus', function () { if (input.value.trim().length >= 2 && box.innerHTML) box.classList.add('open'); });
    document.addEventListener('click', function (e) { if (wrap && !wrap.contains(e.target)) close(); });
    document.addEventListener('keydown', function (e) { if (e.key === 'Escape') { close(); input.blur(); } });
  })();
</script>
