          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M1 4h22M4 4v16M20 4v16M4 12h16M8 12v8M16 12v8"/></svg>
        </div>
        <div>
          <span class="modal-title">Checkout</span>
          <div id="mposClient" class="mpos-sub"></div>
        </div>
      </div>
      <button class="modal-close" onclick="ClassDetailPanel.closeCollectModal()">
        <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
      </button>
    </div>
    <div class="modal-body">
      <!-- Package-credit / drop-in status banner -->
      <div id="mposCredits" class="mpos-banner" style="display:none;"></div>

      <!-- Booking summary -->
      <div class="mpos-sec">Booking summary</div>
      <div class="mpos-card">
        <div id="mposCart"></div>

        <!-- Partial attendance: only charge who actually showed up -->
        <div id="mposAttendRow" class="mpos-attend" style="display:none;">
          <div class="mpos-attend-main">
            <div class="mpos-attend-t">How many people are attending?</div>
            <div class="mpos-attend-d">Charge only the attendees<span id="mposAttendOf"></span></div>
          </div>
          <div class="mpos-stepper">
            <button type="button" onclick="ClassDetailPanel.mposStepAttending(-1)" aria-label="Fewer">−</button>
            <input id="mposAttending" type="number" min="1" step="1" oninput="ClassDetailPanel.mposSetAttending(this.value)" />
            <button type="button" onclick="ClassDetailPanel.mposStepAttending(1)" aria-label="More">+</button>
          </div>
