      <div class="mpos-sec">Add-ons</div>
      <div class="mpos-card mpos-addons">
        <button class="btn btn-secondary btn-sm" onclick="ClassDetailPanel.mposToggleAdd('merch')">🛍 Merchandise</button>
        <button class="btn btn-secondary btn-sm" onclick="ClassDetailPanel.mposToggleAdd('package')">🎁 Package</button>
      </div>
      <div id="mposPicker" style="display:none;max-height:150px;overflow-y:auto;border:1px solid var(--color-border-subtle);border-radius:12px;padding:6px;margin:-8px 0 18px;"></div>

      <!-- Discount + promo -->
      <div class="mpos-grid2">
        <div class="form-group" style="margin:0;">
          <label class="form-label" style="font-size:11px;">Discount</label>
          <div style="display:flex;gap:4px;">
            <input type="number" class="form-control" id="mposDiscAmt" min="0" value="0" style="font-size:12px;" oninput="ClassDetailPanel.mposRecalc()" />
            <select class="form-control" id="mposDiscType" style="width:auto;font-size:12px;" onchange="ClassDetailPanel.mposRecalc()">
              <option value="FIXED">₫</option>
              <option value="PCT">%</option>
            </select>
          </div>
        </div>
        <div class="form-group" style="margin:0;">
          <label class="form-label" style="font-size:11px;">Promo code</label>
          <div style="display:flex;gap:4px;">
            <input type="text" class="form-control" id="mposPromo" placeholder="Enter code" style="font-size:12px;text-transform:uppercase;" />
            <button class="btn btn-secondary btn-sm" onclick="ClassDetailPanel.mposApplyPromo()">Apply</button>
          </div>
          <div id="mposPromoHint" style="font-size:10px;margin-top:3px;"></div>
        </div>
      </div>

      <!-- Order total -->
      <div class="mpos-sec">Order total</div>
      <div class="mpos-card mpos-totals">
        <div class="mpos-trow"><span>Subtotal</span><span id="mposSubtotal">0 ₫</span></div>
        <div id="mposDiscLine" class="mpos-trow" style="display:none;color:var(--color-success);"><span>Discount</span><span id="mposDiscVal">0 ₫</span></div>
        <div class="mpos-trow grand"><span>Total</span><span id="mposTotal">0 ₫</span></div>
      </div>

      <div class="form-group" id="mposPayRow">
        <label class="form-label" style="font-size:11px;">Payment method</label>
        <select class="form-control" id="cdpCpMethod">
          <option value="CASH">Cash</option>
          <option value="BANK_TRANSFER">Bank Transfer</option>
          <option value="MOMO">MoMo</option>
          <option value="ZALO_PAY">ZaloPay</option>
          <option value="CREDIT_CARD">Credit Card</option>
          <option value="WISE">Wise</option>
          <option value="STRIPE">Stripe</option>
        </select>
      </div>

      <div class="form-group" style="margin-top:14px;">
        <label class="form-label" style="font-size:11px;">Note / reason <span id="mposNoteReq" style="color:var(--color-danger);display:none;">(required — amount differs from the standard price)</span></label>
        <textarea class="form-control" id="mposNote" rows="2" placeholder="e.g. covering a second walk-in, agreed discount, etc." style="font-size:12px;"></textarea>
      </div>
      <input type="hidden" id="cdpCpAttendanceId" />
    </div>
    <div class="modal-footer">
      <button class="btn btn-secondary" onclick="ClassDetailPanel.closeCollectModal()">Cancel</button>
      <button class="btn btn-primary" id="mposCompleteBtn" onclick="ClassDetailPanel.mposComplete()">✅ Complete &amp; check in</button>
    </div>
  </div>
</div>

