{
    // Look up invoice for monetary-payment attendees
    var linkedInv = await _invoices.Find(
        Builders<Invoice>.Filter.ElemMatch(
            i => i.Lines,
            Builders<InvoiceLine>.Filter.Eq(l => l.AttendanceId, att.Id)
        )
    ).FirstOrDefaultAsync();

    // The "VAT (online only)" surcharge is a pass-through fee,
    // never commissionable. It lives on Invoice.OnlineFeeAmount
    // (outside the lines), so the per-line total is already
    // fee-free; the whole-invoice / AmountPaid fallbacks must
    // strip this attendee's apportioned share of it.
    decimal onlineFeeShare = 0m;
    if (linkedInv is not null && linkedInv.OnlineFeeAmount > 0m)
    {
        var lineSub = linkedInv.Lines.Sum(l => l.UnitPrice * l.Quantity - l.LineDiscount);
        var myLine = linkedInv.Lines.FirstOrDefault(l => l.AttendanceId == att.Id);
        var myLineTotal = myLine is not null ? (myLine.UnitPrice * myLine.Quantity - myLine.LineDiscount) : 0m;
        onlineFeeShare = (lineSub > 0m && myLineTotal > 0m)
            ? linkedInv.OnlineFeeAmount * (myLineTotal / lineSub)
            : linkedInv.OnlineFeeAmount;
    }

    var paidResolved = false;
    if (linkedInv is not null && linkedInv.Status == "PAID")
    {
        var line = linkedInv.Lines.FirstOrDefault(l => l.AttendanceId == att.Id);
        if (line is not null)
        {
            var lineTotal = line.UnitPrice * line.Quantity - line.LineDiscount;
            if (lineTotal > 0m) { revBase = lineTotal; paidResolved = true; }
        }
        else
        {
            var netExFee = linkedInv.TotalNet - linkedInv.OnlineFeeAmount;
