namespace SoulPilates.Core.Entities;

/// <summary>
/// A tenant studio's public website configuration. One document per tenant DB.
/// Drives the studio's landing page rendered at its subdomain root — the studio
/// picks a template, chooses theme colours, and fills in the editable content.
/// </summary>
public class SiteSettings : BaseEntity
{
    /// <summary>Chosen template: boutique | luxury | minimal | modern | wellness.</summary>
    public string Template { get; set; } = "boutique";

    // ── Theme colours ──
    public string PrimaryColor { get; set; } = "#C97B4B";
    public string AccentColor { get; set; } = "#2BB7A3";

    // ── Header / hero ──
    public string StudioName { get; set; } = "Your Studio";
    public string Slogan { get; set; } = "Move well. Feel better.";
    public string HeroText { get; set; } = "A boutique studio for mindful movement.";
    public string? LogoUrl { get; set; }
    public string? HeaderImageUrl { get; set; }

    // ── About / body ──
    public string AboutTitle { get; set; } = "Welcome to the studio";
    public string AboutText { get; set; } = "Tell your story here — who you are, what you offer, and why clients love training with you.";

    // ── Contact (footer) ──
    public string? ContactAddress { get; set; }
    public string? ContactPhone { get; set; }
    public string? ContactEmail { get; set; }
    public string? ContactHours { get; set; }

    /// <summary>A Google Maps share link — used for the embedded map + "Get directions".</summary>
    public string? MapsLink { get; set; }

    // ── Call to action ──
    public string CtaLabel { get; set; } = "Book a class";
    /// <summary>Where the Book CTA points — defaults to the studio's own booking page.</summary>
    public string BookingUrl { get; set; } = "/booking";

    /// <summary>When false the site shows a "coming soon" placeholder to the public.</summary>
    public bool Published { get; set; } = false;
}

