/// <summary>
/// Instructor blocks / unblocks one of their OWN classes from the PWA. Flips
/// the session Status to BLOCKED (hidden from the public booking page, refuses
/// reservations) and back, without deleting it — existing bookings are left
/// untouched. Ownership-checked; admins impersonating bypass.
/// </summary>
[HttpPatch("session/{id}/block-status")]
public async Task<IActionResult> SetMySessionBlockStatus(string id, [FromBody] InstructorBlockStatusRequest request)
{
    var staffId = ResolveStaffId();
    if (string.IsNullOrWhiteSpace(staffId))
        return NotFound(new { profileLinked = false });

    var session = await _schedulingService.GetSessionByIdAsync(id);
    if (session == null)
        return NotFound(new { message = "Session not found." });
    if (!IsAdminRole() && session.InstructorId != staffId)
        return StatusCode(403, new { message = "You can only manage your own classes." });

    var success = await _schedulingService.SetSessionBlockedAsync(id, request.Blocked);
    if (!success)
        return NotFound(new { message = "Session not found or already in the requested state." });
    return Ok(new { message = request.Blocked ? "Class blocked." : "Class unblocked." });
}

