public async Task<(int today, int week, int month)> GetClassCountsAsync(string? staffId)
{
    if (string.IsNullOrWhiteSpace(staffId)) return (0, 0, 0);

    var tz = TimeSpan.FromHours(7); // Asia/Ho_Chi_Minh, no DST
    var nowLocal = DateTime.UtcNow + tz;
    var todayLocal = nowLocal.Date;
    var mondayOffset = ((int)todayLocal.DayOfWeek + 6) % 7; // Mon = 0
    var weekLocal = todayLocal.AddDays(-mondayOffset);
    var monthLocal = new DateTime(nowLocal.Year, nowLocal.Month, 1);

    var baseFilter = Builders<CalendarSession>.Filter.And(
        Builders<CalendarSession>.Filter.Eq(s => s.InstructorId, staffId),
        Builders<CalendarSession>.Filter.Nin(s => s.Status, new[] { "BLOCKED", "CANCELLED" }));

    async Task<int> Count(DateTime startLocal, DateTime endLocal) =>
        (int)await _sessions.CountDocumentsAsync(Builders<CalendarSession>.Filter.And(baseFilter,
            Builders<CalendarSession>.Filter.Gte(s => s.StartTime, startLocal - tz),
            Builders<CalendarSession>.Filter.Lt(s => s.StartTime, endLocal - tz)));

    var today = await Count(todayLocal, todayLocal.AddDays(1));
    var week = await Count(weekLocal, weekLocal.AddDays(7));
    var month = await Count(monthLocal, monthLocal.AddMonths(1));
    return (today, week, month);
}

