public async Task<(int today, int week, int month)> GetClassCountsAsync(string? staffId)
{
    if (string.IsNullOrWhiteSpace(staffId)) return (0, 0, 0);

    var tz = TimeSpan.FromHours(7); // Asia/Ho_Chi_Minh, no DST
    var nowLocal = DateTime.UtcNow + tz;
    var todayLocal = nowLocal.Date;
    var mondayOffset = ((int)todayLocal.DayOfWeek + 6) % 7; // Mon = 0
    var weekLocal = todayLocal.AddDays(-mondayOffset);
    var monthLocal = new DateTime(nowLocal.Year, nowLocal.Month, 1);

    // A class only counts once it's actually been taught: COMPLETED with at
    // least one attendee who checked in. This excludes future/empty scheduled
    // sessions (the materialiser pre-creates the whole month) and mirrors the
    // commission class-count rule. Pull the instructor's completed classes for
    // the whole month, then bucket by day/week/month locally.
    var monthStartUtc = monthLocal - tz;
    var monthEndUtc = monthLocal.AddMonths(1) - tz;
    var completed = await _sessions.Find(Builders<CalendarSession>.Filter.And(
            Builders<CalendarSession>.Filter.Eq(s => s.InstructorId, staffId),
            Builders<CalendarSession>.Filter.Eq(s => s.Status, "COMPLETED"),
            Builders<CalendarSession>.Filter.Gte(s => s.StartTime, monthStartUtc),
            Builders<CalendarSession>.Filter.Lt(s => s.StartTime, monthEndUtc)))
        .Project(s => new { s.Id, s.StartTime })
        .ToListAsync();
    if (completed.Count == 0) return (0, 0, 0);

    var ids = completed.Select(c => c.Id).ToList();
    var arrivedCursor = await _attendances.DistinctAsync(a => a.CalendarSessionId,
        Builders<Attendance>.Filter.And(
            Builders<Attendance>.Filter.In(a => a.CalendarSessionId, ids),
            Builders<Attendance>.Filter.In(a => a.Status, new[] { "CHECKED_IN", "ARRIVED" })));
    var arrivedSet = (await arrivedCursor.ToListAsync())
        .Where(x => !string.IsNullOrEmpty(x)).ToHashSet();

    int CountIn(DateTime startLocal, DateTime endLocal)
    {
        var s = startLocal - tz; var e = endLocal - tz;
        return completed.Count(c => arrivedSet.Contains(c.Id) && c.StartTime >= s && c.StartTime < e);
    }

    return (CountIn(todayLocal, todayLocal.AddDays(1)),
            CountIn(weekLocal, weekLocal.AddDays(7)),
            CountIn(monthLocal, monthLocal.AddMonths(1)));
}

