// Per-day class calendar for the selected month.
async function loadClassDays(selYear, selMonth) {
  const token = localStorage.getItem("token");
  if (!token) return;
  const viewAsId = window.getViewAsStaffId?.() || null;
  const params = new URLSearchParams();
  if (selYear && selMonth) { params.set("year", selYear); params.set("month", selMonth); }
  if (viewAsId) params.set("viewAs", viewAsId);
  const qs = params.toString() ? "?" + params.toString() : "";
  try {
    const r = await fetch(API + "/api/instructor/class-days" + qs, {
      headers: { Authorization: "Bearer " + token },
    });
    if (!r.ok) return;
    renderClassDays(await r.json());
  } catch (e) { /* leave grid empty */ }
}

function renderClassDays(d) {
  const y = d.year, m = d.month; // m: 1-12
  const counts = d.counts || {};
  const label = document.getElementById("classDaysMonthLabel");
  const totalEl = document.getElementById("classDaysTotal");
  const grid = document.getElementById("classDaysGrid");
  if (label) label.textContent = new Date(y, m - 1, 1).toLocaleDateString("en-US", { month: "long", year: "numeric" });
  if (totalEl) totalEl.textContent = d.total ?? 0;
  if (!grid) return;

  const daysInMonth = new Date(y, m, 0).getDate();
  const firstDow = (new Date(y, m - 1, 1).getDay() + 6) % 7; // Mon = 0
  const values = Object.values(counts).map(Number);
  const maxCount = Math.max(1, ...(values.length ? values : [1]));
  const now = new Date(Date.now() + 7 * 3600 * 1000); // studio-local now
  const todayStr = now.toISOString().slice(0, 10);
  const pad = (n) => String(n).padStart(2, "0");

  let html = "";
  for (let i = 0; i < firstDow; i++) html += '<div class="cd-cell cd-empty"></div>';
  for (let day = 1; day <= daysInMonth; day++) {
    const c = Number(counts[String(day)] || 0);
    const level = c === 0 ? 0 : Math.min(4, Math.ceil((c / maxCount) * 4));
    const isToday = todayStr === `${y}-${pad(m)}-${pad(day)}`;
    html += `<div class="cd-cell cd-l${level}${isToday ? " cd-today" : ""}" title="${c} class${c === 1 ? "" : "es"}">
      <span class="cd-day">${day}</span>${c > 0 ? `<span class="cd-count">${c}</span>` : ""}</div>`;
  }
  grid.innerHTML = html;
}

async function loadEarnings(selYear, selMonth) {
  loadClassDays(selYear, selMonth);

