    public async Task<GlobalSettings> GetAsync(CancellationToken ct = default)
    {
        var existing = await _settings.Find(FilterDefinition<GlobalSettings>.Empty)
            .FirstOrDefaultAsync(ct);

        if (existing == null)
        {
            // First-time bootstrap: seed defaults so callers never see an empty list.
            existing = new GlobalSettings
            {
                ExpenseCategories = GlobalSettings.DefaultExpenseCategories.ToList(),
                RoleAccessSettings = BuildDefaultRoleAccessSettings(),
            };
            await _settings.InsertOneAsync(existing, cancellationToken: ct);
            return existing;
        }

        // Backfill an existing row whose ExpenseCategories has never been set
        // (e.g. a doc seeded before P1-S04 introduced the field).
        if (existing.ExpenseCategories == null || existing.ExpenseCategories.Count == 0)
        {
            existing.ExpenseCategories = GlobalSettings.DefaultExpenseCategories.ToList();
            existing.UpdatedAt = DateTime.UtcNow;
            await _settings.ReplaceOneAsync(s => s.Id == existing.Id, existing, cancellationToken: ct);
        }

        // P1-S13 backfill: cancel windows. A row created before this slice will
        // deserialise these as 0; treat 0 as "uninitialised" and stamp the defaults
        // so /api/customer/cancel-policy never returns a misleading "0h" answer.
        var needsCancelWindowBackfill = existing.CancelWindowHoursGroup <= 0 || existing.CancelWindowHoursPrivate <= 0;
        if (needsCancelWindowBackfill)
        {
            if (existing.CancelWindowHoursGroup <= 0) existing.CancelWindowHoursGroup = 12;
            if (existing.CancelWindowHoursPrivate <= 0) existing.CancelWindowHoursPrivate = 24;
            existing.UpdatedAt = DateTime.UtcNow;
            await _settings.ReplaceOneAsync(s => s.Id == existing.Id, existing, cancellationToken: ct);
        }

        // P2-S01 backfill: a row created before this slice will deserialise
        // OwnersSplitPercentage as 0. Treat 0 (specifically) as uninitialised
        // and stamp the default 85 — the existing 5/10 marketing/savings split
        // already implied an 85% owners pool, so this is just making it explicit.
        if (existing.OwnersSplitPercentage <= 0)
        {
            existing.OwnersSplitPercentage = 85;
            existing.UpdatedAt = DateTime.UtcNow;
            await _settings.ReplaceOneAsync(s => s.Id == existing.Id, existing, cancellationToken: ct);
        }

        // Issue #5 backfill: pre-existing settings rows deserialise
        // RetentionReminderWindows as null / empty and RetentionReminderTickHours
        // as 0. Stamp the documented defaults so the background job has something
        // sane to read on first boot after the upgrade.
        var needsRetentionBackfill =
            existing.RetentionReminderWindows == null ||
            existing.RetentionReminderWindows.Count == 0 ||
            existing.RetentionReminderTickHours <= 0 ||
            existing.RetentionReminderInactivityDays <= 0;
        if (needsRetentionBackfill)
        {
            if (existing.RetentionReminderWindows == null || existing.RetentionReminderWindows.Count == 0)
                existing.RetentionReminderWindows = new List<string> { "14d", "30d" };
            if (existing.RetentionReminderTickHours <= 0)
                existing.RetentionReminderTickHours = 12;
            if (existing.RetentionReminderInactivityDays <= 0)
                existing.RetentionReminderInactivityDays = 14;
            existing.UpdatedAt = DateTime.UtcNow;
            await _settings.ReplaceOneAsync(s => s.Id == existing.Id, existing, cancellationToken: ct);
        }

        // Per-payment-method cancel windows backfill: a row created before this
        // feature will deserialise all six fields as 0. Stamp the 3h default so
        // the cancel logic and the /api/customer/cancel-policy endpoint return
        // meaningful values out of the box.
        var needsCancelTierBackfill = existing.CancelWindowHoursCreditGroup <= 0
            && existing.CancelWindowHoursCreditPrivate <= 0
            && existing.CancelWindowHoursOnlineGroup <= 0
            && existing.CancelWindowHoursOnlinePrivate <= 0
            && existing.CancelWindowHoursStudioGroup <= 0
            && existing.CancelWindowHoursStudioPrivate <= 0;
        if (needsCancelTierBackfill)
        {
            existing.CancelWindowHoursCreditGroup = 3;
            existing.CancelWindowHoursCreditPrivate = 3;
            existing.CancelWindowHoursOnlineGroup = 3;
            existing.CancelWindowHoursOnlinePrivate = 3;
            existing.CancelWindowHoursStudioGroup = 3;
            existing.CancelWindowHoursStudioPrivate = 3;
            existing.UpdatedAt = DateTime.UtcNow;
            await _settings.ReplaceOneAsync(s => s.Id == existing.Id, existing, cancellationToken: ct);
        }

        // Late reschedule backfill: eligible methods list may be null on old rows.
        if (existing.LateRescheduleEligibleMethods == null || existing.LateRescheduleEligibleMethods.Count == 0)
        {
            existing.LateRescheduleEligibleMethods = new List<string> { "PACKAGE_CREDIT", "STRIPE_DEPOSIT", "STRIPE_FULL" };
            if (existing.LateRescheduleMaxPerMonth <= 0) existing.LateRescheduleMaxPerMonth = 1;
            if (string.IsNullOrWhiteSpace(existing.LateRescheduleMode)) existing.LateRescheduleMode = "ACCOUNT";
            existing.UpdatedAt = DateTime.UtcNow;
            await _settings.ReplaceOneAsync(s => s.Id == existing.Id, existing, cancellationToken: ct);
        }

        // Materialisation horizon backfill: old rows deserialise as 0.
        // Stamp the historical default (30 days) so the background service and
        // controller don't accidentally materialise with a zero-day window.
        if (existing.MaterialisationHorizonDays <= 0)
        {
            existing.MaterialisationHorizonDays = 30;
            existing.UpdatedAt = DateTime.UtcNow;
            await _settings.ReplaceOneAsync(s => s.Id == existing.Id, existing, cancellationToken: ct);
        }

        var normalisedRoleAccess = NormaliseRoleAccessSettings(existing.RoleAccessSettings);
        if (!AreRoleAccessSettingsEquivalent(existing.RoleAccessSettings, normalisedRoleAccess))
        {
            existing.RoleAccessSettings = normalisedRoleAccess;
            existing.UpdatedAt = DateTime.UtcNow;
            await _settings.ReplaceOneAsync(s => s.Id == existing.Id, existing, cancellationToken: ct);
        }

        return existing;
    }
