.getElementById("registerForm")
.addEventListener("submit", async (e) => {
  e.preventDefault();
  const firstName = document.getElementById("firstName").value.trim();
  const lastName = document.getElementById("lastName").value.trim();
  const email = document.getElementById("email").value.trim();
  const phone = document.getElementById("phone").value.trim();
  const phoneCountryCode =
    document.getElementById("phoneCC").value || "+84";
  const password = document.getElementById("password").value;
  const fullName = (firstName + " " + lastName).trim();

  if (!fullName || !email || !password)
    return showError("Please fill in all required fields.");
  if (password.length < 8)
    return showError("Password must be at least 8 characters.");

  const btn = document.getElementById("btnRegister");
  btn.disabled = true;
  const orig = btn.innerHTML;
  btn.innerHTML = "<span>...</span>";

  try {
    const res = await fetch(API + "/api/customer/register", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        fullName,
        email,
        password,
        phone: phone || null,
        phoneCountryCode: phone ? phoneCountryCode : null,
      }),
    });
    const data = await res.json();
    if (!res.ok) {
      showError(data.message || "Could not create account.");
      return;
    }

    // GA4: successful signup
    if (typeof window.spTrackEvent === 'function') {
      window.spTrackEvent('sign_up', { method: 'email', page: 'register' });
    }
    // Meta Pixel + CAPI: CompleteRegistration (new customer account).
    if (typeof window.spMetaTrack === 'function') {
      window.spMetaTrack(
        'CompleteRegistration',
        { content_name: 'Customer Account' },
        { email: email || null, phone: phone || null },
      );
    }

    if (data.emailVerificationRequired) {
      // ── Verification required: show "check your email" state ──
      document.getElementById("registerCard").style.display = "none";
      const success = document.getElementById("successCard");
      success.style.display = "block";
      document.getElementById("successVerifyState").style.display = "block";
      document.getElementById("successNormalState").style.display = "none";
      const verifyEmailEl = document.getElementById("successVerifyEmail");
      if (verifyEmailEl) verifyEmailEl.textContent = email;
    } else {
      // ── No verification required: auto-login and redirect ──
      // Priority: ?redirect= param (e.g. booking page) → /onboarding for new accounts
      const postRegRedirect = new URLSearchParams(window.location.search).get("redirect");
      try {
        const loginRes = await fetch(API + "/api/customer/login", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ email, password }),
        });
        const loginData = await loginRes.json();
        if (loginRes.ok && loginData.token) {
          localStorage.setItem("customer_token", loginData.token);
          localStorage.setItem("customer_name", loginData.fullName || fullName);
          localStorage.setItem("customer_email", loginData.email || email);
          localStorage.setItem("customer_clientId", loginData.clientId || "");
          // Respect the original destination; fall back to onboarding
          window.location.href = postRegRedirect || "/onboarding";
          return;
        }
      } catch (_) {
        // Auto-login failed (network hiccup) — fall through to show normal card
      }
      // Fallback: show the normal success card with a "Continue Setup" link
      document.getElementById("registerCard").style.display = "none";
      const success = document.getElementById("successCard");
      success.style.display = "block";
      document.getElementById("successVerifyState").style.display = "none";
      document.getElementById("successNormalState").style.display = "block";
      // Update the Continue Setup link to go to the original destination if present
      if (postRegRedirect) {
        const continueLink = document.querySelector("#successNormalState a");
        if (continueLink) continueLink.href = postRegRedirect;
      }
    }
  } catch (err) {
    showError("Network error. Please try again.");
  } finally {

