public async Task SendBookingConfirmationAsync(string toEmail, string clientName, string bookingReference,
    string className, string instructorName, DateTime classTime, string format,
    DateTime? endTime = null)
{
    if (!_enabled || string.IsNullOrWhiteSpace(toEmail)) return;
    if (!await IsTemplateEnabledAsync(EmailTemplateIds.BookingConfirmation)) return;

    // Default fallback if the caller didn't supply an end-time.
    // BookingController passes session.EndTime so this branch is
    // only hit by legacy callers (e.g. tests).
    var startUtc = DateTime.SpecifyKind(classTime, DateTimeKind.Utc);
    var endUtc = endTime.HasValue
        ? DateTime.SpecifyKind(endTime.Value, DateTimeKind.Utc)
        : startUtc.AddHours(1);

    var dateStr = classTime.ToString("dddd, dd MMM yyyy");
    var timeStr = classTime.ToString("hh:mm tt");

    // HTML-encode every user-supplied field — names, class titles,
    // and instructor names all come from external input. Was a
    // latent issue before P3-S07; locked down here.
    var safeClient = EmailTemplateHelper.EncodeText(clientName);
    var safeRef = EmailTemplateHelper.EncodeText(bookingReference);
    var safeClass = EmailTemplateHelper.EncodeText(className);
    var safeFormat = EmailTemplateHelper.EncodeText(format);
    var safeInstructor = EmailTemplateHelper.EncodeText(instructorName);

    // Resolve the cancel window dynamically from settings.
    // Uses the *most restrictive* general window for the session format
    // (credit tier). If settings can't be loaded, falls back to 3h.
    var cancelHrs = 3;
    if (_settingsService != null)
    {
        try
        {
            var settings = await _settingsService.GetAsync();
            cancelHrs = format == "PRIVATE"
                ? settings.CancelWindowHoursCreditPrivate
                : settings.CancelWindowHoursCreditGroup;
        }
        catch { /* swallow — email is fire-and-forget */ }
    }

    // SPM-76 — substitution dictionaries. Body values are pre-encoded above;
    // the {Token} keys match EmailTemplateDefaults.BookingConfirmationBody.
    // The subject uses the RAW (unencoded) class name, matching legacy output.
    var bodyValues = new Dictionary<string, string>
    {
        ["ClientName"] = safeClient,
        ["BookingReference"] = safeRef,
        ["ClassName"] = safeClass,
        ["Format"] = safeFormat,
        ["Date"] = dateStr,
        ["Time"] = timeStr,
        ["Instructor"] = safeInstructor,
        ["CancelHours"] = cancelHrs.ToString(),
    };
    var subjectValues = new Dictionary<string, string> { ["ClassName"] = className };

    var (subject, inner) = await ResolveTemplateAsync(
        EmailTemplateIds.BookingConfirmation,
        defaultSubject: "Booking Confirmed — {ClassName} | Xác nhận đặt lịch — Soul Pilates",
        defaultBody: EmailTemplateDefaults.BookingConfirmationBody,
        subjectValues: subjectValues,
        bodyValues: bodyValues);

    var body = EmailTemplateHelper.Layout(
        heading: "Booking Confirmed ✓",
        subtitleVi: "Đặt lịch thành công!",
        innerHtml: inner);

    // Build the .ics calendar invite. UID format
    // "{bookingReference}@soulpilates.com.vn" lets us emit a matching
    // METHOD:CANCEL later if the booking is cancelled — calendar
    // clients reconcile by UID.
    var icsBytes = IcsCalendarBuilder.BuildEventInvite(
        uid: $"{bookingReference}@soulpilates.com.vn",
        startUtc: startUtc,
        endUtc: endUtc,
        summary: $"{className} — {instructorName}",
        description: $"Soul Pilates Da Nang · {format} · Reference {bookingReference}",
        location: EmailTemplateHelper.StudioLocation);

    var icsAttachment = new Attachment(
        new MemoryStream(icsBytes),
        $"soul-pilates-{bookingReference}.ics",
        "text/calendar");

    await SendEmailAsync(toEmail, subject, body, icsAttachment);
}

