/// <summary>
/// P5-S01 — fire-and-forget booking confirmation email to the customer.
/// Called at the exact RESERVED → BOOKED transition so the customer only
/// receives the email when their booking is definitively confirmed (not
/// at the speculative RESERVED stage).
/// </summary>
private void FireAndForgetBookingEmail(Attendance attendance, CalendarSession session)
{
    if (string.IsNullOrWhiteSpace(attendance.ClientEmail)) return;
    _ = Task.Run(async () =>
    {
        try
        {
            await _emailService.SendBookingConfirmationAsync(
                attendance.ClientEmail,
                attendance.ClientName ?? "Customer",
                attendance.BookingReference,
                session.ClassName,
                session.InstructorName,
                session.StartTime,
                session.Format,
                session.EndTime);
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex,
                "Failed to send booking confirmation email for attendance {AttendanceId}",
                attendance.Id);
        }
    });
}

