            query.Add("name=" + Uri.EscapeDataString(clientName));
        if (!string.IsNullOrWhiteSpace(toEmail))
            query.Add("email=" + Uri.EscapeDataString(toEmail));
        if (!string.IsNullOrWhiteSpace(guestPhone))
            query.Add("phone=" + Uri.EscapeDataString(guestPhone));
        var registerUrl = $"{_publicBaseUrl}/register?{string.Join("&", query)}";

        var ctaHtml = $@"
<div style=""margin:28px 0 8px;padding:20px 22px;background:#FBF3EC;border:1px solid #F0DCC8;border-radius:10px;"">
  <p style=""margin:0 0 6px;font-weight:700;color:#1a1a1a;font-family:Arial,sans-serif;"">Want to manage this booking?</p>
  <p style=""margin:0 0 14px;font-size:14px;color:#555555;font-family:Arial,sans-serif;"">Create your free account to see your booking history, cancel or reschedule this class, and buy class packages &mdash; all in one place. It only takes a minute.</p>
  <p style=""text-align:center;margin:0 0 6px;""><a href=""{registerUrl}"" style=""background:#EA6A24;color:#ffffff;padding:13px 28px;border-radius:8px;text-decoration:none;font-weight:600;display:inline-block;font-family:Arial,sans-serif;"">Finish creating my account</a></p>
  <p style=""margin:10px 0 0;font-size:12px;color:#999999;font-family:Arial,sans-serif;"">Tạo tài khoản để xem lịch sử đặt lớp, hủy hoặc đổi lịch, và mua gói tập.</p>
</div>";

        var body = EmailTemplateHelper.Layout(
            heading: "Booking Confirmed ✓",
            subtitleVi: "Đặt lịch thành công!",
            innerHtml: inner + ctaHtml);

        var icsBytes = IcsCalendarBuilder.BuildEventInvite(
            uid: $"{bookingReference}@soulpilates.com.vn",
            startUtc: startUtc,
            endUtc: endUtc,
            summary: $"{className} — {instructorName}",
            description: $"Soul Pilates Da Nang · {format} · Reference {bookingReference}",
            location: EmailTemplateHelper.StudioLocation);

        var icsAttachment = new Attachment(
            new MemoryStream(icsBytes),
            $"soul-pilates-{bookingReference}.ics",
            "text/calendar");

        await SendEmailAsync(toEmail, subject, body, icsAttachment);
    }

