if (_redirectParam) {
  const loginLink = document.getElementById("loginLink");
  if (loginLink) loginLink.href = "/login?redirect=" + encodeURIComponent(_redirectParam);
  const goToLoginBtn = document.getElementById("goToLoginBtn");
  if (goToLoginBtn) goToLoginBtn.href = "/login?redirect=" + encodeURIComponent(_redirectParam);
}

// ── Prefill from query params (e.g. the guest booking-confirmation email
//    CTA links here with name/email/phone so the guest only sets a password) ──
const _pfName = (_regParams.get("name") || "").trim();
if (_pfName) {
  const _parts = _pfName.split(/\s+/);
  const _first = document.getElementById("firstName");
  const _last = document.getElementById("lastName");
  if (_first && !_first.value) _first.value = _parts.shift() || "";
  if (_last && !_last.value) _last.value = _parts.join(" ");
}
const _pfEmail = (_regParams.get("email") || "").trim();
if (_pfEmail) {
  const _emailEl = document.getElementById("email");
  if (_emailEl && !_emailEl.value) _emailEl.value = _pfEmail;
}
const _pfPhone = (_regParams.get("phone") || "").trim();
if (_pfPhone) {
  // Accept either national digits or a full "+84…" value; strip a leading
  // country code into the selector when present.
  const _phoneEl = document.getElementById("phone");
  const _ccEl = document.getElementById("phoneCC");
  let _national = _pfPhone;
  if (_pfPhone.startsWith("+") && _ccEl) {
    const _match = Array.from(_ccEl.options)
      .map((o) => o.value)
      .filter((v) => _pfPhone.startsWith(v))
      .sort((a, b) => b.length - a.length)[0];
    if (_match) {
      _ccEl.value = _match;
      _national = _pfPhone.slice(_match.length);
    }
  }
  if (_phoneEl && !_phoneEl.value) _phoneEl.value = _national.replace(/^0+/, "");
}

