34	                 name="client-search-nofill" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false"
35	                 data-lpignore="true" data-form-type="other" data-1p-ignore>
36	        </div>
37	        <span class="text-sm text-muted ml-auto" id="clientCount">0 clients</span>
38	      </div>
39	    </div>
40	  </div>
41	
42	  <div class="card">
43	    <div class="card-body no-pad">
44	      <div class="table-responsive">
45	      <table class="data-table">
46	        <thead>
47	          <tr>
48	            <th>Name</th>
49	            <th>Phone</th>
50	            <th class="hidden-mobile">Email</th>
51	            <th class="hidden-mobile">Member since</th>
52	            <th>Credits</th>
53	            <th>Status</th>
54	            <th>Actions</th>
55	          </tr>
56	        </thead>
57	        <tbody id="clientTable">
58	          <tr><td colspan="7" class="text-muted text-sm" style="text-align:center;padding:40px;">Loading…</td></tr>
59	        </tbody>
60	      </table>
61	      </div>
62	    </div>
63	    <div style="display:flex;align-items:center;justify-content:space-between;padding:12px 16px;border-top:1px solid var(--color-border-subtle);">
64	      <span class="text-sm text-muted" id="paginationInfo">—</span>
65	      <div class="pagination" id="paginationCtrl"></div>
66	    </div>
67	  </div>
68	  </div><!-- /clientsView -->
69	
70	  <!-- Packages tab -->
71	  <div id="packagesView" style="display:none;">
72	    <div class="card" style="margin-bottom:16px;">
73	      <div class="card-body" style="padding:12px 16px;font-size:13px;color:var(--color-text-muted);">
74	        All active packages across clients. <strong>Expiring soon</strong> or <strong>low on credits</strong> appear first.
75	      </div>
76	    </div>
77	    <div class="card">
78	      <div class="card-body no-pad">
79	        <div class="table-responsive">
80	          <table class="data-table">
81	            <thead>
82	              <tr>
83	                <th>Client</th>
84	                <th>Package</th>
85	                <th>Credits</th>
86	                <th class="hidden-mobile">Expires</th>
87	                <th>Status</th>
88	                <th></th>
89	              </tr>
90	            </thead>
91	            <tbody id="packagesTable">
92	              <tr><td colspan="6" class="text-muted text-sm" style="text-align:center;padding:40px;">Loading…</td></tr>
93	            </tbody>
94	          </table>
95	        </div>
96	      </div>
97	    </div>
98	  </div>
99	
100	  <!-- VIP tab -->
101	  <div id="vipView" style="display:none;">
102	    <div class="card" style="margin-bottom:16px;">
103	      <div class="card-body" style="padding:12px 16px;font-size:13px;color:var(--color-text-muted);">
104	        👑 Clients with a lifetime spend of <strong>₫10,000,000</strong> or more — highest first. VIP status updates automatically as clients spend.
105	      </div>
106	    </div>
107	    <div class="card">
108	      <div class="card-body no-pad">
109	        <div class="table-responsive">
110	          <table class="data-table">
111	            <thead>
112	              <tr>
113	                <th>Client</th>
114	                <th>Phone</th>
115	                <th class="hidden-mobile">Classes</th>
116	                <th>Lifetime value</th>
117	                <th></th>
118	              </tr>
119	            </thead>
120	            <tbody id="vipTable">
121	              <tr><td colspan="5" class="text-muted text-sm" style="text-align:center;padding:40px;">Loading…</td></tr>
122	            </tbody>
123	          </table>
124	        </div>
125	      </div>
126	    </div>
127	  </div>
128	
129	</AdminLayout>
130	
131	<script>
132	  const API = import.meta.env.PUBLIC_API_URL;
133	  const token = localStorage.getItem('token');
134	  const PAGE_SIZE = 25;
135	  let allClients = [], currentPage = 1;
136	
137	  function loadClients(q = '') {
138	    fetch(`${API}/api/client?search=${encodeURIComponent(q)}`, { headers: { 'Authorization': 'Bearer ' + token } })
139	      .then(r => r.json()).then(data => { allClients = data; renderPage(1); }).catch(() => {});
140	  }
141	
142	  function _clEsc(s) {
143	    return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]));
144	  }
145	
146	  // Credits cell: small pills per format (group/mat/private), non-zero only.
147	  function _clCreditsCell(c) {
148	    const pill = (label, n, bg, fg) => `<span title="${label} credits" style="display:inline-flex;align-items:center;font-size:10px;font-weight:700;background:${bg};color:${fg};padding:1px 7px;border-radius:999px;">${label} ${n}</span>`;
149	    const parts = [];
150	    if ((c.groupCredits || 0) > 0) parts.push(pill('Group', c.groupCredits, 'rgba(61,140,92,0.14)', '#2E6B46'));
151	    if ((c.matCredits || 0) > 0) parts.push(pill('Mat', c.matCredits, 'rgba(70,110,190,0.14)', '#2f5ba8'));
152	    if ((c.privateCredits || 0) > 0) parts.push(pill('Private', c.privateCredits, 'rgba(234,106,36,0.14)', '#b8541a'));
153	    if (!parts.length) return '<span class="text-muted text-sm">—</span>';
154	    return `<div style="display:flex;gap:4px;flex-wrap:wrap;">${parts.join('')}</div>`;
155	  }
156	
157	  // Small VIP / Super VIP chip shown next to a client's name.
158	  function _clVipChip(tier) {
159	    if (tier === 'SUPER_VIP') return ' <span style="display:inline-flex;align-items:center;font-size:9px;font-weight:800;letter-spacing:.03em;background:linear-gradient(135deg,#8E2DE2,#4A00E0);color:#fff;padding:1px 6px;border-radius:999px;vertical-align:middle;">💎 SUPER VIP</span>';
160	    if (tier === 'VIP') return ' <span style="display:inline-flex;align-items:center;font-size:9px;font-weight:800;letter-spacing:.03em;background:linear-gradient(135deg,#F4C430,#E0A800);color:#4a3500;padding:1px 6px;border-radius:999px;vertical-align:middle;">👑 VIP</span>';
161	    return '';
162	  }
163	
164	  // ── Packages tab ──────────────────────────────────────────────
165	  let _packagesLoaded = false;
166	  function clSwitchTab(tab) {
167	    document.querySelectorAll('.cl-tab').forEach(b => {
168	      const on = b.dataset.tab === tab;
169	      b.classList.toggle('active', on);
170	      b.style.color = on ? 'var(--color-text-primary)' : 'var(--color-text-muted)';
171	      b.style.borderBottomColor = on ? 'var(--color-brand-accent)' : 'transparent';
172	    });
173	    document.getElementById('clientsView').style.display = tab === 'clients' ? '' : 'none';
174	    document.getElementById('packagesView').style.display = tab === 'packages' ? '' : 'none';
175	    document.getElementById('vipView').style.display = tab === 'vip' ? '' : 'none';
176	    if (tab === 'packages' && !_packagesLoaded) { _packagesLoaded = true; loadPackages(); }
177	    if (tab === 'vip' && !_vipLoaded) { _vipLoaded = true; loadVips(); }
178	  }
179	  window.clSwitchTab = clSwitchTab;
180	
181	  // ── VIP tab ──────────────────────────────────────────────────
182	  let _vipLoaded = false;
183	  function loadVips() {
184	    fetch(`${API}/api/client/vips`, { headers: { Authorization: 'Bearer ' + token } })
185	      .then(r => (r.ok ? r.json() : Promise.reject(r.status)))
186	      .then(vips => {
187	        const tbody = document.getElementById('vipTable');
188	        if (!vips.length) {
189	          tbody.innerHTML = '<tr><td colspan="5" class="text-muted text-sm" style="text-align:center;padding:40px;">No VIP clients yet — nobody has reached ₫10,000,000 in lifetime spend.</td></tr>';
190	          return;
191	        }
192	        tbody.innerHTML = vips.map(v => `
193	          <tr style="cursor:pointer;" onclick="location.href='/admin/client-profile?id=${_clEsc(v.id)}'">
194	            <td class="font-medium">${_clEsc(v.name)}${_clVipChip(v.vipTier)}</td>
195	            <td class="text-sm">${_clEsc(v.phone || '—')}</td>
196	            <td class="text-sm hidden-mobile">${v.attendedClasses ?? 0}</td>
197	            <td class="font-medium">₫${Math.round(v.lifetimeValue || 0).toLocaleString()}</td>
198	            <td class="text-sm" style="color:var(--color-brand-accent);">View →</td>
199	          </tr>`).join('');
200	      })
201	      .catch(() => {
202	        document.getElementById('vipTable').innerHTML = '<tr><td colspan="5" class="text-muted text-sm" style="text-align:center;padding:40px;">Could not load VIPs.</td></tr>';
203	      });
204	  }
205	  window.loadVips = loadVips;
206	
207	  function loadPackages() {
208	    fetch(`${API}/api/wallet/active-packages`, { headers: { Authorization: 'Bearer ' + token } })
209	      .then(r => (r.ok ? r.json() : Promise.reject(r.status)))
210	      .then(pkgs => {
211	        const now = Date.now(), dayMs = 86400000;
212	        const info = pkgs.map(p => {
213	          const days = p.expiryDate ? Math.round((new Date(p.expiryDate).getTime() - now) / dayMs) : Infinity;
214	          const low = (p.creditsRemaining || 0) <= 2;
215	          const expSoon = days !== Infinity && days <= 14;
216	          // Lower score = more urgent: whichever runs out first (days, or credits × ~7d of runway).
217	          const score = Math.min(days === Infinity ? 9999 : days, (p.creditsRemaining || 0) * 7);
218	          return { ...p, days, low, expSoon, urgent: low || expSoon, score };
219	        }).sort((a, b) => a.score - b.score);
220	
221	        const tbody = document.getElementById('packagesTable');
222	        if (!info.length) {
223	          tbody.innerHTML = '<tr><td colspan="6" class="text-muted text-sm" style="text-align:center;padding:40px;">No active packages.</td></tr>';
224	          return;
225	        }
226	        tbody.innerHTML = info.map(p => {
227	          const expTxt = p.days === Infinity
228	            ? '<span style="color:var(--color-success);">No expiry</span>'
229	            : new Date(p.expiryDate).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
230	          const flags = [];
231	          if (p.expSoon) flags.push(`<span class="badge badge-warning" style="font-size:10px;">⏳ ${p.days <= 0 ? 'Expired' : p.days + 'd left'}</span>`);
232	          if (p.low) flags.push('<span class="badge badge-danger" style="font-size:10px;">⚠️ Low</span>');
233	          return `<tr${p.urgent ? ' style="background:rgba(244,146,60,0.07);"' : ''}>
234	            <td><a href="/admin/client-profile?id=${p.clientId}" style="color:var(--color-brand-accent);font-weight:600;">${_clEsc(p.clientName)}</a></td>
235	            <td>${_clEsc(p.productName || p.format)}</td>
236	            <td><strong>${p.creditsRemaining}</strong> / ${p.totalCredits} ${flags.join(' ')}</td>
237	            <td class="hidden-mobile">${expTxt}</td>
238	            <td>${_clEsc(p.status || '')}</td>
239	            <td><button class="btn btn-ghost btn-sm btn-icon" title="View client" onclick="window.location.href='/admin/client-profile?id=${p.clientId}'">→</button></td>
240	          </tr>`;
241	        }).join('');
242	      })
243	      .catch(() => {
244	        document.getElementById('packagesTable').innerHTML = '<tr><td colspan="6" class="text-muted text-sm" style="text-align:center;padding:40px;">Could not load packages.</td></tr>';
245	      });
246	  }
247	
248	  function renderPage(page) {
249	    const totalPages = Math.ceil(allClients.length / PAGE_SIZE);
250	    if (page < 1) page = 1;
251	    if (page > totalPages) page = totalPages || 1;
252	    currentPage = page;
253	    const start = (page - 1) * PAGE_SIZE;
254	    const slice = allClients.slice(start, start + PAGE_SIZE);
255	    document.getElementById('clientCount').textContent = `${allClients.length} clients`;
256	    document.getElementById('paginationInfo').textContent = allClients.length
257	      ? `Showing ${start + 1}–${Math.min(start + PAGE_SIZE, allClients.length)} of ${allClients.length}`
258	      : '0 results';
259	
260	    const tbody = document.getElementById('clientTable');
261	    if (!slice.length) {
262	      tbody.innerHTML = `<tr><td colspan="7" style="text-align:center;padding:40px;color:var(--color-text-muted);">No clients found</td></tr>`;
263	    } else {
264	      tbody.innerHTML = slice.map(c => `
265	        <tr style="cursor:pointer;" onclick="window.location.href='/admin/client-profile?id=${c.id}'">
266	          <td><span class="font-medium">${c.name}</span>${_clVipChip(c.vipTier)}${c.email ? `<div class="text-muted" style="font-size:11.5px;margin-top:1px;opacity:0.7;">${c.email}</div>` : ''}</td>
267	          <td class="text-muted text-sm">${c.phone ? (c.phoneCountryCode ? c.phoneCountryCode + ' ' : '') + c.phone : '—'}</td>
268	          <td class="hidden-mobile text-muted text-sm">${c.email ?? '—'}</td>
269	          <td class="hidden-mobile text-muted text-sm">${c.createdAt ? new Date(c.createdAt).toLocaleDateString('en-US', { month: 'short', year: 'numeric' }) : '—'}</td>
270	          <td>${_clCreditsCell(c)}</td>
271	          <td><span class="badge badge-success">Active</span></td>
272	          <td onclick="event.stopPropagation()">
273	            <div style="display:flex;gap:4px;">
274	              <button class="btn btn-ghost btn-sm btn-icon" title="View profile" onclick="window.location.href='/admin/client-profile?id=${c.id}'">
275	                <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
276	              </button>
277	              <button class="btn btn-ghost btn-sm btn-icon" title="Edit" onclick="window.location.href='/admin/client-form?id='+encodeURIComponent('${c.id}')">
278	                <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.12 2.12 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
279	              </button>
280	            </div>
281	          </td>
282	        </tr>`).join('');
283	    }
284	    renderPagination();
285	  }
286	
287	  function renderPagination() {
288	    const totalPages = Math.ceil(allClients.length / PAGE_SIZE);
289	    const ctrl = document.getElementById('paginationCtrl');
290	    if (totalPages <= 1) { ctrl.innerHTML = ''; return; }
291	
292	    let html = '';
293	
294	    // Previous button
295	    html += `<button class="page-btn${currentPage === 1 ? ' disabled' : ''}" ${currentPage === 1 ? 'disabled' : ''} onclick="renderPage(${currentPage - 1})" title="Previous page">‹</button>`;
296	
297	    // Always show page 1
298	    html += `<button class="page-btn${currentPage === 1 ? ' active' : ''}" onclick="renderPage(1)">1</button>`;
299	
300	    if (totalPages <= 5) {
301	      // Show all pages when there are 5 or fewer
302	      for (let i = 2; i <= totalPages; i++) {
303	        html += `<button class="page-btn${i === currentPage ? ' active' : ''}" onclick="renderPage(${i})">${i}</button>`;
304	      }
305	    } else {
306	      // Show pages 2 and 3 (or nearby pages for context)
307	      if (currentPage <= 3) {
308	        // Near the start: show 2, 3 then ellipsis
309	        for (let i = 2; i <= 3; i++) {
310	          html += `<button class="page-btn${i === currentPage ? ' active' : ''}" onclick="renderPage(${i})">${i}</button>`;
311	        }
312	        html += `<span class="page-ellipsis">…</span>`;
313	      } else if (currentPage >= totalPages - 2) {
314	        // Near the end: ellipsis then last 2 before final
315	        html += `<span class="page-ellipsis">…</span>`;
316	        for (let i = totalPages - 2; i < totalPages; i++) {
317	          html += `<button class="page-btn${i === currentPage ? ' active' : ''}" onclick="renderPage(${i})">${i}</button>`;
318	        }
319	      } else {
320	        // Middle: ellipsis, current-1, current, current+1, ellipsis
321	        html += `<span class="page-ellipsis">…</span>`;
322	        for (let i = currentPage - 1; i <= currentPage + 1; i++) {
323	          html += `<button class="page-btn${i === currentPage ? ' active' : ''}" onclick="renderPage(${i})">${i}</button>`;
324	        }
325	        html += `<span class="page-ellipsis">…</span>`;
326	      }
327	
328	      // "Go to page" mini input
329	      html += `<span class="page-goto-wrap">
330	        <input type="number" class="page-goto-input" id="pageGotoInput" min="1" max="${totalPages}" placeholder="#" title="Go to page…" aria-label="Go to page">
331	      </span>`;
332	
333	      // Always show last page
334	      html += `<button class="page-btn${currentPage === totalPages ? ' active' : ''}" onclick="renderPage(${totalPages})">${totalPages}</button>`;
335	    }
336	
337	    // Next button
338	    html += `<button class="page-btn${currentPage === totalPages ? ' disabled' : ''}" ${currentPage === totalPages ? 'disabled' : ''} onclick="renderPage(${currentPage + 1})" title="Next page">›</button>`;
339	
340	    ctrl.innerHTML = html;
341	
342	    // Bind the go-to input
343	    const gotoInput = document.getElementById('pageGotoInput');
344	    if (gotoInput) {
345	      gotoInput.addEventListener('keydown', e => {
346	        if (e.key === 'Enter') {
347	          const p = parseInt(gotoInput.value, 10);
348	          if (p >= 1 && p <= totalPages) renderPage(p);
349	        }
350	      });
351	    }
352	  }
353	
354	  let debounce;
355	  document.getElementById('searchInput').addEventListener('input', e => {
356	    clearTimeout(debounce);
357	    debounce = setTimeout(() => loadClients(e.target.value), 350);
358	  });
359	
360	  // Pre-fill + apply the filter when arriving via the top-bar quick-search
361	  // "View all results" link (/admin/clients?search=…).
362	  const _preSearch = new URLSearchParams(location.search).get('search');
363	  if (_preSearch) {
364	    document.getElementById('searchInput').value = _preSearch;
365	    loadClients(_preSearch);
366	  } else {
367	    loadClients();
368	  }
369	
370	  window.renderPage = renderPage;
371	</script>
