---
import AdminLayout from '../../layouts/AdminLayout.astro';
---
<AdminLayout title="Clients" activePage="clients">

  <div class="page-header">
    <div>
      <div class="page-title">Clients</div>
      <div class="page-subtitle">Manage all studio clients and profiles</div>
    </div>
    <button class="btn btn-primary" onclick="window.location.href='/admin/client-form'">
      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
      New client
    </button>
  </div>

  <!-- Tabs: Clients | Packages -->
  <div class="cl-tabs" style="display:flex;gap:6px;margin-bottom:16px;border-bottom:1px solid var(--color-border-subtle);">
    <button class="cl-tab active" data-tab="clients" onclick="clSwitchTab('clients')"
      style="background:none;border:none;padding:10px 4px;margin-right:14px;font-size:14px;font-weight:600;color:var(--color-text-primary);cursor:pointer;border-bottom:2px solid var(--color-brand-accent);">Clients</button>
    <button class="cl-tab" data-tab="packages" onclick="clSwitchTab('packages')"
      style="background:none;border:none;padding:10px 4px;margin-right:14px;font-size:14px;font-weight:600;color:var(--color-text-muted);cursor:pointer;border-bottom:2px solid transparent;">Packages</button>
    <button class="cl-tab" data-tab="vip" onclick="clSwitchTab('vip')"
      style="background:none;border:none;padding:10px 4px;font-size:14px;font-weight:600;color:var(--color-text-muted);cursor:pointer;border-bottom:2px solid transparent;">👑 VIPs</button>
  </div>

  <div id="clientsView">
  <div class="card" style="margin-bottom:16px;">
    <div class="card-body" style="padding:12px 16px;">
      <div class="flex items-center gap-3">
        <div class="search-input-wrap" style="flex:1;max-width:340px;">
          <svg class="search-icon" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
          <input type="search" id="searchInput" class="form-control search-input" placeholder="Search by name, email, or phone…"
                 name="client-search-nofill" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false"
                 data-lpignore="true" data-form-type="other" data-1p-ignore>
        </div>
        <span class="text-sm text-muted ml-auto" id="clientCount">0 clients</span>
      </div>
    </div>
  </div>

  <div class="card">
    <div class="card-body no-pad">
      <div class="table-responsive">
      <table class="data-table">
        <thead>
          <tr>
            <th>Name</th>
            <th>Phone</th>
            <th class="hidden-mobile">Email</th>
            <th class="hidden-mobile">Member since</th>
            <th>Credits</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody id="clientTable">
          <tr><td colspan="7" class="text-muted text-sm" style="text-align:center;padding:40px;">Loading…</td></tr>
        </tbody>
      </table>
      </div>
    </div>
    <div style="display:flex;align-items:center;justify-content:space-between;padding:12px 16px;border-top:1px solid var(--color-border-subtle);">
      <span class="text-sm text-muted" id="paginationInfo">—</span>
      <div class="pagination" id="paginationCtrl"></div>
    </div>
  </div>
  </div><!-- /clientsView -->

  <!-- Packages tab -->
  <div id="packagesView" style="display:none;">
    <div class="card" style="margin-bottom:16px;">
      <div class="card-body" style="padding:12px 16px;font-size:13px;color:var(--color-text-muted);">
        All active packages across clients. <strong>Expiring soon</strong> or <strong>low on credits</strong> appear first.
      </div>
    </div>
    <div class="card">
      <div class="card-body no-pad">
        <div class="table-responsive">
          <table class="data-table">
            <thead>
              <tr>
                <th>Client</th>
                <th>Package</th>
                <th>Credits</th>
                <th class="hidden-mobile">Expires</th>
                <th>Status</th>
                <th></th>
              </tr>
            </thead>
            <tbody id="packagesTable">
              <tr><td colspan="6" class="text-muted text-sm" style="text-align:center;padding:40px;">Loading…</td></tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
  </div>

  <!-- VIP tab -->
  <div id="vipView" style="display:none;">
    <div class="card" style="margin-bottom:16px;">
      <div class="card-body" style="padding:12px 16px;font-size:13px;color:var(--color-text-muted);">
        👑 Clients with a lifetime spend of <strong>₫10,000,000</strong> or more — highest first. VIP status updates automatically as clients spend.
      </div>
    </div>
    <div class="card">
      <div class="card-body no-pad">
        <div class="table-responsive">
          <table class="data-table">
            <thead>
              <tr>
                <th>Client</th>
                <th>Phone</th>
                <th class="hidden-mobile">Classes</th>
                <th>Lifetime value</th>
                <th></th>
              </tr>
            </thead>
            <tbody id="vipTable">
              <tr><td colspan="5" class="text-muted text-sm" style="text-align:center;padding:40px;">Loading…</td></tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
  </div>

</AdminLayout>

<script>
  const API = import.meta.env.PUBLIC_API_URL;
  const token = localStorage.getItem('token');
  const PAGE_SIZE = 25;
  let allClients = [], currentPage = 1;

  function loadClients(q = '') {
    fetch(`${API}/api/client?search=${encodeURIComponent(q)}`, { headers: { 'Authorization': 'Bearer ' + token } })
      .then(r => r.json()).then(data => { allClients = data; renderPage(1); }).catch(() => {});
  }

  function _clEsc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]));
  }

  // Credits cell: small pills per format (group/mat/private), non-zero only.
  function _clCreditsCell(c) {
    const pill = (label, n, bg, fg) => `<span title="${label} credits" style="display:inline-flex;align-items:center;font-size:10px;font-weight:700;background:${bg};color:${fg};padding:1px 7px;border-radius:999px;">${label} ${n}</span>`;
    const parts = [];
    if ((c.groupCredits || 0) > 0) parts.push(pill('Group', c.groupCredits, 'rgba(61,140,92,0.14)', '#2E6B46'));
    if ((c.matCredits || 0) > 0) parts.push(pill('Mat', c.matCredits, 'rgba(70,110,190,0.14)', '#2f5ba8'));
    if ((c.privateCredits || 0) > 0) parts.push(pill('Private', c.privateCredits, 'rgba(234,106,36,0.14)', '#b8541a'));
    if (!parts.length) return '<span class="text-muted text-sm">—</span>';
    return `<div style="display:flex;gap:4px;flex-wrap:wrap;">${parts.join('')}</div>`;
  }

  // Small VIP / Super VIP chip shown next to a client's name.
  function _clVipChip(tier) {
    if (tier === 'SUPER_VIP') return ' <span style="display:inline-flex;align-items:center;font-size:9px;font-weight:800;letter-spacing:.03em;background:linear-gradient(135deg,#8E2DE2,#4A00E0);color:#fff;padding:1px 6px;border-radius:999px;vertical-align:middle;">💎 SUPER VIP</span>';
    if (tier === 'VIP') return ' <span style="display:inline-flex;align-items:center;font-size:9px;font-weight:800;letter-spacing:.03em;background:linear-gradient(135deg,#F4C430,#E0A800);color:#4a3500;padding:1px 6px;border-radius:999px;vertical-align:middle;">👑 VIP</span>';
    return '';
  }

  // ── Packages tab ──────────────────────────────────────────────
  let _packagesLoaded = false;
  function clSwitchTab(tab) {
    document.querySelectorAll('.cl-tab').forEach(b => {
      const on = b.dataset.tab === tab;
      b.classList.toggle('active', on);
      b.style.color = on ? 'var(--color-text-primary)' : 'var(--color-text-muted)';
      b.style.borderBottomColor = on ? 'var(--color-brand-accent)' : 'transparent';
    });
    document.getElementById('clientsView').style.display = tab === 'clients' ? '' : 'none';
    document.getElementById('packagesView').style.display = tab === 'packages' ? '' : 'none';
    document.getElementById('vipView').style.display = tab === 'vip' ? '' : 'none';
    if (tab === 'packages' && !_packagesLoaded) { _packagesLoaded = true; loadPackages(); }
    if (tab === 'vip' && !_vipLoaded) { _vipLoaded = true; loadVips(); }
  }
  window.clSwitchTab = clSwitchTab;

  // ── VIP tab ──────────────────────────────────────────────────
  let _vipLoaded = false;
  function loadVips() {
    fetch(`${API}/api/client/vips`, { headers: { Authorization: 'Bearer ' + token } })
      .then(r => (r.ok ? r.json() : Promise.reject(r.status)))
      .then(vips => {
        const tbody = document.getElementById('vipTable');
        if (!vips.length) {
          tbody.innerHTML = '<tr><td colspan="5" class="text-muted text-sm" style="text-align:center;padding:40px;">No VIP clients yet — nobody has reached ₫10,000,000 in lifetime spend.</td></tr>';
          return;
        }
        tbody.innerHTML = vips.map(v => `
          <tr style="cursor:pointer;" onclick="location.href='/admin/client-profile?id=${_clEsc(v.id)}'">
            <td class="font-medium">${_clEsc(v.name)}${_clVipChip(v.vipTier)}</td>
            <td class="text-sm">${_clEsc(v.phone || '—')}</td>
            <td class="text-sm hidden-mobile">${v.attendedClasses ?? 0}</td>
            <td class="font-medium">₫${Math.round(v.lifetimeValue || 0).toLocaleString()}</td>
            <td class="text-sm" style="color:var(--color-brand-accent);">View →</td>
          </tr>`).join('');
      })
      .catch(() => {
        document.getElementById('vipTable').innerHTML = '<tr><td colspan="5" class="text-muted text-sm" style="text-align:center;padding:40px;">Could not load VIPs.</td></tr>';
      });
  }
  window.loadVips = loadVips;

  function loadPackages() {
    fetch(`${API}/api/wallet/active-packages`, { headers: { Authorization: 'Bearer ' + token } })
      .then(r => (r.ok ? r.json() : Promise.reject(r.status)))
      .then(pkgs => {
        const now = Date.now(), dayMs = 86400000;
        const info = pkgs.map(p => {
          const days = p.expiryDate ? Math.round((new Date(p.expiryDate).getTime() - now) / dayMs) : Infinity;
          const low = (p.creditsRemaining || 0) <= 2;
          const expSoon = days !== Infinity && days <= 14;
          // Lower score = more urgent: whichever runs out first (days, or credits × ~7d of runway).
          const score = Math.min(days === Infinity ? 9999 : days, (p.creditsRemaining || 0) * 7);
          return { ...p, days, low, expSoon, urgent: low || expSoon, score };
        }).sort((a, b) => a.score - b.score);

        const tbody = document.getElementById('packagesTable');
        if (!info.length) {
          tbody.innerHTML = '<tr><td colspan="6" class="text-muted text-sm" style="text-align:center;padding:40px;">No active packages.</td></tr>';
          return;
        }
        tbody.innerHTML = info.map(p => {
          const expTxt = p.days === Infinity
            ? '<span style="color:var(--color-success);">No expiry</span>'
            : new Date(p.expiryDate).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
          const flags = [];
          if (p.expSoon) flags.push(`<span class="badge badge-warning" style="font-size:10px;">⏳ ${p.days <= 0 ? 'Expired' : p.days + 'd left'}</span>`);
          if (p.low) flags.push('<span class="badge badge-danger" style="font-size:10px;">⚠️ Low</span>');
          return `<tr${p.urgent ? ' style="background:rgba(244,146,60,0.07);"' : ''}>
            <td><a href="/admin/client-profile?id=${p.clientId}" style="color:var(--color-brand-accent);font-weight:600;">${_clEsc(p.clientName)}</a></td>
            <td>${_clEsc(p.productName || p.format)}</td>
            <td><strong>${p.creditsRemaining}</strong> / ${p.totalCredits} ${flags.join(' ')}</td>
            <td class="hidden-mobile">${expTxt}</td>
            <td>${_clEsc(p.status || '')}</td>
            <td><button class="btn btn-ghost btn-sm btn-icon" title="View client" onclick="window.location.href='/admin/client-profile?id=${p.clientId}'">→</button></td>
          </tr>`;
        }).join('');
      })
      .catch(() => {
        document.getElementById('packagesTable').innerHTML = '<tr><td colspan="6" class="text-muted text-sm" style="text-align:center;padding:40px;">Could not load packages.</td></tr>';
      });
  }

  function renderPage(page) {
    const totalPages = Math.ceil(allClients.length / PAGE_SIZE);
    if (page < 1) page = 1;
    if (page > totalPages) page = totalPages || 1;
    currentPage = page;
    const start = (page - 1) * PAGE_SIZE;
    const slice = allClients.slice(start, start + PAGE_SIZE);
    document.getElementById('clientCount').textContent = `${allClients.length} clients`;
    document.getElementById('paginationInfo').textContent = allClients.length
      ? `Showing ${start + 1}–${Math.min(start + PAGE_SIZE, allClients.length)} of ${allClients.length}`
      : '0 results';

    const tbody = document.getElementById('clientTable');
    if (!slice.length) {
      tbody.innerHTML = `<tr><td colspan="7" style="text-align:center;padding:40px;color:var(--color-text-muted);">No clients found</td></tr>`;
    } else {
      tbody.innerHTML = slice.map(c => `
        <tr style="cursor:pointer;" onclick="window.location.href='/admin/client-profile?id=${c.id}'">
          <td><span class="font-medium">${c.name}</span>${_clVipChip(c.vipTier)}${c.email ? `<div class="text-muted" style="font-size:11.5px;margin-top:1px;opacity:0.7;">${c.email}</div>` : ''}</td>
          <td class="text-muted text-sm">${c.phone ? (c.phoneCountryCode ? c.phoneCountryCode + ' ' : '') + c.phone : '—'}</td>
          <td class="hidden-mobile text-muted text-sm">${c.email ?? '—'}</td>
          <td class="hidden-mobile text-muted text-sm">${c.createdAt ? new Date(c.createdAt).toLocaleDateString('en-US', { month: 'short', year: 'numeric' }) : '—'}</td>
          <td>${_clCreditsCell(c)}</td>
          <td><span class="badge badge-success">Active</span></td>
          <td onclick="event.stopPropagation()">
            <div style="display:flex;gap:4px;">
              <button class="btn btn-ghost btn-sm btn-icon" title="View profile" onclick="window.location.href='/admin/client-profile?id=${c.id}'">
                <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
              </button>
              <button class="btn btn-ghost btn-sm btn-icon" title="Edit" onclick="window.location.href='/admin/client-form?id='+encodeURIComponent('${c.id}')">
                <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.12 2.12 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
              </button>
            </div>
          </td>
        </tr>`).join('');
    }
    renderPagination();
  }

  function renderPagination() {
    const totalPages = Math.ceil(allClients.length / PAGE_SIZE);
    const ctrl = document.getElementById('paginationCtrl');
    if (totalPages <= 1) { ctrl.innerHTML = ''; return; }

    let html = '';

    // Previous button
    html += `<button class="page-btn${currentPage === 1 ? ' disabled' : ''}" ${currentPage === 1 ? 'disabled' : ''} onclick="renderPage(${currentPage - 1})" title="Previous page">‹</button>`;

    // Always show page 1
    html += `<button class="page-btn${currentPage === 1 ? ' active' : ''}" onclick="renderPage(1)">1</button>`;

    if (totalPages <= 5) {
      // Show all pages when there are 5 or fewer
      for (let i = 2; i <= totalPages; i++) {
        html += `<button class="page-btn${i === currentPage ? ' active' : ''}" onclick="renderPage(${i})">${i}</button>`;
      }
    } else {
      // Show pages 2 and 3 (or nearby pages for context)
      if (currentPage <= 3) {
        // Near the start: show 2, 3 then ellipsis
        for (let i = 2; i <= 3; i++) {
          html += `<button class="page-btn${i === currentPage ? ' active' : ''}" onclick="renderPage(${i})">${i}</button>`;
        }
        html += `<span class="page-ellipsis">…</span>`;
      } else if (currentPage >= totalPages - 2) {
        // Near the end: ellipsis then last 2 before final
        html += `<span class="page-ellipsis">…</span>`;
        for (let i = totalPages - 2; i < totalPages; i++) {
          html += `<button class="page-btn${i === currentPage ? ' active' : ''}" onclick="renderPage(${i})">${i}</button>`;
        }
      } else {
        // Middle: ellipsis, current-1, current, current+1, ellipsis
        html += `<span class="page-ellipsis">…</span>`;
        for (let i = currentPage - 1; i <= currentPage + 1; i++) {
          html += `<button class="page-btn${i === currentPage ? ' active' : ''}" onclick="renderPage(${i})">${i}</button>`;
        }
        html += `<span class="page-ellipsis">…</span>`;
      }

      // "Go to page" mini input
      html += `<span class="page-goto-wrap">
        <input type="number" class="page-goto-input" id="pageGotoInput" min="1" max="${totalPages}" placeholder="#" title="Go to page…" aria-label="Go to page">
      </span>`;

      // Always show last page
      html += `<button class="page-btn${currentPage === totalPages ? ' active' : ''}" onclick="renderPage(${totalPages})">${totalPages}</button>`;
    }

    // Next button
    html += `<button class="page-btn${currentPage === totalPages ? ' disabled' : ''}" ${currentPage === totalPages ? 'disabled' : ''} onclick="renderPage(${currentPage + 1})" title="Next page">›</button>`;

    ctrl.innerHTML = html;

    // Bind the go-to input
    const gotoInput = document.getElementById('pageGotoInput');
    if (gotoInput) {
      gotoInput.addEventListener('keydown', e => {
        if (e.key === 'Enter') {
          const p = parseInt(gotoInput.value, 10);
          if (p >= 1 && p <= totalPages) renderPage(p);
        }
      });
    }
  }

  let debounce;
  document.getElementById('searchInput').addEventListener('input', e => {
    clearTimeout(debounce);
    debounce = setTimeout(() => loadClients(e.target.value), 350);
  });

  // Pre-fill + apply the filter when arriving via the top-bar quick-search
  // "View all results" link (/admin/clients?search=…).
  const _preSearch = new URLSearchParams(location.search).get('search');
  if (_preSearch) {
    document.getElementById('searchInput').value = _preSearch;
    loadClients(_preSearch);
  } else {
    loadClients();
  }

  window.renderPage = renderPage;
</script>

