const PAGE_SIZE = 25;
let allClients = [], viewClients = [], currentPage = 1;

function loadClients(q = '') {
  fetch(`${API}/api/client?search=${encodeURIComponent(q)}`, { headers: { 'Authorization': 'Bearer ' + token } })
    .then(r => r.json()).then(data => { allClients = Array.isArray(data) ? data : []; populateCountryFilter(); applyView(1); }).catch(() => {});
}

// ── Client-side filter + sort pipeline ────────────────────────────
const _clCreditTotal = c => (c.groupCredits || 0) + (c.matCredits || 0) + (c.privateCredits || 0);

// Populate the country dropdown from the loaded set, preserving the selection.
function populateCountryFilter() {
  const sel = document.getElementById('countryFilter');
  if (!sel) return;
  const prev = sel.value;
  const countries = [...new Set(allClients.map(c => (c.country || '').trim()).filter(Boolean))]
    .sort((a, b) => a.localeCompare(b));
  sel.innerHTML = '<option value="">All countries</option>' +
    countries.map(c => `<option value="${_clEsc(c)}">${_clEsc(c)}</option>`).join('');
  if (countries.includes(prev)) sel.value = prev;
}

// Apply the active filters + sort to allClients → viewClients, then paginate.
function applyView(page = 1) {
  const tier = document.getElementById('tierFilter')?.value || '';
  const credits = document.getElementById('creditsFilter')?.value || '';
  const country = document.getElementById('countryFilter')?.value || '';
  const sort = document.getElementById('sortSelect')?.value || 'name_asc';

  let rows = allClients.filter(c => {
    if (tier === 'vip' && !(c.vipTier === 'VIP' || c.vipTier === 'SUPER_VIP')) return false;
    if (tier === 'SUPER_VIP' && c.vipTier !== 'SUPER_VIP') return false;
    if (credits === 'has' && _clCreditTotal(c) <= 0) return false;
    if (credits === 'none' && _clCreditTotal(c) > 0) return false;
    if (country && (c.country || '').trim() !== country) return false;
    return true;
  });

  const name = c => (c.name || '').toLowerCase();
  const time = c => (c.createdAt ? new Date(c.createdAt).getTime() : 0);
  const sorters = {
    name_asc: (a, b) => name(a).localeCompare(name(b)),
    name_desc: (a, b) => name(b).localeCompare(name(a)),
    newest: (a, b) => time(b) - time(a) || name(a).localeCompare(name(b)),
    oldest: (a, b) => time(a) - time(b) || name(a).localeCompare(name(b)),
    classes: (a, b) => (b.attendedClasses || 0) - (a.attendedClasses || 0) || name(a).localeCompare(name(b)),
    value: (a, b) => (b.lifetimeValue || 0) - (a.lifetimeValue || 0) || name(a).localeCompare(name(b)),
    credits: (a, b) => _clCreditTotal(b) - _clCreditTotal(a) || name(a).localeCompare(name(b)),
  };
  rows.sort(sorters[sort] || sorters.name_asc);

  viewClients = rows;
  const anyFilter = !!(tier || credits || country);
  const clearBtn = document.getElementById('clearFilters');
  if (clearBtn) clearBtn.style.display = anyFilter ? '' : 'none';
  renderPage(page);
}
window.applyView = applyView;

