            if (evt.Value.HasValue) properties["value"] = evt.Value.Value;
            if (!string.IsNullOrWhiteSpace(evt.Currency)) properties["currency"] = evt.Currency;
            if (!string.IsNullOrWhiteSpace(evt.ContentName)) properties["content_name"] = evt.ContentName;
            if (!string.IsNullOrWhiteSpace(evt.ContentCategory)) properties["content_category"] = evt.ContentCategory;
            if (evt.ContentIds is { Count: > 0 })
            {
