public async Task<bool> MarkSucceededAsync(string paymentIntentId)
{
    var record = await _payments.Find(p => p.StripePaymentIntentId == paymentIntentId).FirstOrDefaultAsync();
    if (record == null) return false;
    if (record.Status == "SUCCEEDED") return true;

    await _payments.UpdateOneAsync(p => p.Id == record.Id,
        Builders<PaymentRecord>.Update
            .Set(p => p.Status, "SUCCEEDED")
            .Set(p => p.PaidAt, DateTime.UtcNow));

    // Promote attendance from RESERVED → BOOKED
    await _attendances.UpdateOneAsync(a => a.Id == record.AttendanceId,
        Builders<Attendance>.Update.Set(a => a.Status, "BOOKED"));

    // P4-S04 — webhook-driven Stripe success. Captured at the service
    // layer (not the webhook controller) so MarkSucceededAsync remains the
    // single source of truth regardless of who triggered it.
    await _audit.LogAsync(
        action: "PAYMENT_SUCCEEDED",
        entityType: "PaymentRecord",
        entityId: record.Id!,
        metadata: new { paymentIntentId },
        after: new { record.AttendanceId, record.Amount, Status = "SUCCEEDED" });

    // ── Create invoice for online Stripe bookings ───────────────────────
    // STRIPE_FULL → PAID invoice. STRIPE_DEPOSIT → PARTIAL invoice.
    try
    {
        var attendance = await _attendances.Find(a => a.Id == record.AttendanceId).FirstOrDefaultAsync();

