cd /opt/soulpilates && docker exec soulpilates-prod-mongo mongosh -u admin -p "$(grep '^MONGO_PASSWORD=' prod.env|cut -d= -f2)" --quiet --eval '
const d=db.getSiblingDB("soulpilates");
// all attendances with AmountPaid > 0
const withPaid=d.Attendances.find({AmountPaid:{$gt:0}}).toArray();
print("attendances with AmountPaid>0: "+withPaid.length);
let phantom=[], real=[];
withPaid.forEach(a=>{
  const aid=a._id.toString();
  // real collected = any SUCCEEDED payment with Amount>0 tied to attendance (direct) or its invoice
  const inv=d.Invoices.findOne({"Lines.AttendanceId":aid});
  const payFilter={Status:"SUCCEEDED", Amount:{$gt:0}, $or:[{AttendanceId:aid}]};
  if(inv) payFilter.$or.push({InvoiceId:inv._id.toString()});
  const realPaid=d.Payments.find(payFilter).toArray().reduce((s,p)=>s+(p.Amount||0),0);
  if(realPaid>0) real.push({ref:a.BookingReference,status:a.Status}); else phantom.push({ref:a.BookingReference,status:a.Status,amt:parseFloat(a.AmountPaid)});
});
print("=> REAL payments (leave alone): "+real.length);
print("=> PHANTOM (to reset): "+phantom.length);
const byStatus={}; phantom.forEach(p=>byStatus[p.status]=(byStatus[p.status]||0)+1);
print("   phantom by status: "+JSON.stringify(byStatus));
print("   sample phantom: "+JSON.stringify(phantom.slice(0,8)));
' 2>&1

cd /opt/soulpilates && docker exec soulpilates-prod-mongo mongosh -u admin -p "$(grep '^MONGO_PASSWORD=' prod.env|cut -d= -f2)" --quiet --eval '
const d=db.getSiblingDB("soulpilates");
const withPaid=d.Attendances.find({AmountPaid:{$gt:0}}).toArray();
print("=== AmountPaid>0 breakdown by method + status ===");
const bm={}; withPaid.forEach(a=>{const k=(a.PaymentMethod||"(none)")+" / "+a.Status; bm[k]=(bm[k]||0)+1;});
Object.entries(bm).sort().forEach(([k,v])=>print("  "+k+": "+v));

// PRECISE phantom signature: Stripe method + no stripe intent + no invoice + no SUCCEEDED payment
print("=== precise phantom (STRIPE_* + StripePaymentIntentId null + no invoice + no succeeded payment) ===");
let phantom=[];
withPaid.forEach(a=>{
  if(!["STRIPE_DEPOSIT","STRIPE_FULL"].includes(a.PaymentMethod)) return;
  if(a.StripePaymentIntentId) return; // had a real intent — skip (could be paid)
  const aid=a._id.toString();
  const inv=d.Invoices.findOne({"Lines.AttendanceId":aid});
  if(inv) return; // has an invoice — real money flow, skip
  const succ=d.Payments.countDocuments({AttendanceId:aid,Status:"SUCCEEDED",Amount:{$gt:0}});
  if(succ>0) return;
  phantom.push({ref:a.BookingReference,status:a.Status,method:a.PaymentMethod,amt:parseFloat(a.AmountPaid)});
});
print("  phantom count: "+phantom.length);
const bs={}; phantom.forEach(p=>bs[p.status]=(bs[p.status]||0)+1);
print("  by status: "+JSON.stringify(bs));
print("  amounts seen: "+JSON.stringify([...new Set(phantom.map(p=>p.amt))]));
' 2>&1

