const d=db.getSiblingDB("soulpilates");
const withPaid=d.Attendances.find({AmountPaid:{$gt:0}}).toArray();
let ids=[];
withPaid.forEach(a=>{
  if(!["STRIPE_DEPOSIT","STRIPE_FULL"].includes(a.PaymentMethod)) return;
  if(a.StripePaymentIntentId) return;
  const aid=a._id.toString();
  if(d.Invoices.findOne({"Lines.AttendanceId":aid})) return;
  if(d.Payments.countDocuments({AttendanceId:aid,Status:"SUCCEEDED",Amount:{$gt:0}})>0) return;
  ids.push(a._id);
});
print("phantom records to reset: "+ids.length);
// backup first
const bk=d.Attendances.find({_id:{$in:ids}},{BookingReference:1,Status:1,PaymentMethod:1,AmountPaid:1,AmountDueAtStudio:1}).toArray();
print("BACKUP="+JSON.stringify(bk));
const res=d.Attendances.updateMany({_id:{$in:ids}},{$set:{AmountPaid:NumberDecimal("0"),AmountDueAtStudio:NumberDecimal("0")}});
print("reset: matched="+res.matchedCount+" modified="+res.modifiedCount);
// verify none of the protected sets changed
print("remaining AmountPaid>0 total: "+d.Attendances.countDocuments({AmountPaid:{$gt:0}})+" (should be 47-"+ids.length+")");
print("PAY_AT_STUDIO/ARRIVED still intact: "+d.Attendances.countDocuments({PaymentMethod:"PAY_AT_STUDIO",Status:"ARRIVED",AmountPaid:{$gt:0}}));
' 2>&1 | tee /opt/soulpilates/data/phantom-cleanup-$(date +%Y%m%d-%H%M%S).log | grep -vE "^BACKUP=" 
