const levelLabel = levelLabelMap[lvl] || lvl;

// Spots
const total = s.capacity || 10;
const booked = s.currentBookings || 0;
const spotsLeft = Math.max(0, s.spotsLeft ?? total - booked);
const ratio = booked / total;
const isFull = spotsLeft <= 0;

// Availability dots (cap at 10)
const dotCount = Math.min(total, 10);
const bookedDots = Math.round(ratio * dotCount);
let dotClass = "booked";
if (ratio >= 0.9) dotClass = "booked danger";
else if (ratio >= 0.7) dotClass = "booked warning";
let dots = "";
for (let i = 0; i < dotCount; i++) {
  dots += `<span class="sp-dot ${i < bookedDots ? dotClass : ""}"></span>`;
}

const spotsColorClass = isFull
  ? "sp-spots-danger"
  : spotsLeft <= 2
    ? "sp-spots-warning"
    : "";
const spotsText = isFull
  ? t("booking.full") || "Full"
  : `${spotsLeft} spot${spotsLeft === 1 ? "" : "s"} left`;

// Tags
const tagsHtml = (s.tags || [])
  .filter((tag) => tag && !/^SP_/i.test(tag)) // hide internal SP_* markers
  .slice(0, 3)
  .map((tag) => `<span class="sp-tag">${escapeHtml(tag)}</span>`)
  .join("");

// SPM-71 — Equipment label: join all equipment used by the class.
const equipNames = sessionEquipmentList(s);
const equipLabel = equipNames.length
  ? equipNames.map((n) => equipmentDisplayName(n)).join(", ")
  : "";

const equipIcon = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="9" width="20" height="6" rx="2"/><line x1="7" y1="9" x2="7" y2="15"/></svg>`;
const personIcon = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="7" r="4"/><path d="M5.5 21a6.5 6.5 0 0 1 13 0"/></svg>`;

