echo "=== any full future sessions in DB? ==="
docker exec soulpilates-prod-mongo mongosh -u admin -p "$(grep '^MONGO_PASSWORD=' prod.env|cut -d= -f2)" --quiet --eval '
const d=db.getSiblingDB("soulpilates");
