print("full future SCHEDULED sessions: "+full.length);
full.slice(0,5).forEach(s=>print("  "+s.StartTime.toISOString().slice(0,16)+" "+s.Format+" \""+s.ClassName+"\" "+s.CurrentBookings+"/"+s.Capacity+" id="+s._id));
' 2>&1
