curl -s "https://soulpilates.com.vn/api/booking/schedule?start=2026-08-04T00:00:00&end=2026-08-04T23:59:59&format=PRIVATE" | python3 -c "import sys,json;d=json.load(sys.stdin);print('private sessions Aug 4:',len(d));[print(f'  {(int(c[\"startTime\"][11:13])+7)%24:02d}:00 spotsLeft={c[\"spotsLeft\"]} isFull={c[\"isFull\"]}') for c in d]"

