// Context-aware Back button. From the card/payment step it returns to the
// method-selection view (booking summary, seat selection, contact details are
// all still in the DOM — nothing is reset). Only from the first step does it
// leave the page back to the booking list.
window.checkoutBack = function () {
  const card = document.getElementById("viewCard");
  const cardVisible = card && card.style.display !== "none" && card.offsetParent !== null;
  if (cardVisible) {
    card.style.display = "none";
    document.getElementById("viewMethod").style.display = "";
    try {
      window.scrollTo({ top: 0, behavior: "auto" });
    } catch (e) {
      window.scrollTo(0, 0);
    }
    return;
  }
  window.history.back();
};

