mirror("sumClass", "cardSumClass");
mirror("sumInstructor", "cardSumInstructor");
mirror("sumDateTime", "cardSumDateTime");

// Price breakdown. Falls back gracefully if the API somehow omits
// the new fields (e.g. running against an older backend mid-deploy).
// sessionFee is the PER-PERSON price; multiply by quantity for the class
// total so a multi-seat booking reads clearly (qty × price = total →
// deposit + fee = pay now, with the rest due at studio).
const cur = intentRes.currency;
const sessionFee = intentRes.sessionFee ?? intentRes.amount;
const feeAmount = intentRes.feeAmount ?? 0;
const feePct = intentRes.feePercentage ?? 0;
const dueAtStudio = intentRes.amountDueAtStudio ?? 0;
const qty = quantity || 1;
const classTotal = sessionFee * qty;
const payNow = intentRes.amount ?? 0;
const deposit = Math.max(0, payNow - feeAmount);

document.getElementById("cardSumSessionFee").textContent = fmt(sessionFee, cur);

// Quantity + class total rows only add value for multi-seat bookings.
if (qty > 1) {
  document.getElementById("cardSumQtyRow").style.display = "flex";
  document.getElementById("cardSumQty").textContent = "× " + qty;
  document.getElementById("cardSumTotalRow").style.display = "flex";
  document.getElementById("cardSumTotal").textContent = fmt(classTotal, cur);
} else {
  document.getElementById("cardSumQtyRow").style.display = "none";
  document.getElementById("cardSumTotalRow").style.display = "none";
}

// Deposit row — only for partial (deposit) payments, i.e. when a balance
// is left at the studio and the deposit is less than the full class total.
if (dueAtStudio > 0 && deposit > 0 && deposit < classTotal) {
  document.getElementById("cardSumDepositRow").style.display = "flex";
  document.getElementById("cardSumDeposit").textContent = fmt(deposit, cur);
  const pct = classTotal > 0 ? Math.round((deposit / classTotal) * 100) : 0;
  const dpEl = document.getElementById("cardSumDepositPct");
  if (dpEl) dpEl.textContent = pct > 0 ? `(${pct}%)` : "";
} else {
  document.getElementById("cardSumDepositRow").style.display = "none";
}

if (feeAmount > 0) {
  document.getElementById("cardSumFeeRow").style.display = "flex";
  document.getElementById("cardSumFee").textContent = fmt(
    feeAmount,
    intentRes.currency,
  );
  const pctEl = document.getElementById("cardSumFeePct");
  if (pctEl) pctEl.textContent = feePct > 0 ? `(${feePct}%)` : "";
} else {
  document.getElementById("cardSumFeeRow").style.display = "none";
}
if (dueAtStudio > 0) {
  document.getElementById("cardSumStudioRow").style.display = "flex";
  document.getElementById("cardSumStudio").textContent = fmt(
    dueAtStudio,
    intentRes.currency,
  );
} else {
  document.getElementById("cardSumStudioRow").style.display = "none";
}

