const cur = intentRes.currency;
const isPrivate = session?.format === "PRIVATE";
const heroImg = document.getElementById("cardHeroImg");
const imgUrl = session?.imageUrl || session?.image || "";
if (imgUrl) {
  heroImg.style.backgroundImage = `url('${imgUrl}')`;
  heroImg.classList.remove("sp-co-hero-img--empty");
} else {
  heroImg.classList.add("sp-co-hero-img--empty");
}
