  ? t("booking.privateSession") || "Private Session"
  : session?.className || "—";
document.getElementById("cardHeroInstructor").textContent =
  session?.instructorName || intent?.instructorName || "—";

const cvStart = new Date(session?.startTime || intent?.startTime);
const cvEnd = new Date(session?.endTime || intent?.endTime);
const cvTime = (dt) =>
  dt.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
document.getElementById("cardHeroDate").textContent = isNaN(cvStart)
  ? "—"
  : cvStart.toLocaleDateString(undefined, {
      weekday: "long",
      year: "numeric",
      month: "long",
      day: "numeric",
    });
document.getElementById("cardHeroTime").textContent = isNaN(cvStart)
  ? "—"
  : `${cvTime(cvStart)} – ${cvTime(cvEnd)}`;

// Amounts. sessionFee is PER-PERSON → × quantity = class total.
const qty = quantity || 1;
const sessionFee = intentRes.sessionFee ?? intentRes.amount;
const feeAmount = intentRes.feeAmount ?? 0;
const feePct = intentRes.feePercentage ?? 0;
const dueAtStudio = intentRes.amountDueAtStudio ?? 0;
const classTotal = sessionFee * qty;
const payNow = intentRes.amount ?? 0;
const deposit = Math.max(0, payNow - feeAmount);
const isDeposit = dueAtStudio > 0 && deposit > 0 && deposit < classTotal;
const depositPct = classTotal > 0 ? Math.round((deposit / classTotal) * 100) : 0;

const unit = isPrivate
  ? t("checkout.sessionsUnit") || "Private Sessions"
  : t("checkout.classesUnit") || "Group Classes";
document.getElementById("cardHeroQty").textContent = `${qty} × ${unit}`;

// Deposit callout (partial payments only).
const callout = document.getElementById("cardDepositCallout");
if (isDeposit) {
  callout.style.display = "flex";
  document.getElementById("cardDepositCalloutText").textContent =
    t("checkout.depositCallout", { pct: depositPct }) ||
    `You'll pay a ${depositPct}% deposit today. The remaining balance is paid at the studio.`;
} else {
  callout.style.display = "none";
}

// ── Payment breakdown ──
const subtotalBase = t("checkout.subtotal") || "Subtotal";
document.getElementById("cardSubtotalLabel").textContent =
  qty > 1 ? `${subtotalBase} (${qty} ${unit})` : subtotalBase;
document.getElementById("cardSubtotal").textContent = fmt(classTotal, cur);

const depRow = document.getElementById("cardDepositRow");
if (isDeposit) {
  depRow.style.display = "flex";
  document.getElementById("cardDepositPct").textContent =
    depositPct > 0 ? `(${depositPct}%)` : "";
  document.getElementById("cardDepositAmt").textContent = "−" + fmt(deposit, cur);
} else {
  depRow.style.display = "none";
}

const feeRow = document.getElementById("cardFeeRow");
if (feeAmount > 0) {
  feeRow.style.display = "flex";
  document.getElementById("cardFeePct").textContent =
    feePct > 0 ? `(${feePct}%)` : "";
  document.getElementById("cardFeeAmt").textContent = fmt(feeAmount, cur);
} else {
  feeRow.style.display = "none";
}

document.getElementById("cardPayToday").textContent = fmt(payNow, cur);

const remRow = document.getElementById("cardRemainingRow");
if (dueAtStudio > 0) {
  remRow.style.display = "flex";
  document.getElementById("cardRemaining").textContent = fmt(dueAtStudio, cur);
} else {
  remRow.style.display = "none";
}

