file.content:
.sp-summary-card {
  background: var(--sp-white);
  border: 1px solid var(--sp-border);
  border-radius: var(--sp-radius-lg);
  padding: 20px 24px;
  box-shadow: var(--sp-shadow-card);
}
.sp-summary-row {
  display: flex;
  justify-content: space-between;
  padding: 10px 0;
  border-bottom: 1px solid var(--sp-border);
  gap: 16px;
}
.sp-summary-row:last-child {
  border-bottom: none;
}
.sp-summary-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--sp-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  flex-shrink: 0;
}
.sp-summary-value {
  font-size: 14px;
  font-weight: 500;
  color: var(--sp-text-primary);
  text-align: right;
}
.sp-summary-total {
  border-top: 2px solid var(--sp-dark);
  margin-top: 8px;
  padding-top: 14px;
}
.sp-summary-amount {
  font-size: 22px;
  font-weight: 700;
  color: var(--sp-dark);

