.sp-summary-card {
  background: var(--sp-white);
  border: 1px solid var(--sp-border);
  border-radius: var(--sp-radius-lg);
  padding: 20px 24px;
  box-shadow: var(--sp-shadow-card);
}

/* ── Redesigned checkout summary (hero + payment breakdown) ── */
.sp-co-hero {
  display: flex;
  gap: 16px;
  align-items: stretch;
  background: var(--sp-brand-soft, #fdf1e7);
  border-radius: var(--sp-radius-md, 12px);
  padding: 14px;
}
.sp-co-hero-img {
  width: 132px;
  flex-shrink: 0;
  border-radius: 10px;
  background-size: cover;
  background-position: center;
  min-height: 118px;
}
.sp-co-hero-img--empty {
  background:
    radial-gradient(circle at 30% 30%, rgba(234,106,36,0.18), transparent 60%),
    var(--sp-brand-soft, #fdf1e7);
}
.sp-co-hero-info { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.sp-co-hero-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--sp-text-primary, #1a1a1a);
  line-height: 1.2;
}
.sp-co-hero-with {
  font-size: 13px;
  color: var(--sp-text-secondary, #666);
  margin-top: 2px;
}
.sp-co-accent { color: var(--sp-brand, #ea6a24); font-weight: 600; }
.sp-co-meta { margin-top: 10px; display: flex; flex-direction: column; gap: 6px; }
.sp-co-meta-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--sp-text-primary, #333);
}
.sp-co-meta-row svg {
  width: 15px; height: 15px; flex-shrink: 0;
  color: var(--sp-brand, #ea6a24);
}
.sp-co-callout {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  margin-top: 14px;
  padding: 12px 14px;
  background: var(--sp-success-soft, rgba(61,140,92,0.10));
  border: 1px solid rgba(61,140,92,0.25);
  border-radius: var(--sp-radius-md, 12px);
}
.sp-co-callout-ic {
  width: 26px; height: 26px; flex-shrink: 0;
  border-radius: 50%;
  background: var(--sp-success, #3d8c5c);
  color: #fff;
  display: flex; align-items: center; justify-content: center;
}
.sp-co-callout-ic svg { width: 15px; height: 15px; }
.sp-co-callout-title { font-size: 14px; font-weight: 700; color: var(--sp-text-primary, #1a1a1a); }
.sp-co-callout-text { font-size: 13px; color: var(--sp-text-secondary, #555); margin-top: 2px; line-height: 1.4; }

.sp-co-line {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 9px 0;
  font-size: 14px;
  color: var(--sp-text-primary, #333);
}
.sp-co-line .sp-co-accent { font-weight: 600; }
.sp-co-divider { border-top: 1px solid var(--sp-border, #eee); margin: 8px 0 4px; }
.sp-co-paytoday {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  padding-top: 8px;
}
.sp-co-paytoday-label { font-size: 15px; font-weight: 700; color: var(--sp-text-primary, #1a1a1a); }
.sp-co-paytoday-amt {
  font-size: 30px;
  font-weight: 800;
  color: var(--sp-brand, #ea6a24);
  line-height: 1.1;
  margin-top: 2px;
}
.sp-co-secure {
  display: flex; align-items: center; gap: 5px;
  font-size: 12px; font-weight: 600;
  color: var(--sp-brand, #ea6a24);
}
.sp-co-secure svg { width: 13px; height: 13px; }
.sp-co-remaining {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 14px;
  padding: 12px 14px;
  background: var(--sp-surface-raised, #f7f5f2);
  border-radius: var(--sp-radius-md, 12px);
  font-size: 14px;
  font-weight: 600;
  color: var(--sp-text-primary, #333);
}
@media (max-width: 480px) {
  .sp-co-hero-img { width: 96px; min-height: 96px; }
  .sp-co-hero-title { font-size: 16px; }
  .sp-co-paytoday-amt { font-size: 26px; }
