// Derive the whole breakdown from the INTENT — the source of truth for what
// is actually being charged — so the summary can never disagree with the
// amount. (Using the page's `quantity` variable was unsafe: if the
// reservation was created/clamped at a different seat count, the class total
// and the deposit % would be computed against the wrong base and mislead the
// customer, e.g. showing a 15% deposit for a real 30% charge.)
const sessionFee = intentRes.sessionFee ?? intentRes.amount;
const feeAmount = intentRes.feeAmount ?? 0;
const feePct = intentRes.feePercentage ?? 0;
const dueAtStudio = intentRes.amountDueAtStudio ?? 0;
const payNow = intentRes.amount ?? 0;
const deposit = Math.max(0, payNow - feeAmount);
// Full class value being booked = what's paid online (minus fee) + what's
// left for the studio. Quantity is that total divided by the per-seat price.
const classTotal = deposit + dueAtStudio;
const qty = sessionFee > 0 ? Math.max(1, Math.round(classTotal / sessionFee)) : 1;
const isDeposit = dueAtStudio > 0 && deposit > 0 && deposit < classTotal;
const depositPct = classTotal > 0 ? Math.round((deposit / classTotal) * 100) : 0;

