function initCountryPicker() {
  const hidden = document.getElementById("guestPhoneCc");
  const btn = document.getElementById("guestCcBtn");
  const panel = document.getElementById("guestCcPanel");
  const search = document.getElementById("guestCcSearch");
  const list = document.getElementById("guestCcList");
  if (!hidden || !btn || !panel || !search || !list) return;
  const btnFlag = document.getElementById("guestCcBtnFlag");
  const btnDial = document.getElementById("guestCcBtnDial");
  const esc = (s) =>
    String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

  function render(filter) {
    const q = (filter || "").trim().toLowerCase();
    const rows = SP_COUNTRIES.filter(
      (c) =>
        !q ||
        c.n.toLowerCase().includes(q) ||
        c.d.includes(q) ||
        c.d.replace("+", "").includes(q.replace("+", "")),
    );
    if (!rows.length) {
      list.innerHTML = `<li class="sp-cc-empty">${t("checkout.noCountries") || "No countries found"}</li>`;
      return;
    }
    list.innerHTML = rows
      .map(
        (c) =>
          `<li class="sp-cc-item" role="option" data-dial="${esc(c.d)}" data-flag="${esc(c.f)}"><span class="sp-cc-item-flag">${c.f}</span><span class="sp-cc-item-name">${esc(c.n)}</span><span class="sp-cc-item-dial">${esc(c.d)}</span></li>`,
      )
      .join("");
  }
  function open() {
    panel.style.display = "block";
    btn.setAttribute("aria-expanded", "true");
    search.value = "";
    render("");
    setTimeout(() => search.focus(), 0);
  }
  function close() {
    panel.style.display = "none";
    btn.setAttribute("aria-expanded", "false");
  }
  function pick(dial, flag) {
    hidden.value = dial;
    btnDial.textContent = dial;
    btnFlag.textContent = flag;
    close();
  }

  btn.addEventListener("click", (e) => {
    e.stopPropagation();
    panel.style.display === "block" ? close() : open();
  });
  search.addEventListener("input", () => render(search.value));
  search.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      const first = list.querySelector(".sp-cc-item");
      if (first) pick(first.dataset.dial, first.dataset.flag);
    } else if (e.key === "Escape") {
      close();
    }
  });
  list.addEventListener("click", (e) => {
    const item = e.target.closest(".sp-cc-item");
    if (item) pick(item.dataset.dial, item.dataset.flag);
  });
  document.addEventListener("click", (e) => {
    if (!panel.contains(e.target) && !btn.contains(e.target)) close();
  });
  render("");
}
initCountryPicker();

