public async Task<CustomerAccount> RegisterAsync(string fullName, string email, string password, string? phone, string? phoneCountryCode = null)
{
    // SPM-94: normalize the email (trim + lower-case) before any lookup or
    // persistence so new accounts are stored consistently. This is what makes
    // the case-insensitive reset lookup reliable for accounts created from here
    // onward, and it tightens the duplicate check so "Foo@x.com" and
    // "foo@x.com" can't both register.
    email = (email ?? string.Empty).Trim().ToLowerInvariant();

    // Duplicate check. SPM-94: email is force-lowercased above, but EXISTING
    // accounts may store a mixed-case email, so an exact-match equality misses
    // them and a second account is created (after which case-insensitive login
    // resolves nondeterministically). Match case-insensitively using the same
    // anchored, escaped 'i' regex LoginAsync/RequestPasswordResetAsync use.
    var emailPattern = new MongoDB.Bson.BsonRegularExpression(
        $"^{System.Text.RegularExpressions.Regex.Escape(email)}$", "i");
    var exists = await _accounts
        .Find(Builders<CustomerAccount>.Filter.Regex(a => a.Email, emailPattern))
        .FirstOrDefaultAsync();
    if (exists != null) throw new Exception("An account with this email already exists.");

    // Auto-link to existing Client record (phone first, then email).
    // P2-S13: phone may arrive in either pre-split form (e.g. "+84901234567",
    // typical for older clients), or in post-split form (e.g. national
    // "901234567" + phoneCountryCode "+84"). Match against both
    // representations.
    string? clientId = null;
    Client? linked = null;

    // Skip phone-matching for filler/placeholder numbers (e.g. 999999999,
    // 000000000, sequential): otherwise two unrelated people who both entered
    // a junk phone get linked to the SAME client and see each other's bookings.
    if (!string.IsNullOrWhiteSpace(phone) && !IsPlaceholderPhone(phone))
    {
        // Direct match against PhoneNumber (works for both forms).
        linked = await _clients.Find(c => c.PhoneNumber == phone).FirstOrDefaultAsync();

        // If we got the split form from the form, try matching the
        // (countryCode, national) pair against the entity's two fields.
        if (linked == null && !string.IsNullOrWhiteSpace(phoneCountryCode))
        {
            linked = await _clients
                .Find(c => c.PhoneCountryCode == phoneCountryCode && c.PhoneNumber == phone)
                .FirstOrDefaultAsync();
        }
    }

    if (linked == null)
        // SPM-94: email is force-lowercased above, but an EXISTING Client may
        // store a mixed-case email. An exact-match equality misses it and a
        // DUPLICATE Client gets created. Match case-insensitively with the same
        // anchored, escaped 'i' regex used for the account lookup above.
        linked = await _clients
            .Find(Builders<Client>.Filter.Regex(c => c.Email, emailPattern))
            .FirstOrDefaultAsync();

    if (linked != null)
    {
        clientId = linked.Id;
    }
    else
    {
        // Auto-create CRM Client record. Persist the split form when we
        // have it; otherwise fall back to dumping the raw value into
        // PhoneNumber (the migration command can split it later).
        var newClient = new Client
        {
            FullName = fullName,
            Email = email,
            PhoneNumber = phone,
            PhoneCountryCode = phoneCountryCode,
            ContactPlatform = "EMAIL"
        };
        await _clients.InsertOneAsync(newClient);
        clientId = newClient.Id;
    }

    var emailVerifyEnabled = await IsEmailVerifyEnabledAsync();
    var verificationToken = Guid.NewGuid().ToString("N");
    var account = new CustomerAccount
    {
        FullName = fullName,
        Email = email,
        PasswordHash = PasswordHasher.Hash(password),
        // CustomerAccount keeps a single phone field (not split) — it's
        // primarily the contact channel, not a CRM record. The CRM
        // Client carries the split form.
        PhoneNumber = phone,
        ClientId = clientId,
        // If email verify is disabled, auto-verify; otherwise send email
        EmailVerified = !emailVerifyEnabled,
        EmailVerificationToken = emailVerifyEnabled ? verificationToken : null,
        EmailVerificationExpiry = emailVerifyEnabled ? DateTime.UtcNow.AddHours(24) : null
    };

