private static bool IsPlaceholderPhone(string? phone)
{
    var digits = new string((phone ?? string.Empty).Where(char.IsDigit).ToArray());
    if (digits.Length < 7) return true;               // too short to be a real mobile
    if (digits.Distinct().Count() == 1) return true;  // all same digit (000..., 999...)
    if (digits is "1234567890" or "0123456789" or "123456789" or "12345678" or "1234567")
        return true;                                  // common sequential fillers
    return false;
}

/// <summary>
/// Consume a password-reset token and rotate the user's password.
/// Returns <c>false</c> for any failure mode (missing / expired / re-used
/// token, or password under the 8-char minimum) so the caller can surface
/// a single generic error. On success the token + expiry are cleared,
/// guaranteeing single use.
/// </summary>
public async Task<bool> ResetPasswordAsync(string token, string newPassword)
{
    if (string.IsNullOrWhiteSpace(token)) return false;
    if (string.IsNullOrWhiteSpace(newPassword) || newPassword.Length < 8) return false;

    var account = await _accounts.Find(a =>
        a.PasswordResetToken == token &&
        a.PasswordResetExpiry > DateTime.UtcNow
    ).FirstOrDefaultAsync();

