/// so numbers stored as "901234567" and "+84901234567" compare equal.</summary>
private static string SignificantPhoneDigits(string? raw)
{
    var digits = new string((raw ?? string.Empty).Where(char.IsDigit).ToArray());
    return digits.Length > 9 ? digits[^9..] : digits;
}

/// <summary>
/// Returns which identifier (<c>"email"</c> or <c>"phone"</c>) already belongs to
/// a registered <see cref="CustomerAccount"/>, or <c>null</c> if neither does.
/// Used to steer a guest who already has an account toward logging in instead of
/// booking as a guest (and creating a confusing duplicate). Email match is
/// case-insensitive exact; phone match is by significant digits.
/// </summary>
public async Task<string?> MatchExistingAccountAsync(string? email, string? phone)
{
    if (!string.IsNullOrWhiteSpace(email))
    {
        var pat = new MongoDB.Bson.BsonRegularExpression(
            $"^{System.Text.RegularExpressions.Regex.Escape(email.Trim())}$", "i");
        var byEmail = await _accounts
            .Find(Builders<CustomerAccount>.Filter.Regex(a => a.Email, pat))
            .AnyAsync();
        if (byEmail) return "email";
    }

    if (!string.IsNullOrWhiteSpace(phone) && !IsPlaceholderPhone(phone))
    {
        var target = SignificantPhoneDigits(phone);
        if (!string.IsNullOrEmpty(target))
        {
            var accountPhones = await _accounts
                .Find(Builders<CustomerAccount>.Filter.And(
                    Builders<CustomerAccount>.Filter.Ne(a => a.PhoneNumber, null),
                    Builders<CustomerAccount>.Filter.Ne(a => a.PhoneNumber, "")))
                .Project(a => a.PhoneNumber)
                .ToListAsync();
            if (accountPhones.Any(p => SignificantPhoneDigits(p) == target)) return "phone";
        }
    }

    return null;
}

