namespace SoulPilates.API.Controllers;

[ApiController]
[Route("api/[controller]")]
// NOTE: auth is per-action. Public booking-funnel endpoints are marked
// [AllowAnonymous] individually; the protected ones carry [Authorize]. A
// class-level [AllowAnonymous] used to sit here and silently overrode every
// method-level [Authorize] (ASP0026), exposing the Admin waitlist PII endpoint.
public class BookingController : ControllerBase
{
    private readonly ISchedulingService _schedulingService;
    private readonly IClientService _clientService;
    private readonly IWalletService _walletService;
    // P4-S02 — Waitlist surface for the customer portal + admin visibility.
    private readonly IWaitlistService _waitlistService;

    public BookingController(
        ISchedulingService schedulingService,
        IClientService clientService,
        IWalletService walletService,
        IWaitlistService waitlistService)
    {
        _schedulingService = schedulingService;
        _clientService = clientService;
        _walletService = walletService;
        _waitlistService = waitlistService;
    }

