  // Guest already has an account → steer them to log in.
  if (_err && _err.requiresLogin) {
    revealGuestContactForm();
    showGuestError(
      _err.message ||
        t("checkout.accountExists") ||
        "You already have an account. Please log in to book.",
    );
    btn.disabled = false;
    btn.querySelector("span").textContent = getContinueBtnLabel();
    const _here =
      window.location.pathname + window.location.search;
    setTimeout(() => {
      window.location.href =
        "/login?redirect=" + encodeURIComponent(_here);
    }, 2200);
    return;
  }
  throw new Error(_err.message);
}

