using SoulPilates.Core.Interfaces;
using SoulPilates.Core.Notifications;

namespace SoulPilates.Core.Interfaces;

/// <summary>
/// High-level façade that the rest of the codebase calls. Encapsulates the
/// "push first, email fallback" policy so callers don't need to know about
/// VAPID, channels, or preference matrices — they just say "publish a
/// NewBooking to this instructor".
/// </summary>
public interface INotificationPublisher
{
    /// <summary>
    /// Publish a notification to a single user. The publisher consults the
    /// per-role + per-user preference matrix (Slice E) to decide whether to
    /// push, email both, or skip. Always non-throwing — observability is
    /// via logs.
    /// </summary>
    /// <param name="userId">Target user (admin / instructor / staff).</param>
    /// <param name="category">What kind of event this is. Drives prefs.</param>
    /// <param name="payload">
    /// The exact push payload (title/body/url/tag). The email subject/body
    /// are derived from title+body when fallback fires.
    /// </param>
    Task PublishAsync(string userId, NotificationCategory category, PushPayload payload);

    /// <summary>Convenience for "fan out to every active user in role(s)".</summary>
    Task PublishToRolesAsync(IEnumerable<string> roles, NotificationCategory category, PushPayload payload);
}
