  const atts=d.Attendances.find({CalendarSessionId:c._id, Status:{$in:["CHECKED_IN","ARRIVED"]}}).toArray();
  // paid = package credit (PaymentMethod PACKAGE_CREDIT) OR money (AmountPaid>0 or an invoice/payment)
  const paid=atts.some(a=> a.PaymentMethod==="PACKAGE_CREDIT" || (a.AmountPaid && parseFloat(a.AmountPaid)>0) || a.IsFreeClass===false && a.PaymentMethod);
