window.spTiktokTrack = function (eventName, customData, userData) {
  customData = customData || {};
  userData = userData || {};
  // Advanced-matching fallback: for a logged-in customer, attach their
  // email/phone to EVERY event (PageView, ViewContent, …) so returning
  // visitors are matched, not just at Purchase. Improves match quality and
  // reduces TikTok's "email/phone missing" diagnostic. Anonymous visitors
  // legitimately have none until they identify at checkout.
  try {
    if (!userData.email) {
      var _em = localStorage.getItem('customer_email');
      if (_em) userData.email = _em;
    }
    if (!userData.phone) {
      var _ph = localStorage.getItem('customer_phone');
      if (_ph) userData.phone = _ph;
    }
  } catch (e) {}
  var ttEvent = EVENT_MAP[eventName] || eventName;
  var eventId = uuid();

