// logical errors, so inspect the body rather than only the status. Parse
// the numeric code (tolerating whitespace like "code": 0) — a naive string
// match on "code":0 mis-flagged genuine successes as failures.
var codeMatch = System.Text.RegularExpressions.Regex.Match(body, "\"code\"\\s*:\\s*(-?\\d+)");
var codeOk = !codeMatch.Success || codeMatch.Groups[1].Value == "0";
if (!resp.IsSuccessStatusCode || !codeOk)
{
    _logger.LogWarning("TikTok Events API event {Event} failed: {Status} {Body}",
        evt.EventName, (int)resp.StatusCode, body);
}

