using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.Services;

/// <summary>
/// TikTok Events API sender. Config lives in the "TiktokTracking" section
/// (env: <c>TiktokTracking__PixelCode</c>, <c>TiktokTracking__AccessToken</c>,
/// <c>TiktokTracking__TestEventCode</c>, <c>TiktokTracking__Enabled</c>) — the
/// same env-secret pattern as Meta/SMTP/Stripe, so the access token never
/// touches the DB or any API response.
/// </summary>
public class TiktokEventsService : ITiktokEventsService
{
    // TikTok Business Events API v1.3.
    private const string EventsApiUrl = "https://business-api.tiktok.com/open_api/v1.3/event/track/";

    private readonly HttpClient _http;
    private readonly ILogger<TiktokEventsService> _logger;
    private readonly bool _enabled;
    private readonly string _pixelCode;
    private readonly string _accessToken;
    private readonly string _testEventCode;

    public TiktokEventsService(HttpClient http, IConfiguration config, ILogger<TiktokEventsService> logger)
    {
        _http = http;
        _logger = logger;
        var section = config.GetSection("TiktokTracking");
        _pixelCode = section["PixelCode"] ?? "";
        _accessToken = section["AccessToken"] ?? "";
        _testEventCode = section["TestEventCode"] ?? "";
        _enabled = bool.TryParse(section["Enabled"], out var e) ? e : true;
    }

    public bool IsEnabled =>
        _enabled && !string.IsNullOrWhiteSpace(_pixelCode) && !string.IsNullOrWhiteSpace(_accessToken);

    // Browser Pixel needs only the code — Events API (IsEnabled) additionally needs the
    // token, so the client-side Pixel can go live before the server-side token is added.
    public bool BrowserEnabled => _enabled && !string.IsNullOrWhiteSpace(_pixelCode);

    public string PixelCode => _pixelCode;

    public async Task SendEventAsync(TiktokConversionEvent evt, CancellationToken ct = default)
    {
        if (!IsEnabled) return;

        try
        {
            var user = new Dictionary<string, object?>();
            var hashedEmail = HashNormalized(evt.Email);
            if (hashedEmail != null) user["email"] = hashedEmail;
            var hashedPhone = HashPhone(evt.Phone);
            if (hashedPhone != null) user["phone"] = hashedPhone;
            if (!string.IsNullOrWhiteSpace(evt.Ttp)) user["ttp"] = evt.Ttp;
            if (!string.IsNullOrWhiteSpace(evt.Ttclid)) user["ttclid"] = evt.Ttclid;
            if (!string.IsNullOrWhiteSpace(evt.ClientIpAddress)) user["ip"] = evt.ClientIpAddress;
            if (!string.IsNullOrWhiteSpace(evt.ClientUserAgent)) user["user_agent"] = evt.ClientUserAgent;

            var properties = new Dictionary<string, object?>();
            if (evt.Value.HasValue) properties["value"] = evt.Value.Value;
            if (!string.IsNullOrWhiteSpace(evt.Currency)) properties["currency"] = evt.Currency;
            if (!string.IsNullOrWhiteSpace(evt.ContentName)) properties["content_name"] = evt.ContentName;
            if (!string.IsNullOrWhiteSpace(evt.ContentCategory)) properties["content_category"] = evt.ContentCategory;
            if (evt.ContentIds is { Count: > 0 })
            {
                properties["contents"] = evt.ContentIds
                    .Select(id => new Dictionary<string, object?>
                    {
                        ["content_id"] = id,
                        ["content_type"] = "product",
                        ["content_name"] = evt.ContentName,
                    })
                    .ToList();
            }

            var data = new Dictionary<string, object?>
            {
                ["event"] = evt.EventName,
                ["event_time"] = DateTimeOffset.UtcNow.ToUnixTimeSeconds(),
                ["event_id"] = evt.EventId,
                ["user"] = user,
            };
            if (!string.IsNullOrWhiteSpace(evt.EventSourceUrl))
                data["page"] = new Dictionary<string, object?> { ["url"] = evt.EventSourceUrl };
            if (properties.Count > 0) data["properties"] = properties;

            var payload = new Dictionary<string, object?>
            {
                ["event_source"] = "web",
                ["event_source_id"] = _pixelCode,
                ["data"] = new[] { data },
            };
            if (!string.IsNullOrWhiteSpace(_testEventCode)) payload["test_event_code"] = _testEventCode;

            var json = JsonSerializer.Serialize(payload);
            using var content = new StringContent(json, Encoding.UTF8, "application/json");
            using var request = new HttpRequestMessage(HttpMethod.Post, EventsApiUrl) { Content = content };
            request.Headers.Add("Access-Token", _accessToken);

            var resp = await _http.SendAsync(request, ct);
            var body = await resp.Content.ReadAsStringAsync(ct);
            // TikTok returns HTTP 200 with a JSON body whose "code" is non-zero on
            // logical errors, so inspect the body rather than only the status.
            if (!resp.IsSuccessStatusCode || body.Contains("\"code\":") && !body.Contains("\"code\":0"))
            {
                _logger.LogWarning("TikTok Events API event {Event} failed: {Status} {Body}",
                    evt.EventName, (int)resp.StatusCode, body);
            }
        }
        catch (Exception ex)
        {
            // Tracking must never break the funnel — log and move on.
            _logger.LogWarning(ex, "TikTok Events API send threw for event {Event}", evt.EventName);
        }
    }

    /// <summary>SHA-256 of a trimmed, lower-cased string. Null/blank → null.</summary>
    private static string? HashNormalized(string? raw)
    {
        if (string.IsNullOrWhiteSpace(raw)) return null;
        return Sha256Hex(raw.Trim().ToLowerInvariant());
    }

    /// <summary>Phone normalised to digits only (keeps country code) before hashing.</summary>
    private static string? HashPhone(string? raw)
    {
        if (string.IsNullOrWhiteSpace(raw)) return null;
        var digits = new string(raw.Where(char.IsDigit).ToArray());
        return string.IsNullOrEmpty(digits) ? null : Sha256Hex(digits);
    }

    private static string Sha256Hex(string input)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(input));
        var sb = new StringBuilder(bytes.Length * 2);
        foreach (var b in bytes) sb.Append(b.ToString("x2"));
        return sb.ToString();
    }
}

