using MongoDB.Bson.Serialization.Attributes;
using MongoDB.Bson.Serialization.Options;

namespace SoulPilates.Core.Entities;

/// <summary>
/// V2 Schedule — Studio operating hours with company-wide hours, holidays,
/// and per-date overrides. Embedded as a sub-document on
/// <see cref="GlobalSettings.CompanySchedule"/>.
///
/// <para><b>Company Hours</b> (<see cref="WeeklyHours"/>): Studio-wide
/// open/close per day of week. A missing key means closed. Supports multi-window
/// hours for break periods.</para>
/// </summary>
public class CompanyScheduleConfig
{
    // ── Company-Wide Hours ─────────────────────────────────────────

    /// <summary>
    /// Studio operating hours per day of week.
    /// Key: <see cref="DayOfWeek"/> as int (0=Sunday … 6=Saturday).
    /// Value: <see cref="DayHours"/> with Open/Close or multi-window.
    /// A missing key means the studio is CLOSED on that day of week.
    /// </summary>
    [BsonDictionaryOptions(DictionaryRepresentation.ArrayOfDocuments)]
    public Dictionary<int, DayHours> WeeklyHours { get; set; } = new();

    /// <summary>
    /// Named holidays when the studio is fully closed.
    /// Materialiser skips these dates; calendar shows a full-day banner.
    /// </summary>
    public List<HolidayEntry> Holidays { get; set; } = new();

    /// <summary>
    /// Specific dates with modified operating hours (e.g., half-days before holidays).
    /// Takes precedence over WeeklyHours for that date.
    /// </summary>
    public List<DateOverride> DateOverrides { get; set; } = new();
}

// ── Time-Window Entities ─────────────────────────────────────────────────

/// <summary>
/// A single contiguous time window within a day. Studio-local "HH:mm" (24h).
/// Used by <see cref="DayHours.Windows"/> to express non-contiguous hours
/// (e.g., morning + afternoon with a lunch break).
/// </summary>
public class TimeWindow
{
    /// <summary>Window opening time, e.g. "07:00".</summary>
    public string Open { get; set; } = "07:00";

    /// <summary>Window closing time, e.g. "12:00". Must be after <see cref="Open"/>.</summary>
    public string Close { get; set; } = "21:00";
}

/// <summary>
/// Open/close hours for a single day. Supports two modes:
/// <list type="bullet">
/// <item><b>Single-window</b>: Use <see cref="Open"/>/<see cref="Close"/> only.
///   This is the V2 backward-compatible path (existing data works as-is).</item>
/// <item><b>Multi-window</b>: Populate <see cref="Windows"/>. When non-empty,
///   this list takes precedence over Open/Close, allowing breaks (e.g., lunch closure).
///   Example: [{ "07:00"→"12:00" }, { "13:00"→"21:00" }]</item>
/// </list>
/// </summary>
public class DayHours
{
    /// <summary>Studio opening time, e.g. "07:00". Used in single-window mode.</summary>
    public string Open { get; set; } = "07:00";

    /// <summary>Studio closing time, e.g. "21:00". Used in single-window mode.</summary>
    public string Close { get; set; } = "21:00";

    /// <summary>
    /// Multi-window mode: if populated and non-empty, these windows override the
    /// single Open/Close pair. Allows non-contiguous hours (lunch breaks, split shifts).
    /// Null or empty = use single-window mode (Open/Close).
    /// </summary>
    public List<TimeWindow>? Windows { get; set; }
}

// ── Holiday & Date Override ──────────────────────────────────────────────

/// <summary>
/// A named date when the studio is fully closed (no classes materialise,
/// calendar shows a banner).
/// </summary>
public class HolidayEntry
{
    /// <summary>ISO "yyyy-MM-dd" date string.</summary>
    public string Date { get; set; } = "";

    /// <summary>Human-readable label, e.g. "Christmas", "Lunar New Year".</summary>
    public string Label { get; set; } = "";
}

/// <summary>
/// A specific date with modified operating hours. Overrides the standard
/// <see cref="CompanyScheduleConfig.WeeklyHours"/> for that day.
/// Supports multi-window hours for break periods on override dates.
/// </summary>
public class DateOverride
{
    /// <summary>ISO "yyyy-MM-dd" date string.</summary>
    public string Date { get; set; } = "";

    /// <summary>Modified opening time, e.g. "07:00". Used in single-window mode.</summary>
    public string Open { get; set; } = "07:00";

    /// <summary>Modified closing time, e.g. "15:00". Used in single-window mode.</summary>
    public string Close { get; set; } = "21:00";

    /// <summary>
    /// Multi-window mode for override dates. When non-empty, overrides Open/Close.
    /// </summary>
    public List<TimeWindow>? Windows { get; set; }

    /// <summary>Optional note, e.g. "Christmas Eve early close".</summary>
    public string? Note { get; set; }
}

