using MongoDB.Bson.Serialization.Attributes;

namespace SoulPilates.Core.Entities;

/// <summary>
/// A staff work shift. Modeled like a Google-Calendar event: either a
/// <b>recurring</b> weekly shift (repeats on a <see cref="DayOfWeek"/>) or a
/// <b>one-off</b> shift on a single <see cref="SpecificDate"/>. Recurring shifts
/// can be bounded (<see cref="ValidFrom"/>/<see cref="ValidTo"/>) and can skip
/// individual occurrences via <see cref="ExceptionDates"/> — so a single day can
/// be removed or overridden (an override = an exception + a one-off shift for
/// that date) without touching the series.
///
/// Times are studio-local "HH:mm" (24h), Asia/Ho_Chi_Minh. Lunch/other breaks
/// live in <see cref="Breaks"/> and render as gaps inside the shift block.
/// </summary>
public class StaffShift : BaseEntity
{
    /// <summary>The staff member this shift belongs to.</summary>
    [BsonRepresentation(MongoDB.Bson.BsonType.ObjectId)]
    public string StaffId { get; set; } = null!;

    /// <summary>Denormalised staff name for calendar display without a join.</summary>
    public string? StaffName { get; set; }

    /// <summary>Optional label, e.g. "Teaching", "Reception", "Admin".</summary>
    public string? Label { get; set; }

    /// <summary>Hex colour for the calendar block. Defaults to the brand accent.</summary>
    public string Color { get; set; } = "#EA6A24";

    /// <summary>True = repeats weekly on <see cref="DayOfWeek"/>; false = one-off on <see cref="SpecificDate"/>.</summary>
    public bool IsRecurring { get; set; } = true;

    /// <summary>Day of week for a recurring shift. 0=Sunday … 6=Saturday.</summary>
    public int DayOfWeek { get; set; }

    /// <summary>ISO "yyyy-MM-dd" for a one-off shift (used when not recurring).</summary>
    public string? SpecificDate { get; set; }

    /// <summary>Shift start, local "HH:mm".</summary>
    public string StartTime { get; set; } = "08:00";

    /// <summary>Shift end, local "HH:mm". Must be after <see cref="StartTime"/>.</summary>
    public string EndTime { get; set; } = "17:00";

    /// <summary>Breaks within the shift (e.g. lunch 12:00–13:00). Reuses the schedule TimeWindow shape.</summary>
    public List<TimeWindow> Breaks { get; set; } = new();

    /// <summary>Optional recurrence start bound, ISO "yyyy-MM-dd". Null = no lower bound.</summary>
    public string? ValidFrom { get; set; }

    /// <summary>Optional recurrence end bound, ISO "yyyy-MM-dd". Null = open-ended.</summary>
    public string? ValidTo { get; set; }

    /// <summary>Dates ("yyyy-MM-dd") where this recurring shift is skipped (deleted/overridden occurrence).</summary>
    public List<string> ExceptionDates { get; set; } = new();
}

