import AdminLayout from '../../layouts/AdminLayout.astro';
---
<AdminLayout title="Staff Schedule" activePage="staff-schedule" accessModules="staff,owners">

  <div class="page-header">
    <div>
      <div class="page-title">Staff Schedule</div>
      <div class="page-subtitle">Working hours, lunch breaks & shifts — recurring weekly or one-off.</div>
    </div>
    <button class="btn btn-primary" id="addShiftBtn">
      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
      Add Shift
    </button>
  </div>

  <div class="card" style="margin-bottom:14px;">
    <div class="card-body" style="padding:12px 16px;display:flex;align-items:center;gap:12px;flex-wrap:wrap;">
      <div style="display:flex;align-items:center;gap:6px;">
        <button class="btn btn-ghost btn-sm" id="prevWeek" title="Previous week">‹</button>
        <button class="btn btn-ghost btn-sm" id="todayBtn">Today</button>
        <button class="btn btn-ghost btn-sm" id="nextWeek" title="Next week">›</button>
      </div>
      <strong id="weekLabel" style="font-size:15px;">—</strong>
      <label class="text-sm text-muted" style="margin-left:auto;display:inline-flex;align-items:center;gap:6px;">
        Staff
        <select id="staffFilter" class="form-control" style="height:34px;padding:2px 8px;font-size:13px;width:auto;">
          <option value="">All staff</option>
        </select>
      </label>
    </div>
  </div>

  <div class="card">
    <div class="card-body" style="padding:0;overflow-x:auto;">
      <div id="schedGrid" class="ssched-grid"></div>
    </div>
  </div>

  <!-- Add/Edit shift modal -->
  <div id="shiftModal" class="ssched-modal-backdrop" style="display:none;">
    <div class="ssched-modal">
      <div class="ssched-modal-head">
        <span id="shiftModalTitle">Add Shift</span>
        <button class="ssched-modal-x" id="shiftModalClose">✕</button>
      </div>
      <div class="ssched-modal-body">
        <input type="hidden" id="shiftId" />

        <label class="ssched-lbl">Staff member</label>
        <select id="fStaff" class="form-control"></select>

        <label class="ssched-lbl">Repeats</label>
        <div class="ssched-seg">
          <button type="button" class="ssched-seg-btn active" data-repeat="weekly">Weekly</button>
          <button type="button" class="ssched-seg-btn" data-repeat="oneoff">One-off date</button>
        </div>

        <div id="weeklyRow">
          <label class="ssched-lbl">Day of week</label>
          <select id="fDay" class="form-control">
            <option value="1">Monday</option><option value="2">Tuesday</option>
            <option value="3">Wednesday</option><option value="4">Thursday</option>
            <option value="5">Friday</option><option value="6">Saturday</option>
            <option value="0">Sunday</option>
          </select>
        </div>
        <div id="oneoffRow" style="display:none;">
          <label class="ssched-lbl">Date</label>
          <input type="date" id="fDate" class="form-control" />
        </div>

        <div class="ssched-2col">
          <div><label class="ssched-lbl">Start</label><input type="time" id="fStart" class="form-control" value="08:00" /></div>
          <div><label class="ssched-lbl">End</label><input type="time" id="fEnd" class="form-control" value="17:00" /></div>
        </div>

        <label class="ssched-lbl">Breaks (e.g. lunch)</label>
        <div id="breaksList"></div>
        <button type="button" class="btn btn-ghost btn-sm" id="addBreakBtn">+ Add break</button>

        <div class="ssched-2col">
          <div><label class="ssched-lbl">Label (optional)</label><input type="text" id="fLabel" class="form-control" placeholder="e.g. Reception" /></div>
          <div><label class="ssched-lbl">Colour</label><input type="color" id="fColor" class="form-control" value="#EA6A24" style="height:38px;padding:2px;" /></div>
        </div>

        <div id="validRow" class="ssched-2col">
          <div><label class="ssched-lbl">Starts on (optional)</label><input type="date" id="fValidFrom" class="form-control" /></div>
          <div><label class="ssched-lbl">Ends on (optional)</label><input type="date" id="fValidTo" class="form-control" /></div>
        </div>

        <div class="ssched-err" id="shiftErr"></div>
      </div>
      <div class="ssched-modal-foot">
        <button class="btn btn-ghost" id="skipDayBtn" style="display:none;margin-right:auto;">Remove just this day</button>
        <button class="btn btn-ghost" id="deleteShiftBtn" style="display:none;color:var(--color-danger);">Delete</button>
        <button class="btn btn-primary" id="saveShiftBtn">Save</button>
      </div>
    </div>
  </div>

</AdminLayout>

<style>
  .ssched-grid { display: grid; grid-template-columns: 56px repeat(7, minmax(120px, 1fr)); min-width: 900px; }
