  .ssched-daycol { position: relative; border-right: 1px solid var(--color-border-subtle); cursor: pointer; }
  .ssched-daycol .ssched-hourline { height: 44px; border-bottom: 1px solid var(--color-border-subtle); box-sizing: border-box; }
