    }
    // time gutter
    let gutter = '<div class="ssched-timegutter">';
    for (let h = DAY_START; h < DAY_END; h++) gutter += `<div class="ssched-hour">${h}:00</div>`;
    gutter += '</div>';
    html += gutter;
    // day columns
    for (let i = 0; i < 7; i++) {
      const d = addDays(weekStart, i);
      const dIso = iso(d);
      let col = `<div class="ssched-daycol" data-date="${dIso}" data-dow="${d.getDay()}">`;
      for (let h = DAY_START; h < DAY_END; h++) col += '<div class="ssched-hourline"></div>';
      occ.filter(o => o.date === dIso).forEach(o => {
        const s = Math.max(DAY_START*60, toMin(o.startTime));
        const e = Math.min(DAY_END*60, toMin(o.endTime));
        const top = (s - DAY_START*60) / 60 * HOUR_PX;
        const hgt = Math.max(16, (e - s) / 60 * HOUR_PX);
        let breaks = '';
        (o.breaks || []).forEach(b => {
          const bs = Math.max(s, toMin(b.open)), be = Math.min(e, toMin(b.close));
          if (be <= bs) return;
          const bt = (bs - s) / 60 * HOUR_PX, bh = (be - bs) / 60 * HOUR_PX;
          breaks += `<div class="ssched-break" style="top:${bt}px;height:${bh}px;line-height:${Math.max(8,bh)}px;">${bh>14?'Break':''}</div>`;
        });
        col += `<div class="ssched-block" style="top:${top}px;height:${hgt}px;background:${esc(o.color||'#EA6A24')};"
            data-shift='${esc(JSON.stringify(o))}'>
            <div class="bt">${esc(o.staffName||'')}</div>
            <div class="bh">${esc(o.startTime)}–${esc(o.endTime)}${o.label?' · '+esc(o.label):''}</div>
            ${breaks}
          </div>`;
      });
      col += '</div>';
      html += col;
    }
    grid.innerHTML = html;

    grid.querySelectorAll('.ssched-daycol').forEach(c => c.addEventListener('click', (ev) => {
      if (ev.target.closest('.ssched-block')) return;
      openAdd(c.dataset.date, Number(c.dataset.dow));
    }));
    grid.querySelectorAll('.ssched-block').forEach(b => b.addEventListener('click', (ev) => {
      ev.stopPropagation();
      openEdit(JSON.parse(b.dataset.shift));
    }));
  }

  // ── Modal ──
  const modal = document.getElementById('shiftModal');
  let repeatMode = 'weekly';
  let editingOccurrenceDate = null;

  function renderBreaks() {
    document.getElementById('breaksList').innerHTML = breaksDraft.map((b, i) =>
      `<div class="ssched-break-row">
        <input type="time" class="form-control brk-open" data-i="${i}" value="${b.open}" />
        <input type="time" class="form-control brk-close" data-i="${i}" value="${b.close}" />
        <button type="button" class="btn btn-ghost btn-sm brk-del" data-i="${i}">✕</button>
      </div>`).join('');
    document.querySelectorAll('.brk-del').forEach(el => el.addEventListener('click', () => { breaksDraft.splice(Number(el.dataset.i),1); renderBreaks(); }));
    document.querySelectorAll('.brk-open').forEach(el => el.addEventListener('change', () => breaksDraft[Number(el.dataset.i)].open = el.value));
    document.querySelectorAll('.brk-close').forEach(el => el.addEventListener('change', () => breaksDraft[Number(el.dataset.i)].close = el.value));
  }

  function setRepeat(mode) {
    repeatMode = mode;
    document.querySelectorAll('.ssched-seg-btn').forEach(b => b.classList.toggle('active', b.dataset.repeat === mode));
    document.getElementById('weeklyRow').style.display = mode === 'weekly' ? '' : 'none';
    document.getElementById('oneoffRow').style.display = mode === 'oneoff' ? '' : 'none';
    document.getElementById('validRow').style.display = mode === 'weekly' ? '' : 'none';
  }

  function openAdd(dateIso, dow) {
    document.getElementById('shiftModalTitle').textContent = 'Add Shift';
    document.getElementById('shiftId').value = '';
    document.getElementById('fStaff').selectedIndex = 0;
    setRepeat('weekly');
    document.getElementById('fDay').value = String(dow);
    document.getElementById('fDate').value = dateIso;
    document.getElementById('fStart').value = '08:00';
    document.getElementById('fEnd').value = '17:00';
    document.getElementById('fLabel').value = '';
    document.getElementById('fColor').value = '#EA6A24';
    document.getElementById('fValidFrom').value = '';
    document.getElementById('fValidTo').value = '';
    breaksDraft = [{ open: '12:00', close: '13:00' }];
    editingOccurrenceDate = null;
    document.getElementById('deleteShiftBtn').style.display = 'none';
    document.getElementById('skipDayBtn').style.display = 'none';
    renderBreaks(); showErr(''); modal.style.display = 'flex';
  }

  async function openEdit(o) {
    // Fetch the raw shift to edit the whole series accurately.
    let raw = null;
    try {
      const r = await fetch(`${API}/api/staff-shifts/raw`, H);
      raw = (await r.json()).find(s => s.id === o.shiftId);
    } catch (e) {}
    if (!raw) return;
    document.getElementById('shiftModalTitle').textContent = 'Edit Shift';
    document.getElementById('shiftId').value = raw.id;
    document.getElementById('fStaff').value = raw.staffId;
    setRepeat(raw.isRecurring ? 'weekly' : 'oneoff');
    document.getElementById('fDay').value = String(raw.dayOfWeek);
    document.getElementById('fDate').value = raw.specificDate || o.date;
    document.getElementById('fStart').value = raw.startTime;
    document.getElementById('fEnd').value = raw.endTime;
    document.getElementById('fLabel').value = raw.label || '';
    document.getElementById('fColor').value = raw.color || '#EA6A24';
    document.getElementById('fValidFrom').value = raw.validFrom || '';
    document.getElementById('fValidTo').value = raw.validTo || '';
    breaksDraft = (raw.breaks || []).map(b => ({ open: b.open, close: b.close }));
    editingOccurrenceDate = o.date;
    document.getElementById('deleteShiftBtn').style.display = '';
    document.getElementById('skipDayBtn').style.display = raw.isRecurring ? '' : 'none';
    renderBreaks(); showErr(''); modal.style.display = 'flex';
  }

  function showErr(m) { document.getElementById('shiftErr').textContent = m || ''; }

  function collect() {
    const isRecurring = repeatMode === 'weekly';
    return {
      staffId: document.getElementById('fStaff').value,
      isRecurring,
      dayOfWeek: Number(document.getElementById('fDay').value),
      specificDate: isRecurring ? null : document.getElementById('fDate').value,
      startTime: document.getElementById('fStart').value,
      endTime: document.getElementById('fEnd').value,
      breaks: breaksDraft.filter(b => b.open && b.close),
      label: document.getElementById('fLabel').value || null,
      color: document.getElementById('fColor').value,
      validFrom: isRecurring ? (document.getElementById('fValidFrom').value || null) : null,
      validTo: isRecurring ? (document.getElementById('fValidTo').value || null) : null,
    };
  }

  async function save() {
    const id = document.getElementById('shiftId').value;
    const body = collect();
    if (!body.staffId) return showErr('Choose a staff member.');
    if (body.endTime <= body.startTime) return showErr('End time must be after start time.');
    try {
      const res = id
        ? await fetch(`${API}/api/staff-shifts/${id}`, { method: 'PUT', headers: { ...H.headers, 'Content-Type': 'application/json' }, body: JSON.stringify(body) })
        : await fetch(`${API}/api/staff-shifts`, { method: 'POST', headers: { ...H.headers, 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
      if (!res.ok) return showErr((await res.json().catch(()=>({}))).message || 'Could not save.');
      modal.style.display = 'none'; loadWeek();
    } catch (e) { showErr('Network error.'); }
  }

  document.getElementById('addShiftBtn').addEventListener('click', () => openAdd(iso(new Date()), new Date().getDay()));
  document.getElementById('shiftModalClose').addEventListener('click', () => modal.style.display = 'none');
  modal.addEventListener('click', (e) => { if (e.target === modal) modal.style.display = 'none'; });
  document.querySelectorAll('.ssched-seg-btn').forEach(b => b.addEventListener('click', () => setRepeat(b.dataset.repeat)));
  document.getElementById('addBreakBtn').addEventListener('click', () => { breaksDraft.push({ open: '12:00', close: '13:00' }); renderBreaks(); });
  document.getElementById('saveShiftBtn').addEventListener('click', save);
  document.getElementById('deleteShiftBtn').addEventListener('click', async () => {
    const id = document.getElementById('shiftId').value;
    if (!id || !confirm('Delete this entire shift (all occurrences)?')) return;
    await fetch(`${API}/api/staff-shifts/${id}`, { method: 'DELETE', headers: H.headers });
    modal.style.display = 'none'; loadWeek();
  });
  document.getElementById('skipDayBtn').addEventListener('click', async () => {
    const id = document.getElementById('shiftId').value;
    if (!id || !editingOccurrenceDate) return;
    if (!confirm('Remove just this day from the recurring shift?')) return;
    await fetch(`${API}/api/staff-shifts/${id}/skip`, { method: 'POST', headers: { ...H.headers, 'Content-Type': 'application/json' }, body: JSON.stringify({ date: editingOccurrenceDate }) });
    modal.style.display = 'none'; loadWeek();
  });

  document.getElementById('prevWeek').addEventListener('click', () => { weekStart = addDays(weekStart, -7); loadWeek(); });
  document.getElementById('nextWeek').addEventListener('click', () => { weekStart = addDays(weekStart, 7); loadWeek(); });
  document.getElementById('todayBtn').addEventListener('click', () => { weekStart = mondayOf(new Date()); loadWeek(); });
  document.getElementById('staffFilter').addEventListener('change', loadWeek);

  (async function init() { await loadStaff(); await loadWeek(); })();
</script>

