import InstructorLayout from '../../layouts/InstructorLayout.astro';
---
<InstructorLayout title="My hours" activePage="hours">
  <div style="max-width:1000px;margin:0 auto;">
    <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;margin-bottom:8px;">
      <div>
        <h1 style="margin:0;font-size:26px;font-weight:800;">My hours</h1>
        <p style="margin:4px 0 0;color:var(--color-text-muted,#888);font-size:14px;">Your work shifts & breaks. Set by the studio.</p>
      </div>
      <div style="display:flex;align-items:center;gap:6px;">
        <button class="btn btn-ghost btn-sm" id="prevWeek">‹</button>
        <button class="btn btn-ghost btn-sm" id="todayBtn">This week</button>
        <button class="btn btn-ghost btn-sm" id="nextWeek">›</button>
      </div>
    </div>
    <strong id="weekLabel" style="font-size:15px;"></strong>
    <div class="card" style="margin-top:12px;">
      <div class="card-body" style="padding:0;overflow-x:auto;">
        <div id="grid" class="ih-grid"></div>
      </div>
    </div>
    <div id="empty" style="display:none;text-align:center;padding:40px;color:var(--color-text-muted,#888);">
      No shifts scheduled this week.
    </div>
  </div>
</InstructorLayout>

<style>
  .ih-grid { display:grid; grid-template-columns:50px repeat(7,minmax(110px,1fr)); min-width:840px; }
  .ih-corner,.ih-dayhead { border-bottom:1px solid var(--color-border-subtle,#333); border-right:1px solid var(--color-border-subtle,#333); }
  .ih-dayhead { text-align:center; padding:8px 4px; font-size:12px; }
  .ih-dayhead .dn { font-weight:700; }
  .ih-dayhead.today { background:var(--color-brand-soft,rgba(234,106,36,.12)); }
  .ih-hour { height:42px; font-size:10px; color:var(--color-text-muted,#888); text-align:right; padding-right:5px; border-bottom:1px solid var(--color-border-subtle,#333); box-sizing:border-box; }
  .ih-gutter { border-right:1px solid var(--color-border-subtle,#333); }
  .ih-col { position:relative; border-right:1px solid var(--color-border-subtle,#333); }
  .ih-col .hl { height:42px; border-bottom:1px solid var(--color-border-subtle,#333); box-sizing:border-box; }
  .ih-block { position:absolute; left:2px; right:2px; border-radius:6px; padding:3px 5px; color:#fff; font-size:11px; overflow:hidden; box-shadow:0 1px 3px rgba(0,0,0,.25); }
  .ih-block .bt { font-weight:700; }
  .ih-break { position:absolute; left:0; right:0; background:repeating-linear-gradient(45deg,rgba(0,0,0,.3),rgba(0,0,0,.3) 5px,rgba(0,0,0,.12) 5px,rgba(0,0,0,.12) 10px); font-size:9px; text-align:center; }
</style>

<script>
  const API = import.meta.env.PUBLIC_API_URL;
  const token = localStorage.getItem('token');
  const DAY_START=7, DAY_END=21, HOUR_PX=42;
  const DOW=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  let weekStart = mondayOf(new Date());

  function mondayOf(d){const x=new Date(d);const day=(x.getDay()+6)%7;x.setDate(x.getDate()-day);x.setHours(0,0,0,0);return x;}
  function iso(d){return d.toISOString().slice(0,10);}
  function addDays(d,n){const x=new Date(d);x.setDate(x.getDate()+n);return x;}
  function toMin(t){const [h,m]=(t||'0:0').split(':').map(Number);return h*60+m;}
  function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}

  async function load(){
    const from=iso(weekStart), to=iso(addDays(weekStart,6));
    document.getElementById('weekLabel').textContent =
      weekStart.toLocaleDateString('en-US',{month:'short',day:'numeric'})+' – '+addDays(weekStart,6).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
    let occ=[];
    try{ const r=await fetch(`${API}/api/staff-shifts/mine/occurrences?from=${from}&to=${to}`,{headers:{Authorization:'Bearer '+token}}); occ=r.ok?await r.json():[]; }catch(e){}
    render(occ);
  }

  function render(occ){
    document.getElementById('empty').style.display = occ.length ? 'none' : 'block';
    document.getElementById('grid').style.display = occ.length ? '' : 'none';
    const todayIso=iso(new Date());
    let html='<div class="ih-corner"></div>';
    for(let i=0;i<7;i++){const d=addDays(weekStart,i);html+=`<div class="ih-dayhead ${iso(d)===todayIso?'today':''}"><div class="dn">${DOW[d.getDay()]}</div><div>${d.getDate()}</div></div>`;}
    let g='<div class="ih-gutter">';for(let h=DAY_START;h<DAY_END;h++)g+=`<div class="ih-hour">${h}:00</div>`;g+='</div>';html+=g;
    for(let i=0;i<7;i++){
      const d=addDays(weekStart,i),dIso=iso(d);
      let col='<div class="ih-col">';
      for(let h=DAY_START;h<DAY_END;h++)col+='<div class="hl"></div>';
      occ.filter(o=>o.date===dIso).forEach(o=>{
        const s=Math.max(DAY_START*60,toMin(o.startTime)),e=Math.min(DAY_END*60,toMin(o.endTime));
        const top=(s-DAY_START*60)/60*HOUR_PX,hgt=Math.max(16,(e-s)/60*HOUR_PX);
        let br='';(o.breaks||[]).forEach(b=>{const bs=Math.max(s,toMin(b.open)),be=Math.min(e,toMin(b.close));if(be<=bs)return;const bt=(bs-s)/60*HOUR_PX,bh=(be-bs)/60*HOUR_PX;br+=`<div class="ih-break" style="top:${bt}px;height:${bh}px;line-height:${Math.max(8,bh)}px;">${bh>14?'Break':''}</div>`;});
        col+=`<div class="ih-block" style="top:${top}px;height:${hgt}px;background:${esc(o.color||'#EA6A24')};"><div class="bt">${esc(o.startTime)}–${esc(o.endTime)}</div><div>${o.label?esc(o.label):''}</div>${br}</div>`;
      });
      col+='</div>';html+=col;
    }
    document.getElementById('grid').innerHTML=html;
  }

  document.getElementById('prevWeek').addEventListener('click',()=>{weekStart=addDays(weekStart,-7);load();});
  document.getElementById('nextWeek').addEventListener('click',()=>{weekStart=addDays(weekStart,7);load();});
  document.getElementById('todayBtn').addEventListener('click',()=>{weekStart=mondayOf(new Date());load();});
  load();
</script>

