/// <summary>
/// Marketing-attribution breakdown of online bookings (instagram, tiktok, google,
/// referral, direct, …) between two dates (yyyy-MM-dd, inclusive of `from`,
/// exclusive of the day after `to`).
/// </summary>
[HttpGet("bookings/sources")]
[Authorize(Roles = "Admin,Receptionist,Accountant,Manager")]
public async Task<IActionResult> GetBookingSources([FromQuery] string? from, [FromQuery] string? to)
{
    var f = DateTime.TryParse(from, out var pf) ? pf.Date : DateTime.UtcNow.Date.AddDays(-30);
    var t = DateTime.TryParse(to, out var pt) ? pt.Date.AddDays(1) : DateTime.UtcNow.Date.AddDays(1);
    var rows = await _schedulingService.GetBookingSourceBreakdownAsync(f, t);
    var total = rows.Sum(r => r.Count);
    return Ok(new
    {
        total,
        sources = rows.Select(r => new { source = r.Source, count = r.Count }),
    });
}

/// <summary>CSV export of bookings matching the same filters.</summary>
[HttpGet("bookings/export/csv")]
[Authorize(Roles = "Admin,Receptionist,Accountant")]
public async Task<IActionResult> ExportBookingsCsv([FromQuery] BookingListQuery query)

