const token = localStorage.getItem('token');
const API = import.meta.env.PUBLIC_API_URL;
const fmt = (n) => `${Math.round(Number(n) || 0).toLocaleString('en-US')} ₫`;

// ── Booking sources (marketing attribution) ──
const SRC_LABEL = { instagram:'📸 Instagram', facebook:'👍 Facebook', tiktok:'🎵 TikTok', google:'🔍 Google', youtube:'▶️ YouTube', zalo:'💬 Zalo', bing:'🔍 Bing', referral:'🤝 Referral', walk_by:'🚶 Walked by', direct:'🌐 Direct / Unknown', other:'❓ Other' };
async function loadSources() {
  const days = Number(document.getElementById('srcRange').value || 30);
  const to = new Date(); const from = new Date(); from.setDate(from.getDate() - days);
  const iso = (d) => d.toISOString().slice(0, 10);
  const wrap = document.getElementById('srcBreakdown');
  try {
    const r = await fetch(`${API}/api/scheduling/bookings/sources?from=${iso(from)}&to=${iso(to)}`, { headers: { Authorization: 'Bearer ' + token } });
    const d = await r.json();
    if (!d.total) { wrap.innerHTML = '<span class="text-muted text-sm">No online bookings in this period yet.</span>'; return; }
    wrap.innerHTML = d.sources.map(s => {
      const pct = Math.round((s.count / d.total) * 100);
      const label = SRC_LABEL[s.source] || s.source;
      return `<div style="display:flex;align-items:center;gap:8px;background:var(--color-surface-raised,#f5f3f0);border:1px solid var(--color-border-subtle);border-radius:999px;padding:6px 12px;font-size:13px;">
        <span style="font-weight:600;">${label}</span>
        <span style="font-weight:700;color:var(--color-brand-accent);">${s.count}</span>
        <span class="text-muted" style="font-size:11px;">${pct}%</span></div>`;
    }).join('') + `<div style="display:flex;align-items:center;gap:6px;padding:6px 12px;font-size:13px;color:var(--color-text-muted);">Total: <strong>${d.total}</strong></div>`;
  } catch (e) { wrap.innerHTML = '<span class="text-muted text-sm">Could not load sources.</span>'; }
}
document.getElementById('srcRange')?.addEventListener('change', loadSources);
loadSources();

