---
import AdminLayout from '../../layouts/AdminLayout.astro';
---
<AdminLayout title="Staff Schedule" activePage="staff-schedule" accessModules="staff,owners">

  <div class="page-header">
    <div>
      <div class="page-title">Staff Schedule</div>
      <div class="page-subtitle">Working hours, lunch breaks &amp; shifts — recurring weekly or one-off.</div>
    </div>
    <button class="btn btn-primary" id="addShiftBtn">
      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
      Add Shift
    </button>
  </div>

  <div class="ss-toolbar">
    <div class="ss-nav">
      <button class="ss-navbtn" id="prevBtn" title="Previous month">‹</button>
      <button class="ss-today" id="todayBtn">Today</button>
      <button class="ss-navbtn" id="nextBtn" title="Next month">›</button>
      <strong id="monthLabel" class="ss-month">—</strong>
    </div>
    <div class="ss-right">
      <div class="ss-legend" id="legend"></div>
      <select id="staffFilter" class="form-control ss-filter">
        <option value="">All staff</option>
      </select>
    </div>
  </div>

  <div class="ss-cal">
    <div class="ss-weekhead">
      <div>Mon</div><div>Tue</div><div>Wed</div><div>Thu</div><div>Fri</div><div>Sat</div><div>Sun</div>
    </div>
    <div class="ss-grid" id="calGrid"></div>
  </div>

  <!-- Add/Edit shift modal -->
  <div id="shiftModal" class="ss-modal-bg" style="display:none;">
    <div class="ss-modal">
      <div class="ss-modal-head">
        <span id="shiftModalTitle">Add Shift</span>
        <button class="ss-modal-x" id="shiftModalClose">✕</button>
      </div>
      <div class="ss-modal-body">
        <input type="hidden" id="shiftId" />

        <label class="ss-lbl">Staff member</label>
        <select id="fStaff" class="form-control"></select>

        <label class="ss-lbl">Repeats</label>
        <div class="ss-seg">
          <button type="button" class="ss-seg-btn active" data-repeat="weekly">Every week</button>
          <button type="button" class="ss-seg-btn" data-repeat="oneoff">One day only</button>
        </div>

        <div id="weeklyRow">
          <label class="ss-lbl">Day of week</label>
          <select id="fDay" class="form-control">
            <option value="1">Monday</option><option value="2">Tuesday</option>
            <option value="3">Wednesday</option><option value="4">Thursday</option>
            <option value="5">Friday</option><option value="6">Saturday</option>
            <option value="0">Sunday</option>
          </select>
        </div>
        <div id="oneoffRow" style="display:none;">
          <label class="ss-lbl">Date</label>
          <input type="date" id="fDate" class="form-control" />
        </div>

        <div class="ss-2col">
          <div><label class="ss-lbl">Start</label><input type="time" id="fStart" class="form-control" value="08:00" /></div>
          <div><label class="ss-lbl">End</label><input type="time" id="fEnd" class="form-control" value="17:00" /></div>
        </div>

        <label class="ss-lbl">Breaks (e.g. lunch)</label>
        <div id="breaksList"></div>
        <button type="button" class="btn btn-ghost btn-sm" id="addBreakBtn">+ Add break</button>

        <div class="ss-2col" style="margin-top:4px;">
          <div><label class="ss-lbl">Label (optional)</label><input type="text" id="fLabel" class="form-control" placeholder="e.g. Reception" /></div>
          <div><label class="ss-lbl">Colour</label>
            <div class="ss-swatches" id="swatches"></div>
            <input type="hidden" id="fColor" value="#EA6A24" />
          </div>
        </div>

        <div id="validRow" class="ss-2col">
          <div><label class="ss-lbl">Starts on (optional)</label><input type="date" id="fValidFrom" class="form-control" /></div>
          <div><label class="ss-lbl">Ends on (optional)</label><input type="date" id="fValidTo" class="form-control" /></div>
        </div>

        <div class="ss-err" id="shiftErr"></div>
      </div>
      <div class="ss-modal-foot">
        <button class="btn btn-ghost" id="skipDayBtn" style="display:none;margin-right:auto;">Remove this day only</button>
        <button class="btn btn-ghost" id="deleteShiftBtn" style="display:none;color:var(--color-danger);">Delete series</button>
        <button class="btn btn-primary" id="saveShiftBtn">Save shift</button>
      </div>
    </div>
  </div>

</AdminLayout>

<style>
  .ss-toolbar { display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:12px; margin-bottom:14px; }
  .ss-nav { display:flex; align-items:center; gap:8px; }
  .ss-navbtn { width:32px; height:32px; border-radius:8px; border:1px solid var(--color-border-subtle); background:var(--color-surface-raised,transparent); color:var(--color-text-primary); font-size:18px; cursor:pointer; line-height:1; }
  .ss-navbtn:hover { background:var(--color-brand-soft); }
  .ss-today { border:1px solid var(--color-border-subtle); background:var(--color-surface-raised,transparent); color:var(--color-text-primary); border-radius:8px; padding:6px 12px; font-size:13px; cursor:pointer; }
  .ss-month { font-size:18px; margin-left:6px; }
  .ss-right { display:flex; align-items:center; gap:14px; flex-wrap:wrap; }
  .ss-legend { display:flex; gap:10px; flex-wrap:wrap; }
  .ss-legend .lg { display:inline-flex; align-items:center; gap:5px; font-size:12px; color:var(--color-text-muted); }
  .ss-legend .dot { width:10px; height:10px; border-radius:3px; }
  .ss-filter { height:34px; padding:2px 8px; font-size:13px; width:auto; }

  .ss-cal { border:1px solid var(--color-border-subtle); border-radius:14px; overflow:hidden; background:var(--color-surface,transparent); box-shadow:var(--sp-shadow-card,0 1px 3px rgba(0,0,0,.1)); }
  .ss-weekhead { display:grid; grid-template-columns:repeat(7,1fr); background:var(--color-surface-raised,rgba(255,255,255,.03)); border-bottom:1px solid var(--color-border-subtle); }
  .ss-weekhead > div { padding:10px 12px; font-size:12px; font-weight:700; letter-spacing:.04em; text-transform:uppercase; color:var(--color-text-muted); text-align:left; }
  .ss-grid { display:grid; grid-template-columns:repeat(7,1fr); grid-auto-rows:minmax(112px,1fr); }
  .ss-cell { border-right:1px solid var(--color-border-subtle); border-bottom:1px solid var(--color-border-subtle); padding:6px 7px; cursor:pointer; position:relative; min-height:112px; transition:background .12s; overflow:hidden; }
  .ss-cell:nth-child(7n) { border-right:none; }
  .ss-cell:hover { background:var(--color-brand-soft); }
  .ss-cell.other { background:var(--color-surface-raised,rgba(0,0,0,.12)); }
  .ss-cell.other .ss-daynum { opacity:.35; }
  .ss-daynum { font-size:13px; font-weight:600; color:var(--color-text-primary); margin-bottom:4px; }
  .ss-cell.today .ss-daynum { background:var(--color-brand-accent); color:#fff; border-radius:50%; width:24px; height:24px; display:inline-flex; align-items:center; justify-content:center; }
  .ss-chip { display:block; border-radius:6px; padding:3px 7px; margin-bottom:3px; color:#fff; font-size:11px; line-height:1.25; cursor:pointer; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
  .ss-chip .cn { font-weight:700; }
  .ss-chip .ch { opacity:.92; }
  .ss-chip .cb { opacity:.85; font-size:10px; }
  .ss-more { font-size:11px; color:var(--color-brand-accent); font-weight:600; margin-top:2px; }

  .ss-modal-bg { position:fixed; inset:0; background:rgba(0,0,0,.55); z-index:600; display:flex; align-items:center; justify-content:center; padding:16px; }
  .ss-modal { background:var(--color-bg-elevated,var(--color-surface,#1a1a1a)); border:1px solid var(--color-border-subtle); border-radius:16px; width:460px; max-width:100%; max-height:92vh; overflow-y:auto; box-shadow:0 20px 60px rgba(0,0,0,.4); }
  .ss-modal-head { display:flex; justify-content:space-between; align-items:center; padding:16px 20px; font-size:17px; font-weight:700; border-bottom:1px solid var(--color-border-subtle); }
  .ss-modal-x { background:none; border:none; font-size:18px; cursor:pointer; color:var(--color-text-muted); }
  .ss-modal-body { padding:16px 20px; }
  .ss-modal-foot { display:flex; gap:8px; justify-content:flex-end; align-items:center; padding:14px 20px; border-top:1px solid var(--color-border-subtle); }
  .ss-lbl { display:block; font-size:11px; font-weight:700; color:var(--color-text-muted); text-transform:uppercase; letter-spacing:.5px; margin:14px 0 5px; }
  .ss-2col { display:grid; grid-template-columns:1fr 1fr; gap:10px; }
  .ss-seg { display:inline-flex; border:1px solid var(--color-border-subtle); border-radius:9px; overflow:hidden; }
  .ss-seg-btn { background:none; border:none; padding:8px 16px; cursor:pointer; font-size:13px; color:var(--color-text-muted); }
  .ss-seg-btn.active { background:var(--color-brand-accent); color:#fff; font-weight:600; }
  .ss-break-row { display:grid; grid-template-columns:1fr 1fr auto; gap:6px; margin-bottom:6px; align-items:center; }
  .ss-swatches { display:flex; gap:6px; padding-top:6px; }
  .ss-swatch { width:26px; height:26px; border-radius:7px; cursor:pointer; border:2px solid transparent; }
  .ss-swatch.sel { border-color:var(--color-text-primary); box-shadow:0 0 0 2px var(--color-surface,#000); }
  .ss-err { color:var(--color-danger); font-size:13px; margin-top:12px; min-height:16px; }
  @media (max-width:760px){ .ss-grid{ grid-auto-rows:minmax(84px,1fr); } .ss-cell{ min-height:84px; } .ss-chip .ch,.ss-chip .cb{ display:none; } }
</style>

<script>
  const API = import.meta.env.PUBLIC_API_URL;
  const token = localStorage.getItem('token');
  const H = { headers: { Authorization: 'Bearer ' + token } };
  const HJ = { headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' } };
  const COLORS = ['#EA6A24','#3D8C5C','#3B6FB6','#8E44AD','#D4A017','#C0392B','#16A085','#E67E22'];
  const DOWNAMES = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];

  let viewDate = new Date(); viewDate.setDate(1);
  let staffList = [], breaksDraft = [], colorSel = '#EA6A24', repeatMode = 'weekly', editingOccDate = null;

  const iso = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const addDays = (d,n) => { const x=new Date(d); x.setDate(x.getDate()+n); return x; };
  const esc = s => String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const gridStart = () => { const f=new Date(viewDate); const off=(f.getDay()+6)%7; return addDays(f,-off); };

  async function loadStaff() {
    try { const r = await fetch(`${API}/api/staff`, H); staffList = (await r.json()).filter(s => s.isActive !== false); }
    catch (e) { staffList = []; }
    const opts = staffList.map(s => `<option value="${s.id}">${esc(s.name)}</option>`).join('');
    document.getElementById('staffFilter').innerHTML = '<option value="">All staff</option>' + opts;
    document.getElementById('fStaff').innerHTML = opts || '<option value="">No staff found</option>';
    // colour legend keyed by staff (stable colour per staff via index)
    document.getElementById('legend').innerHTML = staffList.map((s,i) =>
      `<span class="lg"><span class="dot" style="background:${COLORS[i%COLORS.length]}"></span>${esc(s.name)}</span>`).join('');
  }
  function staffColor(staffId) { const i = staffList.findIndex(s => s.id === staffId); return i>=0 ? COLORS[i%COLORS.length] : '#EA6A24'; }

  async function load() {
    const gs = gridStart(), ge = addDays(gs, 41);
    document.getElementById('monthLabel').textContent = viewDate.toLocaleDateString('en-US',{month:'long',year:'numeric'});
    const staffId = document.getElementById('staffFilter').value;
    let occ = [];
    try {
      const url = `${API}/api/staff-shifts/occurrences?from=${iso(gs)}&to=${iso(ge)}` + (staffId ? `&staffId=${staffId}` : '');
      const r = await fetch(url, H); occ = r.ok ? await r.json() : [];
    } catch (e) {}
    render(occ);
  }

  function render(occ) {
    const gs = gridStart(), grid = document.getElementById('calGrid');
    const todayIso = iso(new Date()), mo = viewDate.getMonth();
    const byDay = {}; occ.forEach(o => { (byDay[o.date] = byDay[o.date] || []).push(o); });
    let html = '';
    for (let i = 0; i < 42; i++) {
      const d = addDays(gs, i), dIso = iso(d);
      const cls = ['ss-cell']; if (d.getMonth() !== mo) cls.push('other'); if (dIso === todayIso) cls.push('today');
      const items = (byDay[dIso] || []).sort((a,b) => a.startTime.localeCompare(b.startTime));
      let chips = '';
      items.slice(0,3).forEach(o => {
        const brk = (o.breaks||[]).length ? `<span class="cb"> · ${o.breaks.map(b=>b.open+'–'+b.close).join(', ')}</span>` : '';
        chips += `<span class="ss-chip" style="background:${esc(o.color||staffColor(o.staffId))}" data-o='${esc(JSON.stringify(o))}'>
          <span class="cn">${esc(o.staffName||'')}</span> <span class="ch">${esc(o.startTime)}–${esc(o.endTime)}</span>${brk}</span>`;
      });
      if (items.length > 3) chips += `<div class="ss-more">+${items.length-3} more</div>`;
      html += `<div class="${cls.join(' ')}" data-date="${dIso}"><div class="ss-daynum">${d.getDate()}</div>${chips}</div>`;
    }
    grid.innerHTML = html;
    grid.querySelectorAll('.ss-cell').forEach(c => c.addEventListener('click', ev => { if (ev.target.closest('.ss-chip')) return; openAdd(c.dataset.date); }));
    grid.querySelectorAll('.ss-chip').forEach(ch => ch.addEventListener('click', ev => { ev.stopPropagation(); openEdit(JSON.parse(ch.dataset.o)); }));
  }

  // ── Modal ──
  const modal = document.getElementById('shiftModal');
  function renderSwatches() {
    document.getElementById('swatches').innerHTML = COLORS.map(c =>
      `<div class="ss-swatch ${c===colorSel?'sel':''}" style="background:${c}" data-c="${c}"></div>`).join('');
    document.querySelectorAll('.ss-swatch').forEach(el => el.addEventListener('click', () => { colorSel = el.dataset.c; document.getElementById('fColor').value = colorSel; renderSwatches(); }));
  }
  function renderBreaks() {
    document.getElementById('breaksList').innerHTML = breaksDraft.map((b,i) =>
      `<div class="ss-break-row"><input type="time" class="form-control brk-o" data-i="${i}" value="${b.open}" /><input type="time" class="form-control brk-c" data-i="${i}" value="${b.close}" /><button type="button" class="btn btn-ghost btn-sm brk-d" data-i="${i}">✕</button></div>`).join('');
    document.querySelectorAll('.brk-d').forEach(e => e.addEventListener('click', () => { breaksDraft.splice(+e.dataset.i,1); renderBreaks(); }));
    document.querySelectorAll('.brk-o').forEach(e => e.addEventListener('change', () => breaksDraft[+e.dataset.i].open = e.value));
    document.querySelectorAll('.brk-c').forEach(e => e.addEventListener('change', () => breaksDraft[+e.dataset.i].close = e.value));
  }
  function setRepeat(m) { repeatMode = m; document.querySelectorAll('.ss-seg-btn').forEach(b => b.classList.toggle('active', b.dataset.repeat===m));
    document.getElementById('weeklyRow').style.display = m==='weekly'?'':'none';
    document.getElementById('oneoffRow').style.display = m==='oneoff'?'':'none';
    document.getElementById('validRow').style.display = m==='weekly'?'':'none'; }
  function showErr(m){ document.getElementById('shiftErr').textContent = m || ''; }

  function openAdd(dateIso) {
    const d = dateIso ? new Date(dateIso+'T00:00:00') : new Date();
    document.getElementById('shiftModalTitle').textContent = 'Add Shift';
    document.getElementById('shiftId').value = '';
    document.getElementById('fStaff').selectedIndex = 0;
    setRepeat('weekly');
    document.getElementById('fDay').value = String(d.getDay());
    document.getElementById('fDate').value = dateIso || iso(new Date());
    document.getElementById('fStart').value = '08:00'; document.getElementById('fEnd').value = '17:00';
    document.getElementById('fLabel').value = ''; document.getElementById('fValidFrom').value = ''; document.getElementById('fValidTo').value = '';
    colorSel = '#EA6A24'; document.getElementById('fColor').value = colorSel;
    breaksDraft = [{ open:'12:00', close:'13:00' }]; editingOccDate = null;
    document.getElementById('deleteShiftBtn').style.display = 'none';
    document.getElementById('skipDayBtn').style.display = 'none';
    renderSwatches(); renderBreaks(); showErr('');
    if (!staffList.length) showErr('No active staff found — add staff in Team first.');
    modal.style.display = 'flex';
  }

  async function openEdit(o) {
    let raw = null;
    try { raw = (await (await fetch(`${API}/api/staff-shifts/raw`, H)).json()).find(s => s.id === o.shiftId); } catch (e) {}
    if (!raw) return;
    document.getElementById('shiftModalTitle').textContent = 'Edit Shift';
    document.getElementById('shiftId').value = raw.id;
    document.getElementById('fStaff').value = raw.staffId;
    setRepeat(raw.isRecurring ? 'weekly' : 'oneoff');
    document.getElementById('fDay').value = String(raw.dayOfWeek);
    document.getElementById('fDate').value = raw.specificDate || o.date;
    document.getElementById('fStart').value = raw.startTime; document.getElementById('fEnd').value = raw.endTime;
    document.getElementById('fLabel').value = raw.label || '';
    document.getElementById('fValidFrom').value = raw.validFrom || ''; document.getElementById('fValidTo').value = raw.validTo || '';
    colorSel = raw.color || '#EA6A24'; document.getElementById('fColor').value = colorSel;
    breaksDraft = (raw.breaks || []).map(b => ({ open:b.open, close:b.close }));
    editingOccDate = o.date;
    document.getElementById('deleteShiftBtn').style.display = '';
    document.getElementById('skipDayBtn').style.display = raw.isRecurring ? '' : 'none';
    renderSwatches(); renderBreaks(); showErr(''); modal.style.display = 'flex';
  }

  function collect() {
    const rec = repeatMode === 'weekly';
    return {
      staffId: document.getElementById('fStaff').value,
      isRecurring: rec,
      dayOfWeek: Number(document.getElementById('fDay').value),
      specificDate: rec ? null : document.getElementById('fDate').value,
      startTime: document.getElementById('fStart').value,
      endTime: document.getElementById('fEnd').value,
      breaks: breaksDraft.filter(b => b.open && b.close),
      label: document.getElementById('fLabel').value || null,
      color: document.getElementById('fColor').value,
      validFrom: rec ? (document.getElementById('fValidFrom').value || null) : null,
      validTo: rec ? (document.getElementById('fValidTo').value || null) : null,
    };
  }
  async function save() {
    const id = document.getElementById('shiftId').value, body = collect();
    if (!body.staffId) return showErr('Choose a staff member.');
    if (!body.startTime || !body.endTime) return showErr('Enter start and end times.');
    if (body.endTime <= body.startTime) return showErr('End time must be after start time.');
    if (!body.isRecurring && !body.specificDate) return showErr('Choose a date.');
    const btn = document.getElementById('saveShiftBtn'); btn.disabled = true; btn.textContent = 'Saving…';
    try {
      const res = id
        ? await fetch(`${API}/api/staff-shifts/${id}`, { method:'PUT', ...HJ, body: JSON.stringify(body) })
        : await fetch(`${API}/api/staff-shifts`, { method:'POST', ...HJ, body: JSON.stringify(body) });
      if (!res.ok) { const e = await res.json().catch(()=>({})); btn.disabled=false; btn.textContent='Save shift'; return showErr(e.message || `Could not save (HTTP ${res.status}).`); }
      modal.style.display = 'none'; btn.disabled=false; btn.textContent='Save shift'; load();
    } catch (e) { btn.disabled=false; btn.textContent='Save shift'; showErr('Network error.'); }
  }

  document.getElementById('addShiftBtn').addEventListener('click', () => openAdd(iso(new Date())));
  document.getElementById('shiftModalClose').addEventListener('click', () => modal.style.display='none');
  modal.addEventListener('click', e => { if (e.target === modal) modal.style.display='none'; });
  document.querySelectorAll('.ss-seg-btn').forEach(b => b.addEventListener('click', () => setRepeat(b.dataset.repeat)));
  document.getElementById('addBreakBtn').addEventListener('click', () => { breaksDraft.push({ open:'12:00', close:'13:00' }); renderBreaks(); });
  document.getElementById('saveShiftBtn').addEventListener('click', save);
  document.getElementById('deleteShiftBtn').addEventListener('click', async () => {
    const id = document.getElementById('shiftId').value;
    if (!id || !confirm('Delete this entire shift (all its occurrences)?')) return;
    await fetch(`${API}/api/staff-shifts/${id}`, { method:'DELETE', headers: H.headers }); modal.style.display='none'; load();
  });
  document.getElementById('skipDayBtn').addEventListener('click', async () => {
    const id = document.getElementById('shiftId').value;
    if (!id || !editingOccDate || !confirm('Remove just this day from the recurring shift?')) return;
    await fetch(`${API}/api/staff-shifts/${id}/skip`, { method:'POST', ...HJ, body: JSON.stringify({ date: editingOccDate }) }); modal.style.display='none'; load();
  });
  document.getElementById('prevBtn').addEventListener('click', () => { viewDate.setMonth(viewDate.getMonth()-1); load(); });
  document.getElementById('nextBtn').addEventListener('click', () => { viewDate.setMonth(viewDate.getMonth()+1); load(); });
  document.getElementById('todayBtn').addEventListener('click', () => { viewDate = new Date(); viewDate.setDate(1); load(); });
  document.getElementById('staffFilter').addEventListener('change', load);

  (async function init(){ await loadStaff(); await load(); })();
</script>

