import InstructorLayout from '../../layouts/InstructorLayout.astro';
---
<InstructorLayout title="My hours" activePage="hours">
  <div style="max-width:1100px;margin:0 auto;">
    <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;margin-bottom:14px;">
      <div>
        <h1 style="margin:0;font-size:26px;font-weight:800;">My hours</h1>
        <p style="margin:4px 0 0;color:var(--color-text-muted,#888);font-size:14px;">Your work shifts &amp; breaks — set by the studio.</p>
      </div>
      <div style="display:flex;align-items:center;gap:8px;">
        <button class="ih-nav" id="prevBtn">‹</button>
        <button class="ih-today" id="todayBtn">Today</button>
        <button class="ih-nav" id="nextBtn">›</button>
        <strong id="monthLabel" style="font-size:16px;margin-left:6px;"></strong>
      </div>
    </div>

    <div class="ih-cal">
      <div class="ih-weekhead"><div>Mon</div><div>Tue</div><div>Wed</div><div>Thu</div><div>Fri</div><div>Sat</div><div>Sun</div></div>
      <div class="ih-grid" id="calGrid"></div>
    </div>
    <div id="empty" style="display:none;text-align:center;padding:30px;color:var(--color-text-muted,#888);">No shifts this month.</div>
  </div>
</InstructorLayout>

<style>
  .ih-nav { width:32px;height:32px;border-radius:8px;border:1px solid var(--color-border-subtle,#333);background:transparent;color:var(--color-text-primary);font-size:18px;cursor:pointer;line-height:1; }
  .ih-today { border:1px solid var(--color-border-subtle,#333);background:transparent;color:var(--color-text-primary);border-radius:8px;padding:6px 12px;font-size:13px;cursor:pointer; }
  .ih-cal { border:1px solid var(--color-border-subtle,#333);border-radius:14px;overflow:hidden; }
  .ih-weekhead { display:grid;grid-template-columns:repeat(7,1fr);background:var(--color-surface-raised,rgba(255,255,255,.03));border-bottom:1px solid var(--color-border-subtle,#333); }
  .ih-weekhead > div { padding:9px 10px;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;color:var(--color-text-muted,#888); }
  .ih-grid { display:grid;grid-template-columns:repeat(7,1fr);grid-auto-rows:minmax(96px,1fr); }
  .ih-cell { border-right:1px solid var(--color-border-subtle,#333);border-bottom:1px solid var(--color-border-subtle,#333);padding:6px 7px;min-height:96px;overflow:hidden; }
  .ih-cell:nth-child(7n){ border-right:none; }
  .ih-cell.other { background:var(--color-surface-raised,rgba(0,0,0,.15)); }
  .ih-cell.other .ih-dn { opacity:.35; }
  .ih-dn { font-size:13px;font-weight:600;margin-bottom:4px; }
  .ih-cell.today .ih-dn { background:var(--color-brand-accent);color:#fff;border-radius:50%;width:24px;height:24px;display:inline-flex;align-items:center;justify-content:center; }
  .ih-chip { display:block;border-radius:6px;padding:3px 7px;margin-bottom:3px;color:#fff;font-size:11px;line-height:1.3; }
  .ih-chip .h { font-weight:700; }
  .ih-chip .b { opacity:.85;font-size:10px; }
  @media (max-width:760px){ .ih-grid{grid-auto-rows:minmax(76px,1fr);} .ih-chip .b{display:none;} }
</style>

<script>
  const API = import.meta.env.PUBLIC_API_URL;
  const token = localStorage.getItem('token');
  let viewDate = new Date(); viewDate.setDate(1);
  const iso = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const addDays = (d,n)=>{const x=new Date(d);x.setDate(x.getDate()+n);return x;};
  const esc = s => String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const gridStart = () => { const f=new Date(viewDate); const off=(f.getDay()+6)%7; return addDays(f,-off); };

  async function load() {
    const gs=gridStart(), ge=addDays(gs,41);
    document.getElementById('monthLabel').textContent = viewDate.toLocaleDateString('en-US',{month:'long',year:'numeric'});
    let occ=[];
    try{ const r=await fetch(`${API}/api/staff-shifts/mine/occurrences?from=${iso(gs)}&to=${iso(ge)}`,{headers:{Authorization:'Bearer '+token}}); occ=r.ok?await r.json():[]; }catch(e){}
    render(occ);
  }
  function render(occ){
    document.getElementById('empty').style.display = occ.length?'none':'block';
    const gs=gridStart(), grid=document.getElementById('calGrid'), todayIso=iso(new Date()), mo=viewDate.getMonth();
    const byDay={}; occ.forEach(o=>{(byDay[o.date]=byDay[o.date]||[]).push(o);});
    let html='';
    for(let i=0;i<42;i++){
      const d=addDays(gs,i),dIso=iso(d),cls=['ih-cell'];
      if(d.getMonth()!==mo)cls.push('other'); if(dIso===todayIso)cls.push('today');
      let chips='';
      (byDay[dIso]||[]).sort((a,b)=>a.startTime.localeCompare(b.startTime)).forEach(o=>{
        const brk=(o.breaks||[]).length?`<span class="b"> · break ${o.breaks.map(b=>b.open+'–'+b.close).join(', ')}</span>`:'';
        chips+=`<span class="ih-chip" style="background:${esc(o.color||'#EA6A24')}"><span class="h">${esc(o.startTime)}–${esc(o.endTime)}</span>${o.label?' '+esc(o.label):''}${brk}</span>`;
      });
      html+=`<div class="${cls.join(' ')}"><div class="ih-dn">${d.getDate()}</div>${chips}</div>`;
    }
    grid.innerHTML=html;
  }
  document.getElementById('prevBtn').addEventListener('click',()=>{viewDate.setMonth(viewDate.getMonth()-1);load();});
  document.getElementById('nextBtn').addEventListener('click',()=>{viewDate.setMonth(viewDate.getMonth()+1);load();});
  document.getElementById('todayBtn').addEventListener('click',()=>{viewDate=new Date();viewDate.setDate(1);load();});
  load();
</script>
</InstructorLayout>

