using MongoDB.Driver;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.Services;

/// <summary>
/// Staff shift storage + recurrence expansion. Recurring shifts repeat weekly on
/// a day-of-week; one-off shifts are pinned to a date. Expansion walks the
/// requested date range and emits an occurrence per matching day, honouring the
/// recurrence bounds and per-occurrence exceptions.
/// </summary>
public class StaffShiftService : IStaffShiftService
{
    private readonly IMongoCollection<StaffShift> _shifts;
    private readonly IMongoCollection<Staff> _staff;

    public StaffShiftService(MongoDbContext db)
    {
        _shifts = db.GetCollection<StaffShift>("StaffShifts");
        _staff = db.GetCollection<Staff>("Staff");
    }

    public async Task<List<StaffShift>> GetShiftsAsync(string? staffId = null)
    {
        var filter = string.IsNullOrWhiteSpace(staffId)
            ? Builders<StaffShift>.Filter.Empty
            : Builders<StaffShift>.Filter.Eq(s => s.StaffId, staffId);
        return await _shifts.Find(filter).ToListAsync();
    }

    public async Task<StaffShift> CreateAsync(StaffShift shift)
    {
        NormaliseAndValidate(shift);
        // Backfill the denormalised staff name from the Staff record.
        if (string.IsNullOrWhiteSpace(shift.StaffName))
        {
            var staff = await _staff.Find(s => s.Id == shift.StaffId).FirstOrDefaultAsync();
            shift.StaffName = staff?.Name;
        }
        shift.CreatedAt = DateTime.UtcNow;
        await _shifts.InsertOneAsync(shift);
        return shift;
    }

    public async Task<bool> UpdateAsync(string id, StaffShift shift)
    {
        NormaliseAndValidate(shift);
        var existing = await _shifts.Find(s => s.Id == id).FirstOrDefaultAsync();
        if (existing == null) return false;

        // Preserve identity + accumulated exceptions unless the caller sent new ones.
        shift.Id = id;
        shift.CreatedAt = existing.CreatedAt;
        shift.UpdatedAt = DateTime.UtcNow;
        if (shift.ExceptionDates == null || shift.ExceptionDates.Count == 0)
            shift.ExceptionDates = existing.ExceptionDates;
        if (string.IsNullOrWhiteSpace(shift.StaffName))
        {
            var staff = await _staff.Find(s => s.Id == shift.StaffId).FirstOrDefaultAsync();
            shift.StaffName = staff?.Name ?? existing.StaffName;
        }

        var res = await _shifts.ReplaceOneAsync(s => s.Id == id, shift);
        return res.ModifiedCount > 0 || res.MatchedCount > 0;
    }

    public async Task<bool> DeleteAsync(string id)
    {
        var res = await _shifts.DeleteOneAsync(s => s.Id == id);
        return res.DeletedCount > 0;
    }

    public async Task<bool> SkipOccurrenceAsync(string id, string dateIso)
    {
        if (string.IsNullOrWhiteSpace(dateIso)) return false;
        var res = await _shifts.UpdateOneAsync(
            s => s.Id == id,
            Builders<StaffShift>.Update.AddToSet(s => s.ExceptionDates, dateIso));
        return res.ModifiedCount > 0 || res.MatchedCount > 0;
    }

    public async Task<List<StaffShiftOccurrence>> GetScheduleAsync(DateOnly from, DateOnly to, string? staffId = null)
    {
        var shifts = await GetShiftsAsync(staffId);
        var result = new List<StaffShiftOccurrence>();

        foreach (var s in shifts)
        {
            if (!s.IsRecurring)
            {
                if (DateOnly.TryParse(s.SpecificDate, out var d) && d >= from && d <= to)
                    result.Add(ToOccurrence(s, d));
                continue;
            }

            // Recurring: walk each day in the window on the matching day-of-week.
            DateOnly.TryParse(s.ValidFrom, out var vf);
            var hasVf = !string.IsNullOrWhiteSpace(s.ValidFrom);
            DateOnly.TryParse(s.ValidTo, out var vt);
            var hasVt = !string.IsNullOrWhiteSpace(s.ValidTo);
            var exceptions = new HashSet<string>(s.ExceptionDates ?? new());

            for (var day = from; day <= to; day = day.AddDays(1))
            {
                if ((int)day.DayOfWeek != s.DayOfWeek) continue;
                if (hasVf && day < vf) continue;
                if (hasVt && day > vt) continue;
                if (exceptions.Contains(day.ToString("yyyy-MM-dd"))) continue;
                result.Add(ToOccurrence(s, day));
            }
        }

        return result
            .OrderBy(o => o.Date)
            .ThenBy(o => o.StartTime)
            .ToList();
    }

    private static StaffShiftOccurrence ToOccurrence(StaffShift s, DateOnly date) => new()
    {
        ShiftId = s.Id!,
        StaffId = s.StaffId,
        StaffName = s.StaffName,
        Label = s.Label,
        Color = s.Color,
        Date = date.ToString("yyyy-MM-dd"),
        StartTime = s.StartTime,
        EndTime = s.EndTime,
        Breaks = s.Breaks ?? new(),
        IsRecurring = s.IsRecurring,
    };

    private static void NormaliseAndValidate(StaffShift s)
    {
        if (string.IsNullOrWhiteSpace(s.StaffId))
            throw new ArgumentException("StaffId is required.");
        if (!IsValidTime(s.StartTime) || !IsValidTime(s.EndTime))
            throw new ArgumentException("StartTime and EndTime must be HH:mm.");
        if (string.Compare(s.EndTime, s.StartTime, StringComparison.Ordinal) <= 0)
            throw new ArgumentException("EndTime must be after StartTime.");
        if (s.IsRecurring)
        {
            if (s.DayOfWeek < 0 || s.DayOfWeek > 6)
                throw new ArgumentException("DayOfWeek must be 0–6.");
        }
        else if (!DateOnly.TryParse(s.SpecificDate, out _))
        {
            throw new ArgumentException("SpecificDate (yyyy-MM-dd) is required for a one-off shift.");
        }
        s.Breaks ??= new();
        foreach (var b in s.Breaks)
        {
            if (!IsValidTime(b.Open) || !IsValidTime(b.Close) ||
                string.Compare(b.Close, b.Open, StringComparison.Ordinal) <= 0)
                throw new ArgumentException("Each break needs Open < Close in HH:mm.");
        }
        if (string.IsNullOrWhiteSpace(s.Color)) s.Color = "#EA6A24";
    }

    private static bool IsValidTime(string? t) =>
        !string.IsNullOrWhiteSpace(t) && TimeOnly.TryParseExact(t, "HH:mm", out _);
}

