---
import AdminLayout from '../../layouts/AdminLayout.astro';
---
<AdminLayout title="Staff Schedule" activePage="staff-schedule" accessModules="staff,owners">

  <div class="page-header">
    <div>
      <div class="page-title">Staff Schedule</div>
      <div class="page-subtitle">Manage working hours, lunch breaks &amp; shifts — recurring weekly or one-off.</div>
    </div>
    <button class="btn btn-primary" id="addShiftBtn">
      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="width:16px;height:16px;"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
      Add Shift
    </button>
  </div>

  <div class="ss-toolbar">
    <div class="ss-nav">
      <button class="ss-navbtn" id="prevBtn">‹</button>
      <button class="ss-today" id="todayBtn">Today</button>
      <button class="ss-navbtn" id="nextBtn">›</button>
      <span class="ss-period"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:15px;height:15px;"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg><strong id="periodLabel">—</strong></span>
    </div>
    <div class="ss-filters">
      <div class="ss-chips" id="chips"></div>
      <select id="staffFilter" class="ss-allsel"><option value="">All staff</option></select>
    </div>
  </div>

  <div class="ss-cal">
    <div class="ss-head" id="calHead"></div>
    <div class="ss-body">
      <div class="ss-gutter" id="gutter"></div>
      <div class="ss-cols" id="cols"></div>
    </div>
  </div>

  <div class="ss-overview">
    <div class="ss-ov-title"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:16px;height:16px;"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg> Weekly Overview</div>
    <div class="ss-ov-stat"><span>Total Staff</span><strong id="ovStaff">0</strong></div>
    <div class="ss-ov-stat"><span>Total Shifts</span><strong id="ovShifts">0</strong></div>
    <div class="ss-ov-stat"><span>Total Working Hours</span><strong id="ovWork">0h</strong></div>
    <div class="ss-ov-stat"><span>Total Lunch Hours</span><strong id="ovLunch">0h</strong></div>
  </div>
  <div class="ss-tip">💡 <strong>Tip:</strong> Click any day to add a shift, or click a shift to edit it.</div>

  <!-- Add/Edit shift modal -->
  <div id="shiftModal" class="ss-modal-bg" style="display:none;">
    <div class="ss-modal">
      <div class="ss-modal-head"><span id="shiftModalTitle">Add Shift</span><button class="ss-modal-x" id="shiftModalClose">✕</button></div>
      <div class="ss-modal-body">
        <input type="hidden" id="shiftId" />
        <label class="ss-lbl">Staff member</label>
        <select id="fStaff" class="form-control"></select>
        <label class="ss-lbl">Repeats</label>
        <div class="ss-seg">
          <button type="button" class="ss-seg-btn active" data-repeat="weekly">Every week</button>
          <button type="button" class="ss-seg-btn" data-repeat="oneoff">One day only</button>
        </div>
        <div id="weeklyRow">
          <label class="ss-lbl">Days of week</label>
          <div class="ss-days" id="fDays">
            <button type="button" class="ss-day" data-d="1">Mon</button><button type="button" class="ss-day" data-d="2">Tue</button>
            <button type="button" class="ss-day" data-d="3">Wed</button><button type="button" class="ss-day" data-d="4">Thu</button>
            <button type="button" class="ss-day" data-d="5">Fri</button><button type="button" class="ss-day" data-d="6">Sat</button>
            <button type="button" class="ss-day" data-d="0">Sun</button>
          </div>
          <div class="ss-dayquick">
            <button type="button" class="ss-quick" data-set="1,2,3,4,5">Weekdays</button>
            <button type="button" class="ss-quick" data-set="0,6">Weekend</button>
            <button type="button" class="ss-quick" data-set="0,1,2,3,4,5,6">Every day</button>
          </div>
        </div>
        <div id="oneoffRow" style="display:none;"><label class="ss-lbl">Date</label><input type="date" id="fDate" class="form-control" /></div>
        <div class="ss-2col"><div><label class="ss-lbl">Start</label><input type="time" id="fStart" class="form-control" value="08:00" /></div><div><label class="ss-lbl">End</label><input type="time" id="fEnd" class="form-control" value="17:00" /></div></div>
        <label class="ss-lbl">Breaks (e.g. lunch)</label>
        <div id="breaksList"></div>
        <button type="button" class="btn btn-ghost btn-sm" id="addBreakBtn">+ Add break</button>
        <div class="ss-2col" style="margin-top:4px;"><div><label class="ss-lbl">Label (optional)</label><input type="text" id="fLabel" class="form-control" placeholder="e.g. Reception" /></div><div><label class="ss-lbl">Colour</label><div class="ss-swatches" id="swatches"></div><input type="hidden" id="fColor" value="#EA6A24" /></div></div>
        <div id="validRow" class="ss-2col"><div><label class="ss-lbl">Starts on (optional)</label><input type="date" id="fValidFrom" class="form-control" /></div><div><label class="ss-lbl">Ends on (optional)</label><input type="date" id="fValidTo" class="form-control" /></div></div>
        <div class="ss-err" id="shiftErr"></div>
      </div>
      <div class="ss-modal-foot">
        <button class="btn btn-ghost" id="skipDayBtn" style="display:none;margin-right:auto;">Remove this day only</button>
        <button class="btn btn-ghost" id="deleteShiftBtn" style="display:none;color:var(--color-danger);">Delete series</button>
        <button class="btn btn-primary" id="saveShiftBtn">Save shift</button>
      </div>
    </div>
  </div>
</AdminLayout>

<style>
  .ss-toolbar { display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:12px; margin-bottom:14px; }
  .ss-nav { display:flex; align-items:center; gap:8px; }
  .ss-navbtn { width:34px; height:34px; border-radius:9px; border:1px solid var(--color-border-subtle); background:var(--color-surface-raised,rgba(255,255,255,.03)); color:var(--color-text-primary); font-size:18px; cursor:pointer; }
  .ss-navbtn:hover { background:var(--color-brand-soft); }
  .ss-today { border:1px solid var(--color-border-subtle); background:var(--color-surface-raised,rgba(255,255,255,.03)); color:var(--color-text-primary); border-radius:9px; padding:7px 14px; font-size:13px; cursor:pointer; }
  .ss-period { display:inline-flex; align-items:center; gap:7px; margin-left:8px; color:var(--color-text-primary); font-size:15px; }
  .ss-filters { display:flex; align-items:center; gap:10px; flex-wrap:wrap; }
  .ss-chips { display:flex; gap:8px; flex-wrap:wrap; }
  .ss-chip-f { display:inline-flex; align-items:center; gap:6px; border:1px solid var(--color-border-subtle); border-radius:999px; padding:5px 12px; font-size:13px; cursor:pointer; color:var(--color-text-primary); background:var(--color-surface-raised,rgba(255,255,255,.03)); user-select:none; }
  .ss-chip-f .dot { width:9px; height:9px; border-radius:50%; }
  .ss-chip-f.off { opacity:.4; }
  .ss-allsel { height:34px; border-radius:9px; border:1px solid var(--color-border-subtle); background:var(--color-surface-raised,rgba(255,255,255,.03)); color:var(--color-text-primary); padding:2px 10px; font-size:13px; }

  .ss-cal { border:1px solid var(--color-border-subtle); border-radius:14px; overflow:hidden; background:var(--color-surface,rgba(255,255,255,.015)); box-shadow:var(--sp-shadow-card,0 1px 3px rgba(0,0,0,.15)); }
  .ss-head { display:grid; grid-template-columns:58px repeat(7,1fr); background:var(--color-surface-raised,rgba(255,255,255,.03)); border-bottom:1px solid var(--color-border-subtle); }
  .ss-head > div { padding:10px 10px; text-align:center; border-left:1px solid var(--color-border-subtle); }
  .ss-head > div:first-child { border-left:none; }
  .ss-head .dn { font-size:11px; font-weight:700; letter-spacing:.05em; color:var(--color-text-muted); text-transform:uppercase; }
  .ss-head .dd { font-size:16px; font-weight:700; color:var(--color-text-primary); }
  .ss-head .today .dd { background:var(--color-brand-accent); color:#fff; border-radius:50%; width:28px; height:28px; display:inline-flex; align-items:center; justify-content:center; }
  .ss-body { display:grid; grid-template-columns:58px 1fr; }
  .ss-gutter { position:relative; }
  .ss-ghour { height:40px; font-size:10px; color:var(--color-text-muted); text-align:right; padding-right:6px; box-sizing:border-box; border-bottom:1px solid var(--color-border-subtle); }
  .ss-cols { display:grid; grid-template-columns:repeat(7,1fr); }
  .ss-col { position:relative; border-left:1px solid var(--color-border-subtle); cursor:pointer; }
  .ss-col .ss-hline { height:40px; border-bottom:1px solid var(--color-border-subtle); box-sizing:border-box; }
  .ss-seg-block { position:absolute; border-radius:8px; padding:4px 7px; font-size:11px; overflow:hidden; cursor:pointer; box-sizing:border-box; }
  .ss-seg-work { border:1px solid; }
  .ss-seg-work .sn { font-weight:700; display:flex; align-items:center; gap:5px; }
  .ss-seg-work .sn .d { width:8px; height:8px; border-radius:50%; }
  .ss-seg-work .st { color:var(--color-text-muted); font-size:10px; margin-top:1px; }
  .ss-seg-break { background:rgba(234,106,36,.14); border:1px solid rgba(234,106,36,.4); color:#EA6A24; }
  .ss-seg-break .bt { font-weight:700; display:flex; align-items:center; gap:4px; }
  .ss-seg-break .bh { font-size:10px; opacity:.9; }
  .ss-empty { position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center; color:var(--color-text-muted); pointer-events:none; opacity:.55; }
  .ss-empty svg { width:26px; height:26px; margin-bottom:6px; }
  .ss-empty .e1 { font-size:12px; font-weight:600; }
  .ss-empty .e2 { font-size:11px; }

  .ss-overview { display:flex; align-items:center; gap:28px; flex-wrap:wrap; margin-top:16px; padding:16px 20px; border:1px solid var(--color-border-subtle); border-radius:14px; background:var(--color-surface-raised,rgba(255,255,255,.03)); }
  .ss-ov-title { display:flex; align-items:center; gap:8px; font-weight:700; font-size:14px; }
  .ss-ov-stat { display:flex; flex-direction:column; }
  .ss-ov-stat span { font-size:11px; color:var(--color-text-muted); text-transform:uppercase; letter-spacing:.04em; }
  .ss-ov-stat strong { font-size:20px; color:var(--color-brand-accent); }
  .ss-tip { margin-top:10px; text-align:center; font-size:12.5px; color:var(--color-text-muted); }

  .ss-modal-bg { position:fixed; inset:0; background:rgba(0,0,0,.55); z-index:600; display:flex; align-items:center; justify-content:center; padding:16px; }
  .ss-modal { background:var(--color-bg-elevated,var(--color-surface,#1a1a1a)); border:1px solid var(--color-border-subtle); border-radius:16px; width:460px; max-width:100%; max-height:92vh; overflow-y:auto; box-shadow:0 20px 60px rgba(0,0,0,.4); }
  .ss-modal-head { display:flex; justify-content:space-between; align-items:center; padding:16px 20px; font-size:17px; font-weight:700; border-bottom:1px solid var(--color-border-subtle); }
  .ss-modal-x { background:none; border:none; font-size:18px; cursor:pointer; color:var(--color-text-muted); }
  .ss-modal-body { padding:16px 20px; }
  .ss-modal-foot { display:flex; gap:8px; justify-content:flex-end; align-items:center; padding:14px 20px; border-top:1px solid var(--color-border-subtle); }
  .ss-lbl { display:block; font-size:11px; font-weight:700; color:var(--color-text-muted); text-transform:uppercase; letter-spacing:.5px; margin:14px 0 5px; }
  .ss-2col { display:grid; grid-template-columns:1fr 1fr; gap:10px; }
  .ss-seg { display:inline-flex; border:1px solid var(--color-border-subtle); border-radius:9px; overflow:hidden; }
  .ss-seg-btn { background:none; border:none; padding:8px 16px; cursor:pointer; font-size:13px; color:var(--color-text-muted); }
  .ss-seg-btn.active { background:var(--color-brand-accent); color:#fff; font-weight:600; }
  .ss-days { display:flex; gap:6px; flex-wrap:wrap; }
  .ss-day { border:1px solid var(--color-border-subtle); border-radius:8px; padding:7px 13px; cursor:pointer; background:transparent; color:var(--color-text-muted); font-size:13px; font-weight:600; }
  .ss-day.on { background:var(--color-brand-accent); color:#fff; border-color:var(--color-brand-accent); }
  .ss-dayquick { display:flex; gap:6px; margin-top:8px; }
  .ss-quick { border:none; background:none; color:var(--color-brand-accent); font-size:12px; cursor:pointer; padding:2px 4px; text-decoration:underline; }
  .ss-break-row { display:grid; grid-template-columns:1fr 1fr auto; gap:6px; margin-bottom:6px; align-items:center; }
  .ss-swatches { display:flex; gap:6px; padding-top:6px; }
  .ss-swatch { width:26px; height:26px; border-radius:7px; cursor:pointer; border:2px solid transparent; }
  .ss-swatch.sel { border-color:var(--color-text-primary); }
  .ss-err { color:var(--color-danger); font-size:13px; margin-top:12px; min-height:16px; }
</style>

<script>
  const API = import.meta.env.PUBLIC_API_URL;
  const token = localStorage.getItem('token');
  const H = { headers: { Authorization: 'Bearer ' + token } };
  const HJ = { headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' } };
  const COLORS = ['#EA6A24','#3B82F6','#8B5CF6','#22C55E','#EAB308','#EC4899','#14B8A6','#F97316'];
  const DOW = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  const DAY_START = 7, DAY_END = 20, HOUR_PX = 40;

  let weekStart = mondayOf(new Date());
  let staffList = [], hidden = new Set();
  let breaksDraft = [], colorSel = '#EA6A24', repeatMode = 'weekly', editingOccDate = null, selectedDays = new Set();

  function mondayOf(d){ const x=new Date(d); const o=(x.getDay()+6)%7; x.setDate(x.getDate()-o); x.setHours(0,0,0,0); return x; }
  const iso = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const addDays = (d,n) => { const x=new Date(d); x.setDate(x.getDate()+n); return x; };
  const toMin = t => { const [h,m]=(t||'0:0').split(':').map(Number); return h*60+m; };
  const fmtT = m => { let h=Math.floor(m/60), mm=m%60; const ap=h>=12?'PM':'AM'; h=h%12||12; return `${h}:${String(mm).padStart(2,'0')} ${ap}`; };
  const esc = s => String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const staffColor = id => { const i = staffList.findIndex(s=>s.id===id); return i>=0?COLORS[i%COLORS.length]:'#EA6A24'; };
  const hex2rgba = (h,a) => { const n=parseInt(h.slice(1),16); return `rgba(${(n>>16)&255},${(n>>8)&255},${n&255},${a})`; };

  async function loadStaff() {
    try { const r=await fetch(`${API}/api/staff`, H); staffList=(await r.json()).filter(s=>s.isActive!==false); } catch(e){ staffList=[]; }
    document.getElementById('chips').innerHTML = staffList.map(s =>
      `<span class="ss-chip-f" data-id="${s.id}"><span class="dot" style="background:${staffColor(s.id)}"></span>${esc(s.name)}</span>`).join('');
    document.querySelectorAll('.ss-chip-f').forEach(c => c.addEventListener('click', () => {
      const id=c.dataset.id; hidden.has(id)?hidden.delete(id):hidden.add(id); c.classList.toggle('off', hidden.has(id)); load();
    }));
    document.getElementById('staffFilter').innerHTML = `<option value="">All staff (${staffList.length})</option>` + staffList.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');
    document.getElementById('fStaff').innerHTML = staffList.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('') || '<option value="">No staff</option>';
  }

  async function load() {
    const from=iso(weekStart), to=iso(addDays(weekStart,6));
    const mid = addDays(weekStart,3);
    document.getElementById('periodLabel').textContent = mid.toLocaleDateString('en-US',{month:'long',year:'numeric'});
    const focus = document.getElementById('staffFilter').value;
    let occ=[];
    try { const r=await fetch(`${API}/api/staff-shifts/occurrences?from=${from}&to=${to}`+(focus?`&staffId=${focus}`:''), H); occ=r.ok?await r.json():[]; } catch(e){}
    occ = occ.filter(o => !hidden.has(o.staffId));
    render(occ);
  }

  function segments(o) {
    const s=toMin(o.startTime), e=toMin(o.endTime), out=[];
    const brs=(o.breaks||[]).map(b=>({s:toMin(b.open),e:toMin(b.close)})).filter(b=>b.e>b.s&&b.s>=s&&b.e<=e).sort((a,b)=>a.s-b.s);
    let cur=s;
    brs.forEach(b=>{ if(b.s>cur) out.push({t:'work',s:cur,e:b.s}); out.push({t:'break',s:b.s,e:b.e}); cur=b.e; });
    if(e>cur) out.push({t:'work',s:cur,e});
    return out;
  }

  function render(occ) {
    const todayIso = iso(new Date());
    // header
    let head = '<div></div>';
    for(let i=0;i<7;i++){ const d=addDays(weekStart,i); head+=`<div class="${iso(d)===todayIso?'today':''}"><div class="dn">${DOW[d.getDay()]}</div><div class="dd">${d.getDate()}</div></div>`; }
    document.getElementById('calHead').innerHTML = head;
    // gutter
    let g=''; for(let h=DAY_START;h<DAY_END;h++){ const ap=h>=12?'PM':'AM',hh=h%12||12; g+=`<div class="ss-ghour">${hh} ${ap}</div>`; }
    document.getElementById('gutter').innerHTML = g;
    // columns
    const byDay={}; occ.forEach(o=>{(byDay[iso2(o.date)]=byDay[iso2(o.date)]||[]).push(o);});
    let cols='';
    for(let i=0;i<7;i++){
      const d=addDays(weekStart,i), dIso=iso(d);
      const items=(byDay[dIso]||[]).slice().sort((a,b)=>toMin(a.startTime)-toMin(b.startTime));
      let inner=''; for(let h=DAY_START;h<DAY_END;h++) inner+='<div class="ss-hline"></div>';
      if(!items.length){
        inner += `<div class="ss-empty"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5L19 19M19 5l-1.5 1.5M6.5 17.5L5 19"/></svg><div class="e1">No shifts</div><div class="e2">Day off</div></div>`;
      } else {
        // lane assignment for overlapping shifts
        const lanes=[]; items.forEach(o=>{ const s=toMin(o.startTime),e=toMin(o.endTime); let pl=false; for(let l=0;l<lanes.length;l++){ if(lanes[l]<=s){ o._l=l; lanes[l]=e; pl=true; break; } } if(!pl){ o._l=lanes.length; lanes.push(e); } });
        const nL=lanes.length||1;
        items.forEach(o=>{
          const col=o.color||staffColor(o.staffId);
          const left=(o._l/nL)*100, width=(1/nL)*100;
          segments(o).forEach(seg=>{
            const top=(seg.s-DAY_START*60)/60*HOUR_PX, hgt=Math.max(20,(seg.e-seg.s)/60*HOUR_PX);
            const style=`top:${top}px;height:${hgt}px;left:calc(${left}% + 3px);width:calc(${width}% - 6px);`;
            if(seg.t==='work'){
              inner+=`<div class="ss-seg-block ss-seg-work" style="${style}background:${hex2rgba(col,.16)};border-color:${hex2rgba(col,.5)};" data-o='${esc(JSON.stringify(o))}'>
                <div class="sn"><span class="d" style="background:${col}"></span>${esc(o.staffName||'')}</div>
                <div class="st">${fmtT(seg.s)} – ${fmtT(seg.e)}${o.label?' · '+esc(o.label):''}</div></div>`;
            } else {
              inner+=`<div class="ss-seg-block ss-seg-break" style="${style}" data-o='${esc(JSON.stringify(o))}'>
                <div class="bt">🍴 Lunch Break</div><div class="bh">${fmtT(seg.s)} – ${fmtT(seg.e)}</div></div>`;
            }
          });
        });
      }
      cols+=`<div class="ss-col" data-date="${dIso}">${inner}</div>`;
    }
    document.getElementById('cols').innerHTML = cols;

    document.querySelectorAll('.ss-col').forEach(c => c.addEventListener('click', ev => { if(ev.target.closest('.ss-seg-block')) return; openAdd(c.dataset.date); }));
    document.querySelectorAll('.ss-seg-block').forEach(b => b.addEventListener('click', ev => { ev.stopPropagation(); openEdit(JSON.parse(b.dataset.o)); }));

    // overview
    const staffSet=new Set(), n=occ.length; let work=0, lunch=0;
    occ.forEach(o=>{ staffSet.add(o.staffId); const dur=toMin(o.endTime)-toMin(o.startTime); let br=0; (o.breaks||[]).forEach(b=>br+=Math.max(0,toMin(b.close)-toMin(b.open))); work+=(dur-br); lunch+=br; });
    document.getElementById('ovStaff').textContent = staffSet.size;
    document.getElementById('ovShifts').textContent = n;
    document.getElementById('ovWork').textContent = Math.round(work/60)+'h';
    document.getElementById('ovLunch').textContent = Math.round(lunch/60)+'h';
  }
  function iso2(s){ return s; }

  // ── Modal ──
  const modal = document.getElementById('shiftModal');
  function renderDays(){ document.querySelectorAll('#fDays .ss-day').forEach(b=>b.classList.toggle('on', selectedDays.has(Number(b.dataset.d)))); }
  function renderSwatches(){ document.getElementById('swatches').innerHTML = COLORS.map(c=>`<div class="ss-swatch ${c===colorSel?'sel':''}" style="background:${c}" data-c="${c}"></div>`).join('');
    document.querySelectorAll('.ss-swatch').forEach(e=>e.addEventListener('click',()=>{colorSel=e.dataset.c;document.getElementById('fColor').value=colorSel;renderSwatches();})); }
  function renderBreaks(){ document.getElementById('breaksList').innerHTML=breaksDraft.map((b,i)=>`<div class="ss-break-row"><input type="time" class="form-control brk-o" data-i="${i}" value="${b.open}" /><input type="time" class="form-control brk-c" data-i="${i}" value="${b.close}" /><button type="button" class="btn btn-ghost btn-sm brk-d" data-i="${i}">✕</button></div>`).join('');
    document.querySelectorAll('.brk-d').forEach(e=>e.addEventListener('click',()=>{breaksDraft.splice(+e.dataset.i,1);renderBreaks();}));
    document.querySelectorAll('.brk-o').forEach(e=>e.addEventListener('change',()=>breaksDraft[+e.dataset.i].open=e.value));
    document.querySelectorAll('.brk-c').forEach(e=>e.addEventListener('change',()=>breaksDraft[+e.dataset.i].close=e.value)); }
  function setRepeat(m){ repeatMode=m; document.querySelectorAll('.ss-seg-btn').forEach(b=>b.classList.toggle('active',b.dataset.repeat===m));
    document.getElementById('weeklyRow').style.display=m==='weekly'?'':'none'; document.getElementById('oneoffRow').style.display=m==='oneoff'?'':'none'; document.getElementById('validRow').style.display=m==='weekly'?'':'none'; }
  function showErr(m){ document.getElementById('shiftErr').textContent=m||''; }

  function openAdd(dateIso){
    const d=dateIso?new Date(dateIso+'T00:00:00'):new Date();
    document.getElementById('shiftModalTitle').textContent='Add Shift'; document.getElementById('shiftId').value='';
    document.getElementById('fStaff').selectedIndex=0; setRepeat('weekly');
    selectedDays=new Set([d.getDay()]); renderDays();
    document.getElementById('fDate').value=dateIso||iso(new Date());
    document.getElementById('fStart').value='08:00'; document.getElementById('fEnd').value='17:00';
    document.getElementById('fLabel').value=''; document.getElementById('fValidFrom').value=''; document.getElementById('fValidTo').value='';
    colorSel='#EA6A24'; document.getElementById('fColor').value=colorSel; breaksDraft=[{open:'12:00',close:'13:00'}]; editingOccDate=null;
    document.getElementById('deleteShiftBtn').style.display='none'; document.getElementById('skipDayBtn').style.display='none';
    renderSwatches(); renderBreaks(); showErr(''); if(!staffList.length) showErr('No active staff — add staff in Team first.');
    modal.style.display='flex';
  }
  async function openEdit(o){
    let raw=null; try{ raw=(await(await fetch(`${API}/api/staff-shifts/raw`,H)).json()).find(s=>s.id===o.shiftId); }catch(e){}
    if(!raw) return;
    document.getElementById('shiftModalTitle').textContent='Edit Shift'; document.getElementById('shiftId').value=raw.id;
    document.getElementById('fStaff').value=raw.staffId; setRepeat(raw.isRecurring?'weekly':'oneoff');
    selectedDays=new Set((raw.daysOfWeek&&raw.daysOfWeek.length)?raw.daysOfWeek:[raw.dayOfWeek]); renderDays();
    document.getElementById('fDate').value=raw.specificDate||o.date;
    document.getElementById('fStart').value=raw.startTime; document.getElementById('fEnd').value=raw.endTime;
    document.getElementById('fLabel').value=raw.label||''; document.getElementById('fValidFrom').value=raw.validFrom||''; document.getElementById('fValidTo').value=raw.validTo||'';
    colorSel=raw.color||'#EA6A24'; document.getElementById('fColor').value=colorSel; breaksDraft=(raw.breaks||[]).map(b=>({open:b.open,close:b.close})); editingOccDate=o.date;
    document.getElementById('deleteShiftBtn').style.display=''; document.getElementById('skipDayBtn').style.display=raw.isRecurring?'':'none';
    renderSwatches(); renderBreaks(); showErr(''); modal.style.display='flex';
  }
  function collect(){ const rec=repeatMode==='weekly'; return { staffId:document.getElementById('fStaff').value, isRecurring:rec, daysOfWeek:[...selectedDays], specificDate:rec?null:document.getElementById('fDate').value, startTime:document.getElementById('fStart').value, endTime:document.getElementById('fEnd').value, breaks:breaksDraft.filter(b=>b.open&&b.close), label:document.getElementById('fLabel').value||null, color:document.getElementById('fColor').value, validFrom:rec?(document.getElementById('fValidFrom').value||null):null, validTo:rec?(document.getElementById('fValidTo').value||null):null }; }
  async function save(){
    const id=document.getElementById('shiftId').value, body=collect();
    if(!body.staffId) return showErr('Choose a staff member.');
    if(body.endTime<=body.startTime) return showErr('End time must be after start time.');
    if(body.isRecurring && !body.daysOfWeek.length) return showErr('Pick at least one day of the week.');
    if(!body.isRecurring && !body.specificDate) return showErr('Choose a date.');
    const btn=document.getElementById('saveShiftBtn'); btn.disabled=true; btn.textContent='Saving…';
    try{ const res=id?await fetch(`${API}/api/staff-shifts/${id}`,{method:'PUT',...HJ,body:JSON.stringify(body)}):await fetch(`${API}/api/staff-shifts`,{method:'POST',...HJ,body:JSON.stringify(body)});
      if(!res.ok){ const e=await res.json().catch(()=>({})); btn.disabled=false; btn.textContent='Save shift'; return showErr(e.message||`Could not save (HTTP ${res.status}).`); }
      modal.style.display='none'; btn.disabled=false; btn.textContent='Save shift'; load();
    }catch(e){ btn.disabled=false; btn.textContent='Save shift'; showErr('Network error.'); }
  }

  document.getElementById('addShiftBtn').addEventListener('click', ()=>openAdd(iso(new Date())));
  document.getElementById('shiftModalClose').addEventListener('click', ()=>modal.style.display='none');
  modal.addEventListener('click', e=>{ if(e.target===modal) modal.style.display='none'; });
  document.querySelectorAll('.ss-seg-btn').forEach(b=>b.addEventListener('click',()=>setRepeat(b.dataset.repeat)));
  document.querySelectorAll('#fDays .ss-day').forEach(b=>b.addEventListener('click',()=>{const d=Number(b.dataset.d);selectedDays.has(d)?selectedDays.delete(d):selectedDays.add(d);renderDays();}));
  document.querySelectorAll('.ss-quick').forEach(b=>b.addEventListener('click',()=>{selectedDays=new Set(b.dataset.set.split(',').map(Number));renderDays();}));
  document.getElementById('addBreakBtn').addEventListener('click', ()=>{breaksDraft.push({open:'12:00',close:'13:00'});renderBreaks();});
  document.getElementById('saveShiftBtn').addEventListener('click', save);
  document.getElementById('deleteShiftBtn').addEventListener('click', async ()=>{ const id=document.getElementById('shiftId').value; if(!id||!confirm('Delete this entire shift (all occurrences)?'))return; await fetch(`${API}/api/staff-shifts/${id}`,{method:'DELETE',headers:H.headers}); modal.style.display='none'; load(); });
  document.getElementById('skipDayBtn').addEventListener('click', async ()=>{ const id=document.getElementById('shiftId').value; if(!id||!editingOccDate||!confirm('Remove just this day?'))return; await fetch(`${API}/api/staff-shifts/${id}/skip`,{method:'POST',...HJ,body:JSON.stringify({date:editingOccDate})}); modal.style.display='none'; load(); });
  document.getElementById('prevBtn').addEventListener('click', ()=>{ weekStart=addDays(weekStart,-7); load(); });
  document.getElementById('nextBtn').addEventListener('click', ()=>{ weekStart=addDays(weekStart,7); load(); });
  document.getElementById('todayBtn').addEventListener('click', ()=>{ weekStart=mondayOf(new Date()); load(); });
  document.getElementById('staffFilter').addEventListener('change', load);

  (async function init(){ await loadStaff(); await load(); })();
</script>

