162	<script>
163	  const API = import.meta.env.PUBLIC_API_URL;
164	  const token = localStorage.getItem('token');
165	  const H = { headers: { Authorization: 'Bearer ' + token } };
166	  const HJ = { headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' } };
167	  const COLORS = ['#EA6A24','#3B82F6','#8B5CF6','#22C55E','#EAB308','#EC4899','#14B8A6','#F97316'];
168	  const DOW = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
169	  const DAY_START = 7, DAY_END = 20, HOUR_PX = 40;
