175	  function mondayOf(d){ const x=new Date(d); const o=(x.getDay()+6)%7; x.setDate(x.getDate()-o); x.setHours(0,0,0,0); return x; }
176	  const iso = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
177	  const addDays = (d,n) => { const x=new Date(d); x.setDate(x.getDate()+n); return x; };
178	  const toMin = t => { const [h,m]=(t||'0:0').split(':').map(Number); return h*60+m; };
179	  const fmtT = m => { let h=Math.floor(m/60), mm=m%60; const ap=h>=12?'PM':'AM'; h=h%12||12; return `${h}:${String(mm).padStart(2,'0')} ${ap}`; };
180	  const esc = s => String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
181	  const staffColor = id => { const i = staffList.findIndex(s=>s.id===id); return i>=0?COLORS[i%COLORS.length]:'#EA6A24'; };
182	  const hex2rgba = (h,a) => { const n=parseInt(h.slice(1),16); return `rgba(${(n>>16)&255},${(n>>8)&255},${n&255},${a})`; };
183	
184	  async function loadStaff() {
185	    try { const r=await fetch(`${API}/api/staff`, H); staffList=(await r.json()).filter(s=>s.isActive!==false); } catch(e){ staffList=[]; }
186	    document.getElementById('chips').innerHTML = staffList.map(s =>
187	      `<span class="ss-chip-f" data-id="${s.id}"><span class="dot" style="background:${staffColor(s.id)}"></span>${esc(s.name)}</span>`).join('');
188	    document.querySelectorAll('.ss-chip-f').forEach(c => c.addEventListener('click', () => {
189	      const id=c.dataset.id; hidden.has(id)?hidden.delete(id):hidden.add(id); c.classList.toggle('off', hidden.has(id)); load();
190	    }));
191	    document.getElementById('staffFilter').innerHTML = `<option value="">All staff (${staffList.length})</option>` + staffList.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');
192	    document.getElementById('fStaff').innerHTML = staffList.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('') || '<option value="">No staff</option>';
193	  }
