195	  async function load() {
196	    const from=iso(weekStart), to=iso(addDays(weekStart,6));
197	    const mid = addDays(weekStart,3);
198	    document.getElementById('periodLabel').textContent = mid.toLocaleDateString('en-US',{month:'long',year:'numeric'});
199	    const focus = document.getElementById('staffFilter').value;
200	    let occ=[];
201	    try { const r=await fetch(`${API}/api/staff-shifts/occurrences?from=${from}&to=${to}`+(focus?`&staffId=${focus}`:''), H); occ=r.ok?await r.json():[]; } catch(e){}
202	    occ = occ.filter(o => !hidden.has(o.staffId));
203	    render(occ);
204	  }
