206	  function segments(o) {
207	    const s=toMin(o.startTime), e=toMin(o.endTime), out=[];
208	    const brs=(o.breaks||[]).map(b=>({s:toMin(b.open),e:toMin(b.close)})).filter(b=>b.e>b.s&&b.s>=s&&b.e<=e).sort((a,b)=>a.s-b.s);
209	    let cur=s;
210	    brs.forEach(b=>{ if(b.s>cur) out.push({t:'work',s:cur,e:b.s}); out.push({t:'break',s:b.s,e:b.e}); cur=b.e; });
211	    if(e>cur) out.push({t:'work',s:cur,e});
212	    return out;
213	  }
