215	  function render(occ) {
216	    const todayIso = iso(new Date());
217	    // header
218	    let head = '<div></div>';
219	    for(let i=0;i<7;i++){ const d=addDays(weekStart,i); head+=`<div class="${iso(d)===todayIso?'today':''}"><div class="dn">${DOW[d.getDay()]}</div><div class="dd">${d.getDate()}</div></div>`; }
220	    document.getElementById('calHead').innerHTML = head;
221	    // gutter
222	    let g=''; for(let h=DAY_START;h<DAY_END;h++){ const ap=h>=12?'PM':'AM',hh=h%12||12; g+=`<div class="ss-ghour">${hh} ${ap}</div>`; }
223	    document.getElementById('gutter').innerHTML = g;
224	    // columns
225	    const byDay={}; occ.forEach(o=>{(byDay[iso2(o.date)]=byDay[iso2(o.date)]||[]).push(o);});
226	    let cols='';
227	    for(let i=0;i<7;i++){
228	      const d=addDays(weekStart,i), dIso=iso(d);
229	      const items=(byDay[dIso]||[]).slice().sort((a,b)=>toMin(a.startTime)-toMin(b.startTime));
230	      let inner=''; for(let h=DAY_START;h<DAY_END;h++) inner+='<div class="ss-hline"></div>';
231	      if(!items.length){
232	        inner += `<div class="ss-empty"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5L19 19M19 5l-1.5 1.5M6.5 17.5L5 19"/></svg><div class="e1">No shifts</div><div class="e2">Day off</div></div>`;
233	      } else {
234	        // lane assignment for overlapping shifts
235	        const lanes=[]; items.forEach(o=>{ const s=toMin(o.startTime),e=toMin(o.endTime); let pl=false; for(let l=0;l<lanes.length;l++){ if(lanes[l]<=s){ o._l=l; lanes[l]=e; pl=true; break; } } if(!pl){ o._l=lanes.length; lanes.push(e); } });
236	        const nL=lanes.length||1;
237	        items.forEach(o=>{
238	          const col=o.color||staffColor(o.staffId);
239	          const left=(o._l/nL)*100, width=(1/nL)*100;
240	          segments(o).forEach(seg=>{
241	            const top=(seg.s-DAY_START*60)/60*HOUR_PX, hgt=Math.max(20,(seg.e-seg.s)/60*HOUR_PX);
242	            const style=`top:${top}px;height:${hgt}px;left:calc(${left}% + 3px);width:calc(${width}% - 6px);`;
243	            if(seg.t==='work'){
244	              inner+=`<div class="ss-seg-block ss-seg-work" style="${style}background:${hex2rgba(col,.16)};border-color:${hex2rgba(col,.5)};" data-o='${esc(JSON.stringify(o))}'>
245	                <div class="sn"><span class="d" style="background:${col}"></span>${esc(o.staffName||'')}</div>
246	                <div class="st">${fmtT(seg.s)} – ${fmtT(seg.e)}${o.label?' · '+esc(o.label):''}</div></div>`;
247	            } else {
248	              inner+=`<div class="ss-seg-block ss-seg-break" style="${style}" data-o='${esc(JSON.stringify(o))}'>
249	                <div class="bt">🍴 Lunch Break</div><div class="bh">${fmtT(seg.s)} – ${fmtT(seg.e)}</div></div>`;
250	            }
251	          });
252	        });
253	      }
254	      cols+=`<div class="ss-col" data-date="${dIso}">${inner}</div>`;
255	    }
256	    document.getElementById('cols').innerHTML = cols;
257	
258	    document.querySelectorAll('.ss-col').forEach(c => c.addEventListener('click', ev => { if(ev.target.closest('.ss-seg-block')) return; openAdd(c.dataset.date); }));
259	    document.querySelectorAll('.ss-seg-block').forEach(b => b.addEventListener('click', ev => { ev.stopPropagation(); openEdit(JSON.parse(b.dataset.o)); }));
260	
261	    // overview
262	    const staffSet=new Set(), n=occ.length; let work=0, lunch=0;
263	    occ.forEach(o=>{ staffSet.add(o.staffId); const dur=toMin(o.endTime)-toMin(o.startTime); let br=0; (o.breaks||[]).forEach(b=>br+=Math.max(0,toMin(b.close)-toMin(b.open))); work+=(dur-br); lunch+=br; });
264	    document.getElementById('ovStaff').textContent = staffSet.size;
265	    document.getElementById('ovShifts').textContent = n;
266	    document.getElementById('ovWork').textContent = Math.round(work/60)+'h';
267	    document.getElementById('ovLunch').textContent = Math.round(lunch/60)+'h';
268	  }
269	  function iso2(s){ return s; }
