272	  const modal = document.getElementById('shiftModal');
273	  function renderDays(){ document.querySelectorAll('#fDays .ss-day').forEach(b=>b.classList.toggle('on', selectedDays.has(Number(b.dataset.d)))); }
274	  function renderSwatches(){ document.getElementById('swatches').innerHTML = COLORS.map(c=>`<div class="ss-swatch ${c===colorSel?'sel':''}" style="background:${c}" data-c="${c}"></div>`).join('');
275	    document.querySelectorAll('.ss-swatch').forEach(e=>e.addEventListener('click',()=>{colorSel=e.dataset.c;document.getElementById('fColor').value=colorSel;renderSwatches();})); }
276	  function renderBreaks(){ document.getElementById('breaksList').innerHTML=breaksDraft.map((b,i)=>`<div class="ss-break-row"><input type="time" class="form-control brk-o" data-i="${i}" value="${b.open}" /><input type="time" class="form-control brk-c" data-i="${i}" value="${b.close}" /><button type="button" class="btn btn-ghost btn-sm brk-d" data-i="${i}">✕</button></div>`).join('');
277	    document.querySelectorAll('.brk-d').forEach(e=>e.addEventListener('click',()=>{breaksDraft.splice(+e.dataset.i,1);renderBreaks();}));
278	    document.querySelectorAll('.brk-o').forEach(e=>e.addEventListener('change',()=>breaksDraft[+e.dataset.i].open=e.value));
279	    document.querySelectorAll('.brk-c').forEach(e=>e.addEventListener('change',()=>breaksDraft[+e.dataset.i].close=e.value)); }
280	  function setRepeat(m){ repeatMode=m; document.querySelectorAll('.ss-seg-btn').forEach(b=>b.classList.toggle('active',b.dataset.repeat===m));
281	    document.getElementById('weeklyRow').style.display=m==='weekly'?'':'none'; document.getElementById('oneoffRow').style.display=m==='oneoff'?'':'none'; document.getElementById('validRow').style.display=m==='weekly'?'':'none'; }
282	  function showErr(m){ document.getElementById('shiftErr').textContent=m||''; }
