284	  function openAdd(dateIso){
285	    const d=dateIso?new Date(dateIso+'T00:00:00'):new Date();
286	    document.getElementById('shiftModalTitle').textContent='Add Shift'; document.getElementById('shiftId').value='';
287	    document.getElementById('fStaff').selectedIndex=0; setRepeat('weekly');
288	    selectedDays=new Set([d.getDay()]); renderDays();
289	    document.getElementById('fDate').value=dateIso||iso(new Date());
