291	    document.getElementById('fLabel').value=''; document.getElementById('fValidFrom').value=''; document.getElementById('fValidTo').value='';
292	    colorSel='#EA6A24'; document.getElementById('fColor').value=colorSel; breaksDraft=[{open:'12:00',close:'13:00'}]; editingOccDate=null;
293	    document.getElementById('deleteShiftBtn').style.display='none'; document.getElementById('skipDayBtn').style.display='none';
294	    renderSwatches(); renderBreaks(); showErr(''); if(!staffList.length) showErr('No active staff — add staff in Team first.');
295	    modal.style.display='flex';
