297	  async function openEdit(o){
298	    let raw=null; try{ raw=(await(await fetch(`${API}/api/staff-shifts/raw`,H)).json()).find(s=>s.id===o.shiftId); }catch(e){}
299	    if(!raw) return;
300	    document.getElementById('shiftModalTitle').textContent='Edit Shift'; document.getElementById('shiftId').value=raw.id;
301	    document.getElementById('fStaff').value=raw.staffId; setRepeat(raw.isRecurring?'weekly':'oneoff');
