303	    document.getElementById('fDate').value=raw.specificDate||o.date;
304	    document.getElementById('fStart').value=raw.startTime; document.getElementById('fEnd').value=raw.endTime;
305	    document.getElementById('fLabel').value=raw.label||''; document.getElementById('fValidFrom').value=raw.validFrom||''; document.getElementById('fValidTo').value=raw.validTo||'';
306	    colorSel=raw.color||'#EA6A24'; document.getElementById('fColor').value=colorSel; breaksDraft=(raw.breaks||[]).map(b=>({open:b.open,close:b.close})); editingOccDate=o.date;
307	    document.getElementById('deleteShiftBtn').style.display=''; document.getElementById('skipDayBtn').style.display=raw.isRecurring?'':'none';
308	    renderSwatches(); renderBreaks(); showErr(''); modal.style.display='flex';
