310	  function collect(){ const rec=repeatMode==='weekly'; return { staffId:document.getElementById('fStaff').value, isRecurring:rec, daysOfWeek:[...selectedDays], specificDate:rec?null:document.getElementById('fDate').value, startTime:document.getElementById('fStart').value, endTime:document.getElementById('fEnd').value, breaks:breaksDraft.filter(b=>b.open&&b.close), label:document.getElementById('fLabel').value||null, color:document.getElementById('fColor').value, validFrom:rec?(document.getElementById('fValidFrom').value||null):null, validTo:rec?(document.getElementById('fValidTo').value||null):null }; }
311	  async function save(){
312	    const id=document.getElementById('shiftId').value, body=collect();
313	    if(!body.staffId) return showErr('Choose a staff member.');
314	    if(body.endTime<=body.startTime) return showErr('End time must be after start time.');
315	    if(body.isRecurring && !body.daysOfWeek.length) return showErr('Pick at least one day of the week.');
316	    if(!body.isRecurring && !body.specificDate) return showErr('Choose a date.');
317	    const btn=document.getElementById('saveShiftBtn'); btn.disabled=true; btn.textContent='Saving…';
318	    try{ const res=id?await fetch(`${API}/api/staff-shifts/${id}`,{method:'PUT',...HJ,body:JSON.stringify(body)}):await fetch(`${API}/api/staff-shifts`,{method:'POST',...HJ,body:JSON.stringify(body)});
319	      if(!res.ok){ const e=await res.json().catch(()=>({})); btn.disabled=false; btn.textContent='Save shift'; return showErr(e.message||`Could not save (HTTP ${res.status}).`); }
320	      modal.style.display='none'; btn.disabled=false; btn.textContent='Save shift'; load();
321	    }catch(e){ btn.disabled=false; btn.textContent='Save shift'; showErr('Network error.'); }
322	  }
