326	  modal.addEventListener('click', e=>{ if(e.target===modal) modal.style.display='none'; });
327	  document.querySelectorAll('.ss-seg-btn').forEach(b=>b.addEventListener('click',()=>setRepeat(b.dataset.repeat)));
328	  document.querySelectorAll('#fDays .ss-day').forEach(b=>b.addEventListener('click',()=>{const d=Number(b.dataset.d);selectedDays.has(d)?selectedDays.delete(d):selectedDays.add(d);renderDays();}));
329	  document.querySelectorAll('.ss-quick').forEach(b=>b.addEventListener('click',()=>{selectedDays=new Set(b.dataset.set.split(',').map(Number));renderDays();}));
330	  document.getElementById('addBreakBtn').addEventListener('click', ()=>{breaksDraft.push({open:'12:00',close:'13:00'});renderBreaks();});
331	  document.getElementById('saveShiftBtn').addEventListener('click', save);
332	  document.getElementById('deleteShiftBtn').addEventListener('click', async ()=>{ const id=document.getElementById('shiftId').value; if(!id||!confirm('Delete this entire shift (all occurrences)?'))return; await fetch(`${API}/api/staff-shifts/${id}`,{method:'DELETE',headers:H.headers}); modal.style.display='none'; load(); });
333	  document.getElementById('skipDayBtn').addEventListener('click', async ()=>{ const id=document.getElementById('shiftId').value; if(!id||!editingOccDate||!confirm('Remove just this day?'))return; await fetch(`${API}/api/staff-shifts/${id}/skip`,{method:'POST',...HJ,body:JSON.stringify({date:editingOccDate})}); modal.style.display='none'; load(); });
334	  document.getElementById('prevBtn').addEventListener('click', ()=>{ weekStart=addDays(weekStart,-7); load(); });
335	  document.getElementById('nextBtn').addEventListener('click', ()=>{ weekStart=addDays(weekStart,7); load(); });
336	  document.getElementById('todayBtn').addEventListener('click', ()=>{ weekStart=mondayOf(new Date()); load(); });
337	  document.getElementById('staffFilter').addEventListener('change', load);
338	
339	  (async function init(){ await loadStaff(); await load(); })();
340	</script>
