using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.API.Controllers;

/// <summary>
/// Staff work-schedule (shifts + lunch breaks). Admins/managers/reception manage
/// everyone's shifts; staff read their own via <c>mine/occurrences</c>.
/// </summary>
[ApiController]
[Route("api/staff-shifts")]
public class StaffShiftController : ControllerBase
{
    private readonly IStaffShiftService _shifts;

    public StaffShiftController(IStaffShiftService shifts) => _shifts = shifts;

    // ── Admin management ──────────────────────────────────────────────

    /// <summary>Raw shift definitions (for editing). Optionally filter by staffId.</summary>
    [HttpGet("raw")]
    [Authorize(Roles = "Admin,Manager,Receptionist")]
    public async Task<IActionResult> GetRaw([FromQuery] string? staffId)
        => Ok(await _shifts.GetShiftsAsync(staffId));

    /// <summary>Expanded dated occurrences for a calendar view, [from, to] inclusive (yyyy-MM-dd).</summary>
    [HttpGet("occurrences")]
    [Authorize(Roles = "Admin,Manager,Receptionist")]
    public async Task<IActionResult> GetOccurrences(
        [FromQuery] string from, [FromQuery] string to, [FromQuery] string? staffId)
    {
        if (!DateOnly.TryParse(from, out var f) || !DateOnly.TryParse(to, out var t))
            return BadRequest(new { message = "from and to must be yyyy-MM-dd." });
        return Ok(await _shifts.GetScheduleAsync(f, t, staffId));
    }

    [HttpPost]
    [Authorize(Roles = "Admin,Manager,Receptionist")]
    public async Task<IActionResult> Create([FromBody] StaffShift shift)
    {
        try { return Ok(await _shifts.CreateAsync(shift)); }
        catch (ArgumentException ex) { return BadRequest(new { message = ex.Message }); }
    }

    [HttpPut("{id}")]
    [Authorize(Roles = "Admin,Manager,Receptionist")]
    public async Task<IActionResult> Update(string id, [FromBody] StaffShift shift)
    {
        try
        {
            var ok = await _shifts.UpdateAsync(id, shift);
            return ok ? Ok(new { success = true }) : NotFound();
        }
        catch (ArgumentException ex) { return BadRequest(new { message = ex.Message }); }
    }

    [HttpDelete("{id}")]
    [Authorize(Roles = "Admin,Manager,Receptionist")]
    public async Task<IActionResult> Delete(string id)
        => (await _shifts.DeleteAsync(id)) ? Ok(new { success = true }) : NotFound();

    /// <summary>Skip/remove a single occurrence of a recurring shift ("delete this event").</summary>
    [HttpPost("{id}/skip")]
    [Authorize(Roles = "Admin,Manager,Receptionist")]
    public async Task<IActionResult> Skip(string id, [FromBody] SkipRequest req)
        => (await _shifts.SkipOccurrenceAsync(id, req?.Date ?? ""))
            ? Ok(new { success = true }) : NotFound();

    public class SkipRequest { public string? Date { get; set; } }

    // ── Staff self-service (read-only own schedule) ───────────────────

    /// <summary>The signed-in staff member's own shift occurrences for a date range.</summary>
    [HttpGet("mine/occurrences")]
    [Authorize]
    public async Task<IActionResult> GetMine([FromQuery] string from, [FromQuery] string to)
    {
        var staffId = User.FindFirst("staff_id")?.Value;
        if (string.IsNullOrWhiteSpace(staffId))
            return NotFound(new { profileLinked = false });
        if (!DateOnly.TryParse(from, out var f) || !DateOnly.TryParse(to, out var t))
            return BadRequest(new { message = "from and to must be yyyy-MM-dd." });
        return Ok(await _shifts.GetScheduleAsync(f, t, staffId));
    }
}

