---
import InstructorLayout from '../../layouts/InstructorLayout.astro';
---
<InstructorLayout title="My hours" activePage="hours">
  <div class="page-header">
    <div>
      <div class="page-title">My hours</div>
      <div class="page-subtitle">Your work shifts &amp; lunch breaks — set by the studio.</div>
    </div>
  </div>

  <div class="ss-toolbar">
    <div class="ss-nav">
      <button class="ss-navbtn" id="prevBtn">‹</button>
      <button class="ss-today" id="todayBtn">Today</button>
      <button class="ss-navbtn" id="nextBtn">›</button>
      <span class="ss-period"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:15px;height:15px;"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg><strong id="periodLabel">—</strong></span>
      <div class="ss-viewtog">
        <button type="button" class="ss-vt active" data-view="week">Week</button>
        <button type="button" class="ss-vt" data-view="month">Month</button>
      </div>
    </div>
  </div>

  <div class="ss-cal" id="weekCal">
    <div class="ss-head" id="calHead"></div>
    <div class="ss-body">
      <div class="ss-gutter" id="gutter"></div>
      <div class="ss-cols" id="cols"></div>
    </div>
  </div>

  <div class="ss-month" id="monthCal" style="display:none;">
    <div class="ss-mhead"><div>Mon</div><div>Tue</div><div>Wed</div><div>Thu</div><div>Fri</div><div>Sat</div><div>Sun</div></div>
    <div class="ss-mgrid" id="monthGrid"></div>
  </div>

  <div class="ss-overview">
    <div class="ss-ov-title"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:16px;height:16px;"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg> <span id="ovTitle">Weekly Overview</span></div>
    <div class="ss-ov-stat"><span>Shifts</span><strong id="ovShifts">0</strong></div>
    <div class="ss-ov-stat"><span>Working Hours</span><strong id="ovWork">0h</strong></div>
    <div class="ss-ov-stat"><span>Lunch Hours</span><strong id="ovLunch">0h</strong></div>
  </div>
  <div class="ss-tip" id="emptyTip" style="display:none;">🌙 No shifts scheduled for this period.</div>
</InstructorLayout>

<style is:global>
  .ss-toolbar { display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:12px; margin-bottom:14px; }
  .ss-nav { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
  .ss-navbtn { width:34px; height:34px; border-radius:9px; border:1px solid var(--color-border-subtle); background:var(--color-surface-raised,rgba(255,255,255,.03)); color:var(--color-text-primary); font-size:18px; cursor:pointer; }
  .ss-navbtn:hover { background:var(--color-brand-soft); }
  .ss-today { border:1px solid var(--color-border-subtle); background:var(--color-surface-raised,rgba(255,255,255,.03)); color:var(--color-text-primary); border-radius:9px; padding:7px 14px; font-size:13px; cursor:pointer; }
  .ss-period { display:inline-flex; align-items:center; gap:7px; margin-left:8px; color:var(--color-text-primary); font-size:15px; }
  .ss-viewtog { display:inline-flex; margin-left:10px; border:1px solid var(--color-border-subtle); border-radius:9px; overflow:hidden; }
  .ss-vt { background:transparent; border:none; padding:7px 14px; font-size:13px; cursor:pointer; color:var(--color-text-muted); }
  .ss-vt.active { background:var(--color-brand-accent); color:#fff; font-weight:600; }

  .ss-cal { border:1px solid var(--color-border-subtle); border-radius:14px; overflow:hidden; background:var(--color-surface,rgba(255,255,255,.015)); box-shadow:var(--sp-shadow-card,0 1px 3px rgba(0,0,0,.15)); }
  .ss-head { display:grid; grid-template-columns:58px repeat(7,1fr); background:var(--color-surface-raised,rgba(255,255,255,.03)); border-bottom:1px solid var(--color-border-subtle); }
  .ss-head > div { padding:10px 10px; text-align:center; border-left:1px solid var(--color-border-subtle); }
  .ss-head > div:first-child { border-left:none; }
  .ss-head .dn { font-size:11px; font-weight:700; letter-spacing:.05em; color:var(--color-text-muted); text-transform:uppercase; }
  .ss-head .dd { font-size:16px; font-weight:700; color:var(--color-text-primary); }
  .ss-head .today .dd { background:var(--color-brand-accent); color:#fff; border-radius:50%; width:28px; height:28px; display:inline-flex; align-items:center; justify-content:center; }
  .ss-body { display:grid; grid-template-columns:58px 1fr; }
  .ss-gutter { position:relative; }
  .ss-ghour { height:40px; font-size:10px; color:var(--color-text-muted); text-align:right; padding-right:6px; box-sizing:border-box; border-bottom:1px solid var(--color-border-subtle); }
  .ss-cols { display:grid; grid-template-columns:repeat(7,1fr); }
  .ss-col { position:relative; border-left:1px solid var(--color-border-subtle); }
  .ss-col .ss-hline { height:40px; border-bottom:1px solid var(--color-border-subtle); box-sizing:border-box; }
  .ss-seg-block { position:absolute; border-radius:8px; padding:4px 7px; font-size:11px; overflow:hidden; box-sizing:border-box; }
  .ss-seg-work { border:1px solid; }
  .ss-seg-work .sn { font-weight:700; display:flex; align-items:center; gap:5px; }
  .ss-seg-work .sn .d { width:8px; height:8px; border-radius:50%; }
  .ss-seg-work .st { color:var(--color-text-muted); font-size:10px; margin-top:1px; }
  .ss-seg-break { background:rgba(148,163,184,.16); border:1px dashed rgba(148,163,184,.55); color:#94A3B8; }
  .ss-seg-break .bt { font-weight:700; display:flex; align-items:center; gap:4px; }
  .ss-seg-break .bh { font-size:10px; opacity:.9; }
  .ss-empty { position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center; color:var(--color-text-muted); pointer-events:none; opacity:.5; }
  .ss-empty svg { width:22px; height:22px; margin-bottom:6px; }
  .ss-empty .e1 { font-size:12px; font-weight:600; }
  .ss-empty .e2 { font-size:11px; }

  .ss-month { border:1px solid var(--color-border-subtle); border-radius:14px; overflow:hidden; background:var(--color-surface,rgba(255,255,255,.015)); }
  .ss-mhead { display:grid; grid-template-columns:repeat(7,1fr); background:var(--color-surface-raised,rgba(255,255,255,.03)); border-bottom:1px solid var(--color-border-subtle); }
  .ss-mhead > div { padding:9px 10px; font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.05em; color:var(--color-text-muted); text-align:center; }
  .ss-mgrid { display:grid; grid-template-columns:repeat(7,1fr); grid-auto-rows:minmax(96px,1fr); }
  .ss-mcell { border-right:1px solid var(--color-border-subtle); border-bottom:1px solid var(--color-border-subtle); padding:6px 7px; min-height:96px; overflow:hidden; }
  .ss-mcell:nth-child(7n){ border-right:none; }
  .ss-mcell.other { background:var(--color-surface-raised,rgba(0,0,0,.12)); }
  .ss-mcell.other .ss-mdn { opacity:.35; }
  .ss-mdn { font-size:13px; font-weight:600; margin-bottom:4px; }
  .ss-mcell.today .ss-mdn { background:var(--color-brand-accent); color:#fff; border-radius:50%; width:24px; height:24px; display:inline-flex; align-items:center; justify-content:center; }
  .ss-mchip { display:flex; align-items:center; gap:5px; border-radius:6px; padding:2px 6px; margin-bottom:3px; font-size:11px; line-height:1.4; border:1px solid; }
  .ss-mchip .tm { font-weight:600; white-space:nowrap; }
  .ss-mchip .lb { color:var(--color-text-muted); font-size:10px; margin-left:auto; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }

  .ss-overview { display:flex; align-items:center; gap:28px; flex-wrap:wrap; margin-top:16px; padding:16px 20px; border:1px solid var(--color-border-subtle); border-radius:14px; background:var(--color-surface-raised,rgba(255,255,255,.03)); }
  .ss-ov-title { display:flex; align-items:center; gap:8px; font-weight:700; font-size:14px; }
  .ss-ov-stat { display:flex; flex-direction:column; }
  .ss-ov-stat span { font-size:11px; color:var(--color-text-muted); text-transform:uppercase; letter-spacing:.04em; }
  .ss-ov-stat strong { font-size:20px; color:var(--color-brand-accent); }
  .ss-tip { margin-top:10px; text-align:center; font-size:12.5px; color:var(--color-text-muted); }
</style>

<script>
  const API = import.meta.env.PUBLIC_API_URL;
  const token = localStorage.getItem('token');
  const H = { headers: { Authorization: 'Bearer ' + token } };
  const DOW = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  const DAY_START = 7, DAY_END = 20, HOUR_PX = 40;
  const BRAND = '#EA6A24';

  let weekStart = mondayOf(new Date());
  let monthAnchor = (()=>{ const d=new Date(); d.setDate(1); d.setHours(0,0,0,0); return d; })();
  let viewMode = 'week';

  function mondayOf(d){ const x=new Date(d); const o=(x.getDay()+6)%7; x.setDate(x.getDate()-o); x.setHours(0,0,0,0); return x; }
  const iso = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const addDays = (d,n) => { const x=new Date(d); x.setDate(x.getDate()+n); return x; };
  const toMin = t => { const [h,m]=(t||'0:0').split(':').map(Number); return h*60+m; };
  const fmtT = m => { let h=Math.floor(m/60), mm=m%60; const ap=h>=12?'PM':'AM'; h=h%12||12; return `${h}:${String(mm).padStart(2,'0')} ${ap}`; };
  const esc = s => String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const hex2rgba = (h,a) => { const n=parseInt(h.slice(1),16); return `rgba(${(n>>16)&255},${(n>>8)&255},${n&255},${a})`; };
  const vparam = () => (typeof window.getViewAsParam==='function' ? window.getViewAsParam() : '');

  async function fetchOcc(from, to) {
    let occ=[];
    try { const r=await fetch(`${API}/api/staff-shifts/mine/occurrences?from=${from}&to=${to}`+vparam(), H); occ=r.ok?await r.json():[]; } catch(e){}
    return occ;
  }

  async function load() {
    if (viewMode === 'month') return loadMonth();
    document.getElementById('periodLabel').textContent = addDays(weekStart,3).toLocaleDateString('en-US',{month:'long',year:'numeric'});
    render(await fetchOcc(iso(weekStart), iso(addDays(weekStart,6))));
  }
  async function loadMonth() {
    document.getElementById('periodLabel').textContent = monthAnchor.toLocaleDateString('en-US',{month:'long',year:'numeric'});
    const gs = mondayOf(monthAnchor), ge = addDays(gs,41);
    renderMonth(await fetchOcc(iso(gs), iso(ge)), gs);
  }

  function segments(o) {
    const s=toMin(o.startTime), e=toMin(o.endTime), out=[];
    const brs=(o.breaks||[]).map(b=>({s:toMin(b.open),e:toMin(b.close)})).filter(b=>b.e>b.s&&b.s>=s&&b.e<=e).sort((a,b)=>a.s-b.s);
    let cur=s;
    brs.forEach(b=>{ if(b.s>cur) out.push({t:'work',s:cur,e:b.s}); out.push({t:'break',s:b.s,e:b.e}); cur=b.e; });
    if(e>cur) out.push({t:'work',s:cur,e});
    return out;
  }

  function render(occ) {
    const todayIso = iso(new Date());
    let head = '<div></div>';
    for(let i=0;i<7;i++){ const d=addDays(weekStart,i); head+=`<div class="${iso(d)===todayIso?'today':''}"><div class="dn">${DOW[d.getDay()]}</div><div class="dd">${d.getDate()}</div></div>`; }
    document.getElementById('calHead').innerHTML = head;
    let g=''; for(let h=DAY_START;h<DAY_END;h++){ const ap=h>=12?'PM':'AM',hh=h%12||12; g+=`<div class="ss-ghour">${hh} ${ap}</div>`; }
    document.getElementById('gutter').innerHTML = g;

    const byDay={}; occ.forEach(o=>{(byDay[o.date]=byDay[o.date]||[]).push(o);});
    let cols='';
    for(let i=0;i<7;i++){
      const d=addDays(weekStart,i), dIso=iso(d);
      const items=(byDay[dIso]||[]).slice().sort((a,b)=>toMin(a.startTime)-toMin(b.startTime));
      let inner=''; for(let h=DAY_START;h<DAY_END;h++) inner+='<div class="ss-hline"></div>';
      if(!items.length){
        inner += `<div class="ss-empty"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5L19 19M19 5l-1.5 1.5M6.5 17.5L5 19"/></svg><div class="e1">No shifts</div><div class="e2">Day off</div></div>`;
      } else {
        const lanes=[]; items.forEach(o=>{ const s=toMin(o.startTime),e=toMin(o.endTime); let pl=false; for(let l=0;l<lanes.length;l++){ if(lanes[l]<=s){ o._l=l; lanes[l]=e; pl=true; break; } } if(!pl){ o._l=lanes.length; lanes.push(e); } });
        const nL=lanes.length||1;
        items.forEach(o=>{
          const col=o.color||BRAND;
          const left=(o._l/nL)*100, width=(1/nL)*100;
          segments(o).forEach(seg=>{
            const top=(seg.s-DAY_START*60)/60*HOUR_PX, hgt=Math.max(20,(seg.e-seg.s)/60*HOUR_PX);
            const style=`top:${top}px;height:${hgt}px;left:calc(${left}% + 3px);width:calc(${width}% - 6px);`;
            if(seg.t==='work'){
              inner+=`<div class="ss-seg-block ss-seg-work" style="${style}background:${hex2rgba(col,.16)};border-color:${hex2rgba(col,.5)};">
                <div class="sn"><span class="d" style="background:${col}"></span>${esc(o.label||'Working')}</div>
                <div class="st">${fmtT(seg.s)} – ${fmtT(seg.e)}</div></div>`;
            } else {
              inner+=`<div class="ss-seg-block ss-seg-break" style="${style}">
                <div class="bt">🍴 Lunch Break</div><div class="bh">${fmtT(seg.s)} – ${fmtT(seg.e)}</div></div>`;
            }
          });
        });
      }
      cols+=`<div class="ss-col">${inner}</div>`;
    }
    document.getElementById('cols').innerHTML = cols;
    updateOverview(occ);
  }

  function renderMonth(occ, gs) {
    const todayIso = iso(new Date()), mo = monthAnchor.getMonth();
    const byDay={}; occ.forEach(o=>{(byDay[o.date]=byDay[o.date]||[]).push(o);});
    let html='';
    for(let i=0;i<42;i++){
      const d=addDays(gs,i), dIso=iso(d), cls=['ss-mcell'];
      if(d.getMonth()!==mo) cls.push('other');
      if(dIso===todayIso) cls.push('today');
      const items=(byDay[dIso]||[]).slice().sort((a,b)=>toMin(a.startTime)-toMin(b.startTime));
      let chips='';
      items.slice(0,3).forEach(o=>{
        const col=o.color||BRAND;
        chips+=`<div class="ss-mchip" style="background:${hex2rgba(col,.14)};border-color:${hex2rgba(col,.45)};"><span class="tm">${fmtT(toMin(o.startTime))}–${fmtT(toMin(o.endTime))}</span>${o.label?`<span class="lb">${esc(o.label)}</span>`:''}</div>`;
      });
      if(items.length>3) chips+=`<div class="ss-mchip" style="border-color:transparent;"><span class="lb">+${items.length-3} more</span></div>`;
      html+=`<div class="${cls.join(' ')}"><div class="ss-mdn">${d.getDate()}</div>${chips}</div>`;
    }
    document.getElementById('monthGrid').innerHTML=html;
    updateOverview(occ);
  }

  function updateOverview(occ) {
    let work=0, lunch=0;
    occ.forEach(o=>{ const dur=toMin(o.endTime)-toMin(o.startTime); let br=0; (o.breaks||[]).forEach(b=>br+=Math.max(0,toMin(b.close)-toMin(b.open))); work+=(dur-br); lunch+=br; });
    document.getElementById('ovShifts').textContent = occ.length;
    document.getElementById('ovWork').textContent = Math.round(work/60)+'h';
    document.getElementById('ovLunch').textContent = Math.round(lunch/60)+'h';
    document.getElementById('emptyTip').style.display = occ.length?'none':'block';
  }

  function setView(v){
    viewMode=v;
    document.querySelectorAll('.ss-vt').forEach(b=>b.classList.toggle('active',b.dataset.view===v));
    document.getElementById('weekCal').style.display = v==='week'?'':'none';
    document.getElementById('monthCal').style.display = v==='month'?'':'none';
    document.getElementById('ovTitle').textContent = v==='week'?'Weekly Overview':'Monthly Overview';
    load();
  }
  document.querySelectorAll('.ss-vt').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
  document.getElementById('prevBtn').addEventListener('click', ()=>{ if(viewMode==='month'){ monthAnchor.setMonth(monthAnchor.getMonth()-1); } else { weekStart=addDays(weekStart,-7); } load(); });
  document.getElementById('nextBtn').addEventListener('click', ()=>{ if(viewMode==='month'){ monthAnchor.setMonth(monthAnchor.getMonth()+1); } else { weekStart=addDays(weekStart,7); } load(); });
  document.getElementById('todayBtn').addEventListener('click', ()=>{ if(viewMode==='month'){ monthAnchor=new Date(); monthAnchor.setDate(1); monthAnchor.setHours(0,0,0,0); } else { weekStart=mondayOf(new Date()); } load(); });
  load();
</script>
</InstructorLayout>

