  .ss-ov-title { display:flex; align-items:center; gap:8px; font-weight:700; font-size:14px; }
  .ss-ov-stat { display:flex; flex-direction:column; }
  .ss-ov-stat span { font-size:11px; color:var(--color-text-muted); text-transform:uppercase; letter-spacing:.04em; }
  .ss-ov-stat strong { font-size:20px; color:var(--color-brand-accent); }
  .ss-tip { margin-top:10px; text-align:center; font-size:12.5px; color:var(--color-text-muted); }
</style>

<script>
  const API = import.meta.env.PUBLIC_API_URL;
  const token = localStorage.getItem('token');
  const H = { headers: { Authorization: 'Bearer ' + token } };
  const DOW = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  const DAY_START = 7, DAY_END = 20, HOUR_PX = 40;
  const BRAND = '#EA6A24';

  let weekStart = mondayOf(new Date());
  let monthAnchor = (()=>{ const d=new Date(); d.setDate(1); d.setHours(0,0,0,0); return d; })();
  let viewMode = 'week';

  function mondayOf(d){ const x=new Date(d); const o=(x.getDay()+6)%7; x.setDate(x.getDate()-o); x.setHours(0,0,0,0); return x; }
  const iso = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const addDays = (d,n) => { const x=new Date(d); x.setDate(x.getDate()+n); return x; };
  const toMin = t => { const [h,m]=(t||'0:0').split(':').map(Number); return h*60+m; };
  const fmtT = m => { let h=Math.floor(m/60), mm=m%60; const ap=h>=12?'PM':'AM'; h=h%12||12; return `${h}:${String(mm).padStart(2,'0')} ${ap}`; };
  const esc = s => String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const hex2rgba = (h,a) => { const n=parseInt(h.slice(1),16); return `rgba(${(n>>16)&255},${(n>>8)&255},${n&255},${a})`; };
  const vparam = () => (typeof window.getViewAsParam==='function' ? window.getViewAsParam() : '');

  async function fetchOcc(from, to) {
    let occ=[];
    try { const r=await fetch(`${API}/api/staff-shifts/mine/occurrences?from=${from}&to=${to}`+vparam(), H); occ=r.ok?await r.json():[]; } catch(e){}
    return occ;
  }

  async function load() {
    if (viewMode === 'month') return loadMonth();
    document.getElementById('periodLabel').textContent = addDays(weekStart,3).toLocaleDateString('en-US',{month:'long',year:'numeric'});
    render(await fetchOcc(iso(weekStart), iso(addDays(weekStart,6))));
  }
  async function loadMonth() {
    document.getElementById('periodLabel').textContent = monthAnchor.toLocaleDateString('en-US',{month:'long',year:'numeric'});
    const gs = mondayOf(monthAnchor), ge = addDays(gs,41);
    renderMonth(await fetchOcc(iso(gs), iso(ge)), gs);
  }

  function segments(o) {
    const s=toMin(o.startTime), e=toMin(o.endTime), out=[];
    const brs=(o.breaks||[]).map(b=>({s:toMin(b.open),e:toMin(b.close)})).filter(b=>b.e>b.s&&b.s>=s&&b.e<=e).sort((a,b)=>a.s-b.s);
    let cur=s;
    brs.forEach(b=>{ if(b.s>cur) out.push({t:'work',s:cur,e:b.s}); out.push({t:'break',s:b.s,e:b.e}); cur=b.e; });
    if(e>cur) out.push({t:'work',s:cur,e});
    return out;
  }

  function render(occ) {
    const todayIso = iso(new Date());
    let head = '<div></div>';
    for(let i=0;i<7;i++){ const d=addDays(weekStart,i); head+=`<div class="${iso(d)===todayIso?'today':''}"><div class="dn">${DOW[d.getDay()]}</div><div class="dd">${d.getDate()}</div></div>`; }
    document.getElementById('calHead').innerHTML = head;
    let g=''; for(let h=DAY_START;h<DAY_END;h++){ const ap=h>=12?'PM':'AM',hh=h%12||12; g+=`<div class="ss-ghour">${hh} ${ap}</div>`; }
    document.getElementById('gutter').innerHTML = g;

    const byDay={}; occ.forEach(o=>{(byDay[o.date]=byDay[o.date]||[]).push(o);});
    let cols='';
    for(let i=0;i<7;i++){
      const d=addDays(weekStart,i), dIso=iso(d);
      const items=(byDay[dIso]||[]).slice().sort((a,b)=>toMin(a.startTime)-toMin(b.startTime));
      let inner=''; for(let h=DAY_START;h<DAY_END;h++) inner+='<div class="ss-hline"></div>';
      if(!items.length){
        inner += `<div class="ss-empty"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5L19 19M19 5l-1.5 1.5M6.5 17.5L5 19"/></svg><div class="e1">No shifts</div><div class="e2">Day off</div></div>`;
      } else {
        const lanes=[]; items.forEach(o=>{ const s=toMin(o.startTime),e=toMin(o.endTime); let pl=false; for(let l=0;l<lanes.length;l++){ if(lanes[l]<=s){ o._l=l; lanes[l]=e; pl=true; break; } } if(!pl){ o._l=lanes.length; lanes.push(e); } });
        const nL=lanes.length||1;
        items.forEach(o=>{
          const col=o.color||BRAND;
          const left=(o._l/nL)*100, width=(1/nL)*100;
          segments(o).forEach(seg=>{
            const top=(seg.s-DAY_START*60)/60*HOUR_PX, hgt=Math.max(20,(seg.e-seg.s)/60*HOUR_PX);
            const style=`top:${top}px;height:${hgt}px;left:calc(${left}% + 3px);width:calc(${width}% - 6px);`;
            if(seg.t==='work'){
              inner+=`<div class="ss-seg-block ss-seg-work" style="${style}background:${hex2rgba(col,.16)};border-color:${hex2rgba(col,.5)};">
                <div class="sn"><span class="d" style="background:${col}"></span>${esc(o.label||'Working')}</div>
                <div class="st">${fmtT(seg.s)} – ${fmtT(seg.e)}</div></div>`;
            } else {
              inner+=`<div class="ss-seg-block ss-seg-break" style="${style}">
                <div class="bt">🍴 Lunch Break</div><div class="bh">${fmtT(seg.s)} – ${fmtT(seg.e)}</div></div>`;
            }
          });
        });
      }
      cols+=`<div class="ss-col">${inner}</div>`;
    }
    document.getElementById('cols').innerHTML = cols;
    updateOverview(occ);
  }

  function renderMonth(occ, gs) {
    const todayIso = iso(new Date()), mo = monthAnchor.getMonth();
    const byDay={}; occ.forEach(o=>{(byDay[o.date]=byDay[o.date]||[]).push(o);});
    let html='';
    for(let i=0;i<42;i++){
      const d=addDays(gs,i), dIso=iso(d), cls=['ss-mcell'];
      if(d.getMonth()!==mo) cls.push('other');
      if(dIso===todayIso) cls.push('today');
      const items=(byDay[dIso]||[]).slice().sort((a,b)=>toMin(a.startTime)-toMin(b.startTime));
      let chips='';
      items.slice(0,3).forEach(o=>{
        const col=o.color||BRAND;
        chips+=`<div class="ss-mchip" style="background:${hex2rgba(col,.14)};border-color:${hex2rgba(col,.45)};"><span class="tm">${fmtT(toMin(o.startTime))}–${fmtT(toMin(o.endTime))}</span>${o.label?`<span class="lb">${esc(o.label)}</span>`:''}</div>`;
      });
      if(items.length>3) chips+=`<div class="ss-mchip" style="border-color:transparent;"><span class="lb">+${items.length-3} more</span></div>`;
      html+=`<div class="${cls.join(' ')}"><div class="ss-mdn">${d.getDate()}</div>${chips}</div>`;
    }
    document.getElementById('monthGrid').innerHTML=html;
    updateOverview(occ);
  }

  function updateOverview(occ) {
    let work=0, lunch=0;
    occ.forEach(o=>{ const dur=toMin(o.endTime)-toMin(o.startTime); let br=0; (o.breaks||[]).forEach(b=>br+=Math.max(0,toMin(b.close)-toMin(b.open))); work+=(dur-br); lunch+=br; });
    document.getElementById('ovShifts').textContent = occ.length;
    document.getElementById('ovWork').textContent = Math.round(work/60)+'h';
    document.getElementById('ovLunch').textContent = Math.round(lunch/60)+'h';
    document.getElementById('emptyTip').style.display = occ.length?'none':'block';
  }

  function setView(v){
    viewMode=v;
    document.querySelectorAll('.ss-vt').forEach(b=>b.classList.toggle('active',b.dataset.view===v));
    document.getElementById('weekCal').style.display = v==='week'?'':'none';
    document.getElementById('monthCal').style.display = v==='month'?'':'none';
    document.getElementById('ovTitle').textContent = v==='week'?'Weekly Overview':'Monthly Overview';
    load();
  }
  document.querySelectorAll('.ss-vt').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
  document.getElementById('prevBtn').addEventListener('click', ()=>{ if(viewMode==='month'){ monthAnchor.setMonth(monthAnchor.getMonth()-1); } else { weekStart=addDays(weekStart,-7); } load(); });
  document.getElementById('nextBtn').addEventListener('click', ()=>{ if(viewMode==='month'){ monthAnchor.setMonth(monthAnchor.getMonth()+1); } else { weekStart=addDays(weekStart,7); } load(); });
  document.getElementById('todayBtn').addEventListener('click', ()=>{ if(viewMode==='month'){ monthAnchor=new Date(); monthAnchor.setDate(1); monthAnchor.setHours(0,0,0,0); } else { weekStart=mondayOf(new Date()); } load(); });
  load();
</script>
</InstructorLayout>

