/// <summary>Persistence + querying for the outbound email audit log.</summary>
public interface IEmailLogService
{
    /// <summary>Record one send attempt. Never throws — email logging must not break a send.</summary>
    Task RecordAsync(EmailLog log);

    /// <summary>
    /// Paged, newest-first query. Optional <paramref name="status"/> filter and
    /// <paramref name="search"/> (matches recipient or subject, case-insensitive).
    /// </summary>
    Task<EmailLogPage> QueryAsync(int page, int pageSize, string? status = null, string? search = null);
}

/// <summary>A page of email-log rows plus the total count for pagination.</summary>
public class EmailLogPage
{
    public List<EmailLog> Items { get; set; } = new();
    public long Total { get; set; }
}

