using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.API.Controllers;

/// <summary>
/// Read-only access to the outbound email audit log for the admin "Email Log" page.
/// </summary>
[ApiController]
[Route("api/email-logs")]
[Authorize(Roles = "Admin,Owner,SuperAdmin")]
public class EmailLogController : ControllerBase
{
    private readonly IEmailLogService _emailLogs;

    public EmailLogController(IEmailLogService emailLogs) => _emailLogs = emailLogs;

    /// <summary>Newest-first, paged email log. Optional status + free-text (recipient/subject) filters.</summary>
    [HttpGet]
    public async Task<IActionResult> Get(
        [FromQuery] int page = 1,
        [FromQuery] int pageSize = 50,
        [FromQuery] string? status = null,
        [FromQuery] string? search = null)
    {
        var result = await _emailLogs.QueryAsync(page, pageSize, status, search);
        return Ok(new
        {
            total = result.Total,
            page,
            pageSize,
            items = result.Items.Select(l => new
            {
                l.Id,
                l.To,
                l.Subject,
                l.Status,
                l.Error,
                l.RedirectedTo,
                l.CreatedAt,
            }),
        });
    }
}

