49	    public async Task<ReceptionistKpiDashboardDto> GetDashboardAsync(
50	        int year,
51	        int month,
52	        string? staffId,
53	        string? selectedDateKey,
54	        bool isAdminView,
55	        CancellationToken ct = default)
56	    {
57	        var settings = await _settings.GetAsync(ct);
58	        var monthConfig = await GetOrCreateMonthOverrideAsync(year, month, ct);
59	        var participants = await GetReceptionistParticipantsAsync(year, month, ct);
60	
61	        var selectedStaff = ResolveSelectedReceptionist(participants, staffId);
62	        if (selectedStaff is null)
63	            throw new InvalidOperationException("No receptionist profiles are available yet.");
64	
65	        var parsedDate = ParseSelectedDate(selectedDateKey, year, month);
66	        var selectedDate = parsedDate.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
67	        var monthMetrics = await ComputeMonthMetricsAsync(year, month, settings, monthConfig, participants.Count, ct);
68	        var taskStatus = await BuildTaskStatusAsync(selectedStaff, settings, selectedDate, ct);
69	        var completedTaskDays = await CountCompletedTaskDaysAsync(selectedStaff.Id!, year, month, settings, ct);
70	
71	        var bonusPool = settings.ReceptionistKpiBonusPoolAmount;
72	        var revenuePercent = ComputeTierReward(monthMetrics.GrossRevenue, settings.ReceptionistRevenueTiers);
73	        var packagePercent = ComputeTierReward(monthMetrics.PackageSalesCount, settings.ReceptionistPackageSalesTiers);
74	        var reviewPercent = ComputeTierReward(monthConfig.GoogleReviewCount, settings.ReceptionistGoogleReviewTiers);
75	        var taskPercent = completedTaskDays * Math.Max(0m, settings.ReceptionistDailyTaskCompletionPercent);
76	        var rewardsEnabled = settings.EnableReceptionistKpiProgram && monthConfig.KpiEnabled;
77	        var effectiveRevenuePercent = rewardsEnabled ? revenuePercent : 0m;
78	        var effectivePackagePercent = rewardsEnabled ? packagePercent : 0m;
79	        var effectiveReviewPercent = rewardsEnabled ? reviewPercent : 0m;
80	        var effectiveTaskPercent = rewardsEnabled ? taskPercent : 0m;
81	        var rawTotalPercent = effectiveRevenuePercent + effectivePackagePercent + effectiveReviewPercent + effectiveTaskPercent;
82	        var unlockedPercent = Math.Min(100m, rawTotalPercent);
83	        var unlockedAmount = RoundVnd(bonusPool * unlockedPercent / 100m);
84	        var attendanceCommission = RoundVnd(monthMetrics.AttendanceCommissionPerReceptionist);
85	        var baseSalary = selectedStaff.BaseSalary;
86	
87	        return new ReceptionistKpiDashboardDto
88	        {
89	            Year = year,
90	            Month = month,
91	            MonthLabel = new DateTime(year, month, 1).ToString("MMMM yyyy", CultureInfo.InvariantCulture),
92	            KpiEnabled = settings.EnableReceptionistKpiProgram && monthConfig.KpiEnabled,
93	            IsAdminView = isAdminView,
94	            SelectedDateKey = selectedDate,
95	            Staff = MapStaff(selectedStaff),
96	            Receptionists = participants.Select(MapStaff).ToList(),
97	            MonthConfig = new ReceptionistKpiMonthConfigDto
98	            {
99	                KpiEnabled = monthConfig.KpiEnabled,
100	                GoogleReviewCount = monthConfig.GoogleReviewCount,
101	                Note = monthConfig.Note,
102	            },
103	            BonusPoolAmount = bonusPool,
104	            TotalUnlockedPercent = unlockedPercent,
105	            TotalUnlockedAmount = unlockedAmount,
106	            AttendanceCommissionAmount = attendanceCommission,
107	            BaseSalaryAmount = baseSalary,
108	            TotalProjectedPay = baseSalary + attendanceCommission + unlockedAmount,
109	            TeamAttendanceCount = monthMetrics.AttendanceHeadcount,
110	            TeamAttendanceCommissionPool = monthMetrics.AttendanceCommissionPool,
111	            Categories = BuildCategories(
112	                settings,
113	                monthConfig,
114	                monthMetrics,
115	                completedTaskDays,
116	                bonusPool,
117	                effectiveRevenuePercent,
118	                effectivePackagePercent,
119	                effectiveReviewPercent,
120	                effectiveTaskPercent,
121	                isAdminView),
122	            DailyTasks = taskStatus,
123	        };
124	    }
