162	    public async Task<List<string>> UpdateDailyTaskLogAsync(
163	        string staffId,
164	        string dateKey,
165	        IEnumerable<string> completedTaskIds,
166	        CancellationToken ct = default)
167	    {
168	        if (string.IsNullOrWhiteSpace(staffId))
169	            throw new InvalidOperationException("Receptionist staff id is required.");
170	
171	        if (!DateOnly.TryParseExact(dateKey, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out var parsedDate))
172	            throw new InvalidOperationException("Date must be in yyyy-MM-dd format.");
173	
174	        var staff = await _staff.Find(s => s.Id == staffId && s.Role == "RECEPTIONIST").FirstOrDefaultAsync(ct)
175	            ?? throw new InvalidOperationException("Receptionist profile not found.");
176	
177	        var settings = await _settings.GetAsync(ct);
178	        var allowedTaskIds = settings.ReceptionistDailyTasks
179	            .Where(t => t.IsActive && !string.IsNullOrWhiteSpace(t.Id))
180	            .Select(t => t.Id)
181	            .ToHashSet(StringComparer.OrdinalIgnoreCase);
182	
183	        var filtered = completedTaskIds
184	            .Where(id => !string.IsNullOrWhiteSpace(id) && allowedTaskIds.Contains(id))
185	            .Distinct(StringComparer.OrdinalIgnoreCase)
186	            .ToList();
187	
188	        var existing = await _taskLogs
189	            .Find(x => x.StaffId == staffId && x.DateKey == dateKey)
190	            .FirstOrDefaultAsync(ct);
191	
192	        var row = existing ?? new ReceptionistDailyTaskLog
193	        {
194	            StaffId = staffId,
195	            StaffNameSnapshot = staff.Name,
196	            DateKey = dateKey,
197	            Year = parsedDate.Year,
198	            Month = parsedDate.Month,
199	            CreatedAt = DateTime.UtcNow,
200	        };
201	
202	        row.StaffNameSnapshot = staff.Name;
203	        row.CompletedTaskIds = filtered;
204	        row.UpdatedAt = DateTime.UtcNow;
205	
206	        if (existing is null)
207	            await _taskLogs.InsertOneAsync(row, cancellationToken: ct);
208	        else
209	            await _taskLogs.ReplaceOneAsync(x => x.Id == existing.Id, row, cancellationToken: ct);
210	
211	        return filtered;
212	    }
