214	    public async Task ApplyReceptionistCompToPayablesAsync(int year, int month, CancellationToken ct = default)
215	    {
216	        var settings = await _settings.GetAsync(ct);
217	        var monthConfig = await GetOrCreateMonthOverrideAsync(year, month, ct);
218	        var participants = await GetReceptionistParticipantsAsync(year, month, ct);
219	        if (participants.Count == 0)
220	            return;
221	
222	        var metrics = await ComputeMonthMetricsAsync(year, month, settings, monthConfig, participants.Count, ct);
223	        var bonusPool = settings.ReceptionistKpiBonusPoolAmount;
224	        var revenuePercent = ComputeTierReward(metrics.GrossRevenue, settings.ReceptionistRevenueTiers);
225	        var packagePercent = ComputeTierReward(metrics.PackageSalesCount, settings.ReceptionistPackageSalesTiers);
226	        var reviewPercent = ComputeTierReward(monthConfig.GoogleReviewCount, settings.ReceptionistGoogleReviewTiers);
227	
228	        var existingRows = await _staffPayables
229	            .Find(x => x.Year == year && x.Month == month)
230	            .ToListAsync(ct);
231	        var existingByName = existingRows.ToDictionary(x => x.StaffName.Trim(), x => x, StringComparer.OrdinalIgnoreCase);
232	
233	        foreach (var receptionist in participants)
234	        {
235	            var completedTaskDays = await CountCompletedTaskDaysAsync(receptionist.Id!, year, month, settings, ct);
236	            var taskPercent = completedTaskDays * Math.Max(0m, settings.ReceptionistDailyTaskCompletionPercent);
237	            var unlockedPercent = settings.EnableReceptionistKpiProgram && monthConfig.KpiEnabled
238	                ? Math.Min(100m, revenuePercent + packagePercent + reviewPercent + taskPercent)
239	                : 0m;
240	            var kpiBonus = RoundVnd(bonusPool * unlockedPercent / 100m);
241	            var attendanceCommission = RoundVnd(metrics.AttendanceCommissionPerReceptionist);
242	
243	            existingByName.TryGetValue(receptionist.Name.Trim(), out var prior);
244	
245	            var priorReceptionistCommission = prior?.ReceptionistAttendanceCommissionAmount ?? 0m;
246	            var priorReceptionistBonus = prior?.ReceptionistKpiBonusAmount ?? 0m;
247	            var preservedOtherCommission = (prior?.CommissionAmount ?? 0m) - priorReceptionistCommission;
248	            var preservedOtherBonus = (prior?.BonusAmount ?? 0m) - priorReceptionistBonus;
249	
250	            var row = new StaffPayable
251	            {
252	                Id = prior?.Id,
253	                StaffName = receptionist.Name.Trim(),
254	                Year = year,
255	                Month = month,
256	                SalaryAmount = receptionist.BaseSalary,
257	                ReimbursementAmount = prior?.ReimbursementAmount ?? 0m,
258	                CommissionAmount = preservedOtherCommission + attendanceCommission,
259	                BonusAmount = preservedOtherBonus + kpiBonus,
260	                ReceptionistAttendanceCommissionAmount = attendanceCommission,
261	                ReceptionistKpiBonusAmount = kpiBonus,
262	                PaidStatus = prior?.PaidStatus ?? "PENDING",
263	                PaidAt = prior?.PaidAt,
264	                CreatedAt = prior?.CreatedAt ?? DateTime.UtcNow,
265	                UpdatedAt = DateTime.UtcNow,
266	            };
267	
268	            row.TotalPayable =
269	                row.SalaryAmount +
270	                row.ReimbursementAmount +
271	                row.CommissionAmount +
272	                row.BonusAmount;
273	
274	            if (prior is null)
275	                await _staffPayables.InsertOneAsync(row, cancellationToken: ct);
276	            else
277	                await _staffPayables.ReplaceOneAsync(x => x.Id == prior.Id, row, cancellationToken: ct);
278	        }
279	    }
