287	        var monthPayables = await _staffPayables
288	            .Find(x => x.Year == year && x.Month == month)
289	            .Project(x => x.StaffName)
290	            .ToListAsync(ct);
291	
292	        var rows = await _staff
293	            .Find(x => x.Role == "RECEPTIONIST" && (x.IsActive || monthLogs.Contains(x.Id!) || monthPayables.Contains(x.Name)))
294	            .SortBy(x => x.Name)
