370	                Name = x.Name,
371	                IsCompleted = completed.Contains(x.Id),
372	            })
373	            .ToList();
374	    }
375	
376	    private async Task<int> CountCompletedTaskDaysAsync(
377	        string staffId,
378	        int year,
379	        int month,
380	        GlobalSettings settings,
381	        CancellationToken ct)
382	    {
383	        var activeTasks = settings.ReceptionistDailyTasks
384	            .Where(x => x.IsActive && !string.IsNullOrWhiteSpace(x.Id))
385	            .Select(x => x.Id)
386	            .ToHashSet(StringComparer.OrdinalIgnoreCase);
387	        if (activeTasks.Count == 0)
388	            return 0;
389	
390	        var logs = await _taskLogs
391	            .Find(x => x.StaffId == staffId && x.Year == year && x.Month == month)
392	            .ToListAsync(ct);
393	
394	        return logs.Count(log => activeTasks.All(id => log.CompletedTaskIds.Contains(id, StringComparer.OrdinalIgnoreCase)));
395	    }
396	
397	    private async Task<ReceptionistMonthMetrics> ComputeMonthMetricsAsync(
398	        int year,
399	        int month,
400	        GlobalSettings settings,
401	        ReceptionistKpiMonthOverride monthConfig,
402	        int receptionistCount,
403	        CancellationToken ct)
404	    {
405	        var start = new DateTime(year, month, 1, 0, 0, 0, DateTimeKind.Utc);
406	        var end = start.AddMonths(1);
407	
408	        var paidInvoices = await _invoices
409	            .Find(x => x.Status == "PAID" && x.IssueDate >= start && x.IssueDate < end)
410	            .ToListAsync(ct);
411	
412	        var grossRevenue = paidInvoices.Sum(x => x.TotalNet);
413	        var packageSales = await CountPackageSalesAsync(paidInvoices, ct);
414	
415	        var sessions = await _sessions
416	            .Find(x => x.Status == "COMPLETED" && x.StartTime >= start && x.StartTime < end && !x.IsFreelance)
417	            .Project(x => x.Id)
418	            .ToListAsync(ct);
419	
420	        decimal attendanceHeadcount = 0m;
421	        if (sessions.Count > 0)
422	        {
423	            var attendanceRows = await _attendances
424	                .Find(Builders<Attendance>.Filter.And(
425	                    Builders<Attendance>.Filter.In(x => x.CalendarSessionId, sessions),
426	                    Builders<Attendance>.Filter.In(x => x.Status, CountingAttendanceStatuses)))
427	                .ToListAsync(ct);
428	
429	            attendanceHeadcount = attendanceRows.Sum(x => Math.Max(1, x.Quantity));
430	        }
431	
432	        var commissionPool = RoundVnd(attendanceHeadcount * Math.Max(0m, settings.ReceptionistAttendanceCommissionPerHead));
433	        var splitCount = Math.Max(1, receptionistCount);
434	
435	        return new ReceptionistMonthMetrics
436	        {
437	            GrossRevenue = grossRevenue,
438	            PackageSalesCount = packageSales,
439	            AttendanceHeadcount = attendanceHeadcount,
440	            AttendanceCommissionPool = commissionPool,
441	            AttendanceCommissionPerReceptionist = commissionPool / splitCount,
442	        };
443	    }
444	
445	    private async Task<int> CountPackageSalesAsync(List<Invoice> paidInvoices, CancellationToken ct)
446	    {
447	        var legacyProductIds = paidInvoices
448	            .SelectMany(x => x.Lines)
449	            .Where(x => string.IsNullOrWhiteSpace(x.ProductTypeSnapshot) && !string.IsNullOrWhiteSpace(x.ProductId))
450	            .Select(x => x.ProductId!)
451	            .Distinct()
452	            .ToList();
453	
454	        var legacyProducts = legacyProductIds.Count == 0
455	            ? new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
456	            : (await _products.Find(x => legacyProductIds.Contains(x.Id!)).ToListAsync(ct))
457	                .ToDictionary(x => x.Id!, x => x.Type ?? string.Empty, StringComparer.OrdinalIgnoreCase);
458	
459	        return paidInvoices
460	            .SelectMany(x => x.Lines)
461	            .Count(line =>
462	            {
463	                var productType = line.ProductTypeSnapshot;
464	                if (string.IsNullOrWhiteSpace(productType) && !string.IsNullOrWhiteSpace(line.ProductId))
465	                    legacyProducts.TryGetValue(line.ProductId, out productType);
466	                return string.Equals(productType, "PACKAGE", StringComparison.OrdinalIgnoreCase);
467	            });
468	    }
469	
470	    private List<ReceptionistKpiCategoryProgressDto> BuildCategories(
471	        GlobalSettings settings,
472	        ReceptionistKpiMonthOverride monthConfig,
473	        ReceptionistMonthMetrics metrics,
474	        int completedTaskDays,
475	        decimal bonusPool,
476	        decimal revenuePercent,
477	        decimal packagePercent,
478	        decimal reviewPercent,
479	        decimal taskPercent,
480	        bool isAdminView)
481	    {
482	        return new List<ReceptionistKpiCategoryProgressDto>
483	        {
484	            new()
485	            {
486	                Key = "dailyTasks",
487	                Label = "Daily Tasks",
488	                Description = "Complete every daily checklist item to unlock each day's reward.",
489	                UnlockedPercent = taskPercent,
490	                UnlockedAmount = RoundVnd(bonusPool * taskPercent / 100m),
491	                ProgressLabel = $"{completedTaskDays} full day{(completedTaskDays == 1 ? string.Empty : "s")} completed",
492	                AdminDetail = $"{settings.ReceptionistDailyTaskCompletionPercent:N0}% reward for each fully completed day",
493	            },
494	            BuildTierCategory(
495	                key: "revenue",
496	                label: "Revenue Targets",
497	                description: "Tier-based studio revenue milestones.",
498	                currentValue: metrics.GrossRevenue,
499	                unlockedPercent: revenuePercent,
500	                bonusPool: bonusPool,
501	                tiers: settings.ReceptionistRevenueTiers,
502	                currentValueLabel: "tiers unlocked",
503	                adminDetail: null, // gross revenue intentionally hidden on the KPI page
504	                redactGoals: true),
505	            BuildTierCategory(
506	                key: "packages",
507	                label: "Package Sales",
508	                description: "Paid package sales only. Studio rental packages are excluded.",
509	                currentValue: metrics.PackageSalesCount,
510	                unlockedPercent: packagePercent,
511	                bonusPool: bonusPool,
512	                tiers: settings.ReceptionistPackageSalesTiers,
513	                currentValueLabel: "packages sold",
514	                adminDetail: isAdminView ? $"{metrics.PackageSalesCount:N0} qualifying packages sold" : null,
515	                redactGoals: false),
516	            BuildTierCategory(
517	                key: "reviews",
518	                label: "Google Reviews",
519	                description: "Monthly Google review count entered by admin.",
520	                currentValue: monthConfig.GoogleReviewCount,
521	                unlockedPercent: reviewPercent,
522	                bonusPool: bonusPool,
523	                tiers: settings.ReceptionistGoogleReviewTiers,
524	                currentValueLabel: "reviews reached",
525	                adminDetail: isAdminView ? $"{monthConfig.GoogleReviewCount:N0} reviews entered for this month" : null,
526	                redactGoals: false),
527	        };
528	    }
529	
530	    private ReceptionistKpiCategoryProgressDto BuildTierCategory(
531	        string key,
532	        string label,
533	        string description,
534	        decimal currentValue,
535	        decimal unlockedPercent,
536	        decimal bonusPool,
537	        IEnumerable<ReceptionistKpiTier> tiers,
538	        string currentValueLabel,
539	        string? adminDetail,
540	        bool redactGoals)
541	    {
542	        var ordered = tiers
543	            .OrderBy(x => x.Goal)
544	            .ToList();
545	
546	        var unlockedCount = ordered.Count(x => currentValue >= x.Goal);
547	        var tierDtos = ordered.Select(tier => new ReceptionistKpiTierProgressDto
548	        {
549	            Id = tier.Id,
550	            Label = tier.Label,
551	            GoalLabel = redactGoals ? tier.Label : $"{tier.Goal:N0}",
552	            RewardLabel = $"+{tier.RewardPercent:N0}%",
553	            IsUnlocked = currentValue >= tier.Goal,
554	            ProgressLabel = currentValue >= tier.Goal
555	                ? "Unlocked"
556	                : redactGoals
557	                    ? "Not yet reached"
558	                    : $"{currentValue:N0} / {tier.Goal:N0}",
559	        }).ToList();
560	
561	        return new ReceptionistKpiCategoryProgressDto
562	        {
563	            Key = key,
564	            Label = label,
565	            Description = description,
566	            UnlockedPercent = unlockedPercent,
567	            UnlockedAmount = RoundVnd(bonusPool * unlockedPercent / 100m),
568	            ProgressLabel = $"{unlockedCount} / {ordered.Count} {currentValueLabel}",
569	            AdminDetail = adminDetail,
570	            Tiers = tierDtos,
571	        };
572	    }
573	
574	    private static decimal ComputeTierReward(decimal currentValue, IEnumerable<ReceptionistKpiTier> tiers)
575	        => tiers.Where(x => currentValue >= x.Goal).Sum(x => Math.Max(0m, x.RewardPercent));
576	
577	    private static ReceptionistKpiStaffDto MapStaff(Staff staff) => new()
578	    {
579	        Id = staff.Id ?? string.Empty,
580	        Name = staff.Name,
581	        Email = staff.Email,
582	        PhotoUrl = staff.PhotoUrl,
583	    };
584	
585	    private static decimal RoundVnd(decimal amount) => Math.Round(amount, 0, MidpointRounding.AwayFromZero);
586	
587	    private sealed class ReceptionistMonthMetrics
588	    {
589	        public decimal GrossRevenue { get; set; }
590	        public decimal PackageSalesCount { get; set; }
591	        public decimal AttendanceHeadcount { get; set; }
592	        public decimal AttendanceCommissionPool { get; set; }
593	        public decimal AttendanceCommissionPerReceptionist { get; set; }
594	    }
595	}
