public async Task<GlobalSettings> UpdateAsync(GlobalSettings update, CancellationToken ct = default)
{
    // Always operate against the singleton row — ignore caller's Id to prevent
    // accidentally creating sibling documents that would silently fragment the settings.
    var current = await GetAsync(ct);
    update.Id = current.Id;
    update.UpdatedAt = DateTime.UtcNow;

    // P2-S01 invariant: the three percentages MUST sum to exactly 100. We refuse
    // to persist a misconfiguration because the accounting engine (P2-S03) reads
    // these directly and a bad value would silently distort owner distributions.
    ValidateAllocationTriple(update.MarketingSplitPercentage, update.SavingsSplitPercentage, update.OwnersSplitPercentage);

    // Defensive: if the caller wiped the list, fall back to defaults rather than
    // breaking every dropdown in the app.
    if (update.ExpenseCategories == null || update.ExpenseCategories.Count == 0)
    {
        update.ExpenseCategories = GlobalSettings.DefaultExpenseCategories.ToList();
    }

    // P2-S08: validate Stripe routing mode + owner-payout invariants.
    ValidateStripeRoutingMode(update);
    if (update.StripeRoutingMode == StripeRoutingModes.OwnerRouted)
    {
        await ValidateExactlyOneStripeOwnerAsync(ct);
    }

    // Issue #2 — Merge-preserve upsell fields.
    // The admin page has two save buttons: one for General/Operations settings and one
    // specifically for Payment settings (which includes the upsell section). When the
    // General save fires, it posts a JSON payload that has no upsell keys — ASP.NET
    // deserialises those as C# defaults. A naked ReplaceOneAsync would then stomp the
    // admin's carefully-configured upsell settings.
    //
    // Detection heuristic: if every upsell field in the incoming document is at its
    // C# default AND the payload has no custom headline copy, treat the section as
    // "not submitted" and carry the current DB values forward.  The Payments save
    // always sends explicit values (even when they happen to equal the defaults), so
    // the only way all of these are simultaneously at the coded defaults is when the
    // caller was a partial-payload save button that omitted the whole upsell block.
    PreserveUpsellFieldsIfAbsent(update, current);
    PreserveReceptionistKpiFieldsIfAbsent(update, current);
    PreserveRoleAccessSettingsIfAbsent(update, current);
    update.RoleAccessSettings = NormaliseRoleAccessSettings(update.RoleAccessSettings);

    // P5-S01 — Merge-preserve reservation system fields (same pattern as upsell).
    PreserveReservationFieldsIfAbsent(update, current);

    // V2 — Merge-preserve materialisation horizon (same pattern).
    PreserveMaterialisationHorizonIfAbsent(update, current);

    // V2 Schedule — Always carry forward the DB CompanySchedule (see PreserveScheduleConfigAlways).
    PreserveScheduleConfigAlways(update, current);

    // SPM-76 — Always carry forward the DB EmailTemplates. The non-email save
    // buttons never include an emailTemplates field, so a naked replace would
    // wipe every customised template. Email templates are managed exclusively
    // via the dedicated /email-templates endpoint, so it's safe to always use
    // the DB copy here.
    PreserveEmailTemplatesAlways(update, current);

    // Stripe keys/enabled are edited exclusively via /settings/stripe-keys.
    // A general settings save sends empty encrypted fields + StripeEnabled=false,
    // which would silently WIPE the live keys and disable payments — always
    // carry the DB values forward. (Regression: this guard existed but was
    // never invoked, so any General/Payments save wiped the Stripe config.)
    PreserveStripeKeysIfAbsent(update, current);

    // VIP program is edited exclusively via the /settings/vip PATCH, so always
    // carry the DB values forward — an unrelated full save must never reset them.
    update.EnableVipProgram = current.EnableVipProgram;
    update.VipMinimumSpend = current.VipMinimumSpend;
    update.SuperVipMinimumSpend = current.SuperVipMinimumSpend;
    update.SuperVipMinimumClasses = current.SuperVipMinimumClasses;

    await _settings.ReplaceOneAsync(s => s.Id == current.Id, update, cancellationToken: ct);
    return update;
}

/// <summary>
/// If the incoming <paramref name="update"/> has every upsell field at its C# default
/// (strongly indicating the caller's JSON payload did not include the upsell section),
/// copy the current DB values onto <paramref name="update"/> so the subsequent
/// <c>ReplaceOneAsync</c> does not silently reset them.
/// </summary>
private static void PreserveUpsellFieldsIfAbsent(GlobalSettings update, GlobalSettings current)
{
    var allDefaults =
        update.EnableCheckoutPackageUpsell == true &&
        update.UpsellMinSavingsPercentage == 0 &&
        update.UpsellMaxOptionsShown == 1 &&
        (update.UpsellEligibleFormats == null || update.UpsellEligibleFormats.Count == 0) &&
        update.UpsellHideForActivePackageHolders == true &&
        string.IsNullOrEmpty(update.UpsellHeadlineEn) &&
        string.IsNullOrEmpty(update.UpsellHeadlineVi) &&
        string.IsNullOrEmpty(update.UpsellPackageIdGroup) &&
        string.IsNullOrEmpty(update.UpsellPackageIdPrivate) &&
        string.IsNullOrEmpty(update.UpsellPackageIdMixed);

    if (!allDefaults) return; // Caller explicitly sent upsell fields — leave them as-is.

    update.EnableCheckoutPackageUpsell       = current.EnableCheckoutPackageUpsell;
    update.UpsellMinSavingsPercentage        = current.UpsellMinSavingsPercentage;
    update.UpsellMaxOptionsShown             = current.UpsellMaxOptionsShown;
    update.UpsellEligibleFormats             = current.UpsellEligibleFormats;
    update.UpsellHideForActivePackageHolders = current.UpsellHideForActivePackageHolders;
    update.UpsellHeadlineEn                  = current.UpsellHeadlineEn;
    update.UpsellHeadlineVi                  = current.UpsellHeadlineVi;
    update.UpsellPackageIdGroup              = current.UpsellPackageIdGroup;
    update.UpsellPackageIdPrivate            = current.UpsellPackageIdPrivate;
    update.UpsellPackageIdMixed              = current.UpsellPackageIdMixed;
}

/// <summary>
/// P5-S01 — If the incoming <paramref name="update"/> has every reservation field at
/// its C# default (indicating the caller's payload did not include the section),
/// carry forward the current DB values so we don't accidentally reset them.
/// </summary>
private static void PreserveReceptionistKpiFieldsIfAbsent(GlobalSettings update, GlobalSettings current)
{
    var allDefaults =
        update.EnableReceptionistKpiProgram == false &&
        update.ReceptionistKpiBonusPoolAmount == 5_000_000m &&
        update.ReceptionistDailyTaskCompletionPercent == 1m &&
        update.ReceptionistAttendanceCommissionPerHead == 0m &&
        update.ReceptionistAttendanceSplitMode == "EQUAL_ACTIVE" &&
        (update.ReceptionistDailyTasks == null || update.ReceptionistDailyTasks.Count == 0) &&
        (update.ReceptionistRevenueTiers == null || update.ReceptionistRevenueTiers.Count == 0) &&
        (update.ReceptionistPackageSalesTiers == null || update.ReceptionistPackageSalesTiers.Count == 0) &&
        (update.ReceptionistGoogleReviewTiers == null || update.ReceptionistGoogleReviewTiers.Count == 0);

    if (!allDefaults) return;

    update.EnableReceptionistKpiProgram = current.EnableReceptionistKpiProgram;
    update.ReceptionistKpiBonusPoolAmount = current.ReceptionistKpiBonusPoolAmount;
    update.ReceptionistDailyTaskCompletionPercent = current.ReceptionistDailyTaskCompletionPercent;
    update.ReceptionistAttendanceCommissionPerHead = current.ReceptionistAttendanceCommissionPerHead;
    update.ReceptionistAttendanceSplitMode = current.ReceptionistAttendanceSplitMode;
    update.ReceptionistDailyTasks = current.ReceptionistDailyTasks ?? new List<ReceptionistDailyTaskDefinition>();
    update.ReceptionistRevenueTiers = current.ReceptionistRevenueTiers ?? new List<ReceptionistKpiTier>();
    update.ReceptionistPackageSalesTiers = current.ReceptionistPackageSalesTiers ?? new List<ReceptionistKpiTier>();
    update.ReceptionistGoogleReviewTiers = current.ReceptionistGoogleReviewTiers ?? new List<ReceptionistKpiTier>();
}

private static void PreserveRoleAccessSettingsIfAbsent(GlobalSettings update, GlobalSettings current)
{
    if (update.RoleAccessSettings != null && update.RoleAccessSettings.Count > 0) return;
    update.RoleAccessSettings = current.RoleAccessSettings ?? BuildDefaultRoleAccessSettings();
}

private static void PreserveReservationFieldsIfAbsent(GlobalSettings update, GlobalSettings current)
{
    // Defaults: EnableReservationSystem=true, ExpiryMinutes=15, CleanupInterval=2
    var allDefaults =
        update.EnableReservationSystem == true &&
        update.ReservationExpiryMinutes == 15 &&
        update.ReservationCleanupIntervalMinutes == 2;

    if (!allDefaults) return; // Caller explicitly sent reservation fields.

