=== Controller ===
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.DTOs;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.API.Controllers;

[ApiController]
[Route("api/receptionist-kpi")]
[Authorize(Roles = "Admin,Receptionist")]
public class ReceptionistKpiController : ControllerBase
{
    private readonly IReceptionistKpiService _kpi;

    public ReceptionistKpiController(IReceptionistKpiService kpi) => _kpi = kpi;

    [HttpGet("dashboard")]
    public async Task<IActionResult> GetDashboard(
        [FromQuery] int? year,
        [FromQuery] int? month,
        [FromQuery] string? staffId,
        [FromQuery] string? date,
        CancellationToken ct)
    {
        var now = DateTime.UtcNow;
        var isAdmin = User.IsInRole("Admin");
        var effectiveStaffId = isAdmin ? staffId : ResolveOwnStaffId();
        if (!isAdmin && string.IsNullOrWhiteSpace(effectiveStaffId))
            return BadRequest(new { message = "This receptionist login is not linked to a staff profile yet." });

        try
        {
            var dto = await _kpi.GetDashboardAsync(
                year ?? now.Year,
                month ?? now.Month,
                effectiveStaffId,
                date,
                isAdmin,
                ct);
            return Ok(dto);
        }
        catch (InvalidOperationException ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    [HttpPut("month-config")]
    [Authorize(Roles = "Admin")]
    public async Task<IActionResult> UpdateMonthConfig(
        [FromBody] UpdateReceptionistMonthConfigRequest request,
        CancellationToken ct)
    {
        try
        {
            return Ok(await _kpi.UpsertMonthConfigAsync(request, ct));
        }
        catch (InvalidOperationException ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    [HttpPut("daily-tasks")]
    public async Task<IActionResult> UpdateDailyTasks(
        [FromBody] UpdateReceptionistTaskLogRequest request,
        CancellationToken ct)
    {
        var isAdmin = User.IsInRole("Admin");
        var effectiveStaffId = isAdmin ? request.StaffId : ResolveOwnStaffId();
        if (string.IsNullOrWhiteSpace(effectiveStaffId))
            return BadRequest(new { message = "Receptionist staff id is required." });

        try
        {
            var completed = await _kpi.UpdateDailyTaskLogAsync(
                effectiveStaffId,
                request.DateKey,
                request.CompletedTaskIds,
                ct);
            return Ok(new { completedTaskIds = completed });
        }
        catch (InvalidOperationException ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    private string? ResolveOwnStaffId()
        => User.FindFirst("staff_id")?.Value;
}
