private static void PreserveReceptionistKpiFieldsIfAbsent(GlobalSettings update, GlobalSettings current)
{
    // Receptionist-KPI config is edited exclusively via the dedicated
    // /api/receptionist-kpi/month-settings endpoint (per-month config) and the
    // GlobalSettings copy is only a seed for the very first month. A general or
    // payments settings save NEVER carries these fields, so we ALWAYS carry the
    // DB values forward — the previous "all-defaults" heuristic was fragile
    // (the tier lists have non-empty default initialisers, so it never matched)
    // and every unrelated save silently reset EnableReceptionistKpiProgram to
    // false and the per-head commission to 0.
    update.EnableReceptionistKpiProgram = current.EnableReceptionistKpiProgram;

