    public async Task<ReceptionistKpiMonthSettingsDto> UpsertMonthSettingsAsync(
        UpdateReceptionistMonthSettingsRequest request,
        CancellationToken ct = default)
    {
        if (request.Month < 1 || request.Month > 12)
            throw new InvalidOperationException("Month must be between 1 and 12.");

        var (row, _) = await ResolveMonthOverrideAsync(request.Year, request.Month, ct);

        row.KpiEnabled = request.KpiEnabled;
        row.BonusPoolAmount = Math.Max(0m, request.BonusPoolAmount);
        row.DailyTaskCompletionPercent = Math.Max(0m, request.DailyTaskCompletionPercent);
        row.AttendanceCommissionPerHead = Math.Max(0m, request.AttendanceCommissionPerHead);
        row.AttendanceSplitMode = string.IsNullOrWhiteSpace(request.AttendanceSplitMode) ? "EQUAL_ACTIVE" : request.AttendanceSplitMode.Trim();
        row.GoogleReviewCount = Math.Max(0, request.GoogleReviewCount);
        row.Note = (request.Note ?? string.Empty).Trim();
        row.DailyTasks = MapTasks(request.DailyTasks);
        row.RevenueTiers = MapTiers(request.RevenueTiers);
        row.PackageSalesTiers = MapTiers(request.PackageSalesTiers);
        row.GoogleReviewTiers = MapTiers(request.GoogleReviewTiers);
        row.ConfigInitialized = true;
        row.UpdatedAt = DateTime.UtcNow;

        await _monthOverrides.ReplaceOneAsync(x => x.Id == row.Id, row, cancellationToken: ct);
        return MapSettings(row);
    }

