using System.Globalization;
using MongoDB.Driver;
using SoulPilates.Core.DTOs;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.Services;

public class ReceptionistKpiService : IReceptionistKpiService
{
    private static readonly string[] CountingAttendanceStatuses = { "CHECKED_IN", "ARRIVED" };

    private readonly IMongoCollection<Staff> _staff;
    private readonly IMongoCollection<Invoice> _invoices;
    private readonly IMongoCollection<Product> _products;
    private readonly IMongoCollection<CalendarSession> _sessions;
    private readonly IMongoCollection<Attendance> _attendances;
    private readonly IMongoCollection<ReceptionistDailyTaskLog> _taskLogs;
    private readonly IMongoCollection<ReceptionistDailyCustomTask> _customTasks;
    private readonly IMongoCollection<ReceptionistKpiMonthOverride> _monthOverrides;
    private readonly IMongoCollection<StaffPayable> _staffPayables;
    private readonly ISettingsService _settings;

    public ReceptionistKpiService(MongoDbContext db, ISettingsService settings)
    {
        _staff = db.GetCollection<Staff>("Staff");
        _invoices = db.GetCollection<Invoice>("Invoices");
        _products = db.GetCollection<Product>("Products");
        _sessions = db.GetCollection<CalendarSession>("CalendarSessions");
        _attendances = db.GetCollection<Attendance>("Attendances");
        _taskLogs = db.GetCollection<ReceptionistDailyTaskLog>("ReceptionistDailyTaskLogs");
        _customTasks = db.GetCollection<ReceptionistDailyCustomTask>("ReceptionistDailyCustomTasks");
        _monthOverrides = db.GetCollection<ReceptionistKpiMonthOverride>("ReceptionistKpiMonthOverrides");
        _staffPayables = db.GetCollection<StaffPayable>("StaffPayables");
        _settings = settings;

        _taskLogs.Indexes.CreateOne(new CreateIndexModel<ReceptionistDailyTaskLog>(
            Builders<ReceptionistDailyTaskLog>.IndexKeys
                .Ascending(x => x.StaffId)
                .Ascending(x => x.DateKey),
            new CreateIndexOptions { Unique = true, Name = "ux_staff_date" }));

        _monthOverrides.Indexes.CreateOne(new CreateIndexModel<ReceptionistKpiMonthOverride>(
            Builders<ReceptionistKpiMonthOverride>.IndexKeys
                .Ascending(x => x.Year)
                .Ascending(x => x.Month),
            new CreateIndexOptions { Unique = true, Name = "ux_year_month" }));

        _customTasks.Indexes.CreateOne(new CreateIndexModel<ReceptionistDailyCustomTask>(
            Builders<ReceptionistDailyCustomTask>.IndexKeys.Ascending(x => x.DateKey),
            new CreateIndexOptions { Name = "ix_custom_datekey" }));
    }

    // ── Dashboard ────────────────────────────────────────────────

    public async Task<ReceptionistKpiDashboardDto> GetDashboardAsync(
        int year,
        int month,
        string? staffId,
        string? selectedDateKey,
        bool isAdminView,
        CancellationToken ct = default)
    {
        var monthConfig = await GetOrCreateMonthOverrideAsync(year, month, ct);
        var participants = await GetReceptionistParticipantsAsync(year, month, ct);

        var selectedStaff = ResolveSelectedReceptionist(participants, staffId);
        if (selectedStaff is null)
            throw new InvalidOperationException("No receptionist profiles are available yet.");

        var parsedDate = ParseSelectedDate(selectedDateKey, year, month);
        var selectedDate = parsedDate.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
        var monthMetrics = await ComputeMonthMetricsAsync(year, month, monthConfig, participants.Count, ct);
        var taskStatus = await BuildTaskStatusAsync(selectedStaff, monthConfig, selectedDate, ct);
        var completedTaskDays = await CountCompletedTaskDaysAsync(selectedStaff.Id!, year, month, monthConfig, ct);

        var bonusPool = monthConfig.BonusPoolAmount;
        var revenuePercent = ComputeTierReward(monthMetrics.GrossRevenue, monthConfig.RevenueTiers);
        var packagePercent = ComputeTierReward(monthMetrics.PackageSalesCount, monthConfig.PackageSalesTiers);
        var reviewPercent = ComputeTierReward(monthConfig.GoogleReviewCount, monthConfig.GoogleReviewTiers);
        var taskPercent = completedTaskDays * Math.Max(0m, monthConfig.DailyTaskCompletionPercent);
        var rewardsEnabled = monthConfig.KpiEnabled;
        var effectiveRevenuePercent = rewardsEnabled ? revenuePercent : 0m;
        var effectivePackagePercent = rewardsEnabled ? packagePercent : 0m;
        var effectiveReviewPercent = rewardsEnabled ? reviewPercent : 0m;
        var effectiveTaskPercent = rewardsEnabled ? taskPercent : 0m;
        var rawTotalPercent = effectiveRevenuePercent + effectivePackagePercent + effectiveReviewPercent + effectiveTaskPercent;
        var unlockedPercent = Math.Min(100m, rawTotalPercent);
        var unlockedAmount = RoundVnd(bonusPool * unlockedPercent / 100m);
        var attendanceCommission = RoundVnd(monthMetrics.AttendanceCommissionPerReceptionist);
        var baseSalary = selectedStaff.BaseSalary;

        return new ReceptionistKpiDashboardDto
        {
            Year = year,
            Month = month,
            MonthLabel = new DateTime(year, month, 1).ToString("MMMM yyyy", CultureInfo.InvariantCulture),
            KpiEnabled = monthConfig.KpiEnabled,
            IsAdminView = isAdminView,
            SelectedDateKey = selectedDate,
            Staff = MapStaff(selectedStaff),
            Receptionists = participants.Select(MapStaff).ToList(),
            MonthConfig = new ReceptionistKpiMonthConfigDto
            {
                KpiEnabled = monthConfig.KpiEnabled,
                GoogleReviewCount = monthConfig.GoogleReviewCount,
                Note = monthConfig.Note,
            },
            BonusPoolAmount = bonusPool,
            TotalUnlockedPercent = unlockedPercent,
            TotalUnlockedAmount = unlockedAmount,
            AttendanceCommissionAmount = attendanceCommission,
            BaseSalaryAmount = baseSalary,
            TotalProjectedPay = baseSalary + attendanceCommission + unlockedAmount,
            TeamAttendanceCount = monthMetrics.AttendanceHeadcount,
            TeamAttendanceCommissionPool = monthMetrics.AttendanceCommissionPool,
            Categories = BuildCategories(
                monthConfig,
                monthMetrics,
                completedTaskDays,
                bonusPool,
                effectiveRevenuePercent,
                effectivePackagePercent,
                effectiveReviewPercent,
                effectiveTaskPercent,
                isAdminView),
            DailyTasks = taskStatus,
        };
    }

    // ── Live monthly inputs (from the dashboard admin panel) ─────

    public async Task<ReceptionistKpiMonthConfigDto> UpsertMonthConfigAsync(
        UpdateReceptionistMonthConfigRequest request,
        CancellationToken ct = default)
    {
        if (request.Month < 1 || request.Month > 12)
            throw new InvalidOperationException("Month must be between 1 and 12.");

        var row = await GetOrCreateMonthOverrideAsync(request.Year, request.Month, ct);

        row.KpiEnabled = request.KpiEnabled;
        row.GoogleReviewCount = Math.Max(0, request.GoogleReviewCount);
        row.Note = (request.Note ?? string.Empty).Trim();
        row.UpdatedAt = DateTime.UtcNow;
        await _monthOverrides.ReplaceOneAsync(x => x.Id == row.Id, row, cancellationToken: ct);

        return new ReceptionistKpiMonthConfigDto
        {
            KpiEnabled = row.KpiEnabled,
            GoogleReviewCount = row.GoogleReviewCount,
            Note = row.Note,
        };
    }

    // ── Full per-month settings (the KPI settings page) ──────────

    public async Task<ReceptionistKpiMonthSettingsDto> GetMonthSettingsAsync(int year, int month, CancellationToken ct = default)
    {
        if (month < 1 || month > 12)
            throw new InvalidOperationException("Month must be between 1 and 12.");
        var (row, seeded) = await ResolveMonthOverrideAsync(year, month, ct);
        var dto = MapSettings(row);
        dto.CarriedForward = seeded;
        return dto;
    }

    public async Task<ReceptionistKpiMonthSettingsDto> UpsertMonthSettingsAsync(
        UpdateReceptionistMonthSettingsRequest request,
        CancellationToken ct = default)
    {
        if (request.Month < 1 || request.Month > 12)
            throw new InvalidOperationException("Month must be between 1 and 12.");

        var (row, _) = await ResolveMonthOverrideAsync(request.Year, request.Month, ct);

        row.KpiEnabled = request.KpiEnabled;
        row.BonusPoolAmount = Math.Max(0m, request.BonusPoolAmount);
        row.DailyTaskCompletionPercent = Math.Max(0m, request.DailyTaskCompletionPercent);
        row.AttendanceCommissionPerHead = Math.Max(0m, request.AttendanceCommissionPerHead);
        row.AttendanceSplitMode = string.IsNullOrWhiteSpace(request.AttendanceSplitMode) ? "EQUAL_ACTIVE" : request.AttendanceSplitMode.Trim();
        row.GoogleReviewCount = Math.Max(0, request.GoogleReviewCount);
        row.Note = (request.Note ?? string.Empty).Trim();
        row.DailyTasks = MapTasks(request.DailyTasks);
        row.RevenueTiers = MapTiers(request.RevenueTiers);
        row.PackageSalesTiers = MapTiers(request.PackageSalesTiers);
        row.GoogleReviewTiers = MapTiers(request.GoogleReviewTiers);
        row.ConfigInitialized = true;
        row.UpdatedAt = DateTime.UtcNow;

        await _monthOverrides.ReplaceOneAsync(x => x.Id == row.Id, row, cancellationToken: ct);
        return MapSettings(row);
    }

    // ── Custom (one-off) daily tasks ─────────────────────────────

    public async Task<List<ReceptionistCustomTaskDto>> GetCustomTasksAsync(string dateKey, CancellationToken ct = default)
    {
        if (!DateOnly.TryParseExact(dateKey, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out _))
            throw new InvalidOperationException("Date must be in yyyy-MM-dd format.");
        var rows = await _customTasks.Find(x => x.DateKey == dateKey).SortBy(x => x.CreatedAt).ToListAsync(ct);
        return rows.Select(x => new ReceptionistCustomTaskDto { Id = x.Id!, DateKey = x.DateKey, Name = x.Name }).ToList();
    }

    public async Task<ReceptionistCustomTaskDto> AddCustomTaskAsync(AddReceptionistCustomTaskRequest request, CancellationToken ct = default)
    {
        if (!DateOnly.TryParseExact(request.DateKey, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out var parsed))
            throw new InvalidOperationException("Date must be in yyyy-MM-dd format.");
        var name = (request.Name ?? string.Empty).Trim();
        if (string.IsNullOrWhiteSpace(name))
            throw new InvalidOperationException("Task name is required.");

        var row = new ReceptionistDailyCustomTask
        {
            DateKey = request.DateKey,
            Year = parsed.Year,
            Month = parsed.Month,
            Name = name,
            CreatedAt = DateTime.UtcNow,
        };
        await _customTasks.InsertOneAsync(row, cancellationToken: ct);
        return new ReceptionistCustomTaskDto { Id = row.Id!, DateKey = row.DateKey, Name = row.Name };
    }

    public async Task<bool> DeleteCustomTaskAsync(string id, CancellationToken ct = default)
    {
        var res = await _customTasks.DeleteOneAsync(x => x.Id == id, ct);
        return res.DeletedCount > 0;
    }

    // ── Task log ─────────────────────────────────────────────────

    public async Task<List<string>> UpdateDailyTaskLogAsync(
        string staffId,
        string dateKey,
        IEnumerable<string> completedTaskIds,
        CancellationToken ct = default)
    {
        if (string.IsNullOrWhiteSpace(staffId))
            throw new InvalidOperationException("Receptionist staff id is required.");

        if (!DateOnly.TryParseExact(dateKey, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out var parsedDate))
            throw new InvalidOperationException("Date must be in yyyy-MM-dd format.");

        var staff = await _staff.Find(s => s.Id == staffId && s.Role == "RECEPTIONIST").FirstOrDefaultAsync(ct)
            ?? throw new InvalidOperationException("Receptionist profile not found.");

        var monthConfig = await GetOrCreateMonthOverrideAsync(parsedDate.Year, parsedDate.Month, ct);
        var allowedTaskIds = monthConfig.DailyTasks
            .Where(t => t.IsActive && !string.IsNullOrWhiteSpace(t.Id))
            .Select(t => t.Id)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);

        // Custom tasks for this specific date are also valid completable items.
        var customIds = await _customTasks.Find(x => x.DateKey == dateKey).Project(x => x.Id!).ToListAsync(ct);
        foreach (var cid in customIds) allowedTaskIds.Add(cid);

        var filtered = completedTaskIds
            .Where(id => !string.IsNullOrWhiteSpace(id) && allowedTaskIds.Contains(id))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();

        var existing = await _taskLogs
            .Find(x => x.StaffId == staffId && x.DateKey == dateKey)
            .FirstOrDefaultAsync(ct);

        var row = existing ?? new ReceptionistDailyTaskLog
        {
            StaffId = staffId,
            StaffNameSnapshot = staff.Name,
            DateKey = dateKey,
            Year = parsedDate.Year,
            Month = parsedDate.Month,
            CreatedAt = DateTime.UtcNow,
        };

        row.StaffNameSnapshot = staff.Name;
        row.CompletedTaskIds = filtered;
        row.UpdatedAt = DateTime.UtcNow;

        if (existing is null)
            await _taskLogs.InsertOneAsync(row, cancellationToken: ct);
        else
            await _taskLogs.ReplaceOneAsync(x => x.Id == existing.Id, row, cancellationToken: ct);

        return filtered;
    }

    // ── Payables ─────────────────────────────────────────────────

    public async Task ApplyReceptionistCompToPayablesAsync(int year, int month, CancellationToken ct = default)
    {
        var monthConfig = await GetOrCreateMonthOverrideAsync(year, month, ct);
        var participants = await GetReceptionistParticipantsAsync(year, month, ct);
        if (participants.Count == 0)
            return;

        var metrics = await ComputeMonthMetricsAsync(year, month, monthConfig, participants.Count, ct);
        var bonusPool = monthConfig.BonusPoolAmount;
        var revenuePercent = ComputeTierReward(metrics.GrossRevenue, monthConfig.RevenueTiers);
        var packagePercent = ComputeTierReward(metrics.PackageSalesCount, monthConfig.PackageSalesTiers);
        var reviewPercent = ComputeTierReward(monthConfig.GoogleReviewCount, monthConfig.GoogleReviewTiers);

        var existingRows = await _staffPayables
            .Find(x => x.Year == year && x.Month == month)
            .ToListAsync(ct);
        var existingByName = existingRows.ToDictionary(x => x.StaffName.Trim(), x => x, StringComparer.OrdinalIgnoreCase);

        foreach (var receptionist in participants)
        {
            var completedTaskDays = await CountCompletedTaskDaysAsync(receptionist.Id!, year, month, monthConfig, ct);
            var taskPercent = completedTaskDays * Math.Max(0m, monthConfig.DailyTaskCompletionPercent);
            var unlockedPercent = monthConfig.KpiEnabled
                ? Math.Min(100m, revenuePercent + packagePercent + reviewPercent + taskPercent)
                : 0m;
            var kpiBonus = RoundVnd(bonusPool * unlockedPercent / 100m);
            var attendanceCommission = RoundVnd(metrics.AttendanceCommissionPerReceptionist);

            existingByName.TryGetValue(receptionist.Name.Trim(), out var prior);

            var priorReceptionistCommission = prior?.ReceptionistAttendanceCommissionAmount ?? 0m;
            var priorReceptionistBonus = prior?.ReceptionistKpiBonusAmount ?? 0m;
            var preservedOtherCommission = (prior?.CommissionAmount ?? 0m) - priorReceptionistCommission;
            var preservedOtherBonus = (prior?.BonusAmount ?? 0m) - priorReceptionistBonus;

            var row = new StaffPayable
            {
                Id = prior?.Id,
                StaffName = receptionist.Name.Trim(),
                Year = year,
                Month = month,
                SalaryAmount = receptionist.BaseSalary,
                ReimbursementAmount = prior?.ReimbursementAmount ?? 0m,
                CommissionAmount = preservedOtherCommission + attendanceCommission,
                BonusAmount = preservedOtherBonus + kpiBonus,
                ReceptionistAttendanceCommissionAmount = attendanceCommission,
                ReceptionistKpiBonusAmount = kpiBonus,
                PaidStatus = prior?.PaidStatus ?? "PENDING",
                PaidAt = prior?.PaidAt,
                CreatedAt = prior?.CreatedAt ?? DateTime.UtcNow,
                UpdatedAt = DateTime.UtcNow,
            };

            row.TotalPayable =
                row.SalaryAmount +
                row.ReimbursementAmount +
                row.CommissionAmount +
                row.BonusAmount;

            if (prior is null)
                await _staffPayables.InsertOneAsync(row, cancellationToken: ct);
            else
                await _staffPayables.ReplaceOneAsync(x => x.Id == prior.Id, row, cancellationToken: ct);
        }
    }

    private async Task<List<Staff>> GetReceptionistParticipantsAsync(int year, int month, CancellationToken ct)
    {
        var monthLogs = await _taskLogs
            .Find(x => x.Year == year && x.Month == month)
            .Project(x => x.StaffId)
            .ToListAsync(ct);
        var monthPayables = await _staffPayables
            .Find(x => x.Year == year && x.Month == month)
            .Project(x => x.StaffName)
            .ToListAsync(ct);

        var rows = await _staff
            .Find(x => x.Role == "RECEPTIONIST" && (x.IsActive || monthLogs.Contains(x.Id!) || monthPayables.Contains(x.Name)))
            .SortBy(x => x.Name)
            .ToListAsync(ct);

        // Exclude anyone hired after this month — no pay before their start date.
        var monthEnd = new DateTime(year, month, 1, 0, 0, 0, DateTimeKind.Utc).AddMonths(1).AddTicks(-1);
        rows = rows.Where(x => !x.EmploymentStartDate.HasValue || x.EmploymentStartDate.Value <= monthEnd).ToList();

        return rows;
    }

    // ── Month override resolution (seed + auto-carry-forward) ────

    private async Task<ReceptionistKpiMonthOverride> GetOrCreateMonthOverrideAsync(int year, int month, CancellationToken ct)
        => (await ResolveMonthOverrideAsync(year, month, ct)).row;

    /// <summary>
    /// Returns the month's config row, creating/seeding it if needed. A brand-new month
    /// (or a legacy row that predates per-month config) inherits its config from the most
    /// recent prior initialised month, or from the global defaults if none exists. The
    /// <c>seeded</c> flag is true when this call performed that inheritance (so callers can
    /// tell the user "carried forward from last month").
    /// </summary>
    private async Task<(ReceptionistKpiMonthOverride row, bool seeded)> ResolveMonthOverrideAsync(int year, int month, CancellationToken ct)
    {
        var existing = await _monthOverrides
            .Find(x => x.Year == year && x.Month == month)
            .FirstOrDefaultAsync(ct);

        if (existing is not null && existing.ConfigInitialized)
            return (existing, false);

        var seedSource = await FindSeedConfigAsync(year, month, ct);

        var row = existing ?? new ReceptionistKpiMonthOverride
        {
            Year = year,
            Month = month,
            KpiEnabled = true,
            GoogleReviewCount = 0,
            Note = string.Empty,
            CreatedAt = DateTime.UtcNow,
        };

        ApplySeedConfig(row, seedSource);
        row.ConfigInitialized = true;
        row.UpdatedAt = DateTime.UtcNow;

        if (existing is null)
            await _monthOverrides.InsertOneAsync(row, cancellationToken: ct);
        else
            await _monthOverrides.ReplaceOneAsync(x => x.Id == row.Id, row, cancellationToken: ct);

        return (row, true);
    }

    /// <summary>Most recent initialised month strictly before (year, month), or null.</summary>
    private async Task<ReceptionistKpiMonthOverride?> FindSeedConfigAsync(int year, int month, CancellationToken ct)
    {
        var target = year * 12 + (month - 1);
        var all = await _monthOverrides.Find(x => x.ConfigInitialized).ToListAsync(ct);
        return all
            .Where(x => x.Year * 12 + (x.Month - 1) < target)
            .OrderByDescending(x => x.Year * 12 + (x.Month - 1))
            .FirstOrDefault();
    }

    /// <summary>Copy config from a prior month (or global settings if none) onto <paramref name="row"/>.</summary>
    private void ApplySeedConfig(ReceptionistKpiMonthOverride row, ReceptionistKpiMonthOverride? source)
    {
        if (source is not null)
        {
            row.BonusPoolAmount = source.BonusPoolAmount;
            row.DailyTaskCompletionPercent = source.DailyTaskCompletionPercent;
            row.AttendanceCommissionPerHead = source.AttendanceCommissionPerHead;
            row.AttendanceSplitMode = source.AttendanceSplitMode;
            row.DailyTasks = CloneTasks(source.DailyTasks);
            row.RevenueTiers = CloneTiers(source.RevenueTiers);
            row.PackageSalesTiers = CloneTiers(source.PackageSalesTiers);
            row.GoogleReviewTiers = CloneTiers(source.GoogleReviewTiers);
            return;
        }

        // No prior month — seed from the global defaults (the original single config).
        var s = _settings.GetAsync().GetAwaiter().GetResult();
        row.BonusPoolAmount = s.ReceptionistKpiBonusPoolAmount;
        row.DailyTaskCompletionPercent = s.ReceptionistDailyTaskCompletionPercent;
        row.AttendanceCommissionPerHead = s.ReceptionistAttendanceCommissionPerHead;
        row.AttendanceSplitMode = string.IsNullOrWhiteSpace(s.ReceptionistAttendanceSplitMode) ? "EQUAL_ACTIVE" : s.ReceptionistAttendanceSplitMode;
        row.DailyTasks = CloneTasks(s.ReceptionistDailyTasks);
        row.RevenueTiers = CloneTiers(s.ReceptionistRevenueTiers);
        row.PackageSalesTiers = CloneTiers(s.ReceptionistPackageSalesTiers);
        row.GoogleReviewTiers = CloneTiers(s.ReceptionistGoogleReviewTiers);
    }

    private static List<ReceptionistDailyTaskDefinition> CloneTasks(IEnumerable<ReceptionistDailyTaskDefinition>? tasks)
        => (tasks ?? Enumerable.Empty<ReceptionistDailyTaskDefinition>())
            .Select(t => new ReceptionistDailyTaskDefinition { Id = t.Id, Name = t.Name, IsActive = t.IsActive })
            .ToList();

    private static List<ReceptionistKpiTier> CloneTiers(IEnumerable<ReceptionistKpiTier>? tiers)
        => (tiers ?? Enumerable.Empty<ReceptionistKpiTier>())
            .Select(t => new ReceptionistKpiTier { Id = t.Id, Label = t.Label, Goal = t.Goal, RewardPercent = t.RewardPercent })
            .ToList();

    private static List<ReceptionistDailyTaskDefinition> MapTasks(IEnumerable<ReceptionistDailyTaskDto>? tasks)
        => (tasks ?? Enumerable.Empty<ReceptionistDailyTaskDto>())
            .Where(t => !string.IsNullOrWhiteSpace(t.Name))
            .Select(t => new ReceptionistDailyTaskDefinition
            {
                Id = string.IsNullOrWhiteSpace(t.Id) ? Guid.NewGuid().ToString("N") : t.Id,
                Name = t.Name.Trim(),
                IsActive = t.IsActive,
            })
            .ToList();

    private static List<ReceptionistKpiTier> MapTiers(IEnumerable<ReceptionistKpiTierDto>? tiers)
        => (tiers ?? Enumerable.Empty<ReceptionistKpiTierDto>())
            .Select(t => new ReceptionistKpiTier
            {
                Id = string.IsNullOrWhiteSpace(t.Id) ? Guid.NewGuid().ToString("N") : t.Id,
                Label = string.IsNullOrWhiteSpace(t.Label) ? "Tier" : t.Label.Trim(),
                Goal = Math.Max(0m, t.Goal),
                RewardPercent = Math.Max(0m, t.RewardPercent),
            })
            .ToList();

    private static ReceptionistKpiMonthSettingsDto MapSettings(ReceptionistKpiMonthOverride row) => new()
    {
        Year = row.Year,
        Month = row.Month,
        MonthLabel = new DateTime(row.Year, row.Month, 1).ToString("MMMM yyyy", CultureInfo.InvariantCulture),
        KpiEnabled = row.KpiEnabled,
        BonusPoolAmount = row.BonusPoolAmount,
        DailyTaskCompletionPercent = row.DailyTaskCompletionPercent,
        AttendanceCommissionPerHead = row.AttendanceCommissionPerHead,
        AttendanceSplitMode = row.AttendanceSplitMode,
        GoogleReviewCount = row.GoogleReviewCount,
        Note = row.Note,
        DailyTasks = row.DailyTasks.Select(t => new ReceptionistDailyTaskDto { Id = t.Id, Name = t.Name, IsActive = t.IsActive }).ToList(),
        RevenueTiers = row.RevenueTiers.Select(MapTierDto).ToList(),
        PackageSalesTiers = row.PackageSalesTiers.Select(MapTierDto).ToList(),
        GoogleReviewTiers = row.GoogleReviewTiers.Select(MapTierDto).ToList(),
    };

    private static ReceptionistKpiTierDto MapTierDto(ReceptionistKpiTier t) => new()
    {
        Id = t.Id,
        Label = t.Label,
        Goal = t.Goal,
        RewardPercent = t.RewardPercent,
    };

    private static Staff? ResolveSelectedReceptionist(IEnumerable<Staff> staff, string? requestedId)
    {
        var list = staff.ToList();
        if (list.Count == 0)
            return null;
        if (!string.IsNullOrWhiteSpace(requestedId))
        {
            var match = list.FirstOrDefault(x => x.Id == requestedId);
            if (match is not null)
                return match;
        }
        return list[0];
    }

    private static DateTime ParseSelectedDate(string? dateKey, int year, int month)
    {
        if (DateOnly.TryParseExact(dateKey, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out var parsed))
            return parsed.ToDateTime(TimeOnly.MinValue);

        var today = DateTime.UtcNow.Date;
        if (today.Year == year && today.Month == month)
            return today;

        return new DateTime(year, month, 1);
    }

    // ── Task status + completion (default + custom, both count) ──

    private async Task<List<ReceptionistTaskStatusDto>> BuildTaskStatusAsync(
        Staff staff,
        ReceptionistKpiMonthOverride monthConfig,
        string dateKey,
        CancellationToken ct)
    {
        var log = await _taskLogs
            .Find(x => x.StaffId == staff.Id && x.DateKey == dateKey)
            .FirstOrDefaultAsync(ct);

        var completed = (log?.CompletedTaskIds ?? new List<string>())
            .ToHashSet(StringComparer.OrdinalIgnoreCase);

        var result = monthConfig.DailyTasks
            .Where(x => x.IsActive)
            .Select(x => new ReceptionistTaskStatusDto
            {
                Id = x.Id,
                Name = x.Name,
                IsCompleted = completed.Contains(x.Id),
                IsCustom = false,
            })
            .ToList();

        var customs = await _customTasks.Find(x => x.DateKey == dateKey).SortBy(x => x.CreatedAt).ToListAsync(ct);
        result.AddRange(customs.Select(c => new ReceptionistTaskStatusDto
        {
            Id = c.Id!,
            Name = c.Name,
            IsCompleted = completed.Contains(c.Id!),
            IsCustom = true,
        }));

        return result;
    }

    private async Task<int> CountCompletedTaskDaysAsync(
        string staffId,
        int year,
        int month,
        ReceptionistKpiMonthOverride monthConfig,
        CancellationToken ct)
    {
        var defaultTaskIds = monthConfig.DailyTasks
            .Where(x => x.IsActive && !string.IsNullOrWhiteSpace(x.Id))
            .Select(x => x.Id)
            .ToList();

        var logs = await _taskLogs
            .Find(x => x.StaffId == staffId && x.Year == year && x.Month == month)
            .ToListAsync(ct);
        if (logs.Count == 0)
            return 0;

        // Custom tasks for this month, grouped by date — each day's required set is the
        // month's default tasks PLUS that day's custom tasks (custom tasks count).
        var monthCustoms = await _customTasks.Find(x => x.Year == year && x.Month == month).ToListAsync(ct);
        var customsByDate = monthCustoms
            .GroupBy(x => x.DateKey)
            .ToDictionary(g => g.Key, g => g.Select(x => x.Id!).ToList());

        var completedDays = 0;
        foreach (var log in logs)
        {
            var required = new HashSet<string>(defaultTaskIds, StringComparer.OrdinalIgnoreCase);
            if (customsByDate.TryGetValue(log.DateKey, out var customIds))
                foreach (var cid in customIds) required.Add(cid);

            if (required.Count == 0)
                continue; // nothing to complete that day → doesn't earn the daily reward

            var done = log.CompletedTaskIds.ToHashSet(StringComparer.OrdinalIgnoreCase);
            if (required.All(done.Contains))
                completedDays++;
        }

        return completedDays;
    }

    // ── Metrics ──────────────────────────────────────────────────

    private async Task<ReceptionistMonthMetrics> ComputeMonthMetricsAsync(
        int year,
        int month,
        ReceptionistKpiMonthOverride monthConfig,
        int receptionistCount,
        CancellationToken ct)
    {
        var start = new DateTime(year, month, 1, 0, 0, 0, DateTimeKind.Utc);
        var end = start.AddMonths(1);

        var paidInvoices = await _invoices
            .Find(x => x.Status == "PAID" && x.IssueDate >= start && x.IssueDate < end)
            .ToListAsync(ct);

        var grossRevenue = paidInvoices.Sum(x => x.TotalNet);
        var packageSales = await CountPackageSalesAsync(paidInvoices, ct);

        var sessions = await _sessions
            .Find(x => x.Status == "COMPLETED" && x.StartTime >= start && x.StartTime < end && !x.IsFreelance)
            .Project(x => x.Id)
            .ToListAsync(ct);

        decimal attendanceHeadcount = 0m;
        if (sessions.Count > 0)
        {
            var attendanceRows = await _attendances
                .Find(Builders<Attendance>.Filter.And(
                    Builders<Attendance>.Filter.In(x => x.CalendarSessionId, sessions),
                    Builders<Attendance>.Filter.In(x => x.Status, CountingAttendanceStatuses)))
                .ToListAsync(ct);

            attendanceHeadcount = attendanceRows.Sum(x => Math.Max(1, x.Quantity));
        }

        var commissionPool = RoundVnd(attendanceHeadcount * Math.Max(0m, monthConfig.AttendanceCommissionPerHead));
        var splitCount = Math.Max(1, receptionistCount);

        return new ReceptionistMonthMetrics
        {
            GrossRevenue = grossRevenue,
            PackageSalesCount = packageSales,
            AttendanceHeadcount = attendanceHeadcount,
            AttendanceCommissionPool = commissionPool,
            AttendanceCommissionPerReceptionist = commissionPool / splitCount,
        };
    }

    private async Task<int> CountPackageSalesAsync(List<Invoice> paidInvoices, CancellationToken ct)
    {
        var legacyProductIds = paidInvoices
            .SelectMany(x => x.Lines)
            .Where(x => string.IsNullOrWhiteSpace(x.ProductTypeSnapshot) && !string.IsNullOrWhiteSpace(x.ProductId))
            .Select(x => x.ProductId!)
            .Distinct()
            .ToList();

        var legacyProducts = legacyProductIds.Count == 0
            ? new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
            : (await _products.Find(x => legacyProductIds.Contains(x.Id!)).ToListAsync(ct))
                .ToDictionary(x => x.Id!, x => x.Type ?? string.Empty, StringComparer.OrdinalIgnoreCase);

        return paidInvoices
            .SelectMany(x => x.Lines)
            .Count(line =>
            {
                var productType = line.ProductTypeSnapshot;
                if (string.IsNullOrWhiteSpace(productType) && !string.IsNullOrWhiteSpace(line.ProductId))
                    legacyProducts.TryGetValue(line.ProductId, out productType);
                return string.Equals(productType, "PACKAGE", StringComparison.OrdinalIgnoreCase);
            });
    }

    private List<ReceptionistKpiCategoryProgressDto> BuildCategories(
        ReceptionistKpiMonthOverride monthConfig,
        ReceptionistMonthMetrics metrics,
        int completedTaskDays,
        decimal bonusPool,
        decimal revenuePercent,
        decimal packagePercent,
        decimal reviewPercent,
        decimal taskPercent,
        bool isAdminView)
    {
        return new List<ReceptionistKpiCategoryProgressDto>
        {
            new()
            {
                Key = "dailyTasks",
                Label = "Daily Tasks",
                Description = "Complete every daily checklist item to unlock each day's reward.",
                UnlockedPercent = taskPercent,
                UnlockedAmount = RoundVnd(bonusPool * taskPercent / 100m),
                ProgressLabel = $"{completedTaskDays} full day{(completedTaskDays == 1 ? string.Empty : "s")} completed",
                AdminDetail = $"{monthConfig.DailyTaskCompletionPercent:N0}% reward for each fully completed day",
            },
            BuildTierCategory(
                key: "revenue",
                label: "Revenue Targets",
                description: "Tier-based studio revenue milestones.",
                currentValue: metrics.GrossRevenue,
                unlockedPercent: revenuePercent,
                bonusPool: bonusPool,
                tiers: monthConfig.RevenueTiers,
                currentValueLabel: "tiers unlocked",
                adminDetail: null, // gross revenue intentionally hidden on the KPI page
                redactGoals: true),
            BuildTierCategory(
                key: "packages",
                label: "Package Sales",
                description: "Paid package sales only. Studio rental packages are excluded.",
                currentValue: metrics.PackageSalesCount,
                unlockedPercent: packagePercent,
                bonusPool: bonusPool,
                tiers: monthConfig.PackageSalesTiers,
                currentValueLabel: "packages sold",
                adminDetail: isAdminView ? $"{metrics.PackageSalesCount:N0} qualifying packages sold" : null,
                redactGoals: false),
            BuildTierCategory(
                key: "reviews",
                label: "Google Reviews",
                description: "Monthly Google review count entered by admin.",
                currentValue: monthConfig.GoogleReviewCount,
                unlockedPercent: reviewPercent,
                bonusPool: bonusPool,
                tiers: monthConfig.GoogleReviewTiers,
                currentValueLabel: "reviews reached",
                adminDetail: isAdminView ? $"{monthConfig.GoogleReviewCount:N0} reviews entered for this month" : null,
                redactGoals: false),
        };
    }

    private ReceptionistKpiCategoryProgressDto BuildTierCategory(
        string key,
        string label,
        string description,
        decimal currentValue,
        decimal unlockedPercent,
        decimal bonusPool,
        IEnumerable<ReceptionistKpiTier> tiers,
        string currentValueLabel,
        string? adminDetail,
        bool redactGoals)
    {
        var ordered = tiers
            .OrderBy(x => x.Goal)
            .ToList();

        var unlockedCount = ordered.Count(x => currentValue >= x.Goal);
        var tierDtos = ordered.Select(tier => new ReceptionistKpiTierProgressDto
        {
            Id = tier.Id,
            Label = tier.Label,
            GoalLabel = redactGoals ? tier.Label : $"{tier.Goal:N0}",
            RewardLabel = $"+{tier.RewardPercent:N0}%",
            IsUnlocked = currentValue >= tier.Goal,
            ProgressLabel = currentValue >= tier.Goal
                ? "Unlocked"
                : redactGoals
                    ? "Not yet reached"
                    : $"{currentValue:N0} / {tier.Goal:N0}",
        }).ToList();

        return new ReceptionistKpiCategoryProgressDto
        {
            Key = key,
            Label = label,
            Description = description,
            UnlockedPercent = unlockedPercent,
            UnlockedAmount = RoundVnd(bonusPool * unlockedPercent / 100m),
            ProgressLabel = $"{unlockedCount} / {ordered.Count} {currentValueLabel}",
            AdminDetail = adminDetail,
            Tiers = tierDtos,
        };
    }

    private static decimal ComputeTierReward(decimal currentValue, IEnumerable<ReceptionistKpiTier> tiers)
        => tiers.Where(x => currentValue >= x.Goal).Sum(x => Math.Max(0m, x.RewardPercent));

    private static ReceptionistKpiStaffDto MapStaff(Staff staff) => new()
    {
        Id = staff.Id ?? string.Empty,
        Name = staff.Name,
        Email = staff.Email,
        PhotoUrl = staff.PhotoUrl,
    };

    private static decimal RoundVnd(decimal amount) => Math.Round(amount, 0, MidpointRounding.AwayFromZero);

    private sealed class ReceptionistMonthMetrics
    {
        public decimal GrossRevenue { get; set; }
        public decimal PackageSalesCount { get; set; }
        public decimal AttendanceHeadcount { get; set; }
        public decimal AttendanceCommissionPool { get; set; }
        public decimal AttendanceCommissionPerReceptionist { get; set; }
    }
}

