function buildReceptionistKpiPayload() {
  return {
    enableReceptionistKpiProgram: document.getElementById("enableReceptionistKpiProgram").checked,
    receptionistKpiBonusPoolAmount: parseFloat(document.getElementById("receptionistKpiBonusPoolAmount").value) || 0,
    receptionistDailyTaskCompletionPercent: parseFloat(document.getElementById("receptionistDailyTaskCompletionPercent").value) || 0,
    receptionistAttendanceCommissionPerHead: parseFloat(document.getElementById("receptionistAttendanceCommissionPerHead").value) || 0,
    receptionistAttendanceSplitMode: "EQUAL_ACTIVE",
    receptionistDailyTasks: receptionistDailyTasks
      .map((task) => ({ id: task.id, name: (task.name || "").trim(), isActive: task.isActive !== false }))
      .filter((task) => task.name),
    receptionistRevenueTiers: receptionistRevenueTiers
      .map((tier) => ({ id: tier.id, label: (tier.label || "").trim(), goal: Number(tier.goal || 0), rewardPercent: Number(tier.rewardPercent || 0) }))
      .filter((tier) => tier.label),
    receptionistPackageSalesTiers: receptionistPackageSalesTiers
      .map((tier) => ({ id: tier.id, label: (tier.label || "").trim(), goal: Number(tier.goal || 0), rewardPercent: Number(tier.rewardPercent || 0) }))
      .filter((tier) => tier.label),
    receptionistGoogleReviewTiers: receptionistGoogleReviewTiers
      .map((tier) => ({ id: tier.id, label: (tier.label || "").trim(), goal: Number(tier.goal || 0), rewardPercent: Number(tier.rewardPercent || 0) }))
      .filter((tier) => tier.label),
  };
}

function isRoleMasterLocked(roleKey) {
  return roleKey === "admin";
}

