// ── Per-month KPI settings (KPI & Bonuses tab) ──────────────────
const _kpiNow = new Date();
let kpiYear = _kpiNow.getFullYear();
let kpiMonth = _kpiNow.getMonth() + 1; // 1-12
let kpiLoaded = false;
let kpiGoogleReviewCount = 0; // preserved on save (edited on the KPI Bonus page)

function mapTiersOut(rows) {
  return (rows || [])
    .map((tier) => ({ id: tier.id, label: (tier.label || "").trim(), goal: Number(tier.goal || 0), rewardPercent: Number(tier.rewardPercent || 0) }))
    .filter((tier) => tier.label);
}

function buildKpiMonthPayload() {
  return {
    year: kpiYear,
    month: kpiMonth,
    kpiEnabled: document.getElementById("enableReceptionistKpiProgram").checked,
    bonusPoolAmount: parseFloat(document.getElementById("receptionistKpiBonusPoolAmount").value) || 0,
    dailyTaskCompletionPercent: parseFloat(document.getElementById("receptionistDailyTaskCompletionPercent").value) || 0,
    attendanceCommissionPerHead: parseFloat(document.getElementById("receptionistAttendanceCommissionPerHead").value) || 0,
    attendanceSplitMode: "EQUAL_ACTIVE",
    googleReviewCount: kpiGoogleReviewCount,
    note: "",
    dailyTasks: receptionistDailyTasks
      .map((task) => ({ id: task.id, name: (task.name || "").trim(), isActive: task.isActive !== false }))
      .filter((task) => task.name),
    revenueTiers: mapTiersOut(receptionistRevenueTiers),
    packageSalesTiers: mapTiersOut(receptionistPackageSalesTiers),
    googleReviewTiers: mapTiersOut(receptionistGoogleReviewTiers),
  };
}

function applyKpiMonthSettings(s) {
  kpiGoogleReviewCount = s.googleReviewCount ?? 0;
  document.getElementById("kpiMonthLabel").textContent = s.monthLabel || `${kpiYear}-${kpiMonth}`;
  document.getElementById("kpiCarriedNote").style.display = s.carriedForward ? "" : "none";
  document.getElementById("enableReceptionistKpiProgram").checked = s.kpiEnabled === true;
  document.getElementById("receptionistKpiBonusPoolAmount").value = s.bonusPoolAmount ?? 5000000;
  document.getElementById("receptionistDailyTaskCompletionPercent").value = s.dailyTaskCompletionPercent ?? 1;
  document.getElementById("receptionistAttendanceCommissionPerHead").value = s.attendanceCommissionPerHead ?? 0;
  receptionistDailyTasks = Array.isArray(s.dailyTasks) ? s.dailyTasks.map((t) => normaliseTask(t)) : [];
  receptionistRevenueTiers = Array.isArray(s.revenueTiers) ? s.revenueTiers.map((t) => normaliseTier(t, "revenue")) : [];
  receptionistPackageSalesTiers = Array.isArray(s.packageSalesTiers) ? s.packageSalesTiers.map((t) => normaliseTier(t, "package")) : [];
  receptionistGoogleReviewTiers = Array.isArray(s.googleReviewTiers) ? s.googleReviewTiers.map((t) => normaliseTier(t, "review")) : [];
  renderAllReceptionistKpiEditors();
}

async function loadKpiMonthSettings() {
  try {
    const r = await fetch(`${API}/api/receptionist-kpi/month-settings?year=${kpiYear}&month=${kpiMonth}`, {
      headers: { Authorization: "Bearer " + token },
    });
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    applyKpiMonthSettings(await r.json());
    kpiLoaded = true;
  } catch (e) {
    const lbl = document.getElementById("kpiMonthLabel");
    if (lbl) lbl.textContent = "(failed to load)";
  }
}

async function saveKpiMonthSettings() {
  const btn = document.getElementById("saveKpiBtn");
  const msg = document.getElementById("saveKpiMsg");
  const err = document.getElementById("saveKpiErr");
  msg.style.display = "none"; err.style.display = "none";
  btn.disabled = true; btn.textContent = "Saving…";
  try {
    const r = await fetch(`${API}/api/receptionist-kpi/month-settings`, {
      method: "PUT",
      headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
      body: JSON.stringify(buildKpiMonthPayload()),
    });
    if (!r.ok) { const e = await r.json().catch(() => ({})); throw new Error(e.message || `HTTP ${r.status}`); }
    applyKpiMonthSettings(await r.json());
    msg.style.display = "";
    setTimeout(() => { msg.style.display = "none"; }, 2500);
  } catch (e) {
    err.textContent = e.message || "Could not save."; err.style.display = "";
  } finally {
    btn.disabled = false; btn.textContent = "Save KPI settings for this month";
  }
}

function kpiShiftMonth(delta) {
  let m = kpiMonth - 1 + delta;
  kpiYear += Math.floor(m / 12);
  kpiMonth = ((m % 12) + 12) % 12 + 1;
  loadKpiMonthSettings();
}

