async function loadDashboard() {
  const { year, month } = selectedYearMonth();
  if (!year || !month) return;

  const params = new URLSearchParams({
    year: String(year),
    month: String(month),
    date: dayPicker.value,
  });
  if (isAdmin && staffPicker.value) params.set("staffId", staffPicker.value);

  const res = await fetch(`${API}/api/receptionist-kpi/dashboard?${params.toString()}`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.message || `Failed to load KPI data (${res.status})`);

  currentDashboard = data;
  renderDashboard(data);
}

function renderDashboard(data) {
  const { year, month } = selectedYearMonth();
  const totalPercent = Math.round(Number(data.totalUnlockedPercent || 0));
  const projection = buildProjection(totalPercent);
  const totalBonusPool = Number(data.bonusPoolAmount || 0);
  const projectedBonusAmount = Math.round(totalBonusPool * (projection.forecast / 100));
  const completedTasks = (data.dailyTasks || []).filter((task) => task.isCompleted).length;
  const allTasksCount = (data.dailyTasks || []).length;
  const taskCategory = (data.categories || []).find((category) => String(category.label).toLowerCase() === "daily tasks");

