function renderTasks(tasks) {
  const host = document.getElementById("taskList");
  host.innerHTML = tasks.map((task) => `
    <label class="kpi-task-item">
      <input type="checkbox" data-task-id="${task.id}" ${task.isCompleted ? "checked" : ""}>
      <div class="kpi-task-label">
        <strong>${escapeHtml(task.name)}${task.isCustom ? ' <span style="font-size:10px;padding:1px 7px;border-radius:999px;background:var(--color-brand-soft,rgba(234,106,36,.15));color:var(--color-brand-accent);margin-left:6px;vertical-align:middle;">One-off</span>' : ''}</strong>
        <small>${task.isCompleted ? "Completed for this day" : "Pending for this day"}</small>
      </div>
      ${task.isCustom ? `<button type="button" data-del-custom="${task.id}" title="Remove this one-off task" style="background:none;border:none;color:var(--color-danger);cursor:pointer;font-size:15px;line-height:1;padding:0 6px;">✕</button>` : ''}
      <span class="kpi-task-status-chip ${task.isCompleted ? "done" : "pending"}">${task.isCompleted ? "Done" : "Pending"}</span>
    </label>
  `).join("") + `
    <div style="display:flex;gap:8px;margin-top:12px;">
      <input type="text" id="customTaskName" placeholder="Add a one-off task for this day…" style="flex:1;padding:8px 11px;border:1px solid var(--color-border-subtle,#333);border-radius:8px;background:transparent;color:inherit;font-size:13px;" />
      <button type="button" id="addCustomTaskBtn" class="btn btn-secondary btn-sm">+ Add</button>
    </div>`;
  host.querySelectorAll("[data-del-custom]").forEach((b) =>
    b.addEventListener("click", (e) => { e.preventDefault(); deleteCustomTask(b.dataset.delCustom); }));
  const addBtn = document.getElementById("addCustomTaskBtn");
  if (addBtn) addBtn.addEventListener("click", addCustomTask);
  const inp = document.getElementById("customTaskName");
  if (inp) inp.addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); addCustomTask(); } });
}

async function addCustomTask() {
  const inp = document.getElementById("customTaskName");
  const name = (inp?.value || "").trim();
  if (!name) return;
  try {
    const r = await fetch(`${API}/api/receptionist-kpi/custom-tasks`, {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
      body: JSON.stringify({ dateKey: dayPicker.value, name }),
    });
    if (!r.ok) throw new Error();
    await loadDashboard();
  } catch (e) {
    window.showToast?.("Could not add task", "error");
  }
}

async function deleteCustomTask(id) {
  try {
    await fetch(`${API}/api/receptionist-kpi/custom-tasks/${id}`, {
      method: "DELETE",
      headers: { Authorization: `Bearer ${token}` },
    });
    await loadDashboard();
  } catch (e) {}
}

