---
<AdminLayout title="Email Log" activePage="email-log">

  <div class="page-header">
    <div>
      <div class="page-title">Email Log</div>
      <div class="page-subtitle">Every email the system sent — recipient, subject, and delivery status.</div>
    </div>
  </div>

  <div class="el-toolbar">
    <input type="text" id="elSearch" placeholder="Search recipient or subject…" />
    <div class="el-chips" id="elChips">
      <button class="el-chip active" data-status="">All</button>
      <button class="el-chip" data-status="SENT">Sent</button>
      <button class="el-chip" data-status="FAILED">Failed</button>
      <button class="el-chip" data-status="REDIRECTED">Redirected</button>
      <button class="el-chip" data-status="SUPPRESSED">Suppressed</button>
    </div>
    <button class="el-refresh" id="elRefresh">↻ Refresh</button>
  </div>

  <div class="el-card">
    <table class="el-table">
      <thead>
