using MongoDB.Bson.Serialization.Attributes;

namespace SoulPilates.Core.Entities;

/// <summary>
/// A metadata-only record of one outbound email. Written by EmailService on every
/// send attempt so the studio has an in-app audit of what went out (and what
/// failed) without depending on the Brevo dashboard or ephemeral container logs.
/// The rendered HTML body is intentionally NOT stored (privacy + size).
/// </summary>
public class EmailLog : BaseEntity
{
    /// <summary>The intended recipient (the real customer, even if test-mode redirected it).</summary>
    public string To { get; set; } = string.Empty;

    /// <summary>Rendered subject line.</summary>
    public string Subject { get; set; } = string.Empty;

    /// <summary>
    /// SENT — handed to the SMTP server successfully.
    /// FAILED — SMTP threw (see <see cref="Error"/>).
    /// SUPPRESSED — test mode dropped it (no redirect target).
    /// REDIRECTED — test mode sent it to <see cref="RedirectedTo"/> instead.
    /// </summary>
    public string Status { get; set; } = "SENT";

    /// <summary>SMTP error message when <see cref="Status"/> is FAILED.</summary>
    public string? Error { get; set; }

    /// <summary>Where the email was actually delivered when test-mode redirected it.</summary>
    public string? RedirectedTo { get; set; }
}

