using MongoDB.Driver;
using System.Text.RegularExpressions;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.Services;

/// <summary>
/// Stores outbound-email metadata in the <c>EmailLogs</c> collection and serves it
/// back to the admin "Email Log" page. Recording is best-effort: a logging failure
/// is swallowed so it can never break the actual email send.
/// </summary>
public class EmailLogService : IEmailLogService
{
    private readonly IMongoCollection<EmailLog> _logs;

    public EmailLogService(MongoDbContext db)
        => _logs = db.GetCollection<EmailLog>("EmailLogs");

    public async Task RecordAsync(EmailLog log)
    {
        try
        {
            log.CreatedAt = DateTime.UtcNow;
            await _logs.InsertOneAsync(log);
        }
        catch
        {
            // Best-effort audit — never surface a logging failure to the caller.
        }
    }

    public async Task<EmailLogPage> QueryAsync(int page, int pageSize, string? status = null, string? search = null)
    {
        page = Math.Max(1, page);
        pageSize = Math.Clamp(pageSize, 1, 200);

        var filters = new List<FilterDefinition<EmailLog>>();
        if (!string.IsNullOrWhiteSpace(status))
            filters.Add(Builders<EmailLog>.Filter.Eq(l => l.Status, status.Trim().ToUpperInvariant()));
        if (!string.IsNullOrWhiteSpace(search))
        {
            var rx = new MongoDB.Bson.BsonRegularExpression(Regex.Escape(search.Trim()), "i");
            filters.Add(Builders<EmailLog>.Filter.Or(
                Builders<EmailLog>.Filter.Regex(l => l.To, rx),
                Builders<EmailLog>.Filter.Regex(l => l.Subject, rx)));
        }

        var filter = filters.Count > 0
            ? Builders<EmailLog>.Filter.And(filters)
            : Builders<EmailLog>.Filter.Empty;

        var total = await _logs.CountDocumentsAsync(filter);
        var items = await _logs.Find(filter)
            .SortByDescending(l => l.CreatedAt)
            .Skip((page - 1) * pageSize)
            .Limit(pageSize)
            .ToListAsync();

        return new EmailLogPage { Items = items, Total = total };
    }
}

