---
import AdminLayout from "../../layouts/AdminLayout.astro";
---
<AdminLayout title="Email Log" activePage="email-log" accessModules="audit-log">

  <div class="page-header">
    <div>
      <div class="page-title">Email Log</div>
      <div class="page-subtitle">Every email the system sent — recipient, subject, and delivery status.</div>
    </div>
  </div>

  <div class="el-toolbar">
    <input type="text" id="elSearch" placeholder="Search recipient or subject…" />
    <div class="el-chips" id="elChips">
      <button class="el-chip active" data-status="">All</button>
      <button class="el-chip" data-status="SENT">Sent</button>
      <button class="el-chip" data-status="FAILED">Failed</button>
      <button class="el-chip" data-status="REDIRECTED">Redirected</button>
      <button class="el-chip" data-status="SUPPRESSED">Suppressed</button>
    </div>
    <button class="el-refresh" id="elRefresh">↻ Refresh</button>
  </div>

  <div class="el-card">
    <table class="el-table">
      <thead>
        <tr><th style="width:170px;">When</th><th>Recipient</th><th>Subject</th><th style="width:120px;">Status</th></tr>
      </thead>
      <tbody id="elBody">
        <tr><td colspan="4" class="el-empty">Loading…</td></tr>
      </tbody>
    </table>
  </div>

  <div class="el-pager">
    <button id="elPrev" class="el-pgbtn">‹ Prev</button>
    <span id="elPageInfo">—</span>
    <button id="elNext" class="el-pgbtn">Next ›</button>
  </div>

  <!-- Email preview modal -->
  <div id="elModalBg" class="el-modal-bg" style="display:none;">
    <div class="el-modal">
      <div class="el-modal-head">
        <div style="min-width:0;">
          <div class="el-modal-subject" id="elmSubject">—</div>
          <div class="el-modal-meta" id="elmMeta">—</div>
        </div>
        <button class="el-modal-x" id="elModalClose">✕</button>
      </div>
      <div class="el-modal-body">
        <div id="elmNoBody" class="el-empty" style="display:none;">This email was sent before body-logging was enabled, so its content wasn’t stored.</div>
        <iframe id="elmFrame" class="el-frame" sandbox=""></iframe>
      </div>
    </div>
  </div>
</AdminLayout>

<style is:global>
  .el-toolbar { display:flex; flex-wrap:wrap; gap:10px; align-items:center; padding:12px 14px; background:var(--color-surface); border:1px solid var(--color-border); border-radius:12px; margin-bottom:14px; }
  .el-toolbar input { background:var(--color-surface-raised); color:var(--color-text-primary); border:1px solid var(--color-border); padding:7px 11px; border-radius:8px; font-size:13px; min-width:230px; flex:1; }
  .el-toolbar input:focus { outline:none; border-color:var(--color-brand-accent); }
  .el-chips { display:flex; gap:6px; flex-wrap:wrap; }
  .el-chip { cursor:pointer; padding:6px 12px; border-radius:999px; border:1px solid var(--color-border); background:var(--color-surface-raised); color:var(--color-text-muted); font-size:12.5px; }
  .el-chip.active { background:var(--color-brand-accent); color:#fff; border-color:var(--color-brand-accent); font-weight:600; }
  .el-refresh { cursor:pointer; padding:7px 12px; border-radius:8px; border:1px solid var(--color-border); background:var(--color-surface-raised); color:var(--color-text-primary); font-size:13px; }

  .el-card { border:1px solid var(--color-border); border-radius:12px; overflow:hidden; background:var(--color-surface); }
  .el-table { width:100%; border-collapse:collapse; font-size:13px; }
  .el-table thead th { text-align:left; padding:11px 14px; font-size:11px; text-transform:uppercase; letter-spacing:.05em; color:var(--color-text-muted); border-bottom:1px solid var(--color-border); background:var(--color-surface-raised); }
  .el-table tbody td { padding:11px 14px; border-bottom:1px solid var(--color-border-subtle,var(--color-border)); vertical-align:top; }
  .el-table tbody tr:last-child td { border-bottom:none; }
  .el-when { color:var(--color-text-muted); white-space:nowrap; }
  .el-to { font-weight:600; word-break:break-all; }
  .el-subj { color:var(--color-text-primary); }
  .el-err { display:block; margin-top:3px; font-size:11.5px; color:var(--color-danger); }
  .el-redir { display:block; margin-top:3px; font-size:11.5px; color:var(--color-text-muted); }
  .el-empty { text-align:center; padding:26px; color:var(--color-text-muted); }
  .el-badge { display:inline-block; padding:3px 9px; border-radius:999px; font-size:11px; font-weight:600; }
  .el-badge.SENT { background:rgba(34,197,94,.15); color:#22C55E; }
  .el-badge.FAILED { background:rgba(239,68,68,.16); color:#EF4444; }
  .el-badge.REDIRECTED { background:rgba(59,130,246,.16); color:#3B82F6; }
  .el-badge.SUPPRESSED { background:rgba(148,163,184,.16); color:#94A3B8; }

  .el-pager { display:flex; align-items:center; justify-content:center; gap:14px; margin-top:14px; font-size:13px; color:var(--color-text-muted); }
  .el-pgbtn { cursor:pointer; padding:7px 14px; border-radius:8px; border:1px solid var(--color-border); background:var(--color-surface-raised); color:var(--color-text-primary); font-size:13px; }
  .el-pgbtn:disabled { opacity:.4; cursor:default; }
  .el-table tbody tr.el-row { cursor:pointer; }
  .el-table tbody tr.el-row:hover { background:var(--color-brand-soft,rgba(234,106,36,.06)); }

  .el-modal-bg { position:fixed; inset:0; background:rgba(0,0,0,.55); z-index:700; display:flex; align-items:center; justify-content:center; padding:20px; }
  .el-modal { background:var(--color-bg-elevated,var(--color-surface,#1a1a1a)); border:1px solid var(--color-border); border-radius:14px; width:820px; max-width:100%; max-height:92vh; display:flex; flex-direction:column; overflow:hidden; box-shadow:0 20px 60px rgba(0,0,0,.45); }
  .el-modal-head { display:flex; justify-content:space-between; align-items:flex-start; gap:12px; padding:16px 20px; border-bottom:1px solid var(--color-border); }
  .el-modal-subject { font-size:16px; font-weight:700; color:var(--color-text-primary); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
  .el-modal-meta { font-size:12px; color:var(--color-text-muted); margin-top:3px; }
  .el-modal-x { background:none; border:none; font-size:18px; cursor:pointer; color:var(--color-text-muted); line-height:1; }
  .el-modal-body { padding:0; flex:1; min-height:0; display:flex; }
  .el-frame { width:100%; height:70vh; border:0; background:#fff; }
</style>

<script>
  const API = import.meta.env.PUBLIC_API_URL;
  const token = localStorage.getItem('token');
  const PAGE_SIZE = 50;
  let page = 1, status = '', search = '', total = 0;

  const esc = s => String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt = iso => { const d = new Date(iso); return d.toLocaleString('en-GB',{ day:'2-digit', month:'short', hour:'2-digit', minute:'2-digit' }); };

  async function load() {
    const body = document.getElementById('elBody');
    body.innerHTML = '<tr><td colspan="4" class="el-empty">Loading…</td></tr>';
    const qs = new URLSearchParams({ page:String(page), pageSize:String(PAGE_SIZE) });
    if (status) qs.set('status', status);
    if (search) qs.set('search', search);
    let data = { items: [], total: 0 };
    try {
      const r = await fetch(`${API}/api/email-logs?${qs}`, { headers: { Authorization: 'Bearer ' + token } });
      if (r.ok) data = await r.json();
      else if (r.status === 403) { body.innerHTML = '<tr><td colspan="4" class="el-empty">You don’t have access to the email log.</td></tr>'; return; }
    } catch (e) {}
    total = data.total || 0;
    if (!data.items || !data.items.length) {
      body.innerHTML = '<tr><td colspan="4" class="el-empty">No emails found for this filter.</td></tr>';
    } else {
      body.innerHTML = data.items.map(l => {
        const err = l.error ? `<span class="el-err">⚠ ${esc(l.error)}</span>` : '';
        const redir = l.redirectedTo ? `<span class="el-redir">→ delivered to ${esc(l.redirectedTo)} (test mode)</span>` : '';
        return `<tr class="el-row" data-id="${esc(l.id)}">
          <td class="el-when">${esc(fmt(l.createdAt))}</td>
          <td><span class="el-to">${esc(l.to)}</span>${redir}</td>
          <td><span class="el-subj">${esc(l.subject)}</span>${err}</td>
          <td><span class="el-badge ${esc(l.status)}">${esc(l.status)}</span></td>
        </tr>`;
      }).join('');
    }
    const pages = Math.max(1, Math.ceil(total / PAGE_SIZE));
    document.getElementById('elPageInfo').textContent = `Page ${page} of ${pages} · ${total} email${total===1?'':'s'}`;
    document.getElementById('elPrev').disabled = page <= 1;
    document.getElementById('elNext').disabled = page >= pages;
  }

  let searchTimer;
  document.getElementById('elSearch').addEventListener('input', e => {
    clearTimeout(searchTimer);
    searchTimer = setTimeout(() => { search = e.target.value.trim(); page = 1; load(); }, 300);
  });
  document.getElementById('elChips').addEventListener('click', e => {
    const btn = e.target.closest('.el-chip'); if (!btn) return;
    document.querySelectorAll('.el-chip').forEach(c => c.classList.remove('active'));
    btn.classList.add('active'); status = btn.dataset.status; page = 1; load();
  });
  document.getElementById('elRefresh').addEventListener('click', load);
  document.getElementById('elPrev').addEventListener('click', () => { if (page>1){ page--; load(); } });
  document.getElementById('elNext').addEventListener('click', () => { page++; load(); });
  load();
</script>

