// ── Load active PACKAGE products for upsell dropdowns ──
fetch(`${API}/api/product`, { headers: { Authorization: "Bearer " + token } })
  .then((r) => (r.ok ? r.json() : []))
  .then((products) => {
    const pkgs = (products || []).filter((p) => p.isActive && p.type === "PACKAGE");
    ["upsellPkgGroup", "upsellPkgPrivate", "upsellPkgMixed"].forEach((selId) => {
      const sel = document.getElementById(selId);
      if (!sel) return;
      pkgs.forEach((p) => {
        const opt = document.createElement("option");
        opt.value = p.id;
        const pricePerClass = p.credits > 0 ? Math.round(p.basePrice / p.credits) : p.basePrice;
        opt.textContent = `${p.name} (${p.credits} cr · ${Math.round(p.basePrice).toLocaleString()}₫ · ${Math.round(pricePerClass).toLocaleString()}₫/class)`;
        sel.appendChild(opt);
      });
    });
    // Select saved values once options are populated.
    const setVal = (id, val) => { const el = document.getElementById(id); if (el && val) el.value = val; };
    setVal("upsellPkgGroup",   window._upsellPkgGroup   || "");
    setVal("upsellPkgPrivate", window._upsellPkgPrivate || "");
    setVal("upsellPkgMixed",   window._upsellPkgMixed   || "");
  });

// Toggle picker visibility on radio change.
document.querySelectorAll('input[name="stripeMode"]').forEach((r) => {
  r.addEventListener("change", () => {
    const isOwner = document.getElementById("stripeModeOwner").checked;
    document.getElementById("stripeOwnerPickerWrap").style.display = isOwner
      ? ""
      : "none";

