// ── Load active PACKAGE products for upsell dropdowns ──
// The saved upsell selections (window._upsellPkg*) come from the settings fetch,
// while the dropdown OPTIONS come from this product fetch. These two run in
// parallel, so applying the saved value has to happen after BOTH finish —
// otherwise (products-first) the saved selection is silently dropped and the next
// Save writes a blank, wiping the config. applyUpsellSelections() is therefore
// called from both completions; the one that runs last is the one that sticks.
window._upsellProductsLoaded = false;
window.applyUpsellSelections = function () {
  if (!window._upsellProductsLoaded) return; // options not there yet
  const setVal = (id, val) => { const el = document.getElementById(id); if (el) el.value = val || ""; };
  setVal("upsellPkgGroup",   window._upsellPkgGroup   || "");
  setVal("upsellPkgPrivate", window._upsellPkgPrivate || "");
  setVal("upsellPkgMixed",   window._upsellPkgMixed   || "");
};
fetch(`${API}/api/product`, { headers: { Authorization: "Bearer " + token } })
  .then((r) => (r.ok ? r.json() : []))
  .then((products) => {
    const pkgs = (products || []).filter((p) => p.isActive && p.type === "PACKAGE");
    ["upsellPkgGroup", "upsellPkgPrivate", "upsellPkgMixed"].forEach((selId) => {
      const sel = document.getElementById(selId);
      if (!sel) return;
      pkgs.forEach((p) => {
        const opt = document.createElement("option");
        opt.value = p.id;
        const pricePerClass = p.credits > 0 ? Math.round(p.basePrice / p.credits) : p.basePrice;
        opt.textContent = `${p.name} (${p.credits} cr · ${Math.round(p.basePrice).toLocaleString()}₫ · ${Math.round(pricePerClass).toLocaleString()}₫/class)`;
        sel.appendChild(opt);
      });
    });
    window._upsellProductsLoaded = true;
    window.applyUpsellSelections();
  });

