private readonly ISettingsService? _settingsService;
private readonly IEmailLogService? _emailLogService;

/// <summary>
/// Studio wall-clock timezone. Session times are stored in UTC, but customers
/// must see Vietnam local time (UTC+7) in emails — otherwise a 5:00 PM class
/// reads as 10:00 AM. Falls back to a fixed +7 offset if the tz database entry
/// isn't present on the host.
/// </summary>
private static readonly TimeZoneInfo StudioTz = ResolveStudioTz();
private static TimeZoneInfo ResolveStudioTz()
{
    foreach (var id in new[] { "Asia/Ho_Chi_Minh", "SE Asia Standard Time" })
    {
        try { return TimeZoneInfo.FindSystemTimeZoneById(id); } catch { }
    }
    return TimeZoneInfo.CreateCustomTimeZone("VN+7", TimeSpan.FromHours(7), "Vietnam", "Vietnam");
}

/// <summary>Convert a stored UTC session time to studio-local wall-clock time.</summary>
private static DateTime StudioLocal(DateTime classTime)
    => TimeZoneInfo.ConvertTimeFromUtc(DateTime.SpecifyKind(classTime, DateTimeKind.Utc), StudioTz);

