namespace SoulPilates.Services;

/// <summary>
/// Studio wall-clock time (Asia/Ho_Chi_Minh, UTC+7). Session times are stored in
/// UTC; any human-readable time in an email, push notification, invoice note, or
/// export MUST be converted through here first, otherwise a 5:00 PM class reads as
/// 10:00 AM. Falls back to a fixed +7 offset if the tz database entry is missing.
/// </summary>
public static class StudioTime
{
    public static readonly TimeZoneInfo Tz = Resolve();

    private static TimeZoneInfo Resolve()
    {
        foreach (var id in new[] { "Asia/Ho_Chi_Minh", "SE Asia Standard Time" })
        {
            try { return TimeZoneInfo.FindSystemTimeZoneById(id); } catch { }
        }
        return TimeZoneInfo.CreateCustomTimeZone("VN+7", TimeSpan.FromHours(7), "Vietnam", "Vietnam");
    }

    /// <summary>Convert a stored UTC time to studio-local wall-clock time.</summary>
    public static DateTime Local(DateTime utc)
        => TimeZoneInfo.ConvertTimeFromUtc(DateTime.SpecifyKind(utc, DateTimeKind.Utc), Tz);
}

