public class ReceptionistKpiDashboardDto
{
    public int Year { get; set; }
    public int Month { get; set; }
    public string MonthLabel { get; set; } = string.Empty;
    public bool KpiEnabled { get; set; }
    public bool IsAdminView { get; set; }
    public string SelectedDateKey { get; set; } = string.Empty;
    public ReceptionistKpiStaffDto Staff { get; set; } = new();
    public List<ReceptionistKpiStaffDto> Receptionists { get; set; } = new();
    public ReceptionistKpiMonthConfigDto MonthConfig { get; set; } = new();
    public decimal BonusPoolAmount { get; set; }
    public decimal TotalUnlockedPercent { get; set; }
    public decimal TotalUnlockedAmount { get; set; }
