tabsRoot.querySelectorAll("[data-goal-key]").forEach((button) => {
  button.addEventListener("click", () => {
    currentGoalKey = button.dataset.goalKey;
    renderGoalTabsAndRows(goalTabs);
  });
});

const activeCategory = goalTabs.find((category) => getCategoryMeta(category).key === currentGoalKey) || goalTabs[0];
const meta = getCategoryMeta(activeCategory);
const unlockedCount = (activeCategory.tiers || []).filter((tier) => tier.isUnlocked).length;

summaryRoot.innerHTML = `
  <strong style="display:block;font-size:16px;color:var(--color-text-primary);">${escapeHtml(activeCategory.label)}</strong>
  <span style="display:block;margin-top:6px;">${escapeHtml(activeCategory.progressLabel || activeCategory.description || "")}</span>
`;

rowsRoot.innerHTML = (activeCategory.tiers || []).map((tier, index) => {
  const state = deriveGoalRowState(activeCategory, tier, index);
  const width = deriveGoalProgressWidth(activeCategory, tier, index);
  const goalColor = tier.isUnlocked ? meta.color : state === "active" ? "#ff8d2f" : "rgba(255,255,255,0.4)";
  const subtext = tier.isUnlocked
    ? tier.progressLabel || "Unlocked"
    : tier.goalLabel || tier.progressLabel || "Not yet reached";
  return `
    <div class="kpi-goal-row ${state}" style="--goal-color:${goalColor};">
      <div class="kpi-goal-marker">
        ${state === "unlocked"
          ? `<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg>`
          : state === "active"
            ? `<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="8"></circle></svg>`
            : `<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="8"></circle></svg>`}
      </div>
      <div>
        <div class="kpi-goal-title-line">
          <strong>${escapeHtml(tier.label)}</strong>
          <span class="kpi-goal-reward-pill">${escapeHtml(tier.rewardLabel || `+${parseRewardPercent(tier.rewardLabel)}%`)}</span>
        </div>
        <div class="kpi-goal-subtext">${escapeHtml(subtext)}</div>
        <div class="kpi-goal-progress">
          <div class="kpi-progress-bar" style="--bar-width:${width}%;--bar-color:${state === "unlocked" ? meta.color : "#ff8d2f"};">
            <span></span>
          </div>
        </div>
      </div>
      <div class="kpi-goal-side" style="--goal-color:${state === "unlocked" ? meta.color : "#ff8d2f"};">
        <strong>${state === "unlocked" ? "Unlocked" : state === "active" ? "In progress" : "Pending"}</strong>
        <span>${escapeHtml(tier.goalLabel || "")}</span>
      </div>
    </div>
  `;
}).join("");

footerRoot.textContent = unlockedCount === (activeCategory.tiers || []).length
  ? "This category is fully unlocked for the month."
  : "Keep moving through each tier to unlock more of the monthly bonus.";

