[HttpGet("schedule")]
public async Task<IActionResult> GetPublicSchedule([FromQuery] DateTime start, [FromQuery] DateTime end, [FromQuery] string? format, [FromQuery] string? instructorId)
{
    var sessions = await _schedulingService.GetPublicScheduleAsync(start, end, format, instructorId);
    var result = sessions.Select(s => new
    {
        s.Id,
        s.ClassBlueprintId,
        s.InstructorId,
        s.ClassName,
        s.FocusArea,
        s.DifficultyLevel,
        s.Format,
        s.InstructorName,
        s.InstructorPhotoUrl,
        s.StartTime,
        s.EndTime,
        s.Capacity,
        s.CurrentBookings,
        // SPM-71 — keep returning the singular for back-compat AND the full
        // list so the booking page can show/filter on multiple equipment.
        // Old sessions only have the singular: treat a missing list as [singular].
        s.EquipmentType,
        EquipmentTypes = ResolveEquipmentTypes(s),
        s.ImageUrl,
        s.Tags,
        SpotsLeft = s.Capacity - s.CurrentBookings,
        IsFull = s.CurrentBookings >= s.Capacity
    });
    return Ok(result);
}

