873	    public async Task<bool> RemoveAttendanceAsync(string attendanceId)
874	    {
875	        var att = await _attendances.Find(a => a.Id == attendanceId).FirstOrDefaultAsync();
876	        if (att is null) return false;
877	
878	        // Refund any consumed package credit — ledger-driven, with the legacy
879	        // PackageInstanceId fallback (mirrors the session-cancel refund path).
880	        var (refunded, hasLedgerTrail) = await _walletService.RefundCreditByAttendanceWithTrailAsync(att.Id!);
881	        if (!refunded && !hasLedgerTrail && !string.IsNullOrEmpty(att.PackageInstanceId))
882	            await _walletService.RefundCreditAsync(
883	                att.PackageInstanceId, att.RescheduledFromAttendanceId ?? att.Id!);
884	
885	        // Delete the row and free the seat(s).
886	        await _attendances.DeleteOneAsync(a => a.Id == attendanceId);
887	        if (!string.IsNullOrWhiteSpace(att.CalendarSessionId))
888	        {
