public class ExportService : IExportService
{
    private readonly IMongoDatabase _db;

    // Curated, human-useful datasets for the business export (name → collection).
    private static readonly (string Sheet, string Collection)[] BusinessDatasets =
    {
        ("Clients", "Clients"),
        ("CustomerAccounts", "CustomerAccounts"),
        ("Bookings", "Attendances"),
        ("Classes", "CalendarSessions"),
        ("Invoices", "Invoices"),
        ("Payments", "Payments"),
        ("Packages", "ClientPackages"),
        ("Products", "Products"),
        ("Expenses", "Expenses"),
        ("Staff", "Staff"),
        ("Payroll", "StaffPayables"),
        ("PayrollRuns", "PayrollRuns"),
        ("Promotions", "Promotions"),
        ("PromoRedemptions", "PromoRedemptions"),
    };

    // Never write these to an export (secrets).
    private static readonly HashSet<string> RedactKeys = new(StringComparer.OrdinalIgnoreCase)
    {
        "PasswordHash", "StripeSecretKeyEncrypted", "StripePublishableKeyEncrypted",
        "StripeWebhookSecretEncrypted",
    };

    public ExportService(MongoDbContext ctx) => _db = ctx.Database;

    public async Task<ExportResult> ExportBusinessAsync(string format, CancellationToken ct = default)
    {
        var datasets = new List<(string Sheet, List<string> Columns, List<Dictionary<string, string>> Rows)>();
        foreach (var (sheet, coll) in BusinessDatasets)
        {
            var (cols, rows) = await LoadFlatAsync(coll, ct);
            datasets.Add((sheet, cols, rows));
        }

        var stamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmm");
        return (format ?? "").ToLowerInvariant() switch
        {
            "csv" => new ExportResult(BuildCsvZip(datasets), "application/zip", $"soulpilates-export-{stamp}.zip"),
            "json" => new ExportResult(BuildBusinessJson(datasets), "application/json", $"soulpilates-export-{stamp}.json"),
            _ => new ExportResult(BuildXlsx(datasets), "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", $"soulpilates-export-{stamp}.xlsx"),
        };
    }

    public async Task<ExportResult> ExportFullBackupAsync(bool zip, CancellationToken ct = default)
    {
        var names = (await _db.ListCollectionNames().ToListAsync(ct)).OrderBy(n => n).ToList();
        var settings = new JsonWriterSettings { OutputMode = JsonOutputMode.RelaxedExtendedJson };

        var sb = new StringBuilder();
        sb.Append('{');
        for (int i = 0; i < names.Count; i++)
        {
            var coll = _db.GetCollection<BsonDocument>(names[i]);
            var docs = await coll.Find(FilterDefinition<BsonDocument>.Empty).ToListAsync(ct);
            sb.Append(JsonString(names[i])).Append(':').Append('[');
            for (int j = 0; j < docs.Count; j++)
            {
                Redact(docs[j]);
                sb.Append(docs[j].ToJson(settings));
                if (j < docs.Count - 1) sb.Append(',');
            }
            sb.Append(']');
            if (i < names.Count - 1) sb.Append(',');
        }
        sb.Append('}');

        var json = Encoding.UTF8.GetBytes(sb.ToString());
        var stamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmm");
        if (!zip)
            return new ExportResult(json, "application/json", $"soulpilates-backup-{stamp}.json");

        using var ms = new MemoryStream();
        using (var archive = new ZipArchive(ms, ZipArchiveMode.Create, true))
        {
            var entry = archive.CreateEntry($"soulpilates-backup-{stamp}.json", CompressionLevel.Optimal);
            using var es = entry.Open();
            es.Write(json, 0, json.Length);
        }
        return new ExportResult(ms.ToArray(), "application/zip", $"soulpilates-backup-{stamp}.zip");
    }

    // ── helpers ──────────────────────────────────────────────────

    private async Task<(List<string> Columns, List<Dictionary<string, string>> Rows)> LoadFlatAsync(string collection, CancellationToken ct)
    {
        var docs = await _db.GetCollection<BsonDocument>(collection)
            .Find(FilterDefinition<BsonDocument>.Empty).ToListAsync(ct);

        var rows = new List<Dictionary<string, string>>(docs.Count);
        var columns = new List<string>();
        var seen = new HashSet<string>();

        foreach (var doc in docs)
        {
            var row = new Dictionary<string, string>();
            foreach (var el in doc.Elements)
            {
                var key = el.Name == "_id" ? "id" : el.Name;
                if (seen.Add(key)) columns.Add(key);
                row[key] = RedactKeys.Contains(el.Name) ? "[redacted]" : Scalar(el.Value);
            }
            rows.Add(row);
        }

        // Stable, readable column order: id first, then the rest as discovered.
        columns = columns.OrderBy(c => c == "id" ? 0 : 1).ToList();
        return (columns, rows);
    }

    /// <summary>BSON value → a flat string cell (nested docs/arrays become compact JSON).</summary>
    private static string Scalar(BsonValue v)
    {
        if (v == null || v.IsBsonNull) return "";
        return v.BsonType switch
        {
            BsonType.ObjectId => v.AsObjectId.ToString(),
            BsonType.DateTime => v.ToUniversalTime().ToString("yyyy-MM-dd HH:mm:ss"),
            BsonType.Decimal128 => v.AsDecimal.ToString(System.Globalization.CultureInfo.InvariantCulture),
            BsonType.Double => v.AsDouble.ToString(System.Globalization.CultureInfo.InvariantCulture),
            BsonType.Boolean => v.AsBoolean ? "true" : "false",
            BsonType.Int32 => v.AsInt32.ToString(),
            BsonType.Int64 => v.AsInt64.ToString(),
            BsonType.String => v.AsString,
            BsonType.Document or BsonType.Array => v.ToJson(new JsonWriterSettings { OutputMode = JsonOutputMode.RelaxedExtendedJson }),
            _ => v.ToString() ?? "",
        };
    }

    private static void Redact(BsonDocument doc)
    {
        foreach (var key in RedactKeys)
            if (doc.Contains(key)) doc[key] = "[redacted]";
    }

    private static byte[] BuildXlsx(List<(string Sheet, List<string> Columns, List<Dictionary<string, string>> Rows)> datasets)
    {
        using var wb = new XLWorkbook();
        foreach (var (sheet, columns, rows) in datasets)
        {
            var ws = wb.AddWorksheet(SafeSheetName(sheet, wb));
            for (int c = 0; c < columns.Count; c++)
                ws.Cell(1, c + 1).Value = columns[c];
            ws.Row(1).Style.Font.Bold = true;
            for (int r = 0; r < rows.Count; r++)
                for (int c = 0; c < columns.Count; c++)
                    ws.Cell(r + 2, c + 1).SetValue(rows[r].TryGetValue(columns[c], out var val) ? val : "");
            if (columns.Count > 0) ws.SheetView.FreezeRows(1);
        }
        using var ms = new MemoryStream();
        wb.SaveAs(ms);
        return ms.ToArray();
    }

    private static string SafeSheetName(string name, XLWorkbook wb)
    {
        var clean = new string(name.Where(ch => !"[]:*?/\\".Contains(ch)).ToArray());
        if (clean.Length > 31) clean = clean[..31];
        if (string.IsNullOrWhiteSpace(clean)) clean = "Sheet";
        var final = clean; var i = 2;
        while (wb.Worksheets.Any(w => string.Equals(w.Name, final, StringComparison.OrdinalIgnoreCase)))
            final = (clean.Length > 28 ? clean[..28] : clean) + "_" + i++;
        return final;
    }

    private static byte[] BuildCsvZip(List<(string Sheet, List<string> Columns, List<Dictionary<string, string>> Rows)> datasets)
    {
        using var ms = new MemoryStream();
        using (var archive = new ZipArchive(ms, ZipArchiveMode.Create, true))
        {
            foreach (var (sheet, columns, rows) in datasets)
            {
                var entry = archive.CreateEntry($"{sheet}.csv", CompressionLevel.Optimal);
                using var es = entry.Open();
                using var w = new StreamWriter(es, new UTF8Encoding(true)); // BOM for Excel
                w.WriteLine(string.Join(",", columns.Select(CsvEscape)));
                foreach (var row in rows)
                    w.WriteLine(string.Join(",", columns.Select(c => CsvEscape(row.TryGetValue(c, out var v) ? v : ""))));
            }
        }
        return ms.ToArray();
    }

    private static byte[] BuildBusinessJson(List<(string Sheet, List<string> Columns, List<Dictionary<string, string>> Rows)> datasets)
    {
        var sb = new StringBuilder();
        sb.Append('{');
        for (int d = 0; d < datasets.Count; d++)
        {
            sb.Append(JsonString(datasets[d].Sheet)).Append(":[");
            var rows = datasets[d].Rows;
            for (int r = 0; r < rows.Count; r++)
            {
                sb.Append('{');
                var kvs = rows[r].ToList();
                for (int k = 0; k < kvs.Count; k++)
                {
                    sb.Append(JsonString(kvs[k].Key)).Append(':').Append(JsonString(kvs[k].Value));
                    if (k < kvs.Count - 1) sb.Append(',');
                }
                sb.Append('}');
                if (r < rows.Count - 1) sb.Append(',');
            }
            sb.Append(']');
            if (d < datasets.Count - 1) sb.Append(',');
        }
        sb.Append('}');
        return Encoding.UTF8.GetBytes(sb.ToString());
    }

    private static string CsvEscape(string s)
    {
        s ??= "";
        if (s.Contains('"') || s.Contains(',') || s.Contains('\n') || s.Contains('\r'))
            return "\"" + s.Replace("\"", "\"\"") + "\"";
        return s;
    }

    private static string JsonString(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var ch in s ?? "")
        {
            switch (ch)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (ch < 0x20) sb.Append("\\u").Append(((int)ch).ToString("x4"));
                    else sb.Append(ch);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }
}

