using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.API.Controllers;

/// <summary>
/// Admin-only data export: curated business datasets (Excel/CSV/JSON) and a full
/// raw database backup (JSON). Downloads are generated on demand.
/// </summary>
[ApiController]
[Route("api/export")]
[Authorize(Roles = "Admin")]
public class ExportController : ControllerBase
{
    private readonly IExportService _export;

    public ExportController(IExportService export) => _export = export;

    /// <summary>Business datasets. format = xlsx (default) | csv | json.</summary>
    [HttpGet("business")]
    public async Task<IActionResult> Business([FromQuery] string format = "xlsx", CancellationToken ct = default)
    {
        var r = await _export.ExportBusinessAsync(format, ct);
        return File(r.Content, r.ContentType, r.FileName);
    }

    /// <summary>Full raw backup of every collection. format = json (default) | zip.</summary>
    [HttpGet("backup")]
    public async Task<IActionResult> Backup([FromQuery] string format = "json", CancellationToken ct = default)
    {
        var r = await _export.ExportFullBackupAsync(string.Equals(format, "zip", StringComparison.OrdinalIgnoreCase), ct);
        return File(r.Content, r.ContentType, r.FileName);
    }
}

