import AdminLayout from "../../layouts/AdminLayout.astro";
---
<AdminLayout title="Data Export" activePage="export" accessModules="settings">

  <div class="page-header">
    <div>
      <div class="page-title">Data Export</div>
      <div class="page-subtitle">Download your studio data for accounting, reporting, or a full backup.</div>
    </div>
  </div>

  <div class="ex-grid">
    <div class="card ex-card">
      <div class="card-header">
        <div>
          <div class="card-title">📊 Business data</div>
          <div class="card-subtitle">Clients, bookings, invoices, payments, packages, payroll and more — one clean table per dataset.</div>
        </div>
      </div>
      <div class="card-body">
        <p class="ex-note">Choose a format. Excel gives one workbook with a tab per dataset; CSV gives a zip of one file per dataset; JSON is structured for other tools.</p>
        <div class="ex-btns">
          <button class="btn btn-primary ex-btn" data-kind="business" data-format="xlsx">⬇ Excel (.xlsx)</button>
          <button class="btn btn-secondary ex-btn" data-kind="business" data-format="csv">⬇ CSV (.zip)</button>
          <button class="btn btn-secondary ex-btn" data-kind="business" data-format="json">⬇ JSON</button>
        </div>
      </div>
    </div>

    <div class="card ex-card">
      <div class="card-header">
        <div>
          <div class="card-title">💾 Full database backup</div>
          <div class="card-subtitle">A complete raw dump of every collection — a true technical backup you could restore from.</div>
        </div>
      </div>
      <div class="card-body">
        <p class="ex-note">This includes <strong>everything</strong> (all records, all collections). Passwords and encrypted keys are redacted for safety. Large studios: the file can be several MB.</p>
        <div class="ex-btns">
          <button class="btn btn-primary ex-btn" data-kind="backup" data-format="zip">⬇ Backup (.zip)</button>
          <button class="btn btn-secondary ex-btn" data-kind="backup" data-format="json">⬇ Backup (.json)</button>
        </div>
      </div>
    </div>
  </div>

  <div id="exStatus" class="ex-status" style="display:none;"></div>
</AdminLayout>

<style is:global>
  .ex-grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(320px,1fr)); gap:16px; }
  .ex-card { display:flex; flex-direction:column; }
  .ex-note { font-size:13px; color:var(--color-text-muted); line-height:1.5; margin:0 0 16px; }
  .ex-btns { display:flex; flex-wrap:wrap; gap:10px; }
  .ex-btn { cursor:pointer; }
  .ex-btn:disabled { opacity:.55; cursor:default; }
  .ex-status { margin-top:16px; padding:12px 16px; border-radius:10px; font-size:13.5px; border:1px solid var(--color-border); }
  .ex-status.ok { background:rgba(34,197,94,.12); color:#22C55E; border-color:rgba(34,197,94,.3); }
  .ex-status.err { background:rgba(239,68,68,.12); color:#EF4444; border-color:rgba(239,68,68,.3); }
  .ex-status.busy { color:var(--color-text-muted); }
</style>

<script>
  const API = import.meta.env.PUBLIC_API_URL;
  const token = localStorage.getItem("token");
  const statusEl = document.getElementById("exStatus");

  function setStatus(msg, kind) {
    statusEl.style.display = "";
    statusEl.className = "ex-status " + (kind || "busy");
    statusEl.textContent = msg;
  }

  async function download(kind, format, btn) {
    const url = `${API}/api/export/${kind}?format=${encodeURIComponent(format)}`;
    setStatus("Generating your export… this can take a few seconds for large data.", "busy");
    document.querySelectorAll(".ex-btn").forEach((b) => (b.disabled = true));
    try {
      const res = await fetch(url, { headers: { Authorization: "Bearer " + token } });
      if (!res.ok) {
        if (res.status === 401 || res.status === 403) throw new Error("You don’t have permission to export (admin only).");
        throw new Error(`Export failed (HTTP ${res.status}).`);
      }
      // Derive filename from Content-Disposition, else fall back.
      const cd = res.headers.get("Content-Disposition") || "";
      const match = /filename="?([^"]+)"?/.exec(cd);
      const fallback = kind === "backup" ? `soulpilates-backup.${format === "zip" ? "zip" : "json"}` : `soulpilates-export.${format === "xlsx" ? "xlsx" : format === "csv" ? "zip" : "json"}`;
      const filename = match ? match[1] : fallback;

      const blob = await res.blob();
      const a = document.createElement("a");
      const objUrl = URL.createObjectURL(blob);
      a.href = objUrl;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(objUrl);
      setStatus(`✓ Downloaded ${filename} (${(blob.size / 1024).toFixed(0)} KB).`, "ok");
    } catch (e) {
      setStatus("✗ " + (e.message || "Export failed."), "err");
    } finally {
      document.querySelectorAll(".ex-btn").forEach((b) => (b.disabled = false));
    }
  }

  document.querySelectorAll(".ex-btn").forEach((btn) => {
    btn.addEventListener("click", () => download(btn.dataset.kind, btn.dataset.format, btn));
  });
</script>

