function openSettleModal(staffName) {
  settleScopeStaff = staffName;
  settleExpenses = [];
  document.getElementById("settleStaffName").textContent = staffName;
  document.getElementById("settleYear").value = String(selectedYear);
  document.getElementById("settleMonth").value = String(selectedMonth);
  document.getElementById("settleError").style.display = "none";
  document.getElementById("settleModal").classList.add("open");
  fetch(`${API}/api/accounting/reimbursements?staffName=${encodeURIComponent(staffName)}`, {
    headers: { Authorization: "Bearer " + token },
  })
    .then((r) => r.json())
    .then((rows) => {
      settleExpenses = Array.isArray(rows) ? rows : [];
      renderSettleList();
    })
    .catch(() => {});
}

function renderSettleList() {
  const list = document.getElementById("settleList");
  if (!settleExpenses.length) {
    list.innerHTML = `<div style="text-align:center;padding:30px;color:var(--color-text-muted);">No outstanding expenses.</div>`;
    return;
  }
  list.innerHTML = settleExpenses.map(e => `
    <label style="display:flex;align-items:center;gap:10px;padding:10px 12px;border-bottom:1px solid var(--color-border-subtle);cursor:pointer;">
      <input type="checkbox" data-settle-id="${e.id}" data-amount="${e.amount}" checked />
      <div style="flex:1;">
        <div style="font-size:13px;">${escapeHtml(e.description ?? "")}</div>
        <div style="font-size:11px;color:var(--color-text-muted);">${new Date(e.dateIncurred).toLocaleDateString()} · ${escapeHtml(e.category ?? "")}</div>
      </div>
      <div style="font-weight:600;">${Number(e.amount).toLocaleString()} ₫</div>
    </label>`).join("");
  list.querySelectorAll("input[data-settle-id]").forEach(cb =>
    cb.addEventListener("change", recalcSettleTotal));
  recalcSettleTotal();
}

function recalcSettleTotal() {
  const total = Array.from(document.querySelectorAll("#settleList input[data-settle-id]:checked"))
    .reduce((s, cb) => s + (parseFloat(cb.getAttribute("data-amount")) || 0), 0);
  document.getElementById("settleTotal").textContent = `${total.toLocaleString()} ₫ selected`;
}

public async Task<ReimbursementSettleBatch> SettleReimbursementsAsync(
    string staffName, IEnumerable<string> expenseIds, int year, int month, string settledByUserId)
{
    if (string.IsNullOrWhiteSpace(staffName))
        throw new InvalidOperationException("Staff name is required.");
    if (month < 1 || month > 12)
        throw new InvalidOperationException("Month must be between 1 and 12.");

    var ids = expenseIds?.Where(s => !string.IsNullOrWhiteSpace(s)).Distinct().ToList() ?? new();
    // Filter to the actually-settle-able ones: belong to this staff, PaidBy=STAFF,
    // and not yet settled. Idempotent: already-settled ids are skipped silently.
    var canonical = staffName.Trim();
    var pattern = new MongoDB.Bson.BsonRegularExpression(
        $"^{System.Text.RegularExpressions.Regex.Escape(canonical)}$", "i");
    var settleable = ids.Count == 0 ? new List<Expense>() : await _expenses.Find(
        Builders<Expense>.Filter.And(
            Builders<Expense>.Filter.In(e => e.Id, ids),
            Builders<Expense>.Filter.Eq(e => e.PaidBy, "STAFF"),
            Builders<Expense>.Filter.Eq(e => e.ReimbursementSettled, false),
            Builders<Expense>.Filter.Regex(e => e.StaffName, pattern)))
        .ToListAsync();

    var batch = new ReimbursementSettleBatch
    {
        StaffName = canonical,
        Year = year,
        Month = month,
        ExpenseIds = settleable.Select(e => e.Id!).ToList(),
        TotalAmount = settleable.Sum(e => e.Amount),
        SettledByUserId = settledByUserId,
        SettledAt = DateTime.UtcNow,
    };
    await _settleBatches.InsertOneAsync(batch);

    // Resolve the recipient's owner-status NOW (settle-time) so the
    // washout reader can route this expense deterministically even if the
    // staff member is later promoted to/demoted from owner. (P5 snapshot.)
    var roster = await _owners.ListAsync();
    var matchingOwner = roster.FirstOrDefault(o =>
        o.IsActiveOwner &&
        !string.IsNullOrWhiteSpace(o.Name) &&
        string.Equals(o.Name.Trim(), canonical, StringComparison.OrdinalIgnoreCase));
    var snapshotRecipientType = matchingOwner is not null ? "OWNER" : "STAFF";
    var snapshotOwnerStaffId = matchingOwner?.StaffId;

    if (settleable.Count > 0)
    {
        await _expenses.UpdateManyAsync(
            Builders<Expense>.Filter.In(e => e.Id, batch.ExpenseIds),
            Builders<Expense>.Update
                .Set(e => e.ReimbursementSettled, true)
                .Set(e => e.SettledOn, batch.SettledAt)
                .Set(e => e.SettledForYear, year)
                .Set(e => e.SettledForMonth, month)
                .Set(e => e.SettledInBatchId, batch.Id)
                .Set(e => e.SettledAsRecipientType, snapshotRecipientType)
                .Set(e => e.SettledAsOwnerStaffId, snapshotOwnerStaffId));
    }

    // P5-PWA — ReimbursementSettled push. Notify the recipient staff

