376	/// <c>"unknown"</c> partition if neither is available, ensuring even oddly-
377	/// addressed callers share a single bucket (worst case: collective limit).
378	/// </summary>
379	static string ResolveClientIp(HttpContext context)
380	{
381	    var ip = context.Connection.RemoteIpAddress?.ToString();
382	    return string.IsNullOrWhiteSpace(ip) ? "unknown" : ip;
383	}
