    // UserId is known by the time we push it onto LogContext.
    app.UseMiddleware<CorrelationEnricherMiddleware>();

    app.UseAuthorization();
    app.MapControllers();

    Log.Information("SoulPilates.API starting in {Environment} environment", app.Environment.EnvironmentName);

    // NOTE: A covert remote kill-switch (UpdateCheckerService.ValidateEnvironmentAsync,
    // phoning home to an external server) was removed here — it took the whole system
    // offline whenever that server was unreachable. The app no longer depends on it.

    app.Run();
}
catch (Exception ex) when (ex is not HostAbortedException)
{
    Log.Fatal(ex, "SoulPilates.API terminated unexpectedly");
    throw;
}
finally
{
    Log.CloseAndFlush();
}

/// <summary>
/// Resolve the upstream client IP for rate-limit partitioning. Reads from
/// <c>Connection.RemoteIpAddress</c>, which the ForwardedHeaders middleware
/// (configured upstream of <c>UseRateLimiter</c>) has already populated with
/// the real client IP from the reverse proxy. Falls back to a sentinel
/// <c>"unknown"</c> partition if neither is available, ensuring even oddly-
/// addressed callers share a single bucket (worst case: collective limit).
/// </summary>
static string ResolveClientIp(HttpContext context)
{
    var ip = context.Connection.RemoteIpAddress?.ToString();
    return string.IsNullOrWhiteSpace(ip) ? "unknown" : ip;
}

