#!/usr/bin/env python3
import re, html, datetime, sys
from weasyprint import HTML

SRC = "/opt/soulpilates/SYSTEM_DOCUMENTATION.md"
OUT = "/opt/soulpilates/SYSTEM_DOCUMENTATION.pdf"

def inline(t):
    # escape first, then re-inject markup
    t = html.escape(t)
    t = re.sub(r'`([^`]+)`', r'<code>\1</code>', t)
    t = re.sub(r'\*\*([^*]+)\*\*', r'<strong>\1</strong>', t)
    t = re.sub(r'(?<!\w)\*([^*]+)\*(?!\w)', r'<em>\1</em>', t)
    t = re.sub(r'\[([^\]]+)\]\(([^)]+)\)', r'<a href="\2">\1</a>', t)
    return t

def parse(md):
    lines = md.split("\n")
    out = []
    i = 0
    n = len(lines)
    while i < n:
        ln = lines[i]

        # table: a line with | and next line is a separator row
        if ln.strip().startswith("|") and i + 1 < n and re.match(r'^\s*\|?[\s:|-]+\|[\s:|-]*$', lines[i+1]):
            header = [c.strip() for c in ln.strip().strip("|").split("|")]
            i += 2
            rows = []
            while i < n and lines[i].strip().startswith("|"):
                rows.append([c.strip() for c in lines[i].strip().strip("|").split("|")])
                i += 1
            out.append("<table><thead><tr>" + "".join(f"<th>{inline(c)}</th>" for c in header) + "</tr></thead><tbody>")
            for r in rows:
                out.append("<tr>" + "".join(f"<td>{inline(c)}</td>" for c in r) + "</tr>")
            out.append("</tbody></table>")
            continue

        # headings
        m = re.match(r'^(#{1,4})\s+(.*)$', ln)
        if m:
            lvl = len(m.group(1)); out.append(f"<h{lvl}>{inline(m.group(2))}</h{lvl}>"); i += 1; continue

        # hr
        if re.match(r'^---+\s*$', ln):
            out.append('<hr/>'); i += 1; continue

        # blockquote (possibly multi-line)
        if ln.strip().startswith(">"):
            buf = []
            while i < n and lines[i].strip().startswith(">"):
                buf.append(inline(re.sub(r'^\s*>\s?', '', lines[i]))); i += 1
            out.append("<blockquote>" + "<br/>".join(buf) + "</blockquote>")
            continue

        # lists (unordered/ordered), with wrapped continuation lines
        if re.match(r'^\s*([-*]|\d+\.)\s+', ln):
            items = []  # list of [indent, text]
            ordered = bool(re.match(r'^\s*\d+\.\s+', ln))
            def is_block(s):
                return bool(re.match(r'^(#{1,4}\s|>|---+\s*$|\|)', s.strip())) or s.strip() == ""
            while i < n:
                cur = lines[i]
                if re.match(r'^\s*([-*]|\d+\.)\s+', cur):
                    indent = len(cur) - len(cur.lstrip())
                    text = re.sub(r'^\s*([-*]|\d+\.)\s+', '', cur)
                    items.append([indent, inline(text)]); i += 1
                elif items and not is_block(cur):
                    items[-1][1] += " " + inline(cur.strip()); i += 1  # wrapped continuation
                else:
                    break
            base = min(x[0] for x in items)
            tag = "ol" if ordered else "ul"
            html_out = [f"<{tag}>"]
            open_sub = False
            for indent, text in items:
                if indent > base and not open_sub:
                    html_out.append("<ul>"); open_sub = True
                elif indent <= base and open_sub:
                    html_out.append("</ul>"); open_sub = False
                html_out.append(f"<li>{text}</li>")
            if open_sub: html_out.append("</ul>")
            html_out.append(f"</{tag}>")
            out.append("".join(html_out))
            continue

        # blank
        if ln.strip() == "":
            i += 1; continue

        # paragraph (gather until blank / block)
        buf = [ln]; i += 1
        while i < n and lines[i].strip() != "" and not re.match(r'^(#{1,4}\s|>|---+\s*$|\s*([-*]|\d+\.)\s|\|)', lines[i]):
            buf.append(lines[i]); i += 1
        out.append("<p>" + inline(" ".join(buf)) + "</p>")
    return "\n".join(out)

