      const _pur = {
        // Full class value (price × seats) — not amountDueNow, which is 0 for
        // package-credit / pay-at-studio bookings. The ad platforms need the
        // economic value of the booking for value/ROAS optimization.
        value: (q?.sessionFee || 0) * (q?.quantity || quantity || 1),
        currency: q?.currency || "VND",
        content_name: session?.className || "",
        content_category: session?.format || "",
        content_ids: sessionId ? [sessionId] : [],
      };
      if (typeof window.spMetaTrack === "function") window.spMetaTrack("Purchase", _pur, { email, phone });
      if (typeof window.spTiktokTrack === "function") window.spTiktokTrack("Purchase", _pur, { email, phone });
    }

    // First-party funnel: booking confirmed (end of funnel).
    if (window.spTrackFunnel) window.spTrackFunnel('PurchaseCompleted');
    // GA4 funnel: purchase completed (end of funnel)
    if (typeof window.spTrackEvent === "function") {
      const quoteForMethod = window._spQuotes?.[selectedMethod];
      window.spTrackEvent("purchase", {
        transaction_id: refStr,
        value: quoteForMethod?.amountDueNow || 0,
        currency: quoteForMethod?.currency || "VND",
        items: [
          {
            item_id: sessionId,
            item_name: session?.className || "",
            item_category: session?.format || "",
            quantity: quantity,
          },
        ],
      });
    }
