<!-- ── Google Analytics 4 — Dynamic Loader & Funnel Tracker ── -->
<script is:inline>
  // Loads GA4 gtag.js dynamically based on the admin-configured
  // Measurement ID. Fetched from public API so no secrets leak.
  // Full funnel tracking: page_view → view_class → begin_checkout → purchase
  (function initGA4() {
    // PUBLIC_API_URL is injected at build time into a <meta name="api-url"> tag.
    // We read it here because is:inline scripts are not processed by Vite
    // and cannot use import.meta.env (which caused a Firefox SyntaxError).
    var metaApi = document.querySelector('meta[name="api-url"]');
    var API_URL = metaApi ? metaApi.content : '';

    fetch(API_URL + '/api/analytics/ga-config')
      .then(function(res) { return res.ok ? res.json() : null; })
      .then(function(cfg) {
        if (!cfg || !cfg.measurementId) return;
        var gaId = cfg.measurementId;
        var enableEvents = cfg.enableEventTracking !== false;

        // 1. Inject gtag.js script
        var s = document.createElement('script');
        s.async = true;
        s.src = 'https://www.googletagmanager.com/gtag/js?id=' + gaId;
        document.head.appendChild(s);

        // 2. Initialize dataLayer + gtag
        window.dataLayer = window.dataLayer || [];
        function gtag() { window.dataLayer.push(arguments); }
        window.gtag = gtag;
        gtag('js', new Date());
        gtag('config', gaId, {
          page_path: window.location.pathname,
          send_page_view: true,
        });

        // 3. Expose event helper for pages to use
        window.spTrackEvent = function(eventName, params) {
          if (!enableEvents || typeof gtag !== 'function') return;
          gtag('event', eventName, params || {});
        };

        // 4. Track SPA-style navigations (if any)
        window.addEventListener('popstate', function() {
          gtag('config', gaId, { page_path: window.location.pathname });
        });
      })
      .catch(function(err) {
        // Silently fail — GA is non-critical
        console.debug('[GA4] Config fetch failed, analytics disabled:', err);
      });

