file.content:
function sourceBadge(src) {
  if (src === 'ONLINE') return '🌐';
  if (src === 'WALK_IN') return '🚶';
  if (src === 'ADMIN') return '👤';
  return '—';
}

async function loadBookings() {
  const tbody = document.getElementById('bookingTableBody');
  tbody.innerHTML = `<tr><td colspan="10" style="text-align:center;padding:48px;color:var(--color-text-muted);">Loading…</td></tr>`;

  try {
    const res = await fetch(`${API}/api/scheduling/bookings?${buildQueryParams()}`, {
      headers: { Authorization: 'Bearer ' + token },
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();

    if (!data.items || data.items.length === 0) {
      tbody.innerHTML = `<tr><td colspan="10" style="text-align:center;padding:48px;color:var(--color-text-muted);">No bookings found</td></tr>`;
      renderPagination(data);
      return;

