    (function () {
      try {
        if (localStorage.getItem('sp_mkt_source')) return; // first-touch wins
        var p = new URLSearchParams(location.search);
        var source = null, detail = null;
        var utm = p.get('utm_source');
        var gAds = p.get('gclid') || p.get('gad_source') || p.get('gbraid') || p.get('wbraid');
        if (gAds) { source = 'google_ads'; detail = p.get('utm_campaign') || p.get('campaignid') || null; }
        else if (utm) {
          source = utm.toLowerCase();
          detail = p.get('utm_campaign') || p.get('utm_medium') || null;
          var med = (p.get('utm_medium') || '').toLowerCase();
          if (source === 'google' && (med === 'cpc' || med === 'ppc' || med === 'paid')) source = 'google_ads';
        }
        else if (p.get('ttclid')) source = 'tiktok';
        else if (p.get('fbclid')) source = 'facebook';
        else {
          var host = '';
          try { host = document.referrer ? new URL(document.referrer).hostname.replace(/^www\./, '') : ''; } catch (e) {}
          if (/instagram\./.test(host)) source = 'instagram';
          else if (/facebook\.|(^|\.)fb\./.test(host)) source = 'facebook';
          else if (/tiktok\./.test(host)) source = 'tiktok';
          else if (/google\./.test(host)) source = 'google';
          else if (/youtube\./.test(host)) source = 'youtube';
          else if (/zalo\./.test(host)) source = 'zalo';
          else if (/bing\./.test(host)) source = 'bing';
