.sp-confirm-hero {
  text-align: center;
  padding: 32px 16px 16px;
}
.sp-confirm-iconwrap {
  position: relative;
  display: inline-flex;
  margin: 0 auto;
}
.sp-confirm-icon {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: rgba(61, 140, 92, 0.13);
  color: var(--sp-success);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto;
  position: relative;
  z-index: 1;
  animation: sp-pop 0.5s cubic-bezier(0.18, 0.89, 0.32, 1.28);
}
/* Celebration sparkles that burst out around the checkmark on success. */
.sp-sparkle {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 9px;
  height: 9px;
  background: var(--c, var(--sp-brand));
  border-radius: 2px;
  transform: translate(-50%, -50%) rotate(45deg) scale(0);
  opacity: 0;
  z-index: 0;
  animation:
    sp-sparkle-burst 0.9s cubic-bezier(0.16, 1, 0.3, 1) var(--d, 0s) forwards,
    sp-sparkle-twinkle 2.6s ease-in-out calc(var(--d, 0s) + 0.9s) infinite;
}
@keyframes sp-sparkle-burst {
  0% {
    transform: translate(-50%, -50%) rotate(45deg) scale(0);
    opacity: 0;
  }
  55% {
    transform: translate(calc(-50% + var(--x)), calc(-50% + var(--y))) rotate(45deg) scale(1.2);
    opacity: 1;
  }
  100% {
    transform: translate(calc(-50% + var(--x)), calc(-50% + var(--y))) rotate(45deg) scale(1);
    opacity: 1;
  }
}
@keyframes sp-sparkle-twinkle {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.3; }
}
@media (prefers-reduced-motion: reduce) {
  .sp-sparkle { animation: none; opacity: 0.85; transform: translate(calc(-50% + var(--x)), calc(-50% + var(--y))) rotate(45deg); }
  .sp-confirm-icon { animation: none; }
}
.sp-confirm-icon svg {
  width: 36px;
  height: 36px;
}
@keyframes sp-pop {
  0% {
    transform: scale(0);
  }
  100% {
    transform: scale(1);
  }
}
.sp-booking-ref {
  display: inline-block;
  margin-top: 16px;
  padding: 8px 16px;
  background: var(--sp-surface-raised);
  border-radius: var(--sp-radius-md);
  font-family: "JetBrains Mono", "Courier New", monospace;
  font-weight: 600;
  font-size: 14px;
  letter-spacing: 1px;
  color: var(--sp-text-primary);
}

/* Info card */
.sp-info-card {
  background: var(--sp-white);
  border: 1px solid var(--sp-border);
  border-radius: var(--sp-radius-lg);
  padding: 16px;
  display: flex;
  align-items: flex-start;
  gap: 12px;
}
.sp-info-card-icon {
  width: 40px;
  height: 40px;
  background: var(--sp-brand-soft);
  border-radius: var(--sp-radius-md);
  color: var(--sp-brand);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.sp-info-card-icon svg {
  width: 20px;
  height: 20px;
}
/* Grip-socks illustration is a full photo, not a line glyph, so it gets a
   larger footprint than the generic 20px icon. The tile that wraps it
   grows to fit (and drops the soft-brand chip background) so the image
   reads as a product photo rather than a clipped icon. */
.sp-info-card-icon:has(.sp-grip-socks-img) {
  width: auto;
