/* ─── Confirmation redesign ─────────────────────────────────────── */
.sp-conf-title {
  font-family: Georgia, "Cormorant Garamond", "Times New Roman", serif;
  font-weight: 600;
  letter-spacing: -0.01em;
}

/* Booking reference — labelled box with copy button */
.sp-conf-refbox {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  margin-top: 20px;
  padding: 10px 18px;
  background: var(--sp-surface-raised);
  border: 1px solid var(--sp-border);
  border-radius: var(--sp-radius-md);
}
.sp-conf-reflabel {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: var(--sp-text-muted);
}
.sp-conf-refrow {
  display: flex;
  align-items: center;
  gap: 10px;
}
.sp-conf-refbox .sp-booking-ref {
  margin-top: 0;
  padding: 0;
  background: none;
  font-size: 15px;
  letter-spacing: 1.5px;
}
.sp-conf-copy {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--sp-text-muted);
  cursor: pointer;
  border-radius: 6px;
  transition: background 0.15s ease, color 0.15s ease;
}
.sp-conf-copy svg { width: 15px; height: 15px; }
.sp-conf-copy:hover { background: var(--sp-brand-soft); color: var(--sp-brand); }
.sp-conf-copy.copied { color: var(--sp-success); }

/* Summary card with icon chips */
.sp-conf-card { padding: 22px 22px 12px; }
.sp-conf-cardhead {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-bottom: 16px;
  margin-bottom: 4px;
  border-bottom: 1px solid var(--sp-border);
}
.sp-conf-cardtitle {
  font-family: Georgia, "Cormorant Garamond", "Times New Roman", serif;
  font-size: 20px;
  font-weight: 600;
  color: var(--sp-text-primary);
}
.sp-conf-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--sp-success-soft);
  color: var(--sp-success);
}
.sp-conf-chip svg { width: 19px; height: 19px; }
.sp-conf-chip-brand {
  background: var(--sp-brand-soft);
  color: var(--sp-brand);
}
.sp-conf-row {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 12px 0;
  border-bottom: 1px solid var(--sp-border);
}
.sp-conf-row:last-child { border-bottom: none; }
.sp-conf-rowlabel {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: var(--sp-text-muted);
}
.sp-conf-rowvalue {
  margin-left: auto;
  text-align: right;
  font-size: 15px;
  font-weight: 600;
  color: var(--sp-text-primary);
}

/* Action buttons */
.sp-conf-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  width: 100%;
  padding: 15px 20px;
  border-radius: var(--sp-radius-md);
  font-size: 15px;
  font-weight: 600;
  text-decoration: none;
  transition: transform 0.12s ease, background 0.15s ease, border-color 0.15s ease;
}
.sp-conf-btn:active { transform: scale(0.985); }
.sp-conf-btn svg { width: 18px; height: 18px; flex-shrink: 0; }
.sp-conf-btn-primary {
  background: #3f5540;
  color: #fff;
  position: relative;
}
.sp-conf-btn-primary:hover { background: #35472f; }
.sp-conf-btn-primary .sp-conf-btn-arrow {
  position: absolute;
  right: 18px;
  opacity: 0.85;
}
.sp-conf-btn-outline {
  background: var(--sp-white);
  color: var(--sp-text-primary);
  border: 1px solid var(--sp-border-strong, var(--sp-border));
}
.sp-conf-btn-outline:hover { background: var(--sp-surface-raised); }

/* Warm closing note */
.sp-conf-note {
  margin-top: 20px;
  padding: 22px 20px;
  text-align: center;
  background: var(--sp-brand-soft);
  border-radius: var(--sp-radius-lg);
}
.sp-conf-note-heart { color: var(--sp-brand); display: inline-flex; }
.sp-conf-note-heart svg { width: 18px; height: 18px; }
.sp-conf-note-title {
  font-family: Georgia, "Cormorant Garamond", "Times New Roman", serif;
  font-size: 18px;
  font-weight: 600;
  color: var(--sp-text-primary);
  margin-top: 6px;
}
.sp-conf-note-text {
  font-size: 13px;
  color: var(--sp-text-muted);
  margin-top: 4px;
}

