function addToCart(p) {
  const isStudioRentalProduct = p.type === "FREELANCE_PACKAGE" || p.type === "FREELANCE_SINGLE";
  if (isStudioRentalProduct && saleMode !== "STUDIO_RENTAL") {
    window.showToast && window.showToast("Switch to Studio Rental Sale to sell rental products.", "warning");
    return;
  }
  if (!isStudioRentalProduct && saleMode === "STUDIO_RENTAL") {
    window.showToast && window.showToast("Studio rental checkout only supports studio rental products.", "warning");
    return;
  }
  if (p.type === "MERCHANDISE") {
    // P3-S14: defer the add to the variant picker. Tile click only opens the
    // modal; the actual cart push happens in addVariantToCart() below.
    openVariantPicker(p);
    return;
  }
  const ex = cart.find((c) => (c.lineKey ?? c.id) === p.id);
  if (ex) ex.qty++;
  else
    cart.push({ ...p, lineKey: p.id, unitPrice: p.basePrice ?? 0, qty: 1 });
  renderCart();
}

