async function openVariantPicker(product) {
  const overlay = document.getElementById("variantPickerOverlay");
  const list = document.getElementById("variantPickerList");
  document.getElementById("variantPickerTitle").textContent =
    `Pick a variant — ${product.name}`;
  list.innerHTML = `<div style="padding:24px;text-align:center;color:var(--color-text-muted);font-size:13px;">Loading variants…</div>`;
  overlay.style.display = "flex";

  try {
    const res = await fetch(`${API}/api/merchandise/${product.id}/skus`, {
      headers: { Authorization: "Bearer " + token },
    });
    if (!res.ok) throw new Error(`SKU load failed (${res.status})`);
    const skus = await res.json();
    if (!skus.length) {
      list.innerHTML = `<div style="padding:24px;text-align:center;color:var(--color-text-muted);font-size:13px;">No variants configured for this product yet.</div>`;
      return;
    }
    list.innerHTML = skus
      .map((s) => {
        const oos = (s.stockQuantity ?? 0) <= 0;
        const label =
          [s.variantColor, s.variantSize].filter(Boolean).join(" / ") ||
          s.sku ||
          "Variant";
        return `
        <button class="variant-tile" ${oos ? "disabled" : ""} data-id="${s.id}" data-color="${s.variantColor ?? ""}" data-size="${s.variantSize ?? ""}" style="display:flex;justify-content:space-between;align-items:center;width:100%;padding:12px 14px;border:1px solid var(--color-border-subtle);border-radius:var(--radius-sm);background:${oos ? "var(--color-surface)" : "var(--color-surface-raised)"};color:var(--color-text-primary);margin-bottom:8px;cursor:${oos ? "not-allowed" : "pointer"};opacity:${oos ? 0.55 : 1};text-align:left;">
          <div>
            <div style="font-weight:600;font-size:13px;">${label}</div>
            ${s.sku ? `<div style="font-size:11px;color:var(--color-text-muted);margin-top:2px;">${s.sku}</div>` : ""}
          </div>
          <div style="font-size:12px;color:${oos ? "var(--color-danger)" : "var(--color-text-muted)"};font-weight:600;">${oos ? "Out of stock" : s.stockQuantity + " in stock"}</div>
        </button>`;
      })
      .join("");

    list.querySelectorAll(".variant-tile").forEach((btn) => {
      btn.addEventListener("click", () => {
        if (btn.disabled) return;
        const sku = skus.find((x) => x.id === btn.dataset.id);
        if (!sku) return;
        addVariantToCart(product, sku);
        closeVariantPicker();
      });
    });
  } catch (e) {
    list.innerHTML = `<div style="padding:24px;text-align:center;color:var(--color-danger);font-size:13px;">${e?.message ?? "Could not load variants."}</div>`;
  }
}

function closeVariantPicker() {
  document.getElementById("variantPickerOverlay").style.display = "none";
}

function addVariantToCart(product, sku) {
  const label =
    [sku.variantColor, sku.variantSize].filter(Boolean).join(" / ") ||
    sku.sku ||
    "Variant";
  const lineKey = `${product.id}::sku${sku.id}`;
  const existing = cart.find((c) => c.lineKey === lineKey);
  if (existing) {
    // Don't push past the SKU's stock — the backend would reject the sale
    // anyway, this just gives instant feedback.
    if (existing.qty + 1 > (sku.stockQuantity ?? 0)) {
      window.showToast &&
        window.showToast(
          `Only ${sku.stockQuantity} of "${label}" in stock.`,
          "warning",
        );
      return;
    }
    existing.qty++;
  } else {
    cart.push({
      ...product,
      lineKey,
      variantId: sku.id,
      variantLabel: label,
      unitPrice: product.basePrice ?? 0,
      qty: 1,
    });
  }
  renderCart();
}
function removeFromCart(lineKey) {
  cart = cart.filter((c) => c.lineKey !== lineKey);
  renderCart();
}
function clearCart() {

