using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using System.Threading.Tasks;

namespace SoulPilates.API.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize(Roles = "Admin,Receptionist,Accountant")]
public class ProductController : ControllerBase
{
    private readonly IProductService _productService;

    public ProductController(IProductService productService)
    {
        _productService = productService;
    }

    [HttpGet]
    public async Task<IActionResult> GetAll()
    {
        var products = await _productService.GetAllProductsAsync();
        return Ok(products);
    }

    /// <summary>
    /// PUBLIC endpoint — returns only active PACKAGE products for the customer-facing catalog.
    /// </summary>
    [HttpGet("/api/products/packages")]
    [AllowAnonymous]
    public async Task<IActionResult> GetPublicPackages()
    {
        var products = await _productService.GetAllProductsAsync();
        var packages = products
            .Where(p => p.IsActive && !p.HiddenFromOnline && p.Type == "PACKAGE")
            .OrderBy(p => p.BasePrice)
            .Select(p => new
            {
                id = p.Id,
                name = p.Name,
                description = p.Description,
                iconKey = p.IconKey,
                formatRestriction = p.FormatRestriction,
                basePrice = p.BasePrice,
                credits = p.Credits,
                validityDays = p.ValidityDays,
                pricePerClass = p.Credits > 0 ? Math.Round(p.BasePrice / p.Credits) : p.BasePrice,
                isFeatured = p.IsFeatured
            });
        return Ok(packages);
    }

    [HttpGet("{id}")]
    public async Task<IActionResult> GetById(string id)
    {
        var product = await _productService.GetProductByIdAsync(id);
        if (product == null) return NotFound();
        return Ok(product);
    }

    [Authorize(Roles = "Admin")]
    [HttpPost]
    public async Task<IActionResult> Create([FromBody] Product product)
    {
        var created = await _productService.CreateProductAsync(product);
        return Ok(created);
    }

    [Authorize(Roles = "Admin")]
    [HttpPut("{id}")]
    public async Task<IActionResult> Update(string id, [FromBody] Product product)
    {
        await _productService.UpdateProductAsync(id, product);
        return Ok();
    }

    [Authorize(Roles = "Admin")]
    [HttpDelete("{id}")]
    public async Task<IActionResult> SoftDelete(string id)
    {
        await _productService.DeleteProductAsync(id);
        return Ok();
    }
}

