// _deletedSkuIds collects ids of rows the admin removed so we issue
// DELETE calls in the save fan-out.
let skus = [];
const _deletedSkuIds = [];

// Tier rendering is intentionally absent from this form.

// ── SKU editor (P3-S14) ───────────────────────────────────────────
function renderSkus() {
  const host = document.getElementById("skuRows");
  if (!host) return;
  host.innerHTML = skus
    .map(
      (s, i) => `
    <div style="background:var(--color-surface-raised);border-radius:var(--radius-sm);padding:14px 16px;position:relative;margin-bottom:12px;">
      <div style="display:flex;justify-content:space-between;margin-bottom:10px;">
        <div style="font-size:12px;font-weight:600;color:var(--color-text-muted);">Variant ${i + 1}${s.id ? "" : " · new"}</div>
        <button style="background:none;border:none;color:var(--color-danger);cursor:pointer;font-size:12px;" onclick="removeSku(${i})">Remove</button>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;margin-bottom:10px;">
        <div class="form-group" style="margin:0;"><label class="form-label">Colour</label><input type="text" class="form-control s-color" data-idx="${i}" value="${s.variantColor ?? ""}" placeholder="Black"></div>
        <div class="form-group" style="margin:0;"><label class="form-label">Size</label><input type="text" class="form-control s-size" data-idx="${i}" value="${s.variantSize ?? ""}" placeholder="M"></div>
        <div class="form-group" style="margin:0;"><label class="form-label">SKU code</label><input type="text" class="form-control s-sku" data-idx="${i}" value="${s.sku ?? ""}" placeholder="SP-SOCKS-BLK-M"></div>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
        <div class="form-group" style="margin:0;"><label class="form-label">Stock</label><input type="number" min="0" class="form-control s-stock" data-idx="${i}" value="${s.stockQuantity ?? 0}"></div>
        <div class="form-group" style="margin:0;"><label class="form-label">Reorder threshold</label><input type="number" min="0" class="form-control s-reorder" data-idx="${i}" value="${s.reorderThreshold ?? 0}"></div>
      </div>
    </div>
  `,
    )
    .join("");
}

function addSku() {
  skus.push({
    variantColor: "",
    variantSize: "",
    sku: "",
    stockQuantity: 0,
    reorderThreshold: 0,
  });
  renderSkus();
}
function removeSku(idx) {
  const row = skus[idx];
  if (row?.id) _deletedSkuIds.push(row.id);
  skus.splice(idx, 1);
  renderSkus();
}

document.getElementById("skuRows").addEventListener("input", (e) => {
  const idx = parseInt(e.target.dataset.idx);
  if (isNaN(idx) || !skus[idx]) return;
  if (e.target.classList.contains("s-color"))
    skus[idx].variantColor = e.target.value;
  if (e.target.classList.contains("s-size"))
    skus[idx].variantSize = e.target.value;
  if (e.target.classList.contains("s-sku")) skus[idx].sku = e.target.value;
  if (e.target.classList.contains("s-stock"))
    skus[idx].stockQuantity = parseInt(e.target.value) || 0;
  if (e.target.classList.contains("s-reorder"))
    skus[idx].reorderThreshold = parseInt(e.target.value) || 0;
});
renderSkus();

/**
 * Toggle the per-type field sections.
 * Studio-rental products share the same product form but surface different
 * sections:
 *  - PACKAGE / FREELANCE_PACKAGE → package settings
 *  - SINGLE_CLASS                → format selection + price only (no credits/validity)
 *  - FREELANCE_SINGLE            → single-class pricing only
 *  - MERCHANDISE                 → SKU/stock/variants
 */

