using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.API.Controllers;

[ApiController]
[Route("api/merchandise")]
[Authorize] // SKU lookups are admin OR receptionist (POS).
public class MerchandiseSkuController : ControllerBase
{
    private readonly IMerchandiseSkuService _skuService;

    public MerchandiseSkuController(IMerchandiseSkuService skuService)
    {
        _skuService = skuService;
    }

    /// <summary>All SKUs across all products. Admin merch list uses this for the reorder-pill roll-up.</summary>
    [HttpGet("skus")]
    public async Task<IActionResult> GetAll() =>
        Ok(await _skuService.GetAllAsync());

    /// <summary>SKUs for one product. POS variant picker reads this when a MERCHANDISE tile is clicked.</summary>
    [HttpGet("{productId}/skus")]
    public async Task<IActionResult> GetByProduct(string productId) =>
        Ok(await _skuService.GetByProductIdAsync(productId));

    [HttpGet("skus/{id}")]
    public async Task<IActionResult> GetById(string id)
    {
        var sku = await _skuService.GetByIdAsync(id);
        return sku is null ? NotFound() : Ok(sku);
    }

    [HttpPost("skus")]
    [Authorize(Roles = "Admin")]
    public async Task<IActionResult> Create([FromBody] MerchandiseSku sku)
    {
        try
        {
            var created = await _skuService.CreateAsync(sku);
            return Ok(created);
        }
        catch (ArgumentException ex)
        {
            return BadRequest(new { error = ex.Message });
        }
    }

    [HttpPut("skus/{id}")]
    [Authorize(Roles = "Admin")]
    public async Task<IActionResult> Update(string id, [FromBody] MerchandiseSku sku)
    {
        try
        {
            await _skuService.UpdateAsync(id, sku);
            return Ok();
        }
        catch (ArgumentException ex)
        {
            return BadRequest(new { error = ex.Message });
        }
    }

    [HttpDelete("skus/{id}")]
    [Authorize(Roles = "Admin")]
    public async Task<IActionResult> Delete(string id)
    {
        try
        {
            await _skuService.DeleteAsync(id);
            return Ok();
        }
        catch (InvalidOperationException ex)
        {
            return Conflict(new { error = ex.Message });
        }
    }
}

