/// <summary>
/// Give away stock without a sale — e.g. a free grip-sock pair rewarded for a
/// Google review. Deducts <paramref name="qty"/> (default 1) from the SKU's
/// shared stock and records an audit entry so giveaways stay traceable. No
/// invoice / client is involved (quick free hand-out). Returns 409 if the
/// variant is out of stock. Available to POS staff (Admin + Receptionist).
/// </summary>
[HttpPost("skus/{id}/giveaway")]
[Authorize(Roles = "Admin,Receptionist,Manager")]
public async Task<IActionResult> GiveAway(string id, [FromQuery] int qty = 1, [FromQuery] string? reason = null)
{
    if (qty <= 0) return BadRequest(new { error = "Quantity must be greater than zero." });

    var sku = await _skuService.GetByIdAsync(id);
    if (sku is null) return NotFound();

    var ok = await _skuService.TryDeductAsync(id, qty);
    if (!ok)
        return Conflict(new { error = $"Only {sku.StockQuantity} in stock for {sku.VariantColor}/{sku.VariantSize}." });

    var label = $"{sku.VariantColor}/{sku.VariantSize}".Trim('/');
    await _audit.LogAsync(
        action: "GIVEAWAY",
        entityType: "MerchandiseSku",
        entityId: id,
        entityLabel: label,
        after: new { qty, reason = reason ?? "Google review reward" });

    var fresh = await _skuService.GetByIdAsync(id);
    return Ok(new { stockQuantity = fresh?.StockQuantity ?? 0 });
}

