function closeVariantPicker() {
  document.getElementById("variantPickerOverlay").style.display = "none";
}

// ── Grip-sock configurator (single / multi-pack / review reward) ─────────
const SOCK_SWATCH = {
  Brown: "#8B5E3C", Pink: "#F4A6C0", Blue: "#3B82F6", White: "#F1F5F9",
  Black: "#1F2937", Grey: "#9CA3AF", Purple: "#8B5CF6", Green: "#22C55E",
};
let _sockCfg = null;

function _sockSku(color, size) {
  return _sockCfg.skus.find(
    (s) => s.variantColor === color && s.variantSize === size,
  );
}
function _sockStock(color, size) {
  const s = _sockSku(color, size);
  return s ? s.stockQuantity ?? 0 : 0;
}
// Units of a given color/size already claimed by OTHER pairs in this order.
function _sockClaimedElsewhere(color, size, exceptIdx) {
  return _sockCfg.selections.reduce(
    (n, sel, i) =>
      i !== exceptIdx && sel.color === color && sel.size === size ? n + 1 : n,
    0,
  );
}

function renderSockConfigurator(product, skus) {
  const sizes = [...new Set(skus.map((s) => s.variantSize).filter(Boolean))];
  const packOn = (product.packSize ?? 0) > 1 && (product.packPrice ?? 0) > 0;
  _sockCfg = {
    product,
    skus,
    sizes,
    colours: Object.keys(SOCK_SWATCH),
    type: "single",
    packOn,
    selections: [{ color: null, size: sizes[0] ?? "Small" }],
  };
  document.getElementById("variantPickerTitle").textContent = product.name;

  const tab = (key, label, show) =>
    show
      ? `<button class="sock-tab" data-type="${key}" onclick="sockCfgSetType('${key}')"
           style="flex:1;padding:9px 6px;border:1px solid var(--color-border-subtle);background:var(--color-surface-raised);color:var(--color-text-secondary);font-size:12.5px;font-weight:600;cursor:pointer;">${label}</button>`
      : "";

  document.getElementById("variantPickerList").innerHTML = `
    <div style="display:flex;border-radius:var(--radius-sm);overflow:hidden;margin-bottom:16px;">
      ${tab("single", "Single", true)}
      ${tab("pack", `${product.packSize}-Pack`, packOn)}
      ${tab("review", "Review reward", true)}
    </div>
    <div id="sockCfgBody"></div>
    <div id="sockCfgFooter" style="margin-top:16px;"></div>`;
  renderSockCfgBody();
}

function sockCfgSetType(type) {
  const need = type === "pack" ? _sockCfg.product.packSize : 1;
  // Resize selections, preserving what's already chosen.
  const cur = _sockCfg.selections;
  const next = [];
  for (let i = 0; i < need; i++)
    next.push(cur[i] ?? { color: null, size: _sockCfg.sizes[0] ?? "Small" });
  _sockCfg.type = type;
  _sockCfg.selections = next;
  renderSockCfgBody();
}
function sockCfgSetSize(idx, size) {
  const sel = _sockCfg.selections[idx];
  sel.size = size;
  // Drop the colour if it's no longer in stock at the new size.
  if (sel.color && _sockStock(sel.color, size) <= 0) sel.color = null;
  renderSockCfgBody();
}
function sockCfgSetColor(idx, color) {
  _sockCfg.selections[idx].color = color;
  renderSockCfgBody();
}

function renderSockCfgBody() {
  const { type, selections, sizes } = _sockCfg;
  const pairHtml = selections
    .map((sel, idx) => {
      const sizeBtns = sizes
        .map(
          (z) => `<button onclick="sockCfgSetSize(${idx},'${z}')"
            style="flex:1;padding:7px 6px;border:1px solid ${sel.size === z ? "var(--color-brand-accent)" : "var(--color-border-subtle)"};background:${sel.size === z ? "var(--color-brand-accent-soft)" : "var(--color-surface-raised)"};color:${sel.size === z ? "var(--color-brand-accent)" : "var(--color-text-secondary)"};border-radius:var(--radius-sm);font-size:12px;font-weight:600;cursor:pointer;">${z}</button>`,
        )
        .join("");
      const swatches = _sockCfg.colours
        .map((c) => {
          const stock = _sockStock(c, sel.size);
          const claimed = _sockClaimedElsewhere(c, sel.size, idx);
          const avail = stock - claimed;
          const oos = avail <= 0;
          const active = sel.color === c;
          return `<button title="${c}${oos ? " — out of stock" : " · " + avail + " left"}"
            ${oos ? "disabled" : `onclick="sockCfgSetColor(${idx},'${c}')"`}
            style="width:30px;height:30px;border-radius:50%;background:${SOCK_SWATCH[c]};cursor:${oos ? "not-allowed" : "pointer"};opacity:${oos ? 0.25 : 1};
            border:2px solid ${active ? "var(--color-brand-accent)" : "rgba(0,0,0,0.15)"};box-shadow:${active ? "0 0 0 2px var(--color-brand-accent-soft)" : "none"};position:relative;"></button>`;
        })
        .join("");
      const chosen = sel.color
        ? `${sel.color} · ${_sockStock(sel.color, sel.size) - _sockClaimedElsewhere(sel.color, sel.size, idx)} left`
        : `<span style="color:var(--color-danger);">Pick a colour</span>`;
      return `
      <div style="border:1px solid var(--color-border-subtle);border-radius:var(--radius-sm);padding:12px;margin-bottom:10px;">
        ${selections.length > 1 ? `<div style="font-size:11px;font-weight:700;color:var(--color-text-muted);margin-bottom:8px;">Pair ${idx + 1}</div>` : ""}
        <div style="display:flex;gap:8px;margin-bottom:10px;">${sizeBtns}</div>
        <div style="display:flex;flex-wrap:wrap;gap:8px;margin-bottom:6px;">${swatches}</div>
        <div style="font-size:11.5px;color:var(--color-text-muted);">${chosen}</div>
      </div>`;
    })
    .join("");
  document.getElementById("sockCfgBody").innerHTML = pairHtml;

  // Footer: price + confirm.
  const allChosen = selections.every((s) => s.color);
  let priceLabel, btnLabel;
  if (type === "single") {
    priceLabel = `${(_sockCfg.product.basePrice ?? 0).toLocaleString()} ₫`;
    btnLabel = "Add to cart";
  } else if (type === "pack") {
    priceLabel = `${(_sockCfg.product.packPrice ?? 0).toLocaleString()} ₫`;
    btnLabel = "Add pack to cart";
  } else {
    priceLabel = `<span style="color:var(--color-success);">Free</span>`;
    btnLabel = "Give away pair";
  }
  document.getElementById("sockCfgFooter").innerHTML = `
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">
      <span style="font-size:12px;color:var(--color-text-muted);">${type === "review" ? "Google review reward" : "Total"}</span>
      <span style="font-size:16px;font-weight:700;">${priceLabel}</span>
    </div>
    <button class="btn btn-primary" style="width:100%;font-weight:600;${allChosen ? "" : "opacity:0.5;pointer-events:none;"}"
      onclick="sockCfgConfirm()">${btnLabel}</button>`;
}

async function sockCfgConfirm() {
  const { type, selections, product } = _sockCfg;
  if (!selections.every((s) => s.color)) return;

  // Final stock guard (covers same-SKU duplicates across pairs).
  const need = {};
  for (const s of selections) {
    const sku = _sockSku(s.color, s.size);
    if (!sku) return;
    need[sku.id] = (need[sku.id] ?? 0) + 1;
  }
  for (const [skuId, qty] of Object.entries(need)) {
    const sku = _sockCfg.skus.find((x) => x.id === skuId);
    if ((sku?.stockQuantity ?? 0) < qty) {
      window.showToast &&
        window.showToast(
          `Only ${sku?.stockQuantity ?? 0} of ${sku?.variantColor}/${sku?.variantSize} in stock.`,
          "warning",
        );
      return;
    }
  }

  if (type === "review") {
    // Quick free hand-out — deduct stock directly, no invoice/client.
    const sel = selections[0];
    const sku = _sockSku(sel.color, sel.size);
    try {
      const r = await fetch(
        `${API}/api/merchandise/skus/${sku.id}/giveaway?reason=${encodeURIComponent("Google review reward")}`,
        { method: "POST", headers: { Authorization: "Bearer " + token } },
      );
      if (!r.ok) {
        const e = await r.json().catch(() => ({}));
        throw new Error(e.error || "Giveaway failed.");
      }
      window.showToast &&
        window.showToast(`Gave away ${sel.color}/${sel.size} pair (review reward).`, "success");
    } catch (e) {
      window.showToast && window.showToast(e.message || "Giveaway failed.", "error");
      return;
    }
    closeVariantPicker();
    return;
  }

  if (type === "single") {
    const sel = selections[0];
    addVariantToCart(product, _sockSku(sel.color, sel.size));
    closeVariantPicker();
    return;
  }

  // Pack: one priced "header" line at packPrice + the remaining pairs at 0,
  // each carrying its own variantId so every pair deducts the shared stock.
