mposRemoveLine(i) { this._mpos.lines.splice(i, 1); this._mposRenderCart(); },

async mposToggleAdd(kind) {
  const picker = document.getElementById('mposPicker');
  if (picker.style.display === 'block' && picker.dataset.kind === kind) { picker.style.display = 'none'; return; }
  picker.dataset.kind = kind; picker.style.display = 'block';
  picker.innerHTML = '<div style="font-size:11px;color:var(--color-text-muted);padding:6px;">Loading…</div>';
  if (!this._mpos.products) {
    try { this._mpos.products = await fetch(`${_CDP_API}/api/product`, { headers: { Authorization: 'Bearer ' + this._getToken() } }).then(r => r.json()); }
    catch { this._mpos.products = []; }
  }
  const want = kind === 'merch' ? 'MERCHANDISE' : 'PACKAGE';
  const list = (this._mpos.products || []).filter(p => p.type === want && p.isActive !== false && !p.hiddenFromPos);
  this._mpos._pickList = list;
  const esc = this._esc.bind(this);
  picker.innerHTML = list.length ? list.map((p, i) =>
    `<div style="display:flex;justify-content:space-between;align-items:center;padding:6px;cursor:pointer;border-radius:6px;" onmouseover="this.style.background='var(--color-surface-raised)'" onmouseout="this.style.background=''" onclick="ClassDetailPanel.mposAddProduct(${i})">
      <span style="font-size:12px;">${esc(p.name)}</span><span style="font-size:12px;color:var(--color-text-muted);">${this._mposFmt(p.basePrice)}</span></div>`
  ).join('') : `<div style="font-size:11px;color:var(--color-text-muted);padding:6px;">No ${kind} items available.</div>`;
},

mposAddProduct(idx) {
  const p = this._mpos._pickList[idx]; if (!p) return;
  const existing = this._mpos.lines.find(l => l.productId === p.id);
  if (existing) existing.qty += 1;
  else this._mpos.lines.push({ productId: p.id, name: p.name, unitPrice: p.basePrice || 0, qty: 1, type: p.type });
  document.getElementById('mposPicker').style.display = 'none';
  this._mposRenderCart();
},

async mposApplyPromo() {
  const code = (document.getElementById('mposPromo').value || '').trim().toUpperCase();
  const hint = document.getElementById('mposPromoHint');
  const m = this._mpos;
  if (!code) { m.promo = null; hint.textContent = ''; this.mposRecalc(); return; }
  const subtotal = (m.chargeDropIn ? m.dropInPrice : 0) + m.lines.reduce((s, l) => s + l.unitPrice * l.qty, 0);
  try {
    const r = await fetch(`${_CDP_API}/api/promotions/preview`, {
      method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + this._getToken() },
      body: JSON.stringify({ code, subtotalVnd: subtotal, productTypes: m.lines.map(l => l.type), clientId: m.clientId }),
    });
    const d = await r.json().catch(() => ({}));
    const disc = d.discountVnd ?? d.discount ?? 0;
    if (!r.ok || d.valid === false || disc <= 0) {
      m.promo = null; hint.style.color = 'var(--color-danger)'; hint.textContent = (d.message || d.reason || 'Invalid code');
    } else {
      m.promo = { code, discount: disc, promotionId: d.promotionId || d.id || null };
      hint.style.color = 'var(--color-success)'; hint.textContent = `−${this._mposFmt(disc)} applied`;
    }
  } catch { m.promo = null; hint.style.color = 'var(--color-danger)'; hint.textContent = 'Could not validate'; }
  this.mposRecalc();
},

_mposDiscount(base) {
  const dv = parseFloat(document.getElementById('mposDiscAmt').value) || 0;
  const dt = document.getElementById('mposDiscType').value;
  let disc = dt === 'PCT' ? base * dv / 100 : dv;
  if (this._mpos.promo) disc += this._mpos.promo.discount;
  return Math.min(base, Math.max(0, disc));
},

mposRecalc() {
  const m = this._mpos; if (!m) return;
  const classAmt = m.chargeDropIn ? m.dropInPrice : 0;
  const prodSub = m.lines.reduce((s, l) => s + l.unitPrice * l.qty, 0);
  const subtotal = classAmt + prodSub;
  const disc = this._mposDiscount(subtotal);
  const total = Math.max(0, subtotal - disc);
  m._prodSub = prodSub; m._classAmt = classAmt;
  document.getElementById('mposSubtotal').textContent = this._mposFmt(subtotal);
  const dl = document.getElementById('mposDiscLine');
  if (disc > 0) { dl.style.display = 'flex'; document.getElementById('mposDiscVal').textContent = '−' + this._mposFmt(disc); }
  else dl.style.display = 'none';
  document.getElementById('mposTotal').textContent = this._mposFmt(total);
  // Payment method is only relevant when money is actually owed. A pure
  // package-credit checkout (total 0) hides it.
  const payRow = document.getElementById('mposPayRow');
  if (payRow) payRow.style.display = total > 0 ? '' : 'none';
  const cbtn = document.getElementById('mposCompleteBtn');
  if (cbtn && !cbtn.disabled) cbtn.textContent = total > 0 ? '✅ Complete & check in' : '✅ Check in (credit)';
},

