async mposAddProduct(idx) {
  const p = this._mpos._pickList[idx]; if (!p) return;
  // Pack-enabled merchandise (grip socks) opens the size/colour configurator
  // with single / multi-pack / review-reward options, mirroring the main POS.
  if (p.type === 'MERCHANDISE' && (p.packSize ?? 0) > 0) {
    await this.mposOpenSock(p);
    return;
  }
  const existing = this._mpos.lines.find(l => l.productId === p.id && !l.variantId);
  if (existing) existing.qty += 1;
  else this._mpos.lines.push({ productId: p.id, name: p.name, unitPrice: p.basePrice || 0, qty: 1, type: p.type });
  document.getElementById('mposPicker').style.display = 'none';
  this._mposRenderCart();
},

/* ── Grip-sock configurator (calendar checkout) ── */
_sockSku(color, size) {
  return this._mposSock.skus.find(s => s.variantColor === color && s.variantSize === size);
},
_sockStock(color, size) { const s = this._sockSku(color, size); return s ? (s.stockQuantity ?? 0) : 0; },
_sockClaimedElsewhere(color, size, exceptIdx) {
  return this._mposSock.selections.reduce((n, sel, i) =>
    (i !== exceptIdx && sel.color === color && sel.size === size) ? n + 1 : n, 0);
},

async mposOpenSock(product) {
  const picker = document.getElementById('mposPicker');
  picker.style.display = 'block';
  picker.style.maxHeight = 'none';
  picker.innerHTML = '<div style="font-size:11px;color:var(--color-text-muted);padding:6px;">Loading…</div>';
  let skus = [];
  try { skus = await fetch(`${_CDP_API}/api/merchandise/${product.id}/skus`, { headers: { Authorization: 'Bearer ' + this._getToken() } }).then(r => r.json()); }
  catch { skus = []; }
  if (!skus.length) { picker.innerHTML = '<div style="font-size:11px;color:var(--color-danger);padding:6px;">No variants configured.</div>'; return; }
  const sizes = [...new Set(skus.map(s => s.variantSize).filter(Boolean))];
  this._mposSock = {
    product, skus, sizes,
    colours: Object.keys(_CDP_SOCK_SWATCH),
    packOn: (product.packSize ?? 0) > 1 && (product.packPrice ?? 0) > 0,
    type: 'single',
    selections: [{ color: null, size: sizes[0] ?? 'Small' }],
  };
  this._mposRenderSock();
},

mposSockSetType(type) {
  const need = type === 'pack' ? this._mposSock.product.packSize : 1;
  const cur = this._mposSock.selections;
  const next = [];
  for (let i = 0; i < need; i++) next.push(cur[i] ?? { color: null, size: this._mposSock.sizes[0] ?? 'Small' });
  this._mposSock.type = type; this._mposSock.selections = next;
  this._mposRenderSock();
},
mposSockSetSize(idx, size) {
  const sel = this._mposSock.selections[idx]; sel.size = size;
  if (sel.color && this._sockStock(sel.color, size) <= 0) sel.color = null;
  this._mposRenderSock();
},
mposSockSetColor(idx, color) { this._mposSock.selections[idx].color = color; this._mposRenderSock(); },

_mposRenderSock() {
  const s = this._mposSock;
  const p = s.product;
  const tab = (key, label, show) => show
    ? `<button onclick="ClassDetailPanel.mposSockSetType('${key}')" style="flex:1;padding:7px 4px;border:1px solid ${s.type === key ? 'var(--color-brand-accent)' : 'var(--color-border-subtle)'};background:${s.type === key ? 'var(--color-brand-accent-soft)' : 'var(--color-surface-raised)'};color:${s.type === key ? 'var(--color-brand-accent)' : 'var(--color-text-secondary)'};font-size:11.5px;font-weight:600;cursor:pointer;">${label}</button>`
    : '';
  const pairs = s.selections.map((sel, idx) => {
    const sizeBtns = s.sizes.map(z =>
      `<button onclick="ClassDetailPanel.mposSockSetSize(${idx},'${z}')" style="flex:1;padding:6px;border:1px solid ${sel.size === z ? 'var(--color-brand-accent)' : 'var(--color-border-subtle)'};background:${sel.size === z ? 'var(--color-brand-accent-soft)' : 'var(--color-surface-raised)'};color:${sel.size === z ? 'var(--color-brand-accent)' : 'var(--color-text-secondary)'};border-radius:8px;font-size:11.5px;font-weight:600;cursor:pointer;">${z}</button>`
    ).join('');
    const swatches = s.colours.map(c => {
      const avail = this._sockStock(c, sel.size) - this._sockClaimedElsewhere(c, sel.size, idx);
      const oos = avail <= 0; const active = sel.color === c;
      return `<button title="${c}${oos ? ' — out of stock' : ' · ' + avail + ' left'}" ${oos ? 'disabled' : `onclick="ClassDetailPanel.mposSockSetColor(${idx},'${c}')"`} style="width:26px;height:26px;border-radius:50%;background:${_CDP_SOCK_SWATCH[c]};cursor:${oos ? 'not-allowed' : 'pointer'};opacity:${oos ? 0.25 : 1};border:2px solid ${active ? 'var(--color-brand-accent)' : 'rgba(0,0,0,0.15)'};"></button>`;
    }).join('');
    const chosen = sel.color ? `${sel.color} · ${this._sockStock(sel.color, sel.size) - this._sockClaimedElsewhere(sel.color, sel.size, idx)} left` : '<span style="color:var(--color-danger);">Pick a colour</span>';
    return `<div style="border:1px solid var(--color-border-subtle);border-radius:8px;padding:10px;margin-bottom:8px;">
      ${s.selections.length > 1 ? `<div style="font-size:10px;font-weight:700;color:var(--color-text-muted);margin-bottom:6px;">Pair ${idx + 1}</div>` : ''}
      <div style="display:flex;gap:6px;margin-bottom:8px;">${sizeBtns}</div>
      <div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:5px;">${swatches}</div>
      <div style="font-size:11px;color:var(--color-text-muted);">${chosen}</div></div>`;
  }).join('');
  const allChosen = s.selections.every(x => x.color);
  let priceLabel, btnLabel;
  if (s.type === 'single') { priceLabel = this._mposFmt(p.basePrice || 0); btnLabel = 'Add to cart'; }
  else if (s.type === 'pack') { priceLabel = this._mposFmt(p.packPrice || 0); btnLabel = 'Add pack'; }
  else { priceLabel = 'Free'; btnLabel = 'Give away pair'; }
  document.getElementById('mposPicker').innerHTML = `
    <div style="display:flex;gap:4px;margin-bottom:12px;">${tab('single', 'Single', true)}${tab('pack', `${p.packSize}-Pack`, s.packOn)}${tab('review', 'Review', true)}</div>
    ${pairs}
    <div style="display:flex;justify-content:space-between;align-items:center;margin:10px 0;">
      <span style="font-size:11px;color:var(--color-text-muted);">${s.type === 'review' ? 'Review reward' : 'Total'}</span>
      <span style="font-size:14px;font-weight:700;">${priceLabel}</span></div>
    <button class="btn btn-primary btn-sm" style="width:100%;font-weight:600;${allChosen ? '' : 'opacity:0.5;pointer-events:none;'}" onclick="ClassDetailPanel.mposSockConfirm()">${btnLabel}</button>`;
},

async mposSockConfirm() {
  const s = this._mposSock; const p = s.product;
  if (!s.selections.every(x => x.color)) return;
  const need = {};
  for (const sel of s.selections) { const sku = this._sockSku(sel.color, sel.size); if (!sku) return; need[sku.id] = (need[sku.id] ?? 0) + 1; }
  for (const [skuId, qty] of Object.entries(need)) {
    const sku = s.skus.find(x => x.id === skuId);
    if ((sku?.stockQuantity ?? 0) < qty) { window.showToast?.(`Only ${sku?.stockQuantity ?? 0} of ${sku?.variantColor}/${sku?.variantSize} in stock.`, 'warning'); return; }
  }

  if (s.type === 'review') {
    const sel = s.selections[0]; const sku = this._sockSku(sel.color, sel.size);
    try {
      const r = await fetch(`${_CDP_API}/api/merchandise/skus/${sku.id}/giveaway?reason=${encodeURIComponent('Google review reward')}`, { method: 'POST', headers: { Authorization: 'Bearer ' + this._getToken() } });
      if (!r.ok) { const e = await r.json().catch(() => ({})); throw new Error(e.error || 'Giveaway failed.'); }
      window.showToast?.(`Gave away ${sel.color}/${sel.size} pair (review reward).`, 'success');
    } catch (e) { window.showToast?.(e.message || 'Giveaway failed.', 'error'); return; }
    document.getElementById('mposPicker').style.display = 'none';
    return;
  }

  if (s.type === 'single') {
    const sel = s.selections[0]; const sku = this._sockSku(sel.color, sel.size);
    const label = `${sel.color}/${sel.size}`;
    const existing = this._mpos.lines.find(l => l.variantId === sku.id);
    if (existing) existing.qty += 1;
    else this._mpos.lines.push({ productId: p.id, variantId: sku.id, variantLabel: label, name: `${p.name} · ${label}`, unitPrice: p.basePrice || 0, qty: 1, type: p.type });
  } else {
    // Pack: header line at packPrice + remaining pairs at 0, each with its variantId.
    s.selections.forEach((sel, i) => {
      const sku = this._sockSku(sel.color, sel.size); const label = `${sel.color}/${sel.size}`;
      this._mpos.lines.push({ productId: p.id, variantId: sku.id, variantLabel: label, name: i === 0 ? `${p.name} (${p.packSize}-Pack) · ${label}` : `↳ ${label}`, unitPrice: i === 0 ? (p.packPrice || 0) : 0, qty: 1, type: p.type });
    });
  }
  document.getElementById('mposPicker').style.display = 'none';
  this._mposRenderCart();
},

