      if (!r.ok) { const e = await r.json().catch(() => ({})); throw new Error(e.error || 'Giveaway failed.'); }
      window.showToast?.(`Gave away ${sel.color}/${sel.size} pair (review reward).`, 'success');
    } catch (e) { window.showToast?.(e.message || 'Giveaway failed.', 'error'); return; }
