namespace SoulPilates.Core.Interfaces;

/// <summary>
/// Server-side TikTok Events API sender. Mirrors the browser TikTok Pixel:
/// the client fires <c>ttq.track(...)</c> with an <c>event_id</c>, and this
/// service posts the SAME event (same <c>event_id</c>) straight to TikTok's
/// Events API so the two are de-duplicated. Because the call leaves our own
/// server it survives ad-blockers / iOS / cookie loss that would drop the
/// browser Pixel — the key to good ad optimisation. Same design as
/// <see cref="IMetaConversionsService"/>.
/// </summary>
public interface ITiktokEventsService
{
    /// <summary>True when the server-side Events API can send — needs Pixel code + access token + master switch.</summary>
    bool IsEnabled { get; }

    /// <summary>True when the browser Pixel should load — needs only the Pixel code + master switch (no token).</summary>
    bool BrowserEnabled { get; }

    /// <summary>The public Pixel code (safe to expose to the browser). Empty when unset.</summary>
    string PixelCode { get; }

    /// <summary>
    /// Send one event to TikTok. Raw email/phone are hashed (SHA-256) before
    /// leaving the process; never pass already-hashed values. Fire-and-forget
    /// safe — swallows/logs failures so a tracking hiccup never breaks a booking.
    /// </summary>
    Task SendEventAsync(TiktokConversionEvent evt, CancellationToken ct = default);
}

/// <summary>Input for a single TikTok Events API event.</summary>
public class TiktokConversionEvent
{
    /// <summary>TikTok standard event name (e.g. CompletePayment, ViewContent, InitiateCheckout, CompleteRegistration, Pageview).</summary>
    public string EventName { get; set; } = "";
    public string EventId { get; set; } = "";
    public string? EventSourceUrl { get; set; }

    // Raw (un-hashed) customer identifiers — improve match quality. Optional.
    public string? Email { get; set; }
    public string? Phone { get; set; }

    // TikTok browser cookies/click id, forwarded from the client for attribution.
    public string? Ttp { get; set; }
    public string? Ttclid { get; set; }

    // Request context, captured server-side.
    public string? ClientIpAddress { get; set; }
    public string? ClientUserAgent { get; set; }

    // Custom data.
    public decimal? Value { get; set; }
    public string? Currency { get; set; }
    public string? ContentName { get; set; }
    public string? ContentCategory { get; set; }
    public List<string>? ContentIds { get; set; }
}

