1373	  function buildEventCard(s) {
1374	    const ev = document.createElement('div');
1375	    const st = new Date(s.startTime);
1376	    const et = new Date(s.endTime);
1377	
1378	    if (s.status === 'BLOCKED') {
1379	      ev.className = 'ev blocked';
1380	      // SPM-70 — distinguish a standalone block (origin === 'BLOCK', deletable)
1381	      // from a REAL class that was blocked (origin !== 'BLOCK', revertable).
1382	      const isStandaloneBlock = s.origin === 'BLOCK';
1383	      let scopeHtml = '';
1384	      if (s.blockScope === 'FORMAT' && s.blockScopeValue)
1385	        scopeHtml = `<span class="ev-block-scope" style="background:var(--color-brand-accent);color:#fff;">${s.blockScopeValue}</span>`;
1386	      else if (s.blockScope === 'DIFFICULTY' && s.blockScopeValue)
1387	        scopeHtml = `<span class="ev-block-scope" style="background:var(--color-warning);color:#000;">${s.blockScopeValue}</span>`;
1388	      const headline = isStandaloneBlock ? (s.blockedReason || 'Blocked') : (s.className || 'Class');
1389	      const hint = isStandaloneBlock ? 'Click to remove' : 'Blocked · click to unblock';
1390	      ev.innerHTML = `<div class="ev-block-icon">🔒</div>
1391	        <div class="ev-block-label">${isStandaloneBlock ? 'Studio Blocked' : 'Class Blocked'}</div>
1392	        <div class="ev-block-reason">${esc(headline)}</div>${scopeHtml}
1393	        <div class="ev-block-unblock" style="font-size:9px;margin-top:4px;opacity:0.7;">${hint}</div>`;
1394	      if (myRole === 'ADMIN' || myRole === 'MANAGER' || myRole === 'OWNER' || myRole === 'RECEPTIONIST') {
1395	        ev.style.cursor = 'pointer';
1396	        if (isStandaloneBlock)
1397	          ev.addEventListener('click', e => { e.stopPropagation(); showUnblockPopover(e, s); });
1398	        else
1399	          // A blocked REAL class must NOT be deleted — offer revert instead.
1400	          ev.addEventListener('click', e => { e.stopPropagation(); showClassBlockPopover(e, s, false); });
1401	      }
1402	      return ev;
1403	    }
