function slotAction(action) {
  const d = popoverDate; hideSlotPopover(); if (!d) return;
  const iso = isoLocal(d);
  if (action === 'session') { document.getElementById('sStart').value = iso; openNewSession(); }
  else if (action === 'block') {
    document.getElementById('bStart').value = iso;
    document.getElementById('bDuration').value = '60';
