private static string MapStaffRoleToUserRole(string? staffRole)
{
    return (staffRole ?? string.Empty).Trim().ToUpperInvariant() switch
    {
        "RECEPTIONIST" => "Receptionist",
        "INSTRUCTOR" => "Instructor",
        "MANAGER" => "Manager",
        "OWNER" => "Owner",
        "ACCOUNTANT" => "Accountant",
        "SUPERADMIN" => "SuperAdmin",
        "FREELANCE" => "Freelance",
        _ => "Instructor",
    };
}

public async Task<List<MonthlyCommissionOverride>> ListCommissionOverridesAsync(
    string staffId, CancellationToken ct = default)
{
    return await _commissionOverrides
        .Find(o => o.StaffId == staffId)
        .SortByDescending(o => o.Year)
        .ThenByDescending(o => o.Month)
        .ToListAsync(ct);
}

public async Task<MonthlyCommissionOverride> UpsertCommissionOverrideAsync(
    MonthlyCommissionOverride payload, CancellationToken ct = default)
{
    if (payload.Month < 1 || payload.Month > 12)
        throw new InvalidOperationException("Month must be between 1 and 12.");

