    var res = await fetch(apiBase + '/api/management-access', {
      headers: { Authorization: 'Bearer ' + (localStorage.getItem('token') || '') }
    });
    if (!res.ok) throw new Error('role access unavailable');

    var data = await res.json();
    var roleEnabled = data && data.roleEnabled !== false;
    var enabledModules = Array.isArray(data && data.enabledModuleKeys)
      ? data.enabledModuleKeys.map(function(moduleKey) { return String(moduleKey || '').toLowerCase(); })
      : [];
    var allowedSet = new Set(enabledModules);

    // Instructors with zero granted admin pages belong in their own portal.
    if (window.__isInstructor && enabledModules.length === 0) {
      window.location.href = '/instructor';
      return;
    }

    document.querySelectorAll('[data-module]').forEach(function(el) {
      var moduleKeys = parseModuleList(el.getAttribute('data-module'));
      var visible = roleEnabled && hasAnyAllowed(moduleKeys, allowedSet);
      el.style.display = visible ? '' : 'none';
    });

    applySidebarSectionVisibility();

    if (!roleEnabled || !hasAnyAllowed(parseModuleList(activeModuleRaw), allowedSet)) {
      var fallbackHref = findFirstVisibleManagementLink();
      if (fallbackHref && fallbackHref !== window.location.pathname) {
        window.location.replace(fallbackHref);
        return;
      }
      showManagementAccessDenied();
    }
  } catch (e) {
    // If we can't resolve access, an instructor has no safe admin surface to
