    /* ── Global Chart.js premium theme (visual only) ─────────────────────
       Pages load chart.js from CDN and build their own charts. We intercept
       the moment `window.Chart` is assigned and set library-wide DEFAULTS —
       typography, tooltips, grid, smooth curves — so every chart on every
       page shares the premium look without touching any page's chart code,
       datasets, or options (page-level options still win where set). */
    (function () {
      function themeChart(C) {
        try {
          var css = getComputedStyle(document.documentElement);
          var muted = (css.getPropertyValue('--color-text-muted') || '#8C8379').trim();
          var grid = 'rgba(140,131,121,0.14)';
          C.defaults.font.family = "'Inter', -apple-system, sans-serif";
          C.defaults.font.size = 11;
          C.defaults.color = muted;
          C.defaults.borderColor = grid;
          C.defaults.plugins.legend.labels.usePointStyle = true;
          C.defaults.plugins.legend.labels.pointStyle = 'circle';
          C.defaults.plugins.legend.labels.boxWidth = 7;
          C.defaults.plugins.legend.labels.boxHeight = 7;
          C.defaults.plugins.legend.labels.padding = 14;
          C.defaults.plugins.tooltip.backgroundColor = 'rgba(17,19,26,0.94)';
          C.defaults.plugins.tooltip.titleColor = '#F4F6FA';
          C.defaults.plugins.tooltip.bodyColor = '#B4BAC6';
          C.defaults.plugins.tooltip.borderColor = 'rgba(249,115,22,0.35)';
          C.defaults.plugins.tooltip.borderWidth = 1;
          C.defaults.plugins.tooltip.cornerRadius = 10;
          C.defaults.plugins.tooltip.padding = 10;
          C.defaults.plugins.tooltip.displayColors = true;
          C.defaults.plugins.tooltip.boxPadding = 4;
          C.defaults.elements.line.tension = 0.4;
          C.defaults.elements.line.borderWidth = 2.5;
          C.defaults.elements.point.radius = 0;
          C.defaults.elements.point.hoverRadius = 5;
          C.defaults.elements.point.hoverBorderWidth = 2;
          C.defaults.elements.bar.borderRadius = 6;
          C.defaults.elements.arc.borderWidth = 0;
          C.defaults.animation.duration = 650;
          C.defaults.animation.easing = 'easeOutQuart';
          if (C.defaults.scales && C.defaults.scales.category) {}
          C.defaults.scale = C.defaults.scale || {};
        } catch (e) { /* theming is best-effort */ }
      }
      var existing = window.Chart;
      if (existing) { themeChart(existing); return; }
      Object.defineProperty(window, 'Chart', {
        configurable: true,
        set: function (v) {
          Object.defineProperty(window, 'Chart', { value: v, writable: true, configurable: true });
