openEditModal() {
  if (!this._sessionDetail) { window.showToast?.('No session selected', 'error'); return; }
  const c = this._sessionDetail;
  const modal = document.getElementById('cdpEditModal');
  if (!modal) return;
  (document.getElementById('cdpEsClassName')).value = c.className || '';
  (document.getElementById('cdpEsStartTime')).value = this._isoLocal(new Date(c.startTime));
  const dur = Math.round((new Date(c.endTime) - new Date(c.startTime)) / 60000);
  (document.getElementById('cdpEsDuration')).value = String(dur || 60);
  (document.getElementById('cdpEsCapacity')).value = String(c.capacity || 10);
  (document.getElementById('cdpEsDifficulty')).value = c.difficultyLevel || 'ALL_LEVELS';
  (document.getElementById('cdpEsFocusArea')).value = c.focusArea || '';
  (document.getElementById('cdpEsNote')).value = '';
  const sel = document.getElementById('cdpEsInstructorId');
  const staffList = this._getStaffList();
  sel.innerHTML = '<option value="">Select instructor...</option>' +
    staffList.filter(s => s.isActive !== false).map(s =>
      `<option value="${s.id}" ${s.id === c.instructorId ? 'selected' : ''}>${this._esc(s.name)}${s.role ? ` (${s.role})` : ''}</option>`
    ).join('');
  const statusSel = document.getElementById('cdpEsStatus');
  if (statusSel) statusSel.value = c.status || '';
  const pubChk = document.getElementById('cdpEsIsPublic');
  // Default to public (checked) when the field is missing on legacy sessions.
  if (pubChk) pubChk.checked = c.isPublic !== false;
  modal.classList.add('open');
},

closeEditModal() {
  document.getElementById('cdpEditModal')?.classList.remove('open');
},

async saveEdit() {
  if (!this._sessionDetail) return;
  const sid = this._sessionDetail.id;
  const start = new Date((document.getElementById('cdpEsStartTime')).value);
  const end = new Date(start);
  end.setMinutes(end.getMinutes() + parseInt((document.getElementById('cdpEsDuration')).value));
  const instSel = document.getElementById('cdpEsInstructorId');
  const instName = instSel.options[instSel.selectedIndex]?.text?.split(' (')[0] || '';
  const body = {
    className: (document.getElementById('cdpEsClassName')).value.trim(),
    instructorId: instSel.value || null, // SPM-122 — send null, not '', for "no instructor"
    instructorName: instName,
    startTime: start.toISOString(),
    endTime: end.toISOString(),
    capacity: parseInt((document.getElementById('cdpEsCapacity')).value),
    difficultyLevel: (document.getElementById('cdpEsDifficulty')).value,
    focusArea: (document.getElementById('cdpEsFocusArea')).value.trim(),
    note: (document.getElementById('cdpEsNote')).value.trim() || null,
    status: (document.getElementById('cdpEsStatus'))?.value || null,
    isPublic: (document.getElementById('cdpEsIsPublic'))?.checked ?? true,
  };
  try {
    const r = await fetch(`${_CDP_API}/api/scheduling/session/${sid}/override`, {
      method: 'PATCH',
      headers: { Authorization: 'Bearer ' + this._getToken(), 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    if (!r.ok) { const err = await r.text(); throw new Error(err); }
    window.showToast?.('Session updated', 'success');
    this.closeEditModal();
    if (this._afterSessionEdit) await this._afterSessionEdit(sid);
    else this.refresh();
  } catch (err) {
    window.showToast?.(`Failed to update session: ${err.message}`, 'error');
  }
},

