/* ── Quick session actions (status + reassign, no modal) ────── */
// Build the full override body from the current session, applying overrides.
// The /override endpoint expects the whole set of editable fields, so we echo
// the current values and change only what the quick action touched.
_buildOverrideBody(overrides) {
  const c = this._sessionDetail;
  return Object.assign({
    className: c.className || '',
    instructorId: c.instructorId || null,
    instructorName: c.instructorName || '',
    startTime: new Date(c.startTime).toISOString(),
    endTime: new Date(c.endTime).toISOString(),
    capacity: c.capacity || 10,
    difficultyLevel: c.difficultyLevel || 'ALL_LEVELS',
    focusArea: c.focusArea || '',
    note: null,
    status: c.status || null,
    isPublic: c.isPublic !== false,
  }, overrides || {});
},

async _patchSession(overrides, successMsg) {
  if (!this._sessionDetail) return;
  const sid = this._sessionDetail.id;
  try {
    const r = await fetch(`${_CDP_API}/api/scheduling/session/${sid}/override`, {
      method: 'PATCH',
      headers: { Authorization: 'Bearer ' + this._getToken(), 'Content-Type': 'application/json' },
      body: JSON.stringify(this._buildOverrideBody(overrides)),
    });
    if (!r.ok) { const err = await r.text(); throw new Error(err); }
    window.showToast?.(successMsg, 'success');
    if (this._afterSessionEdit) await this._afterSessionEdit(sid);
    else this.refresh();
  } catch (err) {
    window.showToast?.(`Update failed: ${err.message}`, 'error');
    this.refresh();
  }
},

quickSetStatus(newStatus) {
  if (!this._sessionDetail || newStatus === this._sessionDetail.status) return;
  const label = { COMPLETED: 'Marked completed', NO_SHOW: 'Marked no-show', CANCELLED: 'Cancelled', SCHEDULED: 'Set to upcoming' }[newStatus] || 'Status updated';
  this._patchSession({ status: newStatus }, label);
},

startReassign() {
  const row = document.getElementById('cdpInstructorRow');
  if (!row || !this._sessionDetail) return;
  const c = this._sessionDetail;
  const staffList = this._getStaffList().filter(s => s.isActive !== false);
  const opts = '<option value="">— No instructor —</option>' + staffList.map(s =>
    `<option value="${s.id}" ${s.id === c.instructorId ? 'selected' : ''}>${this._esc(s.name)}</option>`).join('');
  row.innerHTML = `<span class="dp-icon">👤</span>
    <select class="dp-inst-select" id="cdpReassignSelect">${opts}</select>
    <button class="dp-inst-save" onclick="ClassDetailPanel.commitReassign()">Save</button>
    <button class="dp-inst-cancel" onclick="ClassDetailPanel.refresh()">Cancel</button>`;
},

commitReassign() {
  const sel = document.getElementById('cdpReassignSelect');
  if (!sel) return;
  const newId = sel.value || null;
  const newName = newId ? (sel.options[sel.selectedIndex]?.text || '') : '';
  if (newId === (this._sessionDetail?.instructorId || null)) { this.refresh(); return; }
  this._patchSession({ instructorId: newId, instructorName: newName }, 'Instructor reassigned');
},

