using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using SoulPilates.Core.DTOs;

namespace SoulPilates.Core.Interfaces;

/// <summary>
/// First-party web-analytics: writes visitor/funnel events from the public
/// tracking beacon and reads them back as dashboard aggregations. Unlike
/// <see cref="IAnalyticsService"/> this service DOES write (the beacon), but
/// every read method remains side-effect-free.
/// </summary>
public interface IVisitorAnalyticsService
{
    /// <summary>Persist one beacon event. Resolves country + referrer source + new/returning server-side.</summary>
    Task TrackAsync(TrackEventRequest req, string? ipAddress, string? userAgent, CancellationToken ct = default);

    /// <summary>Count of distinct sessions seen in the last <paramref name="windowMinutes"/> minutes.</summary>
    Task<int> GetLiveVisitorCountAsync(int windowMinutes = 5, CancellationToken ct = default);

    /// <summary>Headline visitor stats + country/referrer breakdowns over [startUtc, endUtc).</summary>
    Task<VisitorSummaryDto> GetVisitorSummaryAsync(DateTime startUtc, DateTime endUtc, CancellationToken ct = default);

    /// <summary>Booking-funnel stage counts with drop-off over [startUtc, endUtc).</summary>
    Task<List<FunnelStepRow>> GetBookingFunnelAsync(DateTime startUtc, DateTime endUtc, CancellationToken ct = default);

    /// <summary>
    /// Self-reported "How did you hear about us?" distribution from customer
    /// onboarding, over customers created in [startUtc, endUtc).
    /// </summary>
    Task<List<VisitorBreakdownRow>> GetSignupSourcesAsync(DateTime startUtc, DateTime endUtc, CancellationToken ct = default);
}

