13	namespace SoulPilates.Services;
14	
15	/// <summary>
16	/// First-party web-analytics store + aggregations. See
17	/// <see cref="IVisitorAnalyticsService"/>. Writes come only from the public
18	/// tracking beacon; reads power the admin Visitors dashboard.
19	/// </summary>
20	public class VisitorAnalyticsService : IVisitorAnalyticsService
21	{
22	    private readonly IMongoCollection<VisitorEvent> _events;
23	    private readonly IMongoCollection<CustomerAccount> _accounts;
24	    private readonly IGeoIpResolver _geo;
25	
26	    public VisitorAnalyticsService(MongoDbContext dbContext, IGeoIpResolver geo)
27	    {
28	        _events = dbContext.GetCollection<VisitorEvent>("VisitorEvents");
29	        _accounts = dbContext.GetCollection<CustomerAccount>("CustomerAccounts");
30	        _geo = geo;
31	    }
32	
33	    public async Task TrackAsync(TrackEventRequest req, string? ipAddress, string? userAgent, CancellationToken ct = default)
34	    {
35	        if (string.IsNullOrWhiteSpace(req.VisitorId) || string.IsNullOrWhiteSpace(req.SessionId))
36	            return; // malformed beacon — ignore silently
37	
38	        // New vs returning: has this VisitorId ever been seen before now?
39	        var seenBefore = await _events
40	            .Find(e => e.VisitorId == req.VisitorId)
41	            .Limit(1)
42	            .AnyAsync(ct);
43	
44	        var geo = await _geo.ResolveAsync(ipAddress, ct);
45	
46	        BookingFunnelStep? step = null;
47	        if (req.Type == "funnel_step" &&
48	            Enum.TryParse<BookingFunnelStep>(req.FunnelStep, ignoreCase: true, out var parsed))
49	        {
50	            step = parsed;
51	        }
52	
53	        var occurredAt = req.OccurredAtMs.HasValue
54	            ? DateTimeOffset.FromUnixTimeMilliseconds(req.OccurredAtMs.Value).UtcDateTime
55	            : DateTime.UtcNow;
56	
57	        var evt = new VisitorEvent
58	        {
59	            Type = req.Type == "funnel_step" ? "funnel_step" : "pageview",
60	            VisitorId = req.VisitorId,
61	            SessionId = req.SessionId,
62	            Path = Trim(req.Path, 300),
63	            Referrer = Trim(req.Referrer, 500),
64	            ReferrerSource = ClassifyReferrer(req.Referrer, req.Path),
65	            Country = geo.Country,
66	            CountryCode = geo.CountryCode,
67	            IpAddress = ipAddress,
68	            UserAgent = Trim(userAgent, 500),
69	            IsNewVisitor = !seenBefore,
70	            FunnelStep = step,
71	            OccurredAt = occurredAt,
72	        };
73	
74	        await _events.InsertOneAsync(evt, cancellationToken: ct);
75	    }
76	
77	    public async Task<int> GetLiveVisitorCountAsync(int windowMinutes = 5, CancellationToken ct = default)
78	    {
79	        var since = DateTime.UtcNow.AddMinutes(-Math.Abs(windowMinutes));
80	        var recent = await _events
81	            .Distinct<string>("SessionId",
82	                Builders<VisitorEvent>.Filter.Gte(e => e.OccurredAt, since), cancellationToken: ct)
83	            .ToListAsync(ct);
84	        return recent.Count;
85	    }
86	
87	    public async Task<VisitorSummaryDto> GetVisitorSummaryAsync(DateTime startUtc, DateTime endUtc, CancellationToken ct = default)
88	    {
89	        var inRange = Builders<VisitorEvent>.Filter.And(
90	            Builders<VisitorEvent>.Filter.Gte(e => e.OccurredAt, startUtc),
91	            Builders<VisitorEvent>.Filter.Lt(e => e.OccurredAt, endUtc),
92	            Builders<VisitorEvent>.Filter.Eq(e => e.Type, "pageview"));
93	
94	        var events = await _events.Find(inRange).ToListAsync(ct);
95	
96	        var byVisitor = events
97	            .GroupBy(e => e.VisitorId)
98	            .ToList();
99	
100	        var total = byVisitor.Count;
101	        // A visitor counts as "new" when their first-ever pageview in range was
102	        // flagged new at capture time (no earlier events existed).
103	        var newCount = byVisitor.Count(g => g.Any(e => e.IsNewVisitor));
104	        var returning = total - newCount;
105	
106	        var countries = BuildBreakdown(
107	            events.Select(e => (Label: string.IsNullOrWhiteSpace(e.Country) ? "Unknown" : e.Country!, e.VisitorId)),
108	            total);
109	        var referrers = BuildBreakdown(
110	            events.Select(e => (Label: string.IsNullOrWhiteSpace(e.ReferrerSource) ? "direct" : e.ReferrerSource!, e.VisitorId)),
111	            total);
112	
113	        return new VisitorSummaryDto
114	        {
115	            TotalVisitors = total,
116	            NewVisitors = newCount,
117	            ReturningVisitors = returning,
118	            TotalPageviews = events.Count,
119	            Countries = countries,
120	            Referrers = referrers,
121	        };
122	    }
123	
