using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.API.Controllers;

/// <summary>
/// Booking-page promotional offers. Public GET feeds the /booking popup;
/// the admin PUT (Settings → Offers) saves the toggleable set.
/// </summary>
[ApiController]
[Route("api/offers")]
public class OffersController : ControllerBase
{
    private readonly ISettingsService _settings;

    public OffersController(ISettingsService settings) => _settings = settings;

    /// <summary>Public — the enabled offers to show in the booking popup (empty when the popup is off).</summary>
    [HttpGet]
    [AllowAnonymous]
    public async Task<IActionResult> GetPublic()
    {
        var s = await _settings.GetAsync();
        if (!s.OffersPopupEnabled)
            return Ok(new { popupEnabled = false, offers = System.Array.Empty<object>() });

        var offers = (s.Offers ?? new())
            .Where(o => o.Enabled)
            .OrderBy(o => o.DisplayOrder)
            .Select(o => new
            {
                id = o.Id,
                type = o.Type,
                promoCode = o.PromoCode,
                firstTimeOnly = o.FirstTimeOnly,
                imageUrl = o.ImageUrl,
                badgeEn = o.BadgeEn, badgeVi = o.BadgeVi,
                headlineEn = o.HeadlineEn, headlineVi = o.HeadlineVi,
                subEn = o.SubEn, subVi = o.SubVi,
            });

        return Ok(new { popupEnabled = true, offers });
    }

    /// <summary>Admin — full offers list incl. disabled, for the Settings → Offers editor.</summary>
    [HttpGet("admin")]
    [Authorize(Roles = "Admin")]
    public async Task<IActionResult> GetAdmin()
    {
        var s = await _settings.GetAsync();
        return Ok(new { popupEnabled = s.OffersPopupEnabled, offers = s.Offers ?? new() });
    }

    public class SaveOffersRequest
    {
        public bool PopupEnabled { get; set; }
        public List<PromoOffer> Offers { get; set; } = new();
    }

    [HttpPut]
    [Authorize(Roles = "Admin")]
    public async Task<IActionResult> Save([FromBody] SaveOffersRequest req)
    {
        if (req is null) return BadRequest();
        var saved = await _settings.UpdateOffersAsync(req.PopupEnabled, req.Offers ?? new());
        return Ok(new { popupEnabled = saved.OffersPopupEnabled, offers = saved.Offers });
    }
}

