namespace SoulPilates.Core.Entities;

/// <summary>
/// A single promotional offer surfaced in the booking-page popup and controllable
/// from admin Settings → Offers. Stored as an embedded list on
/// <see cref="GlobalSettings.Offers"/> (not its own collection) so the whole set
/// saves/loads with settings and can be reordered/toggled freely.
/// </summary>
public class PromoOffer
{
    /// <summary>Stable slug id (e.g. "bring-a-friend"). Used by the client + reporting.</summary>
    public string Id { get; set; } = "";

    /// <summary>Per-offer on/off toggle.</summary>
    public bool Enabled { get; set; } = false;

    /// <summary>
    /// Mechanic. One of <see cref="OfferTypes"/>:
    /// BRING_A_FRIEND / BOGO (both: book 2 seats, charge 1),
    /// FREE_SOCKS (marketing tag — free grip socks handed over at the studio),
    /// DISCOUNT (ordinary %/fixed code applied to the class price).
    /// </summary>
    public string Type { get; set; } = OfferTypes.BringAFriend;

    /// <summary>Promotion code attached to the booking when the offer is claimed. Optional for FREE_SOCKS.</summary>
    public string PromoCode { get; set; } = "";

    /// <summary>Show only to first-time visitors (vs everyone). Default true.</summary>
    public bool FirstTimeOnly { get; set; } = true;

    /// <summary>Optional image (e.g. the grip-socks photo) rendered on the offer card.</summary>
    public string ImageUrl { get; set; } = "";

    public int DisplayOrder { get; set; } = 0;

    public string BadgeEn { get; set; } = "";
    public string BadgeVi { get; set; } = "";
    public string HeadlineEn { get; set; } = "";
    public string HeadlineVi { get; set; } = "";
    public string SubEn { get; set; } = "";
    public string SubVi { get; set; } = "";
}

public static class OfferTypes
{
    public const string BringAFriend = "BRING_A_FRIEND";
    public const string Bogo = "BOGO";
    public const string FreeSocks = "FREE_SOCKS";
    public const string Discount = "DISCOUNT";
}

