  // ── Offers tab (booking-page popup promotions) ──────────────────────────────
  (function () {
    let _offers = [];
    const TYPE_LABELS = {
      BRING_A_FRIEND: "Bring a friend (2 seats, friend free)",
      BOGO: "Buy 1 Get 1 (free class credit)",
      FREE_SOCKS: "Free grip socks (given at studio)",
      DISCOUNT: "Discount code (% or fixed off)",
    };
    function esc(s) { const d = document.createElement("div"); d.textContent = s == null ? "" : String(s); return d.innerHTML; }

    function renderOffers() {
      const host = document.getElementById("offersList");
      if (!host) return;
      host.innerHTML = _offers.map((o, i) => `
        <div style="border:1px solid var(--color-border-subtle);border-radius:10px;padding:14px 16px;background:var(--color-surface-raised);">
          <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px;">
            <label style="display:flex;align-items:center;gap:8px;cursor:pointer;">
              <input type="checkbox" class="of-enabled" data-i="${i}" ${o.enabled ? "checked" : ""} style="width:17px;height:17px;accent-color:var(--color-brand-accent);" />
              <span style="font-weight:700;font-size:13.5px;">${esc(TYPE_LABELS[o.type] || o.type)}</span>
            </label>
            ${o.imageUrl ? `<img src="${esc(o.imageUrl)}" alt="" style="width:34px;height:34px;object-fit:cover;border-radius:6px;" />` : ""}
          </div>
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
            <div><label class="form-label" style="font-size:11px;">Promo code</label><input type="text" class="form-control of-code" data-i="${i}" value="${esc(o.promoCode || "")}" /></div>
            <div><label class="form-label" style="font-size:11px;">Image URL (optional)</label><input type="text" class="form-control of-img" data-i="${i}" value="${esc(o.imageUrl || "")}" placeholder="/grip-socks.jpg" /></div>
            <div><label class="form-label" style="font-size:11px;">Headline (EN)</label><input type="text" class="form-control of-hen" data-i="${i}" value="${esc(o.headlineEn || "")}" /></div>
            <div><label class="form-label" style="font-size:11px;">Headline (VI)</label><input type="text" class="form-control of-hvi" data-i="${i}" value="${esc(o.headlineVi || "")}" /></div>
            <div><label class="form-label" style="font-size:11px;">Subtext (EN)</label><input type="text" class="form-control of-sen" data-i="${i}" value="${esc(o.subEn || "")}" /></div>
            <div><label class="form-label" style="font-size:11px;">Subtext (VI)</label><input type="text" class="form-control of-svi" data-i="${i}" value="${esc(o.subVi || "")}" /></div>
          </div>
          <label style="display:inline-flex;align-items:center;gap:7px;margin-top:10px;cursor:pointer;font-size:12px;color:var(--color-text-muted);">
            <input type="checkbox" class="of-fto" data-i="${i}" ${o.firstTimeOnly ? "checked" : ""} style="accent-color:var(--color-brand-accent);" />
            Show to first-time visitors only
          </label>
        </div>`).join("");
    }

    function collect() {
      const g = (cls, i) => document.querySelector(`.${cls}[data-i="${i}"]`);
      _offers.forEach((o, i) => {
        o.enabled = g("of-enabled", i)?.checked ?? false;
        o.promoCode = g("of-code", i)?.value?.trim() ?? "";
        o.imageUrl = g("of-img", i)?.value?.trim() ?? "";
        o.headlineEn = g("of-hen", i)?.value ?? "";
        o.headlineVi = g("of-hvi", i)?.value ?? "";
        o.subEn = g("of-sen", i)?.value ?? "";
        o.subVi = g("of-svi", i)?.value ?? "";
        o.firstTimeOnly = g("of-fto", i)?.checked ?? false;
      });
    }

    async function loadOffers() {
      try {
        const r = await fetch(API + "/api/offers/admin", { headers: { Authorization: "Bearer " + token } });
        if (!r.ok) return;
        const data = await r.json();
        document.getElementById("offersPopupEnabled").checked = !!data.popupEnabled;
        _offers = Array.isArray(data.offers) ? data.offers : [];
        renderOffers();
      } catch (e) {}
    }

    window.saveOffers = async function () {
      collect();
      const btn = document.getElementById("offersSaveBtn");
      const msg = document.getElementById("offersSaveMsg");
      btn.disabled = true; msg.textContent = "Saving…"; msg.style.color = "var(--color-text-muted)";
      try {
        const body = { popupEnabled: document.getElementById("offersPopupEnabled").checked, offers: _offers };
        const r = await fetch(API + "/api/offers", {
          method: "PUT",
          headers: { Authorization: "Bearer " + token, "Content-Type": "application/json" },
          body: JSON.stringify(body),
        });
        if (!r.ok) throw new Error("Save failed (" + r.status + ")");
        const data = await r.json();
        _offers = data.offers || _offers;
        msg.textContent = "Saved ✓"; msg.style.color = "var(--color-success)";
        setTimeout(() => (msg.textContent = ""), 2500);
      } catch (e) {
        msg.textContent = e.message; msg.style.color = "var(--color-danger)";
      } finally { btn.disabled = false; }
    };

    // Lazy-load when the Offers tab is first opened.
    let _loaded = false;
    document.querySelectorAll('.settings-tab[data-tab="offers"]').forEach((b) =>
      b.addEventListener("click", () => { if (!_loaded) { _loaded = true; loadOffers(); } }));
  })();

</script>

