public class ClassAttendeeDto
{
    public string AttendanceId { get; set; } = null!;
    public string ClientId { get; set; } = null!;
    public string ClientName { get; set; } = "Unknown";
    public string? ClientPhone { get; set; }
    public string? ClientEmail { get; set; }
    public string? BookingReference { get; set; }
    public string Status { get; set; } = "BOOKED";
    public string BookingSource { get; set; } = "ONLINE";
    public DateTime BookedAt { get; set; }
    public string? PaymentMethod { get; set; }
    public decimal AmountPaid { get; set; }
    public decimal AmountDueAtStudio { get; set; }
    public bool IsFreeClass { get; set; }
    public bool CountsTowardsCommission { get; set; }
    /// <summary>Number of seats this attendance row represents. Defaults to 1.</summary>
    public int Quantity { get; set; } = 1;
    /// <summary>Computed: "paid", "partial", "unpaid", "free", "package"</summary>
    public string PaymentStatus { get; set; } = "unpaid";
    /// <summary>
    /// SPM-84 — true when this session is the client's first-ever non-cancelled
    /// attendance at the studio (NEW client); false = Recurring. Defaults false
    /// so legacy/unscored rows render as Recurring.
    /// </summary>
    public bool IsNew { get; set; } = false;
    /// <summary>
    /// True when the attendee's Client has no linked customer account — i.e. they
    /// booked as a guest (guest checkout or admin-created) and never finished
    /// creating an account. Drives the "GUEST" tag on the calendar roster.
    /// </summary>
    public bool IsGuest { get; set; } = false;
    /// <summary>
    /// SPM-85 — true when this attendee still owes money for the session,
    /// using the same rule the POS uses: excludes PACKAGE_CREDIT and free
    /// classes; PAY_AT_STUDIO (or unset) with no amount paid is unpaid, and a
    /// PARTIAL payment with an outstanding balance is also unpaid. Defaults
    /// false so settled/legacy rows do not show a missing-payment tag.
    /// </summary>
    public bool IsUnpaid { get; set; } = false;

