114	    public async Task<PriceQuote> QuotePriceAsync(
115	        string sessionFormat,
116	        string paymentMethod,
117	        decimal? customSessionFee = null,
118	        int quantity = 1,
119	        string? clientId = null)
120	    {
121	        // Defensive clamps:
122	        //   • Private classes are 1-seat, EXCEPT a "Duo Class" (SPM-98) which seats 2
123	        //     in the same private session (booker pays for both); cap PRIVATE at 2 so a
124	        //     malicious or buggy client cannot bill more than a duo.
125	        //   • quantity ≤ 0 is meaningless; treat as 1.
126	        if (quantity <= 0) quantity = 1;
127	        if (sessionFormat == "PRIVATE" && quantity > 2) quantity = 2;
128	
129	        // Deposit % and session pricing are admin-owned — no appsettings fallbacks.
130	        var settings = await _settingsService.GetAsync();
131	        var depositPct = settings.DepositPercentage;
132	        var feePct = settings.OnlinePaymentFeePercentage;
133	
134	        // customSessionFee must always be supplied by the caller (sourced from
135	        // CalendarSession.DropInPrice which is snapshotted from the ClassBlueprint).
136	        // A null here means the caller forgot to pass it — surface a clear error
137	        // rather than silently quoting the wrong price.
138	        if (customSessionFee is null)
139	            throw new InvalidOperationException(
140	                "PAYMENT.MISSING_SESSION_FEE — customSessionFee is required. " +
141	                "Pass CalendarSession.DropInPrice when calling QuotePriceAsync.");
142	
143	        var sessionFee = customSessionFee.Value;
144	
145	        // Total billable for this quote is sessionFee * quantity. For STRIPE_FULL and
146	        // PAY_AT_STUDIO the customer pays this in full one way or another. For
147	        // STRIPE_DEPOSIT the deposit is taken on the total and the remainder is
148	        // collected at the studio. PACKAGE_CREDIT pays zero today and deducts N credits at check-in.
149	        var billableTotal = sessionFee * quantity;
150	
151	        var quote = new PriceQuote
152	        {
153	            SessionFee = sessionFee,
154	            DepositPercentage = depositPct,
155	            FeePercentage = feePct,
156	            Currency = Currency,
157	            Quantity = quantity,
158	        };
159	
160	        switch (paymentMethod)
161	        {
162	            case "PACKAGE_CREDIT":
163	                quote.AmountDueNow = 0;
164	                quote.AmountDueAtStudio = 0;
165	                break;
166	            case "STRIPE_DEPOSIT":
167	            {
168	                var baseDeposit = Math.Round(billableTotal * depositPct / 100m);
169	                var fee = feePct > 0 ? Math.Round(baseDeposit * feePct / 100m) : 0m;
170	                quote.FeeAmount = fee;
171	                quote.AmountDueNow = baseDeposit + fee;
172	                quote.AmountDueAtStudio = billableTotal - baseDeposit; // remaining is base, no extra fee
173	                break;
174	            }
175	            case "STRIPE_FULL":
176	            {
177	                var fee = feePct > 0 ? Math.Round(billableTotal * feePct / 100m) : 0m;
178	                quote.FeeAmount = fee;
