// ── Admin / Owner impersonation: viewAs ──
const _viewAsId = window.getViewAsStaffId?.() || null;
// SPM-103 — 'all' is the whole-studio aggregate sentinel, not a staffId.
const _isAllInstructors = _viewAsId === 'all';
// Owner gets the same schedule/roster impersonation parity as admins.
const _isAdmin = myRole === 'admin' || myRole === 'superadmin' || myRole === 'owner';
const _viewAs = _viewAsId ? `&viewAs=${encodeURIComponent(_viewAsId)}` : '';
// Helper to append viewAs to any URL (handles ? vs &)
const vaUrl = (url) => {
  if (!_viewAs) return url;
  return url + (url.includes('?') ? _viewAs : '?' + _viewAs.substring(1));
};

// When impersonating a single instructor, override the cached staffId.
// In "All instructors" mode there is no single staffId to scope to.
if (_viewAsId && !_isAllInstructors) myStaffId = _viewAsId;

// ── State ──
const classState = {
  page: 1, limit: 20,
  dateFrom: '', dateTo: '', status: '', hasAttendees: false, onlyUpcoming: false,
};
const bookingState = {
  page: 1, limit: 20,
};
let classData = null;
let bookingData = null;
let _currentDrawerSession = null;

// ── Init ──
async function insInit() {
  // Check if admin — show banner ONLY if no viewAs is active
  if (_isAdmin && !_viewAsId) {
    // No instructor selected — try to load own profile, if 404 show admin banner
    try {
      const res = await fetch(`${API}/api/instructor/me`, {
        headers: { Authorization: 'Bearer ' + token },
      });
      if (res.status === 404) {
        document.getElementById('insAdminBanner').style.display = '';
        document.getElementById('insClassSkeleton').style.display = 'none';
        return;
      }
      if (res.status === 401) {
        localStorage.removeItem('token');
        window.location.href = '/admin/login';
        return;
      }
    } catch {
      document.getElementById('insAdminBanner').style.display = '';
      document.getElementById('insClassSkeleton').style.display = 'none';
      return;
    }
  }

