public async Task<List<OfferFunnelRow>> GetOfferFunnelAsync(DateTime startUtc, DateTime endUtc, CancellationToken ct = default)
{
    var settings = await _settings.GetAsync(ct);
    var offers = (settings.Offers ?? new List<PromoOffer>())
        .OrderBy(o => o.DisplayOrder).ToList();
    if (offers.Count == 0) return new List<OfferFunnelRow>();

    // Offer impression/claim events in range, grouped by (offer, type) → distinct visitors.
    var offerEvents = await _events.Find(Builders<VisitorEvent>.Filter.And(
            Builders<VisitorEvent>.Filter.Gte(e => e.OccurredAt, startUtc),
            Builders<VisitorEvent>.Filter.Lt(e => e.OccurredAt, endUtc),
            Builders<VisitorEvent>.Filter.In(e => e.Type, new[] { "offer_shown", "offer_claimed" })))
        .Project(e => new { e.Type, e.OfferKey, e.VisitorId })
        .ToListAsync(ct);

    int Distinct(string key, string type) => offerEvents
        .Where(e => e.Type == type && string.Equals(e.OfferKey, key, StringComparison.OrdinalIgnoreCase))
        .Select(e => e.VisitorId).Distinct().Count();

    // Completed bookings carrying each offer's promo code (non-cancelled), in range.
    var codes = offers.Where(o => !string.IsNullOrWhiteSpace(o.PromoCode))
        .Select(o => o.PromoCode.Trim().ToUpperInvariant()).Distinct().ToList();
    var bookedByCode = new Dictionary<string, int>();
    if (codes.Count > 0)
    {
        var atts = await _attendances.Find(Builders<Attendance>.Filter.And(
                Builders<Attendance>.Filter.Gte(a => a.BookedAt, startUtc),
                Builders<Attendance>.Filter.Lt(a => a.BookedAt, endUtc),
                Builders<Attendance>.Filter.In(a => a.PromoCode, codes),
                Builders<Attendance>.Filter.Nin(a => a.Status, new[] { "CANCELLED", "LATE_CANCEL", "RESERVED" })))
            .Project(a => a.PromoCode)
            .ToListAsync(ct);
        bookedByCode = atts
            .Where(c => !string.IsNullOrWhiteSpace(c))
            .GroupBy(c => c!.Trim().ToUpperInvariant())
            .ToDictionary(g => g.Key, g => g.Count());
    }

    return offers.Select(o =>
    {
        var shown = Distinct(o.Key, "offer_shown");
        var claimed = Distinct(o.Key, "offer_claimed");
        var code = (o.PromoCode ?? "").Trim().ToUpperInvariant();
        var booked = code.Length > 0 && bookedByCode.TryGetValue(code, out var b) ? b : 0;
        return new OfferFunnelRow
        {
            OfferKey = o.Key,
            Label = string.IsNullOrWhiteSpace(o.HeadlineEn) ? o.Key : o.HeadlineEn,
            Shown = shown,
            Claimed = claimed,
            Booked = booked,
            ClaimRate = shown > 0 ? Math.Round(100.0 * claimed / shown, 1) : 0,
            BookRate = claimed > 0 ? Math.Round(100.0 * booked / claimed, 1) : 0,
        };
    }).ToList();
}

