// First-party offer tracking → /api/track (powers the admin analytics
// offer funnel: shown → claimed → booked).
function _trackOffer(type, key) {
  try {
    var vid = localStorage.getItem('sp_vid') || '';
    var sid = sessionStorage.getItem('sp_sid') || vid;
    if (!vid) return;
    var body = JSON.stringify({ type: type, visitorId: vid, sessionId: sid, path: '/booking', offerKey: key });
    if (navigator.sendBeacon) {
      navigator.sendBeacon('/api/track', new Blob([body], { type: 'application/json' }));
    } else {
      fetch('/api/track', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: body, keepalive: true });
    }
  } catch (e) {}
}

