function sourceBadge(src) {
  if (src === 'ONLINE') return '🌐';
  if (src === 'WALK_IN') return '🚶';
  if (src === 'ADMIN') return '👤';
  return '—';
}

async function loadBookings() {
  const tbody = document.getElementById('bookingTableBody');
  tbody.innerHTML = `<tr><td colspan="10" style="text-align:center;padding:48px;color:var(--color-text-muted);">Loading…</td></tr>`;

  try {
    const res = await fetch(`${API}/api/scheduling/bookings?${buildQueryParams()}`, {
      headers: { Authorization: 'Bearer ' + token },
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();

    if (!data.items || data.items.length === 0) {
      tbody.innerHTML = `<tr><td colspan="10" style="text-align:center;padding:48px;color:var(--color-text-muted);">No bookings found</td></tr>`;
      renderPagination(data);
      return;
    }

    tbody.innerHTML = data.items.map(b => {
      const bookedAt = new Date(b.bookedAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      const sessDate = b.sessionStartTime ? new Date(b.sessionStartTime).toLocaleDateString('en-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—';
      const statusCls = b.status === 'ARRIVED' || b.status === 'CHECKED_IN' ? 'badge-success' : b.status === 'NO_SHOW' || b.status === 'LATE_CANCEL' ? 'badge-danger' : b.status === 'CANCELLED' ? 'badge-danger' : 'badge-default';
      const invLink = b.linkedInvoiceNumber
        ? `<a href="/admin/invoices?search=${encodeURIComponent(b.linkedInvoiceNumber)}" title="View invoice ${b.linkedInvoiceNumber}" style="color:var(--color-brand-accent);font-size:11px;" onclick="event.stopPropagation();">📄 ${esc(b.linkedInvoiceNumber)}</a>`
        : '';
      return `<tr class="bkg-row" data-id="${b.attendanceId}" style="cursor:pointer;">
        <td class="text-sm font-medium" style="font-family:monospace;font-size:11px;">${esc(b.bookingReference || b.attendanceId?.substring(0, 8))}</td>
        <td><a href="/admin/client-profile?id=${b.clientId}" style="color:var(--color-brand-accent);font-weight:500;font-size:13px;" onclick="event.stopPropagation();">${esc(b.clientName)}</a></td>
        <td class="text-sm">${esc(b.className || '—')}</td>
        <td class="text-muted text-sm">${esc(b.instructorName || '—')}</td>
        <td class="text-muted text-sm">${bookedAt}</td>
        <td class="text-sm">${sessDate}</td>
        <td><span class="badge ${statusCls}">${b.status}</span></td>
        <td>${paymentBadge(b)}</td>
        <td style="text-align:center;font-size:14px;" title="${b.bookingSource}">${sourceBadge(b.bookingSource)}</td>
        <td>${invLink}</td>
      </tr>`;
    }).join('');

