function sourceBadge(src) {
  if (src === 'ONLINE') return '🌐';
  if (src === 'WALK_IN') return '🚶';
  if (src === 'ADMIN') return '👤';
  return '—';
}

// Marketing attribution shown under the channel icon (where the customer came
// from). Only meaningful for ONLINE bookings; walk-in/admin have no ad source.
function marketingBadge(b) {
  if (b.bookingSource !== 'ONLINE') return '';
  const key = (b.marketingSource || 'direct').toLowerCase();
  const label = SRC_LABEL[key] || SRC_LABEL.direct;
  return `<div style="font-size:10px;color:var(--color-text-muted);white-space:nowrap;margin-top:2px;">${label}</div>`;
}

// Offer/promo attached to the booking.
function offerBadge(b) {
  if (b.isBringAFriend) return `<div style="font-size:9px;font-weight:700;color:var(--color-brand-accent);white-space:nowrap;margin-top:2px;">🎉 Bring-a-friend</div>`;
  if (!b.promoCode) return '';
  const c = String(b.promoCode).toUpperCase();
  const lbl = c === 'FREESOCKS' ? '🧦 Free socks' : c === 'BOGO' ? '🎁 Buy 1 Get 1' : ('🏷️ ' + esc(c));
  return `<div style="font-size:9px;font-weight:700;color:var(--color-brand-accent);white-space:nowrap;margin-top:2px;">${lbl}</div>`;
}

