mongosh --quiet -u "$MONGO_INITDB_ROOT_USERNAME" -p "$MONGO_INITDB_ROOT_PASSWORD" --authenticationDatabase admin soulpilates --eval "
print(\"=== offer events (rows) by type+offer ===\");
db.VisitorEvents.aggregate([
  {\$match:{Type:{\$in:[\"offer_shown\",\"offer_claimed\"]}}},
  {\$group:{_id:{t:\"\$Type\",o:\"\$OfferKey\"}, rows:{\$sum:1}, visitors:{\$addToSet:\"\$VisitorId\"}}}
]).forEach(function(r){ print(r._id.t+\" / \"+r._id.o+\": rows=\"+r.rows+\" distinctVisitors=\"+r.visitors.length); });
print(\"=== total distinct visitors shown ANY offer ===\");
print(db.VisitorEvents.distinct(\"VisitorId\",{Type:\"offer_shown\"}).length);
print(\"=== distinct visitors who claimed ANY offer ===\");
print(db.VisitorEvents.distinct(\"VisitorId\",{Type:\"offer_claimed\"}).length);
print(\"=== earliest/latest offer_shown ===\");
var f=db.VisitorEvents.find({Type:\"offer_shown\"}).sort({OccurredAt:1}).limit(1).toArray()[0];
var l=db.VisitorEvents.find({Type:\"offer_shown\"}).sort({OccurredAt:-1}).limit(1).toArray()[0];
print((f?f.OccurredAt.toISOString():\"none\")+\" → \"+(l?l.OccurredAt.toISOString():\"none\"));
"' 2>&1 | head -20

