mongosh --quiet -u "$MONGO_INITDB_ROOT_USERNAME" -p "$MONGO_INITDB_ROOT_PASSWORD" --authenticationDatabase admin soulpilates --eval "
var claimers=db.VisitorEvents.distinct(\"VisitorId\",{Type:\"offer_claimed\",OfferKey:\"free-socks\"});
print(\"claimers: \"+claimers.length);
var shownAlso=db.VisitorEvents.distinct(\"VisitorId\",{Type:\"offer_shown\",OfferKey:\"free-socks\",VisitorId:{\$in:claimers}});
print(\"of those, also had offer_shown: \"+shownAlso.length);
print(\"=== bookings with FREESOCKS promo ===\");
print(db.Attendances.countDocuments({PromoCode:\"FREESOCKS\"}));
"' 2>&1 | head

