public async Task SendVerificationEmailAsync(string toEmail, string fullName, string token)
{
    if (!_enabled || string.IsNullOrWhiteSpace(toEmail)) return;

    var verifyUrl = $"{_publicBaseUrl}/verify-email?token={token}";

    var safeName = EmailTemplateHelper.EncodeText(fullName);

    // SPM-76 — {VerifyUrl} is the code-built deep-link (required variable).
    var bodyValues = new Dictionary<string, string>
    {
        ["FullName"] = safeName,
        ["VerifyUrl"] = verifyUrl,
    };

    var (subject, inner) = await ResolveTemplateAsync(
        EmailTemplateIds.Verification,
        defaultSubject: "Verify your Soul Pilates account | Xác minh tài khoản",
        defaultBody: EmailTemplateDefaults.VerificationBody,
        subjectValues: new Dictionary<string, string>(),
        bodyValues: bodyValues);

    var body = EmailTemplateHelper.Layout(
        heading: "Verify your email",
        subtitleVi: "Xác minh địa chỉ email của bạn",
        innerHtml: inner);

    await SendEmailAsync(toEmail, subject, body);
}

/// <summary>
/// Send the password-reset deep-link to a customer who hit the
/// <c>/forgot-password</c> page. Mirrors the verify-email contract:
/// <list type="bullet">
///   <item>Silently no-ops when SMTP is disabled or recipient blank.</item>
///   <item>Link target uses <see cref="_publicBaseUrl"/> so dev, staging and prod all land on the right host.</item>
///   <item>Token is treated as opaque — the service has already persisted the hash + expiry; we only render it.</item>
/// </list>
/// The reset link expires in 24h to match the entity's
/// <see cref="CustomerAccount.PasswordResetExpiry"/> contract.
/// </summary>
public async Task SendPasswordResetEmailAsync(string toEmail, string fullName, string token)
{
    if (!_enabled || string.IsNullOrWhiteSpace(toEmail)) return;

    var resetUrl = $"{_publicBaseUrl}/reset-password?token={token}";

    var safeName = EmailTemplateHelper.EncodeText(fullName);

    // SPM-76 — {ResetUrl} is the code-built deep-link (required variable so an

    // SPM-76 — {ResetUrl} is the code-built deep-link (required variable so an
    // admin edit can never strip the reset link out of the email).
    var bodyValues = new Dictionary<string, string>
    {
        ["FullName"] = safeName,
        ["ResetUrl"] = resetUrl,
    };

    var (subject, inner) = await ResolveTemplateAsync(
        EmailTemplateIds.PasswordReset,
        defaultSubject: "Reset your Soul Pilates password | Đặt lại mật khẩu",
        defaultBody: EmailTemplateDefaults.PasswordResetBody,
        subjectValues: new Dictionary<string, string>(),
        bodyValues: bodyValues);

    var body = EmailTemplateHelper.Layout(
        heading: "Reset your password",
        subtitleVi: "Đặt lại mật khẩu của bạn",
        innerHtml: inner);

    await SendEmailAsync(toEmail, subject, body);
}

