// re-sends to accounts that haven't activated yet). `onlyClientId`/`onlyEmail`
// let you target a single record for testing before the full send.
public async Task<ActivationInviteResult> SendActivationInvitesAsync(
    string? onlyClientId, string? onlyEmail, bool resend)
{
    var clients = await _clients.Find(_ => true).ToListAsync();

    if (!string.IsNullOrWhiteSpace(onlyClientId))
        clients = clients.Where(c => c.Id == onlyClientId).ToList();
    if (!string.IsNullOrWhiteSpace(onlyEmail))
        clients = clients.Where(c => string.Equals(c.Email, onlyEmail, StringComparison.OrdinalIgnoreCase)).ToList();

    var result = new ActivationInviteResult();

    foreach (var c in clients)
    {
        if (string.IsNullOrWhiteSpace(c.Email)) { result.NoEmail++; continue; }
        var email = c.Email.Trim().ToLowerInvariant();
        var token = Guid.NewGuid().ToString("N") + Guid.NewGuid().ToString("N");
        var expiry = DateTime.UtcNow.AddDays(30);

        var existing = await _accounts.Find(a => a.Email == email).FirstOrDefaultAsync();
        if (existing == null)
        {
            var acct = new CustomerAccount
            {
                FullName = c.FullName,
                Email = email,
                ClientId = c.Id,
                // Random unusable hash — no login until they set a password.
                PasswordHash = PasswordHasher.Hash(Guid.NewGuid().ToString("N")),
                EmailVerified = false,
                PasswordResetToken = token,
                PasswordResetExpiry = expiry,
            };
            await _accounts.InsertOneAsync(acct);
            await _emailService.SendActivationEmailAsync(email, c.FullName, token);
            result.Created++;
        }
        else if (!existing.EmailVerified && resend)
        {
            await _accounts.UpdateOneAsync(a => a.Id == existing.Id,
                Builders<CustomerAccount>.Update
                    .Set(a => a.PasswordResetToken, token)
                    .Set(a => a.PasswordResetExpiry, expiry));
            await _emailService.SendActivationEmailAsync(email, existing.FullName, token);
            result.Resent++;
        }
        else
        {
            result.Skipped++; // already activated, or unverified without resend
        }
    }

    return result;
}

