using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;
using System;
using System.Collections.Generic;

namespace SoulPilates.Core.DTOs;

public class ClientDto
{
    public string? id { get; set; }
    public string name { get; set; } = null!;
    public string? email { get; set; }

    /// <summary>National portion of the phone number (no leading +CC). E.g. <c>"901234567"</c>.</summary>
    public string? phone { get; set; }

    /// <summary>Country dial code with leading +. E.g. <c>"+84"</c>. Optional; null when unknown.</summary>
    public string? phoneCountryCode { get; set; }

    public string preferredContactPlatform { get; set; } = "NONE";
    public string? country { get; set; } = "Vietnam";
    public string? notes { get; set; }
    public string? medicalHistory { get; set; }
    public string? referralSource { get; set; }
    public List<string> tags { get; set; } = new();
    public string? partnerCode { get; set; }

    /// <summary>
    /// Optional date-of-birth. Used by birthday/age-segment analytics and
    /// surfaced on the admin client form. Storing it on the CRM Client is
    /// independent of <c>CustomerAccount.DateOfBirth</c> — admin entry
    /// captures DOB for walk-ins who never self-registered online.
    /// </summary>
    public DateTime? dateOfBirth { get; set; }

    public DateTime? createdAt { get; set; }

    // ── Read-only lifecycle metrics ──────────────────────────────────
    // Populated server-side only; ignored on inbound POST/PUT bodies.
    // Surfaced on the edit form so the operator sees the client's
    // tenure / value at a glance.

    /// <summary>Date of the client's first booked attendance, if any.</summary>
    public DateTime? firstVisitDate { get; set; }

    /// <summary>All-time PAID-invoice revenue attributable to this client (VND).</summary>
    public decimal lifetimeValue { get; set; }

    /// <summary>Checked-in class count (drives the Super VIP tier).</summary>
    public int attendedClasses { get; set; }

    // Active remaining credits, split by format (for the clients-list Credits column).
    public int groupCredits { get; set; }
    public int matCredits { get; set; }
    public int privateCredits { get; set; }

    /// <summary>Derived VIP tier: "" (none), "VIP", or "SUPER_VIP".</summary>
    public string vipTier { get; set; } = "";
}

