543	    /// Produces a human-readable, monotonically-ordered invoice number
544	    /// in the form <c>SP-INV-YYMMDD-NNNN</c>, where NNNN is the next sequence
545	    /// for that calendar day (UTC). Format mirrors the booking-reference style
546	    /// already documented in <c>_AGENT_NOTES.md</c>.
547	    /// </summary>
548	    private async Task<string> GenerateInvoiceNumberAsync(DateTime issueDate)
549	    {
550	        var dayPrefix = $"SP-INV-{issueDate.ToUniversalTime():yyMMdd}-";
551	
552	        // Count existing invoices with the same prefix to derive the next sequence.
553	        // Uses a regex match on InvoiceNumber so we don't need a separate counter collection
554	        // (acceptable given studio scale; will be revisited if sequencing becomes a hot path).
555	        var filter = Builders<Invoice>.Filter.Regex(
556	            i => i.InvoiceNumber,
557	            new MongoDB.Bson.BsonRegularExpression($"^{dayPrefix}"));
558	
559	        var existingForDay = await _invoices.CountDocumentsAsync(filter);
560	        var sequence = (existingForDay + 1).ToString("D4", CultureInfo.InvariantCulture);
561	
562	        return dayPrefix + sequence;
563	    }
