mongosh --quiet -u "$MONGO_INITDB_ROOT_USERNAME" -p "$MONGO_INITDB_ROOT_PASSWORD" --authenticationDatabase admin soulpilates --eval "
print(\"=== products with IncludesFreePrivateClass ===\");
var prods=db.Products.find({IncludesFreePrivateClass:true},{Name:1,Credits:1,FormatRestriction:1,ValidityDays:1}).toArray();
prods.forEach(p=>print(p._id+\"  \"+p.Name+\"  credits=\"+p.Credits+\"  fmt=\"+p.FormatRestriction+\"  valid=\"+p.ValidityDays));
print(\"=== recent GROUP packages (last 3 days) from those products (via invoice lines) ===\");
var since=new Date(Date.now()-3*24*3600*1000);
db.ClientPackages.find({CreatedAt:{\$gte:since}, Format:{\$ne:\"PRIVATE\"}}).sort({CreatedAt:-1}).limit(10).toArray().forEach(function(w){
  var cl=db.Clients.findOne({_id:w.ClientId}) || db.Clients.findOne({_id:ObjectId(w.ClientId)});
  var hasFreePriv=db.ClientPackages.countDocuments({ClientId:w.ClientId, Format:\"PRIVATE\", FractionalValuePerClass:0});
  print(w.CreatedAt.toISOString()+\"  client=\"+(cl?cl.FullName:w.ClientId)+\"  credits=\"+w.TotalCredits+\"  freePrivateCredits=\"+hasFreePriv+\"  invLine=\"+w.InvoiceLineId);
});
"' 2>&1 | head -25

cd /opt/soulpilates && docker compose -f docker-compose.prod.yml --env-file prod.env up -d backend 2>&1 | tail -2
for i in $(seq 1 8); do c=$(curl -sL -o /dev/null -w "%{http_code}" https://soulpilates.com.vn/api/offers); [ "$c" != "502" ] && break; sleep 4; done; echo "backend ($c)"
echo "=== retroactively grant the missing free PRIVATE credits ==="
docker exec soulpilates-prod-mongo bash -lc '
mongosh --quiet -u "$MONGO_INITDB_ROOT_USERNAME" -p "$MONGO_INITDB_ROOT_PASSWORD" --authenticationDatabase admin soulpilates --eval "
var since=new Date(Date.now()-3*24*3600*1000);
// find recent GROUP packages from free-private products missing their private credit
var freeProds=db.Products.find({IncludesFreePrivateClass:true}).toArray();
var byId={}; freeProds.forEach(p=>byId[p._id.valueOf()]=p);
var granted=0;
db.ClientPackages.find({CreatedAt:{\$gte:since}, Format:{\$ne:\"PRIVATE\"}}).forEach(function(w){
  var already=db.ClientPackages.countDocuments({ClientId:w.ClientId, Format:\"PRIVATE\", FractionalValuePerClass:0, SourceNote:/FREE_PRIVATE/});
  if(already>0) return;
  // only for 30/60 group packs (60 credits or 30 credits from the free-priv products)
  if(w.TotalCredits!==60 && w.TotalCredits!==30) return;
  var cl=db.Clients.findOne({_id:w.ClientId});
  var exp = w.ExpiryDate ? w.ExpiryDate : null;
  db.ClientPackages.insertOne({
    ClientId:w.ClientId, InvoiceLineId:null, Format:\"PRIVATE\",
    TotalCredits:1, CreditsUsed:0, CreditsRemaining:1,
    ActivationDate:w.ActivationDate||new Date(), ExpiryDate:exp,
    Status:\"ACTIVE\", FractionalValuePerClass:0,
    SourceNote:\"FREE_PRIVATE:retroactive:\"+w._id.valueOf(),
    RetentionRemindersSent:[], CreatedAt:new Date(), UpdatedAt:new Date()
  });
  print(\"granted free PRIVATE credit to \"+(cl?cl.FullName:w.ClientId)+\" (from \"+w.TotalCredits+\"-pack)\");
  granted++;
});
print(\"total granted: \"+granted);
"' 2>&1 | head

