using MongoDB.Driver;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.Services;

/// <summary>
/// Records voucher redemptions (customer arrived with a partner-location voucher)
/// and rolls them up for the "voucher traffic by location" analytics. When the
/// promotion gives socks it deducts a pair from grip-sock stock via the SKU service.
/// </summary>
public class VoucherTrafficService : IVoucherTrafficService
{
    private readonly IMongoCollection<VoucherTrafficLog> _logs;
    private readonly ISettingsService _settings;
    private readonly IMerchandiseSkuService _skus;

    public VoucherTrafficService(MongoDbContext db, ISettingsService settings, IMerchandiseSkuService skus)
    {
        _logs = db.GetCollection<VoucherTrafficLog>("VoucherTrafficLogs");
        _settings = settings;
        _skus = skus;
    }

    public async Task<(List<VoucherLocation>, List<VoucherPromotion>)> GetConfigAsync(CancellationToken ct = default)
    {
        var s = await _settings.GetAsync(ct);
        return (s.VoucherLocations ?? new(), s.VoucherPromotions ?? new());
    }

    public Task SaveConfigAsync(List<VoucherLocation> locations, List<VoucherPromotion> promotions, CancellationToken ct = default)
        => _settings.UpdateVoucherConfigAsync(locations ?? new(), promotions ?? new(), ct);

    public async Task<VoucherTrafficLog> RecordAsync(VoucherRecordRequest req, CancellationToken ct = default)
    {
        var s = await _settings.GetAsync(ct);
        var loc = (s.VoucherLocations ?? new()).FirstOrDefault(l => l.Key == req.LocationKey)
            ?? throw new InvalidOperationException("Unknown voucher location.");
        var promo = (s.VoucherPromotions ?? new()).FirstOrDefault(p => p.Key == req.PromotionKey)
            ?? throw new InvalidOperationException("Unknown voucher promotion.");

        var log = new VoucherTrafficLog
        {
            LocationKey = loc.Key,
            LocationName = loc.Name,
            PromotionKey = promo.Key,
            PromotionName = promo.Name,
            ClientId = string.IsNullOrWhiteSpace(req.ClientId) ? null : req.ClientId,
            ClientName = req.ClientName,
            RecordedByStaffId = string.IsNullOrWhiteSpace(req.RecordedByStaffId) ? null : req.RecordedByStaffId,
        };

        if (promo.GivesSocks)
        {
            if (string.IsNullOrWhiteSpace(req.SocksSkuId))
                throw new InvalidOperationException("Pick the sock size + colour handed over for this voucher.");
            var sku = await _skus.GetByIdAsync(req.SocksSkuId);
            if (sku is null) throw new InvalidOperationException("Sock variant not found.");
            var ok = await _skus.TryDeductAsync(req.SocksSkuId, 1);
            if (!ok) throw new InvalidOperationException($"Out of stock: {sku.VariantColor}/{sku.VariantSize}.");
            log.GaveSocks = true;
            log.SocksSkuId = sku.Id;
            log.SocksColor = sku.VariantColor;
            log.SocksSize = sku.VariantSize;
        }

        await _logs.InsertOneAsync(log, cancellationToken: ct);
        return log;
    }

    public async Task<List<VoucherLocationStat>> GetByLocationAsync(DateTime startUtc, DateTime endUtc, CancellationToken ct = default)
    {
        var rows = await _logs.Find(Builders<VoucherTrafficLog>.Filter.And(
                Builders<VoucherTrafficLog>.Filter.Gte(l => l.CreatedAt, startUtc),
                Builders<VoucherTrafficLog>.Filter.Lt(l => l.CreatedAt, endUtc)))
            .ToListAsync(ct);

        return rows
            .GroupBy(r => string.IsNullOrWhiteSpace(r.LocationName) ? "Unknown" : r.LocationName)
            .Select(g => new VoucherLocationStat
            {
                Location = g.Key,
                Count = g.Count(),
                SocksGiven = g.Count(x => x.GaveSocks),
            })
            .OrderByDescending(r => r.Count)
            .ToList();
    }
}

