using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.API.Controllers;

/// <summary>
/// Voucher promotions distributed at partner locations (shops/cafes). Config
/// (locations + promotions) lives on GlobalSettings; redemptions are logged for
/// the "voucher traffic by location" analytics. Distinct from the discount
/// voucher-batch system.
/// </summary>
[ApiController]
[Route("api/voucher-traffic")]
public class VoucherTrafficController : ControllerBase
{
    private readonly IVoucherTrafficService _service;

    public VoucherTrafficController(IVoucherTrafficService service) => _service = service;

    /// <summary>Locations + promotions — used by POS (voucher tagging) and the admin editor.</summary>
    [HttpGet("config")]
    [Authorize(Roles = "Admin,Receptionist,HeadInstructor,Manager,Accountant")]
    public async Task<IActionResult> GetConfig(CancellationToken ct)
    {
        var (locations, promotions) = await _service.GetConfigAsync(ct);
        return Ok(new { locations, promotions });
    }

    public class SaveConfigRequest
    {
        public List<VoucherLocation> Locations { get; set; } = new();
        public List<VoucherPromotion> Promotions { get; set; } = new();
    }

    [HttpPut("config")]
    [Authorize(Roles = "Admin")]
    public async Task<IActionResult> SaveConfig([FromBody] SaveConfigRequest req, CancellationToken ct)
    {
        if (req is null) return BadRequest();
        await _service.SaveConfigAsync(req.Locations ?? new(), req.Promotions ?? new(), ct);
        var (locations, promotions) = await _service.GetConfigAsync(ct);
        return Ok(new { locations, promotions });
    }

    /// <summary>Record a voucher redemption at POS (deducts socks when the promotion gives them).</summary>
    [HttpPost("record")]
    [Authorize(Roles = "Admin,Receptionist,HeadInstructor,Manager")]
    public async Task<IActionResult> Record([FromBody] VoucherRecordRequest req, CancellationToken ct)
    {
        try
        {
            var log = await _service.RecordAsync(req, ct);
            return Ok(new { recorded = true, id = log.Id, gaveSocks = log.GaveSocks });
        }
        catch (InvalidOperationException ex)
        {
            return BadRequest(new { error = ex.Message });
        }
    }

    [HttpGet("analytics")]
    [Authorize(Roles = "Admin,Accountant")]
    public async Task<IActionResult> Analytics([FromQuery] DateTime start, [FromQuery] DateTime end, CancellationToken ct)
        => Ok(await _service.GetByLocationAsync(start.ToUniversalTime(), end.ToUniversalTime(), ct));
}

