  // ── Vouchers (locations + promotions) ──────────────────────────────────────
  let _vLocations = [];
  let _vPromotions = [];
  let _voucherLoaded = false;
  const _slug = (s) => String(s || '').toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || ('x-' + Date.now());
  const _vEsc = (s) => { const d = document.createElement('div'); d.textContent = s == null ? '' : String(s); return d.innerHTML; };

  function renderVoucherLists() {
    document.getElementById('voucherLocationList').innerHTML = _vLocations.map((l, i) => `
      <div style="display:flex;align-items:center;gap:8px;">
        <input type="checkbox" class="vl-active" data-i="${i}" ${l.active !== false ? 'checked' : ''} title="Active" style="width:16px;height:16px;accent-color:var(--color-brand-accent);" />
        <input type="text" class="form-control vl-name" data-i="${i}" value="${_vEsc(l.name)}" placeholder="Roots Cafe" style="flex:1;" />
        <button class="btn btn-ghost btn-sm" type="button" style="color:var(--color-danger);" onclick="removeVoucherLocation(${i})">×</button>
      </div>`).join('') || '<div style="font-size:12px;color:var(--color-text-muted);">No locations yet.</div>';
    document.getElementById('voucherPromotionList').innerHTML = _vPromotions.map((p, i) => `
      <div style="display:flex;align-items:center;gap:8px;">
        <input type="checkbox" class="vp-active" data-i="${i}" ${p.active !== false ? 'checked' : ''} title="Active" style="width:16px;height:16px;accent-color:var(--color-brand-accent);" />
        <input type="text" class="form-control vp-name" data-i="${i}" value="${_vEsc(p.name)}" placeholder="Free Socks Promotion" style="flex:1;" />
        <label style="display:flex;align-items:center;gap:5px;font-size:11.5px;white-space:nowrap;cursor:pointer;">
          <input type="checkbox" class="vp-socks" data-i="${i}" ${p.givesSocks ? 'checked' : ''} style="accent-color:var(--color-brand-accent);" /> gives socks
        </label>
        <button class="btn btn-ghost btn-sm" type="button" style="color:var(--color-danger);" onclick="removeVoucherPromotion(${i})">×</button>
      </div>`).join('') || '<div style="font-size:12px;color:var(--color-text-muted);">No promotions yet.</div>';
  }
  function _collectVouchers() {
    const g = (cls, i) => document.querySelector(`.${cls}[data-i="${i}"]`);
    _vLocations.forEach((l, i) => { l.name = g('vl-name', i)?.value?.trim() || ''; l.active = g('vl-active', i)?.checked ?? true; if (!l.key) l.key = _slug(l.name); });
    _vPromotions.forEach((p, i) => { p.name = g('vp-name', i)?.value?.trim() || ''; p.givesSocks = g('vp-socks', i)?.checked ?? false; p.active = g('vp-active', i)?.checked ?? true; if (!p.key) p.key = _slug(p.name); });
    _vLocations = _vLocations.filter((l) => l.name);
    _vPromotions = _vPromotions.filter((p) => p.name);
  }
  window.addVoucherLocation = () => { _collectVouchers(); _vLocations.push({ key: '', name: '', active: true }); renderVoucherLists(); };
  window.removeVoucherLocation = (i) => { _collectVouchers(); _vLocations.splice(i, 1); renderVoucherLists(); };
  window.addVoucherPromotion = () => { _collectVouchers(); _vPromotions.push({ key: '', name: '', givesSocks: false, active: true }); renderVoucherLists(); };
  window.removeVoucherPromotion = (i) => { _collectVouchers(); _vPromotions.splice(i, 1); renderVoucherLists(); };

  async function loadVoucherConfig() {
    if (_voucherLoaded) return;
    _voucherLoaded = true;
    try {
      const r = await fetch(API + '/api/voucher-traffic/config', { headers: { Authorization: 'Bearer ' + token } });
      if (!r.ok) return;
      const d = await r.json();
      _vLocations = Array.isArray(d.locations) ? d.locations : [];
      _vPromotions = Array.isArray(d.promotions) ? d.promotions : [];
      renderVoucherLists();
    } catch (e) {}
  }
  window.saveVoucherConfig = async () => {
    _collectVouchers();
    // Ensure keys are stable slugs.
    _vLocations.forEach((l) => { if (!l.key) l.key = _slug(l.name); });
    _vPromotions.forEach((p) => { if (!p.key) p.key = _slug(p.name); });
    const btn = document.getElementById('voucherSaveBtn');
    const msg = document.getElementById('voucherSaveMsg');
    btn.disabled = true; msg.textContent = 'Saving…'; msg.style.color = 'var(--color-text-muted)';
    try {
      const r = await fetch(API + '/api/voucher-traffic/config', {
        method: 'PUT',
        headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' },
        body: JSON.stringify({ locations: _vLocations, promotions: _vPromotions }),
      });
      if (!r.ok) throw new Error('Save failed (' + r.status + ')');
      const d = await r.json();
      _vLocations = d.locations || _vLocations; _vPromotions = d.promotions || _vPromotions;
      renderVoucherLists();
      msg.textContent = 'Saved ✓'; msg.style.color = 'var(--color-success)';
      setTimeout(() => (msg.textContent = ''), 2500);
    } catch (e) { msg.textContent = e.message; msg.style.color = 'var(--color-danger)'; }
    finally { btn.disabled = false; }
  };
</script>

