// ── Voucher redemption ──────────────────────────────────────────────────
let _voucherCfg = null;
let _voucherSocksSkus = [];

async function openVoucherModal() {
  document.getElementById("voucherError").style.display = "none";
  document.getElementById("voucherSocksWrap").style.display = "none";
  document.getElementById("voucherClientNote").textContent = selectedClient
    ? `Will be linked to ${selectedClient.name}.`
    : "No client selected — will be recorded anonymously for traffic tracking.";
  if (!_voucherCfg) {
    try { _voucherCfg = await fetch(`${API}/api/voucher-traffic/config`, { headers: { Authorization: "Bearer " + token } }).then(r => r.json()); }
    catch (e) { _voucherCfg = { locations: [], promotions: [] }; }
  }
  const locs = (_voucherCfg.locations || []).filter(l => l.active !== false);
  const promos = (_voucherCfg.promotions || []).filter(p => p.active !== false);
  if (!locs.length || !promos.length) {
    window.showToast && window.showToast("Set up voucher locations & promotions first (Referrals → Vouchers).", "warning");
    return;
  }
  document.getElementById("voucherLocation").innerHTML = '<option value="">Select location…</option>' +
    locs.map(l => `<option value="${_posEsc(l.key)}">${_posEsc(l.name)}</option>`).join("");
  document.getElementById("voucherPromotion").innerHTML = '<option value="">Select promotion…</option>' +
    promos.map(p => `<option value="${_posEsc(p.key)}" data-socks="${p.givesSocks ? 1 : 0}">${_posEsc(p.name)}</option>`).join("");
  document.getElementById("voucherOverlay").style.display = "flex";
}
function closeVoucherModal() { document.getElementById("voucherOverlay").style.display = "none"; }

async function onVoucherPromotionChange() {
  const sel = document.getElementById("voucherPromotion");
  const givesSocks = sel.options[sel.selectedIndex]?.dataset?.socks === "1";
  const wrap = document.getElementById("voucherSocksWrap");
  if (!givesSocks) { wrap.style.display = "none"; return; }
  wrap.style.display = "block";
  if (!_voucherSocksSkus.length) {
    const sockProd = (allProducts || []).find(p => p.type === "MERCHANDISE" && ((p.packSize || 0) > 0 || /grip\s*sock/i.test(p.name || "")));
    if (sockProd) {
      try { _voucherSocksSkus = await fetch(`${API}/api/merchandise/${sockProd.id}/skus`, { headers: { Authorization: "Bearer " + token } }).then(r => r.json()); }
      catch (e) { _voucherSocksSkus = []; }
    }
  }
  const opts = (_voucherSocksSkus || []).map(s => {
    const oos = (s.stockQuantity ?? 0) <= 0;
    return `<option value="${s.id}" ${oos ? "disabled" : ""}>${_posEsc(s.variantColor)}/${_posEsc(s.variantSize)} — ${oos ? "out of stock" : s.stockQuantity + " left"}</option>`;
  }).join("");
  document.getElementById("voucherSocksPicker").innerHTML = `<select class="form-control" id="voucherSocksSku"><option value="">Select socks…</option>${opts}</select>`;
}

async function submitVoucher() {
  const err = document.getElementById("voucherError"); err.style.display = "none";
  const locKey = document.getElementById("voucherLocation").value;
  const promoSel = document.getElementById("voucherPromotion");
  const promoKey = promoSel.value;
  if (!locKey || !promoKey) { err.textContent = "Pick a location and a promotion."; err.style.display = "block"; return; }
  const givesSocks = promoSel.options[promoSel.selectedIndex]?.dataset?.socks === "1";
  let socksSkuId = null;
  if (givesSocks) {
    socksSkuId = document.getElementById("voucherSocksSku")?.value || "";
    if (!socksSkuId) { err.textContent = "Pick the socks size & colour handed over."; err.style.display = "block"; return; }
  }
  const btn = document.getElementById("voucherSubmitBtn"); btn.disabled = true; btn.textContent = "Recording…";
  try {
    const body = { locationKey: locKey, promotionKey: promoKey, socksSkuId, clientId: selectedClient?.id || null, clientName: selectedClient?.name || null };
    const r = await fetch(`${API}/api/voucher-traffic/record`, { method: "POST", headers: { Authorization: "Bearer " + token, "Content-Type": "application/json" }, body: JSON.stringify(body) });
    const d = await r.json().catch(() => ({}));
    if (!r.ok) throw new Error(d.error || "Failed to record.");
    window.showToast && window.showToast("Voucher recorded" + (d.gaveSocks ? " — socks deducted from stock" : "") + ".", "success");
    _voucherSocksSkus = []; // refresh stock next open
    closeVoucherModal();
  } catch (e) {
    err.textContent = e.message || "Could not record the voucher."; err.style.display = "block";
  } finally { btn.disabled = false; btn.textContent = "Record voucher"; }
}
window.openVoucherModal = openVoucherModal;
window.closeVoucherModal = closeVoucherModal;
window.onVoucherPromotionChange = onVoucherPromotionChange;
window.submitVoucher = submitVoucher;

window.closeVariantPicker = closeVariantPicker;

