/* ── Voucher redemption (calendar checkout) ── */
async mposOpenVoucher() {
  const picker = document.getElementById('mposPicker');
  if (picker.style.display === 'block' && picker.dataset.kind === 'voucher') { picker.style.display = 'none'; return; }
  picker.dataset.kind = 'voucher'; picker.style.display = 'block';
  picker.innerHTML = '<div style="font-size:11px;color:var(--color-text-muted);padding:6px;">Loading…</div>';
  if (!this._voucherCfg) {
    try { this._voucherCfg = await fetch(`${_CDP_API}/api/voucher-traffic/config`, { headers: { Authorization: 'Bearer ' + this._getToken() } }).then(r => r.json()); }
    catch { this._voucherCfg = { locations: [], promotions: [] }; }
  }
  const esc = this._esc.bind(this);
  const locs = (this._voucherCfg.locations || []).filter(l => l.active !== false);
  const promos = (this._voucherCfg.promotions || []).filter(p => p.active !== false);
  if (!locs.length || !promos.length) {
    picker.innerHTML = '<div style="font-size:11px;color:var(--color-text-muted);padding:6px;">Set up voucher locations &amp; promotions in Referrals → Vouchers first.</div>';
    return;
  }
  picker.innerHTML = `<div style="display:flex;flex-direction:column;gap:8px;padding:4px;">
    <select class="form-control" id="mposVLoc"><option value="">Voucher from…</option>${locs.map(l => `<option value="${esc(l.key)}">${esc(l.name)}</option>`).join('')}</select>
    <select class="form-control" id="mposVPromo" onchange="ClassDetailPanel.mposVoucherPromoChange()"><option value="">Promotion…</option>${promos.map(p => `<option value="${esc(p.key)}" data-socks="${p.givesSocks ? 1 : 0}">${esc(p.name)}</option>`).join('')}</select>
    <div id="mposVSocks" style="display:none;"></div>
    <div id="mposVErr" style="display:none;font-size:11px;color:var(--color-danger);"></div>
    <button class="btn btn-primary btn-sm" onclick="ClassDetailPanel.mposSubmitVoucher()">Record voucher</button>
  </div>`;
},

async mposVoucherPromoChange() {
  const sel = document.getElementById('mposVPromo');
  const gives = sel.options[sel.selectedIndex]?.dataset?.socks === '1';
  const wrap = document.getElementById('mposVSocks');
  if (!gives) { wrap.style.display = 'none'; return; }
  wrap.style.display = 'block';
  if (!this._voucherSocksSkus) {
    if (!this._mpos.products) { try { this._mpos.products = await fetch(`${_CDP_API}/api/product`, { headers: { Authorization: 'Bearer ' + this._getToken() } }).then(r => r.json()); } catch { this._mpos.products = []; } }
    const sp = (this._mpos.products || []).find(p => p.type === 'MERCHANDISE' && ((p.packSize || 0) > 0 || /grip\s*sock/i.test(p.name || '')));
    if (sp) { try { this._voucherSocksSkus = await fetch(`${_CDP_API}/api/merchandise/${sp.id}/skus`, { headers: { Authorization: 'Bearer ' + this._getToken() } }).then(r => r.json()); } catch { this._voucherSocksSkus = []; } }
    else this._voucherSocksSkus = [];
  }
  const esc = this._esc.bind(this);
  wrap.innerHTML = `<select class="form-control" id="mposVSku"><option value="">Socks size &amp; colour…</option>${(this._voucherSocksSkus || []).map(s => { const oos = (s.stockQuantity ?? 0) <= 0; return `<option value="${s.id}" ${oos ? 'disabled' : ''}>${esc(s.variantColor)}/${esc(s.variantSize)} — ${oos ? 'out of stock' : s.stockQuantity + ' left'}</option>`; }).join('')}</select>`;
},

async mposSubmitVoucher() {
  const err = document.getElementById('mposVErr'); err.style.display = 'none';
  const locKey = document.getElementById('mposVLoc').value;
  const pSel = document.getElementById('mposVPromo'); const promoKey = pSel.value;
  if (!locKey || !promoKey) { err.textContent = 'Pick a location and promotion.'; err.style.display = 'block'; return; }
  const gives = pSel.options[pSel.selectedIndex]?.dataset?.socks === '1';
  let socksSkuId = null;
  if (gives) { socksSkuId = document.getElementById('mposVSku')?.value || ''; if (!socksSkuId) { err.textContent = 'Pick the socks size & colour.'; err.style.display = 'block'; return; } }
  try {
    const body = { locationKey: locKey, promotionKey: promoKey, socksSkuId, clientId: this._mpos?.clientId || null, clientName: this._mpos?.clientName || null };
    const r = await fetch(`${_CDP_API}/api/voucher-traffic/record`, { method: 'POST', headers: { Authorization: 'Bearer ' + this._getToken(), 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
    const d = await r.json().catch(() => ({}));
    if (!r.ok) throw new Error(d.error || 'Failed to record.');
    window.showToast?.('Voucher recorded' + (d.gaveSocks ? ' — socks deducted from stock' : '') + '.', 'success');
    this._voucherSocksSkus = null;
    document.getElementById('mposPicker').style.display = 'none';
  } catch (e) { err.textContent = e.message || 'Could not record the voucher.'; err.style.display = 'block'; }
},

