/// <summary>Distinct studio-local dates ("yyyy-MM-dd") the receptionist is scheduled to work this month.</summary>
private async Task<HashSet<string>> GetWorkingDayKeysAsync(string staffId, int year, int month, CancellationToken ct)
{
    var from = new DateOnly(year, month, 1);
    var to = from.AddMonths(1).AddDays(-1);
    var occ = await _shifts.GetScheduleAsync(from, to, staffId);
    return occ
        .Where(o => o.StaffId == staffId && !string.IsNullOrWhiteSpace(o.Date))
        .Select(o => o.Date)
        .ToHashSet(StringComparer.OrdinalIgnoreCase);
}

/// <summary>
/// Daily-task reward. <c>DailyTaskCompletionPercent</c> is the TOTAL allocation for
/// daily tasks for the month; it is spread across the receptionist's scheduled
/// working days, so each completed working day is worth total ÷ working-days.
/// Returns (completed working days, total working days, earned percent).
/// </summary>
private async Task<(int completed, int workingDays, decimal taskPercent)> ComputeDailyTaskRewardAsync(
    string staffId, int year, int month, ReceptionistKpiMonthOverride cfg, CancellationToken ct)
{
    var workingDays = await GetWorkingDayKeysAsync(staffId, year, month, ct);
    var completed = await CountCompletedTaskDaysAsync(staffId, year, month, cfg, workingDays, ct);
    var total = workingDays.Count;
    var allocation = Math.Max(0m, cfg.DailyTaskCompletionPercent);
    var taskPercent = total > 0 ? (completed / (decimal)total) * allocation : 0m;
    return (completed, total, taskPercent);
}

