  }

  // Set default date range: today → +30 days
  const now = new Date();
  const fromDate = new Date(now);
  fromDate.setDate(fromDate.getDate() - 7); // Include recent past
  const toDate = new Date(now);
  toDate.setDate(toDate.getDate() + 60);

  classState.dateFrom = fromDate.toISOString().slice(0, 10);
  classState.dateTo = toDate.toISOString().slice(0, 10);

  const fDateFrom = document.getElementById('insDateFrom');
  const fDateTo = document.getElementById('insDateTo');
  fDateFrom.value = classState.dateFrom;
  fDateTo.value = classState.dateTo;

  // Wire up filters
  fDateFrom.addEventListener('change', () => { classState.dateFrom = fDateFrom.value; classState.page = 1; loadClasses(); });
  fDateTo.addEventListener('change', () => { classState.dateTo = fDateTo.value; classState.page = 1; loadClasses(); });
  document.getElementById('insStatusFilter').addEventListener('change', (e) => {
    classState.status = e.target.value; classState.page = 1; loadClasses();
  });
  document.getElementById('insHasAttendees').addEventListener('change', (e) => {
    classState.hasAttendees = e.target.checked; classState.page = 1;
    const icCb = document.getElementById('icHasAttendees');
    if (icCb) icCb.checked = classState.hasAttendees;
    if (_calInitialized) icRenderGrid();
    loadClasses();
  });
  document.getElementById('insOnlyUpcoming').addEventListener('change', (e) => {
    classState.onlyUpcoming = e.target.checked; classState.page = 1; loadClasses();
  });

  // Drawer events
  document.getElementById('insDrawerOverlay').addEventListener('click', insCloseDrawer);
  document.addEventListener('keydown', e => { if (e.key === 'Escape') insCloseDrawer(); });

  // SPM-103 — aggregate view context for the owner / admin.
  if (_isAllInstructors) {
    const sub = document.getElementById('insSubtitle');
    if (sub) sub.textContent = 'All instructors — whole-studio schedule and rosters';
  }

  // Show tabs & filters
  document.getElementById('insTabs').style.display = '';
  document.getElementById('insClassFilters').style.display = '';

  // Load data
  await Promise.all([loadClasses(), loadBookings()]);
}

