using SoulPilates.Core.Entities;

namespace SoulPilates.Core.Interfaces;

/// <summary>
/// Manages staff work shifts (recurring weekly + one-off) and expands them into
/// concrete dated occurrences for a calendar view.
/// </summary>
public interface IStaffShiftService
{
    /// <summary>All raw shift definitions (for editing). Optionally filtered to one staff member.</summary>
    Task<List<StaffShift>> GetShiftsAsync(string? staffId = null);

    Task<StaffShift> CreateAsync(StaffShift shift);
    Task<bool> UpdateAsync(string id, StaffShift shift);
    Task<bool> DeleteAsync(string id);

    /// <summary>Skip a single occurrence of a recurring shift (Google-Calendar "delete this event").</summary>
    Task<bool> SkipOccurrenceAsync(string id, string dateIso);

    /// <summary>
    /// Expand recurring + one-off shifts into concrete dated occurrences within
    /// [from, to] (inclusive, studio-local dates). Optionally scoped to one staff member.
    /// </summary>
    Task<List<StaffShiftOccurrence>> GetScheduleAsync(DateOnly from, DateOnly to, string? staffId = null);
}

/// <summary>One concrete dated shift, produced by expanding a StaffShift over a date range.</summary>
public class StaffShiftOccurrence
{
    public string ShiftId { get; set; } = null!;
    public string StaffId { get; set; } = null!;
    public string? StaffName { get; set; }
    public string? Label { get; set; }
    public string Color { get; set; } = "#EA6A24";

    /// <summary>ISO "yyyy-MM-dd" studio-local date of this occurrence.</summary>
    public string Date { get; set; } = "";

    public string StartTime { get; set; } = "";
    public string EndTime { get; set; } = "";
    public List<TimeWindow> Breaks { get; set; } = new();

    /// <summary>True when this occurrence comes from a recurring series (vs a one-off).</summary>
    public bool IsRecurring { get; set; }
}

