async function batchFetchAttendees() {
  const ids = getVisibleSessions().filter(s => s.status !== 'BLOCKED').map(s => s.id);
  const batchSize = 8;
  for (let i = 0; i < ids.length; i += batchSize) {
    await Promise.all(ids.slice(i, i+batchSize).map(async sid => {
      try {
        const bookings = await fetch(`${API}/api/scheduling/session/${sid}/bookings`,
          { headers: { Authorization: 'Bearer ' + token } }).then(r => r.json());
        attendeeCache.set(sid, bookings);
        patchClientNames(sid, bookings);
      } catch {}
    }));
  }
}

function patchClientNames(sid, bookings) {
  const el = document.querySelector(`.ev-clients[data-sid="${sid}"]`);
  if (!el || !bookings.length) return;
  const max = 4;
  const lines = bookings.slice(0, max).map(b => {
    const parts = (b.clientName || 'Unknown').split(' ');
    const abbr = parts.length > 1 ? `${parts[0]} ${parts[parts.length-1][0]}.` : parts[0];
    return `<div class="ev-client-line">⬤ ${esc(abbr)}</div>`;
  });
  if (bookings.length > max) lines.push(`<div class="ev-more">+${bookings.length - max} more</div>`);
  el.innerHTML = lines.join('');
}

/* ═══ Quick Actions Popover ═══ */
let popoverDate = null;
function showSlotPopover(e, date) {
  e.stopPropagation();
  hideMultiDropdown();
  popoverDate = date;
  const pop = document.getElementById('slotPopover');
  const dayStr = date.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
  const hourStr = fmtHour(date.getHours());
  document.getElementById('slotPopoverLabel').textContent = `${dayStr} · ${hourStr}`;
  const sb = document.getElementById('slotBlockBtn');
  if (sb) sb.style.display = (myRole === 'ADMIN' || myRole === 'MANAGER' || myRole === 'OWNER' || myRole === 'RECEPTIONIST' || myRole === 'HEADINSTRUCTOR') ? '' : 'none';
  let top = e.clientY + 4, left = e.clientX + 4;
