  requestAnimationFrame(() => {
    if (left + pop.offsetWidth > window.innerWidth - 12) left = window.innerWidth - pop.offsetWidth - 12;
    if (top + pop.offsetHeight > window.innerHeight - 12) top = top - pop.offsetHeight - 8;
