// Recompute the neon "needs completion" glow on cards + collapsed pills once
// attendee rosters have loaded. Safe to call repeatedly.
function refreshNeedsCompletion() {
  document.querySelectorAll('.ev-clients[data-sid]').forEach(el => {
    const card = el.closest('.ev');
    if (!card) return;
    const s = allSessions.find(x => x.id === el.getAttribute('data-sid'));
    if (!s) return;
    card.classList.toggle('needs-completion', sessionNeedsCompletion(s));
  });
  document.querySelectorAll('.ev-multi-pill[data-sids]').forEach(pill => {
    const sess = (pill.getAttribute('data-sids') || '').split(',').filter(Boolean)
      .map(id => allSessions.find(x => x.id === id)).filter(Boolean);
