    let badge = pill.querySelector('.pill-need-badge');
    if (needsCount > 0) {
      if (!badge) {
        badge = document.createElement('span');
        badge.className = 'pill-need-badge';
        pill.insertBefore(badge, pill.querySelector('.pill-arrow'));
