/* Finished class with attendees, not yet marked completed — loud neon nag so
   reception doesn't forget to check people out (credit/revenue/commission). */
.ev.needs-completion,
.ev-multi-pill.needs-completion {
  --ev-accent: #EEFF00;
  background: rgba(238,255,0,0.20) !important;
  border: 2px solid #EEFF00 !important;
  border-left: 4px solid #EEFF00 !important;
  animation: evNeedsPulse 2.4s ease-in-out infinite;
  z-index: 2;
}
@keyframes evNeedsPulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(238,255,0,0.0), 0 0 3px 0 rgba(238,255,0,0.25); }
  50%      { box-shadow: 0 0 0 3px rgba(238,255,0,0.10), 0 0 8px 1px rgba(238,255,0,0.40); }
}
.ev-multi-pill.needs-completion .pill-label { color: #7a8000; font-weight: 700; }
.pill-need-badge {
  font-size: 9px; font-weight: 800; line-height: 1;
  background: #EEFF00; color: #3a3d00;
  padding: 2px 5px; border-radius: 4px; margin-left: 4px;
}
/* Neon nag reads on the light theme too. */
:root:not([data-theme="dark"]) .ev.needs-completion { color: var(--color-text-primary); }
@media (prefers-reduced-motion: reduce) {
  .ev.needs-completion,
  .ev-multi-pill.needs-completion { animation: none; box-shadow: 0 0 0 3px rgba(238,255,0,0.6); }
}

