// Terminal per-attendee states — money/credit is settled (or intentionally not
// owed). Anything else on a finished class still needs reception to act.
const RESOLVED_ATTENDEE_STATUS = new Set(['COMPLETED','NO_SHOW','LATE_CANCEL','RESCHEDULED','CANCELLED']);
function sessionHasUnresolvedAttendees(sid) {
  const roster = attendeeCache.get(sid);
  if (!roster || !roster.length) return false; // roster not loaded yet — can't tell
  return roster.some(b => !RESOLVED_ATTENDEE_STATUS.has(String(b.status || '').toUpperCase()));
}

function sessionNeedsCompletion(s) {
  if (!s || s.status === 'BLOCKED') return false;
  if ((s.currentBookings ?? 0) <= 0) return false;
  const end = new Date(s.endTime).getTime();
  if (isNaN(end) || end >= Date.now()) return false; // not finished yet
  // Not marked completed at all → nag (original behaviour).
  if (s.status !== 'COMPLETED') return true;
  // Marked COMPLETED but an attendee was left un-checked-out (still ARRIVED/
  // BOOKED): that person's credit/revenue/commission is stranded, so keep
  // nagging until every attendee is resolved. Needs the roster (loads async).
  return sessionHasUnresolvedAttendees(s.id);
}

