/// from the old sheet (P1-S10) have a null <c>CalendarSessionId</c>, in
/// which case we fall back to the denormalised <c>ClientName</c> /
/// <c>BookedAt</c> on the attendance row. Format and instructor name
/// come from <see cref="CalendarSession"/> denormalised fields (no Staff
/// join needed for the row itself; the photo URL is only fetched if the
/// denormalised one is missing).
/// </para>
/// </summary>
public async Task<IReadOnlyList<ClientBookingHistoryRow>> GetBookingHistoryForClientAsync(
    string clientId, int limit = 50, bool includeCancelled = false)
{
    if (string.IsNullOrWhiteSpace(clientId))
        return Array.Empty<ClientBookingHistoryRow>();
    if (limit <= 0) limit = 50;
    if (limit > 200) limit = 200;

    // Newest-first lookup on the client's attendances.
    // SPM-79 — RESCHEDULED bookings are always excluded: the seat/payment was moved
    // to the new booking, so the rescheduled-away row must not appear as the client's
    // (unpaid) booking in POS, regardless of the includeCancelled toggle.
    var attendanceFilter = Builders<Attendance>.Filter.Eq(a => a.ClientId, clientId)
        & Builders<Attendance>.Filter.Ne(a => a.Status, "RESCHEDULED");
    if (!includeCancelled)
    {
        attendanceFilter &= Builders<Attendance>.Filter.Ne(a => a.Status, "CANCELLED");
    }
    var attendances = await _attendances
        .Find(attendanceFilter)
        .SortByDescending(a => a.BookedAt)
        .Limit(limit)
        .ToListAsync();

    if (attendances.Count == 0) return Array.Empty<ClientBookingHistoryRow>();

    // Batch session lookup — one round-trip for every session referenced.
    var sessionIds = attendances
        .Where(a => !string.IsNullOrWhiteSpace(a.CalendarSessionId))
        .Select(a => a.CalendarSessionId!)
        .Distinct()
        .ToList();

    var sessions = sessionIds.Count == 0
        ? new Dictionary<string, CalendarSession>()
        : (await _sessions
                .Find(Builders<CalendarSession>.Filter.In(s => s.Id, sessionIds))
                .ToListAsync())
            .ToDictionary(s => s.Id!, s => s);

    var rows = new List<ClientBookingHistoryRow>(attendances.Count);
    foreach (var att in attendances)
    {
        CalendarSession? sess = null;
        if (!string.IsNullOrWhiteSpace(att.CalendarSessionId))
        {
            sessions.TryGetValue(att.CalendarSessionId, out sess);
        }

        rows.Add(new ClientBookingHistoryRow(
            AttendanceId: att.Id ?? string.Empty,
            CalendarSessionId: att.CalendarSessionId,

