// Session history is paginated so EVERY session shows, no matter how many
// times the client came — 20 per page, "Load more" appends the next page.
const BOOKING_PAGE_SIZE = 20;
let bookingOffset = 0;
let bookingTotalShown = 0;

const statusBadge = (s) =>
  s === "ARRIVED" || s === "CHECKED_IN"
    ? "badge-success"
    : s === "NO_SHOW"
      ? "badge-danger"
      : "badge-default";

function renderBookingRows(bookings) {
  return bookings
    .map(
      (b) => `
          <tr>
            <td class="text-muted text-sm">${b.sessionStartTime ? new Date(b.sessionStartTime).toLocaleDateString("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }) : new Date(b.bookedAt).toLocaleDateString("en-US", { month: "short", day: "numeric" })}</td>
            <td>${b.className ?? "—"}</td>
            <td class="text-muted text-sm">${b.instructorName ?? "—"}</td>
            <td><span class="badge ${statusBadge(b.status)}">${b.status}</span></td>
            <td>${bookingPaymentBadge(b)}${bookingCollectBtn(b)}</td>
          </tr>`,
    )
    .join("");
}

function loadBookingPage() {
  const btn = document.getElementById("bookingLoadMoreBtn");
  const wrap = document.getElementById("bookingLoadMoreWrap");
  const countEl = document.getElementById("bookingCount");
  if (btn) { btn.disabled = true; btn.textContent = "Loading…"; }

  fetch(`${API}/api/scheduling/client/${clientId}/bookings?limit=${BOOKING_PAGE_SIZE}&offset=${bookingOffset}`, {
    headers: { Authorization: "Bearer " + token },
  })
    .then((r) => (r.ok ? r.json() : Promise.reject(r.status)))
    .then((bookings) => {
      const table = document.getElementById("bookingTable");
      if (bookingOffset === 0 && !bookings.length) {
        table.innerHTML = `<tr><td colspan="5" style="text-align:center;padding:40px;color:var(--color-text-muted);">No sessions yet</td></tr>`;
        if (wrap) wrap.style.display = "none";
        return;
      }
      // Replace the "Loading…" placeholder on the first page, then append.
      if (bookingOffset === 0) table.innerHTML = "";
      table.insertAdjacentHTML("beforeend", renderBookingRows(bookings));
      bookingOffset += bookings.length;
      bookingTotalShown += bookings.length;

      // A short page means we've reached the end of the history.
      const hasMore = bookings.length === BOOKING_PAGE_SIZE;
      if (wrap) wrap.style.display = hasMore ? "block" : (bookingTotalShown > BOOKING_PAGE_SIZE ? "block" : "none");
      if (btn) {
        btn.disabled = false;
        btn.textContent = "Load more sessions";
        btn.style.display = hasMore ? "" : "none";
      }
      if (countEl) countEl.textContent = `Showing ${bookingTotalShown} session${bookingTotalShown === 1 ? "" : "s"}${hasMore ? "" : " (all)"}`;
    })
    .catch(() => {
      if (bookingOffset === 0) {
        document.getElementById("bookingTable").innerHTML =
          `<tr><td colspan="5" style="text-align:center;padding:40px;color:var(--color-text-muted);">No session history available.</td></tr>`;
      }
      if (btn) { btn.disabled = false; btn.textContent = "Load more sessions"; }
    });
}

document.getElementById("bookingLoadMoreBtn")?.addEventListener("click", loadBookingPage);
loadBookingPage();

