/// <inheritdoc />
public async Task<List<MonthlyClassCountDto>> GetMonthlyClassCountsAsync(AnalyticsRangeQuery range)
{
    // Classes the studio ACTUALLY taught: non-freelance, COMPLETED sessions
    // that started in the window and had at least one attendee who arrived /
    // checked in. Same "actually ran" rule as GetMonthSummaryAsync, but
    // bucketed per studio-local calendar month instead of one flat total.
    var completedSessions = await _sessions
        .Find(Builders<CalendarSession>.Filter.And(
            Builders<CalendarSession>.Filter.Gte(s => s.StartTime, range.StartDate),
            Builders<CalendarSession>.Filter.Lt(s => s.StartTime, range.EndDate),
            Builders<CalendarSession>.Filter.Eq(s => s.Status, "COMPLETED"),
            Builders<CalendarSession>.Filter.Eq(s => s.IsFreelance, false)))
        .ToListAsync();

    if (completedSessions.Count == 0) return new List<MonthlyClassCountDto>();

    var completedSessionIds = completedSessions.Select(s => s.Id).ToList();
    var attendedSessionIds = (await _attendances.Distinct(
            a => a.CalendarSessionId,
            Builders<Attendance>.Filter.And(
                Builders<Attendance>.Filter.In(a => a.CalendarSessionId, completedSessionIds),
                Builders<Attendance>.Filter.In(a => a.Status, AttendedStatuses)))
        .ToListAsync())
        .ToHashSet();

    var sessions = completedSessions.Where(s => attendedSessionIds.Contains(s.Id));

    // Bucket by studio-local month so a late-evening VN class doesn't roll
    // into the next month at the UTC boundary.
    var buckets = sessions
        .GroupBy(s => new DateTime(
            StudioTime.Local(s.StartTime).Year,
            StudioTime.Local(s.StartTime).Month, 1))
        .OrderBy(g => g.Key)
        .Select(g => new MonthlyClassCountDto
        {
            Month = g.Key.ToString("yyyy-MM", CultureInfo.InvariantCulture),
            MonthLabel = g.Key.ToString("MMM yyyy", CultureInfo.InvariantCulture),
            GroupClasses = g.Count(s => s.Format == "GROUP" || s.Format == "MAT"),
            PrivateClasses = g.Count(s => s.Format == "PRIVATE" || s.Format == "DUO"),
            TotalClasses = g.Count(),
        })
        .ToList();

    return buckets;
}

