async function loadMonthSummary() {
  const sub = document.getElementById("monthSummarySubtitle");
  const hasCompare =
    state.compareYear != null && state.compareMonth != null;
  sub.textContent = hasCompare
    ? `${periodLabel()} vs ${periodLabel(state.compareYear, state.compareMonth)}`
    : periodLabel();
  try {
    // Fetch primary always; comparison only when a "Compare to" month is
    // set. Both hit the SAME month-summary endpoint, different ranges.
    const [primary, compare] = await Promise.all([
      fetchMonthSummary(state.year, state.month),
      hasCompare
        ? fetchMonthSummary(state.compareYear, state.compareMonth)
        : Promise.resolve(null),
    ]);
    MONTH_KPIS.forEach((kpi) => {
      const cur = primary[kpi.field];
      document.getElementById(`kpi-${kpi.id}`).textContent =
