async function loadTopClassTimes() {
  const { start, end } = rangeFromState();
  els.topClassTimesSubtitle.textContent = `Loading… (${periodLabel()})`;
  const formatParam = state.format
    ? `&format=${encodeURIComponent(state.format)}`
    : "";
  try {
    const res = await fetch(
      `${API}/api/analytics/top-class-times?startDate=${start}&endDate=${end}${formatParam}`,
      { headers: { Authorization: `Bearer ${token}` } },
    );
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const rows = await res.json();
    renderClassTimesChart(rows);
    renderClassTimesTable(rows);
    const fmtSuffix = state.format
      ? ` (${state.format.toLowerCase()})`
      : "";
    els.topClassTimesSubtitle.textContent = `${rows.length} hour-bucket${rows.length === 1 ? "" : "s"}${fmtSuffix} for ${periodLabel()}`;
  } catch (err) {
