    els.topClassTimesSubtitle.textContent = "Unable to load.";
    els.topClassTimesTable.innerHTML =
      '<tr><td colspan="5" class="muted">Unable to load.</td></tr>';
  }
}

// ── Customer Mix (P3-S04) ────────────────────────────────
let customerMixChart = null;

// Segment label table — keeps the chart legend / table label in one place
// so future copy tweaks don't need to be hunted in two spots.
const SEGMENT_LABELS = {
  RECURRING: "Recurring",
  ONE_TIME: "One-time",
  DORMANT: "Dormant",
};

function renderCustomerMixChart(recurring, oneTime) {
  if (typeof Chart === "undefined") return;
  const palette = readPalette();
  const ctx = document.getElementById("customerMixChart").getContext("2d");

  // Recurring uses brand-accent (warm); one-time uses muted secondary so the
  // accent slice always reads as the "loyal" segment without needing a legend.
  const recurringColor = palette.bar;
  const oneTimeColor = palette.isDark
    ? "rgba(255,255,255,0.18)"
    : "#D8D2CA";

  const data = {
    labels: [SEGMENT_LABELS.RECURRING, SEGMENT_LABELS.ONE_TIME],
    datasets: [
      {
        data: [recurring.clientCount, oneTime.clientCount],
        backgroundColor: [recurringColor, oneTimeColor],
        borderColor: palette.isDark ? "#1A1410" : "#FFFFFF",
        borderWidth: 2,
        hoverOffset: 6,
      },
    ],
  };

  if (customerMixChart) {
    customerMixChart.data = data;
    customerMixChart.update();
    return;
  }

  customerMixChart = new Chart(ctx, {
    type: "doughnut",
    data,
    options: {
      responsive: true,
      maintainAspectRatio: false,
      cutout: "62%",
      animation: { duration: 300 },
      plugins: {
        legend: {
          position: "bottom",
          labels: {
            color: palette.tick,
            font: { size: 12 },
            boxWidth: 10,
            boxHeight: 10,
            usePointStyle: true,
          },
        },
        tooltip: {
