let monthlyClassesChart = null;

async function loadMonthlyClasses() {
  // Window = 12 studio months ending at (and including) the selected month.
  const startY = state.month === 12 ? state.year : state.year - 1;
  const startM = state.month === 12 ? 1 : state.month + 1; // 11 months back
  const start = `${startY}-${String(startM).padStart(2, "0")}-01`;
  const { end } = rangeFromState(); // exclusive start of month after selected
  els.monthlyClassesSubtitle.textContent = `Loading… (12 months to ${periodLabel()})`;
  try {
    const res = await fetch(
      `${API}/api/analytics/monthly-class-counts?startDate=${start}&endDate=${end}`,
      { headers: { Authorization: `Bearer ${token}` } },
    );
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const rows = await res.json();
    renderMonthlyClassesChart(rows);
    renderMonthlyClassesTable(rows);
    const totalClasses = rows.reduce((s, r) => s + (r.totalClasses || 0), 0);
    els.monthlyClassesSubtitle.textContent = rows.length
      ? `${totalClasses} classes taught across ${rows.length} month${rows.length === 1 ? "" : "s"} (to ${periodLabel()})`
      : `No classes taught in the 12 months to ${periodLabel()}`;
  } catch (err) {
    console.error("[analytics] monthly-class-counts fetch failed", err);
    els.monthlyClassesSubtitle.textContent = "Unable to load.";
    els.monthlyClassesTable.innerHTML =
      '<tr><td colspan="4" class="muted">Unable to load.</td></tr>';
  }
}

function renderMonthlyClassesChart(rows) {
  if (typeof Chart === "undefined") return;
  const pal = readPalette();
  const labels = rows.map((r) => r.monthLabel);
  const groupData = rows.map((r) => r.groupClasses || 0);
  const privateData = rows.map((r) => r.privateClasses || 0);
  const privateColor = pal.isDark ? "rgba(255,255,255,0.22)" : "#D8D2CA";
  const data = {
    labels,
    datasets: [
      { label: "Group", data: groupData, backgroundColor: pal.bar, borderRadius: 4, stack: "classes" },
      { label: "Private", data: privateData, backgroundColor: privateColor, borderRadius: 4, stack: "classes" },
    ],
  };
  if (monthlyClassesChart) {
    monthlyClassesChart.data = data;
    monthlyClassesChart.update();
    return;
  }
  monthlyClassesChart = new Chart(
    document.getElementById("monthlyClassesChart").getContext("2d"),
    {
      type: "bar",
      data,
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: { duration: 300 },
        scales: {
          x: { stacked: true, ticks: { color: pal.tick }, grid: { display: false } },
          y: { stacked: true, beginAtZero: true, ticks: { color: pal.tick, precision: 0 }, grid: { color: pal.grid } },
        },
        plugins: {
          legend: { position: "bottom", labels: { color: pal.tick, boxWidth: 10, boxHeight: 10, usePointStyle: true } },
          tooltip: {
            backgroundColor: pal.tooltipBg,
            borderColor: pal.tooltipBorder,
            borderWidth: 1,
            titleColor: pal.tooltipText,
            bodyColor: pal.tooltipText,
            padding: 10,
          },
        },
      },
    },
  );
}

function renderMonthlyClassesTable(rows) {
  if (!rows.length) {
    els.monthlyClassesTable.innerHTML =
