// SPM-75 — "Compare to" month. Only the Month Summary KPI strip reacts;
// the rest of the dashboard (charts, tables) stays single-period. Clearing
// the picker removes the deltas and restores the original behaviour.
els.comparePicker.addEventListener("change", () => {
  if (els.comparePicker.value) {
    const [y, m] = els.comparePicker.value.split("-").map(Number);
    state.compareYear = y;
    state.compareMonth = m;
  } else {
    state.compareYear = null;
    state.compareMonth = null;
  }
  loadMonthSummary();
});

// Attendance-health segmented control — only this card refreshes; no
// need to re-fetch the rest of the dashboard when the operator pivots
// between instructor / blueprint / time-slot views.
[
  els.attRatesByInstructor,
  els.attRatesByBlueprint,
  els.attRatesByTimeSlot,
].forEach((btn) => {
  btn.addEventListener("click", () => {
    const next = btn.dataset.groupby;
    if (next === attendanceGroupBy) return;
    setAttendanceGroupBy(next);
    loadAttendanceRates();
  });
});

