7	/// <summary>
8	/// Server-authoritative catalog of dashboard widgets. Each widget declares the
9	/// roles allowed to see it, so revenue/financial widgets never reach a
10	/// receptionist or instructor even if a tampered layout requests them. The
11	/// frontend renders only what this catalog (filtered by role) returns.
12	/// </summary>
13	public static class DashboardWidgetCatalog
14	{
15	    public sealed record Widget(
16	        string Id,
17	        string Title,
18	        string Category,
19	        string Description,
20	        int DefaultW,
21	        int DefaultH,
22	        int MinW,
23	        int MinH,
24	        string[] AllowedRoles);
25	
26	    // Role groups. Financial data is limited to the money-trusted roles.
27	    private static readonly string[] Financial = { "Admin", "Owner", "Accountant", "SuperAdmin" };
28	    private static readonly string[] Operational = { "Admin", "Owner", "Accountant", "Manager", "Receptionist", "SuperAdmin" };
29	    private static readonly string[] Everyone = { "Admin", "Owner", "Accountant", "Manager", "Receptionist", "Instructor", "Freelance", "SuperAdmin" };
30	
31	    /// <summary>The full catalog. Order here is the default placement order.</summary>
32	    public static readonly IReadOnlyList<Widget> All = new List<Widget>
33	    {
34	        // ── Financial (Admin / Owner / Accountant) ──
35	        new("business-summary",   "Business Summary",     "Financial",   "Revenue, profit, clients, classes, packages, bookings & visitors — toggle Today / Week / Month.", 8, 4, 5, 3, Financial),
36	        new("revenue-kpi",        "Monthly Revenue",      "Financial",   "Revenue this month with month-over-month delta.", 4, 2, 3, 2, Financial),
37	        new("payroll-estimate",   "Payroll Estimate",     "Financial",   "Estimated payroll for the current period.",       4, 2, 3, 2, Financial),
38	        new("revenue-vs-expenses","Revenue vs Expenses",  "Financial",   "Yearly revenue against expenses.",                8, 4, 4, 3, Financial),
39	        new("revenue-breakdown",  "What's Driving Revenue","Financial",  "Revenue split by source (classes / packages / merch).", 4, 4, 3, 3, Financial),
40	        new("recent-invoices",    "Recent Invoices",      "Financial",   "The latest invoices raised.",                     6, 4, 4, 3, Financial),
41	        new("signup-source",      "Sign-up Source",       "Financial",   "How new customers heard about the studio.",       6, 3, 4, 2, Financial),
42	
43	        // ── Operational (Admin / Owner / Accountant / Manager / Receptionist) ──
44	        new("active-clients",     "Active Clients (30d)", "Operational", "Distinct clients with activity in the last 30 days.", 4, 2, 3, 2, Operational),
45	        new("classes-week",       "Classes This Week",    "Operational", "Scheduled classes for the current week.",         4, 2, 3, 2, Everyone),
46	        new("occupancy",          "Class Occupancy",      "Operational", "Average class fill rate for the period.",          4, 2, 3, 2, Operational),
47	        new("occupancy-times",    "Occupancy by Time",    "Operational", "Best-attended time slots, split by Group/Mat vs Private.", 8, 4, 4, 3, Operational),
48	        new("studio-pulse",       "Studio Pulse",         "Operational", "Today's at-a-glance activity snapshot.",           6, 4, 4, 3, Operational),
49	        new("top-clients",        "Top Clients",          "Operational", "Highest-value clients for the period.",            6, 4, 4, 3, Operational),
50	
51	        // ── Web analytics (Admin / Owner / Accountant / Manager / Receptionist) ──
52	        new("live-visitors",      "Live Visitors",        "Web",         "Visitors active on the site right now.",           3, 2, 3, 2, Operational),
53	        new("booking-funnel",     "Booking Funnel",       "Web",         "Where visitors drop off on the way to a booking.", 8, 4, 4, 3, Operational),
