56	    /// <summary>Widgets a given role is allowed to see.</summary>
57	    public static IEnumerable<Widget> ForRole(string? role)
58	    {
59	        var r = (role ?? "").Trim();
60	        return All.Where(w => w.AllowedRoles.Contains(r, StringComparer.OrdinalIgnoreCase));
61	    }
62	
63	    public static bool IsAllowed(string widgetId, string? role)
64	    {
65	        var r = (role ?? "").Trim();
66	        return All.Any(w => w.Id == widgetId && w.AllowedRoles.Contains(r, StringComparer.OrdinalIgnoreCase));
67	    }
