const token = localStorage.getItem('token');
const API = import.meta.env.PUBLIC_API_URL;
const authH = { Authorization: `Bearer ${token}` };

// ── formatters ──
const fmtVnd = (n) => `${Math.round(Number(n) || 0).toLocaleString('en-US')} VND`;
const fmtInt = (n) => `${Math.round(Number(n) || 0).toLocaleString('en-US')}`;
const fmtPct = (n) => `${Math.round((Number(n) || 0) * 100)}%`;
// Occupancy comes back already expressed as a percentage (e.g. 56.0), so it
// must NOT be multiplied by 100 again. Clamp to 100% as a defensive cap.
const fmtPctRaw = (n) => `${Math.min(100, Math.round((Number(n) || 0) * 10) / 10)}%`;
const esc = (v) => String(v ?? '').replace(/[<>&"']/g, c => ({ '<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&#39;' }[c]));
const css = (n) => getComputedStyle(document.documentElement).getPropertyValue(n).trim();
function monthRange() {
  const now = new Date();
  const start = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;
  const nx = new Date(now.getFullYear(), now.getMonth()+1, 1);
  const end = `${nx.getFullYear()}-${String(nx.getMonth()+1).padStart(2,'0')}-01`;
  return { start, end };
}
const _dayStr = (d) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function todayRange() {
  const now = new Date();
  const t = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const nx = new Date(t); nx.setDate(nx.getDate()+1);
  return { start: _dayStr(t), end: _dayStr(nx) };
}
function weekRange() {
  const now = new Date();
  const t = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const dow = (t.getDay() + 6) % 7; // Monday = 0
  const mon = new Date(t); mon.setDate(mon.getDate() - dow);
  const nextMon = new Date(mon); nextMon.setDate(nextMon.getDate() + 7);
  return { start: _dayStr(mon), end: _dayStr(nextMon) };
}
const periodRange = (p) => p === 'today' ? todayRange() : p === 'week' ? weekRange() : monthRange();

// ── shared fetches (cached so multiple widgets reuse one request) ──
let _kpis, _summary;
const getKpis = () => (_kpis ||= fetch(`${API}/api/analytics/dashboard-kpis`, { headers: authH }).then(r => r.ok ? r.json() : null).catch(() => null));
const getSummary = () => {
  const { start, end } = monthRange();
  return (_summary ||= fetch(`${API}/api/analytics/month-summary?startDate=${start}&endDate=${end}`, { headers: authH }).then(r => r.ok ? r.json() : null).catch(() => null));
};

// ── widget registry: id → { render(el), load(el) } ──
const WIDGETS = {
  'business-summary': {
    render: () => `
      <div class="wg-eyebrow">Overview</div>
      <div class="wg-title wg-title-row">
        <span>Business Summary</span>
