          <button type="button" data-p="today" class="active">Today</button>
          <button type="button" data-p="week">This Week</button>
          <button type="button" data-p="month">This Month</button>
        </span>
      </div>
      <div class="wg-subrow">
        <span class="wg-sub" data-f="label">Loading…</span>
        <span class="wg-seg wg-seg-sm" data-f="view">
          <button type="button" data-v="numbers" class="active">Numbers</button>
          <button type="button" data-v="chart">Chart</button>
        </span>
      </div>
      <div class="wg-body">
        <div class="wg-pulse-grid wg-metric-grid" data-f="numbers"></div>
        <div class="wg-canvas-wrap" data-f="chartwrap" style="display:none;"><canvas data-f="c"></canvas></div>
      </div>`,
    load: async (el) => {
      let period = 'today', view = 'numbers', data = null;
      const METRICS = [
        ['Revenue', d => fmtVnd(d.revenueVnd ?? 0), d => d.revenueVnd ?? 0, true],
        ['Profit', d => fmtVnd(d.profitVnd ?? 0), d => d.profitVnd ?? 0, true],
        ['New Clients', d => fmtInt(d.newClients ?? 0), d => d.newClients ?? 0, false],

