419	    async function boot() {
420	      let data;
421	      try {
422	        const r = await fetch(`${API}/api/me/dashboard`, { headers: authH });
423	        if (!r.ok) throw new Error(`HTTP ${r.status}`);
424	        data = await r.json();
425	      } catch (e) {
426	        document.getElementById('dashEmpty').textContent = 'Failed to load your dashboard. Please refresh.';
427	        document.getElementById('dashEmpty').style.display = 'block';
428	        return;
429	      }
430	      catalog = data.catalog || [];
431	      placements = data.widgets || [];
432	
433	      grid = GridStack.init({ column: 12, cellHeight: 90, margin: 8, float: false, disableDrag: true, disableResize: true, animate: true }, gridEl);
434	
435	      placements.forEach(addWidgetToGrid);
436	      refreshEmptyState();
437	      buildCustomizeList();
438	      wireRemove();
439	    }
440	
441	    // ── remove (edit mode) ──
442	    function wireRemove() {
443	      gridEl.addEventListener('click', (e) => {
444	        const btn = e.target.closest('[data-remove]');
445	        if (!btn || !document.body.classList.contains('dash-edit')) return;
446	        const item = btn.closest('.grid-stack-item');
447	        const id = btn.getAttribute('data-remove');
448	        grid.removeWidget(item);
449	        const cb = document.querySelector(`.dash-wg-toggle input[data-id="${id}"]`);
450	        if (cb) cb.checked = false;
451	        refreshEmptyState();
452	      });
453	    }
454	
455	    // ── customize popup ──
456	    function buildCustomizeList() {
457	      const list = document.getElementById('customizeList');
458	      const cats = [...new Set(catalog.map(c => c.category))];
459	      list.innerHTML = cats.map(cat => {
460	        const items = catalog.filter(c => c.category === cat);
461	        return `<div class="dash-cat">${esc(cat)}</div>` + items.map(c => {
462	          const on = placements.some(p => p.widgetId === c.id);
463	          return `<div class="dash-wg-toggle"><div class="info"><div class="nm">${esc(c.title)}</div><div class="ds">${esc(c.description)}</div></div>
464	            <label class="dash-switch"><input type="checkbox" data-id="${c.id}" ${on ? 'checked' : ''}/><span class="track"></span></label></div>`;
465	        }).join('');
466	      }).join('');
467	
468	      list.querySelectorAll('input[data-id]').forEach(cb => {
469	        cb.addEventListener('change', () => {
470	          const id = cb.getAttribute('data-id');
471	          const existing = gridEl.querySelector(`[gs-widget-id="${id}"]`);
472	          if (cb.checked && !existing) {
473	            const meta = catalog.find(c => c.id === id) || {};
474	            addWidgetToGrid({ widgetId: id, x: 0, y: 1000, w: meta.defaultW, h: meta.defaultH });
475	          } else if (!cb.checked && existing) {
476	            grid.removeWidget(existing);
477	          }
478	          refreshEmptyState();
479	          persist();
480	        });
481	      });
482	    }
483	
484	    // ── persist ──
485	    function collectLayout() {
486	      return grid.engine.nodes.map(n => ({
487	        widgetId: n.el.getAttribute('gs-widget-id'),
488	        x: n.x, y: n.y, w: n.w, h: n.h,
489	      })).filter(p => p.widgetId);
490	    }
491	    async function persist() {
492	      const widgets = collectLayout();
493	      placements = widgets;
494	      try {
495	        await fetch(`${API}/api/me/dashboard`, {
496	          method: 'PUT', headers: { ...authH, 'Content-Type': 'application/json' },
497	          body: JSON.stringify({ widgets }),
498	        });
499	      } catch (e) { console.warn('save failed', e); }
500	    }
501	
502	    // ── edit mode ──
503	    let editing = false;
504	    function setEdit(on) {
505	      editing = on;
506	      document.body.classList.toggle('dash-edit', on);
507	      grid.enableMove(on); grid.enableResize(on);
508	      document.getElementById('btnEdit').style.display = on ? 'none' : '';
509	      document.getElementById('btnSave').style.display = on ? '' : 'none';
510	    }
511	
512	    // ── wire toolbar ──
