}

async function boot() {
  let data;
  try {
    const r = await fetch(`${API}/api/me/dashboard`, { headers: authH });
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    data = await r.json();
  } catch (e) {
    document.getElementById('dashEmpty').textContent = 'Failed to load your dashboard. Please refresh.';
    document.getElementById('dashEmpty').style.display = 'block';
    return;
  }
  catalog = data.catalog || [];
  placements = data.widgets || [];

  grid = GridStack.init({ column: 12, cellHeight: 90, margin: 8, float: false, disableDrag: true, disableResize: true, animate: true }, gridEl);

  placements.forEach(addWidgetToGrid);
  refreshEmptyState();
  buildCustomizeList();
  wireRemove();
}

// ── remove (edit mode) ──
function wireRemove() {
  gridEl.addEventListener('click', (e) => {
    const btn = e.target.closest('[data-remove]');
    if (!btn || !document.body.classList.contains('dash-edit')) return;
    const item = btn.closest('.grid-stack-item');
    const id = btn.getAttribute('data-remove');
    grid.removeWidget(item);
    const cb = document.querySelector(`.dash-wg-toggle input[data-id="${id}"]`);
    if (cb) cb.checked = false;
    refreshEmptyState();
  });
}

// ── customize popup ──
function buildCustomizeList() {
  const list = document.getElementById('customizeList');
  const cats = [...new Set(catalog.map(c => c.category))];
  list.innerHTML = cats.map(cat => {
    const items = catalog.filter(c => c.category === cat);
    return `<div class="dash-cat">${esc(cat)}</div>` + items.map(c => {
      const on = placements.some(p => p.widgetId === c.id);
      return `<div class="dash-wg-toggle"><div class="info"><div class="nm">${esc(c.title)}</div><div class="ds">${esc(c.description)}</div></div>
        <label class="dash-switch"><input type="checkbox" data-id="${c.id}" ${on ? 'checked' : ''}/><span class="track"></span></label></div>`;
    }).join('');
  }).join('');

  list.querySelectorAll('input[data-id]').forEach(cb => {
    cb.addEventListener('change', () => {
      const id = cb.getAttribute('data-id');
      const existing = gridEl.querySelector(`[gs-widget-id="${id}"]`);
      if (cb.checked && !existing) {
        const meta = catalog.find(c => c.id === id) || {};
        addWidgetToGrid({ widgetId: id, x: 0, y: 1000, w: meta.defaultW, h: meta.defaultH });
      } else if (!cb.checked && existing) {
        grid.removeWidget(existing);
      }
      refreshEmptyState();
      persist();
    });
  });
}

// ── persist ──
function collectLayout() {
  return grid.engine.nodes.map(n => ({
    widgetId: n.el.getAttribute('gs-widget-id'),
    x: n.x, y: n.y, w: n.w, h: n.h,
  })).filter(p => p.widgetId);
}
async function persist() {
  const widgets = collectLayout();
  placements = widgets;
  try {
    await fetch(`${API}/api/me/dashboard`, {
      method: 'PUT', headers: { ...authH, 'Content-Type': 'application/json' },
      body: JSON.stringify({ widgets }),
    });
  } catch (e) { console.warn('save failed', e); }
}

// ── edit mode ──
let editing = false;
function setEdit(on) {
  editing = on;
  document.body.classList.toggle('dash-edit', on);
  grid.enableMove(on); grid.enableResize(on);
  document.getElementById('btnEdit').style.display = on ? 'none' : '';
  document.getElementById('btnSave').style.display = on ? '' : 'none';
}

// ── wire toolbar ──
document.getElementById('btnCustomize').addEventListener('click', () => document.getElementById('customizeModal').classList.add('open'));
document.getElementById('btnCloseCustomize').addEventListener('click', () => document.getElementById('customizeModal').classList.remove('open'));
document.getElementById('btnCloseCustomize2').addEventListener('click', () => document.getElementById('customizeModal').classList.remove('open'));
document.getElementById('customizeModal').addEventListener('click', (e) => { if (e.target.id === 'customizeModal') e.currentTarget.classList.remove('open'); });

