// Re-flows every widget the role may see onto the 12-col grid in the catalog's
// (priority-lane) order — the same algorithm the server uses for a brand-new
// dashboard. Lets anyone adopt the restructured layout in one click.
function defaultLayoutFromCatalog() {
  const out = []; let x = 0, y = 0, rowH = 0;
  catalog.forEach(c => {
    const w = c.defaultW || 4, h = c.defaultH || 2;
    if (x + w > 12) { x = 0; y += rowH; rowH = 0; }
    out.push({ widgetId: c.id, x, y, w, h });
    x += w; rowH = Math.max(rowH, h);
