public async Task<Expense> MarkExpensePaidAsync(string expenseId)
{
    // Look up the existing row up-front so we can: (a) 404 properly when
    // the id is bogus, (b) emit a before/after audit pair, and (c) keep
    // the operation idempotent — if it's already paid we skip the write
    // entirely (no audit churn, no jittery UpdatedAt bumps).
    var existing = await _expenses.Find(e => e.Id == expenseId).FirstOrDefaultAsync()
        ?? throw new InvalidOperationException($"Expense {expenseId} not found.");

    // Flipping an expense to PAID changes downstream cash-flow analytics for
    // the month the expense lives in — reject if that month is locked.
    await AssertMonthNotLockedAsync(existing.DateIncurred.Year, existing.DateIncurred.Month);

    if (existing.PaidStatus == "PAID" && existing.OutstandingAmount == 0m)
        return existing;

    var before = new { existing.PaidStatus, existing.OutstandingAmount };

    await _expenses.UpdateOneAsync(
        e => e.Id == expenseId,
        Builders<Expense>.Update
            .Set(e => e.PaidStatus, "PAID")
            .Set(e => e.OutstandingAmount, 0m)
            .Set(e => e.UpdatedAt, DateTime.UtcNow));

    existing.PaidStatus = "PAID";
    existing.OutstandingAmount = 0m;
    existing.UpdatedAt = DateTime.UtcNow;

    await _audit.LogAsync(
        action: "UPDATE",
        entityType: "Expense",
        entityId: expenseId,
        entityLabel: existing.Category,
        before: before,
        after: new { existing.PaidStatus, existing.OutstandingAmount });

    return existing;
}

public async Task<CapitalInvestment> LogCapitalInvestmentAsync(CapitalInvestment investment)
{
    // Capital affects the washout via depreciation; refuse to log against a
    // closed month so historical washouts stay frozen.
    await AssertMonthNotLockedAsync(investment.PurchaseDate.Year, investment.PurchaseDate.Month);

    await _capital.InsertOneAsync(investment);
    await _audit.LogAsync(
        action: "CREATE",
        entityType: "CapitalInvestment",
        entityId: investment.Id!,
        entityLabel: investment.AssetName,
        after: new
        {
            investment.AssetName,
            investment.PurchaseAmount,
            investment.PurchaseDate,
            investment.DepreciationMonths,
            investment.MonthlyDepreciationAmount,
            investment.IsPreOpening,
        });
    return investment;
}

public async Task<IReadOnlyList<OwnerDistribution>> ListOwnerDistributionsAsync(int month, int year)
{
    return await _distributions
        .Find(d => d.Year == year && d.Month == month)
        .ToListAsync();
}

