    if (newDate.Year != existing.DateIncurred.Year || newDate.Month != existing.DateIncurred.Month)
        await AssertMonthNotLockedAsync(newDate.Year, newDate.Month);

    var before = new
    {
        existing.Category, existing.Amount, existing.DateIncurred,
        existing.Description, existing.PaidStatus, existing.FundSource,
    };

    var paidStatus = string.IsNullOrWhiteSpace(updated.PaidStatus) ? existing.PaidStatus : updated.PaidStatus;
    var outstanding = paidStatus == "PAID" ? 0m : updated.OutstandingAmount;

    await _expenses.UpdateOneAsync(
        e => e.Id == expenseId,
        Builders<Expense>.Update
            .Set(e => e.Category, updated.Category)
            .Set(e => e.Description, updated.Description)
            .Set(e => e.Amount, updated.Amount)
            .Set(e => e.DateIncurred, newDate)
            .Set(e => e.Type, updated.Type)
            .Set(e => e.PaidBy, updated.PaidBy)
            .Set(e => e.StaffName, updated.StaffName)
            .Set(e => e.Frequency, updated.Frequency)
            .Set(e => e.PaidStatus, paidStatus)
            .Set(e => e.OutstandingAmount, outstanding)
            .Set(e => e.PaymentMethod, updated.PaymentMethod)
            .Set(e => e.VendorName, updated.VendorName)
            .Set(e => e.FundSource, updated.FundSource)
            .Set(e => e.UpdatedAt, DateTime.UtcNow));

    var after = await _expenses.Find(e => e.Id == expenseId).FirstOrDefaultAsync();
    await _audit.LogAsync(
        action: "UPDATE",
        entityType: "Expense",
        entityId: expenseId,
        entityLabel: updated.Category,
        before: before,
        after: new
        {
            after!.Category, after.Amount, after.DateIncurred,
            after.Description, after.PaidStatus, after.FundSource,
        });

    return after!;
}

