using SoulPilates.Core.DTOs;
using SoulPilates.Core.Entities;

namespace SoulPilates.Core.Interfaces;

public interface IAccountingService
{
    Task<Expense> LogExpenseAsync(Expense expense);
    Task<IEnumerable<Expense>> GetExpensesAsync(int month, int year);
    Task<IReadOnlyList<MonthlySalaryRow>> GetMonthlySalariesAsync(int year, int month);
    Task SetMonthlySalaryAsync(string staffId, int year, int month, decimal amount);

    /// <summary>
    /// Flips an expense's <c>PaidStatus</c> to <c>"PAID"</c> and zeroes
    /// <c>OutstandingAmount</c>. Idempotent — calling on an already-paid row
    /// returns the existing entity untouched. Independent of the reimbursement
    /// workflow: this answers "did the vendor get their money?", while
    /// <see cref="SettleReimbursementsAsync"/> answers "did we pay the staff
    /// back?". Throws <see cref="InvalidOperationException"/> when the id is
    /// unknown so the controller can return 404.
    /// </summary>
    Task<Expense> MarkExpensePaidAsync(string expenseId);

    Task<CapitalInvestment> LogCapitalInvestmentAsync(CapitalInvestment investment);

    /// <summary>
    /// Computes (or re-computes) the month's <see cref="MonthlyWashout"/> AND emits one
    /// <see cref="OwnerDistribution"/> row per active owner with their share of the
    /// Owners pool. Idempotent: re-running on the same (month, year) upserts both the
    /// washout and every distribution. Locked months refuse to recompute.
    /// </summary>
    Task<MonthlyWashout> ComputeMonthlyWashoutAsync(int month, int year);

    /// <summary>
    /// Returns all <see cref="OwnerDistribution"/> rows for the given month, ordered by
    /// owner name (joined client-side). The Washout view (P2-S07) displays this.
    /// </summary>
    Task<IReadOnlyList<OwnerDistribution>> ListOwnerDistributionsAsync(int month, int year);

    // ----- P2-S05: Reimbursement workflow ----------------------------------

    /// <summary>
    /// Lists the unsettled <c>PaidBy="STAFF"</c> expenses owed to <paramref name="staffName"/>
    /// (case-insensitive). The <c>/admin/expenses</c> Settle modal calls this.
    /// </summary>
    Task<IReadOnlyList<Expense>> GetOutstandingReimbursementsAsync(string staffName);

    /// <summary>
    /// Marks the given expenses as settled into the (year, month) washout for
    /// <paramref name="staffName"/>. Returns the audit-trail batch row. Idempotent:
    /// already-settled ids are silently skipped (no double-credit), and a recompute
    /// of the washout will pick up the new totals.
    /// </summary>
    Task<ReimbursementSettleBatch> SettleReimbursementsAsync(
        string staffName,
        IEnumerable<string> expenseIds,
        int year,
        int month,
        string settledByUserId);

    /// <summary>
    /// Aggregates outstanding reimbursements grouped by <c>StaffName</c> for the
    /// expenses page summary card. Empty list when nothing is outstanding.
    /// </summary>
    Task<IReadOnlyList<OutstandingReimbursementGroup>> GetOutstandingReimbursementsSummaryAsync();

    /// <summary>Lists <see cref="StaffPayable"/> rows for the given month — the non-owner half of the Washout view.</summary>
    Task<IReadOnlyList<StaffPayable>> ListStaffPayablesAsync(int month, int year);

    // ----- P2-S06: Bonus / ad-hoc payout ------------------------------------

    /// <summary>Records a one-off ad-hoc payout. Validates amount &gt; 0 and month range.</summary>
    Task<Bonus> RecordBonusAsync(Bonus bonus);

    /// <summary>Lists all bonuses for the (year, month), most-recently authorised first.</summary>
    Task<IReadOnlyList<Bonus>> ListBonusesByMonthAsync(int month, int year);

    /// <summary>Atomically marks a bonus as PAID, sets <c>PaidAt = UtcNow</c>.</summary>
    Task<Bonus> MarkBonusPaidAsync(string bonusId);

    /// <summary>Deletes a bonus. Used for typo correction; the next washout recompute clears the credit.</summary>
    Task DeleteBonusAsync(string bonusId);

    // ----- P2-S07: Total Payable per Payee view ----------------------------

    /// <summary>
    /// Sets the lock state on the (year, month) washout. When locked, recompute
    /// is refused so the audit trail can't be rewritten after distributions are paid.
    /// Returns null when the washout doesn't exist (controller maps to 404).
    /// </summary>
    Task<MonthlyWashout?> SetWashoutLockAsync(int month, int year, bool locked);

    /// <summary>Marks an <see cref="OwnerDistribution"/> as paid. Idempotent across washout recomputes (status is carried forward).</summary>
    Task<OwnerDistribution> MarkOwnerDistributionPaidAsync(string distributionId);

    /// <summary>Marks a <see cref="StaffPayable"/> as paid. Idempotent across washout recomputes.</summary>
    Task<StaffPayable> MarkStaffPayablePaidAsync(string payableId);

    /// <summary>
    /// Single-call roll-up for the Washout view: the washout itself plus all
    /// distributions, staff payables and outstanding loans. Returns an empty
    /// summary (washout=null) when nothing has been computed yet.
    /// </summary>
    Task<WashoutSummary> GetWashoutSummaryAsync(int month, int year);

    // ----- P2-S10: Referee commission engine ---------------------------------

    /// <summary>Lists per-partner monthly payable rows for the Washout "Partner payouts" section.</summary>
    Task<IReadOnlyList<PartnerPayable>> ListPartnerPayablesAsync(int month, int year);

    /// <summary>Marks a <see cref="PartnerPayable"/> as paid. Idempotent across washout recomputes.</summary>
    Task<PartnerPayable> MarkPartnerPayablePaidAsync(string payableId);

    /// <summary>Lists the source <see cref="RefereePayout"/> rows for a partner in a given month (drill-down view).</summary>
    Task<IReadOnlyList<RefereePayout>> ListRefereePayoutsAsync(string partnerId, int month, int year);

    // ----- P2-S11: Multi-month P&L grid -------------------------------------

    /// <summary>
    /// Returns a 12-column (or <paramref name="months"/>-column) P&amp;L matrix
    /// ending at (<paramref name="endYear"/>, <paramref name="endMonth"/>) inclusive.
    /// Reads the already-computed <see cref="MonthlyWashout"/> rows; any month
    /// with no washout document yields a zero-filled column rather than an error
    /// (the studio routinely reviews historical years before data existed).
    ///
    /// <para>
    /// Per-row composition: Revenue (gross + per-category + per-method splits),
    /// COGS (sum of <c>Expense.Type=="COGS"</c> rows in the month), OpEx (Fixed),
    /// Capital Depreciation, Payroll, Referral Commissions, Net Before Allocations,
    /// Marketing/Savings/Owners allocations, and one row per active owner with
    /// their distribution allocation.
    /// </para>
    /// </summary>
    Task<PnlGridDto> GetPnlGridAsync(int endYear, int endMonth, int months);

    // ----- P2-S12: Live Investment Payback widget ---------------------------

    /// <summary>
    /// Computes the dashboard's Investment Payback summary: pre-opening initial
    /// investment, post-opening CapEx (informational), cumulative net profit
    /// across all historical washouts, and the derived "remaining to recover"
    /// + payback percentage. Read by <c>admin/index.astro</c> on mount.
    ///
    /// <para>
    /// Idempotent and side-effect-free — re-deriving from <see cref="CapitalInvestment"/>
    /// + <see cref="MonthlyWashout"/> on every call. Returns zero values for an
    /// empty DB rather than throwing.
    /// </para>
    /// </summary>
    Task<PaybackSummaryDto> GetPaybackSummaryAsync();
}

/// <summary>Roll-up DTO returned by <see cref="IAccountingService.GetWashoutSummaryAsync"/>.</summary>
public class WashoutSummary
{
    public MonthlyWashout? Washout { get; set; }
    public IReadOnlyList<OwnerDistribution> Distributions { get; set; } = Array.Empty<OwnerDistribution>();
    public IReadOnlyList<StaffPayable> StaffPayables { get; set; } = Array.Empty<StaffPayable>();
    public IReadOnlyList<PartnerPayable> PartnerPayables { get; set; } = Array.Empty<PartnerPayable>();
    public IReadOnlyList<OwnerLoan> OutstandingLoans { get; set; } = Array.Empty<OwnerLoan>();
}

/// <summary>Aggregated tile in the Outstanding Reimbursements summary card.</summary>
public class OutstandingReimbursementGroup
{
    public string StaffName { get; set; } = null!;
    public decimal TotalAmount { get; set; }
    public int ExpenseCount { get; set; }
}

