function renderExpenseTable() {
  const filter = document.getElementById("paidFilter").value;
  const tbody = document.getElementById("expenseTable");
  const tfoot = document.getElementById("expenseFoot");
  const totalEl = document.getElementById("outstandingTotal");

  const filtered = allExpenses
    .filter(e => filter === "ALL" ? true : (e.paidStatus ?? "PAID") === filter)
    .sort((a, b) => new Date(b.dateIncurred) - new Date(a.dateIncurred));

  if (!filtered.length) {
    tbody.innerHTML = `<tr><td colspan="8" style="text-align:center;padding:40px;color:var(--color-text-muted);">No expenses for this month</td></tr>`;
    tfoot.style.display = "none";
    return;
  }

  tbody.innerHTML = filtered.map(e => {
    const paidStatus = e.paidStatus ?? "PAID";
    const paidBadge = paidStatus === "PAID"
      ? `<span class="badge badge-success" style="font-size:10px;">Paid</span>`
      : `<span class="badge badge-warning" style="font-size:10px;">Not paid</span>`;
    const outstanding = Number(e.outstandingAmount ?? 0);
    const outstandingHint = outstanding > 0
      ? `<div style="font-size:10px;color:var(--color-warning);margin-top:2px;">${outstanding.toLocaleString()} ₫ outstanding</div>`
      : "";

    const paidCell = paidStatus === "PAID"
      ? `${paidBadge}${e.reimbursementSettled ? `<div style="font-size:10px;color:var(--color-success);margin-top:2px;">Reimbursed in ${e.settledForYear}-${String(e.settledForMonth).padStart(2,"0")}</div>` : ""}`
      : `${paidBadge}${outstandingHint}<button class="btn btn-secondary btn-sm" style="margin-top:6px;font-size:10px;padding:3px 8px;" data-mark-paid="${e.id}" title="Mark this expense as paid to the vendor">Mark paid</button>`;

    const fs = e.fundSource || "OPERATIONS";
    const fundBadge = fs === "MARKETING"
      ? `<span class="badge" style="font-size:10px;background:rgba(124,58,237,.12);color:var(--color-brand-accent);border:1px solid rgba(124,58,237,.25);">📢 MKT</span>`
      : fs === "SAVINGS"
        ? `<span class="badge" style="font-size:10px;background:rgba(16,185,129,.12);color:var(--color-success);border:1px solid rgba(16,185,129,.25);">🏦 SAV</span>`
        : `<span class="badge badge-default" style="font-size:10px;">OPS</span>`;

    return `
      <tr>
        <td class="text-muted text-sm">${new Date(e.dateIncurred).toLocaleDateString("en-US", { month: "short", day: "numeric" })}</td>
        <td><span class="badge ${e.expenseType === "CAPEX" ? "badge-warning" : e.expenseType === "COGS" ? "badge-danger" : "badge-default"}" style="font-size:10px;">${e.expenseType ?? "OPEX"}</span></td>
        <td><span class="badge badge-default">${escapeHtml(e.category ?? "")}</span></td>
        <td>
          ${escapeHtml(e.description ?? "")}
          ${e.vendorName ? `<div style="font-size:10px;color:var(--color-text-muted);margin-top:2px;">${escapeHtml(e.vendorName)}</div>` : ""}
        </td>
        <td class="hidden-mobile">${fundBadge}</td>
        <td style="font-size:12px;">${e.paidBy === "STAFF" ? `⚠ ${escapeHtml(e.staffName ?? "Staff")} (reimburse)` : "Company"}</td>
        <td>${paidCell}</td>
        <td class="font-semibold" style="color:var(--color-danger);">−${e.amount?.toLocaleString()} ₫</td>
      </tr>`;
  }).join("");

  tbody.querySelectorAll("[data-mark-paid]").forEach(b =>
    b.addEventListener("click", () => markExpensePaid(b.getAttribute("data-mark-paid"))));

  const totalOutstanding = filtered.reduce((sum, e) => sum + Number(e.outstandingAmount ?? 0), 0);
  totalEl.textContent = `${totalOutstanding.toLocaleString()} ₫`;
  tfoot.style.display = totalOutstanding > 0 ? "" : "none";
}

