var w = db.MonthlyWashouts.findOne({Year:2026, Month:7});
if(!w){print(\"NO JULY WASHOUT DOC\");} else {
  function n(x){return x&&x.\$numberDecimal?Number(x.\$numberDecimal):Number(x||0);}
  var rev=n(w.TotalSalesRevenue), pay=n(w.TotalPayroll), sal=n(w.TotalSalaries), fix=n(w.TotalFixedExpenses), dep=n(w.TotalCapitalDepreciation), net=n(w.TotalNetBeforeAllocations);
  print(\"Revenue: \"+rev); print(\"Payroll: \"+pay); print(\"Salaries: \"+sal); print(\"Fixed: \"+fix); print(\"Depreciation: \"+dep); print(\"Net(stored): \"+net);
  var calcNet = rev-pay-sal-fix-dep;
  print(\"Net(recomputed rev-pay-sal-fix-dep): \"+calcNet+\"  => \"+(calcNet===net?\"MATCH\":\"MISMATCH diff=\"+(net-calcNet)));
  var mkt=n(w.MarketingAllocation), sav=n(w.SavingsAllocation), own=n(w.OwnersPool);
  var mp=n(w.MarketingPercentageApplied), sp=n(w.SavingsPercentageApplied), op=n(w.OwnersPercentageApplied);
  print(\"Alloc% mkt/sav/own: \"+mp+\"/\"+sp+\"/\"+op+\" sum=\"+(mp+sp+op));
  print(\"Alloc mkt: \"+mkt+\" (exp \"+Math.round(net*mp/100)+\")\");
  print(\"Alloc sav: \"+sav+\" (exp \"+Math.round(net*sp/100)+\")\");
  print(\"Alloc own: \"+own+\" (exp \"+Math.round(net*op/100)+\")\");
  print(\"Alloc sum: \"+(mkt+sav+own)+\" vs net \"+net);
  print(\"UpdatedAt: \"+w.UpdatedAt+\" Locked: \"+w.Locked);
}
"'

